editor(node) = begin
  while !(node isa Editor)
    node = node.parent
  end
  node
end

"A node that belongs to `e` and is kept for as long as `e` is"
own!(e, node) = (node.parent === nothing && setfield!(node, :parent, e); node)
node!(make, e, key) = get!(() -> own!(e, make()), e.nodes, key)

"""
A part of the page joins the children of the document, so one part can find
another by a walk of the tree: up to the document, then through its children.
`layout!` empties that list and gives the document each part of the page that
shows, so the children are the parts of this page, in the order of their lines.
The paragraphs, the headings and the other blocks that are made for the lines
on screen follow them.
"""
own!(d::Document, node) = begin
  parent = getfield(node, :parent)
  (parent === nothing || (parent === d && !listed(d, node))) && add_child!(d, node)
  node
end

"True if `node` is in the list of the children of `d`"
listed(d::Document, node) = getfield(node, :prevsibling) !== nothing || getfield(d, :firstchild) === node

"""
Take every child out of the document's list. Each one keeps the document as
its parent, so a node that an earlier frame made can still reach the editor.
"""
unlist!(d::Document) = begin
  child = getfield(d, :firstchild)
  while child !== nothing
    next = getfield(child, :nextsibling)
    setfield!(child, :prevsibling, nothing)
    setfield!(child, :nextsibling, nothing)
    child = next
  end
  setfield!(d, :firstchild, nothing)
  d
end

const MARKDOWN = (".md", ".markdown", ".mdx")
ismarkdown(path) = lowercase(splitext(path)[2]) in MARKDOWN

# The files of code that the page changes, as it changes a Markdown file. The whole file is one block of code.
const CODE_FILES = (".jl",)

"""
True when the file at `path` is code that the page can change: a kind of file
in `CODE_FILES`, whose text shows whole. A file that's too long to show whole,
or that isn't text, is only shown.
"""
iscode(path) = begin
  (lowercase(splitext(path)[2]) in CODE_FILES && isfile(path)) || return false
  filesize(path) == 0 && return true
  found = try reading(path, tidy=false) catch; nothing end
  found !== nothing && !found[2]
end

"Open the editor on a file, or on the first Markdown file in a folder"
build_editor(path) = begin
  path = abspath(expanduser(path))
  e = Editor()
  load_sheet_font()
  e.nodes[:input] = own!(e, TextInput(placeholder="Find a file", font_family=SANS, font_size=15px,
                                      look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text)))
  if isdir(path)
    e.folder = path
    e.panel = true
    list_files!(e)
    isempty(e.files) || open!(e, e.files[1])
  else
    open!(e, path)
  end
  e
end

list_files!(e) = begin
  names = isdir(e.folder) ? readdir(e.folder) : String[]
  # A name that starts with a dot is hidden, as it is in the Finder. .DS_Store is the Finder's own file, and never shows.
  shows(n) = e.hidden ? n != ".DS_Store" : !ishidden(n)
  paths = [joinpath(e.folder, n) for n in sort!(names, by=lowercase) if shows(n)]
  # The sidebar lists the folders, then each file. The file finder lists the Markdown files.
  files = filter(isfile, paths)
  e.listed = [filter(isdir, paths); files]
  e.files = filter(ismarkdown, files)
end

"""
Show the file at `path`. A file that's already open keeps its changes. The
file that leaves goes on the list that `go_back!` reads, unless `record` is false.
"""
open!(e, path; record=true) = begin
  # A sound that the last page was playing stops. A new window has no last page, and another window's sound plays on.
  isempty(e.buffers) || silence!()
  write_blocks!(e)   # the page that leaves keeps what its blocks hold
  e.buf.offset = e.scroll.offset
  from = e.buf.path
  from == path || forget_ticked!(e)   # an item that was ticked in a list of what's found leaves that list
  # A new file ends the list of files to go forward to, as a new address does in a web browser
  record && !isempty(from) && from != path && (push!(e.back, from); empty!(e.ahead))
  e.buf = get!(e.buffers, path) do
    isfile(path) ? load(path) : Buffer(path=path)
  end
  if e.folder != dirname(path)
    e.folder = dirname(path)
    list_files!(e)
  end
  e.scroll.offset = e.buf.offset
  e.popup = :none
  e.goal = nothing
  w = window_of(e)
  w === nothing || focus(e)
  e
end

# --- the files that showed before --------------------------------------------------------
#
# Each window keeps the files that it showed, in the order that it showed them.
# ⌘⌥← goes back to the file that showed before the one that shows now, as the
# back button of a web browser does. ⌘⌥→ goes forward again, to the file that
# going back left. While the sidebar is open, two arrows at its top do the
# same. They are in the top bar, at the right of the part that's over the
# sidebar, and they aren't there while the sidebar is closed, or while
# something fills the window (see `filled`). An arrow is
# faint when it has no file to go to, and its tooltip names the file that it
# goes to. The two buttons at the side of a mouse go back and forward as well,
# if the mouse has them. Any way of showing a file adds to the list: a link, the
# list of files, the file finder, a line of a `find` block. A file shows from
# the place that it was scrolled to, because its buffer keeps that. A link to
# a heading of the page that shows adds nothing, because the file is the same.

"True when the window can show the file at `path` again: it's on the disk, or it's a new page that has no file yet"
showable(e, path) = haskey(e.buffers, path) || isfile(path)

"""
The file that `go_back!` would show, or nothing when no file showed before the
one that shows now. With `e.ahead` as the `list`, it's the file that
`go_forward!` would show.
"""
last_shown(e, list=e.back) = (i = findlast(p -> p != e.buf.path && showable(e, p), list); i === nothing ? nothing : list[i])

"""
Show the last file of `from` that's still there, and put the file that leaves
on `to`. A file that was renamed is there under its new name. One that went to
the Trash is passed over. It's true when there was a file to show.
"""
step_back!(e, from, to) = begin
  while !isempty(from)
    path = pop!(from)
    (path == e.buf.path || !showable(e, path)) && continue
    isempty(e.buf.path) || push!(to, e.buf.path)
    open!(e, path, record=false)
    return true
  end
  false
end

"Show the file that showed before the one that shows now. It's false when no file showed before."
go_back!(e) = step_back!(e, e.back, e.ahead)

"Show the file that `go_back!` left. It's false when there is none, or when another file was opened since."
go_forward!(e) = step_back!(e, e.ahead, e.back)

window_size(e) = something(viewport(e), e.size)

"The folder of the document that's showing. The sidebar can show another folder."
docdir(e) = isempty(e.buf.path) ? e.folder : dirname(e.buf.path)

"True when the file or folder at `path` is a hidden one: its name starts with a dot"
ishidden(path) = startswith(basename(path), '.')

"Make the sidebar list the hidden files and folders too, or leave them out again"
hidden!(e, on::Bool) = (e.hidden = on; list_files!(e); save_settings!(e); e)

"Show the folders and files of `folder` in the sidebar. The document that's showing stays."
go_folder!(e, folder) = begin
  e.folder = folder
  list_files!(e)
  e.files_scroll.offset = 0px
  e
end
input(e) = e.nodes[:input]::TextInput

# --- faces -----------------------------------------------------------------------------

const TEXT_SIZE = 17px   # of the page's text, before it's zoomed
body(e) = Face(e.font, nearest_weight(e.font, e.weight).style, TEXT_SIZE * e.zoom, colours.ink, false)
const HEADINGS = (2.1, 1.75, 1.4, 1.2, 1.05, 1.0)

"The face a line's plain text is drawn in"
face(e, line::Line) = begin
  b = body(e)
  k = line.kind
  k == Kind.heading ? Face(emboldened(b), size=b.size * HEADINGS[line.level]) :
  # A callout's text is the page's own. Its title is bold, in the colour of its kind.
  opens_callout(line) ? Face(emboldened(b), color=callout_colour(line.lang)) :
  k == Kind.blockquote ? (isempty(line.lang) ? Face(b, style=slanted(b.style), color=colours.dim) : b) :
  # Code is the size that the settings page chooses. The markup of a table or a rule is code's usual size.
  k in (Kind.code, Kind.fence) ? Face(b, family=codefont(), style=codestyle(), size=code_size(e)) :
  k in (Kind.table, Kind.rule) ? Face(b, family=codefont(), style=codestyle(), size=b.size * CODE_SCALE) : b
end

"The face for one span of a line whose plain text is drawn in `base`"
face(base::Face, s::Span) = begin
  s.markup && return Face(base, color=colours.faint)
  # The TeX of a formula, while it shows as it's written, is in the font of code
  s.math && return Face(codefont(), codestyle(), base.size * 0.86, base.color, false)
  # Inline code that runs is Julia, so its parts get the colours they have in a code block
  s.code && return Face(codefont(), codestyle(), base.size * 0.86, base.color, true, s.live ? "julia" : "")
  f = s.bold ? emboldened(base) : base
  s.italic && !isitalic(f.style) && (f = Face(f, style=slanted(f.style)))
  Face(f, color=!isempty(s.link) ? colours.accent : s.strike ? colours.faint : base.color)
end

# --- the weights of the page's text and of code --------------------------------------
#
# The page's text and code can each be lighter or heavier than the font's usual
# weight. The settings pages list the weights that each font has, up to
# Semibold, by the names that the font gives them. Code starts in Light, so
# that it reads lighter than the page's text. Bold text and headings are
# heavier than the rest: Bold, or Extra bold when the text is Semibold. A font
# that lacks the weight you chose draws the one nearest to it, and the next
# font that has the weight draws it again.
#
# A weight is kept as the Mac's number for it, like 300 for Light. Fonts don't
# agree on names: Helvetica Neue's UltraLight is lighter than its Thin, and
# Charter calls its usual weight Roman. The Mac's numbers don't always agree
# with the names either: it says that Source Code Pro's ExtraLight weighs 300
# and its Light 342. So a font's weights are in the order of the Mac's numbers,
# with the font's own names, and each is drawn by its name.

"What the settings pages call each weight of a font whose faces the Mac hides, like SF Mono, from 100 to 900"
const WEIGHT_NAMES = ("Thin", "Extra light", "Light", "Regular", "Medium", "Semibold", "Bold", "Extra bold", "Black")
const HEAVIEST = 650   # the heaviest that the page's text and code can be: Semibold. Heavier text would hide what's bold.

weight_label(w::Integer) = WEIGHT_NAMES[clamp(round(Int, w / 100), 1, length(WEIGHT_NAMES))]

"The style of a face of the weight `w`, as Skia reads it: \"\" for Regular, or like \"Light\" and \"Bold Italic\""
text_style(w::Integer, italic::Bool=false) = begin
  name = w == 400 ? "" : weight_name(w)
  italic ? String(strip("$name Italic")) : name
end

"The style of the slanted face of `style`, like \"Light Italic\""
slanted(style::AbstractString) = isempty(style) ? "Italic" : "$style Italic"

"The weight of bold text among text of the weight `w`"
bolder(w::Integer) = max(700, w + 200)

"The face `f` made bold. A face that's bold already, like a heading's, stays as it is."
emboldened(f::Face) = begin
  w = weight_of(f.style)
  w >= 700 ? f : Face(f, style=text_style(bolder(w), isitalic(f.style)))
end

"A weight of a font: what the settings pages call it, the style that draws it, and the Mac's number for it"
const Weight = @NamedTuple{label::String, style::String, weight::Int}
const font_weights = Dict{String,Vector{Weight}}()

"""
The weights of `family` that the page's text or code can be in, lightest
first, by the names that the font gives them. A font whose faces the Mac
hides, like SF Mono, has the weights that it draws when asked for 100, 200
and so on. There are none when the Mac has no font of that family.
"""
text_weights(family::AbstractString) = get!(font_weights, String(family)) do
  faces = filter(f -> !f.italic && f.width == Int(Skia.SK_FONT_STYLE_WIDTH_NORMAL), installed_faces(family))
  found = if isempty(faces)
    Weight[(label=weight_label(w), style=text_style(w), weight=w) for w in filter(>(0), [installed_weight(family, w) for w in 100:100:900])]
  else
    # The usual face draws with no style, as it did before there were weights to choose
    usual(f) = f.weight == 400 && lowercase(f.name) in ("regular", "roman", "normal")
    Weight[(label=f.name, style=usual(f) ? "" : f.name, weight=f.weight) for f in faces]
  end
  found = sort!(unique(w -> w.weight, found), by=w -> w.weight)
  light = filter(w -> w.weight <= HEAVIEST, found)
  # A font that has only heavy weights draws its lightest
  isempty(light) ? found[1:min(1, end)] : light
end

"""
The weight of `family` nearest to `w`: the one that text of the weight `w` is
drawn in. Of two that are as near, it's the one nearer to Regular.
"""
nearest_weight(family::AbstractString, w::Integer) = begin
  has = text_weights(family)
  isempty(has) && return (label=weight_label(w), style=text_style(w), weight=Int(w))
  argmin(x -> (abs(x.weight - w), abs(x.weight - 400)), has)
end

"The Mac's number for the weight of `family` called `name`, like \"Light\""
weight_called(family::AbstractString, name::AbstractString) = begin
  has = text_weights(family)
  i = findfirst(w -> w.label == name, has)
  i === nothing && error("The weights of $(font_label(family)) are $(join([w.label for w in has], ", ", " and ")). $name isn't one of them.")
  has[i].weight
end

"`w` if text can be that heavy"
text_weight(w::Integer) = 0 < w <= HEAVIEST ? Int(w) : error("A weight of text goes from 1, the lightest, to $HEAVIEST, which is Semibold. $w isn't one of them.")

piece(text, col, face; atomic=false, n=length(text), link="", node=nothing) = Piece(text, col, n, face, atomic, link, node)

# --- the font of code ------------------------------------------------------------------
#
# Code is drawn in a font whose letters are all one width. The settings page
# lists each such font on the Mac, and code is drawn in the one you choose, in
# the weight you choose. Code starts in the font's light weight when the font
# has one, as SF Mono has, so that code reads lighter than the page's text.

"The weight of the face of `family` nearest to `weight`, or 0 when the Mac has no font of that family"
installed_weight(family::AbstractString, weight::Integer) = begin
  style = Skia.sk_fontstyle_new(Int32(weight), Int32(Skia.SK_FONT_STYLE_WIDTH_NORMAL), Skia.SK_FONT_STYLE_SLANT_UPRIGHT)
  typeface = Skia.sk_fontmgr_match_family_style(fontmgr[], String(family), style)
  Skia.sk_fontstyle_delete(style)
  typeface == C_NULL && return 0
  found = Skia.sk_typeface_get_fontstyle(typeface)
  w = Int(Skia.sk_fontstyle_get_weight(found))
  Skia.sk_fontstyle_delete(found)
  Skia.sk_typeface_unref(typeface)
  w
end

"Draw code in the font and weight that `e`'s settings choose, from now until another window starts to draw"
use_code_font!(e) = (code_type[] = (e.code_font, nearest_weight(e.code_font, e.code_weight).style); e)

"True when every letter of `family` is as wide as every other, as in a font for code"
isfixed(family) = begin
  f = Face(family, "", 20px, colours.ink, false)
  all(c -> has(f, c), "iMw0") && measure(f, "i") == measure(f, "M") == measure(f, "0")
end

# The Mac's own font for code has a hidden name, and the list calls it SF Mono
font_label(family) = family == ".SF NS Mono" ? "SF Mono" : family
font_family(label) = label == "SF Mono" && CODE_FONT == ".SF NS Mono" ? CODE_FONT : label

const fixed_fonts = String[]

"""
The names in `fonts` with each font once, where a font comes in copies whose
letters are the same. A Nerd Font comes as X Nerd Font, X Nerd Font Mono and X
Nerd Font Propo, whose icons differ. A variable font, X Var, is X with its
weights in one file. The plain X stays, or the one there is.
"""
once_each(fonts) = filter(f -> !(endswith(f, COPIES) && replace(f, COPIES => "") in fonts), fonts)
const COPIES = r"(?<= Nerd Font) (Mono|Propo)$| Var$"

# Fonts of pictures, not letters, though each picture is as wide as the next
const PICTURE_FONTS = ("Webdings", "Wingdings", "Wingdings 2", "Wingdings 3", "Symbol", "Zapf Dingbats", "Bodoni Ornaments")

"The families of the fonts on this Mac whose letters are all one width, in order, with the one that code is drawn in at first"
code_fonts() = begin
  if isempty(fixed_fonts)
    names = String[]
    name = Skia.sk_string_new_empty()
    for i in 0:Skia.sk_fontmgr_count_families(fontmgr[])-1
      Skia.sk_fontmgr_get_family_name(fontmgr[], Cint(i), name)
      push!(names, unsafe_string(Skia.sk_string_get_c_str(name)))
    end
    Skia.sk_string_delete(name)
    # A font whose name starts with a dot is the Mac's own, for its menus and windows
    found = filter(f -> !startswith(f, '.') && font_family(f) == f && !(f in PICTURE_FONTS) && isfixed(f), unique(names))
    append!(fixed_fonts, sort!(once_each(found), by=lowercase))
  end
  unique([CODE_FONT; fixed_fonts])
end

# The text that stands for the box of a to-do item. The box is drawn in its place, so only the text's width matters.
# Both hold the same characters, so an empty box and a ticked one are the same width.
const TODO_OPEN, TODO_DONE = "[ ] ", "] [ "
"True when `seg` is the box of a to-do item"
isbox(seg) = seg.atomic && (seg.text == TODO_OPEN || seg.text == TODO_DONE)

"The runs of text that line `text` is drawn as. With `raw`, the markup shows."
pieces(e, text::String, line::Line, raw::Bool, i::Int=0) = begin
  base = face(e, line)
  out = Piece[]
  k = line.kind
  if k == Kind.code && line.lang == MATTER
    # In front matter, the key is fainter than what it's set to, and a comment slants
    m = match(r"^(\s*(?:-\s+)?)([^:#\s][^:#]*:)(.*)$", text)
    if startswith(lstrip(text), '#') || m === nothing
      comment = startswith(lstrip(text), '#')
      isempty(text) || push!(out, piece(text, 0, comment ? Face(base, color=colours.comment, style=codeslant()) : base))
    else
      isempty(m[1]) || push!(out, piece(String(m[1]), 0, base))
      push!(out, piece(String(m[2]), length(m[1]), Face(base, color=colours.dim)))
      isempty(m[3]) || push!(out, piece(String(m[3]), length(m[1]) + length(m[2]), base))
    end
    return out
  elseif k == Kind.code && line.lang == TOML_MATTER
    # TOML front matter looks like YAML front matter: a key and its = are fainter, and so is a
    # [table] line that starts a group of keys. A comment slants.
    m = match(r"^(\s*)((?:\"[^\"]*\"|'[^']*'|[\w.-])+\s*=)(.*)$", text)
    if startswith(lstrip(text), '#')
      push!(out, piece(text, 0, Face(base, color=colours.comment, style=codeslant())))
    elseif startswith(lstrip(text), '[') && m === nothing
      push!(out, piece(text, 0, Face(base, color=colours.dim)))
    elseif m === nothing
      isempty(text) || push!(out, piece(text, 0, base))
    else
      isempty(m[1]) || push!(out, piece(String(m[1]), 0, base))
      push!(out, piece(String(m[2]), length(m[1]), Face(base, color=colours.dim)))
      isempty(m[3]) || push!(out, piece(String(m[3]), length(m[1]) + length(m[2]), base))
    end
    return out
  elseif k == Kind.code && line.lang == HEX
    # In a line of a file's bytes, the place in the file is faint and the bytes as characters are dim
    n = ncodeunits(text)
    for (lo, hi, colour) in ((0, HEX_BYTES, colours.faint), (HEX_BYTES, HEX_CHARS, base.color), (HEX_CHARS, n, colours.dim))
      lo < n && push!(out, piece(text[lo+1:min(hi, n)], lo, Face(base, color=colour)))
    end
    return out
  elseif k == Kind.code
    # Each part of a line of code has its own colour, and comments slant
    for t in tokens(text, line.lang)
      colour = t.kind == :plain ? base.color : getfield(colours, t.kind)
      push!(out, piece(t.text, t.col, Face(base, color=colour, style=t.kind == :comment ? codeslant() : base.style)))
    end
    return out
  elseif k in (Kind.fence, Kind.table, Kind.rule)
    k == Kind.fence && !raw && return out
    isempty(text) || push!(out, piece(text, 0, k == Kind.table ? base : Face(base, color=colours.faint)))
    return out
  end
  lead = head(text, line.prefix)
  if k in (Kind.bullet, Kind.ordered, Kind.todo)
    line.level > 0 && push!(out, piece(head(lead, line.level), 0, base))
    mark = Face(emboldened(base), color=colours.marker)
    if k == Kind.bullet && !raw
      push!(out, piece("•  ", line.level, mark, atomic=true, n=line.prefix - line.level))
    elseif k == Kind.todo && !raw
      push!(out, piece(isdone(text) ? TODO_DONE : TODO_OPEN, line.level, base, atomic=true, n=line.prefix - line.level))
    else
      push!(out, piece(rest(lead, line.level), line.level, mark))
    end
    # A to-do item that's done reads fainter
    k == Kind.todo && isdone(text) && (base = Face(base, color=colours.dim))
  elseif k == Kind.paragraph
    isempty(lead) || push!(out, piece(lead, 0, base))
  elseif opens_callout(line) && !raw
    # The line that names a callout's kind shows the kind's icon, and its name when the line has no title of its own
    push!(out, callout_mark(e, line, base, length(text) > line.prefix))
  elseif raw && !isempty(lead)
    push!(out, piece(lead, 0, Face(base, color=colours.faint)))
  end
  start = line.prefix
  note = k == Kind.paragraph && !raw ? match(NOTE, text) : nothing
  if note !== nothing
    # The line that holds a footnote's text starts with the footnote's number
    start = length(note.match)
    push!(out, piece(note_mark(e, note[1]) * ".  ", 0, Face(base, color=colours.accent), atomic=true, n=start, link="^" * note[1]))
  end
  for s in spans(rest(text, start), start)
    s.markup && !raw && continue
    if startswith(s.link, '^') && !raw
      # [^name] shows as the footnote's number, small and raised
      push!(out, piece(note_mark(e, s.text), s.col, Face(base, size=base.size * 0.7, color=colours.accent), atomic=true, n=length(s.text), link=s.link))
      continue
    end
    # $x^2$ shows as the formula that its TeX describes
    if s.math && !raw && Maths.available()
      push!(out, equation(e, s, base))
      continue
    end
    # Line -1 isn't one of the document's lines: it's a line of a file under a path. Its inline code shows as code.
    s.live && !raw && i >= 0 ? push!(out, inline(e, i, s, base)) : symbols!(out, s.text, s.col, face(base, s), s.link)
  end
  out
end

# --- callouts ------------------------------------------------------------------------------
#
# A callout is a quote that stands out: a note, a tip, a warning. Its first
# line names its kind, as GitHub writes it: `> [!NOTE]`. The lines of the quote
# under that one are the callout's text. The page shows the first line as the
# kind's icon and its name, like "Note", in the kind's colour. Words after the
# `]` are a title, and show in place of the name. The callout's lines have a
# line of that colour down their left, and a little of the colour behind them.
# `markdown.jl` reads the lines.

"The icon of each kind of callout"
const CALLOUT_ICONS = (note="info-circle", tip="lightbulb", important="exclamation-square", warning="exclamation-triangle", caution="exclamation-octagon")

"The colour of a kind of callout. Each is a colour that code has in this page's colours."
callout_colour(kind) =
  kind == "tip" ? colours.string : kind == "important" ? colours.keyword : kind == "warning" ? colours.number :
  kind == "caution" ? removed_colour() : colours.call

"What a callout of this kind is called when it has no title of its own, like \"Note\""
callout_name(kind) = uppercasefirst(kind)

"The colour behind the lines of a callout: a little of its kind's colour over the page"
callout_tint(kind) = (c = RGBA(callout_colour(kind)); RGBA(c.r, c.g, c.b, dark_page() ? 0.12 : 0.08))

"What shows in place of the `> [!NOTE]` that starts a callout: the kind's icon, and the kind's name when `name` isn't empty"
@def mutable struct CalloutMark <: SemanticUI
  kind::String = "note"
  name::String = ""
  face::Face = Face("", "", TEXT_SIZE, colours.ink, false)   # of the name
end

const CALLOUT_GAP = 0.45   # the room between the icon and the words after it, as a part of the size of the text

icon_size(m::CalloutMark) = px(round(num(m.face.size) * 0.95))
wide(m::CalloutMark) = icon_size(m) + m.face.size * CALLOUT_GAP + measure(m.face, m.name)

describe(m::CalloutMark) =
  Row(fixed(wide(m)), Alignment.Center, justify=Alignment.Start, child_gap=m.face.size * CALLOUT_GAP,
    Icon(getproperty(CALLOUT_ICONS, Symbol(m.kind)), size=icon_size(m), color=m.face.color),
    (isempty(m.name) ? () : (Box(Text(m.name, size=m.face.size, family=m.face.family, subfamily=m.face.style, color=m.face.color, wrap=WrapMode.none)),))...)

inputs(m::CalloutMark) = (m.kind, m.name, m.face)

"""
The piece that stands for what starts the first line of a callout, in text
drawn in `base`. `titled` is true when the line has a title of its own after
it. The piece then shows only the icon.
"""
callout_mark(e, line::Line, base::Face, titled::Bool) = begin
  m = CalloutMark(kind=line.lang, name=titled ? "" : callout_name(line.lang), face=base)
  # It's part of its line, which is laid out once and kept. It can reach the document, and it isn't one of the document's children.
  setfield!(m, :parent, node!(Document, e, :document))
  piece(callout_name(line.lang), 0, base, atomic=true, n=line.prefix, node=Inline(m, wide(m), base.size * 1.2))
end

# --- inline code -------------------------------------------------------------------------
#
# !`code` in a line of text is inline code. The page runs the code and shows
# what it makes in place of the code: a node, like a switch or a file path, or
# any other value as text. The code shows again while the caret is on its line.

const INLINE = "!`"   # what inline code starts with

"The lines of `b` that have inline code"
inline_lines(e, b::Buffer) = get!(e.flows, (:inline, b.path, b.version)) do
  [i for (i, text) in enumerate(b.lines) if occursin(INLINE, text)]
end

"""
Which one of the document's pieces of inline code with this code the span `s`
of line `i` is: 1 for the first. Two pieces with the same code each make a
node of their own.
"""
ordinal(e, i::Int, s::Span) = begin
  b = e.buf
  marked = INLINE * s.text * "`"
  1 <= i <= length(b.lines) || return 1
  before = sum(j -> count(marked, b.lines[j]), Iterators.filter(<(i), inline_lines(e, b)), init=0)
  before + count(marked, head(b.lines[i], max(0, s.col - length(INLINE)))) + 1
end

"""
What the `n`th piece of inline code `code` of the document made. It's a Shown
when the code made a node. For any other value it's the value as text, and
true if that text says what went wrong.
"""
made(e, code::String, n::Int) = begin
  key = (:inline, e.buf.path, code, n)
  get!(e.nodes, key) do
    out = evaluate(e, code, key=key, inline=true)
    out isa Tuple && return out
    shown = Shown(value=out, inline=true)
    out isa SemanticUI && own!(shown, out)
    shown
  end
end

"Lay out what inline code made, to learn how much room it takes in its line"
fit(e, shown) = begin
  # It's part of its line. It can reach the document, and it isn't one of the document's children:
  # a line is laid out once and kept, so the document isn't given it again on each frame.
  shown.parent === nothing && setfield!(shown, :parent, node!(Document, e, :document))
  concrete = describe(Row(Alignment.Start, geometry(shown)), (e.width, 9999px))
  # A node with no width of its own, like a slider, takes all the room it's given. In a line it gets this much.
  w = concrete.width < 16px ? INLINE_W * e.zoom : concrete.width
  Inline(shown, min(w, e.width), concrete.height)
end

const INLINE_W = 180px   # of a node in a line of text that has no width of its own, before the text is zoomed

"The piece that stands for the inline code of span `s`, on line `i`, in text drawn in `base`"
inline(e, i::Int, s::Span, base::Face) = begin
  out = made(e, s.text, ordinal(e, i, s))
  n = length(s.text)
  out isa Tuple || return piece(s.text, s.col, base, atomic=true, n=n, node=fit(e, out))
  text, failed = out
  piece(text, s.col, failed ? Face(base, color=colours.accent) : base, atomic=true, n=n)
end

const LONGEST_VALUE = 200   # characters of a value that inline code shows as text

"""
A value as the text that inline code shows for it. A number reads the way a
sheet shows it: 28.8 and not 28.799999999999997, with or without a unit.
"""
said(value) = begin
  text = value isa AbstractString ? String(value) : value === nothing ? "nothing" : Base.invokelatest(shown, value)
  text = replace(text, r"\s*\n\s*" => " ")
  length(text) > LONGEST_VALUE ? first(text, LONGEST_VALUE) * "…" : text
end

# The page's fonts have no ⌘, ⌫ or arrows, so those characters are drawn in one that does
const SYMBOLS = r"[⌘⌥⇧⌃⏎⇥⌫⌦⎋←→↑↓]+"

"""
Add `text` to `out`, with its keyboard symbols in a font that has them. That's
Lucida Grande, and for a symbol that it hasn't got, like ⏎, a font that macOS picks.
"""
symbols!(out, text, col, face, link="") = begin
  at = 1
  add(part, f) = isempty(part) || (push!(out, piece(String(part), col, f; link)); col += length(part))
  for m in eachmatch(SYMBOLS, text)
    add(SubString(text, at, prevind(text, m.offset)), face)
    for (part, f) in runs(m.match, Face(face, family=SYMBOL_FONT, style=""))
      add(part, f)
    end
    at = m.offset + ncodeunits(m.match)
  end
  add(SubString(text, at), face)
  out
end

"The first and last line of the code block that line `i` is in, with the lines that open and close it"
codeblock(b::Buffer, i::Int) = begin
  ks = kinds(b)
  s = t = i
  while s > 1 && !(ks[s].kind == Kind.fence && ks[s].level == 0); s -= 1 end
  while t < length(ks) && !(ks[t].kind == Kind.fence && ks[t].level == 1 && t > s); t += 1 end
  (s, t)
end

"""
True when the caret is in the code block that line `i` is in, and the selection
doesn't reach out of the block. A selection that goes through a block leaves it
as it reads.
"""
incode(b::Buffer, i::Int) = begin
  caretless(b) && return false
  s, t = codeblock(b, i)
  # A block that the caret is on as a whole shows as what it makes
  s <= b.caret[1] <= t && s <= b.anchor[1] <= t && picked(b) === nothing
end

# --- rich text and plain text ----------------------------------------------------------------
#
# A page is written in one of two ways. A click on the snake or the ladder in the
# top bar changes from one to the other, and so does ⌘E. You can change the text in both.
# The two are levels of abstraction. Plain text is the low level: the page's
# symbols. Rich text is the high level: the graphics that the symbols make.
#
# As rich text, a line shows the way it reads: bold words are bold, and the
# characters that make them bold don't show. A diagram shows as a diagram. A
# line stays that way when the caret comes onto it, so the caret has rules:
#
#   - It can't stop among characters that don't show, like the ** of bold
#     text or the # of a heading. A key that moves it goes over them.
#   - It stays on the side of them that it came from. After **bold**, a caret
#     that came from the left is in the bold text, and what's typed there is
#     bold. A caret that came from the right is after the bold text.
#   - It doesn't go into a part of the page that shows as one thing: a
#     diagram, a form, a picture, a line across the page. It goes onto the
#     part as a whole, and a line goes round the part. Return then gives the
#     part the keyboard, so you can type in a field of a form. ⌫ takes the
#     part away. ↑ and ↓ go on to the line before it and the line after it.
#   - It steps over the ``` lines of a code block, which don't show.
#
# Only a part that's being typed shows its markup: the caret is on it because
# its text was typed there, and it stays as text until the caret leaves.
# Without that, a line like ```mermaid could never be typed.
#
# As plain text, the part of the page that the caret is in shows its markup:
# its line, the cell of a table, the whole of a code block or a diagram. The
# caret goes anywhere. Every other part of the page still shows as rich text.

"The kinds of line whose text shows without its markup in rich text"
const TEXT_KINDS = (Kind.paragraph, Kind.heading, Kind.bullet, Kind.ordered, Kind.todo, Kind.blockquote)

"True when the page is written as rich text: it's a document, and the part with the caret doesn't show its markup"
rich(b::Buffer) = !b.plain && b.view == :markdown

"True when the caret is on line `i`, and the selection doesn't reach another line"
alone(b::Buffer, i::Int) = !caretless(b) && i == b.caret[1] == b.anchor[1]

"True when line `i` holds only a picture, a sound or a video"
pictured(b::Buffer, i::Int) = kinds(b)[i].kind == Kind.paragraph && occursin("![", b.lines[i]) && occursin(PICTURE_LINE, b.lines[i])

"""
True when line `i` shows its markup. It has to have the caret. As plain text
that's enough. As rich text, the line also has to be one that shows as
something other than its text, which is only so while it's typed: a ``` line,
a line across the page, a picture, a table's line of dashes.
"""
israw(b::Buffer, i::Int) =
  alone(b, i) && (!rich(b) || (picked(b) === nothing && (kinds(b)[i].kind in (Kind.fence, Kind.rule, Kind.table) || pictured(b, i) || maths_line(b, i))))

"""
The spans of line `i` as rich text reads them: the text after what starts the
line, or the text of each cell of a row of a table. `start` is the column
where that text starts.
"""
richspans(b::Buffer, i::Int) = begin
  text, line = b.lines[i], kinds(b)[i]
  if line.kind in TEXT_KINDS
    note = line.kind == Kind.paragraph ? match(NOTE, text) : nothing
    start = note === nothing ? line.prefix : length(note.match)
    return (start, spans(rest(text, start), start))
  end
  out = Span[]
  line.kind == Kind.table && table(b, i) !== nothing || return (0, out)
  for c in tablecells(text)
    append!(out, spans(rest(head(text, c.hi), c.lo), c.lo))
  end
  (0, out)
end

"""
The parts of line `i` that take no room in rich text, each as the column it
starts at and the column it ends at: markup like **, and what starts a heading,
a list item or a quote. Two that touch are one. The caret can't stop inside
one. The part that starts a line starts at -1, so that column 0 is inside it.
"""
unseen(b::Buffer, i::Int) = begin
  start, ss = richspans(b, i)
  out = Tuple{Int,Int}[]
  kinds(b)[i].kind == Kind.paragraph && start == kinds(b)[i].prefix || start == 0 || push!(out, (-1, start))
  for s in ss
    s.markup || continue
    a, z = s.col, s.col + length(s.text)
    !isempty(out) && last(out)[2] == a ? (out[end] = (last(out)[1], z)) : push!(out, (a, z))
  end
  out
end

"The parts of line `i` that each show as one thing in rich text: the name of a footnote, inline code that runs, and a formula"
wholes(b::Buffer, i::Int) =
  Tuple{Int,Int}[(s.col, s.col + length(s.text)) for s in richspans(b, i)[2]
                 if !s.markup && (s.live || (s.math && Maths.available()) || startswith(s.link, '^')) && length(s.text) > 1]

"The first column of line `i` where the caret can stop in rich text: where the text of a heading or a list item starts"
first_stop(b::Buffer, i::Int) = begin
  rich(b) || return 0
  hidden = unseen(b, i)
  isempty(hidden) || first(hidden)[1] >= 0 ? 0 : first(hidden)[2]
end

"""
The first and last line of the part of the page that line `i` is in, when the
caret steps over that part in rich text. That's a part that shows as one
thing: a block that shows as a diagram, a plan, a chart and so on, the front
matter, a formula on lines of its own, a picture, a line across the page, a
table's line of dashes. A ``` line is such a part by itself. Nothing for a
line of text or of code.
"""
solid(b::Buffer, i::Int) = begin
  # A `columns` block that takes no room is such a part, with the empty lines after it that take none
  fold = column_fold(b, i)
  fold === nothing || return fold
  ks = kinds(b)
  k = ks[i]
  if k.kind in (Kind.fence, Kind.code)
    s, t = codeblock(b, i)
    lang = ks[s].lang
    closed = t > s && ks[s].kind == Kind.fence && ks[t].kind == Kind.fence && ks[t].level == 1
    whole = closed && (lang in (MATTER, TOML_MATTER, TAKEOFF, SCHEDULE, LIVE) || haskey(BLOCKS, lang) ||
                       (lang == DIAGRAM && isdiagram(join(b.lines[s+1:t-1], "\n"))) ||
                       (lang == MATH && has_maths(join(b.lines[s+1:t-1], "\n"))) || block_source(b, s) !== nothing)
    return whole ? (s, t) : k.kind == Kind.fence ? (i, i) : nothing
  end
  (k.kind == Kind.rule || pictured(b, i) || maths_line(b, i)) && return (i, i)
  if k.kind == Kind.table
    run = table(b, i)
    run !== nothing && i == run[1] + 1 && return (i, i)
  end
  nothing
end

"""
True when the caret can go to line `i` from line `from`. It can't go into a
part that shows as one thing, but it can move about in one that it's already
in, which shows as text because it's being typed. A ``` line only has the
caret while it's typed.
"""
free(b::Buffer, i::Int, from::Int) = begin
  run = solid(b, i)
  run === nothing && return true
  kinds(b)[i].kind == Kind.fence ? from == i : run[1] <= from <= run[2]
end

"""
The first and last line of the part of the page that line `i` is in, when the
caret can be on that part as a whole: a block that shows as a diagram, a form,
a plan and so on, the front matter, a picture, a line across the page. Nothing
for any other line. A ``` line of a code block isn't such a part, and nor is
a table's line of dashes: neither shows, so the caret steps over them.
"""
part(b::Buffer, i::Int) = begin
  run = solid(b, i)
  run === nothing && return nothing
  k = kinds(b)[i].kind
  # A `columns` block that takes no room doesn't show either
  k == Kind.table || (k == Kind.fence && run[1] == run[2]) || column_fold(b, i) !== nothing ? nothing : run
end

"""
The first and last line of the part of the page that the caret is on as a
whole, or nothing when it's in text. The caret is on a part when it's at the
very start of the part's first line, in rich text, with nothing selected. The
part then shows as what it makes, with a line round it, and not as its code.
"""
picked(b::Buffer) = begin
  key = (b.version, b.caret, b.anchor, b.plain, b.reading)
  key == b.picked_for && return b.picked
  i, col = b.caret
  run = rich(b) && col == 0 && alone(b, i) && i <= length(b.lines) ? part(b, i) : nothing
  b.picked_for = key
  b.picked = run !== nothing && run[1] == i ? run : nothing
end

"""
The first line after `i`, or with `by` of -1 before it, that the caret can go
to from line `from`: a line of text, or a line of a part that the caret can be
on as a whole. It's 0, or a line past the last, when there's none.
"""
step_over(b::Buffer, i::Int, by::Int, from::Int) = begin
  while 1 <= i <= length(b.lines) && !free(b, i, from) && part(b, i) === nothing
    s, t = solid(b, i)
    i = by > 0 ? t + 1 : s - 1
  end
  i
end

"Where the caret goes in rich text when it's sent to `p` from `from`, going in the direction `by`: the nearest place where it can stop, or the start of a part that it goes onto as a whole"
settle_rich(b::Buffer, p::Pos, by::Int, from::Pos) = begin
  i, col = p
  if !free(b, i, from[1])
    found = false
    for d in (by < 0 ? (-1, 1) : (1, -1))
      j = step_over(b, i, d, from[1])
      1 <= j <= length(b.lines) || continue
      # The caret goes onto a part like a diagram as a whole: to the start of its first line
      free(b, j, from[1]) || return (part(b, j)[1], 0)
      i, col, by, found = j, d > 0 ? 0 : length(b.lines[j]), d, true
      break
    end
    found || return p   # the page has nothing but lines that don't show
  end
  for (a, z) in Iterators.flatten((unseen(b, i), wholes(b, i)))
    a < col < z || continue
    col = a < 0 || by > 0 ? z : by < 0 ? a : col - a < z - col ? a : z
  end
  (i, col)
end

"""
Look at where the caret is, before the page is laid out. As rich text, a caret
that something put among characters that don't show goes to the nearest place
where it can stop. In a file that was just opened, and after a change from
plain text to rich text, a caret that's in a part of the page that shows as
one thing goes onto the part as a whole. At any other time it stays in such a
part, which then shows as text: a key or a click can't take it there, so
something meant to. A click on the front matter does, and so does the menu
that inserts a block.
"""
stand!(b::Buffer) = begin
  b.caret == b.stood && return b
  # The caret is on no line while the page is drawn for paper, so it has nowhere to stand
  b.caret[1] < 1 && return b
  if rich(b) && !selecting(b) && isempty(b.others)
    b.caret = b.anchor = b.stood === nothing ? settle(b, b.caret, 1, from=(0, 0)) :
                                               settle(b, b.caret, cmp(b.caret, b.stood), from=b.caret)
  end
  b.stood = b.caret
  b
end

"""
The pairs of markup in `ss`, the spans of a line: for each, the place in `ss` of
the span that opens it and of the one that closes it, like the two ** of bold
text. A pair that's inside another comes before it.
"""
markpairs(ss) = begin
  out = Tuple{Int,Int}[]
  open = Int[]
  for (k, s) in enumerate(ss)
    (s.markup && s.text != "\\") || continue
    o = isempty(open) ? "" : ss[last(open)].text
    closes = !isempty(o) && (o == "[" ? startswith(s.text, "](") : o == "[^" ? s.text == "]" : o == "!`" ? s.text == "`" : o == s.text)
    closes ? push!(out, (pop!(open), k)) : push!(open, k)
  end
  out
end

"""
Which characters of line `i` go when the columns `x` to `y` of it are deleted
as rich text: true for each one that goes. The text between goes. Markup
stays if it still has text to mark, so bold text that loses its last words
is still bold, and it goes with the last of its text. With `lead`, what starts
the line goes too: that's for a line that's joined to the one before it.
"""
cutmask(b::Buffer, i::Int, x::Int, y::Int; lead=false) = begin
  text, line = b.lines[i], kinds(b)[i]
  n = length(text)
  gone = falses(n)
  if !(line.kind in TEXT_KINDS || (line.kind == Kind.table && table(b, i) !== nothing))
    gone[x+1:y] .= true
    return gone
  end
  start, ss = richspans(b, i)
  mark = falses(n)
  lead && (gone[1:min(start, y)] .= true)
  # Text that no span holds, like the | between two cells, goes as it would in plain text
  held = falses(n)
  for s in ss
    held[s.col+1:s.col+length(s.text)] .= true
    s.markup ? (mark[s.col+1:s.col+length(s.text)] .= true) : (gone[max(s.col, x)+1:min(s.col + length(s.text), y)] .= true)
  end
  for c in max(x, start)+1:y
    held[c] || (gone[c] = true)
  end
  # The \ before a character goes with the character
  for s in ss
    s.markup && s.text == "\\" && s.col + 2 <= n && gone[s.col+2] && (gone[s.col+1] = true)
  end
  for (o, c) in markpairs(ss)
    from, to = ss[o].col + length(ss[o].text), ss[c].col
    all(k -> mark[k] || gone[k], from+1:to) || continue
    any(k -> gone[k], from+1:to) || continue   # nothing between them was deleted, so they stay
    gone[ss[o].col+1:from] .= true
    gone[to+1:to+length(ss[c].text)] .= true
  end
  gone
end

"""
What to change to delete the text from `lo` to `hi` as rich text: the place
where the change starts, the place where it ends, and the markup between them
that stays. The change can reach past `lo` and `hi`, to take the markup of
text that's all deleted. `typed` is true when something is typed in its place.
"""
richcut(b::Buffer, lo::Pos, hi::Pos; typed=false) = begin
  kept(i, gone, x, y) = String([c for (k, c) in enumerate(b.lines[i]) if x < k <= y && !gone[k]])
  reach(gone, x, y) = (min(x, something(findfirst(gone), x + 1) - 1), max(y, something(findlast(gone), y)))
  if lo[1] == hi[1]
    gone = cutmask(b, lo[1], lo[2], hi[2])
    x, y = reach(gone, lo[2], hi[2])
    return ((lo[1], x), (hi[1], y), kept(lo[1], gone, x, y))
  end
  # A selection that takes all the text of its first line takes what starts that line too, like the # of a
  # heading. The last line then keeps what starts it, unless its text all goes. Any other selection joins
  # what's left of the last line to the first, without what starts the last. So does one that's typed over:
  # what's typed is in the first line, with what starts it.
  whole = !typed && lo[2] <= first_stop(b, lo[1])
  top = whole ? trues(length(b.lines[lo[1]])) : cutmask(b, lo[1], lo[2], length(b.lines[lo[1]]))
  bottom = cutmask(b, hi[1], 0, hi[2], lead=!whole || hi[2] >= length(b.lines[hi[1]]))
  x = whole ? 0 : reach(top, lo[2], lo[2])[1]
  _, y = reach(bottom, hi[2], hi[2])
  ((lo[1], x), (hi[1], y), kept(lo[1], top, x, length(b.lines[lo[1]])) * kept(hi[1], bottom, 0, y))
end

"""
What Return adds in rich text to keep the look of each half of the text that
the caret is in: the markup that closes what's open at the caret, to end the
first line, and the markup that opens it again, to start the next. A caret
at the very start or end of bold text goes outside it first, so neither line
gets bold text with nothing in it.
"""
halves!(b::Buffer) = begin
  i, col = b.caret
  (rich(b) && !selecting(b) && kinds(b)[i].kind in TEXT_KINDS) || return ("", "")
  _, ss = richspans(b, i)
  found = markpairs(ss)
  inside((o, c)) = (ss[o].col + length(ss[o].text), ss[c].col)
  moved = true
  while moved
    moved = false
    for p in found
      from, to = inside(p)
      col == to && to > from && (col = to + length(ss[p[2]].text); moved = true)
      col == from && to > from && (col = ss[p[1]].col; moved = true)
    end
  end
  b.caret = b.anchor = (i, col)
  around = [p for p in found if inside(p)[1] < col < inside(p)[2]]
  (join(ss[c].text for (_, c) in around), join(ss[o].text for (o, _) in reverse(around)))
end

"Lay out line `i` of the document"
flow(e, i::Int, raw::Bool=israw(e.buf, i)) = begin
  # A line in a column of the page is laid out for the column's width. See "blocks of the page side by side".
  column = column_at(e, i)
  column === nothing || return column_flow(e, column, i, raw)
  text, line = e.buf.lines[i], kinds(e.buf)[i]
  if e.buf.view == :code
    # A line of a file of code is laid out as a line of a file that's only shown is
    length(e.flows) > 4000 && empty!(e.flows)
    return get!(() -> file_line(e, text, line, i), e.flows, (:file, text, line))
  end
  # The lines that open and close a code block show while the caret is in the block. As rich text, one only shows while it's typed.
  line.kind == Kind.fence && (raw = rich(e.buf) ? israw(e.buf, i) : incode(e.buf, i))
  build() = laid(e, text, line, raw, i)
  # What inline code made can change its size, so its line is laid out again each time
  !raw && occursin(INLINE, text) && !(line.kind in (Kind.code, Kind.fence, Kind.rule)) && return build()
  length(e.flows) > 4000 && empty!(e.flows)
  # A footnote's number comes from the rest of the document, which `notes` reads once for each
  # version of it. So the line is kept for that version, and laid out again after a change.
  !raw && occursin("[^", text) && return get!(build, e.flows, (text, line, raw, :notes, e.buf.path, e.buf.version))
  get!(build, e.flows, (text, line, raw))
end

"Lay out `text`, line `i` of the document, which is a line of the kind `line`, for a page that's `wide`"
laid(e, text, line::Line, raw::Bool, i::Int, wide=e.width) = begin
  base = face(e, line)
  ps = spare(pieces(e, text, line, raw, i))
  k = line.kind
  # A hidden ``` line leaves a little room at the top or bottom of its block
  lh = k == Kind.heading ? base.size * 1.35 : body(e).size * (k == Kind.fence && !raw ? 0.6 : 1.65)
  # Lines of bigger code are further apart
  k in (Kind.code, Kind.fence) && (lh *= e.code_scale / CODE_SCALE)
  left = k in (Kind.code, Kind.fence) ? BLOCK_X : k == Kind.blockquote ? QUOTE_X : 0px
  # Lines that a list item wraps onto start under its text, not under its bullet
  hang = k in (Kind.bullet, Kind.ordered, Kind.todo) ? sum(p -> measure(p.face, p.text), ps[1:min(end, line.level > 0 ? 2 : 1)], init=0px) : left
  above = k == Kind.heading ? lh * 0.3 : 0px
  below = k == Kind.heading ? lh * 0.12 : 0px
  wrap(ps, wide; lh, size=base.size, left, hang, above, below, kind=k, raw)
end

"Forget every layout, after something that changes how all the text is drawn"
restyle!(e) = (empty!(e.flows); e.reveal = true; e)

# --- tables ----------------------------------------------------------------------------
#
# A table is a line of cells, a line of dashes, then more lines of cells. It's
# drawn as a grid, and the caret moves from cell to cell. The line of dashes
# isn't drawn. If the caret gets onto it, the table shows as plain lines.

"The first and last line of the table that line `i` is part of, or nothing"
table(b::Buffer, i::Int) = begin
  ks = kinds(b)
  ks[i].kind == Kind.table || return nothing
  s = t = i
  while s > 1 && ks[s-1].kind == Kind.table; s -= 1 end
  while t < length(ks) && ks[t+1].kind == Kind.table; t += 1 end
  t > s && isdivider(b.lines[s+1]) ? (s, t) : nothing
end

"The lines of a table that are rows of cells"
tablerows((s, t)) = [s; s+2:t]

"The cells of the row that `p` is in, when that row is drawn in a grid or a sheet"
rowcells(b::Buffer, p::Pos) = begin
  insheet(b, p[1]) && return sheetcells(b.lines[p[1]])
  inspread(b, p[1]) && return spreadcells(b.lines[p[1]])
  run = table(b, p[1])
  (run === nothing || p[1] == run[1] + 1) ? Cell[] : tablecells(b.lines[p[1]])
end

within(c::Cell, col::Int) = c.lo <= col <= c.limit

"The cell that `p` is in, or nothing"
cellat(b::Buffer, p::Pos) = begin
  cs = rowcells(b, p)
  i = findfirst(c -> within(c, p[2]), cs)
  i === nothing ? nothing : cs[i]
end

"Which of `cs` column `col` is in, or is nearest to"
nearest(cs, col::Int) = argmin(i -> within(cs[i], col) ? 0 : min(abs(col - cs[i].lo), abs(col - cs[i].limit)), eachindex(cs))

"""
Where the caret goes when it's sent to `p`. In a table that's the same place
if `p` is in a cell. Otherwise it's the next cell in the direction `by`, or the
nearest cell when `by` is 0.
"""
settle(b::Buffer, p::Pos, by::Int=0; from::Pos=b.caret) = begin
  rich(b) || return settle_cells(b, p, by)
  # A caret that's on a part as a whole isn't in the part's text, so it can't move about in that text
  from == b.caret && picked(b) !== nothing && (from = (0, 0))
  # As rich text the caret also keeps off what doesn't show. A place that one rule gives can break the other, so both look again.
  for _ in 1:4
    q = settle_rich(b, settle_cells(b, p, by), by, from)
    q == p && break
    p = q
  end
  p
end

"Where the caret goes when it's sent to `p`, by the rules of a table, a sheet and a spreadsheet"
settle_cells(b::Buffer, p::Pos, by::Int=0) = begin
  run = sheet(b, p[1])
  run === nothing || return settle(b, run, p, by)
  run = spread(b, p[1])
  run === nothing || return settle(b, run, p, by, spreadcells)
  run = table(b, p[1])
  run === nothing && return p
  s, t = run
  i, col = p
  if i == s + 1
    # The line of dashes. Step over it, unless that's where a click put the caret.
    by == 0 && return p
    j = by < 0 ? s : s + 2
    return j > t ? (t < length(b.lines) ? (t + 1, 0) : p) : settle_cells(b, (j, col))
  end
  cs = tablecells(b.lines[i])
  (isempty(cs) || any(c -> within(c, col), cs)) && return p
  rows = tablerows(run)
  r = findfirst(==(i), rows)
  if by < 0
    c = findlast(c -> c.limit < col, cs)
    c === nothing || return (i, cs[c].hi)
    r > 1 && return row_edge(b, rows[r-1], 1)
    s > 1 ? line_end(b, s - 1) : (i, cs[1].lo)
  elseif by > 0
    c = findfirst(c -> c.lo > col, cs)
    c === nothing || return (i, cs[c].lo)
    r < length(rows) && return row_edge(b, rows[r+1], -1)
    t < length(b.lines) ? (t + 1, 0) : (i, cs[end].hi)
  else
    c = cs[nearest(cs, col)]
    (i, clamp(col, c.lo, c.limit))
  end
end

"The start of the first cell of row `i`, or with `by` of 1 the end of its last cell"
row_edge(b::Buffer, i::Int, by::Int) = begin
  cs = tablecells(b.lines[i])
  isempty(cs) ? (i, 0) : by < 0 ? (i, cs[1].lo) : (i, cs[end].hi)
end

"The runs of text in a cell that shows columns `lo` to `hi` of `text`"
cellpieces(e, i::Int, text::String, lo::Int, hi::Int, base::Face, raw::Bool) = begin
  out = Piece[]
  for s in spans(rest(head(text, hi), lo), lo)
    s.markup && !raw && continue
    s.math && !raw && Maths.available() ? push!(out, equation(e, s, base)) :
    s.live && !raw ? push!(out, inline(e, i, s, base)) : symbols!(out, s.text, s.col, face(base, s), s.link)
  end
  out
end

"How wide a piece is before it's wrapped"
wide(p::Piece) = p.node === nothing ? measure(p.face, p.text) : p.node.w

"The text of each cell of a row of a table, without the spaces around it"
celltexts(line::AbstractString) = begin
  chars = collect(strip(line))
  !isempty(chars) && chars[1] == '|' && popfirst!(chars)
  !isempty(chars) && chars[end] == '|' && (length(chars) < 2 || chars[end-1] != '\\') && pop!(chars)
  out, cell = String[], Char[]
  for (i, c) in enumerate(chars)
    c == '|' && (i == 1 || chars[i-1] != '\\') ? (push!(out, strip(String(cell))); empty!(cell)) : push!(cell, c)
  end
  push!(out, strip(String(cell)))
end

tableline(cells) = "| " * join(cells, " | ") * " |"

"The side each column's text sits on, from the table's line of dashes: :left, :center or :right"
aligns(divider::AbstractString) =
  [startswith(c, ':') && endswith(c, ':') ? :center : endswith(c, ':') ? :right : :left for c in celltexts(divider)]

"Move each line of `f` across so its text sits on `side` of a space `room` wide"
align(f::Flow, room::px, side::Symbol) = begin
  side == :left && return f
  lines = map(f.lines) do vl
    dx = max(0px, room - sum(seg -> seg.w, vl.segs, init=0px)) * (side == :center ? 0.5 : 1)
    VLine([Seg(s.text, s.col, s.n, s.face, s.atomic, s.link, s.x + dx, s.w, s.node) for s in vl.segs], vl.x + dx, vl.from, vl.to, vl.top, vl.high)
  end
  Flow(lines, f.lh, f.size, f.above, f.below, f.kind, f.raw)
end

"Lay out the table in lines `from` to `to` of the document"
grid(e, from::Int, to::Int) = begin
  b = e.buf
  caret = from <= b.caret[1] <= to ? b.caret : nothing
  build() = begin
    base = Face(body(e), size=body(e).size * 0.94)
    lh = base.size * 1.5
    rows = tablerows((from, to))
    cells = [tablecells(b.lines[i]) for i in rows]
    ncols = max(1, maximum(length, cells))
    parts = map(enumerate(rows)) do (r, i)
      map(1:ncols) do c
        c <= length(cells[r]) || return Piece[]
        cell = cells[r][c]
        # The cell with the caret shows the spaces typed after its text, and as plain text its markup
        active = caret !== nothing && caret[1] == i && within(cell, caret[2])
        cellpieces(e, i, b.lines[i], cell.lo, active ? max(cell.hi, caret[2]) : cell.hi,
                   r == 1 ? emboldened(base) : base, active && b.plain)
      end
    end
    # Each column gets room in proportion to its longest cell
    natural = [maximum(row -> sum(wide, row[c], init=0px), parts, init=0px) + 2CELL_X for c in 1:ncols]
    natural = [clamp(w, 60px, e.width * 0.75) for w in natural]
    space = e.width - 1px * (ncols + 1)
    widths = natural .* (num(space) / num(sum(natural)))
    sides = aligns(b.lines[from+1])
    flows = [[align(wrap(row[c], widths[c] - 2CELL_X; lh, size=base.size, left=CELL_X), widths[c] - 2CELL_X, get(sides, c, :left))
              for c in 1:ncols] for row in parts]
    heights = [maximum(f -> tall(f), row) + 2CELL_Y for row in flows]
    Grid(rows, widths, heights, cells, flows)
  end
  # What inline code made can change its size, so a table with some in it is laid out again each time
  any(text -> occursin(INLINE, text), @view b.lines[from:to]) && return build()
  get!(build, e.flows, (:grid, from, b.lines[from:to], caret, b.plain))
end

const TABLE_GAP = 8px   # above and below a table
tall(g::Grid) = g.head + sum(g.heights) + 1px * (length(g.heights) + 1) + 2TABLE_GAP

"Where the text of row `r`, column `c` starts, from the top left of the table's item"
cell_origin(g::Grid, r::Int, c::Int) =
  (g.left + 1px * c + sum(g.widths[1:c-1], init=0px),
   TABLE_GAP + g.head + 1px * r + sum(g.heights[1:r-1], init=0px) + (g.heights[r] - tall(g.flows[r][c]))/2)

"The column in `cell` nearest to `x` on line `k` of its flow"
cellcol(f::Flow, k::Int, x::px, cell::Cell) =
  isempty(f.lines[k].segs) ? cell.lo : clamp(colat(f, k, x), cell.lo, cell.limit)

"The row and column of `g` that holds the caret at `p`, or nothing"
gridcell(g::Grid, p::Pos) = begin
  r = findfirst(==(p[1]), g.rows)
  (r === nothing || isempty(g.cells[r])) && return nothing
  (r, nearest(g.cells[r], p[2]))
end

# --- spreadsheets ----------------------------------------------------------------------
#
# A code block in the language `spreadsheet` is drawn as a spreadsheet. Each
# line of the block is a row, with a | between its cells, as in a table. A row
# of letters is over the cells, one for each column. A column of numbers is on
# their left, one for each row. A cell that starts with = is a formula: a Julia
# expression that can use the other cells by name, like B2 * C2 or sum(D2:D9).
# The cell shows what its formula comes to. While the caret is in the cell, it
# shows the formula.
#
# It's laid out as a `Grid`, so the caret moves as it does in a table, and the
# bar over the grid adds and removes a row or a column. Hold ⌥ and click the
# spreadsheet to see it as lines of code.

const SPREAD_Y = 5px   # above and below the text of a cell

"""
The lines that open and close the spreadsheet that line `i` is in, or nothing.
A spreadsheet needs a row, and it shows as lines of code while the caret is on
the line that opens or closes it.
"""
spread(b::Buffer, i::Int) = drawn(b, i, SPREADSHEET)

"True when line `i` is a row of a spreadsheet"
inspread(b::Buffer, i::Int) = begin
  run = spread(b, i)
  run !== nothing && run[1] < i < run[2]
end

"The lines that are the rows of the table or the spreadsheet that line `i` is in"
gridrows(b::Buffer, i::Int) = begin
  run = spread(b, i)
  run === nothing ? tablerows(table(b, i)) : collect(run[1]+1:run[2]-1)
end

"The name of every cell of a spreadsheet that has `rows` rows and `cols` columns"
cellnames(rows::Int, cols::Int) = [letters(c) * string(r) for r in 1:rows for c in 1:cols]

"How wide the longest part of `p` is that can't go onto two lines: a word, a number or what a formula comes to"
unbroken(p::Piece) =
  p.node !== nothing ? p.node.w : p.atomic ? measure(p.face, p.text) :
  maximum(word -> measure(p.face, word), split(p.text), init=0px) + (p.face.chip ? 2(CHIP_X + 1px) : 0px)

"Lay out the spreadsheet whose code block opens on line `from` and closes on line `to`"
spreadgrid(e, from::Int, to::Int) = begin
  b = e.buf
  caret = alone(b, b.caret[1]) && from < b.caret[1] < to ? b.caret : nothing
  build() = begin
    base = Face(body(e), size=body(e).size * 0.94)
    lh = base.size * 1.5
    rows = collect(from+1:to-1)
    cells = [spreadcells(b.lines[i]) for i in rows]
    texts = [spreadtexts(b.lines[i]) for i in rows]
    # The cells are only worked out again when the text of one changes
    values = get!(() -> answers(texts), e.flows, (:answers, texts))
    ncols = maximum(length, cells)
    typing(r, c) = caret !== nothing && caret[1] == rows[r] && c <= length(cells[r]) && within(cells[r][c], caret[2])
    # What the cell in row `r`, column `c` shows. With `on`, it's the cell with the caret.
    shows(r, c, on) = begin
      c <= length(cells[r]) || return Piece[]
      i, cell, v = rows[r], cells[r][c], values[r][c]
      # The cell with the caret shows the spaces typed after its text
      upto = on ? max(cell.hi, caret[2]) : cell.hi
      isformula(texts[r][c]) || return cellpieces(e, i, b.lines[i], cell.lo, upto, base, on)
      # A formula shows what it comes to. With the caret in its cell, it shows the formula, and each cell that it names is a chip.
      on && return exprpieces(b.lines[i], cell.lo, upto, cellnames(length(rows), ncols), base)
      [piece(v.failed ? "!" : v.text, cell.lo, base, atomic=true, n=cell.hi - cell.lo)]
    end
    # The columns are as wide as they are with no caret in a cell, so a column keeps its width
    # while you edit one of its cells. A formula that's wider than its column wraps.
    resting = [[shows(r, c, false) for c in 1:ncols] for r in eachindex(rows)]
    parts = [[typing(r, c) ? shows(r, c, true) : resting[r][c] for c in 1:ncols] for r in eachindex(rows)]
    # Each column gets room in proportion to its longest cell, as in a table
    natural = [clamp(maximum(row -> sum(wide, row[c], init=0px), resting, init=0px) + 2CELL_X, 60px, e.width * 0.75) for c in 1:ncols]
    gutter = max(measure(Face(base, family=SANS, size=base.size * 0.72), string(length(rows))) + 14px, base.size * 1.9)
    space = e.width - gutter - 1px * (ncols + 2)
    # When the columns don't all fit, text wraps before a number is cut short: each column keeps
    # the room its longest word or number needs, and the columns share what's left
    least = [min(natural[c], max(maximum(row -> maximum(unbroken, row[c], init=0px), resting, init=0px) + 2CELL_X, 36px)) for c in 1:ncols]
    widths = sum(natural) <= space ? natural .* (num(space) / num(sum(natural))) :
             sum(least) >= space ? least .* (num(space) / num(sum(least))) :
             least .+ (natural .- least) .* (num(space - sum(least)) / num(sum(natural .- least)))
    flows = [[align(wrap(row[c], widths[c] - 2CELL_X; lh, size=base.size, left=CELL_X), widths[c] - 2CELL_X,
                    # A number stays on the right while you type it. A formula is on the left while its cell shows it.
                    c <= length(cells[r]) && values[r][c].number && !(typing(r, c) && isformula(texts[r][c])) ? :right : :left)
              for c in 1:ncols] for (r, row) in enumerate(parts)]
    heights = [maximum(tall, row) + 2SPREAD_Y for row in flows]
    Grid(rows, widths, heights, cells, flows, lh + 1px, gutter + 1px, values)
  end
  # What inline code made can change its size, so a spreadsheet with some in it is laid out again each time
  any(text -> occursin(INLINE, text), @view b.lines[from:to]) && return build()
  get!(build, e.flows, (:spread, from, b.lines[from:to], caret))
end

"A spreadsheet as nodes: the grid of a table, with a row of letters over it and a column of numbers on its left"
spreadsheet(e::Editor, it::Item, g::Grid) = begin
  b = e.buf
  line = border(1px, :solid, colours.line; between=true)
  size = body(e).size * 0.94
  at = alone(b, b.caret[1]) ? gridcell(g, b.caret) : nothing
  # The letter and the number of the caret's cell are darker
  name(text, on) = Box(height(grow=grow), Alignment.Center, justify=Alignment.Center,
                       label(text, size * 0.72, color=on ? colours.ink : colours.dim, weight=on ? "Semibold" : ""))
  cell(r, c) = begin
    v = c <= length(g.values[r]) ? g.values[r][c] : nothing
    # A formula that went wrong shows a !, which says what went wrong while the mouse is over it
    (v !== nothing && v.failed && at != (r, c)) || return rows(g.flows[r][c])
    [Box(padding(CELL_X, 0px), own!(node!(Document, e, :document), Trouble(message=v.text, size=size * 0.9)))]
  end
  head = Row(width(grow=grow), height(g.head - 1px), Alignment.Start, line[:between], background(colours.head),
    Box(fixed(g.left - 1px), height(grow=grow)),
    [Box(fixed(g.widths[c]), height(grow=grow), name(letters(c), at !== nothing && at[2] == c)) for c in eachindex(g.widths)]...)
  body_rows = [Row(width(grow=grow), height(g.heights[r]), Alignment.Start, line[:between], background(colours.bg),
                 Box(fixed(g.left - 1px), height(grow=grow), background(colours.head), name(string(r), at !== nothing && at[1] == r)),
                 [Column(fixed(g.widths[c]), height(grow=grow), Alignment.Start, justify=Alignment.Center, cell(r, c)...)
                  for c in eachindex(g.widths)]...)
               for r in eachindex(g.rows)]
  Box(width(grow=grow), padding(0px, TABLE_GAP),
    Column(width(grow=grow), Alignment.Start, line, name="Spreadsheet", head, body_rows...))
end

"Draw a line around the cell in row `r`, column `c` of a spreadsheet whose item has its top left corner at (x, y)"
ring(ctx, g::Grid, (r, c), x, y) =
  rectangle(ctx, x + g.left + 1px * c + sum(g.widths[1:c-1], init=0px) - 0.5px,
            y + TABLE_GAP + g.head + 1px * r + sum(g.heights[1:r-1], init=0px) - 0.5px,
            g.widths[c] + 1px, g.heights[r] + 1px, stroke=colours.accent, border=1.5px)

"""
Add or remove a row or a column of the spreadsheet the caret is in, at the
caret. Each formula still names the same cells after it: a cell that moved has
a new name, so the formula is written with that name.
"""
spreadop!(e, action::Symbol) = begin
  b = e.buf
  i = b.caret[1]
  inspread(b, i) || return
  s, t = spread(b, i)
  rows = map(spreadtexts, b.lines[s+1:t-1])
  n = maximum(length, rows)
  rows = [[row; fill("", n - length(row))] for row in rows]
  r = i - s                                           # the caret's row
  c = nearest(spreadcells(b.lines[i]), b.caret[2])    # and its column
  if action == :addrow
    r += 1
    rows = [moved.(row, 1, row=r) for row in rows]
    insert!(rows, r, fill("", n))
  elseif action == :delrow
    length(rows) == 1 && return
    deleteat!(rows, r)
    rows = [moved.(row, -1, row=r + 1) for row in rows]
    r = min(r, length(rows))
  elseif action == :addcol
    c += 1
    rows = [moved.(row, 1, col=c) for row in rows]
    foreach(row -> insert!(row, c, ""), rows)
  elseif action == :delcol
    n == 1 && return
    foreach(row -> deleteat!(row, c), rows)
    rows = [moved.(row, -1, col=c + 1) for row in rows]
    c = min(c, n - 1)
  else
    return
  end
  edit!(b, (s + 1, 0), line_end(b, t - 1), join(map(tableline, rows), "\n"))
  b.caret = b.anchor = (s + r, spreadcells(b.lines[s+r])[c].hi)
  touch!(e)
end

"Backspace in an empty row of a spreadsheet removes the row, and the last row takes the spreadsheet with it"
droprow!(e) = begin
  b = e.buf
  i = b.caret[1]
  s, t = spread(b, i)
  t - s == 2 && return (edit!(b, (s, 0), line_end(b, t), ""); touch!(e))
  spreadop!(e, :delrow)
  above = max(i - 1, s + 1)
  b.caret = b.anchor = (above, spreadcells(b.lines[above])[end].hi)
  touch!(e)
end

# --- sheets ----------------------------------------------------------------------------
#
# A code block in the language `sheet` is drawn as a sheet, like the one in
# Centient's notepad. Each line of the block is a row: a name, an = and a Julia
# expression. The expression can use the names of the rows above it the way
# they're written, and those names show as chips. What each row comes to shows
# on its right. A row without a name shows its number instead.
#
# The caret moves from cell to cell, as it does in a table. Tab and shift-Tab
# go to the next and the last cell, and Return starts a row. Hold ⌥ and click
# the sheet to see it as lines of code.

const SHEET_GAP = 8px   # above and below a sheet
const SHEET_X = 10px    # beside the text of a cell
const SHEET_Y = 4px     # above the first row and below the last
const RAISE = 0.28      # of the size of the text: how far a character from the spare font goes up, twice over
const RESULT_X = 8px    # beside the text of what a row comes to

# A sheet's text is in Source Code Pro ExtraLight, a step lighter than
# Centient's Light. A Mac without that font gets the font of the code blocks.
const SHEET_FILE = something(findfirst(isfile, joinpath.((joinpath(homedir(), "Library/Fonts"), "/Library/Fonts"),
                                                         "SourceCodePro-ExtraLight.ttf")) |>
                             i -> i === nothing ? nothing : joinpath((joinpath(homedir(), "Library/Fonts"), "/Library/Fonts")[i],
                                                                     "SourceCodePro-ExtraLight.ttf"), "")
const SHEET_FONT = isempty(SHEET_FILE) ? MONO : "Source Code Pro"
const SHEET_WEIGHT = isempty(SHEET_FILE) ? "" : "ExtraLight"

"""
Read the sheet's font from its file. A request for a weight of this font by
name can come back in another weight, so the file is read itself. This runs each time an
editor is made, because a built app forgets its fonts when it starts.
"""
load_sheet_font() = isempty(SHEET_FILE) || register_font(SHEET_FILE)

"A sheet laid out"
struct Sheet
  rows::Vector{Int}             # the line of the document each row comes from
  cells::Vector{Vector{Cell}}   # each row's name and expression, or only its expression
  names::Vector{Flow}
  exprs::Vector{Flow}
  results::Vector{Result}       # what each row comes to
  heights::Vector{px}
  name_w::px                    # how wide the column of names is
  size::px                      # of the text
end

"""
The lines that open and close the sheet that line `i` is in, or nothing. A
sheet needs a row, and it shows as lines of code while the caret is on the
line that opens or closes it.
"""
sheet(b::Buffer, i::Int) = drawn(b, i, SHEET)

"The lines that open and close the code block in the language `lang` that line `i` is in, when the block is drawn as a sheet or a spreadsheet"
drawn(b::Buffer, i::Int, lang::String) = begin
  ks = kinds(b)
  (ks[i].kind == Kind.fence || (ks[i].kind == Kind.code && ks[i].lang == lang)) || return nothing
  s, t = codeblock(b, i)
  (t > s + 1 && ks[s].kind == Kind.fence && ks[s].lang == lang && ks[t].kind == Kind.fence && ks[t].level == 1) || return nothing
  israw(b, s) || israw(b, t) ? nothing : (s, t)
end

"True when line `i` is a row of a sheet"
insheet(b::Buffer, i::Int) = begin
  run = sheet(b, i)
  run !== nothing && run[1] < i < run[2]
end

"""
The runs of text in the expression that is columns `lo` to `hi` of `text`. Each
of `names` is a chip, and a * that multiplies shows as ×.
"""
exprpieces(text::String, lo::Int, hi::Int, names, base::Face) = begin
  expr = rest(head(text, hi), lo)
  chars = collect(expr)
  faces = fill(base, length(chars))
  times = [c == '*' for c in chars]
  for t in tokens(expr, "julia")
    t.kind == :plain && continue
    span = t.col+1:t.col+length(t.text)
    faces[span] .= Ref(Face(base, color=getfield(colours, t.kind)))
    # A * in a string or a comment is only a *
    t.kind in (:string, :comment) && (times[span] .= false)
  end
  for (a, z, _) in uses(expr, names)
    faces[a+1:z] .= Ref(Face(base, chip=true))
  end
  out = Piece[]
  i = 1
  while i <= length(chars)
    if times[i]
      push!(out, piece("×", lo + i - 1, faces[i], atomic=true, n=1))
      i += 1
      continue
    end
    j = i
    while j < length(chars) && faces[j+1] === faces[i] && !times[j+1]; j += 1 end
    push!(out, piece(String(chars[i:j]), lo + i - 1, faces[i]))
    i = j + 1
  end
  out
end

"How wide the chip that shows `r` is. A row that went wrong shows a !."
chip_w(face::Face, r::Result) =
  isempty(r.text) ? 0px : r.failed ? measure(face, "!") + 2RESULT_X : sum(measure(f, t) for (t, f) in runs(r.text, face)) + 2RESULT_X

const drawable = Dict{Tuple{String,String,Char},Bool}()

"True when the font of `face` has a letter shape for `c`"
has(face::Face, c::Char) =
  get!(drawable, (face.family, face.style, c)) do
    Skia.sk_font_unichar_to_glyph(skia_font(face.family, face.size, face.style).raw, Int32(c)) != 0
  end

const stand_ins = Dict{Char,String}()

"""
The name of a font on this Mac that has the character `c`, or "" when none
has. macOS picks it, as it does for the text of an app: Menlo when Menlo has
the character, and if not a font of symbols, of another script or of emoji.
"""
font_with(c::Char) = get!(stand_ins, c) do
  style = Skia.sk_fontstyle_new(Int32(400), Int32(Skia.SK_FONT_STYLE_WIDTH_NORMAL), Skia.SK_FONT_STYLE_SLANT_UPRIGHT)
  found = Skia.sk_fontmgr_match_family_style_character(Skia.sk_fontmgr_ref_default(), MONO, style, C_NULL, Int32(0), Int32(c))
  Skia.sk_fontstyle_delete(style)
  found == C_NULL && return ""
  name = Skia.sk_typeface_get_family_name(found)
  family = unsafe_string(Skia.sk_string_get_c_str(name))
  Skia.sk_string_delete(name)
  # The font is asked for by its name from here on, so it has to answer to that name
  has(Face(family, "", 12px, colours.ink, false), c) ? family : ""
end

"""
`text` in runs, each with the face to draw it in. A character that the font of
`face` doesn't have is in a font that has it: Menlo for the raised minus of
m⁻¹, a font of symbols for the ⋮ in a big matrix, and so on.
"""
runs(text::AbstractString, face::Face) = begin
  out = Tuple{String,Face}[]
  for c in text
    family = isascii(c) || has(face, c) ? face.family : font_with(c)
    f = family == face.family || isempty(family) ? face : Face(face, family=family, style="")
    if !isempty(out) && last(out)[2] === f
      out[end] = (last(out)[1] * c, f)
    else
      push!(out, (string(c), f))
    end
  end
  out
end

"True when the font of `face` has every character of `text`"
hasall(face::Face, text::AbstractString) = all(c -> isascii(c) || has(face, c), text)

"""
The pieces `ps` of a line, with each character that the code font lacks in a
piece of its own, in a font that has it. A `code` chip stays one piece, and
draws those characters itself.
"""
spare(ps::Vector{Piece}) = begin
  whole(p) = p.face.family != codefont() || p.face.chip || p.atomic || p.node !== nothing || hasall(p.face, p.text)
  all(whole, ps) && return ps
  out = Piece[]
  for p in ps
    whole(p) && (push!(out, p); continue)
    col = p.col
    for (part, f) in runs(p.text, p.face)
      push!(out, Piece(part, col, length(part), f, false, p.link, nothing))
      col += length(part)
    end
  end
  out
end

"`text` in the face `f`, as the parts of a row. A character that the font lacks is in a font that has it."
spared(text::AbstractString, f::Face) =
  [Box(fixed(measure(pf, part)), Alignment.Start,
     Text(part, size=pf.size, family=pf.family, subfamily=pf.style, color=pf.color, wrap=WrapMode.none)) for (part, pf) in runs(text, f)]

"Lay out the sheet whose code block opens on line `from` and closes on line `to`"
sheetgrid(e, from::Int, to::Int) = begin
  b = e.buf
  caret = from < b.caret[1] < to && b.caret[1] == b.anchor[1] ? b.caret : nothing
  # The layout holds the number of each row's line, so it's kept for these lines only
  get!(e.flows, (:sheet, from, b.lines[from+1:to-1], caret)) do
    size = body(e).size * 0.86
    lh = size * 1.7
    ink = Face(SHEET_FONT, SHEET_WEIGHT, size, colours.ink, false)
    rows = collect(from+1:to-1)
    cells = [sheetcells(b.lines[i]) for i in rows]
    texts = [parts(b.lines[i]) for i in rows]
    # The rows are only worked out again when the text of one changes
    results = get!(() -> tally(texts), e.flows, (:sheetrun, texts))
    # The cell with the caret shows the spaces typed after its text
    upto(i, c) = caret !== nothing && caret[1] == i && within(c, caret[2]) ? max(c.hi, caret[2]) : c.hi
    names = map(zip(rows, cells)) do (i, cs)
      length(cs) == 2 || return Piece[]
      text = rest(head(b.lines[i], upto(i, cs[1])), cs[1].lo)
      isempty(text) ? Piece[] : [piece(text, cs[1].lo, ink)]
    end
    name_w = clamp(maximum(ps -> sum(p -> measure(p.face, p.text), ps, init=0px), names, init=0px) + 2px, 3size, e.width * 0.4)
    # An expression has the room that its row's name and result leave it
    room = e.width - 3px - 4SHEET_X - name_w
    exprs = map(enumerate(rows)) do (r, i)
      c = cells[r][end]
      chip = chip_w(ink, results[r])
      wrap(exprpieces(b.lines[i], c.lo, upto(i, c), known(texts, r), ink), max(80px, room - chip - (chip > 0px ? SHEET_X : 0px)); lh, size)
    end
    nameflows = [wrap(ps, name_w; lh, size) for ps in names]
    heights = [max(tall(n), tall(x)) for (n, x) in zip(nameflows, exprs)]
    Sheet(rows, cells, nameflows, exprs, results, heights, name_w, size)
  end
end

tall(s::Sheet) = sum(s.heights) + 2px + 2SHEET_Y + 2SHEET_GAP

"How far the top of row `r` is from the top of the sheet's item"
row_top(s::Sheet, r::Int) = SHEET_GAP + 1px + SHEET_Y + sum(s.heights[1:r-1], init=0px)

"How far the text of an expression starts from the left of the sheet"
expr_x(s::Sheet) = 2px + 3SHEET_X + s.name_w

"The layout of cell `k` of row `r`, and how far its text starts from the left of the sheet"
cellflow(s::Sheet, r::Int, k::Int) =
  length(s.cells[r]) == 2 && k == 1 ? (s.names[r], 1px + SHEET_X) : (s.exprs[r], expr_x(s))

"Which cell of row `r` is under a point `x` from the left of the sheet"
cellunder(s::Sheet, r::Int, x::px) = length(s.cells[r]) == 2 && x < expr_x(s) - SHEET_X ? 1 : length(s.cells[r])

"The row of the sheet under a point `y` from the top of its item"
rowunder(s::Sheet, y::px) = something(findfirst(r -> y < row_top(s, r) + s.heights[r], eachindex(s.rows)), length(s.rows))

"The place in row `r` nearest to `x`, on the first line of the row's cell, or on its last when `by` is -1"
place(s::Sheet, r::Int, by::Int, x::px) = begin
  k = cellunder(s, r, x)
  f, dx = cellflow(s, r, k)
  (s.rows[r], cellcol(f, by < 0 ? length(f.lines) : 1, x - dx, s.cells[r][k]))
end

"Where the caret goes when ↑ or ↓ brings it into a sheet from the line above or below it"
enter(e, it::Item, s::Sheet, by::Int, x::px) = place(s, by > 0 ? 1 : length(s.rows), by, x)

"""
One run of text of a sheet, in a box as tall as the line with the text in the
middle of it. A name of another row is a chip with round ends.
"""
sheetseg(seg::Seg, lh::px) = begin
  f = seg.face
  t = Text(seg.text, size=f.size, family=f.family, subfamily=f.style, color=f.color, wrap=WrapMode.none)
  f.chip || return Box(fixed(seg.w), height(lh), Alignment.Center, t)
  h = f.size * 1.45
  Box(fixed(seg.w), height(lh), Alignment.Center,
    Box(fixed(seg.w), height(h), padding(CHIP_X, 0px), radius(h / 2), background(colours.chip), border(1px, :solid, colours.chip_line), t))
end

sheetlines(f::Flow) =
  [Row(width(grow=grow), height(f.lh), Alignment.Center, padding(0px, 0px, 0px, vl.x), clip=true,
       [sheetseg(seg, f.lh) for seg in vl.segs]...) for vl in f.lines]

describe(e::Editor, it::Item, s::Sheet) = begin
  b = e.buf
  lh = s.size * 1.7
  n = length(s.rows)
  bare(f) = isempty(f.lines[1].segs)
  hint(text) = Row(height(lh), Text(text, size=s.size, family=SHEET_FONT, subfamily=SHEET_WEIGHT, color=colours.faint, wrap=WrapMode.none))
  rows = map(1:n) do r
    above, below = (r == 1 ? SHEET_Y : 0px), (r == n ? SHEET_Y : 0px)
    pad = padding(above, SHEET_X, below, SHEET_X)
    # The caret is in this row's expression
    typing = b.caret[1] == b.anchor[1] == s.rows[r] && nearest(s.cells[r], b.caret[2]) == length(s.cells[r])
    res = s.results[r]
    w = chip_w(Face(SHEET_FONT, SHEET_WEIGHT, s.size, colours.ink, false), res)
    chip = isempty(res.text) ? () :
      (Column(fixed(w + SHEET_X), height(grow=grow), Alignment.Start, padding(above + 1px, SHEET_X, 0px, 0px),
         res.failed ? own!(node!(Document, e, :document), Trouble(message=res.text, size=s.size)) :
           Row(fixed(w), height(lh - 2px), Alignment.Center, padding(RESULT_X, 0px), radius(6px), background(colours.chip),
             # Menlo's raised signs sit lower than Source Code Pro's raised digits, so they go up a little
             [Box(padding(0px, 0px, f.family == SHEET_FONT ? 0px : s.size * RAISE, 0px),
                Text(t, size=s.size, family=f.family, subfamily=f.style, color=colours.ink, wrap=WrapMode.none))
              for (t, f) in runs(res.text, Face(SHEET_FONT, SHEET_WEIGHT, s.size, colours.ink, false))]...)),)
    Row(width(grow=grow), height(s.heights[r] + above + below), Alignment.Start,
      # A row without a name shows its number
      Column(fixed(s.name_w + 2SHEET_X + 1px), height(grow=grow), Alignment.Start, pad, border(1px, :solid, colours.line)[:right],
        (bare(s.names[r]) ? (hint(string(r)),) : sheetlines(s.names[r]))...),
      Column(width(grow=grow), height(grow=grow), Alignment.Start, pad,
        (bare(s.exprs[r]) && typing ? (hint("expression"),) : sheetlines(s.exprs[r]))...),
      chip...)
  end
  Box(width(grow=grow), padding(0px, SHEET_GAP),
    Column(width(grow=grow), Alignment.Start, radius(6px), background(colours.float), border(1px, :solid, colours.line), name="Sheet",
      rows...))
end

describe(t::Trouble) = begin
  w = measure(Face(SHEET_FONT, SHEET_WEIGHT, t.size, colours.accent, false), "!") + 2RESULT_X
  Box(fixed(w), height(t.size * 1.7 - 2px), padding(RESULT_X, 0px), radius(6px), background(colours.chip),
    Text("!", size=t.size, family=MONO, subfamily="Bold", color=colours.accent, wrap=WrapMode.none))
end

draw(ctx, size, ui::ConcreteRect, t::Trouble) = (t.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(t::Trouble, ev::MouseMove) =
  show_tooltip!(ev.window, tip_label(t.message), t.rect..., placement=:bottom, gap=6px)

"""
The boxes that cover the selected part of a sheet whose top left corner is at
(x, y). A selection that covers several lines takes each row whole.
"""
marks(e, it::Item, s::Sheet, x, y) = begin
  b = e.buf
  out = Rect[]
  selecting(b) || return out
  lo, hi = selection(b)
  if b.caret[1] != b.anchor[1]
    n = length(s.rows)
    bottom = y + it.tall - SHEET_GAP
    lo[1] <= it.first && hi[1] >= it.first && push!(out, (num(x), num(y), num(x + 7px), num(y + SHEET_GAP)))
    for (r, i) in enumerate(s.rows)
      lo[1] <= i <= hi[1] || continue
      top = r == 1 ? y + SHEET_GAP : y + row_top(s, r)
      push!(out, (num(x), num(top), num(x + item_room(e, it)[2]), num(r == n ? bottom : y + row_top(s, r + 1))))
    end
    lo[1] <= it.last && hi[1] >= it.last && push!(out, (num(x), num(bottom), num(x + 7px), num(y + it.tall)))
    return out
  end
  r = findfirst(==(b.caret[1]), s.rows)
  r === nothing && return out
  sel = selected(b, s.rows[r])
  for (k, cell) in enumerate(s.cells[r])
    (sel[1] < cell.limit && sel[2] > cell.lo) || continue
    f, dx = cellflow(s, r, k)
    append!(out, marks(f, x + dx, y + row_top(s, r), (max(sel[1], cell.lo), min(sel[2], cell.limit), false), margin=false))
  end
  out
end

"Draw the caret in the cell of a sheet that it's in. The sheet's top left corner is at (x, y)."
caret(ctx, e, s::Sheet, x, y) = begin
  p = e.buf.caret
  r = findfirst(==(p[1]), s.rows)
  r === nothing && return
  f, dx = cellflow(s, r, nearest(s.cells[r], p[2]))
  caret(ctx, e, f, x + dx, y + row_top(s, r), p[2])
end

"The place in a sheet under a point that is (dx, dy) from the top left of its item"
locate(e, it::Item, s::Sheet, dx, dy) = begin
  r = rowunder(s, dy)
  k = cellunder(s, r, dx)
  f, x = cellflow(s, r, k)
  line = clamp(floor(Int, num(dy - row_top(s, r)) / num(f.lh)) + 1, 1, length(f.lines))
  (s.rows[r], cellcol(f, line, dx - x, s.cells[r][k]))
end

"""
A click on a sheet. It returns true when it has put the caret somewhere itself.
With ⌥ held, the sheet shows as lines of code. A click where a row's name goes
gives a row that has no name a place for one.
"""
press!(e, it::Item, s::Sheet, pos) = begin
  b = e.buf
  if held(e, Keys.opt)
    b.caret = b.anchor = line_end(b, it.first)
    return true
  end
  r = rowunder(s, pos[2] - e.origin[2] - it.top)
  (length(s.cells[r]) == 1 && pos[1] - e.origin[1] - item_room(e, it)[1] < expr_x(s) - SHEET_X) || return false
  name_row!(e, s.rows[r])
  true
end

"Give the row on line `i`, which has no name, a place for one, and put the caret there"
name_row!(e, i::Int) = begin
  b = e.buf
  edit!(b, (i, 0), (i, 0), " = ")
  b.caret = b.anchor = (i, 0)
  e.clicked = (time(), (i, 0), 1)
  touch!(e)
end

"""
Where the caret goes when it's sent to `p` in the sheet that runs from line `s`
to line `t`. See `settle` for a table. A spreadsheet works the same way, with
`cells` to read the cells of a row.
"""
settle(b::Buffer, (s, t)::Tuple{Int,Int}, p::Pos, by::Int, cells=sheetcells) = begin
  i, col = p
  first_cell(i) = (i, cells(b.lines[i])[1].lo)
  last_cell(i) = (i, cells(b.lines[i])[end].hi)
  # The lines that open and close the sheet don't show, so the caret steps over them
  i == s && return by < 0 && s > 1 ? line_end(b, s - 1) : first_cell(s + 1)
  i == t && return by > 0 && t < length(b.lines) ? (t + 1, 0) : last_cell(t - 1)
  cs = cells(b.lines[i])
  any(c -> within(c, col), cs) && return p
  if by < 0
    c = findlast(c -> c.limit < col, cs)
    c === nothing || return (i, cs[c].hi)
    i - 1 > s ? last_cell(i - 1) : s > 1 ? line_end(b, s - 1) : first_cell(i)
  elseif by > 0
    c = findfirst(c -> c.lo > col, cs)
    c === nothing || return (i, cs[c].lo)
    i + 1 < t ? first_cell(i + 1) : t < length(b.lines) ? (t + 1, 0) : last_cell(i)
  else
    c = cs[nearest(cs, col)]
    (i, clamp(col, c.lo, c.limit))
  end
end

"The place one line up or down from the caret, which is in a sheet"
vertical(e, it::Item, s::Sheet, by::Int) = begin
  b = e.buf
  # The caret can be on the line that opens or closes the sheet, at the end of a selection
  r = something(findfirst(==(b.caret[1]), s.rows), b.caret[1] <= it.first ? 1 : length(s.rows))
  k = nearest(s.cells[r], b.caret[2])
  f, dx = cellflow(s, r, k)
  line, x = spot(f, b.caret[2])
  x = e.goal = something(e.goal, x + dx)
  1 <= line + by <= length(f.lines) && return (b.caret[1], cellcol(f, line + by, x - dx, s.cells[r][k]))
  r += by
  1 <= r <= length(s.rows) && return place(s, r, by, x)
  if by < 0
    it.first == 1 && return b.caret
    f = flow(e, it.first - 1, b.plain)
    return (it.first - 1, colat(f, length(f.lines), x))
  end
  # ↓ on the last row of a sheet at the end of the document starts a line below it
  it.last == length(b.lines) && edit!(b, line_end(b, it.last), line_end(b, it.last), "\n")
  (it.last + 1, colat(flow(e, it.last + 1, e.buf.plain), 1, x))
end

"Return in a sheet starts a row under the caret's row. In a last row that's empty, it ends the sheet instead."
next_row!(e) = begin
  b = e.buf
  i = b.caret[1]
  s, t = sheet(b, i)
  if i == t - 1 && t - s > 2 && all(isempty, parts(b.lines[i]))
    edit!(b, line_end(b, i - 1), line_end(b, t), "\n" * b.lines[t] * "\n")
    b.caret = b.anchor = (t, 0)
    return touch!(e)
  end
  edit!(b, line_end(b, i), line_end(b, i), "\n = ")
  b.caret = b.anchor = (i + 1, 0)
  touch!(e)
end

"""
Tab in a sheet goes to the next cell and selects what's in it, or with `back`
to the one before. Going on from the last cell adds a row, and going back from
an expression that has no name makes a place for one.
"""
sheet_tab!(e, back::Bool) = begin
  b = e.buf
  i, col = b.caret
  s, t = sheet(b, i)
  cs = sheetcells(b.lines[i])
  k = nearest(cs, col)
  pick(i, c) = begin
    b.anchor, b.caret = (i, c.lo), (i, c.hi)
    touch!(e)
  end
  if back
    length(cs) == 1 && return name_row!(e, i)
    k == 2 && return pick(i, cs[1])
    return i - 1 > s ? pick(i - 1, sheetcells(b.lines[i-1])[end]) : nothing
  end
  k < length(cs) && return pick(i, cs[2])
  i + 1 < t && return pick(i + 1, sheetcells(b.lines[i+1])[1])
  edit!(b, line_end(b, i), line_end(b, i), "\n = ")
  b.caret = b.anchor = (i + 1, 0)
  touch!(e)
end

"""
Backspace in a sheet, when it does more than delete a character. In a row
that's empty it takes the row away, and the last row takes the sheet with it.
At the start of an expression it goes back to the row's name. It returns true
when it did one of these.
"""
erase_row!(e, to::Pos) = begin
  b = e.buf
  i, col = b.caret
  to < b.caret || return false
  s, t = sheet(b, i)
  cs = sheetcells(b.lines[i])
  if all(isempty, parts(b.lines[i]))
    if t - s == 2
      edit!(b, (s, 0), line_end(b, t), "")
    elseif i - 1 > s
      edit!(b, line_end(b, i - 1), line_end(b, i), "")
    else
      edit!(b, (i, 0), (i + 1, 0), "")
      b.caret = b.anchor = settle(b, (i, 0), 1)
    end
    touch!(e)
    return true
  end
  (length(cs) == 2 && col == cs[2].lo && nearest(cs, col) == 2) || return false
  b.caret = b.anchor = (i, cs[1].hi)
  touch!(e)
  true
end

# --- the names a sheet offers ----------------------------------------------------------
#
# While you type a name in an expression of a sheet, a list under the caret
# shows the names of the rows above that start the same way. ↑ and ↓ choose
# one, Return or Tab types the rest of it, and esc hides the list.

isnamechar(c::Char) = isletter(c) || isdigit(c) || c == '_'

"""
The names that the text before the caret could be the start of: the line, the
column where the name starts, and the names. Nothing when the caret isn't in an
expression of a sheet, or no name fits. A name fits when it starts with what's
typed, or when one of its words does.
"""
offered(e) = begin
  b = e.buf
  i, col = b.caret
  selecting(b) && return nothing
  insheet(b, i) || return code_offered(e)   # a code block offers names too
  cs = sheetcells(b.lines[i])
  c = cs[end]
  (c.lo <= col <= c.limit && nearest(cs, col) == length(cs)) || return nothing
  s, _ = sheet(b, i)
  rows = [parts(b.lines[j]) for j in s+1:i-1]
  names = known(rows, length(rows) + 1)
  isempty(names) && return nothing
  chars = collect(b.lines[i])
  # In the middle of a word, nothing is offered
  col < length(chars) && isnamechar(chars[col+1]) && return nothing
  before = map(lowercase, chars[c.lo+1:col])
  # The longest run of words before the caret that starts a name wins, so "wall l" finds "Wall length"
  for from in max(1, length(before) - 40):length(before)
    (isletter(before[from]) || before[from] == '_') || continue
    from > 1 && isnamechar(before[from-1]) && continue
    typed = String(before[from:end])
    fits(n) = lowercase(n) != typed && (startswith(lowercase(n), typed) || any(w -> startswith(w, typed), split(lowercase(n))))
    found = filter(fits, names)
    isempty(found) || return (i, c.lo + from - 1, found)
    # A whole name is typed already, so its last words aren't the start of another
    any(n -> lowercase(n) == typed, names) && return nothing
  end
  nothing
end

"Which name of the list is chosen, and the list that esc hid. Each is kept with the place its list is for."
suggesting(e) = get!(() -> Ref{Any}((at=(0, 0), chosen=1, hidden=(0, 0))), e.nodes, :suggesting)

"The list of names to show now: the line, the column where the name starts, the names and which one is chosen. Or nothing."
suggestion(e) = begin
  caretless(e.buf) && return nothing
  found = offered(e)
  state = suggesting(e)[]
  # A list that esc hid stays hidden while its name is being typed, and no longer
  if state.hidden != (0, 0) && (found === nothing || state.hidden != (found[1], found[2]))
    state = suggesting(e)[] = (at=state.at, chosen=state.chosen, hidden=(0, 0))
  end
  found === nothing && return nothing
  i, start, names = found
  state.hidden == (i, start) && return nothing
  (i, start, names, state.at == (i, start) ? clamp(state.chosen, 1, length(names)) : 1)
end

"What a key does while the list of names shows. It returns true when the key was for the list."
suggest_key!(e, K) = begin
  found = suggestion(e)
  found === nothing && return false
  i, start, names, chosen = found
  state = suggesting(e)
  if K == Keys.down || K == Keys.up
    state[] = (at=(i, start), chosen=mod1(chosen + (K == Keys.down ? 1 : -1), length(names)), hidden=(0, 0))
  elseif K == Keys.enter || K == Keys.tab
    edit!(e.buf, (i, start), e.buf.caret, names[chosen])
  elseif K == Keys.escape
    state[] = (at=(0, 0), chosen=1, hidden=(i, start))
  else
    return false
  end
  touch!(e)
  true
end

"The list of names, placed in the window under the name being typed. Nothing when there's no list to show."
suggestbox(e) = begin
  found = suggestion(e)
  found === nothing && return ()
  i, start, names, chosen = found
  it = item(e, i)
  s = it.content
  # Where the name starts, from the left of the page's text and from the top of the item, and the font of the list
  if s isa Sheet
    r = findfirst(==(i), s.rows)
    r === nothing && return ()
    f, dx = cellflow(s, r, length(s.cells[r]))
    k, x = spot(f, start)
    face = Face(SHEET_FONT, SHEET_WEIGHT, s.size, colours.ink, false)
    across, down = item_room(e, it)[1] + dx + x, row_top(s, r) + f.lh * k
  elseif s isa Flow
    # In a code block, the list is under the line of the screen that the name is on
    k, x = spot(s, start)
    face = Face(codefont(), codestyle(), s.size, colours.ink, false)
    across, down = x, line_top(s, k) + s.lines[k].high
  else
    return ()
  end
  # In Julia code, each name has what it is at the right of its row, in a paler colour
  notes = s isa Flow ? name_notes(e, i, names) : fill("", length(names))
  pale = Face(face, color=colours.dim)
  span(note) = sum(((part, f),) -> measure(f, part), runs(note, pale), init=0px)
  needs(n, note) = measure(face, n) + (isempty(note) ? 0px : NOTE_GAP + span(note))
  wide = max(150px, maximum(map(needs, names, notes)) + 26px)
  list = Column(fixed(wide), Alignment.Start, padding(4px), radius(7px), background(colours.float), border(1px, :solid, colours.line), lifted,
    name="Names",
    [Row(width(grow=grow), height(face.size * 1.8), Alignment.Center, padding(8px, 0px), radius(4px),
         background(j == chosen ? colours.active : clear),
       (isempty(note) ? (Text(n, size=face.size, family=face.family, subfamily=face.style, color=colours.ink, wrap=WrapMode.none),) :
        (Box(Text(n, size=face.size, family=face.family, subfamily=face.style, color=colours.ink, wrap=WrapMode.none)),
         Box(width(grow=grow), height(1px)), spared(note, pale)...))...)
     for (j, (n, note)) in enumerate(zip(names, notes))]...)
  # A list that's too wide for the room at its right stays in the window
  left = clamp(text_left(e) + across - 9px, 8px, max(8px, window_size(e)[1] - 8px - wide))
  top = TOPBAR_H + PAGE_TOP + it.top - e.scroll.offset + down + 3px
  top >= TOPBAR_H || return ()
  (Row(width(grow=grow), height(grow=grow), Alignment.Start, padding(top, 0px, 0px, left), list),)
end

# --- the page's layout ---------------------------------------------------------------

# --- live blocks ---------------------------------------------------------------------
#
# A code block in the language `ui` holds Julia code. The page runs it once and
# shows its value where the block is: a UI node from any module, or any other
# value as text. The node is kept, so a node with state keeps it between frames.
#
# The code can use the names that pages use most with no line that loads them:
# UI.jl's components, like Slider and STLViewer, the parts of a layout, like
# Column and px, a file path as fs"notes.md" and a colour as colorant"tomato".

const LIVE = "ui"
const LIVE_GAP = 8px   # above and below what a live block shows

"The modules whose names a live block can use with no line that loads them"
const USUAL = ("github.com/jkroso/UI.jl/Interface/Semantic", "github.com/jkroso/UI.jl/Interface/Geometric")

"Give the module `m` each name that the module at `path` exports"
share!(m, path) = begin
  from = include_string(m, "@use $(repr(path))")
  # The module can be new, so its names are asked for as they are now
  for name in Base.invokelatest(names, from)
    # A menu and a tree each have an Item, so a block loads the one it means
    (name == nameof(from) || name == :Item) && continue
    Core.eval(m, :(const $name = $(Base.invokelatest(getglobal, from, name))))
  end
end

"The module that the live blocks of every document run in"
sandbox(e) = get!(e.nodes, :sandbox) do
  m = Module(:Page)
  # Kip by the module that's loaded here, not by name. A built app can't find a package by name.
  Core.eval(m, :(const Kip = $Kip))
  Core.eval(m, :(using .Kip))
  foreach(path -> share!(m, path), USUAL)
  include_string(m, "@use \"github.com/jkroso/URI.jl/FSPath\" FSPath @fs_str")
  Core.eval(m, :(const $(Symbol("@colorant_str")) = $(var"@colorant_str")))
  # A live block can read and set the page's colours: `page_theme()` gives "Sepia", "Paper" or "Night"
  Core.eval(m, :(const page_theme = $(() -> (reads!(e, :theme); titlecase(string(e.theme))))))
  Core.eval(m, :(const page_theme! = $(name -> theme!(e, Symbol(lowercase(string(name)))))))
  # ... and the size of the page's text, in pixels
  Core.eval(m, :(const page_text_size = $(() -> (reads!(e, :zoom); TEXT_SIZE.value * e.zoom))))
  Core.eval(m, :(const page_text_size! = $(size -> text_size!(e, size))))
  # ... and the font of the page's text, by name
  Core.eval(m, :(const page_font = $(() -> (reads!(e, :font); e.font))))
  Core.eval(m, :(const page_font! = $(name -> font!(e, String(name)))))
  # ... and its weight, by name: `page_weights()` gives the weights that the font has, like "Light" and "Regular",
  # and `page_weight()` the one that the text is drawn in
  Core.eval(m, :(const page_weights = $(() -> (reads!(e, :font); [w.label for w in text_weights(e.font)]))))
  Core.eval(m, :(const page_weight = $(() -> (reads!(e, :font); reads!(e, :weight); nearest_weight(e.font, e.weight).label))))
  Core.eval(m, :(const page_weight! = $(name -> weight!(e, String(name)))))
  # ... and the width of the page, in pixels
  Core.eval(m, :(const page_width = $(() -> e.widest.value)))
  Core.eval(m, :(const page_width! = $(width -> page_width!(e, width))))
  # ... and what the count at the top right counts: `page_count()` gives "Words", "Characters" or "Reading time"
  Core.eval(m, :(const page_count = $(() -> (reads!(e, :stat); STAT_NAMES[findfirst(==(e.stat), STATS)]))))
  Core.eval(m, :(const page_count! = $(name -> stat!(e, STATS[something(findfirst(==(String(name)), STAT_NAMES), 1)]))))
  # ... and whether the page checks its spelling
  Core.eval(m, :(const page_spelling = $(() -> (reads!(e, :spelling); e.spelling))))
  Core.eval(m, :(const page_spelling! = $(on -> spelling!(e, Bool(on)))))
  # ... and whether a page is written to its file when its window stops being the front window
  Core.eval(m, :(const page_autosave = $(() -> (reads!(e, :autosave); e.autosave))))
  Core.eval(m, :(const page_autosave! = $(on -> autosave!(e, Bool(on)))))
  # ... and whether a line of a file of code that's too long for the window goes on under itself
  Core.eval(m, :(const code_wrap = $(() -> (reads!(e, :wrap); e.wrap))))
  Core.eval(m, :(const code_wrap! = $(on -> wrap!(e, Bool(on)))))
  # ... and whether it shows the number of each line, and shades the line that the caret is on
  Core.eval(m, :(const code_numbers = $(() -> (reads!(e, :numbers); e.numbers))))
  Core.eval(m, :(const code_numbers! = $(on -> numbers!(e, Bool(on)))))
  Core.eval(m, :(const code_shade = $(() -> (reads!(e, :shade); e.shade))))
  Core.eval(m, :(const code_shade! = $(on -> shade!(e, Bool(on)))))
  # ... and how many spaces one step of indentation is in code: 2 or 4
  Core.eval(m, :(const code_indent = $(() -> (reads!(e, :indent); e.indent))))
  Core.eval(m, :(const code_indent! = $(n -> indent_width!(e, Int(n)))))
  # ... and how big code is, in pixels. It grows and shrinks with the page's text.
  Core.eval(m, :(const code_text_size = $(() -> (reads!(e, :code_scale); reads!(e, :zoom); code_size(e).value))))
  Core.eval(m, :(const code_text_size! = $(size -> code_size!(e, size))))
  # ... and the font of code, by the name in the list of `code_fonts()`. `code_family(name)` gives the font's own name, to draw the name in.
  Core.eval(m, :(const code_fonts = $(() -> font_label.(unique([code_fonts(); e.code_font])))))
  Core.eval(m, :(const code_family = $(name -> font_family(String(name)))))
  Core.eval(m, :(const code_font = $(() -> (reads!(e, :code_font); font_label(e.code_font)))))
  Core.eval(m, :(const code_font! = $(name -> code_font!(e, font_family(String(name))))))
  # ... and its weight, by name: `code_weights()` gives the weights that the font has, and `code_weight()` the one that code is drawn in
  Core.eval(m, :(const code_weights = $(() -> (reads!(e, :code_font); [w.label for w in text_weights(e.code_font)]))))
  Core.eval(m, :(const code_weight = $(() -> (reads!(e, :code_font); reads!(e, :code_weight); nearest_weight(e.code_font, e.code_weight).label))))
  Core.eval(m, :(const code_weight! = $(name -> code_weight!(e, String(name)))))
  # ... and after how many characters a faint line goes down a file of code. 0 is no line.
  Core.eval(m, :(const code_guide = $(() -> (reads!(e, :guide); e.guide))))
  Core.eval(m, :(const code_guide! = $(n -> guide!(e, Int(n)))))
  # ... and the key bindings. `key_bundles()` gives the names of the bundles, and `key_bundle()` the one that's chosen.
  # `key_list()` shows each command with its keys, and a click on one changes them. `keys_changed()` is true when a
  # command has other keys than the bundle's, and `key_reset!()` gives every command the bundle's keys again.
  Core.eval(m, :(const key_bundles = $(() -> String[first(b) for b in BUNDLES])))
  Core.eval(m, :(const key_bundle = $(() -> (reads!(e, :bundle); e.bundle))))
  Core.eval(m, :(const key_bundle! = $(name -> bundle!(e, String(name)))))
  Core.eval(m, :(const key_list = $(() -> own!(e, KeyList()))))
  Core.eval(m, :(const keys_changed = $(() -> (reads!(e, :bundle); reads!(e, :rebound); !isempty(e.rebound)))))
  Core.eval(m, :(const key_reset! = $(() -> bundle!(e, e.bundle))))
  # ... and the app that opens Markdown files: `markdown_app()` gives its name, like "Ladder", or "" when macOS can't say.
  # `default_app!()` asks macOS to make that app Ladder. It gives false when the Ladder app isn't installed.
  # `app_installed()` is true when the Ladder app is on this Mac.
  Core.eval(m, :(const markdown_app = $(() -> (reads!(e, :app); app_name(markdown_app())))))
  Core.eval(m, :(const app_installed = $(() -> (reads!(e, :app); !isempty(app_path())))))
  Core.eval(m, :(const default_app! = $(() -> default_app!(e))))
  # ... and the app's own updates. `app_updates()` is true when the app gets a newer version without being asked.
  # `update_news()` says how far an update has got. `update_offer()` is what a button can do about it now, like
  # "Check now", or "" for nothing. `update!()` does that.
  Core.eval(m, :(const app_updates = $(() -> (reads!(e, :updates); e.updates))))
  Core.eval(m, :(const app_updates! = $(on -> updates!(e, Bool(on)))))
  Core.eval(m, :(const update_news = $(() -> update_news(e))))
  Core.eval(m, :(const update_offer = $(() -> (reads!(e, :updates); reads!(e, :update); Update.label(Update.own())))))
  Core.eval(m, :(const update! = $(() -> update_act!(e))))
  # ... and the email. `email_form()` shows the fields of the account, with a button that keeps them. `email_news()`
  # says how far the look for new email has got. `email_check!()` looks now, and `email_show!()` shows the inbox.
  # `email_every()` is how many minutes go by between two looks. `email_back()` is how many months back the emails
  # that Ladder gets go, with 0 for every email. `email_rest()` is whether it gets the other folders after the inbox.
  Core.eval(m, :(const email_form = $(() -> node!(MailForm, e, :mail_form))))
  Core.eval(m, :(const email_news = $(() -> mail_news(e))))
  Core.eval(m, :(const email_check! = $(() -> mail_check!(e))))
  Core.eval(m, :(const email_show! = $(() -> mail_show!(e))))
  Core.eval(m, :(const email_every = $(() -> mail_every(e))))
  Core.eval(m, :(const email_every! = $(minutes -> mail_every!(e, minutes))))
  Core.eval(m, :(const email_back = $(() -> mail_back(e))))
  Core.eval(m, :(const email_back! = $(months -> mail_back!(e, months))))
  Core.eval(m, :(const email_rest = $(() -> mail_rest(e))))
  Core.eval(m, :(const email_rest! = $(on -> mail_rest!(e, on))))
  # The units that a sheet has, from Units.jl, so that code can work with lengths, times and so on: 12m * 2.4m.
  # They come in with `using`, so a name that a block makes or loads for itself wins over a unit with that name.
  Core.eval(m, :(const SheetUnits = $(units())))
  Core.eval(m, :(using .SheetUnits))
  m
end

"""
Note that the live block that's running now asked for a setting of the page:
`:theme`, `:zoom`, `:font` or `:stat`. Such a block is run again when the setting changes, so
what it shows stays true.
"""
reads!(e, setting::Symbol) = begin
  key = get(e.nodes, :running, nothing)
  key === nothing || push!(get!(() -> Set{Any}(), e.nodes, (:readers, setting)), key)
  nothing
end

"""
Ask macOS to make Ladder the app that opens Markdown files, for the button on
the settings page. macOS asks you to confirm, so the window then looks for
your answer. It's false when the Ladder app isn't installed.
"""
default_app!(e) = begin
  before = markdown_app()
  make_default!() || return false
  e.nodes[:asked] = (time(), before, time())
  true
end

"Run again the live blocks that asked for `setting`"
rerun!(e, setting::Symbol) = foreach(pop!(e.nodes, (:readers, setting), ())) do key
  # What the block made before is kept until it runs again, so that what it makes then can
  # carry on from it, like a chooser whose choice was clicked sliding to it
  old = pop!(e.nodes, key, nothing)
  old === nothing || (e.nodes[(:replaced, key)] = old)
end

"""
Wrap the page's text again, for a live block that changed a setting. The block
under the mouse stays where it is in the window, so a slider that's being
dragged doesn't move up or down, away from the mouse.
"""
rewrap!(e) = begin
  save_settings!(e)
  empty!(e.flows)
  win = window_of(e)
  if win !== nothing && !isempty(e.layout)
    y = win.mouse[2] - TOPBAR_H - PAGE_TOP + e.scroll.offset
    i = findfirst(it -> it.top <= y < it.top + it.tall, e.layout)
    i === nothing || (e.nodes[:hold] = (e.layout[i].first, e.layout[i].top - e.scroll.offset))
  end
  e
end

"Make the page's text `size` pixels tall, for a live block"
text_size!(e, size) = (e.zoom = zoom_for(size); rewrap!(e))

const NARROWEST, WIDEST = 400, 1200   # the page widths that the settings page offers

"""
Make the page `width` pixels wide, to the nearest ten, for a live block. That's
its width while the text is its usual size: bigger text gets a wider page, so
a line holds as many words as before. A window that's too narrow for the page
shows it as wide as it can.
"""
page_width!(e, width) = (e.widest = px(clamp(10round(Int, width / 10), NARROWEST, WIDEST)); rewrap!(e))

"Draw the page's text in the font called `name`"
font!(e, name::String) = (e.font = name; save_settings!(e); rerun!(e, :font); restyle!(e))

"Draw the page's text in the weight called `w`, like \"Light\", or in the weight `w`, like 300"
weight!(e, w::Union{Integer,AbstractString}) = begin
  e.weight = w isa Integer ? text_weight(w) : weight_called(e.font, w)
  save_settings!(e)
  rerun!(e, :weight)
  restyle!(e)
end

"Use the colours called `name` for the page"
theme!(e, name::Symbol) = begin
  name in THEME_ORDER || error("The page's colours are Sepia, Paper and Night. $name isn't one of them.")
  e.theme = name
  save_settings!(e)
  rerun!(e, :theme)
  restyle!(e)
end

# The errors of the live blocks that failed. The app's self-test reads it, to check its own pages.
const problems = String[]

"""
Run the code of a live block and return a UI node that shows its value, or its
error. `key` is where the editor keeps what the code made. With `inline`, the
code is in a line of text: a value that isn't a node comes back as its text,
with true if the text says what went wrong.
"""
evaluate(e, code::String; key=(:live, e.buf.path, code), inline=false) = begin
  path = e.buf.path
  # The code can load the drawing methods of a node, and the frame that runs it
  # can't call them yet. So the window draws one more frame soon after.
  e.nodes[:ran] = true
  e.nodes[:running] = key
  try
    # Kip finds a path like "./widgets.jl" from the folder of the document, and so does a relative FSPath
    cd(isdir(docdir(e)) ? docdir(e) : pwd()) do
      value = include_string(sandbox(e), code, isempty(path) ? joinpath(e.folder, "untitled.md") : path)
      node = inline ? present_inline(value) : present(value)
      node !== nothing ? node : inline ? (said(value), false) : note(repr("text/plain", value), colours.ink)
    end
  catch err
    err = err isa LoadError ? err.error : err
    push!(problems, sprint(showerror, err))
    # A line of text has room for the first line of what went wrong
    inline ? (said(first(split(sprint(showerror, err), '\n'))), true) : note(sprint(showerror, err), colours.accent)
  finally
    delete!(e.nodes, :running)
  end
end

"""
The node that shows `value` in a live block, or nothing to show it as text. Add
a method to show a type of your own as a node.
"""
present(value) = nothing
present(node::Union{SemanticUI,GeometricUI}) = node
# Text on its own goes in a box as wide as the page, so that it wraps and takes the page's colours
present(text::Text) = Box(width(grow=grow), Alignment.Start, text)
present(p::FSPath) = begin
  path = abspath(string(p))
  path = ispath(path) ? realpath(path) : path
  Breadcrumb(at=length(path) > 1 ? String(rstrip(path, '/')) : path)
end

"""
The node that shows `value` in a line of text, for inline code, or nothing to
show it as text. It's what a live block shows, unless a type has a method here.
"""
present_inline(value) = present(value)
present_inline(text::Text) = Box(Alignment.Start, text)
# A file path in a line of text is as wide as its names. Its list floats under it.
present_inline(p::FSPath) = (l = present(p); l.inline = true; l)

note(text, colour) = Box(width(grow=grow), padding(BLOCK_X, 10px), background(colours.block),
  Text(String(text), size=13px, family=codefont(), subfamily=codestyle(), color=colour))

"""
What a live block shows: the node that its code made. The code can make a
layout with nodes in it, like `Column(Checkbox(), Checkbox())`. Making the
Column describes each Checkbox once, so each frame describes them again, and
a click on a checkbox shows.
"""
@def mutable struct Shown <: SemanticUI
  value::Any = nothing   # a SemanticUI or a GeometricUI
  was::Theme = light     # the theme that the text in a GeometricUI value has now
  inline::Bool = false   # made by inline code, so it's in a line of text and only as wide as what it shows
end

cursor(::Shown) = :arrow

# A drag that starts in a live block is the block's. The page's text doesn't select as the mouse moves.
onmouse(s::Shown, ::MouseMove) = held(s, Keys.mouse_left) ? handled : nothing

# The components in the block get the page's colours
describe(s::Shown) = begin
  e = editor(s)
  t = component_theme(e.zoom)
  was, s.was = s.was, t
  with_theme(t) do
    # A diagram, a model and a video have a button that makes them fill the window. One that fills it leaves its room here empty.
    what = s.inline ? nothing : fill_what(s.value)
    what !== nothing && what[1] == :node && zoomed_node(e, s.value) && return Column(width(grow=grow), Alignment.Start, held_room(e))
    inner = s.value isa SemanticUI ? Base.invokelatest(convert, GeometricUI, s.value) : redescribe!(detach!(s.value), t, was)
    what === nothing || (inner = fillable(s, what, inner, wide=fill_wide(s.value)))
    s.inline ? Row(width(grow=grow), Alignment.Center, inner) : Column(width(grow=grow), Alignment.Start, inner)
  end
end

# What inline code made can float a list over the page, as a file path does. A
# click in that list is the list's, so it stops here, before the page's text sees it.
onkey(s::Shown, ev::KeyPress{Keys.mouse_left}) = begin
  s.inline || return nothing
  r = rect(s)
  x, y = ev.window.mouse
  r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height ? nothing : handled
end

"""
Describe again each semantic node in `geo`, and put the new geometry where the
old geometry was. Text that has the colours of the theme `was` gets the colours of `t`.
"""
redescribe!(geo, t, was) = begin
  child = geo.firstchild
  while child !== nothing
    next = child.nextsibling
    if child isa GeometricUI && child.from isa SemanticUI
      new = Base.invokelatest(convert, GeometricUI, child.from)
      new === child || swap!(child, new)
    elseif child isa GeometricUI
      redescribe!(child, t, was)
    elseif child isa Text
      adopt_theme!(child, t, was)
    end
    child = next
  end
  geo
end

"Put `new` in the place of `old` among its siblings"
swap!(old, new) = begin
  parent, prev, next = old.parent, old.prevsibling, old.nextsibling
  detach!(new)
  setfield!(new, :parent, parent)
  setfield!(new, :prevsibling, prev)
  setfield!(new, :nextsibling, next)
  prev === nothing ? setfield!(parent, :firstchild, new) : setfield!(prev, :nextsibling, new)
  next === nothing || setfield!(next, :prevsibling, new)
  setfield!(old, :parent, nothing)
  setfield!(old, :prevsibling, nothing)
  setfield!(old, :nextsibling, nothing)
  new
end

# --- files in a live block ---------------------------------------------------------------
#
# An FSPath shows as a breadcrumb: the name of each folder on the way to it,
# in a row. Click the last name to list what's in that folder under the
# breadcrumb, and click an earlier name to go to that folder. A click on a
# line of the list makes that file or folder the path, so its name joins the
# breadcrumb. Under a path to a file is a preview of the file:
#
#   - a picture, of any kind that Skia or macOS reads
#   - the model in an STL or 3MF file
#   - a player for a sound or a video file
#   - the pages of a PDF file, one at a time
#   - a CSV file as a table, and the list of the files in a zip
#   - a Markdown file as it reads
#   - the text of any other text file, which the wheel scrolls through. The lines
#     of a file of code have the colours that a code block gives them.
#   - the picture that the Finder shows, for a file like a Word file or a font
#
# A sound or a video plays on while you scroll the page and type in it. It stops
# when the path goes to another file, when the preview closes and when the window
# shows another page.

"One line of the list under a Breadcrumb: a file or a folder"
@def mutable struct FileEntry <: SemanticUI
  path::String = ""
end

"One name in a Breadcrumb"
@def mutable struct Crumb <: SemanticUI
  path::String = ""
  name::String = ""
end

"The path `at`, as the names of the folders on the way to it"
@def mutable struct Breadcrumb <: SemanticUI
  at::String = ""
  open::Bool = false     # is the list of what's in the folder showing?
  # Kept so each name and each line knows when the mouse is over it
  crumbs::Dict{String,Crumb} = Dict{String,Crumb}()
  entries::Dict{String,FileEntry} = Dict{String,FileEntry}()
  # The STLViewer of the model at `at`, the player of the sound or the video there, or the Pages
  # of the PDF file there. It's kept so that the model stays as it was turned, the file plays on
  # from one frame to the next, and the page stays the one you turned to.
  viewer::Any = nothing
  text::Any = nothing    # what `kept!` keeps of the file at `at`, like its text, or false if it has none
  read::Any = nothing    # what `text` is: its kind, the path of its file and when the file last changed
  inline::Bool = false   # in a line of text, so its list floats under it and takes no room on the page
  folders::Bool = false  # only a folder can be the path, as when you choose where something is kept. The folder needn't be made yet.
  room::Union{Nothing,px} = nothing   # how wide it can be, when it has less room than the page is wide
end

"The list or the preview under a breadcrumb that's in a line of text. It floats over the page."
@def mutable struct Listing <: SemanticUI
  of::Any = nothing   # the Breadcrumb
end

const LISTING_W = 340px

describe(f::Listing) =
  Column(width(grow=grow), Alignment.Start, padding(6px), radius(8px), background(colours.block), border(1px, :solid, colours.line),
         lifted, child_gap=1px, contents(f.of)...)

"Show the list of a breadcrumb that's in a line of text when it's open, and take the list away when it isn't"
list!(l::Breadcrumb, w) = begin
  w === nothing && return
  l.open || return close_popup!(w, :listing)
  e = editor(l)
  popup!(w, Listing(of=l), anchor=l, gap=4px, width=min(LISTING_W, e.width), key=:listing, onclose=() -> (l.open = false),
         theme=component_theme(e.zoom))
end

const MOST_FILES = 100

entry(l::Breadcrumb, path) = get!(() -> own!(l, FileEntry(path=path)), l.entries, path)

"The name and the path of each step on the way to `path`. The home folder is one step, named ~."
steps(path) = begin
  home = homedir()
  inside = path == home || startswith(path, home * "/")
  at = inside ? home : "/"
  out = [(inside ? "~" : "/", at)]
  for name in splitpath(relpath(path, at))
    name == "." && continue
    at = joinpath(at, name)
    push!(out, (name, at))
  end
  out
end

"The files and folders in `dir` that aren't hidden, folders first"
listing(dir) = begin
  names = try filter(n -> !startswith(n, "."), readdir(dir)) catch; String[] end
  sort!(names, by=n -> (!isdir(joinpath(dir, n)), lowercase(n)))
end

describe(l::Breadcrumb) = begin
  l.open || hush!(l)
  names = [get!(() -> own!(l, Crumb(path=path, name=name)), l.crumbs, path) for (name, path) in steps(l.at)]
  arrow() = Icon("chevron-right", size=9px, color=colours.faint)
  # The first name and as many of the last names as fit. An … stands for the names left out.
  # An open breadcrumb that isn't in a line of text is in a panel with what's under it, so it has less room
  panel = l.open && !l.inline
  n = fitting(map(wide, names), something(l.room, editor(l).width) - (panel ? 2PANEL_PAD : 0px))
  kept = n < length(names) - 1 ? Any[names[1], Box(width(DOTS_W), label("…", color=colours.dim)), names[end-n+1:end]...] : names
  parts = Iterators.flatten(i == 1 ? (c,) : (arrow(), c) for (i, c) in enumerate(kept))
  l.inline && return Row(height(24px), child_gap=CRUMB_GAP, clip=true, parts...)
  trail = Row(width(grow=grow), height(30px), child_gap=CRUMB_GAP, clip=true, parts...)
  panel || return Column(width(grow=grow), Alignment.Start, trail)
  # One background goes round the names and what's under them, to show that they're one thing
  Column(width(grow=grow), Alignment.Start, padding(PANEL_PAD), radius(8px), background(colours.block), child_gap=1px,
    trail, contents(l)...)
end

const PANEL_PAD = 6px

"What shows under an open breadcrumb: the lines of a folder, or the preview of a file"
contents(l::Breadcrumb) = begin
  l.folders && !isdir(l.at) &&
    return (Row(width(grow=grow), height(26px), padding(10px, 0px), label("This folder isn't made yet", 12px, color=colours.dim)),)
  isdir(l.at) || return (preview(l, l.at),)
  hush!(l)
  l.viewer = l.text = nothing
  names = listing(l.at)
  l.folders && filter!(n -> isdir(joinpath(l.at, n)), names)
  shown = first(names, MOST_FILES)
  isempty(names) && return (Row(width(grow=grow), height(26px), padding(10px, 0px), label("This folder is empty", 12px, color=colours.dim)),)
  ((entry(l, joinpath(l.at, n)) for n in shown)...,
   (length(names) > length(shown) ? (Row(width(grow=grow), height(26px), padding(10px, 0px),
      label("and $(length(names) - length(shown)) more", 12px, color=colours.dim)),) : ())...)
end

const CRUMB_GAP = 2px
const ARROW_W = 9px
const DOTS_W = 18px
const LONGEST_NAME = 28   # characters. A longer name loses its middle.

"A name with its middle left out if it's long, like 8ebf6aee-d8a…e60dbee0e511"
short(name) = length(name) <= LONGEST_NAME ? name :
  first(name, LONGEST_NAME ÷ 2 - 1) * "…" * last(name, LONGEST_NAME ÷ 2)

"How wide a name of a breadcrumb is. The last name is bold and has an icon."
wide(c::Crumb) = begin
  last = c.path == (c.parent::Breadcrumb).at
  measure(Face(SANS, last ? "Semibold" : "", 13px, colours.ink, false), short(c.name)) + 12px + (last ? 19px : 0px)
end

"How many of the last names fit in `room` after the first name, when an … stands for the rest"
fitting(widths, room) = begin
  step = ARROW_W + 2CRUMB_GAP
  sum(widths) + step * (length(widths) - 1) <= room && return length(widths) - 1
  used = widths[1] + step + DOTS_W
  n = 0
  for w in Iterators.reverse(widths[2:end])
    used += step + w
    used > room && n > 0 && break
    n += 1
  end
  min(n, length(widths) - 2)
end

describe(c::Crumb) = begin
  l = c.parent::Breadcrumb
  last = c.path == l.at
  Row(height(24px), padding(6px, 0px), radius(5px), child_gap=6px,
      background(last && l.open ? colours.active : ishovered(c) ? colours.hover : clear),
    (last ? (Icon(l.folders || isdir(c.path) ? "folder" : file_icon(c.path), size=13px, color=colours.dim),) : ())...,
    Box(label(short(c.name), color=last ? colours.ink : colours.dim, weight=last ? "Semibold" : "")))
end

cursor(::Crumb) = :hand

# The last name shows and hides the list. An earlier name goes to its folder.
onkey(c::Crumb, ev::KeyPress{Keys.mouse_left}) = begin
  l = c.parent::Breadcrumb
  # In a line of text, a click with ⌥ held shows the code and leaves the path as it is
  l.inline && held(c, Keys.opt) && return nothing
  c.path == l.at ? (l.open = !l.open) : (l.at = c.path; l.open = true)
  l.inline && list!(l, ev.window)
  nothing
end

describe(r::FileEntry) = begin
  folder = isdir(r.path)
  Row(width(grow=grow), height(26px), padding(10px, 0px), radius(5px), child_gap=8px, clip=true,
      background(ishovered(r) ? colours.hover : clear),
    Icon(folder ? "folder" : file_icon(r.path), size=13px, color=colours.dim),
    Box(width(grow=grow), Alignment.Start, label(basename(r.path))),
    (folder ? () : (Box(label(bytes(filesize(r.path)), 12px, color=colours.dim)),))...)
end

"A file's size in words, like 6.5 KB"
bytes(n) = begin
  n < 1000 && return "$n bytes"
  for unit in ("KB", "MB", "GB")
    n /= 1000
    (n < 1000 || unit == "GB") && return "$(n < 10 ? round(n, digits=1) : round(Int, n)) $unit"
  end
end

const PICTURES = (".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp")
const PREVIEW_LINES = 12
const MODELS = (".stl", ".3mf")   # the files of 3D models that the viewer reads
const MODEL_HEIGHT = 260px
# The sound and the video files that macOS plays
const SOUNDS = (".mp3", ".m4a", ".wav", ".aif", ".aiff", ".aac", ".flac", ".caf")
const VIDEOS = (".mp4", ".mov", ".m4v")

"The viewer of the model in the STL or 3MF file at `path`, or nothing if the file can't be read as a model"
model(l::Breadcrumb, path) = begin
  v = l.viewer
  (v isa STLViewer && v.path == path) || (hush!(l); v = l.viewer = own!(l, STLViewer(path=path, height=MODEL_HEIGHT)))
  load!(v) isa Mesh ? v : nothing
end

"The player of the sound or the video file at `path`. `Player` is AudioPlayer or VideoPlayer."
player(l::Breadcrumb, path, Player) = begin
  v = l.viewer
  (v isa Player && v.path == path) && return v
  hush!(l)
  l.viewer = own!(l, Player === VideoPlayer ? VideoPlayer(path=path, height=MODEL_HEIGHT) : AudioPlayer(path=path))
end

"Stop the sound or the video that the breadcrumb's player is playing"
hush!(l::Breadcrumb) = (l.viewer isa Union{AudioPlayer,VideoPlayer} && pause!(l.viewer); l)

const LINE_H = 18px          # the height of a line of a file's text
const TEXT_PAD = 8px         # above the first line and under the last
const MOST_TEXT = 400_000    # bytes. The preview of a longer file stops there.

"""
The text of the file that a breadcrumb previews. It's kept so that the file
is read once, and so that the text stays where you scrolled it to.
"""
mutable struct FileText
  lines::Vector{String}
  more::Bool        # the file is longer than what was read
  scroll::Scroll
end

FileText(lines, more) = FileText(lines, more, Scroll(width(grow=grow), height(LINE_H * min(length(lines), PREVIEW_LINES) + 2TEXT_PAD)))

"""
The lines of the file at `path` and whether it has more, or nothing if it isn't
text. With `tidy`, a tab is two spaces and a long line stops at 200 characters,
which is how the lines of a file of code are shown.
"""
reading(path; tidy=true) = begin
  bytes = open(io -> read(io, MOST_TEXT + 1), path)
  more = length(bytes) > MOST_TEXT
  more && resize!(bytes, MOST_TEXT)
  (isempty(bytes) || 0x00 in view(bytes, 1:min(length(bytes), 4000))) && return nothing
  s = String(bytes)
  # A file that was cut short can stop part way through a character
  for _ in 1:3
    (isvalid(s) || !more) && break
    s = String(codeunits(s)[1:end-1])
  end
  isvalid(s) || return nothing
  lines = [tidy ? String(first(replace(rstrip(line, '\r'), '\t' => "  "), 200)) : String(rstrip(line, '\r')) for line in split(s, '\n')]
  # The last line of a file that was cut short isn't all there, and a file that ends with a new line has no line after it
  (more || isempty(lines[end])) && length(lines) > 1 && pop!(lines)
  lines, more
end

"""
What the breadcrumb `l` keeps of the file at `path`: what `make(path)` gave, or
nothing if `make` found nothing to show. It's made again when the file changes.
`kind` names what's kept, so that two kinds of preview don't take each other's.
"""
kept!(make, l::Breadcrumb, path, kind) = begin
  key = (kind, path, mtime(path))
  l.read == key || (l.read = key; l.text = something(make(path), false))
  l.text === false ? nothing : l.text
end

"The text of the file at `path` for the breadcrumb `l`, or nothing if the file isn't text"
text!(l::Breadcrumb, path) = kept!(l, path, :text) do path
  found = reading(path)
  found === nothing ? nothing : FileText(found...)
end

"""
`n` rows that are each `high` tall, `PREVIEW_LINES` of them at a time. The
wheel scrolls through the rest. `row(i)` makes row `i`. Only the rows in view
are made, so a long file costs no more than a short one.
"""
scrolled(row, scroll::Scroll, n, high=LINE_H) = begin
  lo = clamp(floor(Int, (scroll.offset - TEXT_PAD) / high), 0, max(0, n - PREVIEW_LINES))
  hi = min(n, lo + PREVIEW_LINES + 2)
  Box(width(grow=grow), padding(10px, 0px), radius(5px), background(colours.bg), clip=true,
    reuse!(scroll, Column(width(grow=grow), Alignment.Start,
      spacer(TEXT_PAD + high * lo),
      [row(i) for i in lo+1:hi]...,
      spacer(TEXT_PAD + high * (n - hi)))))
end

"The text of a file. `lang` is the end of the file's name, like jl."
textview(t::FileText, lang) = scrolled(i -> codeline(t.lines[i], lang), t.scroll, length(t.lines))

"""
One line of a file's text. A file of code has the colours that a code block
has: `lang` is the end of the file's name, like jl, and a file that isn't code
is all one colour.
"""
codeline(line, lang) = Row(height(LINE_H),
  [part for t in tokens(line, lang)
        for part in spared(t.text, Face(codefont(), t.kind == :comment ? codeslant() : codestyle(), 12px,
                                        t.kind == :plain ? colours.ink : getfield(colours, t.kind), false))]...)

# --- the files in a zip -------------------------------------------------------------------

const ZIPS = (".zip", ".jar")
const MOST_ZIP = 300_000_000   # bytes. A bigger zip isn't read.

"The files in the zip at `path`, as lines of text: the name of each and how big it is once it's unpacked"
zipped(path) = begin
  filesize(path) > MOST_ZIP && return nothing
  found = try ThreeMF.entries(read(path)) catch; return nothing end
  names = sort!([name for name in keys(found) if !endswith(name, '/')])
  isempty(names) && return nothing
  wide = min(64, maximum(length, names))
  FileText([rpad(length(name) > 64 ? "…" * last(name, 63) : name, wide) * "   " * bytes(found[name].full) for name in names], false)
end

# --- a CSV file as a table --------------------------------------------------------------------

const TABLES = (".csv", ".tsv")
const ROW_H = 24px
const MOST_COLUMNS = 40

"The rows of a CSV file that a breadcrumb previews, and how wide each column is"
mutable struct FileTable
  rows::Vector{Vector{String}}
  widths::Vector{px}
  more::Bool
  scroll::Scroll
end

"The cells of one line of a CSV file, as csv.jl reads them. `mark` is the character between two cells."
const csv_cells = Csvs.cells

"The rows of the CSV file at `path`. The mark between its cells is the one its first line has most of: a comma, a tab or a semicolon."
tabled(path) = begin
  found = reading(path, tidy=false)
  found === nothing && return nothing
  lines, more = found
  lines = filter(!isempty, lines)
  isempty(lines) && return nothing
  mark = argmax(c -> count(==(c), lines[1]), (',', '\t', ';'))
  rows = [first(csv_cells(line, mark), MOST_COLUMNS) for line in lines]
  columns = maximum(length, rows)
  face(r) = Face(SANS, r == 1 ? "Semibold" : "", 12px, colours.ink, false)
  # A column is as wide as the widest of its first hundred cells, and no wider than 240px
  widths = [clamp(maximum(r -> c <= length(rows[r]) ? measure(face(r), rows[r][c]) : 0px, 1:min(100, length(rows))), 24px, 240px) + 20px
            for c in 1:columns]
  FileTable(rows, widths, more, Scroll(width(grow=grow), height(ROW_H * min(length(rows), PREVIEW_LINES) + 2TEXT_PAD)))
end

"The rows of a CSV file as a table. Its first row is its headings."
tableview(t::FileTable) = scrolled(r -> tablerow(t, r), t.scroll, length(t.rows), ROW_H)

"Row `r` of a CSV file's table"
tablerow(t::FileTable, r) =
  Row(height(ROW_H), Alignment.Start, radius(3px), background(r == 1 ? colours.head : iseven(r) ? clear : colours.stripe),
    [Box(fixed(w), height(ROW_H), padding(10px, 0px), Alignment.Start, clip=true,
         label(c <= length(t.rows[r]) ? t.rows[r][c] : "", 12px, weight=r == 1 ? "Semibold" : ""))
     for (c, w) in enumerate(t.widths)]...)

# --- a Markdown file as it reads ---------------------------------------------------------------

const PAGE_ZOOM = 0.8        # the text of a page under a path is this much smaller than the text of the page itself
const PAGE_HEIGHT = 320px    # the most of the page that shows. The wheel scrolls through the rest.

"The lines of a Markdown file that a breadcrumb previews, laid out as the page lays out its own lines"
mutable struct FilePage
  flows::Vector{Flow}
  tops::Vector{px}   # how far each line is under the first
  tall::px
  more::Bool
  scroll::Scroll
end

"How wide what's under the breadcrumb `l` is"
room(l::Breadcrumb) = (e = editor(l); (l.inline ? min(LISTING_W, e.width) : e.width - 2PANEL_PAD) - 12px)

"The Markdown file at `path`, laid out for the breadcrumb `l`. It's laid out again when the page's text changes its size, font, weight or colours."
filepage(l::Breadcrumb, path) = begin
  e = editor(l)
  wide = room(l) - 28px   # the page has 14px of room on each side
  kept!(l, path, (:page, wide, e.zoom, e.theme, e.font, e.weight)) do path
    found = reading(path, tidy=false)
    found === nothing && return nothing
    lines, more = found
    kinds = classify(lines)
    zoom = e.zoom
    e.zoom = zoom * PAGE_ZOOM
    # -1 says that the line isn't one of the document's, so its inline code isn't run
    flows = try
      [laid(e, lines[i], kinds[i], false, -1, wide) for i in eachindex(lines)]
    finally
      e.zoom = zoom
    end
    tops = accumulate(+, map(tall, flows)) .- map(tall, flows)
    total = sum(tall, flows, init=0px)
    FilePage(flows, tops, total, more, Scroll(width(grow=grow), height(min(total + 2TEXT_PAD, PAGE_HEIGHT))))
  end
end

"A Markdown file as it reads. Only the lines in view are made."
pageview(e, p::FilePage) = begin
  from = p.scroll.offset - TEXT_PAD
  lo = something(findlast(<=(from), p.tops), 1)
  hi = something(findfirst(>(from + PAGE_HEIGHT), p.tops), length(p.tops) + 1) - 1
  under = p.tall - (p.tops[hi] + tall(p.flows[hi]))
  Box(width(grow=grow), padding(14px, 0px), radius(5px), background(colours.bg), clip=true,
    reuse!(p.scroll, Column(width(grow=grow), Alignment.Start,
      spacer(TEXT_PAD + p.tops[lo]),
      [describe(e, Item(0, 0, 0px, tall(f), f), f) for f in p.flows[lo:hi]]...,
      spacer(TEXT_PAD + under))))
end

# --- the pages of a PDF file --------------------------------------------------------------------

const PAGE_W = 420px   # how wide a page of a PDF file shows

"The pages of a PDF file, one at a time. A click on the left half goes back a page, and one on the right half goes on."
@def mutable struct Pages <: SemanticUI
  path::String = ""
  page::Int = 1
  count::Int = 0
  wide::px = PAGE_W   # how wide a page shows
end

describe(p::Pages) = begin
  # Twice as many pixels as px, so that the page is sharp on a screen with 2 pixels to the px
  key = pdf_page(p.path, p.page, round(Int, 2num(p.wide)))
  key === nothing && return label("This page can't be shown", 12px, color=colours.dim)
  shape = image_aspect(key)
  arrow(name, on) = Icon(name, size=11px, color=on ? colours.dim : colours.faint)
  Column(Alignment.Start, child_gap=6px,
    fillable(p, (:pdf, p.path, p.page), Image(key, fixed(p.wide), height(p.wide / shape), radius(3px), border(1px, :solid, colours.line))),
    (p.count > 1 ? (Row(fixed(p.wide), height(22px), justify=Alignment.Center, child_gap=10px,
       arrow("chevron-left", p.page > 1), label("Page $(p.page) of $(p.count)", 12px, color=colours.dim),
       arrow("chevron-right", p.page < p.count)),) : ())...)
end

cursor(p::Pages) = p.count > 1 ? :hand : :arrow

"Go on by `by` pages, as far as the first page or the last"
turn!(p::Pages, by) = (p.page = clamp(p.page + by, 1, max(1, p.count)); handled)

onkey(p::Pages, ev::KeyPress{Keys.mouse_left}) = begin
  focus(p)
  r = rect(p)
  r === nothing ? handled : turn!(p, ev.window.mouse[1] < r.left + p.wide / 2 ? -1 : 1)
end
# The arrow keys turn the pages too, once a click has given them the keyboard
onkey(p::Pages, ::KeyPress{Keys.left}) = turn!(p, -1)
onkey(p::Pages, ::KeyPress{Keys.right}) = turn!(p, 1)

"The pages of the PDF file at `path`, or nothing if it isn't a PDF file that macOS can read"
pager(l::Breadcrumb, path) = begin
  v = l.viewer
  v isa Pages && v.path == path && return v
  hush!(l)
  n = pdf_pages(path)
  n == 0 ? nothing : (l.viewer = own!(l, Pages(path=path, count=n)))
end

# --- what shows for each kind of file --------------------------------------------------------------

# The pictures that macOS reads and Skia doesn't
const MAC_PICTURES = (".heic", ".heif", ".tif", ".tiff", ".svg", ".ico", ".icns", ".psd")
# The files whose first page the Finder can show
const DOCUMENTS = (".rtf", ".rtfd", ".doc", ".docx", ".pages", ".key", ".numbers", ".xls", ".xlsx", ".ppt", ".pptx", ".odt", ".epub")
const FONTS = (".ttf", ".otf", ".ttc", ".woff", ".woff2")
const CODE = (".jl", ".js", ".mjs", ".cjs", ".ts", ".tsx", ".jsx", ".py", ".rb", ".rs", ".go", ".c", ".h", ".cc", ".cpp", ".hpp", ".swift",
              ".kt", ".java", ".sh", ".zsh", ".css", ".html", ".json", ".toml", ".yml", ".yaml", ".xml", ".sql", ".lua")

"The icon for the file at `path`. It says what kind of file it is, from the end of the file's name."
file_icon(path) = begin
  ext = lowercase(splitext(path)[2])
  ext in MARKDOWN || ext == ".txt" ? "file-earmark-text" :
  ext in PICTURES || ext in MAC_PICTURES ? "file-earmark-image" :
  ext in SOUNDS ? "file-earmark-music" :
  ext in VIDEOS ? "file-earmark-play" :
  ext in MODELS ? "box" :
  ext == ".pdf" ? "file-earmark-pdf" :
  ext in ZIPS ? "file-earmark-zip" :
  ext in TABLES ? "file-earmark-spreadsheet" :
  ext in FONTS ? "file-earmark-font" :
  ext in DOCUMENTS ? "file-earmark-richtext" :
  ext in CODE ? "file-earmark-code" : "file-earmark"
end

"Every icon that `file_icon` can give, and those of a file that's only shown: of a binary file, and of the button that opens the file in its own app. The built app reads them all when it's made."
const FILE_ICONS = ("file-earmark", "file-earmark-text", "file-earmark-image", "file-earmark-music", "file-earmark-play", "box",
                    "file-earmark-pdf", "file-earmark-zip", "file-earmark-spreadsheet", "file-earmark-font", "file-earmark-richtext",
                    "file-earmark-code", "file-earmark-binary", "box-arrow-up-right", "chevron-left", "chevron-right")

"The picture kept under `key`, no taller than `most` and no wider than 420px. A picture of a page has a line round it."
framed(key, most=260px; page=false) = begin
  shape = image_aspect(key)
  w = min(420px, most * shape)
  page ? Image(key, fixed(w), height(w / shape), radius(3px), border(1px, :solid, colours.line)) :
         Image(key, fixed(w), height(w / shape), radius(4px))
end

"""
What shows for the file at `path`, or nothing if the file has no preview. `ext`
is the end of the file's name. `note(words)` adds words to the line under the
preview.
"""
peek(l::Breadcrumb, path, ext, note) = begin
  mac = Sys.isapple()
  # A picture, a model and a video have a button that makes them fill the window
  pic(key, more...; kw...) = fillable(l, (:picture, key), framed(key, more...; kw...))
  if ext in PICTURES
    return pic(path)
  elseif ext in MAC_PICTURES
    key = picture(path)
    key === nothing || return pic(key)
  elseif ext in MODELS
    viewer = model(l, path)
    viewer === nothing || return fillable(l, (:node, viewer), viewer, wide=:grow)
  elseif mac && ext in SOUNDS
    return player(l, path, AudioPlayer)
  elseif mac && ext in VIDEOS
    p = player(l, path, VideoPlayer)
    return fillable(l, (:node, p), p, wide=video_wide(p))
  elseif mac && ext == ".pdf"
    found = pager(l, path)
    found === nothing || return found
  elseif ext in ZIPS
    list = kept!(zipped, l, path, :zip)
    list === nothing && return nothing
    note("$(length(list.lines)) file$(length(list.lines) == 1 ? "" : "s")")
    return textview(list, "")
  elseif ext in TABLES
    table = kept!(tabled, l, path, :table)
    table === nothing && return nothing
    note(table.more ? "the first $(length(table.rows) - 1) rows" : "$(length(table.rows) - 1) row$(length(table.rows) == 2 ? "" : "s")")
    return tableview(table)
  elseif ismarkdown(path)
    page = filepage(l, path)
    page === nothing && return nothing
    page.more && note("the first $(bytes(MOST_TEXT)) of $(bytes(filesize(path)))")
    return pageview(editor(l), page)
  elseif ext in DOCUMENTS || ext in FONTS
    key = thumbnail(path)
    return key === nothing ? nothing : pic(key, 400px, page=ext in DOCUMENTS)
  end
  text = text!(l, path)
  if text !== nothing
    text.more && note("the first $(bytes(MOST_TEXT)) of $(bytes(filesize(path)))")
    return textview(text, lstrip(ext, '.'))
  end
  # The Finder has a picture for many kinds of file that have none here
  key = thumbnail(path)
  key === nothing ? nothing : pic(key)
end

"What shows under the path of a file: its picture, its model, its player, its pages or its text, and when it last changed"
preview(l::Breadcrumb, path) = begin
  isfile(path) || return Box(height(0px))
  ext = lowercase(splitext(path)[2])
  # A player that was made for another file stops when the path leaves that file
  l.viewer !== nothing && l.viewer.path != path && (hush!(l); l.viewer = nothing)
  about = "Changed " * Libc.strftime("%-d %b %Y, %H:%M", mtime(path))
  content = try
    peek(l, path, ext, words -> (about *= "  ·  " * words))
  catch
    nothing
  end
  content === nothing && (content = label("This file has no preview", 12px, color=colours.dim))
  Column(width(grow=grow), Alignment.Start, padding(6px), child_gap=8px,
    content, label(about, 12px, color=colours.dim))
end

cursor(::FileEntry) = :hand

onkey(r::FileEntry, ::KeyPress{Keys.mouse_left}) = begin
  (r.parent::Breadcrumb).at = r.path
end

# --- a file that isn't Markdown, in the page -------------------------------------------------
#
# A click on a file in the sidebar shows the file in the page, whatever kind of
# file it is. Ladder changes Markdown files and Julia files, so any other file
# is only shown, and the top bar says "Read only". The button beside those
# words opens the file in the app that the Mac uses for it.
#
# A Julia file is one block of code, with no lines that open and close it. You
# type in it as in a `julia` code block of a page: ⌘Return runs the expression
# that the caret is in, a list offers names, a bracket comes with the bracket
# that closes it, and ⌘S writes the file.
#
#   - A file of text shows its text. A file of code has the colours that a code
#     block has. You can select the text, copy it and find words in it.
#   - A picture, a model, a sound, a video, a PDF file, a CSV file, a Word file
#     and a font show as they do under a file path, as big as the page has room for.
#   - A CSV file shows as a table as wide as the window, which you can sort and
#     filter by its headings. "a CSV file in the page" says more.
#   - A JSON file shows as a tree of its values. "a JSON file as a tree"
#     says more.
#   - A zip shows the list of the files in it.
#   - Any other file is a binary file. The page says so, and a button there
#     shows the file's bytes in hexadecimal.

const MOST_LINE = 2000     # characters. A longer line of a file's text stops there.
const HEX = "hex"          # the language of the lines that show a file's bytes
const HEX_BYTES = 10       # the column of such a line where the bytes start, after their place in the file
const HEX_CHARS = 60       # the column where the same bytes start as characters
const MOST_HEX = 160_000   # bytes. The lines of a longer file stop there.

"True when a file whose name ends with `ext` has a viewer of its own, so it doesn't show as text"
viewed(ext) = ext in PICTURES || ext in MAC_PICTURES || ext in MODELS || ext in SOUNDS || ext in VIDEOS || ext == ".pdf" ||
              ext in TABLES || ext in DOCUMENTS || ext in FONTS

"A line of a file's text as the page shows it: a tab is two spaces, and a very long line stops with an …"
shown_line(line) = begin
  s = replace(line, '\t' => "  ")
  length(s) > MOST_LINE ? first(s, MOST_LINE) * "…" : String(s)
end

"The buffer that shows the file at `path`, which isn't Markdown. A JSON file shows as a tree, or with `tree` false as its text."
look(path; tree=true) = begin
  ext = lowercase(splitext(path)[2])
  if ext in ZIPS
    list = try zipped(path) catch; nothing end
    n = list === nothing ? 0 : length(list.lines)
    list === nothing || return Buffer(path=path, view=:text, lines=list.lines, about="$(commas(n)) file$(n == 1 ? "" : "s")")
  elseif tree && ext in JSONS && json_of(path) !== nothing
    return Buffer(path=path, view=:file)
  elseif !viewed(ext)
    found = try reading(path, tidy=false) catch; nothing end
    if found !== nothing
      lines, more = found
      return Buffer(path=path, view=:text, lines=map(shown_line, lines),
                    about=more ? "First $(bytes(MOST_TEXT)) of $(bytes(filesize(path)))" : "")
    end
  end
  Buffer(path=path, view=:file)
end

"""
The bytes of the file at `path` as lines of text. Each line has the place of
its first byte in the file, then 16 bytes in hexadecimal, then the same bytes
as characters. A byte that isn't a character of plain text shows as a dot.
"""
hexlines(path) = begin
  data = open(io -> read(io, MOST_HEX), path)
  hex(row) = join((string(x, base=16, pad=2) for x in row), ' ')
  map(0:16:max(0, length(data) - 1)) do at
    row = data[at+1:min(at + 16, end)]
    rpad(string(at, base=16, pad=8), HEX_BYTES) * rpad(hex(row[1:min(8, end)]) * "  " * hex(row[9:end]), HEX_CHARS - HEX_BYTES) *
      String([0x20 <= x < 0x7f ? Char(x) : '.' for x in row])
  end
end

"What the top bar says of the bytes of the file at `path`: how many of them show, when not all do"
hex_about(path) = filesize(path) > MOST_HEX ? "First $(bytes(MOST_HEX)) of $(bytes(filesize(path)))" : ""

"Show the bytes of the file that the page shows, in hexadecimal"
hex!(e) = begin
  b = e.buf
  (readonly(b) && isfile(b.path)) || return e
  b.lines, b.about, b.view = hexlines(b.path), hex_about(b.path), :hex
  b.caret = b.anchor = (1, 0)
  b.saved = b.version += 1
  e.scroll.offset = 0px
  focus(e)
  e
end

# --- a JSON file as a tree ---------------------------------------------------------------------
#
# A JSON file shows as a tree of its values, as the inspector of a `ui` block
# shows a Julia value. The first row is the file's whole value, so you can see
# whether the file holds an object or a list. Each key of an object, and each
# item of a list, is a row, a step in from the row of what holds it. The row
# of an object or a list has an arrow, and a click on the row opens it or
# closes it. ⌥-click opens or closes everything in it too. A closed one shows
# on its row what it holds, as much as the row has room for. An open one says
# how many keys or items it has, in its brackets: {3 keys} or [22 items]. At
# first the tree is open as far as about a window of rows goes. The place of
# an item in its list counts from 0, as JSON's own tools count it.
#
# A click also chooses the row and gives the tree the keyboard. Then ↑ and ↓
# go from row to row, → opens a row or goes into it, ← closes it or goes to
# the row that holds it, and Return opens or closes it. ⌘C copies the value of
# the row: a string as its text, and an object or a list as JSON. Esc gives
# the keyboard back to the page.
#
# The tree is the file at the high level, as the graphics are of a page. The
# snake in the top bar, or ⌘E, goes down a level to the file's text, which you
# can select and search. The ladder, or ⌘E again, goes back up to the tree,
# open as it was. A file that isn't JSON after all, and one bigger than
# MOST_JSON, only shows as text.
#
# Only the rows that are in the window are made, so a long tree costs no more
# to draw than a short one.

const JSONS = (".json", ".geojson")
const MOST_JSON = 32_000_000   # bytes. A bigger JSON file only shows as text.
const JSON_STEP = 18px         # how far in each level of the tree is
const JSON_ARROW = 16px        # the room for the arrow of an object or a list
const JSON_PAD = 6px           # between the ends of a row's highlight and its text
const MOST_STRING = 2000       # characters. A longer string stops there on its row.

"An object of a JSON file: its keys and their values, in the order that the file has them"
struct JSONObject
  keys::Vector{String}
  values::Vector{Any}
end

"A number of a JSON file, as the file writes it. So 3 shows as 3, 1.50 as 1.50, and a long number loses no digits."
struct JSONNumber
  text::String
end

"""
What the JSON in `data` holds: a JSONObject, a list, a string, a JSONNumber,
true, false or nothing. It's an error if `data` isn't JSON.
"""
json_value(data::AbstractVector{UInt8}) = begin
  # Some programs start a file with a mark that says it's UTF-8. It isn't part of the JSON.
  i = length(data) >= 3 && data[1] == 0xef && data[2] == 0xbb && data[3] == 0xbf ? 4 : 1
  value, i = json_read(data, json_blank(data, i))
  json_blank(data, i) > length(data) || error("There's more after the JSON")
  value
end

"The place of the first byte at or after `i` that isn't a space or a line break"
json_blank(d, i) = begin
  while i <= length(d) && (d[i] == 0x20 || d[i] == 0x0a || d[i] == 0x0d || d[i] == 0x09)
    i += 1
  end
  i
end

"Byte `i` of `d`. It's an error if the JSON stops before it."
json_byte(d, i) = i <= length(d) ? d[i] : error("The JSON stops early")

const JSON_NUMBER = r"^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$"

"The value that starts at byte `i` of `d`, and the place of the byte after it"
json_read(d, i) = begin
  c = json_byte(d, i)
  if c == UInt8('{')
    keys, values = String[], Any[]
    i = json_blank(d, i + 1)
    json_byte(d, i) == UInt8('}') && return JSONObject(keys, values), i + 1
    while true
      key, i = json_string(d, i)
      i = json_blank(d, i)
      json_byte(d, i) == UInt8(':') || error("A key of the JSON has no value")
      value, i = json_read(d, json_blank(d, i + 1))
      push!(keys, key)
      push!(values, value)
      i = json_blank(d, i)
      c = json_byte(d, i)
      c == UInt8('}') && return JSONObject(keys, values), i + 1
      c == UInt8(',') || error("The JSON has an object that doesn't end")
      i = json_blank(d, i + 1)
    end
  elseif c == UInt8('[')
    list = Any[]
    i = json_blank(d, i + 1)
    json_byte(d, i) == UInt8(']') && return list, i + 1
    while true
      value, i = json_read(d, i)
      push!(list, value)
      i = json_blank(d, i)
      c = json_byte(d, i)
      c == UInt8(']') && return list, i + 1
      c == UInt8(',') || error("The JSON has a list that doesn't end")
      i = json_blank(d, i + 1)
    end
  elseif c == UInt8('"')
    json_string(d, i)
  else
    j = i
    while j <= length(d) && !(d[j] in (UInt8(','), UInt8('}'), UInt8(']'), 0x20, 0x0a, 0x0d, 0x09))
      j += 1
    end
    word = String(d[i:j-1])
    word == "true" ? (true, j) : word == "false" ? (false, j) : word == "null" ? (nothing, j) :
      occursin(JSON_NUMBER, word) ? (JSONNumber(word), j) : error("The JSON has $(repr(first(word, 20))) where a value should be")
  end
end

"The string that starts at byte `i` of `d`, and the place of the byte after it"
json_string(d, i) = begin
  json_byte(d, i) == UInt8('"') || error("The JSON has no string where one should be")
  i += 1
  j = i
  # Most strings have no \ in them, and are copied as they are
  while (c = json_byte(d, j)) != UInt8('"') && c != UInt8('\\')
    j += 1
  end
  d[j] == UInt8('"') && return String(d[i:j-1]), j + 1
  out = IOBuffer()
  write(out, view(d, i:j-1))
  while (c = json_byte(d, j)) != UInt8('"')
    if c == UInt8('\\')
      x = json_byte(d, j + 1)
      j += 2
      if x == UInt8('u')
        n, j = json_hex(d, j)
        # A character past U+FFFF is written as two halves
        if 0xd800 <= n < 0xdc00 && j + 1 <= length(d) && d[j] == UInt8('\\') && d[j+1] == UInt8('u')
          low, k = json_hex(d, j + 2)
          0xdc00 <= low < 0xe000 && ((n, j) = (0x10000 + ((n - 0xd800) << 10) + (low - 0xdc00), k))
        end
        # Half of one on its own is no character
        print(out, 0xd800 <= n < 0xe000 ? '�' : Char(n))
      else
        write(out, x == UInt8('n') ? UInt8('\n') : x == UInt8('t') ? UInt8('\t') : x == UInt8('r') ? UInt8('\r') :
                   x == UInt8('b') ? UInt8('\b') : x == UInt8('f') ? UInt8('\f') : x)
      end
    else
      write(out, c)
      j += 1
    end
  end
  String(take!(out)), j + 1
end

"The number that the four hexadecimal digits at byte `i` of `d` write, and the place of the byte after them"
json_hex(d, i) = begin
  i + 3 <= length(d) || error("The JSON stops early")
  parse(UInt32, String(d[i:i+3]), base=16), i + 4
end

"What each JSON file that was read holds, with when the file had last changed then. Only the last few are kept."
const JSON_READ = Dict{String,Tuple{Float64,Any}}()

"""
What the JSON file at `path` holds, or nothing if it isn't JSON or is bigger
than MOST_JSON. A file is read once, and again when it changes.
"""
json_of(path) = begin
  at = mtime(path)
  kept = get(JSON_READ, path, nothing)
  kept !== nothing && kept[1] == at && return kept[2]
  value = 0 < filesize(path) <= MOST_JSON ? (try json_value(read(path)) catch; nothing end) : nothing
  length(JSON_READ) >= 4 && empty!(JSON_READ)
  JSON_READ[path] = (at, value)
  value
end

"True when the page shows a JSON file that can show as a tree: as the tree, or down a level as the file's text"
json_page(b::Buffer) = b.view in (:file, :text) && lowercase(splitext(b.path)[2]) in JSONS && isfile(b.path) && json_of(b.path) !== nothing

json_items(o::JSONObject) = zip(o.keys, o.values)
json_items(l::Vector{Any}) = zip(0:length(l)-1, l)
"How many keys or items `v` has. A value that's neither an object nor a list has none."
json_length(o::JSONObject) = length(o.keys)
json_length(l::Vector{Any}) = length(l)
json_length(_) = 0
json_holder(v) = v isa JSONObject || v isa Vector{Any}

"How many keys or items `v` has, in words"
json_count(o::JSONObject) = (n = length(o.keys); "$(commas(n)) key$(n == 1 ? "" : "s")")
json_count(l::Vector{Any}) = (n = length(l); "$(commas(n)) item$(n == 1 ? "" : "s")")

"Write `v` as JSON. An object and a list have each key or item on a line of its own, `depth` steps of two spaces in."
json_write(io::IO, s::AbstractString) = begin
  print(io, '"')
  for c in s
    c == '"' ? print(io, "\\\"") : c == '\\' ? print(io, "\\\\") : c == '\n' ? print(io, "\\n") :
    c == '\r' ? print(io, "\\r") : c == '\t' ? print(io, "\\t") :
    isvalid(c) && c < ' ' ? print(io, "\\u", string(UInt32(c), base=16, pad=4)) : print(io, c)
  end
  print(io, '"')
end
json_write(io::IO, n::JSONNumber) = print(io, n.text)
json_write(io::IO, b::Bool) = print(io, b)
json_write(io::IO, ::Nothing) = print(io, "null")
json_write(io::IO, v::Union{JSONObject,Vector{Any}}, depth=0) = begin
  object = v isa JSONObject
  json_length(v) == 0 && return print(io, object ? "{}" : "[]")
  print(io, object ? '{' : '[')
  for (k, (key, x)) in enumerate(json_items(v))
    print(io, k > 1 ? ",\n" : "\n", "  "^(depth + 1))
    object && (json_write(io, key); print(io, ": "))
    json_write(io, x, depth + 1)
  end
  print(io, '\n', "  "^depth, object ? '}' : ']')
end
json_write(io::IO, x, depth) = json_write(io, x)

"What ⌘C copies of `v`: a string as its text, and any other value as JSON"
json_copy(v::AbstractString) = String(v)
json_copy(v) = sprint(json_write, v)

"A row of a JSON file's tree: how many steps in it is, the key of its value or its place in its list, and its value"
struct JSONRow
  depth::Int
  key::Union{Nothing,String,Int}
  value::Any
end

"The tree of the JSON file at `path`"
@def mutable struct JSONTree <: SemanticUI
  path::String = ""
  root::Any = nothing
  open::IdDict{Any,Bool} = IdDict{Any,Bool}()   # the objects and the lists that are open
  rows::Vector{JSONRow} = JSONRow[]             # the rows that show, worked out again when one opens or closes
  chosen::Int = 0                               # the row that the arrow keys are on, or 0 for none
end

"""
Show the tree of `root`, open as far as about `most` rows go. The top object
or list is always open. Then each level opens as a whole while there's room
for all of it.
"""
plant!(t::JSONTree, root, most=60) = begin
  t.root, t.chosen = root, 0
  empty!(t.open)
  level = json_holder(root) ? Any[root] : Any[]
  count = 0
  while !isempty(level)
    n = sum(json_length, level)
    count > 0 && count + n > most && break
    foreach(v -> t.open[v] = true, level)
    count += n
    level = Any[x for v in level for (_, x) in json_items(v) if json_length(x) > 0]
  end
  t.rows = json_rows(t)
  t
end

"""
The rows that show. The first is the file's whole value, so a file that holds
a list shows that it's a list, and with that row closed the tree is that one
row. Under each object or list that's open are the rows of its keys or items.
"""
json_rows(t::JSONTree) = json_rows!(JSONRow[], t.open, 0, nothing, t.root)
json_rows!(rows, open, depth, key, value) = begin
  push!(rows, JSONRow(depth, key, value))
  if json_holder(value) && get(open, value, false)
    for (k, x) in json_items(value)
      json_rows!(rows, open, depth + 1, k, x)
    end
  end
  rows
end

"True when row `i` is an object or a list that's open"
json_opened(t::JSONTree, i) = (v = t.rows[i].value; json_holder(v) && get(t.open, v, false))

"Open row `i` if it's closed, or close it. With `all`, everything in it opens or closes with it."
json_toggle!(t::JSONTree, i; all=false) = begin
  v = t.rows[i].value
  json_length(v) > 0 || return t
  shut = json_opened(t, i)
  set!(x) = shut ? delete!(t.open, x) : (t.open[x] = true)
  all ? json_each(set!, v) : set!(v)
  t.rows = json_rows(t)
  t
end

"Call `f` on `v` and on each object and list in it that has something in it"
json_each(f, v) = begin
  json_length(v) > 0 || return
  f(v)
  for (_, x) in json_items(v)
    json_each(f, x)
  end
end

"How far apart the rows of the tree are: as far as the lines of the file's text"
json_row_h(e) = code_size(e) * 1.5 / CODE_SCALE

"The face of the tree's text: the font of code, in `colour`"
json_face(e, colour=colours.ink) = Face(codefont(), codestyle(), code_size(e), colour, false)

"Words of the tree, in `colour`. Each is in a box, so it's as wide as it is and no wider."
json_words(e, s, colour) = Box(height(grow=grow), Alignment.Center,
  Text(s, size=code_size(e), family=codefont(), subfamily=codestyle(), color=colour, wrap=WrapMode.none))

"`s` as a string of JSON, in its quotes, no longer than `room` characters. A longer one stops with an …"
json_quoted(s, room) = begin
  q = sprint(json_write, length(s) > MOST_STRING ? first(s, MOST_STRING) : s)
  length(q) <= room && length(s) <= MOST_STRING ? q : first(q, max(2, room - 2)) * "…\""
end

"What `x` shows as in a closed object or list: an object or a list in short, and a string no longer than 40 characters"
json_brief(x) = json_holder(x) ? (x isa JSONObject ? (json_length(x) == 0 ? "{}" : "{…}") : (json_length(x) == 0 ? "[]" : "[…]")) :
                x isa AbstractString ? json_quoted(x, 40) : sprint(json_write, x)

"""
What a closed object or list holds, on one line of no more than `room`
characters, as far as there's room. The end says how many more there are.
"""
json_peek(v, room) = begin
  object = v isa JSONObject
  n = json_length(v)
  parts = String[]
  used = 2
  for (key, x) in json_items(v)
    part = (object ? key * ": " : "") * json_brief(x)
    left = n - length(parts) - 1   # how many come after this one
    more = left > 0 ? length(", … $(commas(left)) more") : 0
    !isempty(parts) && used + 2 + length(part) + more > room && break
    used += (isempty(parts) ? 0 : 2) + length(part)
    push!(parts, part)
  end
  left = n - length(parts)
  inside = join(parts, ", ") * (left > 0 ? ", … $(commas(left)) more" : "")
  object ? "{" * inside * "}" : "[" * inside * "]"
end

"The text of the value of a row, and its colour, no longer than `room` characters"
json_shown(t::JSONTree, i, room) = begin
  v = t.rows[i].value
  v isa AbstractString ? (json_quoted(v, room), colours.string) :
  v isa JSONNumber ? (v.text, colours.number) :
  v isa Bool || v === nothing ? (sprint(json_write, v), colours.keyword) :
  json_length(v) == 0 ? (json_brief(v), colours.dim) :
  json_opened(t, i) ? (v isa JSONObject ? "{" * json_count(v) * "}" : "[" * json_count(v) * "]", colours.dim) :
                      (json_peek(v, room), colours.dim)
end

"The row of the tree that the mouse is over, or 0"
json_under(t::JSONTree) = begin
  ishovered(t) || return 0
  r, w = rect(t), window_of(t)
  (r === nothing || w === nothing) && return 0
  i = floor(Int, (w.mouse[2] - r.top) / json_row_h(editor(t))) + 1
  1 <= i <= length(t.rows) ? i : 0
end

"Row `i` of the tree. `over` is true while the mouse is over it, and `keys` while the tree has the keyboard."
json_row(t::JSONTree, e, i, over, keys) = begin
  row = t.rows[i]
  h = json_row_h(e)
  tint = i == t.chosen ? (keys ? colours.select : colours.active) : over ? colours.hover : clear
  key = row.key === nothing ? () :
        row.key isa Int ? (json_words(e, string(row.key), colours.faint), json_words(e, ": ", colours.faint)) :
                          (json_words(e, row.key, colours.call), json_words(e, ": ", colours.dim))
  # The code font is monospaced, so the room for the value is a number of characters
  wide = measure(json_face(e), "0")
  keyed = row.key === nothing ? 0 : length(string(row.key)) + 2
  room = max(12, floor(Int, (e.width - 2JSON_PAD - JSON_STEP * row.depth - JSON_ARROW) / wide) - keyed)
  text, colour = json_shown(t, i, room)
  arrow = json_length(row.value) > 0 ? Icon(json_opened(t, i) ? "chevron-down" : "chevron-right", size=10px, color=colours.dim) : Box()
  Row(width(grow=grow), height(h), Alignment.Center, padding(JSON_PAD, 0px), radius(4px), background(tint), clip=true,
    Box(width(JSON_STEP * row.depth)), Box(width(JSON_ARROW), height(grow=grow), Alignment.Center, arrow),
    key..., json_words(e, text, colour))
end

describe(t::JSONTree) = begin
  e = editor(t)
  h = json_row_h(e)
  n = length(t.rows)
  _, high = window_size(e)
  # Only the rows that are in the window are made, and a few more above and below
  lo = clamp(floor(Int, (e.scroll.offset - PAGE_TOP) / h) - 6, 0, n)
  hi = min(n, lo + ceil(Int, high / h) + 12)
  over = json_under(t)
  w = window_of(t)
  keys = w !== nothing && w.focus === t
  Column(width(grow=grow), Alignment.Start,
    spacer(h * lo), [json_row(t, e, i, i == over, keys) for i in lo+1:hi]..., spacer(h * (n - hi)))
end

cursor(t::JSONTree) = (i = json_under(t); i > 0 && json_length(t.rows[i].value) > 0 ? :hand : :arrow)

# A click chooses a row and gives the tree the keyboard. On an object or a list it opens it or closes it,
# and with ⌥ it opens or closes everything in it too.
onkey(t::JSONTree, ev::KeyPress{Keys.mouse_left}) = begin
  i = json_under(t)
  focus(t)
  i == 0 && return handled
  t.chosen = i
  json_toggle!(t, i, all=Keys.opt in ev.window.keys)
  handled
end

"Choose row `i`, and scroll the page so that it's in the window"
json_choose!(t::JSONTree, i) = begin
  isempty(t.rows) && return handled
  t.chosen = clamp(i, 1, length(t.rows))
  e = editor(t)
  r = rect(t)
  r === nothing && return handled
  h = json_row_h(e)
  top = r.top + h * (t.chosen - 1)   # where the row is in the window
  _, high = window_size(e)
  top < TOPBAR_H + h ? scroll_page!(e, top - TOPBAR_H - h) : top + 2h > high ? scroll_page!(e, top + 2h - high) : nothing
  handled
end

onkey(t::JSONTree, ::KeyPress{Keys.down}) = json_choose!(t, t.chosen + 1)
onkey(t::JSONTree, ::KeyPress{Keys.up}) = json_choose!(t, max(1, t.chosen - 1))
# → opens a closed row, and goes into one that's open
onkey(t::JSONTree, ::KeyPress{Keys.right}) = begin
  i = t.chosen
  i == 0 && return json_choose!(t, 1)
  json_length(t.rows[i].value) == 0 && return handled
  json_opened(t, i) ? json_choose!(t, i + 1) : (json_toggle!(t, i); handled)
end
# ← closes an open row, and goes out of one that's closed, to the row that holds it
onkey(t::JSONTree, ::KeyPress{Keys.left}) = begin
  i = t.chosen
  i == 0 && return json_choose!(t, 1)
  json_opened(t, i) && return (json_toggle!(t, i); handled)
  d = t.rows[i].depth
  d == 0 ? handled : json_choose!(t, findprev(r -> r.depth < d, t.rows, i))
end
onkey(t::JSONTree, ::KeyPress{Keys.enter}) = (t.chosen > 0 && json_toggle!(t, t.chosen); handled)
onkey(t::JSONTree, ev::KeyPress{Keys.c}) = begin
  Keys.cmd in ev.window.keys || return nothing
  t.chosen > 0 && clipboard(json_copy(t.rows[t.chosen].value))
  handled
end

"Show the JSON file of the page as its text, or as a tree again"
json_level!(e) = begin
  b = e.buf
  shown = look(b.path, tree=b.view == :text)
  b.lines, b.about, b.view = shown.lines, shown.about, shown.view
  b.caret = b.anchor = (1, 0)
  b.saved = b.version += 1
  e.scroll.offset = 0px
  focus(e)
  e
end

# A whole file of code or of text starts at the left of the page, not in the
# middle of it as a page's text is, and has the number of each line beside it.
# The number of the line that the caret is in is a little darker. The list of
# the files in a zip has no numbers.

const NUMBER_GAP = 14px   # between the numbers of the lines and the text

"True when the page shows a whole file of code or of text, which can have the number of each line beside it"
numbered(b::Buffer) = b.view == :code || (b.view == :text && !(lowercase(splitext(b.path)[2]) in ZIPS))

"The font of the numbers of the lines: a little smaller and fainter than the code"
number_face(e) = (code = face(e, Line(Kind.code, 0, 0, "")); Face(code, size=code.size * 0.9, color=colours.faint))

"True when the page shows the number of each line beside it: a file of code or of text, unless the settings page hid them"
numbers(e) = numbered(e.buf) && e.numbers

"How much room the numbers of the page's lines take beside the text, with the gap between them. A page with no numbers takes none."
gutter(e) = numbers(e) ? measure(number_face(e), "0") * max(2, ndigits(length(e.buf.lines))) + NUMBER_GAP : 0px

const capitals = Dict{Tuple{String,String,Float32},px}()

"How tall a capital letter of `face` is"
capital(face::Face) = get!(capitals, (face.family, face.style, Float32(num(face.size)))) do
  metrics = Ref{Skia.sk_font_metrics_t}()
  Skia.sk_font_get_metrics(skia_font(face.family, face.size, face.style).raw, metrics)
  px(metrics[].capHeight)
end

"Write the number of each line on screen beside the line. The page's text starts at `left`, and its first line is at `top`."
draw_numbers(ctx, e, left, top) = begin
  b = e.buf
  numbers(e) || return
  f = number_face(e)
  # A number stands on the line that its line of code stands on
  rise = capital(face(e, Line(Kind.code, 0, 0, "")))
  for it in e.layout[e.shown]
    flow = it.content
    flow isa Flow || continue
    words = string(it.first)
    here = !caretless(b) && !readonly(b) && it.first == b.caret[1]
    x = left - NUMBER_GAP - measure(f, words)
    y = top + it.top + line_top(flow, 1) + (flow.lines[1].high + rise) / 2
    write_ink(ctx, words, num(x), num(y), here ? Face(f, color=colours.dim) : f)
  end
end

# A line of a file of code or of text that's too long for the window goes on
# under itself, at the window's right edge. The part under it starts one step of
# indentation further in than the line does, so it doesn't look like a line of
# its own. The settings page can turn that off. Then a long line goes on past
# the edge of the window, and the page scrolls sideways to show the rest of it,
# under the numbers of the lines. The caret stays in sight as it moves.
#
# The settings page has more for code. A file of code can show the numbers of
# its lines or not, shade the line that the caret is on, and have a faint line
# down it after a number of characters, to show where a line gets too long. In
# all code, in a file or in a page, it sets how big the code is and how many
# spaces one step of indentation is.

const INDENTS = (2, 4)                  # the steps of indentation that the settings page offers
const GUIDES = (0, 80, 92, 100, 120)    # the places for the line down a file of code. 0 is no line.
const CODE_SCALES = (0.4, 2.5)          # the least and most that code can be, beside the page's text
const SIDE_ROOM = 40px   # how near the caret gets to the left or right of the window before the page scrolls sideways

"True when the long lines of the page go on under themselves. Only a file of code or of text can have them go on past the window."
wraps(e) = e.wrap || !numbered(e.buf)

"How far the page is scrolled to the right"
sideways(e) = wraps(e) ? 0px : e.buf.across

"How far the page can scroll to the right: as far as the longest line goes past the right of the window"
sideways_room(e) = max(0px, e.reach + SIDE_ROOM - e.width)

"Scroll the page `by` to the right, as far as it goes"
scroll_sideways!(e, by) = (e.buf.across = clamp(e.buf.across + by, 0px, sideways_room(e)); e)

"""
Two fingers that move sideways on the trackpad, or the wheel with ⇧ held,
scroll the page sideways. Their move up or down still scrolls the page up or down.
"""
swipe!(e, ev::MouseScroll) = begin
  (wraps(e) || ev.delta[1] == 0px) && return nothing
  scroll_sideways!(e, -30ev.delta[1])
  ev.delta[2] == 0px ? handled : nothing
end
onscroll(d::Document, ev::MouseScroll) = swipe!(editor(d), ev)
onscroll(p::Page, ev::MouseScroll) = swipe!(editor(p), ev)

"How far the lines of `f` go, from the left of the text"
extent(f::Flow) = maximum(vl -> isempty(vl.segs) ? vl.x : last(vl.segs).x + last(vl.segs).w, f.lines)

"Turn on or off the wrapping of a line of a file of code that's too long for the window"
wrap!(e, on::Bool) = (e.wrap = on; save_settings!(e); rerun!(e, :wrap); restyle!(e))

"Show or hide the numbers of the lines of a file of code"
numbers!(e, on::Bool) = (e.numbers = on; save_settings!(e); rerun!(e, :numbers); restyle!(e))

"Shade the line of a file of code that the caret is on, or don't"
shade!(e, on::Bool) = (e.shade = on; save_settings!(e); rerun!(e, :shade); e)

"Make one step of indentation in code `n` spaces: 2 or 4"
indent_width!(e, n::Int) = begin
  n in INDENTS || error("A step of indentation is 2 or 4 spaces. $n isn't one of them.")
  e.indent = n
  save_settings!(e)
  rerun!(e, :indent)
  restyle!(e)
end

"Put the faint line down a file of code after `n` characters. 0 takes the line away."
guide!(e, n::Int) = begin
  n in GUIDES || error("The line goes after 80, 92, 100 or 120 characters, or 0 for none. $n isn't one of them.")
  e.guide = n
  save_settings!(e)
  rerun!(e, :guide)
  e
end

"Draw code in the font called `family`, in the weight that the settings choose or the nearest one it has"
code_font!(e, family::String) = begin
  installed_weight(family, 400) > 0 || error("This Mac has no font called $family.")
  e.code_font = family
  use_code_font!(e)
  save_settings!(e)
  rerun!(e, :code_font)
  restyle!(e)
end

"Draw code in the weight called `w`, like \"Light\", or in the weight `w`, like 300"
code_weight!(e, w::Union{Integer,AbstractString}) = begin
  e.code_weight = w isa Integer ? text_weight(w) : weight_called(e.code_font, w)
  use_code_font!(e)
  save_settings!(e)
  rerun!(e, :code_weight)
  restyle!(e)
end

"How big code is: a part of the size of the page's text, so it grows and shrinks with it"
code_size(e) = body(e).size * e.code_scale

"Make code `size` pixels tall, for a live block. The text of the page stays the size it is."
code_size!(e, size) = (e.code_scale = clamp(size / num(body(e).size), CODE_SCALES...); rewrap!(e))

"The spaces of one step of indentation, in a block of the kind `block`. In code the settings page chooses how many."
indentation(e, block) = block === CodeBlock ? " "^e.indent : STEP

"Lay out `text`, line `i` of a file that shows as text. It has no background of its own and starts at the edge of the page."
file_line(e, text, line::Line, i::Int) = begin
  ps = spare(pieces(e, text, line, false, i))
  # Lines of bigger code are further apart
  lh, size = code_size(e) * 1.5 / CODE_SCALE, face(e, line).size
  wraps(e) || return wrap(ps, px(Inf); lh, size)
  # The spaces at the start of the line, and one step more, though half the page is always left for the text
  indent = match(r"^[ \t]*", text).match
  hang = min(measure(face(e, line), indent * " "^e.indent), e.width / 2)
  wrap(ps, e.width; lh, size, hang)
end

"""
The lines of a file that shows as text, laid out. Each is a line of code. The
whole page is code, so the lines have no background of their own and start at
the edge of the page.
"""
text_items(e, b::Buffer) = begin
  ks = kinds(b)
  items = Vector{Item}(undef, length(b.lines))
  top = 0px
  for (i, text) in enumerate(b.lines)
    f = file_line(e, text, ks[i], i)
    items[i] = Item(i, i, top, tall(f), f)
    top += tall(f)
  end
  items
end

"What the page shows for a file that doesn't show as text: a viewer of its kind, or words that say it's a binary file"
@def mutable struct FileView <: SemanticUI
  path::String = ""
  viewer::Any = nothing   # the STLViewer, the player or the Pages of the file, kept from one frame to the next
  table::Any = nothing    # the FileSheet of a CSV file: its table, and what's chosen for it
  button::Any = nothing   # the HexButton of a binary file
end

"The button under the words that say a file is binary. A click shows the file's bytes."
@def mutable struct HexButton <: SemanticUI end

describe(b::HexButton) = Box(height(30px), padding(14px, 0px), radius(6px), background(ishovered(b) ? colours.active : colours.hover),
                             label("View as hexadecimal", 13px))
cursor(::HexButton) = :hand
onkey(b::HexButton, ::KeyPress{Keys.mouse_left}) = (hex!(editor(b)); handled)

cursor(::FileView) = :arrow

"The one item of the page of a file that shows in a viewer"
file_item(e, b::Buffer) = begin
  v = node!(() -> FileView(path=b.path), e, (:fileview, b.path))
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(v)), (e.width, 9999px))
  high = concrete.height + 2LIVE_GAP
  Item(1, 1, 0px, high, Live(v, high))
end

"The picture kept under `key`, `wide` across, and no wider than the page's text"
fitted(e, key, wide; line=false) = begin
  source = image_source(key)
  w = min(e.width, px(wide))
  h = w * source.height / source.width
  line ? Image(key, fixed(w), height(h), radius(3px), border(1px, :solid, colours.line)) : Image(key, fixed(w), height(h), radius(4px))
end

"""
What shows the file of `v`, or nothing if Ladder has nothing that shows it.
`note(words)` adds words to the line that says how big the file is.
"""
viewer(v::FileView, e, note) = begin
  path = v.path
  ext = lowercase(splitext(path)[2])
  mac = Sys.isapple()
  _, h = window_size(e)
  room = clamp(h - TOPBAR_H - PAGE_TOP - 150px, 240px, 800px)   # how tall a model or a video shows
  # What's made for the file is kept, so the model stays as it was turned and the file plays on
  made(make, T) = v.viewer isa T ? v.viewer : (v.viewer = own!(v, make()))
  if ext in PICTURES || ext in MAC_PICTURES
    key = picture_key(path)
    key === nothing && return nothing
    source = image_source(key)
    # A picture of pixels is a pixel to the px. One that macOS read, like an SVG, is the size that macOS says it is.
    size = something(natural(key), (source.width, source.height))
    note("$(round(Int, size[1])) × $(round(Int, size[2]))")
    return fillable(v, (:picture, key), fitted(e, key, size[1]))
  elseif ext in MODELS
    m = made(() -> STLViewer(path=path), STLViewer)
    zoomed_node(e, m) || (m.height = room)   # one that fills the window is as tall as the window
    return load!(m) isa Mesh ? fillable(v, (:node, m), m, wide=:grow) : nothing
  elseif mac && ext in SOUNDS
    return made(() -> AudioPlayer(path=path), AudioPlayer)
  elseif mac && ext in VIDEOS
    p = made(() -> VideoPlayer(path=path), VideoPlayer)
    zoomed_node(e, p) || (p.height = room)
    return fillable(v, (:node, p), p, wide=video_wide(p))
  elseif mac && ext == ".pdf"
    p = made(() -> Pages(path=path, count=pdf_pages(path)), Pages)
    p.count == 0 && return nothing
    p.wide = e.width
    return p
  elseif ext in JSONS
    root = json_of(path)
    root === nothing && return nothing
    t = made(() -> JSONTree(path=path), JSONTree)
    t.root === root || plant!(t, root)   # a file that changed shows afresh
    json_holder(root) && note(json_count(root))
    return t
  elseif ext in TABLES
    return sheet_view(v, e, note)
  end
  # The picture that the Finder shows: the first page of a Word file, the letters of a font,
  # and what it has for many kinds of file that have no viewer here
  key = thumbnail(path)
  key === nothing && return nothing
  fillable(v, (:picture, key), fitted(e, key, image_source(key).width / 2, line=ext in DOCUMENTS))   # the picture has two pixels to the px
end

describe(v::FileView) = begin
  e = editor(v)
  # A Text on its own would take the whole width and start at the left, so each is in a box that the column centres
  words(parts) = Column(width(grow=grow), padding(90px, 0px, 30px, 0px), child_gap=10px, [p isa Text ? Box(p) : p for p in parts]...)
  isfile(v.path) || return words((label("$(basename(v.path)) isn't there any more", 15px),))
  about = bytes(filesize(v.path)) * "  ·  Changed " * Libc.strftime("%-d %b %Y, %H:%M", mtime(v.path))
  filesize(v.path) == 0 && return words((label("$(basename(v.path)) is empty", 15px), label(about, 12px, color=colours.dim)))
  # A model and a player are components, so they get the colours and the text size that a live block gives them
  with_theme(component_theme(e.zoom)) do
    content = try
      viewer(v, e, more -> (about *= "  ·  " * more))
    catch
      nothing
    end
    line = label(about, 12px, color=colours.dim)
    if content === nothing
      # Nothing shows this file, so the page says what it is, and its bytes are a click away
      v.button === nothing && (v.button = own!(v, HexButton()))
      return words((Icon("file-earmark-binary", size=34px, color=colours.faint), label("$(basename(v.path)) is a binary file", 15px),
                    line, Box(height(4px)), v.button))
    end
    # A table can be long, so what's said about it is in the top bar, where it stays in sight while the table scrolls
    if lowercase(splitext(v.path)[2]) in TABLES
      e.buf.path == v.path && (e.buf.about = about)
      return Box(width(grow=grow), Alignment.Start, content)
    end
    # A tree can be long, so the line about it is over it. Anything else has the line under it.
    lowercase(splitext(v.path)[2]) in JSONS ? Column(width(grow=grow), Alignment.Start, child_gap=10px, line, content) :
                                              Column(width(grow=grow), child_gap=10px, content, Box(line))
  end
end

# --- a CSV file in the page -------------------------------------------------------------------
#
# A CSV file that the sidebar opens shows as a table as wide as the window has
# room for. Each column is as wide as its first rows need, up to `WIDEST_CELL`,
# and a table that's narrower than the window shares the rest of the room
# among its columns. A table that's wider than the window scrolls sideways: two
# fingers that move sideways on the trackpad, or the wheel with ⇧ held. Text
# that's too long for its column stops with an …. The row of headings stays at
# the top of the window while the rows scroll under it. A thin line with round
# corners goes round the table.
#
# A click on a heading opens a menu. Its first part puts the rows in the order
# of that column, A to Z or Z to A, and a click on the order that the rows have
# now puts them back in the file's order. A column of numbers goes in the order
# of its numbers. Empty cells go last in both orders.
#
# The menu's second part shows fewer rows. A column with no more than
# `FEW_VALUES` different values lists them, each with how many rows have it. A
# click on a value ticks it, and only the rows with a ticked value show. Any
# other column has a field, and only the rows with its words in that column
# show. Return keeps what the field holds, and esc puts back what it held
# before. The heading of a column that shows fewer rows is in the accent
# colour, with a funnel beside it. The top bar says how big the file is, when
# it last changed, and how many rows show. It's there and not over the table,
# so the words stay in sight while the table scrolls. The table starts nearer
# the top bar than the text of a page does, so the window shows more rows.
#
# Ladder reads `FILE_ROWS` rows of the file at most. When the file changes on
# the disk and its headings stay the same, the table keeps its order and what
# it shows.

const FILE_ROWS = 100_000       # the most rows of a CSV file that the page reads
const FILE_BYTES = 40_000_000   # and the most of the file that it reads
const HEAD_H = 30px             # how tall the row of headings is
const CELL_PAD = 10px           # on each side of a cell's text
const SHEET_LINE = 1px          # the line round the table
const SHEET_ROUND = 6px         # how round the corners of that line are
const SHEET_ABOVE = 4px         # the room over the table. With LIVE_GAP, the table is 12px under the top bar.
const WIDEST_CELL = 360px       # the widest a column is before the columns share the room that's left
const FEW_VALUES = 20           # a column with no more different values than this lists them in its menu
const SHEET_MENU_W = 240px
const SHEET_KEY = :sheet_column

"The table of a CSV file that the page shows, and what's chosen for it"
mutable struct FileSheet
  table::Csvs.Table
  at::Float64                      # when the file last changed, when it was read
  natural::Vector{px}              # how wide each column needs to be, up to WIDEST_CELL
  widths::Vector{px}               # how wide each column is in the page
  wide::px                         # how wide the page was when the widths were worked out
  sort::Any                        # the column that the rows are in the order of and :asc or :desc, or nothing for the file's order
  filters::Dict{Int,String}        # the words that a column's cells must have, for each column that has some
  picks::Dict{Int,Set{String}}     # the values that show, for each column whose menu lists its values and has some ticked
  sought::Any                      # what the rows were last found for: the order, and what each column keeps
  found::Vector{Int}               # the rows that show, in the order that they show in. Row 1 is the headings.
  values::Dict{Int,Any}            # each column's values with how many rows have each, or nothing when it has more than FEW_VALUES
  asking::Int                      # the column whose menu is open, or 0
  was::Any                         # what that column kept when its menu opened, which esc puts back
  field::Any                       # the text field of the menu
  parts::Dict{Any,Any}             # the headings and the lines of the menu, kept between frames
  across::px                       # how far the table is scrolled to the right
  cut::Dict{Tuple{Int,Int},Tuple{px,String}}   # the text of a cell as it shows, with the width that it was cut short for
end

"The font of a cell, or of a heading with `bold`"
cell_face(bold=false) = Face(SANS, bold ? "Semibold" : "", 12px, colours.ink, false)

"""
The table in the CSV file at `path`, read for the page. When `old` is the
table that the file had before and the headings are the same, the new one
keeps its order, what it shows, and how far it's scrolled.
"""
file_sheet(path, old) = begin
  t = Csvs.load(path, most=FILE_ROWS, upto=FILE_BYTES)
  rows = t.rows
  head, plain = cell_face(true), cell_face()
  # A heading has room for the arrow of its order beside it
  need(r, c) = measure(r == 1 ? head : plain, first(celltext(rows[r][c]), 300)) + (r == 1 ? 14px : 0px)
  natural = [clamp(maximum(r -> need(r, c), 1:min(length(rows), 200)), 24px, WIDEST_CELL) + 2CELL_PAD for c in eachindex(t.numbers)]
  s = FileSheet(t, mtime(path), natural, copy(natural), 0px, nothing, Dict{Int,String}(), Dict{Int,Set{String}}(), nothing, Int[],
                Dict{Int,Any}(), 0, nothing, nothing, Dict{Any,Any}(), 0px, Dict{Tuple{Int,Int},Tuple{px,String}}())
  if old isa FileSheet && !isempty(rows) && !isempty(old.table.rows) && old.table.rows[1] == rows[1]
    s.sort, s.filters, s.picks, s.across = old.sort, old.filters, old.picks, old.across
    s.asking, s.was, s.field, s.parts = old.asking, old.was, old.field, old.parts
  end
  s
end

"Share the page's width `wide` among the columns of `s`. A table that's narrower than the page grows, each column by its share."
spread!(s::FileSheet, wide) = begin
  s.wide == wide && return s
  total = sum(s.natural, init=0px)
  s.widths = total < wide ? s.natural .* (num(wide) / num(total)) : copy(s.natural)
  s.wide = wide
  empty!(s.cut)
  s
end

"True when column `c` of `s` shows only some rows"
narrowed(s::FileSheet, c::Int) = haskey(s.filters, c) || haskey(s.picks, c)
"True when some column of `s` shows only some rows"
narrowed(s::FileSheet) = !isempty(s.filters) || !isempty(s.picks)

"Keep only the rows that have `words` in column `column`. No words takes that away."
keep!(s::FileSheet, column::Int, words) = begin
  words = String(strip(words))
  isempty(words) ? delete!(s.filters, column) : (s.filters[column] = words)
  s
end

"""
The values of column `c` of `s`, each with how many rows have it, in the order
that the column puts them in. It's nothing when the column has more than
`FEW_VALUES` different values.
"""
values_of(s::FileSheet, c::Int) = get!(s.values, c) do
  counts = Dict{String,Int}()
  for r in 2:length(s.table.rows)
    value = s.table.rows[r][c]
    counts[value] = get(counts, value, 0) + 1
    length(counts) > FEW_VALUES && return nothing
  end
  [(value, counts[value]) for value in in_order(s.table, collect(keys(counts)), c, :asc, value -> value)]
end

"""
`items` in the order of column `c` of `t`, A to Z with `way` :asc and Z to A
with :desc. `cell(item)` is the text of the item's cell. In a column of
numbers, the cells that are numbers go in the order of their numbers, and come
before the rest. Empty cells go last whichever way.
"""
in_order(t::Csvs.Table, items, c, way, cell) = begin
  rev = way == :desc
  blank = [x for x in items if isempty(cell(x))]
  full = [(x, lowercase(cell(x))) for x in items if !isempty(cell(x))]
  if t.numbers[c]
    found = [(x, Charts.number(cell(x))) for (x, _) in full]
    numbers = sort!([(x, n[1]) for (x, n) in found if n !== nothing], by=last, rev=rev)
    words = sort!([(x, lowercase(cell(x))) for (x, n) in found if n === nothing], by=last, rev=rev)
    return [first.(numbers); first.(words); blank]
  end
  [first.(sort!(full, by=last, rev=rev)); blank]
end

"""
The rows of `s` that show, in the order that they show in: the rows that have
each column's words in that column and one of its ticked values, in the order
of the column that's chosen. When they change, a page that was scrolled down
the table goes back to the top of the table.
"""
sheet_rows!(e, s::FileSheet) = begin
  key = (s.sort, copy(s.filters), Dict(c => copy(p) for (c, p) in s.picks))
  key == s.sought && return s.found
  rows = s.table.rows
  words = [(c, lowercase(w)) for (c, w) in s.filters]
  keep = [r for r in 2:length(rows) if all(((c, w),) -> occursin(w, lowercase(rows[r][c])), words) &&
                                       all(((c, p),) -> rows[r][c] in p, s.picks)]
  s.sort === nothing || (keep = in_order(s.table, keep, s.sort[1], s.sort[2], r -> rows[r][s.sort[1]]))
  s.sought === nothing || (e.scroll.offset = min(e.scroll.offset, sheet_top()))
  s.sought, s.found = key, keep
  keep
end

"How far the top of the table of a CSV file is under the top of the page"
sheet_top() = SHEET_ABOVE + LIVE_GAP + SHEET_LINE

"The text of row `r`, column `c` of `s`, as it shows in a column that's `room` wide: on one line, and cut short with an … when it's too long"
shown_cell(s::FileSheet, r, c, room, face=cell_face(r == 1)) = begin
  kept = get(s.cut, (r, c), nothing)
  kept !== nothing && kept[1] == room && return kept[2]
  length(s.cut) > 50_000 && empty!(s.cut)
  text = first(celltext(s.table.rows[r][c]), 300)
  while measure(face, text) > room && length(text) > 1
    text = first(text, max(1, floor(Int, (length(text) - 1) * num(room) / num(measure(face, text))) - 1)) * "…"
  end
  s.cut[(r, c)] = (room, text)
  text
end

"A node of the headings or of the menu of the table of `v`, kept between frames"
sheet_part!(make, v, key) = get!(() -> own!(v, make()), (v.table::FileSheet).parts, key)

"""
The table of the CSV file that `v` shows, or nothing when the file has no
table. It's as wide as the page and as tall as all the rows that show, but only
the rows in the window are made. The headings stay at the top of the window
while the page is scrolled down the table. `note(words)` adds to what the top
bar says of the file.
"""
sheet_view(v, e, note) = begin
  at = mtime(v.path)
  (v.table isa FileSheet && v.table.at == at) || (v.table = file_sheet(v.path, v.table))
  s = v.table::FileSheet
  isempty(s.table.problem) || return nothing
  # What the field of a heading's menu holds is what its column keeps, as it's typed
  s.asking > 0 && s.field !== nothing && values_of(s, s.asking) === nothing && keep!(s, s.asking, s.field.text)
  found = sheet_rows!(e, s)
  n, total = length(found), length(s.table.rows) - 1
  held = s.table.more ? "the first $(commas(total)) rows" : "$(commas(total)) row$(total == 1 ? "" : "s")"
  note(n < total || narrowed(s) ? "$(commas(n)) of $held" : held)
  wide = e.width - 2SHEET_LINE   # the room inside the line round the table
  spread!(s, wide)
  room = sum(s.widths, init=0px)
  s.across = clamp(s.across, 0px, max(0px, room - wide))
  _, h = window_size(e)
  into = e.scroll.offset - sheet_top()   # how far the top of the window is past the top of the table
  lo = clamp(floor(Int, (into - HEAD_H) / ROW_H) - 4, 0, n)
  hi = min(n, lo + ceil(Int, h / ROW_H) + 8)
  plain = cell_face()
  row(k) = (r = found[k];
    Row(fixed(room), height(ROW_H), Alignment.Start, background(iseven(k) ? colours.stripe : clear),
      [Row(fixed(w), height(ROW_H), padding(CELL_PAD, 0px), Alignment.Center, clip=true, label(shown_cell(s, r, c, w - 2CELL_PAD, plain), 12px))
       for (c, w) in enumerate(s.widths)]...))
  none = n == 0 ? (Box(fixed(min(room, wide)), height(2ROW_H), label("No row has what the headings keep.", 12px, color=colours.dim)),) : ()
  rows = Column(fixed(room), Alignment.Start, spacer(HEAD_H + ROW_H * lo), [row(k) for k in lo+1:hi]..., spacer(ROW_H * (n - hi)), none...)
  heads = Row(fixed(room), height(HEAD_H), Alignment.Start, background(colours.head),
    [sheet_part!(() -> SheetHead(of=v, column=c), v, (:head, c)) for c in eachindex(s.widths)]...)
  # The headings are over the rows, and move down with the window until the rows end
  stick = clamp(into, 0px, ROW_H * max(n - 1, 0))
  table = Stack(fixed(room), Alignment.Start, rows, Box(Alignment.Start, offset_y=stick, heads))
  frame = sheet_part!(() -> SheetFrame(of=v), v, :frame)
  frame.wide, frame.inside = e.width, Box(Alignment.Start, offset_x=-s.across, table)
  frame
end

"The line round a CSV file's table, which has round corners. The table scrolls sideways inside it."
@def mutable struct SheetFrame <: SemanticUI
  of::Any = nothing       # the FileView
  wide::px = 0px          # how wide it is, with its line
  inside::Any = nothing   # what's in it in this frame: the table, as far to the left as it's scrolled
end

describe(f::SheetFrame) = Row(fixed(f.wide), Alignment.Start, padding(SHEET_LINE), clip_x=true, name="Table frame", detach!(f.inside))
cursor(::SheetFrame) = :arrow

# The rows of the table have square ends, so the page's colour goes over what of them is outside the
# round corners. The line goes round on top of that.
draw(ctx, size, ui::ConcreteRect, f::SheetFrame) = begin
  x, y, w, h, r = num(ui.left), num(ui.top), num(ui.width), num(ui.height), num(SHEET_ROUND)
  shape = Skia.sk_path_new()
  rect = Ref(Skia.sk_rect_t(Float32(x), Float32(y), Float32(x + w), Float32(y + h)))
  Skia.sk_path_add_rounded_rect(shape, rect, Float32(r), Float32(r), Skia.SK_PATH_DIRECTION_CW)
  Skia.sk_canvas_save(ctx)
  Skia.sk_canvas_clip_path_with_operation(ctx, shape, Skia.SK_CLIP_OP_DIFFERENCE, true)
  foreach(((cx, cy),) -> round_box(ctx, cx, cy, r, r, 0; fill=colours.bg), ((x, y), (x + w - r, y), (x, y + h - r), (x + w - r, y + h - r)))
  Skia.sk_canvas_restore(ctx)
  Skia.sk_path_delete(shape)
  line = num(SHEET_LINE)
  round_box(ctx, x + line / 2, y + line / 2, w - line, h - line, r - line / 2; line=colours.line, wide=line)
  nothing
end

# Two fingers that move sideways, or the wheel with ⇧ held, scroll a wide table sideways. Their move up or down scrolls the page.
onscroll(v::FileView, ev::MouseScroll) = begin
  s = v.table
  (s isa FileSheet && ev.delta[1] != 0px) || return nothing
  s.across = clamp(s.across - 30ev.delta[1], 0px, max(0px, sum(s.widths, init=0px) - s.wide))
  ev.delta[2] == 0px ? handled : nothing
end

"The heading of a column of a CSV file's table. A click on it opens the column's menu."
@def mutable struct SheetHead <: SemanticUI
  of::Any = nothing   # the FileView
  column::Int = 1
end
"The menu of a column of a CSV file's table: its two orders, and what shows fewer rows"
@def mutable struct SheetMenu <: SemanticUI
  of::Any = nothing
  column::Int = 1
end
"One of the two orders in the menu of a column of a CSV file's table"
@def mutable struct SheetOrder <: SemanticUI
  of::Any = nothing
  way::Symbol = :asc
end
"A value in the menu of a column of a CSV file's table. A click ticks it, or takes the tick away."
@def mutable struct SheetValue <: SemanticUI
  of::Any = nothing
  value::String = ""
  count::Int = 0
end

describe(h::SheetHead) = begin
  s = h.of.table::FileSheet
  c = h.column
  w = s.widths[c]
  way = s.sort !== nothing && s.sort[1] == c ? s.sort[2] : nothing
  lit = ishovered(h) || s.asking == c
  fewer = narrowed(s, c)
  colour = fewer ? colours.accent : colours.ink
  # The funnel of a column that shows fewer rows, and the arrow of its order. With neither, the mouse over the heading shows that it opens.
  marks = ((fewer ? (Icon("funnel-fill", size=9px, color=colours.accent),) : ())...,
           (way !== nothing ? (Icon(way == :asc ? "chevron-up" : "chevron-down", size=9px, color=colours.ink),) :
            lit && !fewer ? (Icon("chevron-down", size=9px, color=colours.faint),) : ())...)
  room = w - 2CELL_PAD - 13px * length(marks)
  Row(fixed(w), height(HEAD_H), padding(CELL_PAD, 0px), child_gap=4px, Alignment.Center, clip=true,
      background(lit ? colours.hover : clear),
    Box(label(shown_cell(s, 1, c, max(room, 12px)), 12px, color=colour, weight="Semibold")), marks...)
end

cursor(::SheetHead) = :hand
onmouse(::SheetHead, ::MouseMove) = handled

onkey(h::SheetHead, ev::KeyPress{Keys.mouse_left}) = begin
  v = h.of
  s = v.table::FileSheet
  c = h.column
  listed = values_of(s, c) !== nothing
  s.asking = c
  s.was = listed ? (haskey(s.picks, c) ? copy(s.picks[c]) : nothing) : get(s.filters, c, "")
  # The menu's field starts with what the column keeps, which esc puts back
  if !listed
    s.field === nothing && (s.field = own!(v, TextInput(placeholder="Contains…", font_family=SANS, font_size=13px,
                                                        look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))))
    s.field.text = s.was
    s.field.cursor = s.field.anchor = length(s.was)
  end
  menu = sheet_part!(() -> SheetMenu(of=v), v, :menu)
  menu.column = c
  e = editor(v)
  # A click outside the menu closes it and keeps what's chosen
  popup!(ev.window, menu, anchor=h, placement=:below, gap=4px, width=SHEET_MENU_W, key=SHEET_KEY,
         onclose=() -> (v.table isa FileSheet && (v.table.asking = 0); focus(e)), theme=component_theme(e.zoom))
  listed || focus(s.field)
  handled
end

"Close the menu of the table of `v`, and give the keyboard back to the page"
close_sheet_menu!(v) = begin
  v.table isa FileSheet && (v.table.asking = 0)
  w = window_of(v)
  w === nothing || close_popup!(w, SHEET_KEY)
  focus(editor(v))
  handled
end

describe(m::SheetMenu) = begin
  v, c = m.of, found_colours()
  s = v.table::FileSheet
  section(words) = Row(width(grow=grow), height(22px), padding(8px, 0px), Alignment.Center, label(words, 10px, color=c.dim, weight="Semibold"))
  order(way) = sheet_part!(() -> SheetOrder(of=v, way=way), v, (:sort, way))
  values = values_of(s, m.column)
  value(text, count) = (r = sheet_part!(() -> SheetValue(of=v, value=text), v, (:value, m.column, text)); r.count = count; r)
  fewer = values === nothing ?
    (section("FILTER FOR"),
     Box(width(grow=grow), padding(4px, 2px),
       Box(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), border(1px, :solid, c.line), background(c.frame), s.field))) :
    (section("SHOW"), [value(text, count) for (text, count) in values]...)
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Column menu",
    Column(width(grow=grow), Alignment.Start,
      section("SORT"), order(:asc), order(:desc),
      Box(width(grow=grow), height(13px), Alignment.Center, Box(width(grow=grow), height(1px), background(c.rule))),
      fewer...))
end

# The menu sees a key before its text field does. Return keeps what's chosen, and esc puts back what the column kept before.
onkey(m::SheetMenu, ::KeyPress{Keys.enter}) = close_sheet_menu!(m.of)
onkey(m::SheetMenu, ::KeyPress{Keys.escape}) = begin
  s = m.of.table::FileSheet
  if values_of(s, m.column) === nothing
    keep!(s, m.column, s.was)
  else
    s.was === nothing ? delete!(s.picks, m.column) : (s.picks[m.column] = s.was)
  end
  close_sheet_menu!(m.of)
end

describe(r::SheetOrder) = begin
  s, c = r.of.table::FileSheet, found_colours()
  on = s.sort == (s.asking, r.way)
  numbers = s.asking > 0 && s.table.numbers[s.asking]
  words = numbers ? (r.way == :asc ? "Smallest first" : "Largest first") : (r.way == :asc ? "A–Z" : "Z–A")
  Row(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      background(on || ishovered(r) ? c.pick : c.frame),
    Icon(r.way == :asc ? "chevron-up" : "chevron-down", size=10px, color=on ? c.ink : c.dim),
    label(words, 13px, color=on ? c.ink : c.dim, weight=on ? "Semibold" : ""))
end

cursor(::SheetOrder) = :hand
onmouse(::SheetOrder, ::MouseMove) = handled
# A click on the order that the rows have puts them back in the file's order
onkey(r::SheetOrder, ::KeyPress{Keys.mouse_left}) = (s = r.of.table::FileSheet; s.sort = s.sort == (s.asking, r.way) ? nothing : (s.asking, r.way); handled)

describe(r::SheetValue) = begin
  s, c = r.of.table::FileSheet, found_colours()
  ticked = get(s.picks, s.asking, nothing)
  on = ticked !== nothing && r.value in ticked
  Row(width(grow=grow), height(26px), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      background(ishovered(r) ? c.pick : c.frame),
    Box(fixed(10px), (on ? (Icon("check", size=10px, color=c.ink),) : ())...),
    Box(width(grow=grow), Alignment.Start, clip_x=true,
      label(isempty(r.value) ? "Empty" : r.value, 13px, color=isempty(r.value) || !(on || ticked === nothing) ? c.dim : c.ink, weight=on ? "Semibold" : "")),
    Box(label(commas(r.count), 11px, color=c.dim)))
end

cursor(::SheetValue) = :hand
onmouse(::SheetValue, ::MouseMove) = handled
# A click ticks the value, or takes the tick away. With every value ticked, or none, every row shows.
onkey(r::SheetValue, ::KeyPress{Keys.mouse_left}) = begin
  s = r.of.table::FileSheet
  c = s.asking
  ticked = get!(Set{String}, s.picks, c)
  r.value in ticked ? delete!(ticked, r.value) : push!(ticked, r.value)
  (isempty(ticked) || length(ticked) == length(values_of(s, c))) && delete!(s.picks, c)
  handled
end

"What the live block with this code shows"
live(e, code::String) = begin
  key = (:live, e.buf.path, code)
  node = get!(e.nodes, key) do
    shown = Shown(value=evaluate(e, code))
    shown.value isa SemanticUI && own!(shown, shown.value)
    old = pop!(e.nodes, (:replaced, key), nothing)
    old isa Shown && carry!(shown.value, old.value)
    shown
  end
  own!(node!(Document, e, :document), node)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(node)), (e.width, 9999px))
  Live(node, concrete.height + 2LIVE_GAP)
end

# --- diagrams -----------------------------------------------------------------------
#
# A code block in the language `mermaid` shows the diagram that its code
# describes: a flowchart, a sequence diagram, a state diagram, a class diagram,
# a pie chart, a mind map, an entity relationship diagram, a Gantt chart or a
# timeline. UI.jl's Mermaid component reads the code and draws it. Click
# it with ⌥ held to see its code, or as plain text put the caret in the block.
# A diagram of the first five kinds can be changed while it fills the window:
# see "a picture, a diagram or a page that fills the window". The last four
# fill the window too, and are changed in their code.

const DIAGRAM = "mermaid"

"True when `code` is the code of a diagram that can be drawn"
isdiagram(code::AbstractString) = problem(code) === nothing

"What the `mermaid` block with this code shows: its diagram, or nothing if the code can't be drawn as one"
diagram(e, code::String) = begin
  isdiagram(code) || return nothing
  # A Shown gives the diagram the page's colours and font, as it does for what a live block makes
  node = get!(e.nodes, (:diagram, code)) do
    shown = Shown(value=Mermaid(code))
    own!(shown, shown.value)
    shown
  end
  own!(node!(Document, e, :document), node)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(node)), (e.width, 9999px))
  Live(node, concrete.height + 2LIVE_GAP)
end

# --- formulas ---------------------------------------------------------------------------
#
# A formula is written in TeX between dollar signs. $x^2$ is a formula in a
# line of text. A formula on lines of its own goes between a line of $$ and
# another, or between $$ and $$ on one line, or in a code block in the language
# `math`. It's in the middle of the page, and its fractions and sum signs are
# bigger. math.jl reads the TeX and says where each character goes.
#
# In a line of text the formula is one thing: the caret goes over it in one
# step, and ⌘E shows its TeX. On lines of its own it's a part of the page, as
# a diagram is: the caret goes onto it as a whole, and Return shows its TeX.

"A formula as it's set: in a line of text, or with `display` on lines of its own in the middle of the page"
@def mutable struct Equation <: SemanticUI
  tex::String = ""
  size::px = TEXT_SIZE         # of the text that it's in
  display::Bool = false
  colour::Any = nothing        # of the text that it's in, or nothing for the page's ink
  mid::px = 0px                # in a line of text: how far the middle of the line's capital letters is over the line they stand on
end

"The formula of `m`, with where each of its characters goes"
typeset(m::Equation) = Maths.formula(m.tex, num(m.size), m.display)

"How far a formula in a line of text goes over and under the middle of the line. A row of the page puts the middle of each thing in it at the same height."
half_height(m::Equation) = (f = typeset(m); px(max(Maths.height(f) - num(m.mid), Maths.depth(f) + num(m.mid))))

describe(m::Equation) = begin
  f = typeset(m)
  m.display ? Box(width(grow=grow), height(px(Maths.height(f) + Maths.depth(f)))) : Box(fixed(px(Maths.wide(f))), height(2half_height(m)))
end

draw(ctx, size, ui::ConcreteRect, m::Equation) = begin
  f = typeset(m)
  # On lines of its own it's in the middle of the page. In a line of text it stands on the line that the letters stand on.
  x = m.display ? ui.left + max(0px, ui.width - px(Maths.wide(f))) / 2 : ui.left
  y = m.display ? ui.top + px(Maths.height(f)) : ui.top + half_height(m) + m.mid
  Maths.paint(ctx, f, num(x), num(y), something(m.colour, colours.ink), colours.accent)
  nothing
end

# The mouse over a formula that has a command that Ladder doesn't know says which. Two lines with the
# same text show the same formula, so the words go under the mouse, not under where the formula was drawn.
onmouse(m::Equation, ev::MouseMove) = begin
  words = tip(m)
  isempty(words) && return nothing
  x, y = ev.position
  show_tooltip!(ev.window, tip_label(words), x - 1px, y - 10px, 2px, 20px, placement=:bottom, gap=6px)
  nothing
end

"What the mouse over a formula says: the commands of its TeX that Ladder doesn't know, or nothing when it knows them all"
tip(m::Equation) = (unknown = unique(typeset(m).problems); isempty(unknown) ? "" : "Ladder doesn't know " * join(unknown, ", ", " or "))

"The piece that stands for the formula of span `s`, in text drawn in `base`"
equation(e, s::Span, base::Face) = begin
  m = Equation(tex=s.text, size=base.size, colour=base.color, mid=capital(base) / 2)
  # It's part of its line, which is laid out once and kept. It can reach the document, and it isn't one of the document's children.
  setfield!(m, :parent, node!(Document, e, :document))
  piece(s.text, s.col, base, atomic=true, n=length(s.text), node=Inline(m, px(Maths.wide(typeset(m))), 2half_height(m)))
end

const MATHS_LINE = r"^\s*\$\$(.*\S.*)\$\$\s*$"

"The TeX of a line that holds only a formula between \$\$ and \$\$, or nothing for any other line"
maths_text(text::AbstractString) = begin
  m = match(MATHS_LINE, text)
  m === nothing || occursin("\$\$", m[1]) ? nothing : String(strip(m[1]))
end

"True when line `i` holds only a formula between \$\$ and \$\$, which shows on a line of its own"
maths_line(b::Buffer, i::Int) =
  kinds(b)[i].kind == Kind.paragraph && occursin("\$\$", b.lines[i]) && maths_text(b.lines[i]) !== nothing && Maths.available()

"True when `tex` is a formula that can be set: it has something in it, and the Mac has the font for maths"
has_maths(tex::AbstractString) = !isempty(strip(tex)) && Maths.available()

const MATHS_SMALLEST = 0.5   # how small a formula that's wider than the page gets, as a part of the size of the text

"What a formula on lines of its own shows, or nothing if `tex` can't be set"
equation_item(e, tex) = begin
  (tex === nothing || !has_maths(tex)) && return nothing
  m = get!(() -> Equation(tex=String(tex), display=true), e.nodes, (:equation, String(tex)))
  own!(node!(Document, e, :document), m)
  m.size = body(e).size
  # A formula that's wider than the page is smaller, so that all of it shows
  wide = px(Maths.wide(typeset(m)))
  wide > e.width && (m.size *= max(MATHS_SMALLEST, e.width / wide))
  f = typeset(m)
  Live(m, px(Maths.height(f) + Maths.depth(f)) + 2LIVE_GAP)
end

# --- takeoffs ---------------------------------------------------------------------------
#
# A code block in the language `takeoff` shows a plan that you measure from: a
# page of a PDF file, or a picture. takeoff.jl says how the block is written.
# Click it with ⌥ held to see its lines, or as plain text put the caret in the block.
#
#   - Drop a PDF file or a picture on the block, or click it, to choose the plan.
#   - Set the scale: type it, like 1:100, or choose the ruler, click the two ends
#     of a length that you know and type how long it is.
#   - Two buttons under the table start a measure. Add a measure asks what it
#     measures: type a few words that describe it, like "Double power point".
#     Its item is defined later: the measure is matched to one in Centient.
#     Add from catalogue asks for an item of Centient's catalogue, and shows
#     only on a Mac that has Centient. The item gives the measure its name, and
#     its unit says what the measure is and chooses the tool: a length for an
#     item sold by the metre, an area for one sold by the square metre, and a
#     count for the rest.
#   - A measure with no item and nothing drawn yet is what the tool you choose
#     makes it. A click on a measure in the list chooses its tool too.
#   - The table has no column for a measure's name. A measure with no item
#     shows its words, and a click on them, when it's the measure that's
#     chosen, changes them. A measure with an item shows the item's name, then
#     the catalogue that it's from, and the same click chooses another item.
#   - The table has columns for the price of one and for the cost while a
#     measure has an item. With none, there's no price to show.
#   - What a search of Centient finds shows in a list that floats beside the
#     text field. The search for an item looks in one catalogue at a time: the
#     business's own items, or a supplier's that ⌥ lets you choose. The headings of the table of measures sort and search it.
#   - A click on the unit after a measure's amount lists the units that it can
#     be in, as Centient's unit picker does. Type to search them. The amount
#     shows in the unit that you choose, and the quote's line is in it too. A
#     measure with nothing drawn and no item can take a unit of another kind,
#     and that changes what it measures.
#   - A count takes a mark for each click. A length and an area take a corner for
#     each click. To end one, click the Done button beside its last corner,
#     click twice, or press Return. An area also ends with a click on its
#     first corner.
#   - A corner snaps to the lines of a PDF plan: to the end of a line, to the
#     place where two lines cross, or to the nearest point of a line. A small
#     mark shows where it will go. It snaps to the corners of what's already
#     measured too. The magnet turns snapping off, and so does ⌘ while it's held.
#   - The tool after the area tool cuts a shape out of an area, like a window
#     out of a wall. Draw its outline over the area. What the area comes to is
#     then without the part of the cut-out that's in it. A cut-out is selected,
#     moved and taken away like any outline, and it goes when its area does.
#   - With the arrow, click a mark or a line to select it, drag a corner to move
#     it, and press Delete to take it away. Drag the plan to move it.
#   - A mouse wheel makes the plan bigger and smaller round the mouse, and so
#     does a pinch. Two fingers on the trackpad move the plan. With ⌘ held, they
#     make it bigger and smaller. In the page, the wheel and two fingers move
#     the page until you click the plan. A plan that shows whole stays put.
#   - The button with four arrows makes the block fill the window, with the list
#     of measures beside the plan or under it. Esc puts it back in the page.
#   - V, C, L, A, X and S choose the tools. Esc drops what's half drawn. ⌘Z takes
#     the last change back.
#   - Choose the customer, then Make quote in Centient. Centient makes a quote
#     with a line for each measure. A measure with an item is priced from the
#     catalogue. One with none is a line of its words, to price in Centient.
#
# Every change is written into the block's lines, so the file holds the whole
# takeoff. The catalogue, the contacts and the quote come from Centient through
# its MCP server, which centient.jl starts. Centient's app needn't be open.

const TAKEOFF = Plans.TAKEOFF
const PLAN_LEAST = 220px      # how tall the plan's view is at the least
const REACH = 7.0             # px. A corner or a line that's this near the mouse is under it.
const SNAP = 8.0              # px. A corner that's put this near a line of the plan goes on the line.
const NEAR = 24.0             # the most px to a point of the page: as big as the plan gets
const SETTLED = 0.15          # seconds after the plan last moved until a plan that's slow to draw is drawn sharp
const QUICK = 0.012           # seconds. A plan that's drawn in less is drawn sharp while it moves.
const MOST_FOUND = 8          # the lines of the list under a search
const SIDE_W = 380px          # how wide the list of measures is beside a plan that fills the window
const HUES = (colorant"rgb(222,72,58)", colorant"rgb(38,120,214)", colorant"rgb(30,150,90)", colorant"rgb(232,140,24)",
              colorant"rgb(140,84,208)", colorant"rgb(18,160,170)", colorant"rgb(214,70,150)", colorant"rgb(128,104,72)")
"The tools of a takeoff, in the order of their buttons: the icon of each, what it says of itself, and the letter that chooses it"
const PLAN_TOOLS = (:select => ("cursor", "Select and move  V", 'v'), :count => ("plus-circle", "Count  C", 'c'),
                    :length => ("vector-pen", "Measure a length  L", 'l'), :area => ("pentagon", "Measure an area  A", 'a'),
                    :cut => ("subtract", "Cut a shape out of an area  X", 'x'),
                    :scale => ("rulers", "Set the scale from a length that you know  S", 's'))
"Every icon that a takeoff can show. The built app reads them all when it's made."
const PLAN_ICONS = ["cursor", "plus-circle", "vector-pen", "pentagon", "rulers", "chevron-left", "chevron-right", "zoom-out", "zoom-in",
                    "aspect-ratio", "file-earmark-pdf", "x-lg", "plus-lg", "map", "person", "receipt", "arrows-fullscreen", "fullscreen-exit",
                    "chevron-up", "chevron-down", "check", "subtract", "magnet", "box-seam"]

"True when the page's theme is a dark one"
dark_page() = RGBA(colours.bg).r < 0.5
"""
What's behind the plan's paper, round the table of measures and at the foot of
a takeoff: the theme's colour for things that float over the page, which is a
little lighter than the page. In a dark page it's the page's own colour.
"""
takeoff_back() = dark_page() ? colours.bg : colours.float

"The colour of the measure at place `i` in the list"
hue(i) = HUES[mod1(i, length(HUES))]

"The part of a page of a PDF plan that a takeoff shows, as a picture that Skia draws. It's kept until the view moves."
mutable struct Sharp
  of::Any                         # what it's a picture of
  image::Ptr{Skia.sk_image_t}
  cost::Float64                   # seconds that the last one took to draw
end

"What a `takeoff` block shows: the plan, the tools and the list of measures"
@def mutable struct TakeoffView <: SemanticUI
  n::Int = 0                              # its place among the page's takeoffs
  first::Int = 0                          # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Plans.Takeoff = Plans.Takeoff()
  lines::Vector{String} = String[]        # the lines that `data` was read from
  tool::Symbol = :select
  current::Int = 0                        # the measure that the tools draw for: its place in the list, or 0
  picked::Any = nothing                   # what's selected on the plan: the place of its measure and its shape, and of its point if it's one corner
  draft::Vector{Plans.Point} = Plans.Point[]   # the corners so far of what's being drawn
  zoom::Float64 = 0.0                     # px to a point of the page. 0 fits the page in the view.
  at::Plans.Point = (0.0, 0.0)            # the point of the page at the view's top left
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the view was last drawn in the window: its left, top, width and height
  fitted::Any = nothing                   # the file and the page that the zoom is for
  mouse::Any = nothing                    # the point of the page under the mouse, or the one near it that a corner snaps to
  aim::Any = nothing                      # what `mouse` snapped to: :corner, :crossing or :line, or nothing when it's where the mouse is
  snap::Bool = true                       # corners snap to the lines of the plan
  grab::Any = nothing                     # a drag: of the plan, or of a corner
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where the plan was last clicked
  moved::Float64 = 0.0                    # when the view last moved
  asking::Any = nothing                   # what the text field is for: (:name, i), (:item, i), (:extra, i), (:scale,), (:length, a, b) or (:customer,)
  query::String = ""                      # the words that were last searched for
  typed::Float64 = 0.0                    # when the words in the text field last changed
  search::Any = nothing                   # the search that Centient hasn't answered yet
  rows::Vector{Any} = Any[]               # what the last search found
  pick::Int = 1                           # the row of them that Return takes
  known::Dict{String,Any} = Dict{String,Any}()   # what Centient says of each item: its name, its unit, its price
  lookup::Any = nothing                   # the request for those that Centient hasn't answered yet
  quoting::Any = nothing                  # the request for a quote that Centient hasn't answered yet
  said::String = ""                       # what the foot of the block says
  wrong::Bool = false                     # it says what went wrong
  parts::Dict{Any,Any} = Dict{Any,Any}()  # its buttons, rows and text field, kept between frames
  sharp::Sharp = Sharp(nothing, C_NULL, 1.0)
  full::Bool = false                      # it fills the window, over the page
  beside::Bool = false                    # it fills the window with its list of measures beside the plan, not under it
  tall::px = 0px                          # how tall it was in the page when it was last laid out there
  pinned::px = 0px                        # how far the page was scrolled when it filled the window
  sort::Any = nothing                     # the column that the table of measures is sorted by, and which way: (:cost, :desc)
  filters::Dict{Symbol,String} = Dict{Symbol,String}()   # the words that a column's text must have for the table to show a measure
  order::Vector{Int} = Int[]              # the measures that the table shows, in the order that it shows them
  reads::UInt = UInt(0)                   # what its parts read, as one number. See `shown_state`.
  measured::Int = -1                      # the `version` of its geometry when `tall` was measured
end

"The part of a takeoff that shows the plan"
@def mutable struct PlanArea <: SemanticUI
  of::Any = nothing
end
"A button of a takeoff: a tool, a page arrow, the button that makes the quote"
@def mutable struct PlanButton <: SemanticUI
  of::Any = nothing
  action::Any = :none
  icon::String = ""
  words::String = ""
  tip::String = ""
  off::Bool = false                           # it does nothing now, and shows that
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
  quiet::Bool = false                         # clicked, so no tooltip until the mouse leaves it
end
"A measure in a takeoff's list"
@def mutable struct MeasureRow <: SemanticUI
  of::Any = nothing
  i::Int = 0
end
"The amount of a measure in its row: the number, then the unit that it's in"
@def mutable struct AmountCell <: SemanticUI
  of::Any = nothing
  i::Int = 0
  unit::Any = nothing   # its UnitWord
end
"The unit after a measure's amount. A click on it shows the list of units that the measure can be in."
@def mutable struct UnitWord <: SemanticUI
  of::Any = nothing     # the AmountCell
end
"The list of units that floats under a measure's amount, with a field that searches it"
@def mutable struct UnitMenu <: SemanticUI
  of::Any = nothing
  i::Int = 0
  side::Symbol = :bottom   # the side of the amount that it's on
  pick::Int = 0            # the row that was picked when it was last drawn. A row that the keys pick is brought in sight.
end
"A unit in the list of units"
@def mutable struct UnitRow <: SemanticUI
  of::Any = nothing
  k::Int = 0
end
"A part of a measure's row that a click changes: its item, or what it adds for waste"
@def mutable struct MeasureCell <: SemanticUI
  of::Any = nothing
  i::Int = 0
  what::Symbol = :item
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn: its width cuts its words short, and its tooltip goes under it
  full::String = ""                           # its words when they're cut short with …, to show in its tooltip, or "" when they fit
end
"""
The heading of a column of the table of measures. It fills the column's cell, so
the mouse can be anywhere over the column to use it. A click sorts by the
column, or opens a menu that sorts and searches it.
"""
@def mutable struct ColumnHead <: SemanticUI
  of::Any = nothing
  key::Symbol = :item
  side::Symbol = :start   # the side of the cell that its words go on: :start, or :end over numbers that line up on the right
  words::Any = nothing    # its HeadWords
end
"The words of a column's heading, and the arrow of its order. The heading's menu and tooltip point at them."
@def mutable struct HeadWords <: SemanticUI
  of::Any = nothing   # the heading
end
"The menu of a column of text: its two orders and a field to search it. It floats under the heading, as it does in Centient's lists."
@def mutable struct ColumnMenu <: SemanticUI
  of::Any = nothing
  key::Symbol = :item
  side::Symbol = :bottom   # the side of the heading that it's on
end
"One of the two orders in the menu of a column"
@def mutable struct SortRow <: SemanticUI
  of::Any = nothing
  key::Symbol = :item
  dir::Symbol = :asc
end
"A line of the list that a search shows: an item of Centient's catalogue, or a contact"
@def mutable struct FoundRow <: SemanticUI
  of::Any = nothing
  k::Int = 0
end
"The foot of the list of items: the catalogue that the list shows. A click on it shows another."
@def mutable struct CatalogueFoot <: SemanticUI
  of::Any = nothing
end
"""
The list of what a search found. It floats beside the text field with an arrow
that points at the field, the way the lists in Centient's own forms do.
"""
@def mutable struct FoundList <: SemanticUI
  of::Any = nothing
  side::Symbol = :bottom   # the side of the text field that it's on
  rows::Any = nothing      # what it showed last. A new list starts at its top.
  pick::Int = 0            # the row that was picked when it was last drawn. A row that the keys pick is brought in sight.
  popup::Any = nothing     # what UI.jl floats it in
  settled::Bool = false    # its side of the text field is chosen, and it keeps that side while it's open
end

"A part of `v` that's kept between frames"
part!(make, v::TakeoffView, key) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, v)
  node
end

"The text field of a takeoff. One field does for the name of a measure, a search, the scale and the rest."
plan_input(v::TakeoffView) = part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

# --- the plan's file ---------------------------------------------------------------------

"The file of the plan, or \"\" when the block names none that's there"
plan_path(v::TakeoffView) = begin
  isempty(v.data.plan) && return ""
  path = abspath(docdir(editor(v)), expanduser(unescaped(v.data.plan)))
  isfile(path) ? path : ""
end

ispdf(path) = lowercase(splitext(path)[2]) == ".pdf"

"How many pages the plan has"
plan_pages(v::TakeoffView) = (path = plan_path(v); isempty(path) ? 0 : ispdf(path) ? pdf_pages(path) : 1)

"""
How wide and how tall the page that shows is, in points, or nothing when there's
no plan to show. A picture has a point for each of its pixels.
"""
plan_size(v::TakeoffView) = begin
  path = plan_path(v)
  isempty(path) && return nothing
  ispdf(path) && return pdf_size(path, v.data.page)
  key = picture_key(path)
  key === nothing && return nothing
  source = image_source(key)
  (Float64(source.width), Float64(source.height))
end

"How tall the plan's view is in a block that's `w` wide: tall enough for the whole page, and no taller than leaves room for the list"
plan_h(v::TakeoffView, w::px) = begin
  s = plan_size(v)
  s === nothing && return 180px
  _, tall = window_size(editor(v))
  clamp((w - 2px(PAPER_EDGE)) * s[2] / s[1] + 2px(PAPER_EDGE), PLAN_LEAST, max(PLAN_LEAST, tall - 280px))
end

"Make the file at `path` the plan"
plan!(v::TakeoffView, path) = begin
  v.data.plan = named(editor(v), path)
  v.data.page = 1
  v.zoom = 0.0
  empty!(v.draft)
  commit!(v)
end

"Ask which file holds the plan, with macOS's own panel"
choose_plan!(v::TakeoffView, w) = begin
  # A window that isn't on the screen, like one a test makes, has no panel to ask with
  (Sys.isapple() && !isempty(w.glfw)) || return handled
  path = with_pool() do
    panel = msg(cls("NSOpenPanel"), "openPanel")
    msg(panel, "setDirectoryURL:", msg(cls("NSURL"), "fileURLWithPath:", nsstring(docdir(editor(v)))))
    # 1 is the panel's Open button
    ccall((:objc_msgSend, libobjc), Int, (Ptr{Cvoid}, Ptr{Cvoid}), panel, sel("runModal")) == 1 || return nothing
    jstring(msg(msg(panel, "URL"), "path"))
  end
  # The panel took the mouse, so the window never heard its button come up
  Keys.mouse_left in w.keys && (w.keys ⊻= Keys.mouse_left)
  path === nothing || plan!(v, path)
  handled
end

"The takeoff under the mouse, or nothing"
takeoff_at(e, w) = begin
  x, y = w.mouse
  for node in values(e.nodes)
    node isa TakeoffView || continue
    r = rect(node)
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return node
  end
  nothing
end

# --- the block's lines -------------------------------------------------------------------

"The first and the last line of the `n`th takeoff block of `b`, or nothing"
takeoff_lines(b::Buffer, n::Int) = block_lines(b, TAKEOFF, n)

"The first and the last line of the `n`th code block of `b` in the language `lang`, or nothing"
block_lines(b::Buffer, lang::String, n::Int) = begin
  ks = kinds(b)
  seen = 0
  for i in eachindex(ks)
    (ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == lang) || continue
    (seen += 1) == n || continue
    t = codeblock(b, i)[2]
    return t > i && ks[t].kind == Kind.fence && ks[t].level == 1 ? (i, t) : nothing
  end
  nothing
end

"Read the takeoff again from the lines of its block, if they've changed"
reread!(v::TakeoffView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Plans.takeoff(lines)
  v.current = min(v.current, length(v.data.measures))
  v.picked = nothing
  v
end

"""
Write the takeoff into its block. The caret stays where it was in the text, and
⌘Z takes the change back. If the block's lines aren't the ones that the takeoff
was read from, something else changed them, and the takeoff is read again.
"""
commit!(v::TakeoffView) = begin
  b = editor(v).buf
  readonly(b) && return v
  span = takeoff_lines(b, v.n)
  span === nothing && return v
  i, t = span
  v.first, v.last = i, t
  b.lines[i+1:t-1] == v.lines || return reread!(v, b.lines[i+1:t-1])
  new = Plans.written(v.data)
  new == v.lines && return v
  caret, anchor = b.caret, b.anchor
  edit!(b, line_end(b, i), line_end(b, t - 1), isempty(new) ? "" : "\n" * join(new, "\n"))
  by = length(new) - length(v.lines)
  moved(p) = p[1] >= t ? (p[1] + by, p[2]) : p[1] > i ? (i, 0) : p
  b.caret, b.anchor = moved(caret), moved(anchor)
  v.last += by
  v.lines = new
  v
end

"What the `takeoff` block from line `i` to line `t` shows. `n` is its place among the page's takeoffs."
takeoff_item(e, i, t, n) = begin
  v = get!(() -> TakeoffView(n=n), e.nodes, (:takeoff, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v.first, v.last = i, t
  reread!(v, e.buf.lines[i+1:t-1])
  # A takeoff that fills the window is drawn over the page, and its room in the page stays empty
  v.full && return Live(Box(width(grow=grow), height(v.tall)), v.tall + 2LIVE_GAP)
  # Lay it out once to learn how tall it is. While nothing that it shows changes, its geometry
  # is kept (see `shown_state`), and so is its height. Laid out again here at another height
  # than the page gives it, the page's layout of it couldn't be used again either.
  g = geometry(v)
  if version(v) == 0 || version(v) != v.measured
    v.tall = describe(Column(fixed(e.width), Alignment.Start, g), (e.width, 9999px)).height
    v.measured = version(v)
  end
  Live(v, v.tall + 2LIVE_GAP)
end

# --- Centient ----------------------------------------------------------------------------

"What Centient says of the item that `ref` names, or nothing if it hasn't said yet"
known(v::TakeoffView, ref) = isempty(ref) ? nothing : get(v.known, ref, nothing)

"Ask Centient for the items of the takeoff that it hasn't told of yet. The plan's view asks when it's drawn, so a takeoff that's out of sight asks nothing."
lookup!(v::TakeoffView) = begin
  v.lookup === nothing || return
  refs = unique!([m.item for m in v.data.measures if !isempty(m.item) && !haskey(v.known, m.item)])
  (isempty(refs) || !Centient.available()) && return
  # An item that Centient doesn't have is asked for once
  foreach(ref -> v.known[ref] = nothing, refs)
  v.lookup = Centient.ask("lookup_items", Dict("refs" => refs))
  nothing
end

"A sentence at the foot of the block. `wrong` shows it as something that went wrong."
say!(v::TakeoffView, words, wrong=false) = (v.said = String(words); v.wrong = wrong; handled)

"An amount of money: \$1,234.50"
dollars(x::Real) = begin
  cents = round(Int, 100x)
  (cents < 0 ? "-" : "") * "\$" * commas(abs(cents) ÷ 100) * "." * lpad(abs(cents) % 100, 2, '0')
end

"""
The price of one of measure `m`'s unit, from the catalogue's `row`. Centient's
price is for one of the item's unit, so an item sold at \$2 a foot is \$6.56 a
metre to a measure in metres. It's nothing when the item is sold by a unit
that `m` can't be in, like a price a metre for a count.
"""
unit_price(m, row) = begin
  u = string(something(get(row, "unit", nothing), ""))
  Plans.kind_for(u) == m.kind || return nothing
  # A unit that Centient doesn't name, like "lineal metre" or "each", is its kind's own
  row["price"] * get(Plans.UNIT_SIZES, Plans.unit(m), 1.0) / get(Plans.UNIT_SIZES, u, 1.0)
end

"What `amount` of its kind's own unit of measure `m` costs at the price of the catalogue's `row`"
cost_of(m, amount::Real, row) = begin
  p = unit_price(m, row)
  p === nothing ? amount * row["price"] : Plans.in_unit(amount, Plans.unit(m)) * p
end

"""
The line of a quote for measure `m`, which comes to `amount` of its kind's own
unit. The line is in the measure's unit, and Centient prices it from the item
in that unit. A measure with no item names none, and its line is its words,
to match to an item in Centient.
"""
quote_line(m, amount::Real) = begin
  unit = Plans.unit(m)
  line = Dict{String,Any}("quantity" => round(Plans.in_unit(amount, unit), sigdigits=6), "unit" => unit, "note" => m.name)
  isempty(m.item) || (line["ref"] = m.item)
  line
end

"Ask Centient for a quote with a line for each measure"
make_quote!(v::TakeoffView) = begin
  v.quoting === nothing || return handled
  t = v.data
  Centient.available() || return say!(v, "Centient isn't on this Mac, so Ladder can't make the quote", true)
  isempty(t.customer) && return say!(v, "Choose the customer first", true)
  lines = Any[]
  for m in t.measures
    amount = Plans.amount(t, m)
    amount === nothing && return say!(v, "Set the scale first, so that $(isempty(m.name) ? "each length" : m.name) has a size", true)
    amount > 0 || continue
    push!(lines, quote_line(m, amount))
  end
  isempty(lines) && return say!(v, "Nothing is measured yet", true)
  plan = isempty(t.plan) ? "" : " of " * basename(t.plan)
  v.quoting = Centient.ask("create_quote", Dict{String,Any}("customer" => t.customer, "notes" => "From a takeoff$plan in Ladder", "lines" => lines))
  say!(v, "Making the quote in Centient…")
end

"""
What happens to a takeoff in each frame, before the page is laid out: a drag
that ended is written down, the text field that lost the keyboard closes, and
Centient's answers are taken.
"""
tick!(v::TakeoffView) = begin
  w = window_of(v)
  v.grab !== nothing && !held(v, Keys.mouse_left) && drop!(v)
  # A click somewhere else took the keyboard from the text field
  v.asking !== nothing && w !== nothing && w.focus !== plan_input(v) && settle_asking!(v)
  waiting = false
  # A column shows what its search finds while you type
  v.asking !== nothing && v.asking[1] == :filter && search_column!(v, v.asking[2], plan_input(v).text)
  # The list of units shows the ones that match what's typed. New words pick the unit that they name, or the first.
  if v.asking !== nothing && v.asking[1] == :unit
    words = String(strip(plan_input(v).text))
    v.rows = Any[u for u in units_for(v, v.asking[2]) if unit_matches(u, words)]
    words == v.query || (v.query = words; v.pick = something(findfirst(u -> names_unit(u, words), v.rows), 1))
    v.pick = clamp(v.pick, 1, max(1, length(v.rows)))
  end
  if v.asking !== nothing && v.asking[1] in (:item, :customer)
    words = String(strip(plan_input(v).text))
    words == v.query || (v.query = words; v.typed = time(); v.pick = 1)
    # The search waits until the typing stops for a moment
    if v.typed > 0 && time() - v.typed > 0.2
      v.typed = 0.0
      from = ITEM_FROM[]
      v.search = v.asking[1] == :customer ? Centient.ask("find_contacts", Dict("query" => words)) :
                 from[1] == :suppliers    ? Centient.ask("list_catalogues", Dict("query" => words)) :
                 Centient.ask("search_catalogue", Dict("query" => words, "catalogue" => from[1] == :own ? "own" : from[2]))
    end
    waiting = v.typed > 0
  end
  Centient.check!()
  r = v.search
  if r !== nothing && Centient.finished(r)
    v.search = nothing
    if Centient.failed(r)
      v.rows = Any[]
      say!(v, r.problem, true)
    else
      v.rows = collect(Any, get(r.value, r.tool == "find_contacts" ? "contacts" : r.tool == "list_catalogues" ? "catalogues" : "items", Any[]))
      v.pick = clamp(v.pick, 1, max(1, length(v.rows)))
    end
  end
  r = v.lookup
  if r !== nothing && Centient.finished(r)
    v.lookup = nothing
    Centient.failed(r) || foreach(row -> v.known[row["ref"]] = row, get(r.value, "items", Any[]))
  end
  r = v.quoting
  if r !== nothing && Centient.finished(r)
    v.quoting = nothing
    if Centient.failed(r)
      say!(v, r.problem, true)
    else
      v.data.made = string(get(r.value, "number", ""))
      company = Centient.server.company
      say!(v, "Centient has quote $(v.data.made) for $(dollars(get(r.value, "total", 0.0))) with GST" * (isempty(company) ? "" : ", in $company"))
      commit!(v)
    end
  end
  # While Centient works, the window looks again soon
  (waiting || v.search !== nothing || v.lookup !== nothing || v.quoting !== nothing) && redraw_in!(v, 0.1)
  v
end

"Do what each takeoff of the page that shows needs in this frame"
takeoff_tick!(e) = for (key, node) in collect(e.nodes)
  (node isa TakeoffView && key[2] == e.buf.path) || continue
  tick!(node)
  node.full || continue
  # A takeoff whose block has gone goes back to the page. Under one that fills the window, the page stays where it was.
  takeoff_lines(e.buf, node.n) === nothing ? (node.full = false) : (e.scroll.offset = node.pinned)
end

# --- the text field ----------------------------------------------------------------------

"Close the text field, if it shows. What's typed in it is kept, but nothing is chosen from a list."
settle_asking!(v::TakeoffView) = v.asking === nothing ? handled : v.asking[1] in (:item, :customer, :unit) ? stop_asking!(v) : answer!(v)

"Show the text field for `what`, with `text` in it and selected"
ask!(v::TakeoffView, what, text="", placeholder="") = begin
  settle_asking!(v)
  i = plan_input(v)
  i.color = colours.ink
  i.text, i.placeholder = String(text), String(placeholder)
  i.anchor, i.cursor = 0, length(i.text)
  v.asking = what
  v.rows, v.pick, v.search = Any[], 1, nothing
  v.query, v.typed = "\0", 0.0   # no words yet, so the first look at the field starts a search
  v.said, v.wrong = "", false
  focus(i)
  if what[1] == :item
    # The list starts on the catalogue that an item was last chosen from, and not on the list of suppliers
    ITEM_FROM[][1] == :suppliers && (ITEM_FROM[] = (:own,))
    i.placeholder = "⌥ to toggle catalogue"
  end
  what[1] in (:item, :customer) && Centient.available() && show_found!(v)
  handled
end

"Take the text field away. The keyboard goes back to the plan."
stop_asking!(v::TakeoffView) = begin
  v.asking = nothing
  v.rows, v.search = Any[], nothing
  w = window_of(v)
  w === nothing || (close_popup!(w, FOUND_KEY); close_popup!(w, HEAD_KEY); close_popup!(w, UNIT_KEY))
  w !== nothing && w.focus === plan_input(v) && focus(part!(() -> PlanArea(of=v), v, :area))
  handled
end

"The number of metres that `text` says: 3.6, 3.6m or 3600mm. It's nothing when it says none."
metres_typed(text) = begin
  m = match(r"^\s*(\d+(?:\.\d+)?)\s*(mm|cm|m)?\s*$", lowercase(text))
  m === nothing && return nothing
  n = parse(Float64, m[1]) * (m[2] == "mm" ? 0.001 : m[2] == "cm" ? 0.01 : 1.0)
  n > 0 ? n : nothing
end

"Give page `page` the scale `n`. A plan's first scale is for all its pages. After that, a page gets a scale of its own."
scale!(v::TakeoffView, n) = begin
  t = v.data
  page = t.page
  key = isempty(t.scales) || plan_pages(v) <= 1 || (length(t.scales) == 1 && haskey(t.scales, 0) && page == 1) ? 0 : page
  t.scales[key] = round(n, digits=1)
  commit!(v)
end

"Take row `k` of what a search found"
choose_row!(v::TakeoffView, k::Int) = begin
  a = v.asking
  (a === nothing || !(1 <= k <= length(v.rows))) && return stop_asking!(v)
  row = v.rows[k]
  # A supplier in the list of suppliers opens its catalogue. The search goes on there.
  a[1] == :item && haskey(row, "slug") && return browse!(v, (:catalogue, string(row["slug"]), string(row["name"])))
  if a[1] == :customer
    v.data.customer = string(row["name"])
  elseif a[2] <= length(v.data.measures)
    m = v.data.measures[a[2]]
    was = known(v, m.item)
    # A measure that still has the name it was made with, or its old item's name, takes the new item's name
    (isempty(m.name) || occursin(FIRST_NAME, m.name) || (was !== nothing && m.name == was["name"])) &&
      (m.name = replace(string(row["name"]), '|' => '/'))
    m.item = string(row["ref"])
    v.known[m.item] = row
    # The item's unit says what the measure is, and the tool for it is ready to draw
    kind = Plans.kind_for(get(row, "unit", nothing))
    isempty(m.shapes) && m.kind != kind && (m.kind = kind; m.unit = "")
    # The amount shows in the unit that the item is sold by, when the measure can be in it
    sold = string(something(get(row, "unit", nothing), ""))
    Plans.unit_kind(sold) == m.kind && Plans.unit!(m, sold)
    stop_asking!(v)
    commit!(v)
    v.current = a[2]
    tool!(v, m.kind)
    m.kind == kind || say!(v, "Centient's price for $(row["name"]) is for $(sold_by(row)), and this measure is $(KIND_WORDS[m.kind])", true)
    return handled
  end
  stop_asking!(v)
  commit!(v)
  handled
end

"Do what the text field was for with what's typed in it"
answer!(v::TakeoffView) = begin
  a = v.asking
  a === nothing && return handled
  text = String(strip(plan_input(v).text))
  t = v.data
  # A column's search changes what the table shows, and nothing in the block
  a[1] == :filter && return (search_column!(v, a[2], text); stop_asking!(v))
  a[1] == :unit && return isempty(v.rows) ? stop_asking!(v) : unit!(v, a[2], v.rows[clamp(v.pick, 1, length(v.rows))])
  if a[1] in (:item, :customer)
    isempty(v.rows) || return choose_row!(v, v.pick)
    # Nothing to choose from. An empty field takes the item away, and a customer is kept as it's typed.
    a[1] == :item && isempty(text) && a[2] <= length(t.measures) && (t.measures[a[2]].item = "")
    a[1] == :customer && !isempty(text) && (t.customer = text)
  elseif a[1] == :name
    a[2] <= length(t.measures) && !isempty(text) && (t.measures[a[2]].name = replace(text, '|' => '/'))
  elseif a[1] == :extra
    n = tryparse(Float64, strip(replace(text, '%' => "", '+' => "")))
    a[2] <= length(t.measures) && (t.measures[a[2]].extra = n === nothing ? 0.0 : clamp(n, 0, 1000) / 100)
  elseif a[1] == :scale
    n = Plans.scale(text)
    n === nothing ? say!(v, "A scale is written like 1:100", true) : scale!(v, n)
  elseif a[1] == :length
    real = metres_typed(text)
    n = real === nothing ? nothing : Plans.scale(a[2], a[3], real)
    n === nothing ? say!(v, "Type the length in metres, like 3.6", true) : scale!(v, n)
    empty!(v.draft)
    v.tool = :select
  end
  stop_asking!(v)
  commit!(v)
  handled
end

# The keys of the text field that the field has no use for come here
onkey(v::TakeoffView, ::KeyPress{Keys.enter}) = v.asking === nothing ? nothing : answer!(v)
onkey(v::TakeoffView, ::KeyPress{Keys.escape}) = begin
  v.asking === nothing && return nothing
  v.asking[1] == :length && (empty!(v.draft); v.tool = :select)
  stop_asking!(v)
end
# ⌥ in an empty search for an item changes the catalogue that the list shows
onkey(v::TakeoffView, ::KeyPress{Keys.opt}) = begin
  a = v.asking
  (a !== nothing && a[1] == :item && Centient.available() && isempty(strip(plan_input(v).text))) || return nothing
  toggle_catalogue!(v)
end
onkey(v::TakeoffView, ::KeyPress{Keys.down}) = v.asking === nothing ? nothing : (v.pick = min(v.pick + 1, max(1, length(v.rows))); handled)
onkey(v::TakeoffView, ::KeyPress{Keys.up}) = v.asking === nothing ? nothing : (v.pick = max(v.pick - 1, 1); handled)

# --- the view of the plan ----------------------------------------------------------------

"The point of the page that's at a place in the window"
page_point(v::TakeoffView, x, y) = (v.at[1] + (x - v.box[1]) / v.zoom, v.at[2] + (y - v.box[2]) / v.zoom)

"The place in the window of a point of the page"
window_point(v::TakeoffView, p) = (v.box[1] + (p[1] - v.at[1]) * v.zoom, v.box[2] + (p[2] - v.at[2]) * v.zoom)

# The lines of the pages of PDF plans that were last shown, each with a grid that finds the ones near the mouse.
# Each is kept under its file, when the file last changed, and its page.
const plan_lines = Dict{Any,Plans.Lines}()

"The lines of the page that shows, for corners to snap to. A picture has none, and nor has a PDF file that's a scan of paper."
lines_of(v::TakeoffView) = begin
  path = plan_path(v)
  (isempty(path) || !ispdf(path)) && return Plans.Lines()
  key = (path, mtime(path), v.data.page)
  kept = get(plan_lines, key, nothing)
  kept === nothing || return kept
  length(plan_lines) >= 4 && empty!(plan_lines)
  s = pdf_size(path, v.data.page)
  found = pdf_lines(path, v.data.page)
  plan_lines[key] = s === nothing || found === nothing ? Plans.Lines() : Plans.Lines(found[1], s[1], s[2], found[2])
end

"""
The point of the page where a corner goes when the mouse is at a place in the
window, and what it snapped to there: :corner, :crossing or :line. With the
magnet off or ⌘ held, and where nothing is near, it's the point under the
mouse, and nothing. `skip` is a corner that it doesn't snap to: the one that's
being dragged.
"""
aim(v::TakeoffView, w, x, y; skip=nothing) = begin
  p = page_point(v, x, y)
  (v.snap && !(Keys.cmd in w.keys)) || return (p, nothing)
  something(Plans.snap(v.data, lines_of(v), v.data.page, p, SNAP / v.zoom, skip=skip), (p, nothing))
end

"The px of white that the view keeps round the paper, so that the paper's edge and its shadow show"
const PAPER_EDGE = 14.0

"How many px to a point fits the whole page in the view, with white round it"
fit_zoom(v::TakeoffView, s) = max(min((v.box[3] - 2PAPER_EDGE) / s[1], (v.box[4] - 2PAPER_EDGE) / s[2]), 1e-3)

"Show the whole page, in the middle of the view"
fit!(v::TakeoffView, s) = begin
  v.zoom = fit_zoom(v, s)
  v.at = ((s[1] - v.box[3] / v.zoom) / 2, (s[2] - v.box[4] / v.zoom) / 2)
  v
end

"""
Keep the page in the view. Where the page is narrower than the view, it stays
in the middle, and so it does where it's shorter. So the plan only moves once
it's bigger than the view, and then no further than its edges, with the
white that the view keeps round the paper. `s` is the page's size in points.
"""
hold!(v::TakeoffView, s) = begin
  w, h = v.box[3] / v.zoom, v.box[4] / v.zoom
  e = PAPER_EDGE / v.zoom
  v.at = (s[1] <= w ? (s[1] - w) / 2 : clamp(v.at[1], -e, s[1] - w + e),
          s[2] <= h ? (s[2] - h) / 2 : clamp(v.at[2], -e, s[2] - h + e))
  v
end

"Note that the view moved just now, and keep the page in it"
moved!(v::TakeoffView) = begin
  v.moved = time()
  s = plan_size(v)
  s === nothing ? v : hold!(v, s)
end

"Make the plan `by` times as big. The point of the page at the place `(x, y)` in the window stays there."
zoom_plan!(v::TakeoffView, by, x, y) = begin
  s = plan_size(v)
  (s === nothing || v.zoom <= 0) && return handled
  p = page_point(v, x, y)
  v.zoom = clamp(v.zoom * by, fit_zoom(v, s), NEAR)   # never smaller than the whole page
  v.at = (p[1] - (x - v.box[1]) / v.zoom, p[2] - (y - v.box[2]) / v.zoom)
  moved!(v)
  handled
end

"Go on by `by` pages"
page!(v::TakeoffView, by) = begin
  page = clamp(v.data.page + by, 1, max(1, plan_pages(v)))
  page == v.data.page && return handled
  v.data.page = page
  v.zoom = 0.0
  v.picked = nothing
  empty!(v.draft)
  commit!(v)
  handled
end

# --- drawing -----------------------------------------------------------------------------

"How many of the screen's pixels a px is wide on the canvas `ctx`"
density(ctx) = begin
  m = Ref(Skia.sk_matrix_t(1f0, 0f0, 0f0, 0f0, 1f0, 0f0, 0f0, 0f0, 1f0))
  Skia.sk_canvas_get_total_matrix(ctx, m)
  sqrt(abs(m[].scaleX * m[].scaleY - m[].skewX * m[].skewY))
end

const plan_sampling = Skia.sk_sampling_options_t(0, false, Skia.sk_cubic_resampler_t(0f0, 0f0),
                                                 Skia.SK_FILTER_MODE_LINEAR, Skia.SK_MIPMAP_MODE_NONE)

"Draw the part `from` of a picture of Skia's into the part `to` of the window. Each is a left, a top, a width and a height."
paint_picture(ctx, image, from, to) = begin
  a = Ref(Skia.sk_rect_t(Float32(from[1]), Float32(from[2]), Float32(from[1] + from[3]), Float32(from[2] + from[4])))
  b = Ref(Skia.sk_rect_t(Float32(to[1]), Float32(to[2]), Float32(to[1] + to[3]), Float32(to[2] + to[4])))
  paint = Skia.sk_paint_new()
  Skia.sk_paint_set_antialias(paint, true)
  Skia.sk_canvas_draw_image_rect(ctx, image, a, b, Ref(plan_sampling), paint, Skia.SRC_RECT_CONSTRAINT_FAST)
  Skia.sk_paint_delete(paint)
end

"The part of a page of a PDF plan that the view shows, drawn at the screen's own pixels and kept until the view moves"
sharpen!(v::TakeoffView, path, of, k, x, y, w, h) = sharpen!(v.sharp, path, v.data.page, of, k, x, y, w, h)

"""
The part of page `page` of the PDF file at `path` that's `w` by `h` pixels and
starts `x` and `y` pixels into the page drawn `k` pixels to the point. It's kept
in `p` while `of`, what it's a picture of, stays the same.
"""
sharpen!(p::Sharp, path, page, of, k, x, y, w, h) = begin
  p.of == of && return p.image
  started = time()
  pixels = pdf_part(path, page, k, x, y, w, h)
  p.image == C_NULL || Skia.sk_image_unref(p.image)
  p.image, p.of = C_NULL, of
  pixels === nothing && return C_NULL
  info = Ref(Skia.sk_image_info_t(C_NULL, Skia.SK_COLOR_TYPE_BGRA_8888, Skia.SK_ALPHA_TYPE_PREMUL, w, h))
  GC.@preserve info pixels begin
    data = Skia.sk_data_new_with_copy(pointer(pixels), UInt64(4w * h))
    p.image = Skia.sk_image_new_raster_data(info, data, Csize_t(4w))
    Skia.sk_data_unref(data)
  end
  p.cost = time() - started
  p.image
end

"How round the corners of the plan's paper are, in px"
const PAPER_ROUND = 3.0

"""
Draw the plan's paper, with what shows where it ends on the white behind it:
a soft shadow under it and a thin line round it. Its corners are a little round.
"""
paper!(ctx, (x, y, w, h)) = begin
  shape(grow, down) = begin
    path = Skia.sk_path_new()
    rect = Ref(Skia.sk_rect_t(Float32(x - grow), Float32(y - grow + down), Float32(x + w + grow), Float32(y + h + grow + down)))
    Skia.sk_path_add_rounded_rect(path, rect, Float32(PAPER_ROUND + grow), Float32(PAPER_ROUND + grow), Skia.SK_PATH_DIRECTION_CW)
    path
  end
  fill(path, paint) = (Skia.sk_canvas_draw_path(ctx, path, paint); Skia.sk_paint_delete(paint); Skia.sk_path_delete(path))
  shadow = ink(RGBA(0, 0, 0, 0.2))
  blur = Skia.sk_maskfilter_new_blur_with_flags(Skia.SK_BLUR_STYLE_NORMAL, 6f0, true)
  Skia.sk_paint_set_maskfilter(shadow, blur)
  fill(shape(0, 2), shadow)
  Skia.sk_maskfilter_unref(blur)
  # The line is outside the paper, so the plan doesn't cover it
  fill(shape(0.5, 0), ink(RGBA(0, 0, 0, 0.16), 1))
  fill(shape(0, 0), ink(colorant"white"))
end

"Draw the page of the plan that shows. `s` is its size in points."
draw_plan(ctx, v::TakeoffView, s) = begin
  left, top, wide, tall = v.box
  path = plan_path(v)
  # Where the paper is in the window
  x, y = window_point(v, (0.0, 0.0))
  paper = (x, y, s[1] * v.zoom, s[2] * v.zoom)
  paper!(ctx, paper)
  # What's on the paper is cut off at the paper's round corners
  with_round_clip(() -> plan_ink(ctx, v, s, path, paper), ctx, px(paper[1]), px(paper[2]), px(paper[3]), px(paper[4]), px(PAPER_ROUND))
end

"Draw what's on the paper: the picture, or the part of the PDF page that's in the view"
plan_ink(ctx, v::TakeoffView, s, path, paper) = begin
  left, top, wide, tall = v.box
  if !ispdf(path)
    key = picture_key(path)
    key === nothing || paint_picture(ctx, image_source(key).raw, (0, 0, s[1], s[2]), paper)
    return
  end
  # Never fewer than 2 pixels to the px, so that the plan is sharp on paper too
  d = clamp(density(ctx), 2, 3)
  w, h = round(Int, wide * d), round(Int, tall * d)
  (w < 1 || h < 1) && return
  k = v.zoom * d   # the screen's pixels to a point of the page
  of = (path, mtime(path), v.data.page, k, v.at, w, h)
  p = v.sharp
  # A plan that takes long to draw shows a rougher picture of the whole page while it moves
  if p.of != of && p.cost > QUICK && time() - v.moved < SETTLED
    rough = pdf_page(path, v.data.page, 2000)
    rough === nothing || paint_picture(ctx, image_source(rough).raw, (0, 0, image_source(rough).width, image_source(rough).height), paper)
    redraw_in!(v, SETTLED)
    return
  end
  image = sharpen!(v, path, of, k, v.at[1] * k, v.at[2] * k, w, h)
  image == C_NULL && return
  # The picture is of the whole view, with white where the paper ends. The paper's edge cuts it off.
  paint_picture(ctx, image, (0, 0, w, h), (left, top, wide, tall))
end

"A paint for lines `wide` px wide, or for filling when `wide` is 0"
ink(colour, wide=0.0) = begin
  paint = Skia.sk_paint_new()
  Skia.sk_paint_set_antialias(paint, true)
  Skia.sk_paint_set_color(paint, sk_color(colour))
  Skia.sk_paint_set_style(paint, wide > 0 ? Skia.SK_PAINT_STYLE_STROKE : Skia.SK_PAINT_STYLE_FILL)
  if wide > 0
    Skia.sk_paint_set_stroke_width(paint, Float32(wide))
    Skia.sk_paint_set_stroke_join(paint, Skia.SK_STROKE_JOIN_ROUND)
    Skia.sk_paint_set_stroke_cap(paint, Skia.SK_STROKE_CAP_ROUND)
  end
  paint
end

"Skia's path through the places `ps`. `closed` joins its end to its start."
path_through(ps, closed) = begin
  shape = Skia.sk_path_new()
  for (i, (x, y)) in enumerate(ps)
    i == 1 ? Skia.sk_path_move_to(shape, Float32(x), Float32(y)) : Skia.sk_path_line_to(shape, Float32(x), Float32(y))
  end
  closed && Skia.sk_path_close(shape)
  shape
end

"""
Draw a line through the places `ps`. `fill` colours what's inside it, but not
what's inside one of the outlines `holes`. `closed` joins its end to its start.
`dashed` draws it in dashes.
"""
trace(ctx, ps, colour, wide; fill=nothing, closed=false, holes=(), dashed=false) = begin
  length(ps) < 2 && return
  shape = path_through(ps, closed)
  if fill !== nothing
    paint = ink(fill)
    Skia.sk_canvas_save(ctx)
    for hole in holes
      length(hole) < 3 && continue
      cut = path_through(hole, true)
      Skia.sk_canvas_clip_path_with_operation(ctx, cut, Skia.SK_CLIP_OP_DIFFERENCE, true)
      Skia.sk_path_delete(cut)
    end
    Skia.sk_canvas_draw_path(ctx, shape, paint)
    Skia.sk_canvas_restore(ctx)
    Skia.sk_paint_delete(paint)
  end
  paint = ink(colour, wide)
  if dashed
    dashes = Float32[6, 5]
    effect = Skia.sk_path_effect_create_dash(dashes, Cint(2), 0f0)
    Skia.sk_paint_set_path_effect(paint, effect)
    Skia.sk_path_effect_unref(effect)
  end
  Skia.sk_canvas_draw_path(ctx, shape, paint)
  Skia.sk_paint_delete(paint)
  Skia.sk_path_delete(shape)
end

"""
Show where the next corner snaps to: a square on a corner of the plan, a cross
where two of its lines cross, and a ring on a line.
"""
snap_mark(ctx, (x, y), kind) = begin
  r = 5.0
  # White under the colour, so that it shows on a dark part of the plan
  for (colour, wide) in ((colorant"white", 3.5), (colours.accent, 1.5))
    if kind == :corner
      trace(ctx, [(x - r, y - r), (x + r, y - r), (x + r, y + r), (x - r, y + r)], colour, wide, closed=true)
    elseif kind == :crossing
      trace(ctx, [(x - r, y - r), (x + r, y + r)], colour, wide)
      trace(ctx, [(x - r, y + r), (x + r, y - r)], colour, wide)
    else
      paint = ink(colour, wide)
      Skia.sk_canvas_draw_circle(ctx, Float32(x), Float32(y), Float32(r), paint)
      Skia.sk_paint_delete(paint)
    end
  end
end

"Draw a dot of radius `r` at the place `(x, y)`, with a white edge"
dot(ctx, (x, y), r, colour) = begin
  for (radius, c) in ((r + 1.5, colorant"white"), (r, colour))
    paint = ink(c)
    Skia.sk_canvas_draw_circle(ctx, Float32(x), Float32(y), Float32(radius), paint)
    Skia.sk_paint_delete(paint)
  end
end

"Write `words` in a small dark box beside the place `(x, y)`"
tag(ctx, (x, y), words) = begin
  isempty(words) && return
  face = Face(SANS, "Semibold", 11px, colorant"white", false)
  wide = num(measure(face, words))
  rounded_rectangle(ctx, px(x + 10), px(y - 22), px(wide + 12), 18px, 4px, background=RGBA(0.12, 0.12, 0.12, 0.85))
  paint = ink(colorant"white")
  blob = Skia.sk_textblob_make_from_string(words, skia_font(face.family, face.size, face.style).raw, Skia.SK_TEXT_ENCODING_UTF8)
  Skia.sk_canvas_draw_text_blob(ctx, blob, Float32(x + 16), Float32(y - 9), paint)
  Skia.sk_textblob_unref(blob)
  Skia.sk_paint_delete(paint)
end

"What a shape of this kind comes to in the unit `unit`, as the plan shows it beside the shape, or \"\" when its page has no scale"
size_text(v::TakeoffView, kind, shape, unit=Plans.own_unit(kind)) = begin
  a = Plans.amount(v.data, kind, shape)
  a === nothing ? "" : Plans.shown(kind, a, unit)
end

"""
What shape `j` of measure `m` comes to in the measure's unit, as the plan shows
it beside the shape: an outline without its cut-outs, and a cut-out as what it
takes away, with a minus. It's "" when its page has no scale.
"""
size_text(v::TakeoffView, m::Plans.Measure, j::Int) = begin
  a = Plans.amount(v.data, m, j)
  a === nothing ? "" : (m.shapes[j].cut ? "−" : "") * Plans.shown(m.kind, a, Plans.unit(m))
end

"""
What a cut-out with the corners `points` takes from the outline at the place
`from`, as the plan shows it while the cut-out is drawn. Over no outline, it
says so.
"""
cut_text(v::TakeoffView, from, points) = begin
  length(points) < 3 && return ""
  from === nothing && return "Not over an area"
  n = Plans.scale(v.data, v.data.page)
  n === nothing && return ""
  m = v.data.measures[from[1]]
  "−" * Plans.shown(:area, Plans.takes(m, from[2], points) * Plans.metres(n)^2, Plans.unit(m))
end

"Draw what's measured on the page that shows, and what's being drawn"
draw_shapes(ctx, v::TakeoffView) = begin
  t = v.data
  for (i, m) in enumerate(t.measures), (j, s) in enumerate(m.shapes)
    s.page == t.page || continue
    colour = hue(i)
    on = v.picked !== nothing && v.picked[1] == i && v.picked[2] == j
    ps = [window_point(v, p) for p in s.points]
    if m.kind == :count
      for (k, p) in enumerate(ps)
        dot(ctx, p, on && length(v.picked) == 3 && v.picked[3] == k ? 7.5 : 5, colour)
      end
      continue
    end
    area = m.kind == :area
    if s.cut
      # A cut-out is an outline of dashes. Its area's colour stops at it.
      trace(ctx, ps, colour, on ? 3 : 1.5, closed=true, dashed=true)
    else
      holes = area ? [[window_point(v, p) for p in m.shapes[k].points] for k in Plans.cuts(m, j)] : ()
      trace(ctx, ps, colour, on ? 4 : 2.5, fill=area ? RGBA(colour, 0.22) : nothing, closed=area, holes=holes)
    end
    # The corners show on the measure that the tools draw for, so that you can take hold of one
    (on || v.current == i) && foreach(p -> dot(ctx, p, on ? 4 : 3, colour), ps)
    on && tag(ctx, ps[end], size_text(v, m, j))
  end
  # Where the next corner goes, when it snaps to something
  marked = v.aim !== nothing && v.mouse !== nothing && v.asking === nothing && ishovered(part!(() -> PlanArea(of=v), v, :area))
  if isempty(v.draft)
    marked && snap_mark(ctx, window_point(v, v.mouse), v.aim)
    return
  end
  # What's being drawn runs on to the mouse
  cut = v.tool == :cut
  kind = cut ? :area : v.tool
  # With the mouse over the Done button, it shows what a click there leaves
  done = over_done(v)
  points = v.mouse === nothing || v.asking !== nothing || done ? copy(v.draft) : [v.draft; [v.mouse]]
  # A cut-out has the colour of the area that it's cut from
  from = cut ? Plans.cut_from(t, t.page, points, v.current) : nothing
  colour = kind == :scale ? colours.accent : cut ? (from === nothing ? colours.dim : hue(from[1])) :
           hue(v.current > 0 && t.measures[v.current].kind == kind ? v.current : length(t.measures) + 1)
  ps = [window_point(v, p) for p in points]
  closed = kind == :area && length(ps) > 2
  trace(ctx, ps, colour, 2, fill=closed && !cut ? RGBA(colour, 0.15) : nothing, closed=closed, dashed=cut)
  foreach(p -> dot(ctx, p, 3, colour), ps[1:length(v.draft)])
  # In the unit of the measure that it's for
  unit = v.current > 0 && t.measures[v.current].kind == kind ? Plans.unit(t.measures[v.current]) : Plans.own_unit(kind)
  kind == :scale || tag(ctx, ps[end], cut ? cut_text(v, from, points) : size_text(v, kind, Plans.Shape(t.page, points), unit))
  marked && !done && snap_mark(ctx, window_point(v, v.mouse), v.aim)
  draw_done(ctx, v, done)
end

# --- the button that ends a line or an outline -------------------------------------------
#
# While a length or an area is being drawn, a Done button shows beside its last
# corner, as soon as it has corners enough to end. A click on the button ends
# the line or the outline, as Return does, and puts no corner down. The button
# is behind the last corner and to one side of the line that led to it. The
# next corner is seldom put there, so the button is seldom in its way.

const DONE_W, DONE_H = 64.0, 24.0   # px. How wide and how tall the Done button is.
const DONE_GAP = 10.0               # px between the button and the line that led to the last corner

"""
Where the Done button is in the window: its left, its top, its width and its
height. It's nothing while there's no line or outline with corners enough to end.
"""
done_box(v::TakeoffView) = begin
  (v.tool in (:length, :area, :cut) && v.zoom > 0) || return nothing
  n = length(v.draft)
  n >= (v.tool == :length ? 2 : 3) || return nothing
  (x, y), (x0, y0) = window_point(v, v.draft[n]), window_point(v, v.draft[n-1])
  far = hypot(x - x0, y - y0)
  # The way the line went to its last corner
  ux, uy = far > 0 ? ((x - x0) / far, (y - y0) / far) : (1.0, 0.0)
  # The button's place on one side of the line. Its front is level with the corner, and its near edge is DONE_GAP from the line.
  place(nx, ny) = begin
    back = (abs(ux) * DONE_W + abs(uy) * DONE_H) / 2
    off = (abs(nx) * DONE_W + abs(ny) * DONE_H) / 2 + DONE_GAP
    (x - ux * back + nx * off - DONE_W / 2, y - uy * back + ny * off - DONE_H / 2)
  end
  left, top, wide, tall = v.box
  fits((bx, by)) = bx >= left && by >= top && bx + DONE_W <= left + wide && by + DONE_H <= top + tall
  # The side that's lower in the window, or the right one of two that are level. The other side if only that one is in the view.
  nx, ny = ux > 0 || (ux == 0 && uy < 0) ? (-uy, ux) : (uy, -ux)
  at = place(nx, ny)
  other = place(-nx, -ny)
  fits(at) || !fits(other) || (at = other)
  # A corner that's out of sight still has its button in sight
  (clamp(at[1], left, max(left, left + wide - DONE_W)), clamp(at[2], top, max(top, top + tall - DONE_H)), DONE_W, DONE_H)
end

"True when the place `(x, y)` of the window is on the Done button"
on_done(v::TakeoffView, x, y) = begin
  b = done_box(v)
  b !== nothing && b[1] <= x <= b[1] + b[3] && b[2] <= y <= b[2] + b[4]
end

"True when the mouse is over the Done button"
over_done(v::TakeoffView) = (w = window_of(v); w !== nothing && on_done(v, num(w.mouse[1]), num(w.mouse[2])))

"What the Done button's tooltip says"
done_tip(v::TakeoffView) = (v.tool == :length ? "End the line" : "End the outline") * "  Return"

"Draw the Done button. It's lighter while the mouse is over it."
draw_done(ctx, v::TakeoffView, over::Bool) = begin
  b = done_box(v)
  b === nothing && return
  size = (px(b[3]), px(b[4]))
  white = colorant"white"
  button = Box(fixed(size[1]), height(size[2]), radius(size[2] / 2), Alignment.Center, border(1.5px, :solid, white),
               background(over ? RGBA(0.3, 0.3, 0.3, 0.95) : RGBA(0.12, 0.12, 0.12, 0.9)),
               Row(Alignment.Center, child_gap=4px, Icon("check", size=12px, color=white), label("Done", 12px, color=white, weight="Semibold")))
  Skia.sk_canvas_save(ctx)
  Skia.sk_canvas_translate(ctx, Float32(b[1]), Float32(b[2]))
  draw(ctx, size, describe(button, size))
  Skia.sk_canvas_restore(ctx)
end

describe(a::PlanArea) = begin
  v = a.of
  # In the window, the plan takes all the room that the tools leave
  h = v.full ? height(grow=grow) : height(plan_h(v, editor(v).width - 2px))
  plan_size(v) === nothing || return Box(width(grow=grow), h, background(takeoff_back()))
  words = isempty(v.data.plan) ? "Drop a plan here, or click to choose one: a PDF file or a picture" :
                                 "$(v.data.plan) isn't a plan that Ladder can show. Click to choose another."
  Column(width(grow=grow), h, justify=Alignment.Center, child_gap=10px, background(colours.stripe),
    Icon("map", size=26px, color=colours.faint), Box(label(words, 13px, color=colours.dim)))
end

draw(ctx, size, ui::ConcreteRect, a::PlanArea) = begin
  v = a.of
  was = v.box
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  s = plan_size(v)
  s === nothing && return
  # A new file or a new page is shown whole
  shown = (plan_path(v), v.data.page)
  if v.zoom <= 0 || v.fitted != shown
    fit!(v, s)
    v.fitted = shown
  elseif was[3] > 0 && (was[3] != v.box[3] || was[4] != v.box[4])
    # The view changed its size, as it does when the window does, when it fills the window and on paper.
    # A view that showed the whole page still does. A view that was bigger shows the same part of the plan.
    if v.zoom <= 1.0001min(was[3] / s[1], was[4] / s[2])
      fit!(v, s)
    else
      middle = (v.at[1] + was[3] / 2v.zoom, v.at[2] + was[4] / 2v.zoom)
      v.zoom = max(v.zoom * v.box[3] / was[3], fit_zoom(v, s))
      v.at = (middle[1] - v.box[3] / 2v.zoom, middle[2] - v.box[4] / 2v.zoom)
      hold!(v, s)
    end
  end
  lookup!(v)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    draw_plan(ctx, v, s)
    draw_shapes(ctx, v)
  end
end

"""
True when the mouse is over something on the plan that a click selects: a
mark, a line, an outline or the inside of one. The window asks for the cursor
before the plan sees the mouse move, so this reads where the window's mouse is.
"""
over_shape(v::TakeoffView) = begin
  w = window_of(v)
  (w === nothing || v.zoom <= 0) && return false
  p = page_point(v, num(w.mouse[1]), num(w.mouse[2]))
  Plans.shape(v.data, v.data.page, p, REACH / v.zoom) !== nothing
end

# With the select tool, a hand over something that a click selects, and an arrow over the paper
cursor(a::PlanArea) = begin
  v = a.of
  plan_size(v) === nothing || over_done(v) ? :hand : v.tool == :select ? (v.grab !== nothing || over_shape(v) ? :hand : :arrow) : :crosshair
end

# --- the mouse and the keys on the plan --------------------------------------------------

"The name that a new measure of this kind starts with: Count 1, Length 2"
first_name(v::TakeoffView, kind) = "$(uppercasefirst(string(kind))) $(count(m -> m.kind == kind, v.data.measures) + 1)"
const FIRST_NAME = r"^(Count|Length|Area) \d+$"
const KIND_WORDS = Dict(:count => "a count", :length => "a length", :area => "an area")

"What an item's price is for, in words: each one, each m, each m²"
sold_by(row) = begin
  unit = string(something(get(row, "unit", nothing), ""))
  unit in ("", "Piece", "each") ? "each one" : "each " * unit
end

"Make a measure that has nothing drawn yet one of `kind`. A name that it was made with follows its kind."
kind!(v::TakeoffView, m, kind::Symbol) = begin
  (m.kind == kind || !isempty(m.shapes)) && return m
  occursin(FIRST_NAME, m.name) && (m.name = first_name(v, kind))
  m.kind = kind
  m.unit = ""
  m
end

"The measure of this kind that the tools draw for. If the current measure is of another kind, a new one starts."
measure!(v::TakeoffView, kind::Symbol) = begin
  ms = v.data.measures
  1 <= v.current <= length(ms) && ms[v.current].kind == kind && return ms[v.current]
  push!(ms, Plans.Measure(kind, first_name(v, kind)))
  v.current = length(ms)
  last(ms)
end

"What the foot of the block says when a cut-out is drawn where there's no area to cut it from"
const CUT_NOWHERE = "A cut-out goes over an area that's measured. Measure the area first, then cut the shape out of it."

"""
End the line or the outline that's being drawn. One with too few corners is
dropped. A cut-out goes to the area that it's over, and one that's over none is
dropped too.
"""
finish_shape!(v::TakeoffView) = begin
  kind = v.tool
  if kind == :cut && length(v.draft) >= 3
    made = Plans.cut!(v.data, v.data.page, copy(v.draft), v.current)
    empty!(v.draft)
    if made === nothing
      say!(v, CUT_NOWHERE, true)
    else
      v.current = made[1]
      v.said == CUT_NOWHERE && say!(v, "")
      commit!(v)
    end
  elseif kind in (:length, :area) && length(v.draft) >= (kind == :length ? 2 : 3)
    push!(measure!(v, kind).shapes, Plans.Shape(v.data.page, copy(v.draft)))
    empty!(v.draft)
    commit!(v)
  end
  empty!(v.draft)
  handled
end

"""
Choose a tool. A tool that measures draws for the measure that's chosen in the
list. If that measure is of another kind, it becomes the tool's kind when
nothing is drawn for it yet and it has no item. If not, the tool draws for the
last measure of its kind.
"""
tool!(v::TakeoffView, tool::Symbol) = begin
  v.tool = tool
  empty!(v.draft)
  v.picked = nothing
  ms = v.data.measures
  if tool in Plans.KINDS && !(1 <= v.current <= length(ms) && ms[v.current].kind == tool)
    m = 1 <= v.current <= length(ms) ? ms[v.current] : nothing
    if m !== nothing && isempty(m.shapes) && isempty(m.item)
      kind!(v, m, tool)
      commit!(v)
    else
      v.current = something(findlast(m -> m.kind == tool, ms), 0)
    end
  end
  handled
end

"A drag ended. A corner that moved is written down."
drop!(v::TakeoffView) = begin
  g = v.grab
  v.grab = nothing
  g !== nothing && g[1] == :corner && g[3] && commit!(v)
  v
end

"Take away what's selected on the plan: a mark, a corner, or a whole line or outline"
remove_picked!(v::TakeoffView) = begin
  p = v.picked
  p === nothing && return handled
  m = v.data.measures[p[1]]
  # An outline takes its cut-outs with it
  length(p) == 3 ? Plans.remove!(m, p[2], p[3]) : Plans.remove!(m, p[2])
  v.picked = nothing
  commit!(v)
  handled
end

onkey(a::PlanArea, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = a.of, ev.window
  focus(a)
  plan_size(v) === nothing && return choose_plan!(v, w)
  v.zoom > 0 || return handled
  x, y = num(w.mouse[1]), num(w.mouse[2])
  # A click on the Done button ends what's being drawn, and puts no corner down
  on_done(v, x, y) && return (hide_tooltip!(w); finish_shape!(v))
  p = page_point(v, x, y)
  at, cx, cy = v.clicked
  twice = time() - at < 0.35 && hypot(x - cx, y - cy) < 4
  v.clicked = (time(), x, y)
  reach = REACH / v.zoom
  page = v.data.page
  if v.tool == :count
    Plans.mark!(measure!(v, :count), page, p)
    commit!(v)
  elseif v.tool in (:length, :area, :cut)
    closes = v.tool != :length && length(v.draft) >= 3 && hypot(v.draft[1][1] - p[1], v.draft[1][2] - p[2]) <= reach
    # The first click of two put the last corner down. A corner snaps to the plan's lines.
    (twice && !isempty(v.draft)) || closes ? finish_shape!(v) : push!(v.draft, aim(v, w, x, y)[1])
  elseif v.tool == :scale
    length(v.draft) >= 2 && empty!(v.draft)
    push!(v.draft, aim(v, w, x, y)[1])
    length(v.draft) == 2 && ask!(v, (:length, v.draft[1], v.draft[2]), "", "metres")
  else
    corner = Plans.corner(v.data, page, p, reach)
    if corner !== nothing
      v.picked, v.current = corner, corner[1]
      v.grab = (:corner, corner, false)
    else
      v.picked = Plans.shape(v.data, page, p, reach)
      v.picked === nothing || (v.current = v.picked[1])
      v.grab = (:pan, (x, y), v.at)
    end
  end
  handled
end

# A right-click ends what's being drawn
onkey(a::PlanArea, ::KeyPress{Keys.mouse_right}) = isempty(a.of.draft) ? nothing : finish_shape!(a.of)

onmouse(a::PlanArea, ev::MouseMove) = begin
  v = a.of
  v.zoom > 0 || return nothing
  x, y = num(ev.position[1]), num(ev.position[2])
  g = v.grab
  # A corner that a tool is about to put down snaps to the plan's lines, and so does one that's dragged. A mark of a count doesn't.
  drawing = g === nothing && v.tool in (:length, :area, :cut, :scale) && !on_done(v, x, y)
  dragged = g !== nothing && g[1] == :corner && v.data.measures[g[2][1]].kind != :count
  v.mouse, v.aim = drawing ? aim(v, ev.window, x, y) : dragged ? aim(v, ev.window, x, y, skip=g[2]) : (page_point(v, x, y), nothing)
  # The Done button says what it does, and the key that does the same
  on_done(v, x, y) && show_tooltip!(ev.window, tip_label(done_tip(v)), px.(done_box(v))..., placement=:bottom, gap=6px)
  g === nothing && return handled
  Keys.mouse_left in ev.window.keys || (drop!(v); return handled)
  if g[1] == :pan
    (x0, y0), at = g[2], g[3]
    v.at = (at[1] - (x - x0) / v.zoom, at[2] - (y - y0) / v.zoom)
    moved!(v)
  else
    i, j, k = g[2]
    v.data.measures[i].shapes[j].points[k] = v.mouse
    v.grab = (:corner, g[2], true)
  end
  handled   # the drag is the plan's, so the page's text doesn't select
end

# A mouse wheel makes the plan bigger or smaller, round the mouse, like a map. Two fingers on the trackpad move
# the plan, and a pinch makes it bigger or smaller. With ⌘ held, both make it bigger or smaller.
# A plan in the page takes them once a click has given it the keyboard, or while ⌘ is held. Before that, they
# move the page that the plan is on, so that the page can scroll past it. A plan that fills the window has no page.
onscroll(a::PlanArea, ev::MouseScroll) = begin
  v, w = a.of, ev.window
  v.zoom > 0 || return nothing
  cmd = Keys.cmd in w.keys
  (cmd || w.focus === a || v.full) || return nothing
  (cmd || ev.wheel) && return zoom_plan!(v, exp(num(ev.delta[2]) / 10), num(w.mouse[1]), num(w.mouse[2]))
  v.at = (v.at[1] - 30num(ev.delta[1]) / v.zoom, v.at[2] - 30num(ev.delta[2]) / v.zoom)
  moved!(v)
  handled
end

# Two fingers that move apart or together on the trackpad make the plan bigger or smaller, round the mouse
onpinch(a::PlanArea, ev::Pinch) = begin
  v, w = a.of, ev.window
  v.zoom > 0 || return nothing
  zoom_plan!(v, ev.scale, num(w.mouse[1]), num(w.mouse[2]))
end

onkey(a::PlanArea, ::KeyPress{Keys.enter}) = finish_shape!(a.of)
onkey(a::PlanArea, ::KeyPress{Keys.escape}) = begin
  v = a.of
  # Esc drops what's half drawn, then puts the arrow back, then puts a takeoff that fills the window
  # back in the page, then gives the keyboard back to the text
  isempty(v.draft) || return (empty!(v.draft); handled)
  v.tool == :select ? (v.full ? full!(v, false) : nothing) : tool!(v, :select)
end
onkey(a::PlanArea, ::KeyPress{K}) where K = begin
  v = a.of
  if K in (Keys.backspace, Keys.delete)
    # While something is being drawn, Delete takes its last corner back
    return isempty(v.draft) ? remove_picked!(v) : (pop!(v.draft); handled)
  elseif (command = command_of(editor(v), window_of(a), K)) in (:undo, :redo)
    b = editor(v).buf
    command == :redo ? redo!(b) : undo!(b)
    return handled
  end
  nothing
end

ontype(a::PlanArea, ev::Typed) = begin
  Keys.cmd in ev.window.keys && return nothing
  i = findfirst(((_, (_, _, letter)),) -> letter == lowercase(ev.char), PLAN_TOOLS)
  i === nothing ? nothing : tool!(a.of, PLAN_TOOLS[i][1])
end

# --- the buttons -------------------------------------------------------------------------

"The button of `v` that's kept under `key`, with what it does and shows now"
button!(v::TakeoffView, key, action; icon="", words="", tip="", off=false) = begin
  b = part!(() -> PlanButton(of=v), v, (:button, key))
  b.action, b.icon, b.words, b.tip, b.off = action, icon, words, tip, off
  b
end

describe(b::PlanButton) = begin
  v = b.of
  ishovered(b) || (b.quiet = false)
  # The tool in use is lit, and so is the magnet while corners snap
  on = (b.action isa Tuple && b.action[1] == :tool && v.tool == b.action[2]) || (b.action == :snap && v.snap)
  colour = b.off ? colours.faint : on ? colours.accent : colours.dim
  Box(height(26px), padding(7px, 0px), radius(6px), Alignment.Center, name="Button",
      background(on ? colours.active : ishovered(b) && !b.off ? colours.hover : clear),
    Row(Alignment.Center, child_gap=5px,
      (isempty(b.icon) ? () : (Icon(b.icon, size=14px, color=colour),))...,
      (isempty(b.words) ? () : (label(b.words, 12px, color=b.off ? colours.faint : colours.ink),))...))
end

cursor(b::PlanButton) = b.off ? :arrow : :hand

draw(ctx, size, ui::ConcreteRect, b::PlanButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::PlanButton, ev::MouseMove) = begin
  (b.quiet || isempty(b.tip)) && return
  show_tooltip!(ev.window, tip_label(b.tip), b.rect..., placement=:bottom, gap=6px)
end

onkey(b::PlanButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  b.off ? handled : act!(b.of, b.action, ev.window)
end

"Make the takeoff fill the window, or put it back in the page"
full!(v::TakeoffView, on::Bool) = begin
  e = editor(v)
  on && unfill!(e)   # one block at a time fills the window
  v.full = on
  v.pinned = e.scroll.offset
  focus(part!(() -> PlanArea(of=v), v, :area))
  handled
end

"The takeoff of the page that fills the window, or nothing"
full_takeoff(e) = begin
  for (key, node) in e.nodes
    node isa TakeoffView && node.full && key[2] == e.buf.path && return node
  end
  nothing
end

"""
True for a kind of view that can fill the window, over the page: a takeoff, a
schedule and a sketch. Such a view has the fields `full`, `tall`, which is how
tall it was in the page, and `pinned`, which is how far the page was scrolled.
"""
can_fill(v) = hasfield(typeof(v), :full) && hasfield(typeof(v), :pinned)
"True for a view that fills the window now"
filling(v) = can_fill(v) && v.full

"Put the block that fills the window back in the page"
unfill!(e) = foreach(node -> filling(node) && (node.full = false), values(e.nodes))

"The takeoff, the schedule or the sketch of the page that fills the window, or nothing"
full_block(e) = begin
  for (key, node) in e.nodes
    filling(node) || continue
    # A view is kept under its page: the second part of the key of a takeoff and a schedule, and the third of another block
    (key[1] == :block ? key[3] : key[2]) == e.buf.path && return node
  end
  nothing
end

"The takeoff, the schedule or the sketch that fills the window, over the page and the sidebar and under the top bar"
takeoff_over(e) = begin
  v = full_block(e)
  v === nothing ? () : (Box(width(grow=grow), height(grow=grow), padding(TOPBAR_H, 0px, 0px, 0px), background(colours.bg), geometry(v)),)
end

"Do what a button of a takeoff does"
act!(v::TakeoffView, action, w) = begin
  settle_asking!(v)
  a = action isa Tuple ? action[1] : action
  t = v.data
  if a == :tool
    tool!(v, action[2])
  elseif a == :page
    page!(v, action[2])
  elseif a == :zoom
    zoom_plan!(v, action[2], v.box[1] + v.box[3] / 2, v.box[2] + v.box[4] / 2)
  elseif a == :fit
    v.zoom = 0.0
  elseif a == :snap
    v.snap = !v.snap
    v.aim = nothing
  elseif a == :full
    full!(v, !v.full)
  elseif a == :scale
    s = Plans.scale(t, t.page)
    ask!(v, (:scale,), s === nothing ? "1:100" : Plans.scale_text(s))
  elseif a == :choose
    choose_plan!(v, w)
  elseif a in (:add, :add_item)
    # It starts as what the tool in use measures, or as a count. Its item's unit, or the next tool, can change that.
    kind = v.tool in Plans.KINDS ? v.tool : :count
    empty!(v.filters)   # a search of the table could hide the new measure
    push!(t.measures, Plans.Measure(kind, first_name(v, kind)))
    v.current = length(t.measures)
    tool!(v, kind)
    commit!(v)
    # A measure from the catalogue asks for its item: it takes the item's name, and the item's unit says what it is.
    # Another asks for the words that describe it. Typing takes the place of the name that it was made with.
    a == :add_item ? ask!(v, (:item, v.current)) : ask!(v, (:name, v.current), last(t.measures).name, "What it measures")
  elseif a == :delete && action[2] <= length(t.measures)
    deleteat!(t.measures, action[2])
    v.current = v.current == action[2] ? 0 : v.current > action[2] ? v.current - 1 : v.current
    v.picked = nothing
    commit!(v)
  elseif a == :customer
    Centient.available() ? ask!(v, (:customer,), "", "Search Centient's contacts") :
                           ask!(v, (:customer,), t.customer, "The customer's name")
  elseif a == :quote
    make_quote!(v)
  end
  handled
end

# --- the list of measures ----------------------------------------------------------------

"The text field in a box, where the thing that it changes was"
field(v::TakeoffView, wide=width(grow=grow)) =
  Box(wide, height(24px), padding(6px, 0px), radius(5px), border(1px, :solid, colours.accent), background(colours.bg), plan_input(v))

"The mark beside a measure's name, in its colour: a dot for a count, a line for a length, a square for an area"
swatch(kind::Symbol, colour) =
  Box(width(14px), height(14px), Alignment.Center,
    kind == :count ? Box(width(10px), height(10px), radius(5px), background(colour)) :
    kind == :length ? Box(width(14px), height(3px), radius(1.5px), background(colour)) :
                      Box(width(11px), height(11px), radius(2px), background(RGBA(colour, 0.3)), border(1.5px, :solid, colour)))

"A price as a row of the list shows it: \$22.00 / m, or \$5.97 each"
price_text(row) = begin
  unit = string(something(get(row, "unit", nothing), ""))
  dollars(row["price"]) * (unit in ("", "Piece", "each") ? " each" : " / " * unit)
end

"""
`s` cut short with … so that it's no wider than `wide` at `size`. It's all of
`s` when it fits, and when there's no width to fit it to yet.
"""
elide(s::AbstractString, size, wide) = begin
  face = Face(SANS, "", size, colours.ink, false)
  (wide <= 0px || measure(face, s) <= wide) && return String(s)
  # The most letters that fit with the … after them
  cs = collect(s)
  lo, hi = 0, length(cs)
  while lo < hi
    mid = (lo + hi + 1) ÷ 2
    measure(face, rstrip(String(cs[1:mid])) * "…") <= wide ? (lo = mid) : (hi = mid - 1)
  end
  rstrip(String(cs[1:lo])) * "…"
end

"""
What the table calls measure `m`. With an item that Centient has told of, it's
the item's name. With no item, it's the words that describe the measure, which
are its name in the block.
"""
item_name(v::TakeoffView, m) = begin
  row = known(v, m.item)
  row === nothing ? (isempty(m.name) ? m.item : m.name) : string(row["name"])
end

"The words `shown`, which start the words of `parts` and may end with …, as a text for each part in its colour"
runs(shown::AbstractString, parts) = begin
  cs, at, out = collect(shown), 0, Any[]
  for (s, colour) in parts
    n = min(length(s), length(cs) - at)
    n > 0 || break
    push!(out, label(String(cs[at+1:at+n]), 13px, color=colour))
    at += n
  end
  out
end

describe(c::MeasureCell) = begin
  v, i = c.of, c.i
  i <= length(v.data.measures) || return Box(width(0px))
  m = v.data.measures[i]
  wide = c.what == :extra ? fixed(52px) : width(grow=grow)
  c.full = ""
  # The item's cell holds the field for the item, and the field for the words of a measure with none
  a = v.asking
  a !== nothing && a[1] in (c.what == :item ? (:item, :name) : (:extra,)) && a[2] == i && return field(v, wide)
  # The words are in a row with no width of its own, so long words take no room from the cells beside them.
  # They're cut short with … to fit the width the cell had when it was last drawn. Each of `parts` is words and their colour.
  words(parts...) = begin
    s = join(first.(parts))
    shown = elide(s, 13px, c.rect[3])
    shown == s || (c.full = s)
    Row(wide, height(grow=grow), Alignment.Center, clip=true, Row(fixed(0px), runs(shown, parts)...))
  end
  c.what == :extra && return words((m.extra > 0 ? "+" * Plans.number(100m.extra) * "%" : "+0%", m.extra > 0 ? colours.ink : colours.faint))
  name, row = item_name(v, m), known(v, m.item)
  # An item that Centient knows shows where it's from after its name
  row === nothing ? words((name, colours.ink)) : words((name, colours.ink), ("  ·  " * string(row["source"]), colours.dim))
end

cursor(::MeasureCell) = :hand

draw(ctx, size, ui::ConcreteRect, c::MeasureCell) = begin
  # A new width cuts the words short in another place, so the cell is described again
  ui.width == c.rect[3] || redraw_in!(c.of, 0)
  c.rect = (ui.left, ui.top, ui.width, ui.height)
  nothing
end

# Words that are cut short show whole under the cell
onmouse(c::MeasureCell, ev::MouseMove) = isempty(c.full) ? nothing :
  show_tooltip!(ev.window, tip_label(c.full), c.rect..., placement=:bottom, gap=6px)

onkey(c::MeasureCell, ::KeyPress{Keys.mouse_left}) = begin
  v, i = c.of, c.i
  i <= length(v.data.measures) || return handled
  m = v.data.measures[i]
  # The first click on a row chooses it. A click on the row that's chosen changes the part that's clicked.
  chosen = v.current == i
  chosen || choose_measure!(v, i)
  chosen || return handled
  c.what == :extra && return ask!(v, (:extra, i), m.extra > 0 ? Plans.number(100m.extra) : "", "%")
  # A measure from the catalogue chooses another item. One with no item changes the words that describe it.
  isempty(m.item) || !Centient.available() ? ask!(v, (:name, i), m.name, "What it measures") : ask!(v, (:item, i))
end

describe(r::MeasureRow) = begin
  v, i = r.of, r.i
  i <= length(v.data.measures) || return Box(height(0px))
  m = v.data.measures[i]
  cell(what) = part!(() -> MeasureCell(of=v, i=i, what=what), v, (:cell, i, what))
  amount = Plans.amount(v.data, m)
  row = known(v, m.item)
  # A Text on its own would take all of the row, so each is in a box that the row puts at its right
  # It's as tall as the row, so that what cuts a long text off at the side doesn't cut the tail of a comma or a g
  right(wide, s, colour) = Row(fixed(wide), height(grow=grow), Alignment.Center, justify=Alignment.End, clip=true, Box(label(s, 13px, color=colour)))
  back = background(v.current == i ? colours.active : ishovered(r) ? colours.hover : clear)
  # The first row has a line that doesn't show, so that its words are where the other rows' are
  line = (border(1px, :solid, !isempty(v.order) && v.order[1] == i ? clear : colours.line)[:top],)
  size = part!(() -> AmountCell(of=v, i=i), v, (:amount, i))
  cost = right(88px, row === nothing || amount === nothing ? "" : dollars(cost_of(m, amount, row)), colours.ink)
  remove = button!(v, (:delete, i), (:delete, i), icon="x-lg", tip="Remove this measure")
  # The panel beside a plan that fills the window is narrow, so a measure has two lines there
  # The cost and the price have columns only while a measure has an item to price it
  costs = has_items(v) ? (cost,) : ()
  v.beside && return Column(width(grow=grow), Alignment.Start, padding(10px, 4px), name="Measure", back, line...,
    Row(width(grow=grow), height(26px), child_gap=8px, Alignment.Center, swatch(m.kind, hue(i)), cell(:item), size),
    Row(width(grow=grow), height(26px), child_gap=8px, Alignment.Center, Box(width(14px)), cell(:extra), Box(width(grow=grow)), costs..., remove))
  Row(width(grow=grow), height(32px), padding(10px, 0px), child_gap=10px, Alignment.Center, name="Measure", back, line...,
    swatch(m.kind, hue(i)), cell(:item), cell(:extra), size,
    # A narrow block has no room for the price of one, so it shows what the measure comes to and no more
    # The price is for one of the measure's unit, so it needs no unit after it. One that the measure can't be in says its own.
    (has_price(v) ? (right(96px, row === nothing ? "" : (p = unit_price(m, row); p === nothing ? price_text(row) : dollars(p)), colours.dim),) : ())...,
    costs..., remove)
end

cursor(::MeasureRow) = :hand

"Make measure `i` the one that the tools draw for, and choose the tool of its kind"
choose_measure!(v::TakeoffView, i::Int) = begin
  i <= length(v.data.measures) || return handled
  v.current = i
  tool!(v, v.data.measures[i].kind)
end

onkey(r::MeasureRow, ::KeyPress{Keys.mouse_left}) = choose_measure!(r.of, r.i)

# --- the units of a measure --------------------------------------------------------------
#
# A click on the unit after a measure's amount shows the list of units that it
# can be in, as Centient's unit picker does: each unit's name, and the short
# form that goes after an amount at the right. A field at the top of the list
# searches it. The up and down arrows pick a unit, and so does the mouse. Return or a
# click takes it. Esc, or a click somewhere else, closes the list and changes
# nothing.

const UNIT_KEY = :takeoff_units
const AMOUNT_W = 96px    # how wide the column of amounts is
const MOST_UNITS = 8     # the units that the list shows before it scrolls

"""
The units that measure `i` can be in. One with nothing drawn and no item can be
a count, a length or an area, so it can take a unit of each kind. Any other
keeps its kind.
"""
units_for(v::TakeoffView, i::Int) = begin
  i <= length(v.data.measures) || return String[]
  m = v.data.measures[i]
  isempty(m.shapes) && isempty(m.item) ? reduce(vcat, collect(Plans.KIND_UNITS)) : copy(getfield(Plans.KIND_UNITS, m.kind))
end

"Write a unit as a keyboard can: m^2 or m2 for m². What's typed is folded the other way, so that each finds the other."
fold_unit(s::AbstractString) = begin
  s = replace(lowercase(s), "^2" => "²", "^3" => "³")
  replace(s, r"([a-z]+)([23])(?!\d)" => m -> m[1:end-1] * (m[end] == '2' ? "²" : "³"))
end

"Other words that a unit is typed as"
const UNIT_EXTRAS = Dict("hectare" => ["ha", "hectares"], "ft" => ["feet"], "inch" => ["in", "inches"],
                         "ft²" => ["sq ft", "square feet"], "m" => ["meter"], "m²" => ["sqm", "square meter"], "Piece" => ["each"])

"True when `words` find `unit`: they're in its name, its short form, or the name that Centient gives it"
unit_matches(unit::AbstractString, words::AbstractString) = begin
  isempty(words) && return true
  q = fold_unit(words)
  any(h -> occursin(q, fold_unit(h)), [Plans.UNIT_WORDS[unit], Plans.unit_short(unit), unit, get(UNIT_EXTRAS, unit, String[])...])
end

"True when `words` are a name of `unit` and not only part of one: metre for m, and not for mm"
names_unit(unit::AbstractString, words::AbstractString) =
  (q = fold_unit(words); any(h -> fold_unit(h) == q, [Plans.UNIT_WORDS[unit], Plans.unit_short(unit), unit, get(UNIT_EXTRAS, unit, String[])...]))

"The unit word of the amount `c`. It belongs to the amount, so the mouse over it is over the amount too."
unit_word(c::AmountCell) = begin
  c.unit === nothing && (c.unit = UnitWord(of=c); setfield!(c.unit, :parent, c))
  c.unit
end

describe(c::AmountCell) = begin
  v, i = c.of, c.i
  i <= length(v.data.measures) || return Box(width(0px))
  m = v.data.measures[i]
  amount = Plans.amount(v.data, m)
  # It's as tall as the row, so that what cuts a long amount off at the side doesn't cut the tail of a comma or a g
  cell(parts...) = Row(fixed(AMOUNT_W), height(grow=grow), Alignment.Center, justify=Alignment.End, clip=true, name="Amount", parts...)
  amount === nothing && return cell(Box(label("No scale", 13px, color=colours.accent)))
  unit = Plans.unit(m)
  number = Box(label(Plans.amount_number(Plans.in_unit(amount, unit)), 13px, color=colours.ink))
  # The unit is there to click when the measure can be in another. A count that can only be in pieces is a number.
  length(units_for(v, i)) > 1 ? cell(number, unit_word(c)) : cell(Box(label(Plans.shown(m, amount), 13px, color=colours.ink)))
end

cursor(::AmountCell) = :hand
# A click on the number chooses the measure, as a click on the rest of its row does
onkey(c::AmountCell, ::KeyPress{Keys.mouse_left}) = choose_measure!(c.of, c.i)

describe(w::UnitWord) = begin
  c = w.of
  v = c.of
  c.i <= length(v.data.measures) || return Box(width(0px))
  unit = Plans.unit(v.data.measures[c.i])
  lit = ishovered(w) || v.asking == (:unit, c.i)
  # A foot and an inch are marks right after the number. Another unit has a space before it, and the space is the unit's to click.
  Row(height(grow=grow), padding(0px, 0px, 0px, unit in ("inch", "ft") ? 1px : 4px), Alignment.Center,
    label(Plans.unit_short(unit), 13px, color=lit ? colours.accent : colours.ink))
end

cursor(::UnitWord) = :hand
onkey(w::UnitWord, ev::KeyPress{Keys.mouse_left}) = open_units!(w.of, ev.window)

"Show the list of the units that the measure of the amount `c` can be in, under its unit"
open_units!(c::AmountCell, window) = begin
  v, i = c.of, c.i
  i <= length(v.data.measures) || return handled
  ask!(v, (:unit, i), "", "Filter…")
  v.query = ""   # so that the first frame keeps the unit that's picked
  v.rows = Any[units_for(v, i)...]
  v.pick = something(findfirst(==(Plans.unit(v.data.measures[i])), v.rows), 1)
  menu = UnitMenu(of=v, i=i)
  v.parts[:unit_menu] = menu
  popup!(window, menu, anchor=unit_word(c), placement=:bottom, gap=9px, width=230px, key=UNIT_KEY,
         onclose=() -> settle_asking!(v), theme=component_theme(editor(v).zoom))
  handled
end

"""
Put measure `i` in `unit`. A unit of another kind makes a measure with nothing
drawn and no item that kind. The tool for it is ready to draw.
"""
unit!(v::TakeoffView, i::Int, unit::AbstractString) = begin
  stop_asking!(v)
  i <= length(v.data.measures) || return handled
  m = v.data.measures[i]
  kind = Plans.unit_kind(unit)
  kind === nothing && return handled
  if kind != m.kind
    (isempty(m.shapes) && isempty(m.item)) || return handled
    kind!(v, m, kind)
  end
  Plans.unit!(m, unit)
  commit!(v)
  v.current = i
  tool!(v, m.kind)
end

# The list of units and the lists at the top of a `find` block are one kind of
# list. These three draw it: the box with the field at its top, a row of it, and
# the words that take the place of its rows when nothing matches.

const FLOAT_ROW = 28px   # how tall a row of such a list is

"""
A list that floats beside what it's for, with a field at its top that searches
it. `input` is the field, and `body` is the rows under it.
"""
float_list(input, body; name="List") = begin
  c = found_colours()
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name=name,
    Column(width(grow=grow), Alignment.Start, child_gap=4px,
      Box(width(grow=grow), padding(2px, 2px),
        Box(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), border(1px, :solid, c.line), background(c.frame), input)),
      body))
end

"""
A row of such a list. `picked` is the row that Return takes, and `on` is the
one that's chosen now, which is in bold. `short` is a word at its right.
"""
float_row(name, short=""; picked=false, on=false) = begin
  c = found_colours()
  Row(width(grow=grow), height(FLOAT_ROW), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      background(picked ? c.pick : c.frame),
    Row(width(grow=grow), height(grow=grow), Alignment.Center, clip=true, label(name, 13px, color=c.ink, weight=on ? "Semibold" : "")),
    (isempty(short) ? () : (Box(label(short, 12px, color=c.dim)),))...)
end

"What such a list says in place of its rows when nothing in it matches"
float_none(words) = Row(width(grow=grow), height(FLOAT_ROW), padding(8px, 0px), Alignment.Center, label(words, 12px, color=found_colours().dim))

describe(r::UnitRow) = begin
  v = r.of
  r.k <= length(v.rows) || return Box(height(0px))
  unit = v.rows[r.k]
  a = v.asking
  on = a !== nothing && a[1] == :unit && a[2] <= length(v.data.measures) && Plans.unit(v.data.measures[a[2]]) == unit
  short = Plans.unit_short(unit)
  name = Plans.UNIT_WORDS[unit]
  # The short form shows when it isn't the name again
  float_row(name, lowercase(short) == lowercase(name) ? "" : short, picked=v.pick == r.k, on=on)
end

cursor(::UnitRow) = :hand
onkey(r::UnitRow, ::KeyPress{Keys.mouse_left}) = begin
  v, a = r.of, r.of.asking
  a !== nothing && a[1] == :unit && r.k <= length(v.rows) ? unit!(v, a[2], v.rows[r.k]) : handled
end
# The mouse picks the unit that it's over, as the arrow keys do
onmouse(r::UnitRow, ::MouseMove) = begin
  v = r.of
  v.pick = r.k
  menu = get(v.parts, :unit_menu, nothing)
  menu === nothing || (menu.pick = r.k)   # it's in sight already, so the list doesn't scroll to it
  handled
end

describe(m::UnitMenu) = begin
  v = m.of
  n, high = length(v.rows), FLOAT_ROW
  scroll = get!(() -> Scroll(width(grow=grow)), v.parts, :unit_scroll)
  body = if n == 0
    float_none("No unit has that name")
  else
    # Half a row at the bottom says that the list goes on
    scroll.height = height(n <= MOST_UNITS ? n * high : MOST_UNITS * high - high / 2)
    m.pick == v.pick || (m.pick = v.pick; scroll_into_view!(scroll, high * (v.pick - 1), high * v.pick))
    reuse!(scroll, Column(width(grow=grow), Alignment.Start, [part!(() -> UnitRow(of=v, k=k), v, (:unit_row, k)) for k in 1:n]...))
  end
  float_list(plan_input(v), body, name="Units")
end

placed!(m::UnitMenu, side) = (m.side = side; nothing)
draw(ctx, size, ui::ConcreteRect, m::UnitMenu) = caret(ctx, ui, m.side, rect(unit_word(part!(() -> AmountCell(of=m.of, i=m.i), m.of, (:amount, m.i)))))

# The list sees a key before its field does. The arrows pick a unit, Return takes it, and Esc closes the list.
onkey(m::UnitMenu, ::KeyPress{Keys.enter}) = answer!(m.of)
onkey(m::UnitMenu, ::KeyPress{Keys.escape}) = stop_asking!(m.of)
onkey(m::UnitMenu, ::KeyPress{Keys.down}) = (v = m.of; v.pick = min(v.pick + 1, max(1, length(v.rows))); handled)
onkey(m::UnitMenu, ::KeyPress{Keys.up}) = (v = m.of; v.pick = max(v.pick - 1, 1); handled)

# --- the list that a search shows --------------------------------------------------------
#
# What a search finds shows in a list that floats beside the text field. It
# looks like the lists in Centient's own forms: a cream box with an arrow that
# points at the field, and in it a card with a line for each thing found. The
# up and down arrows pick a line, and so does the mouse. Return or a click
# takes it. Esc closes the list, and so does a click somewhere else.

const FOUND_KEY = :takeoff_found
"The colours of the list: Centient's cream in a light page, and the page's own in a dark one"
found_colours() = dark_page() ?
  (frame=colours.float, pick=colours.active, ink=colours.ink, dim=colours.dim, line=colorant"rgb(86,86,94)", rule=colours.line) :
  (frame=colorant"rgb(233,224,202)", pick=colorant"rgb(224,212,185)", ink=colorant"rgb(27,23,16)", dim=colorant"rgb(110,104,88)",
   line=colorant"rgb(176,164,136)", rule=colorant"rgb(221,212,192)")

# The search for an item looks in one catalogue at a time, as Centient's own
# item field does. It starts in the business's own items. ⌥ in an empty field,
# or a click on the foot of the list, shows the suppliers whose catalogues
# Centient holds. A supplier chosen there opens its catalogue, and the search
# goes on in that. ⌥ again goes back to the suppliers, and from the suppliers
# to the business's own items. The next search starts where an item was last
# chosen from.

"""
The catalogue that the search for an item looks in: `(:own,)` for the
business's own items, `(:suppliers,)` for the list of suppliers to choose a
catalogue from, or `(:catalogue, slug, name)` for one supplier's.
"""
const ITEM_FROM = Ref{Any}((:own,))

"Look in another catalogue. The words that were typed go, and a search of the new one starts now."
browse!(v::TakeoffView, from) = begin
  ITEM_FROM[] = from
  i = plan_input(v)
  i.text = ""
  i.anchor, i.cursor = 0, 0
  v.rows, v.search, v.pick = Any[], nothing, 1
  v.query, v.typed = "", time() - 1
  handled
end

"Go from the business's own items to the list of suppliers, and from the list or a supplier's catalogue back"
toggle_catalogue!(v::TakeoffView) = browse!(v, ITEM_FROM[][1] == :catalogue ? (:suppliers,) : ITEM_FROM[][1] == :suppliers ? (:own,) : (:suppliers,))

"What the foot of the list says of the catalogue that it shows"
catalogue_words() = (from = ITEM_FROM[]; from[1] == :own ? "Our catalogue" : from[1] == :suppliers ? "Pick a catalogue" : from[3])

"True when the list shows suppliers to choose from, and false when it shows items"
lists_suppliers(v::TakeoffView) = v.asking !== nothing && v.asking[1] == :item && ITEM_FROM[][1] == :suppliers

"How tall a line of the list is. An item has a second line under its name. A contact or a supplier has its name and no more."
found_h(v::TakeoffView) = v.asking == (:customer,) || lists_suppliers(v) ? 34px : 50px

"Show the list of what the search finds, beside the text field"
show_found!(v::TakeoffView) = begin
  w = window_of(v)
  w === nothing && return
  e = editor(v)
  wide = min(v.asking == (:customer,) ? 340px : 460px, window_size(e)[1] - 16px)
  list = FoundList(of=v)
  v.parts[:found_list] = list
  # The keys stay with the text field, and a click outside the list is the app's, as it is with no list
  list.popup = popup!(w, list, anchor=plan_input(v), placement=:bottom, gap=FOUND_GAP, width=wide, key=FOUND_KEY, modal=false,
                      onclose=() -> stop_asking!(v), theme=component_theme(e.zoom))
end

const FOUND_GAP = 9px   # between the text field and the list, with the list's arrow in it

"""
Choose the side of the text field that the list is on, once for each time it
opens. The list goes under the field when the longest list fits there, and
if not, on the side with more room. A short list, like the one line that shows
while Centient searches, is then on the side that the long list will be on, so
the list doesn't jump from one side to the other.
"""
settle_side!(l::FoundList) = begin
  (l.settled || l.popup === nothing) && return
  v = l.of
  r = rect(plan_input(v))
  r === nothing && return
  item = v.asking !== nothing && v.asking[1] == :item
  # The longest list: its rows, the edges round them, and the foot that names the catalogue
  longest = MOST_FOUND * (item ? 50px : 34px) + 14px + (item ? 28px : 0px)
  over, under = r.top - FOUND_GAP, window_size(editor(v))[2] - r.top - r.height - FOUND_GAP
  l.popup.placement = under >= longest || under >= over ? :bottom : :top
  l.settled = true
end

placed!(l::FoundList, side) = (l.side = side; nothing)

describe(r::FoundRow) = begin
  v = r.of
  r.k <= length(v.rows) || return Box(height(0px))
  row = v.rows[r.k]
  c = found_colours()
  picked = v.pick == r.k
  ref = string(get(row, "ref", ""))
  # Under an item of the business is what it says of it. Under a supplier's product is the supplier's code for it.
  under = isempty(ref) ? "" : startswith(ref, "item ") ? string(something(get(row, "description", nothing), "")) : String(last(split(ref, ' ', limit=2)))
  # At the right is an item's price, and how many products a supplier's catalogue has
  right = !isempty(ref) ? price_text(row) : haskey(row, "slug") ? commas(round(Int, get(row, "products", 0))) * " products" : ""
  # A thin line parts two rows, but not the picked row from the ones beside it. A row with no line has one in its
  # own colour, so that its words don't move by the line's height when the pick comes to it or leaves it.
  back = picked ? c.pick : c.frame
  Row(width(grow=grow), height(found_h(v)), padding(12px, 0px), child_gap=10px, Alignment.Center, background(back),
      border(1px, :solid, r.k == 1 || picked || v.pick == r.k - 1 ? back : c.rule)[:top],
    # As tall as the row, so that what cuts a long name off at the side doesn't cut the tails of its g, p and y
    Column(width(grow=grow), height(grow=grow), Alignment.Start, justify=Alignment.Center, child_gap=6px, clip=true,
      label(string(row["name"]), 13px, color=c.ink),
      (isempty(under) ? () : (label(under, 11px, color=c.dim),))...),
    (isempty(right) ? () : (Box(label(right, 12px, color=c.dim)),))...)
end

cursor(::FoundRow) = :hand
onkey(r::FoundRow, ::KeyPress{Keys.mouse_left}) = choose_row!(r.of, r.k)
# The mouse picks the row that it's over, as the arrow keys do
onmouse(r::FoundRow, ::MouseMove) = begin
  v = r.of
  v.pick = r.k
  list = get(v.parts, :found_list, nothing)
  list === nothing || (list.pick = r.k)   # it's in sight already, so the list doesn't scroll to it
  handled
end

describe(l::FoundList) = begin
  v = l.of
  settle_side!(l)
  c = found_colours()
  high, n = found_h(v), length(v.rows)
  scroll = get!(() -> Scroll(width(grow=grow)), v.parts, :found_scroll)
  l.rows === v.rows || (l.rows = v.rows; l.pick = 0; scroll.offset = 0px)
  item = v.asking !== nothing && v.asking[1] == :item
  body = if n == 0
    words = v.search !== nothing || v.typed > 0 ? "Searching Centient…" :
            !isempty(v.query) && v.query != "\0" ? "Centient has nothing that matches" :
            lists_suppliers(v) ? "Centient holds no supplier's catalogue" : item ? "Nothing here yet" : "Type to search"
    Row(width(grow=grow), height(34px), padding(12px, 0px), Alignment.Center, background(c.frame), label(words, 12px, color=c.dim))
  else
    # Half a row at the bottom says that the list goes on
    scroll.height = height(min(n * high, MOST_FOUND * high - high / 2))
    l.pick == v.pick || (l.pick = v.pick; scroll_into_view!(scroll, high * (v.pick - 1), high * v.pick))
    reuse!(scroll, Column(width(grow=grow), Alignment.Start, [part!(() -> FoundRow(of=v, k=k), v, (:found, k)) for k in 1:n]...))
  end
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Found",
    Column(width(grow=grow), Alignment.Start, child_gap=4px,
      Column(width(grow=grow), Alignment.Start, radius(5px), border(1px, :solid, c.line), background(c.frame), clip=true, body),
      (item ? (part!(() -> CatalogueFoot(of=v), v, :catalogue_foot),) : ())...))
end

# The foot of the list of items says which catalogue it shows. A click on it does what ⌥ does.
describe(f::CatalogueFoot) = begin
  c = found_colours()
  Row(width(grow=grow), height(24px), padding(8px, 0px), radius(5px), child_gap=8px, Alignment.Center, background(ishovered(f) ? c.pick : c.frame),
    Row(width(grow=grow), height(grow=grow), Alignment.Center, clip=true, label(catalogue_words(), 12px, color=c.ink, weight="Semibold")),
    Box(label("⌥ to toggle catalogue", 11px, color=c.dim)))
end
cursor(::CatalogueFoot) = :hand
onmouse(::CatalogueFoot, ::MouseMove) = handled
onkey(f::CatalogueFoot, ::KeyPress{Keys.mouse_left}) = toggle_catalogue!(f.of)

"""
Draw the arrow of a floating box `ui`, on its edge that faces what it's for.
`side` is the side of that thing that the box is on, and `aim` is the thing's
rectangle. The arrow covers the box's border where it joins.
"""
caret(ctx, ui::ConcreteRect, side, aim) = begin
  aim === nothing && return
  c = found_colours()
  left, top, wide, high = num(ui.left), num(ui.top), num(ui.width), num(ui.height)
  x = clamp(num(aim.left + aim.width / 2), left + 16, max(left + 16, left + wide - 16))
  base, tip = side == :top ? (top + high - 1, top + high + 6) : (top + 1, top - 6)
  trace(ctx, [(x - 7, base), (x, tip), (x + 7, base)], c.line, 1; fill=c.frame)
end

draw(ctx, size, ui::ConcreteRect, l::FoundList) = caret(ctx, ui, l.side, rect(plan_input(l.of)))

# --- the columns of the table ------------------------------------------------------------
#
# The headings of the table of measures work as the headings of Centient's
# lists do. A click on a heading of numbers sorts by it: low to high, then high
# to low, then the order that the block is written in. A click on a heading of
# text opens a menu with its two orders and a field that searches the column.
# Return keeps the search, and Esc puts back the one before. A heading whose
# column is searched is in the accent colour. Sorting and searching change what
# the table shows, and nothing in the block or in the quote.

const HEAD_KEY = :takeoff_column
"The columns of the table that sort: the heading of each, and whether it holds text"
const COLUMNS = (item=("Item", true), extra=("Waste", false), amount=("Amount", false), price=("Price", false), cost=("Cost", false))
"What the two orders of a column are called"
order_words(text::Bool) = text ? ("A–Z", "Z–A") : ("Low → High", "High → Low")

"The item of a measure in words, as its column sorts and searches it: what the table calls it, and the catalogue that it's from"
item_words(v::TakeoffView, m) = (row = known(v, m.item); item_name(v, m) * (row === nothing ? "" : "  ·  " * string(row["source"])))

"What measure `i` has in the column `key`, as the thing that the column sorts by"
column_value(v::TakeoffView, i, key) = begin
  m = v.data.measures[i]
  key == :item && return lowercase(item_words(v, m))
  key == :extra && return m.extra
  amount, row = Plans.amount(v.data, m), known(v, m.item)
  key == :amount ? something(amount, -1.0) :
  key == :price  ? (row === nothing ? -1.0 : Float64(something(unit_price(m, row), row["price"]))) :
                   (row === nothing || amount === nothing ? -1.0 : cost_of(m, amount, row))
end

"Search the column `key` for `words`. No words takes its search away."
search_column!(v::TakeoffView, key::Symbol, words) = begin
  words = String(strip(words))
  isempty(words) ? delete!(v.filters, key) : (v.filters[key] = words)
  v
end

"The measures that the table shows, in the order that it shows them: those that the searches keep, sorted by the column that's chosen"
shown_measures(v::TakeoffView) = begin
  ms = v.data.measures
  # The item's column is the one that holds text, so a search is of it
  keep = [i for i in eachindex(ms) if all(words -> occursin(lowercase(words), lowercase(item_words(v, ms[i]))), values(v.filters))]
  v.sort === nothing ? keep : sort!(keep, by=i -> column_value(v, i, v.sort[1]), rev=v.sort[2] == :desc)
end

"The heading of the column `key`. `side` is the side of its cell that its words go on, and nothing keeps the side that it has."
head(v::TakeoffView, key::Symbol, side=nothing) = begin
  h = part!(() -> ColumnHead(of=v, key=key), v, (:head, key))
  side === nothing || (h.side = side)
  h
end

"""
The words of the heading of the column `key`. They belong to the heading, so a
click on them goes to it, and the mouse over them is over it.
"""
head_words(v::TakeoffView, key::Symbol) = begin
  h = head(v, key)
  h.words === nothing && (h.words = HeadWords(of=h); setfield!(h.words, :parent, h))
  h.words
end

"The order that a click on a heading of numbers gives next. It's nothing for the order that the block is written in."
next_order(v::TakeoffView, key) = v.sort === nothing || v.sort[1] != key ? :asc : v.sort[2] == :asc ? :desc : nothing

describe(h::ColumnHead) =
  Row(width(grow=grow), height(grow=grow), Alignment.Center, justify=h.side == :end ? Alignment.End : Alignment.Start, name="Heading",
    head_words(h.of, h.key))

describe(w::HeadWords) = begin
  h = w.of
  v = h.of
  words, text = COLUMNS[h.key]
  dir = v.sort !== nothing && v.sort[1] == h.key ? v.sort[2] : nothing
  open = v.asking !== nothing && v.asking[1] == :filter && v.asking[2] == h.key
  lit = ishovered(h) || open
  colour = haskey(v.filters, h.key) ? colours.accent : lit || dir !== nothing ? colours.ink : colours.dim
  # The arrow of the order that it has. With none, the mouse over it shows what a click gives.
  will = text ? :desc : next_order(v, h.key)
  mark = dir !== nothing ? (Icon(dir == :asc ? "chevron-up" : "chevron-down", size=9px, color=colours.ink),) :
         lit && will !== nothing ? (Icon(will == :asc ? "chevron-up" : "chevron-down", size=9px, color=colours.faint),) : ()
  parts = (label(words, 11px, color=colour), mark...)
  # The arrow goes on the side away from the cell's edge, so that it doesn't push the words when it shows
  Row(height(20px), child_gap=4px, Alignment.Center, (h.side == :start ? parts : reverse(parts))...)
end

cursor(::ColumnHead) = :hand

# A heading of numbers says what a click on it does
onmouse(h::ColumnHead, ev::MouseMove) = begin
  COLUMNS[h.key][2] && return
  will = next_order(h.of, h.key)
  low, high = order_words(false)
  words = will == :asc ? low : will == :desc ? high : "The order they're written in"
  # The tooltip follows the words: the mouse over them shows their arrow, which makes them wider on the next frame
  show_tooltip!(ev.window, tip_label(words), head_words(h.of, h.key), placement=:bottom, gap=6px)
end

onkey(h::ColumnHead, ev::KeyPress{Keys.mouse_left}) = begin
  v = h.of
  hide_tooltip!(ev.window)
  settle_asking!(v)
  COLUMNS[h.key][2] || return (will = next_order(v, h.key); v.sort = will === nothing ? nothing : (h.key, will); handled)
  # The menu's field starts with the column's search, which Esc puts back
  was = get(v.filters, h.key, "")
  ask!(v, (:filter, h.key, was), was, "Contains…")
  menu = ColumnMenu(of=v, key=h.key)
  v.parts[:column_menu] = menu
  # A click outside the menu closes it and keeps what's typed
  popup!(ev.window, menu, anchor=head_words(v, h.key), placement=:bottom, gap=9px, width=210px, key=HEAD_KEY,
         onclose=() -> settle_asking!(v), theme=component_theme(editor(v).zoom))
  handled
end

placed!(m::ColumnMenu, side) = (m.side = side; nothing)

describe(r::SortRow) = begin
  v, c = r.of, found_colours()
  on = v.sort == (r.key, r.dir)
  words = order_words(COLUMNS[r.key][2])[r.dir == :asc ? 1 : 2]
  Row(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      background(on || ishovered(r) ? c.pick : c.frame),
    Icon(r.dir == :asc ? "chevron-up" : "chevron-down", size=10px, color=on ? c.ink : c.dim),
    label(words, 13px, color=on ? c.ink : c.dim, weight=on ? "Semibold" : ""))
end

cursor(::SortRow) = :hand
onmouse(::SortRow, ::MouseMove) = handled
# A click on the order that the table has takes it away
onkey(r::SortRow, ::KeyPress{Keys.mouse_left}) = (v = r.of; v.sort = v.sort == (r.key, r.dir) ? nothing : (r.key, r.dir); handled)

describe(m::ColumnMenu) = begin
  v, c = m.of, found_colours()
  section(words) = Row(width(grow=grow), height(22px), padding(8px, 0px), Alignment.Center, label(words, 10px, color=c.dim, weight="Semibold"))
  order(dir) = part!(() -> SortRow(of=v, key=m.key, dir=dir), v, (:sort, m.key, dir))
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Column menu",
    Column(width(grow=grow), Alignment.Start,
      section("SORT"), order(:asc), order(:desc),
      Box(width(grow=grow), height(13px), Alignment.Center, Box(width(grow=grow), height(1px), background(c.rule))),
      section("FILTER FOR"),
      Box(width(grow=grow), padding(4px, 2px),
        Box(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), border(1px, :solid, c.line), background(c.frame), plan_input(v)))))
end

draw(ctx, size, ui::ConcreteRect, m::ColumnMenu) = caret(ctx, ui, m.side, rect(head_words(m.of, m.key)))

# The menu sees a key before its text field does. Return keeps the search, and Esc puts back the one before.
onkey(m::ColumnMenu, ::KeyPress{Keys.enter}) = answer!(m.of)
onkey(m::ColumnMenu, ::KeyPress{Keys.escape}) = begin
  v = m.of
  a = v.asking
  a !== nothing && a[1] == :filter && search_column!(v, a[2], a[3])
  stop_asking!(v)
end

# --- the whole block ---------------------------------------------------------------------

"A thin line between two groups of buttons"
rule() = Box(width(9px), height(16px), Alignment.Center, Box(width(1px), height(16px), background(colours.line)))

toolbar(v::TakeoffView) = begin
  t = v.data
  n = plan_pages(v)
  s = Plans.scale(t, t.page)
  file = isempty(t.plan) ? "Choose a plan" : basename(t.plan)
  Row(width(grow=grow), height(38px), padding(6px, 0px), child_gap=2px, Alignment.Center, background(colours.block),
    [button!(v, (:tool, tool), (:tool, tool), icon=icon, tip=tip) for (tool, (icon, tip, _)) in PLAN_TOOLS]...,
    rule(),
    button!(v, :snap, :snap, icon="magnet", tip=v.snap ? "Corners snap to the lines of the plan. Click to stop that, or hold ⌘." : "Snap corners to the lines of the plan"),
    rule(),
    button!(v, :scale, :scale, words=s === nothing ? "Set the scale" : Plans.scale_text(s), tip="Type the scale of this page, like 1:100"),
    (n > 1 ? (rule(), button!(v, :back, (:page, -1), icon="chevron-left", tip="The page before", off=t.page <= 1),
              label("Page $(t.page) of $n", 12px, color=colours.dim),
              button!(v, :next, (:page, 1), icon="chevron-right", tip="The next page", off=t.page >= n)) : ())...,
    Box(width(grow=grow)),
    button!(v, :smaller, (:zoom, 1 / 1.4), icon="zoom-out", tip="Smaller"),
    button!(v, :bigger, (:zoom, 1.4), icon="zoom-in", tip=v.full ? "Bigger  pinch, or the mouse wheel" : "Bigger  pinch, or ⌘ and scroll"),
    button!(v, :fit, :fit, icon="aspect-ratio", tip="Show the whole page"),
    button!(v, :full, :full, icon=v.full ? "fullscreen-exit" : "arrows-fullscreen", tip=v.full ? "Back to the page  esc" : "Fill the window"),
    rule(),
    button!(v, :plan, :choose, icon="file-earmark-pdf", words=length(file) > 28 ? first(file, 27) * "…" : file, tip="Choose the plan's file"))
end

"The line under the tools that asks for the scale, or for the length of the line that was drawn"
prompt(v::TakeoffView) = begin
  a = v.asking
  (a !== nothing && a[1] in (:scale, :length)) || return ()
  words, hint = a[1] == :scale ? ("The scale of this page", "like 1:100, then Return") :
                                 ("How long is the line that you drew?", "in metres, like 3.6, or 3600mm, then Return")
  (Row(width(grow=grow), height(36px), padding(12px, 0px), child_gap=10px, Alignment.Center, background(colours.float),
     label(words, 12px), field(v, fixed(110px)), label(hint, 12px, color=colours.dim)),)
end

"""
True when a measure has an item of Centient's catalogue. Only then is there a
price to show, so only then has the table its columns for the price and the cost.
"""
has_items(v::TakeoffView) = any(m -> !isempty(m.item), v.data.measures)

"True when the table of measures shows the price of one of each item: when a measure has an item, and there's room"
has_price(v::TakeoffView) = has_items(v) && editor(v).width >= 720px

"""
The headings of the table of measures. Each is as wide as the cells under it.
The panel beside a plan has two lines for each measure, so it has two
headings and no more: the item and its cost. The cost and the price have
headings only while a measure has an item.
"""
table_head(v::TakeoffView) = begin
  # Each heading fills its cell, so the mouse can use it anywhere over its column
  left(key) = Row(width(grow=grow), height(grow=grow), Alignment.Center, clip=true, head(v, key, :start))
  right(wide, key) = Row(wide, height(grow=grow), Alignment.Center, clip=true, (key === nothing ? () : (head(v, key, :end),))...)
  # With no Centient on the Mac there are no prices, so the columns for them have no headings
  ours(key) = Centient.available() ? key : nothing
  cost = has_items(v) ? (right(fixed(88px), ours(:cost)),) : ()
  look = (width(grow=grow), height(26px), Alignment.Center, background(colours.head), border(1px, :solid, colours.line)[:bottom])
  v.beside && return Row(look..., padding(10px, 0px), child_gap=8px, name="Headings",
    Box(width(14px)), left(:item), cost..., Box(width(28px)))
  Row(look..., padding(10px, 0px), child_gap=10px, name="Headings",
    Box(width(14px)), left(:item), Row(fixed(52px), height(grow=grow), Alignment.Center, clip=true, head(v, :extra, :start)),
    right(fixed(AMOUNT_W), :amount), (has_price(v) ? (right(fixed(96px), ours(:price)),) : ())..., cost...,
    Box(width(28px)))   # over the buttons that remove a measure
end

"""
The table of measures, in a box of its own with round corners: the headings,
then `rows`, then the button that adds a measure. `tall` makes it fill the
height that it's given.
"""
table(v::TakeoffView, rows; tall=false) =
  Box(width(grow=grow), (tall ? (height(grow=grow),) : ())..., padding(10px, 8px),
    Column(width(grow=grow), (tall ? (height(grow=grow),) : ())..., Alignment.Start, radius(8px), border(1px, :solid, colours.line),
           background(colours.bg), clip=true, name="Measures",
      table_head(v), rows, adders(v)))

"""
The buttons at the foot of the table that start a new measure. One starts a
measure that you describe in words. The other starts one for an item of
Centient's catalogue, and shows only on a Mac that has Centient.
"""
adders(v::TakeoffView) =
  Row(width(grow=grow), height(36px), padding(6px, 0px), child_gap=2px, Alignment.Center, border(1px, :solid, colours.line)[:top],
    button!(v, :add, :add, icon="plus-lg", words="Add a measure",
            tip="Say what it measures. Then choose a tool: count, length or area."),
    (Centient.available() ? (button!(v, :add_item, :add_item, icon="box-seam", words="Add from catalogue",
                                     tip="Choose an item of Centient's catalogue. Its unit chooses the tool."),) : ())...)

"The rows of the table of measures: those that the columns' searches keep, in the order of the column that's sorted"
measure_rows(v::TakeoffView) = begin
  v.order = shown_measures(v)
  isempty(v.order) && !isempty(v.data.measures) &&
    return Any[Row(width(grow=grow), height(32px), padding(34px, 0px), Alignment.Center, label("No measure has that", 12px, color=colours.dim))]
  Any[part!(() -> MeasureRow(of=v, i=i), v, (:row, i)) for i in v.order]
end

"The line at the foot of the block: the customer, what the measures come to, and the button that makes the quote"
foot(v::TakeoffView) = begin
  t = v.data
  total, priced, all_priced = 0.0, false, true
  for m in t.measures
    amount, row = Plans.amount(t, m), known(v, m.item)
    (amount === nothing || row === nothing) && (all_priced = false; continue)
    total += cost_of(m, amount, row)
    priced = true
  end
  # The total is of the measures that have an item. While a measure has none, the words say that the total leaves it out.
  total_words = all_priced ? "At catalogue prices" : "Catalogue items only"
  asking = v.asking == (:customer,)
  busy = v.quoting !== nothing
  said = isempty(v.said) ? (isempty(t.made) ? "" : "Quote $(t.made)") : v.said
  colour = v.wrong ? colours.accent : colours.dim
  customer = asking ? field(v, v.beside ? width(grow=grow) : fixed(220px)) :
             button!(v, :customer, :customer, words=isempty(t.customer) ? "Choose the customer" : t.customer, tip="Who the quote is for")
  maker = button!(v, :quote, :quote, icon="receipt", words=busy ? "Making the quote…" : isempty(t.made) ? "Make quote in Centient" : "Make another quote",
                  tip=Centient.available() ? "Centient makes a quote with a line for each measure" : "Centient isn't on this Mac",
                  off=busy || isempty(t.measures) || !Centient.available())
  line = border(1px, :solid, colours.line)[:top]
  # In the panel beside a plan that fills the window, each part of the foot has a line of its own
  v.beside && return Column(width(grow=grow), Alignment.Start, padding(10px, 8px), child_gap=6px, line,
    Row(width(grow=grow), height(28px), child_gap=8px, Alignment.Center, Icon("person", size=14px, color=colours.dim), customer),
    (priced ? (Row(width(grow=grow), height(22px), Alignment.Center, Box(label(total_words, 12px, color=colours.dim)),
                   Box(width(grow=grow)), Box(label(dollars(total), 13px, weight="Semibold"))),) : ())...,
    (isempty(said) ? () : (Box(width(grow=grow), Alignment.Start, Text(said, size=12px, family=SANS, color=colour, wrap=WrapMode.words)),))...,
    Row(width(grow=grow), justify=Alignment.End, maker))
  Row(width(grow=grow), height(42px), padding(10px, 0px), child_gap=8px, Alignment.Center, line,
    Icon("person", size=14px, color=colours.dim), customer,
    Row(width(grow=grow), clip=true, justify=Alignment.End, Box(label(said, 12px, color=colour))),
    # The catalogue's prices, before the GST and the margins that Centient adds to a quote
    (priced ? (label(total_words, 12px, color=colours.dim), label(dollars(total), 13px, weight="Semibold")) : ())...,
    maker)
end

"How tall the list of measures is, with what a search found under one of them"
list_h(v::TakeoffView) = 32px * max(1, length(v.order))

"The most of the window's height that the list of measures takes under a plan that fills the window"
const LIST_SHARE = 0.4

"""
True when the list of measures goes beside a plan that fills the window, and
false when it goes under it. It goes where it leaves the page bigger: beside a
wide window's plan, and under a tall window's.
"""
goes_beside(v::TakeoffView) = begin
  w, h = num.(window_size(editor(v)))
  h -= num(TOPBAR_H) + 38   # the top bar and the tools
  s = plan_size(v)
  s === nothing && return w > h
  side = min(num(SIDE_W), 0.45w)
  # Under the plan are the table, with its headings, its rows and the button that adds a measure, and the foot
  under = min(32.0 * length(v.data.measures), LIST_SHARE * h) + 26 + 36 + 18 + 42
  min((w - side) / s[1], h / s[2]) >= min(w / s[1], (h - under) / s[2])
end

describe(v::TakeoffView) = begin
  e = editor(v)
  plan_input(v).color = colours.ink
  area = part!(() -> PlanArea(of=v), v, :area)
  v.beside = v.full && goes_beside(v)
  with_theme(component_theme(e.zoom)) do
    # Only the tools have a colour of their own behind them. The rest is on white, and the plan's paper has a shadow.
    v.full || return Column(width(grow=grow), Alignment.Start, radius(8px), border(1px, :solid, colours.line), background(takeoff_back()),
                            clip=true, name="Takeoff",
      toolbar(v), prompt(v)..., area,
      table(v, Column(width(grow=grow), Alignment.Start, measure_rows(v)...)),
      foot(v))
    # In the window, the plan is as big as it can be. The wheel scrolls through a list of measures that's longer than its room.
    list = get!(() -> Scroll(width(grow=grow), height(grow=grow)), v.parts, :list)
    rows = Column(width(grow=grow), Alignment.Start, measure_rows(v)...)
    if v.beside
      list.height = height(grow=grow)
      return Row(width(grow=grow), height(grow=grow), Alignment.Start, background(takeoff_back()), name="Takeoff",
        Column(width(grow=grow), height(grow=grow), Alignment.Start, toolbar(v), prompt(v)..., area),
        Column(fixed(min(SIDE_W, window_size(e)[1] * 0.45)), height(grow=grow), Alignment.Start, border(1px, :solid, colours.line)[:left],
          table(v, reuse!(list, rows), tall=true), foot(v)))
    end
    list.height = height(min(list_h(v), (window_size(e)[2] - TOPBAR_H - 38px) * LIST_SHARE))
    Column(width(grow=grow), height(grow=grow), Alignment.Start, background(takeoff_back()), name="Takeoff",
      toolbar(v), prompt(v)..., area, table(v, reuse!(list, rows)), foot(v))
  end
end

cursor(::TakeoffView) = :arrow

# --- what a takeoff's parts read -----------------------------------------------------------
#
# UI.jl describes a node again only when its `inputs` have changed, and otherwise
# uses its last geometry and layout. A takeoff's parts read its measures, its
# state and the page around it. So each part gives one number for all of that,
# which the takeoff works out once a frame, and the fields of its own that it
# reads. On a frame where nothing changed, nothing in the takeoff is described
# or laid out again: that was half the time a page with a takeoff took to
# describe. The lists that float over the page, of a search, of units and of a
# column's menu, have no `inputs`, so they're described on each frame while
# they're open. So is the takeoff while its text field shows, which has none.

"""
Everything that the parts of takeoff `v` read as they're described, as values.
A part that shows something that isn't here has to add it, or it won't change
when that does.
"""
shown_state(v::TakeoffView) = begin
  e = editor(v)
  (Plans.written(v.data), v.asking, v.current, v.filters, v.full, v.known, v.quoting === nothing, v.said, v.sort,
   v.tool, v.snap, v.wrong, e.width, e.zoom, window_size(e), plan_path(v), plan_size(v), plan_pages(v), Centient.available(),
   ntuple(k -> getfield(colours, k), nfields(colours)))
end

# UI.jl asks for the takeoff's inputs before those of its parts on each frame
inputs(v::TakeoffView) = (v.reads = hash(shown_state(v)); (v.reads,))
inputs(a::PlanArea) = (a.of.reads,)
# A schedule's buttons are PlanButtons too. They're described on each frame, as the schedule is.
inputs(b::PlanButton) = b.of isa TakeoffView ? (b.action, b.icon, b.words, b.tip, b.off, b.quiet, b.of.reads) : nothing
inputs(r::MeasureRow) = (r.i, r.of.reads)
inputs(c::AmountCell) = (c.i, c.of.reads)
inputs(u::UnitWord) = (u.of.i, u.of.of.reads)
inputs(c::MeasureCell) = (c.i, c.what, c.rect[3], c.of.reads)   # its width cuts its words short. Where it is doesn't matter.
inputs(h::ColumnHead) = (h.key, h.side, h.of.reads)
inputs(w::HeadWords) = (w.of.key, w.of.side, ishovered(w.of), w.of.of.reads)   # it's lit while the mouse is over its heading
# A click beside a button is the block's, and takes the keyboard from the text field
onkey(v::TakeoffView, ::KeyPress{Keys.mouse_left}) = (focus(part!(() -> PlanArea(of=v), v, :area)); handled)
onmouse(v::TakeoffView, ::MouseMove) = held(v, Keys.mouse_left) ? handled : nothing

# --- a schedule of the page's tasks -------------------------------------------------------
#
# A code block in the language `schedule` shows each to-do item of the page as
# a bar on a line of days. schedule.jl says how the block is written.
#
#   - Drag a bar to say the first day that its task can start.
#   - Drag the right end of a bar to say how many working days the task takes.
#   - Drag from the circle after a bar to another task. That task then waits
#     for this one, and starts when this one is finished. An arrow shows it.
#   - Click an arrow and press Delete to take it away.
#   - Click a task twice to go to its line of the page.
#   - Drag the days, or scroll sideways, to see other days. Pinch, or scroll
#     with ⌘ held, to show more days or fewer.
#   - The button at the top right makes the schedule fill the window. Esc puts
#     it back in the page.
#
# Every change is written into the block's lines, so the file holds the whole
# schedule. While the page has a schedule, the mouse over a to-do item shows
# the task's days beside the item, with buttons that make the task a day
# longer or shorter.

const SCHEDULE = Schedules.SCHEDULE
const TASK_H = 30.0        # px: how tall the row of a task is
const TASK_BAR = 20.0         # and how tall its bar is
const DATES_H = 46.0       # how tall the months and the days over the rows are
const DAY_MOST = 60.0      # the most px to a day
const DAY_LEAST = 2.5      # and the least
const DAY_USUAL = 34.0     # the most px to a day when a schedule shows all its tasks
const BAR_EDGE = 7.0       # px at the right end of a bar, where a drag makes the task longer or shorter
const KNOB = 4.5           # the radius of the circle after a bar, which a link is dragged from
const KNOB_GAP = 11.0      # from the end of a bar to the middle of that circle
const NAMES_W = 250px      # how wide the names of the tasks are at the most
const NAMES_FULL = 360px   # and at the most in a schedule that fills the window
const DETAILS_H = 24px     # how tall the days of a to-do item are beside the item
const DAY_ZERO = Date(2000, 1, 1)   # day number 0
"Every icon that a schedule can show. The built app reads them all when it's made."
const SCHEDULE_ICONS = ["bar-chart-steps", "calendar-event", "zoom-out", "zoom-in", "aspect-ratio", "dash", "plus", "check",
                        "arrows-fullscreen", "fullscreen-exit"]

"What a `schedule` block shows: the page's tasks, each as a bar on a line of days"
@def mutable struct ScheduleView <: SemanticUI
  n::Int = 0                              # its place among the page's schedules
  first::Int = 0                          # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Schedules.Schedule = Schedules.Schedule()
  lines::Vector{String} = String[]        # the lines that `data` was read from
  tasks::Vector{Schedules.Planned} = Schedules.Planned[]   # the page's tasks, with the days of each
  planned::Any = nothing                  # the version of the page, and the day, that `tasks` was worked out for
  renamed::Bool = false                   # a task has a new name that the block's lines don't have yet
  zoom::Float64 = 0.0                     # px to a day. 0 shows every task.
  at::Float64 = 0.0                       # the number of the day at the left edge of the bars
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the days and the bars were last drawn in the window
  picked::Any = nothing                   # what's selected: (:task, key), or (:link, key, key) for the link from one task to the next
  grab::Any = nothing                     # a drag: of a bar, of a bar's end, of a link or of the days
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where it was last clicked
  asking::Bool = false                    # the text field for the day that the work starts shows
  said::String = ""                       # what the top of the block says when something can't be done
  parts::Dict{Any,Any} = Dict{Any,Any}()  # its buttons, names and text field, kept between frames
  full::Bool = false                      # it fills the window, over the page
  tall::px = 0px                          # how tall it was in the page when it was last laid out there
  pinned::px = 0px                        # how far the page was scrolled when it filled the window
end

"The part of a schedule that shows the days and the bars"
@def mutable struct ChartArea <: SemanticUI
  of::Any = nothing
end
"The name of a task, beside its bar"
@def mutable struct TaskName <: SemanticUI
  of::Any = nothing
  key::String = ""
end
"""
The days of the to-do item under the mouse. They show beside the item while
the page has a schedule: the task's first and last day, how many days it
takes, and what it waits for.
"""
@def mutable struct TaskDetails <: SemanticUI
  of::Any = nothing                # the schedule
  key::String = ""                 # the task
  floats::Bool = false             # it's under the item's first line, because that line has no room for it
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where it was last put in the window
  less::Any = nothing              # its two buttons
  more::Any = nothing
end
"A button beside a to-do item that makes its task a day longer or a day shorter"
@def mutable struct DayButton <: SemanticUI
  by::Int = 1
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)
end

"A part of `v` that's kept between frames"
part!(make, v::ScheduleView, key) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, v)
  node
end

"The button of `v` that's kept under `key`, with what it does and shows now"
button!(v::ScheduleView, key, action; icon="", words="", tip="", off=false) = begin
  b = part!(() -> PlanButton(of=v), v, (:button, key))
  b.action, b.icon, b.words, b.tip, b.off = action, icon, words, tip, off
  b
end

"The text field of a schedule, for the day that the work starts"
schedule_input(v::ScheduleView) = part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

field(v::ScheduleView, wide=width(grow=grow)) =
  Box(wide, height(24px), padding(6px, 0px), radius(5px), border(1px, :solid, colours.accent), background(colours.bg), schedule_input(v))

chart(v::ScheduleView) = part!(() -> ChartArea(of=v), v, :area)

# --- the block's lines and the page's tasks -------------------------------------------------

"The to-do items of the page that shows"
page_todos(e) = (b = e.buf; get!(() -> Schedules.todos(b.lines, kinds(b)), e.flows, (:todos, b.path, b.version)))

"The view of the `n`th schedule of the page that shows"
schedule_view(e, n) = begin
  v = get!(() -> ScheduleView(n=n), e.nodes, (:schedule, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v
end

"Read the schedule again from the lines of its block, if they've changed"
reread!(v::ScheduleView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  start = v.data.start
  v.data = Schedules.schedule(lines)
  v.planned = nothing
  v.renamed = false
  # When the work starts on another day, as it does after ⌘Z takes a new day back, every task shows again
  v.data.start == start || (v.zoom = 0.0)
  v
end

"Work out the days of the page's tasks again. A task that was renamed in the page keeps its line of the schedule."
replan!(v::ScheduleView) = begin
  e = editor(v)
  names = [entry.name for entry in v.data.entries]
  v.tasks = Schedules.plan!(v.data, page_todos(e))
  names == [entry.name for entry in v.data.entries] || (v.renamed = true)
  v.planned = (e.buf.version, Dates.today())
  v
end

"The page's tasks with the days of each. They're worked out again when the page has changed, and on a new day."
tasks!(v::ScheduleView) = (v.planned == (editor(v).buf.version, Dates.today()) || replan!(v); v.tasks)

"The place of the task called `key` in the list of tasks, or nothing"
task_place(v::ScheduleView, key) = findfirst(t -> t.todo.key == key, v.tasks)

"""
Write the schedule into its block. The caret stays where it was in the text,
and ⌘Z takes the change back. If the block's lines aren't the ones that the
schedule was read from, something else changed them, and the schedule is read
again. The lines of tasks that the page no longer has go.
"""
commit!(v::ScheduleView) = begin
  e = editor(v)
  b = e.buf
  readonly(b) && return v
  span = block_lines(b, SCHEDULE, v.n)
  span === nothing && return v
  i, t = span
  v.first, v.last = i, t
  b.lines[i+1:t-1] == v.lines || return reread!(v, b.lines[i+1:t-1])
  # The day that the work starts is written down, so that it's the same day tomorrow
  v.data.start === nothing && (v.data.start = Schedules.workday(Dates.today(), v.data.weekends))
  Schedules.prune!(v.data, page_todos(e))
  new = Schedules.written(v.data)
  v.planned = nothing
  v.renamed = false
  new == v.lines && return v
  caret, anchor = b.caret, b.anchor
  edit!(b, line_end(b, i), line_end(b, t - 1), isempty(new) ? "" : "\n" * join(new, "\n"))
  by = length(new) - length(v.lines)
  moved(p) = p[1] >= t ? (p[1] + by, p[2]) : p[1] > i ? (i, 0) : p
  b.caret, b.anchor = moved(caret), moved(anchor)
  v.last += by
  v.lines = new
  v
end

"What the `schedule` block from line `i` to line `t` shows. `n` is its place among the page's schedules."
schedule_item(e, i, t, n) = begin
  v = schedule_view(e, n)
  v.first, v.last = i, t
  reread!(v, e.buf.lines[i+1:t-1])
  tasks!(v)
  # A schedule that fills the window is drawn over the page, and its room in the page stays empty
  v.full && return Live(Box(width(grow=grow), height(v.tall)), v.tall + 2LIVE_GAP)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(v)), (e.width, 9999px))
  v.tall = concrete.height
  Live(v, v.tall + 2LIVE_GAP)
end

"Make the schedule fill the window, or put it back in the page. Either way it shows every task again."
full!(v::ScheduleView, on::Bool) = begin
  e = editor(v)
  on && unfill!(e)   # one block at a time fills the window
  v.full = on
  v.pinned = e.scroll.offset
  v.zoom = 0.0
  focus(chart(v))
  handled
end

"How tall the names and the bars are in a schedule that fills the window, when its tasks need less: the window, under the top bar and the schedule's buttons"
full_room(v::ScheduleView) = num(window_size(editor(v))[2] - TOPBAR_H - 38px)

"How tall the names and the bars of a schedule are"
chart_h(v::ScheduleView) = (rows = DATES_H + TASK_H * length(v.tasks); px(v.full ? max(rows, full_room(v)) : rows))

"""
Write the page to its file. A task that was renamed in the page since its
schedule was last written gets its new name in the schedule first, so that the
file's schedule names the tasks as the file's to-do items do.
"""
save_page!(e) = begin
  write_blocks!(e)   # what a block that a file defines holds now goes into its lines
  for (key, node) in collect(e.nodes)
    (node isa ScheduleView && key[2] == e.buf.path) || continue
    span = block_lines(e.buf, SCHEDULE, node.n)
    span === nothing && continue
    reread!(node, e.buf.lines[span[1]+1:span[2]-1])
    tasks!(node)
    node.renamed && commit!(node)
  end
  save!(e.buf)
end

# --- where things are ------------------------------------------------------------------------

"The number of the day `d`: one more for each day that passes"
daynum(d::Date) = Float64(Dates.value(d - DAY_ZERO))
"The day with the number `n`"
numday(n::Real) = DAY_ZERO + Day(floor(Int, n))

"How far across the window day number `n` starts"
day_x(v::ScheduleView, n::Real) = v.box[1] + (n - v.at) * v.zoom
"The number of the day at `x` across the window, with the part of the day that's passed"
x_day(v::ScheduleView, x::Real) = v.at + (x - v.box[1]) / v.zoom

"Where the bar of the task at place `i` is in the window: its left, top, width and height"
task_bar(v::ScheduleView, i::Int) = begin
  t = v.tasks[i]
  left, right = day_x(v, daynum(t.start)) + 1, day_x(v, daynum(t.finish) + 1) - 1
  (left, v.box[2] + DATES_H + (i - 1) * TASK_H + (TASK_H - TASK_BAR) / 2, max(right - left, 3.0), TASK_BAR)
end

"The middle of the circle after the bar of the task at place `i`"
knob(v::ScheduleView, i::Int) = (b = task_bar(v, i); (b[1] + b[3] + KNOB_GAP, b[2] + b[4] / 2))

"The place of the task whose row is `y` down the window, or nothing"
row_at(v::ScheduleView, y::Real) = begin
  i = floor(Int, (y - v.box[2] - DATES_H) / TASK_H) + 1
  1 <= i <= length(v.tasks) ? i : nothing
end

"""
The corners of the arrow from the end of task `a`'s bar to the start of task
`b`'s. Where the bars leave no room to turn between them, it goes round,
between two rows.
"""
link_points(v::ScheduleView, a::Int, b::Int) = begin
  from, to = task_bar(v, a), task_bar(v, b)
  sx, sy = from[1] + from[3], from[2] + from[4] / 2
  tx, ty = to[1], to[2] + to[4] / 2
  out = sx + 8
  tx - out >= 8 && return [(sx, sy), (out, sy), (out, ty), (tx, ty)]
  between = sy + sign(ty - sy) * TASK_H / 2
  back = tx - 9
  [(sx, sy), (out, sy), (out, between), (back, between), (back, ty), (tx, ty)]
end

"How far the place `(x, y)` is from the line through the places `ps`"
away(ps, x, y) = minimum(1:length(ps)-1) do k
  (ax, ay), (bx, by) = ps[k], ps[k+1]
  long = (bx - ax)^2 + (by - ay)^2
  along = long == 0 ? 0.0 : clamp(((x - ax) * (bx - ax) + (y - ay) * (by - ay)) / long, 0, 1)
  hypot(x - ax - along * (bx - ax), y - ay - along * (by - ay))
end

"""
What's at the place `(x, y)` of a schedule's bars: `(:knob, i)` for the circle
after the bar of the task at place `i`, `(:edge, i)` for the right end of its
bar, `(:bar, i)` for the rest of the bar, `(:link, a, b)` for the arrow from
task `a` to task `b`, `(:row, i)` for the rest of the task's row, or nothing.
"""
under(v::ScheduleView, x::Real, y::Real) = begin
  left, top, wide, tall = v.box
  (v.zoom > 0 && left <= x < left + wide && top + DATES_H <= y < top + tall) || return nothing
  i = row_at(v, y)
  i === nothing && return nothing
  bx, by, bw, bh = task_bar(v, i)
  kx, ky = knob(v, i)
  hypot(x - kx, y - ky) <= KNOB + 3 && return (:knob, i)
  if by - 2 <= y < by + bh + 2 && bx <= x < bx + bw + 3
    return x >= bx + bw - min(BAR_EDGE, bw / 2) ? (:edge, i) : (:bar, i)
  end
  for (b, t) in enumerate(v.tasks), a in t.after
    away(link_points(v, a, b), x, y) <= 4 && return (:link, a, b)
  end
  (:row, i)
end

"The place of the task whose row the mouse is over, in its name or in its bar's row, or 0"
hot_row(v::ScheduleView) = begin
  w = window_of(v)
  (w === nothing || !ishovered(v) || v.zoom <= 0) && return 0
  something(row_at(v, num(w.mouse[2])), 0)
end

"The days of a task in words: Mon 16 Nov – Wed 18 Nov"
task_days(t) = t.start == t.finish ? Schedules.short(t.start) : Schedules.short(t.start) * " – " * Schedules.short(t.finish)
"The days of a task and how many they are: Mon 16 Nov – Wed 18 Nov  ·  3 days"
task_words(t) = task_days(t) * "  ·  " * Schedules.days_text(t.days)

"""
Show every task: the days from the day before the first task starts to the
day after the last one finishes. A short schedule's days are no wider than
`DAY_USUAL` in the page, and no wider than `DAY_MOST` when it fills the window.
"""
fit!(v::ScheduleView) = begin
  ts = v.tasks
  today = Dates.today()
  lo, hi = isempty(ts) ? (today, today + Day(13)) : (minimum(t -> t.start, ts), maximum(t -> t.finish, ts))
  days = daynum(hi) - daynum(lo) + 3.5
  v.zoom = clamp(max(v.box[3], 1.0) / days, DAY_LEAST, v.full ? DAY_MOST : DAY_USUAL)
  v.at = daynum(lo) - 1
  v
end

"Make each day `by` times as wide. The day at `x` across the window stays there."
zoom_days!(v::ScheduleView, by, x) = begin
  v.zoom > 0 || return handled
  day = x_day(v, x)
  v.zoom = clamp(v.zoom * by, DAY_LEAST, DAY_MOST)
  v.at = day - (x - v.box[1]) / v.zoom
  handled
end

# --- drawing -------------------------------------------------------------------------------

"Write `words` on the canvas, with their left end at `x` and the line that they stand on at `y`"
write_ink(ctx, words, x, y, face::Face) = begin
  paint = ink(face.color)
  blob = Skia.sk_textblob_make_from_string(words, skia_font(face.family, face.size, face.style).raw, Skia.SK_TEXT_ENCODING_UTF8)
  Skia.sk_canvas_draw_text_blob(ctx, blob, Float32(x), Float32(y), paint)
  Skia.sk_textblob_unref(blob)
  Skia.sk_paint_delete(paint)
end

"Draw a box whose corners have the radius `r`. `fill` colours it in, and `line` draws its edge, `wide` px wide."
round_box(ctx, x, y, w, h, r; fill=nothing, line=nothing, wide=1.0) = begin
  shape = Skia.sk_path_new()
  rect = Ref(Skia.sk_rect_t(Float32(x), Float32(y), Float32(x + w), Float32(y + h)))
  Skia.sk_path_add_rounded_rect(shape, rect, Float32(r), Float32(r), Skia.SK_PATH_DIRECTION_CW)
  for paint in ((fill === nothing ? () : (ink(fill),))..., (line === nothing ? () : (ink(line, wide),))...)
    Skia.sk_canvas_draw_path(ctx, shape, paint)
    Skia.sk_paint_delete(paint)
  end
  Skia.sk_path_delete(shape)
end

"Draw a line through the corners `ps`, each corner a little round, with the head of an arrow at its end"
arrow(ctx, ps, colour, wide) = begin
  shape = Skia.sk_path_new()
  Skia.sk_path_move_to(shape, Float32(ps[1][1]), Float32(ps[1][2]))
  for k in 2:length(ps)-1
    before, corner, after = ps[k-1], ps[k], ps[k+1]
    d1, d2 = hypot((corner .- before)...), hypot((after .- corner)...)
    r = min(4.0, d1 / 2, d2 / 2)
    a = corner .+ (before .- corner) .* (r / max(d1, 1e-6))
    b = corner .+ (after .- corner) .* (r / max(d2, 1e-6))
    Skia.sk_path_line_to(shape, Float32(a[1]), Float32(a[2]))
    # A conic with this weight is a quarter of a circle
    Skia.sk_path_conic_to(shape, Float32(corner[1]), Float32(corner[2]), Float32(b[1]), Float32(b[2]), Float32(sqrt(0.5)))
  end
  # The line stops where the head starts
  tip, from = ps[end], ps[end-1]
  along = (tip .- from) ./ max(hypot((tip .- from)...), 1e-6)
  base = tip .- along .* 5.5
  Skia.sk_path_line_to(shape, Float32(base[1]), Float32(base[2]))
  paint = ink(colour, wide)
  Skia.sk_canvas_draw_path(ctx, shape, paint)
  Skia.sk_paint_delete(paint)
  Skia.sk_path_delete(shape)
  across = (-along[2], along[1]) .* 3.4
  trace(ctx, [tip, base .+ across, base .- across], colour, 0.6; fill=colour, closed=true)
end

"Draw the months and the days over the rows, the lines between them, the days when no work is done, and today"
draw_days(ctx, v::ScheduleView) = begin
  left, top, wide, tall = v.box
  z = v.zoom
  rows = top + DATES_H
  small = Face(SANS, "", 11px, colours.dim, false)
  each_day, each_week = z >= 20, 7z >= 46
  for n in floor(Int, v.at):ceil(Int, v.at + wide / z)
    d = numday(n)
    x = day_x(v, n)
    off = !Schedules.works(d, v.data.weekends)
    off && round_box(ctx, x, rows, z, tall - DATES_H, 0; fill=RGBA(colours.ink, 0.05))
    month, monday = Dates.day(d) == 1, Dates.dayofweek(d) == 1
    if month
      trace(ctx, [(x, top + 4), (x, top + tall)], RGBA(colours.ink, 0.16), 1.0)
    elseif each_day || (monday && each_week)
      trace(ctx, [(x, rows), (x, top + tall)], RGBA(colours.ink, monday ? 0.1 : 0.05), 1.0)
    end
    if each_day
      words = string(Dates.day(d))
      face = off ? Face(small, color=colours.faint) : small
      write_ink(ctx, words, x + (z - num(measure(face, words))) / 2, top + 37, face)
    elseif monday && each_week
      write_ink(ctx, "$(Dates.day(d)) $(Dates.monthabbr(d))", x + 5, top + 37, small)
    end
  end
  # Today's name goes over the middle of today, when today is in sight
  now = day_x(v, daynum(Dates.today())) + z / 2
  today = Face(SANS, "Semibold", 10.5px, colours.bg, false)
  pill = num(measure(today, "Today")) + 12
  shows = left <= now <= left + wide
  # Each month's name is at the month's first day, or at the left edge when that day is out of sight.
  # A name that today's name would cover goes after it.
  bold = Face(SANS, "Medium", 12px, colours.ink, false)
  month = Dates.firstdayofmonth(numday(v.at))
  while day_x(v, daynum(month)) < left + wide
    next = month + Dates.Month(1)
    words = "$(Dates.monthname(month)) $(Dates.year(month))"
    long = num(measure(bold, words))
    x = max(left + 8, day_x(v, daynum(month)) + 6)
    shows && x < now + pill / 2 + 6 && x + long > now - pill / 2 - 6 && (x = now + pill / 2 + 8)
    write_ink(ctx, words, min(x, day_x(v, daynum(next)) - long - 8), top + 18, bold)
    month = next
  end
  trace(ctx, [(left, rows), (left + wide, rows)], colours.line, 1.0)
  for i in 1:length(v.tasks)
    y = rows + i * TASK_H
    trace(ctx, [(left, y), (left + wide, y)], RGBA(colours.line, 0.6), 1.0)
  end
  # Today has a line down the rows, under its name
  if shows
    trace(ctx, [(now, rows), (now, top + tall)], RGBA(colours.ink, 0.6), 1.0)
    round_box(ctx, now - pill / 2, top + 6, pill, 16, 4; fill=colours.ink)
    write_ink(ctx, "Today", now - pill / 2 + 6, top + 17.5, today)
  end
end

"The colour of a task's bar: one for a task that's done, and one for a task that isn't"
task_hue(t) = t.todo.done ? colours.string : colours.accent

"Draw the bar of each task. The task under the mouse, and the one that's selected, have the circle that a link is dragged from."
draw_bars(ctx, v::ScheduleView) = begin
  left, _, wide, _ = v.box
  hot = hot_row(v)
  g = v.grab
  for (i, t) in enumerate(v.tasks)
    x, y, w, h = task_bar(v, i)
    (x + w + 2KNOB_GAP < left || x > left + wide) && continue
    hue = task_hue(t)
    on = v.picked == (:task, t.todo.key)
    round_box(ctx, x, y, w, h, 5; fill=RGBA(hue, on ? 0.32 : 0.17), line=RGBA(hue, 0.9), wide=on ? 1.8 : 1.0)
    # A task that's done has a tick, and a bar with room says how many days it is
    inset = 6.0
    if t.todo.done && w >= 18
      trace(ctx, [(x + 5.5, y + h / 2 + 0.5), (x + 8.5, y + h / 2 + 3.5), (x + 13.5, y + h / 2 - 3.5)], hue, 1.6)
      inset = 18.0
    end
    face = Face(SANS, "Medium", 10.5px, hue, false)
    words = "$(t.days)d"
    num(measure(face, words)) + inset + 5 <= w && write_ink(ctx, words, x + inset, y + h / 2 + 3.8, face)
    if (g === nothing && (i == hot || on)) || (g !== nothing && g[1] == :link && g[2] == t.todo.key)
      kx, ky = knob(v, i)
      trace(ctx, [(x + w, ky), (kx - KNOB, ky)], RGBA(hue, 0.7), 1.2)
      for (r, colour) in ((KNOB, hue), (KNOB - 1.5, takeoff_back()))
        paint = ink(colour)
        Skia.sk_canvas_draw_circle(ctx, Float32(kx), Float32(ky), Float32(r), paint)
        Skia.sk_paint_delete(paint)
      end
    end
  end
end

"Draw an arrow from each task to each task that waits for it"
draw_links(ctx, v::ScheduleView) = begin
  for (b, t) in enumerate(v.tasks), a in t.after
    on = v.picked == (:link, v.tasks[a].todo.key, t.todo.key)
    arrow(ctx, link_points(v, a, b), on ? colours.accent : RGBA(colours.dim, 0.9), on ? 2.0 : 1.2)
  end
end

"Draw what a drag is doing: the link that's being made, or the days of the bar that's being moved"
draw_drag(ctx, v::ScheduleView) = begin
  g = v.grab
  (g === nothing || g[1] == :pan) && return
  i = task_place(v, g[2])
  i === nothing && return
  x, y, w, h = task_bar(v, i)
  if g[1] == :link
    win = window_of(v)
    win === nothing && return
    mx, my = num(win.mouse[1]), num(win.mouse[2])
    trace(ctx, [knob(v, i), (mx, my)], colours.accent, 1.5)
    # The task that the link would go to has a line round its bar
    j = row_at(v, my)
    if j !== nothing && j != i
      tx, ty, tw, th = task_bar(v, j)
      round_box(ctx, tx - 2, ty - 2, tw + 4, th + 4, 7; line=colours.accent, wide=1.5)
    end
  else
    tag(ctx, (x + w - 4, y + 2), task_words(v.tasks[i]))
  end
end

describe(a::ChartArea) = Box(width(grow=grow), height(chart_h(a.of)))

draw(ctx, size, ui::ConcreteRect, a::ChartArea) = begin
  v = a.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  v.box[3] > 0 || return
  v.zoom > 0 || fit!(v)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    draw_days(ctx, v)
    draw_links(ctx, v)
    draw_bars(ctx, v)
    draw_drag(ctx, v)
  end
end

cursor(a::ChartArea) = begin
  v = a.of
  g = v.grab
  g === nothing || return g[1] == :size ? :resize_x : g[1] == :pan ? :arrow : :hand
  w = window_of(v)
  w === nothing && return :arrow
  hit = under(v, num(w.mouse[1]), num(w.mouse[2]))
  hit === nothing || hit[1] == :row ? :arrow : hit[1] == :edge ? :resize_x : :hand
end

# --- the mouse and the keys on the bars -----------------------------------------------------

"Put the caret at the end of line `i` of the page, and bring the line in sight"
show_line!(e, i::Int) = begin
  b = e.buf
  1 <= i <= length(b.lines) || return handled
  b.caret = b.anchor = line_end(b, i)
  focus(e)
  touch!(e)
  handled
end

"Note a click at `(x, y)`. True when it's the second of two clicks in one place."
click_twice!(v::ScheduleView, x, y) = begin
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  time() - at < 0.35 && hypot(x - cx, y - cy) < 4
end

onkey(a::ChartArea, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = a.of, ev.window
  focus(a)
  v.said = ""
  v.zoom > 0 || return handled
  x, y = num(w.mouse[1]), num(w.mouse[2])
  twice = click_twice!(v, x, y)
  hit = under(v, x, y)
  if hit === nothing || hit[1] == :row
    # A drag of anything but a bar moves the days
    v.picked = nothing
    v.grab = (:pan, x, v.at)
  elseif hit[1] == :link
    v.picked = (:link, v.tasks[hit[2]].todo.key, v.tasks[hit[3]].todo.key)
  else
    t = v.tasks[hit[2]]
    key = t.todo.key
    v.picked = (:task, key)
    if hit[1] == :knob
      v.grab = (:link, key)
    elseif hit[1] == :edge
      v.grab = (:size, key, false)
    elseif twice
      return show_line!(editor(v), t.todo.line)
    else
      # The bar keeps the place where the mouse took hold of it
      v.grab = (:move, key, x - day_x(v, daynum(t.start)), false)
    end
  end
  handled
end

"A drag ended. A link is made, or the bar that moved is written down."
drop!(v::ScheduleView) = begin
  g = v.grab
  v.grab = nothing
  g === nothing && return v
  if g[1] == :link
    w = window_of(v)
    a = task_place(v, g[2])
    b = w === nothing ? nothing : row_at(v, num(w.mouse[2]))
    (a === nothing || b === nothing) && return v
    did = Schedules.link!(v.data, v.tasks, a, b)
    did == :ok && return commit!(v)
    did == :loop && (v.said = "“$(v.tasks[a].todo.name)” waits for “$(v.tasks[b].todo.name)”, so it can't go before it")
  elseif g[1] in (:move, :size) && g[end]
    commit!(v)
  end
  v
end

onmouse(a::ChartArea, ev::MouseMove) = begin
  v = a.of
  v.zoom > 0 || return nothing
  x, y = num(ev.position[1]), num(ev.position[2])
  g = v.grab
  if g === nothing
    # A bar says its days, and the other parts say what they're for
    hit = under(v, x, y)
    if hit !== nothing && hit[1] in (:bar, :edge)
      show_tooltip!(ev.window, tip_label(task_words(v.tasks[hit[2]])), px.(task_bar(v, hit[2]))..., placement=:top, gap=6px)
    elseif hit !== nothing && hit[1] == :knob
      kx, ky = knob(v, hit[2])
      show_tooltip!(ev.window, tip_label("Drag to the task that waits for this one"), px(kx - KNOB), px(ky - KNOB), px(2KNOB), px(2KNOB), placement=:top, gap=6px)
    elseif hit !== nothing && hit[1] == :link
      words = "“$(v.tasks[hit[3]].todo.name)” waits for “$(v.tasks[hit[2]].todo.name)”.  Click, then Delete takes the link away"
      show_tooltip!(ev.window, tip_label(words), px(x - 4), px(y - 4), 8px, 8px, placement=:top, gap=6px)
    end
    return handled
  end
  Keys.mouse_left in ev.window.keys || (drop!(v); return handled)
  # A press that became a drag isn't the first click of two
  hypot(x - v.clicked[2], y - v.clicked[3]) > 4 && (v.clicked = (0.0, 0.0, 0.0))
  if g[1] == :pan
    v.at = g[3] - (x - g[2]) / v.zoom
    return handled
  end
  i = task_place(v, g[2])
  i === nothing && return handled
  t = v.tasks[i]
  if g[1] == :move
    d = Schedules.workday(numday(round(x_day(v, x - g[3]))), v.data.weekends)
    d == t.start && return handled
    Schedules.move!(v.data, v.tasks, t, d)
    replan!(v)
    v.grab = (:move, g[2], g[3], true)
  elseif g[1] == :size
    # The bar ends at the line between two days that's nearest the mouse
    days = max(1, Schedules.span(t.start, numday(round(x_day(v, x))) - Day(1), v.data.weekends))
    days == t.days && return handled
    Schedules.days!(v.data, t, days)
    replan!(v)
    v.grab = (:size, g[2], true)
  end
  handled   # the drag is the schedule's, so the page's text doesn't select
end

"The place across the window that the days grow or shrink round: the mouse, or the nearest end of the days when the mouse is beside them"
zoom_x(v::ScheduleView, w) = clamp(num(w.mouse[1]), v.box[1], v.box[1] + v.box[3])

# Scrolling sideways moves the days, and scrolling with ⌘ held shows more days or fewer, round the mouse.
# They do that anywhere on the schedule: over the bars, the days, the names of the tasks or the buttons.
# Scrolling up and down scrolls the page that the schedule is on.
onscroll(v::ScheduleView, ev::MouseScroll) = begin
  w = ev.window
  v.zoom > 0 || return nothing
  dx, dy = num(ev.delta[1]), num(ev.delta[2])
  Keys.cmd in w.keys && return zoom_days!(v, exp(dy / 10), zoom_x(v, w))
  abs(dx) > abs(dy) || return nothing
  v.at -= 30dx / v.zoom
  handled
end
onscroll(a::ChartArea, ev::MouseScroll) = onscroll(a.of, ev)

onpinch(v::ScheduleView, ev::Pinch) = zoom_days!(v, ev.scale, zoom_x(v, ev.window))
onpinch(a::ChartArea, ev::Pinch) = onpinch(a.of, ev)

# Esc takes the selection away, then puts a schedule that fills the window back in the page, then gives the keyboard back to the text
onkey(a::ChartArea, ::KeyPress{Keys.escape}) = begin
  v = a.of
  v.picked === nothing || return (v.picked = nothing; handled)
  v.full ? full!(v, false) : nothing
end
onkey(a::ChartArea, ::KeyPress{K}) where K = begin
  v = a.of
  if K in (Keys.backspace, Keys.delete)
    # Delete takes away the link that's selected
    p = v.picked
    (p !== nothing && p[1] == :link) || return handled
    from, to = task_place(v, p[2]), task_place(v, p[3])
    v.picked = nothing
    (from === nothing || to === nothing) && return handled
    Schedules.unlink!(v.data, v.tasks, from, to)
    commit!(v)
    return handled
  elseif (command = command_of(editor(v), window_of(a), K)) in (:undo, :redo)
    b = editor(v).buf
    command == :redo ? redo!(b) : undo!(b)
    return handled
  end
  nothing
end

# --- the names, the buttons and the whole block -----------------------------------------------

"How wide the names of the tasks are, beside the bars"
names_w(v::ScheduleView) = v.full ? min(NAMES_FULL, window_size(editor(v))[1] * 0.3) : min(NAMES_W, editor(v).width * 0.36)

describe(n::TaskName) = begin
  v = n.of
  i = task_place(v, n.key)
  i === nothing && return Box(width(grow=grow), height(px(TASK_H)))
  t = v.tasks[i]
  on = v.picked == (:task, n.key)
  # A task under another, further in, is further in here too
  indent = 12px + 14px * min(t.todo.level ÷ 2, 4)
  room = names_w(v) - indent - 12px - (t.todo.done ? 20px : 0px)
  Row(width(grow=grow), height(px(TASK_H)), padding(0px, 12px, 0px, indent), child_gap=6px, Alignment.Center, clip=true,
      background(on ? colours.active : hot_row(v) == i ? colours.hover : clear),
    (t.todo.done ? (Icon("check", size=14px, color=colours.string),) : ())...,
    Box(label(elide(t.todo.name, 13px, room), 13px, color=t.todo.done ? colours.dim : colours.ink)))
end

cursor(::TaskName) = :hand

onkey(n::TaskName, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = n.of, ev.window
  focus(chart(v))
  twice = click_twice!(v, num(w.mouse[1]), num(w.mouse[2]))
  v.picked = (:task, n.key)
  i = task_place(v, n.key)
  twice && i !== nothing ? show_line!(editor(v), v.tasks[i].todo.line) : handled
end

toolbar(v::ScheduleView) = begin
  s = v.data
  start = v.asking ?
    (Box(width(6px)), label("Starts on", 12px), Box(width(6px)), field(v, fixed(120px)), Box(width(8px)),
     label("like 16 Nov, then Return", 12px, color=colours.dim)) :
    (button!(v, :start, :start, icon="calendar-event", words="Starts " * Schedules.long(Schedules.origin(s)),
             tip="Change the day that the work starts"),)
  Row(width(grow=grow), height(38px), padding(6px, 0px), child_gap=2px, Alignment.Center, background(colours.block),
    start..., rule(),
    button!(v, :weekends, :weekends, words=s.weekends ? "Every day" : "Weekdays",
            tip=s.weekends ? "Work is done every day. Click to leave out Saturday and Sunday." :
                             "Work is done from Monday to Friday. Click to count Saturday and Sunday too."),
    Row(width(grow=grow), padding(8px, 0px), clip=true, justify=Alignment.End, Box(label(v.said, 12px, color=colours.accent))),
    button!(v, :smaller, (:zoom, 1 / 1.4), icon="zoom-out", tip="Show more days"),
    button!(v, :bigger, (:zoom, 1.4), icon="zoom-in", tip="Show fewer days  pinch, or ⌘ and scroll"),
    button!(v, :fit, :fit, icon="aspect-ratio", tip="Show every task"),
    button!(v, :full, :full, icon=v.full ? "fullscreen-exit" : "arrows-fullscreen", tip=v.full ? "Back to the page  esc" : "Fill the window"))
end

"Do what a button of a schedule does"
act!(v::ScheduleView, action, w) = begin
  a = action isa Tuple ? action[1] : action
  v.said = ""
  if a == :start
    i = schedule_input(v)
    i.color = colours.ink
    i.text = Schedules.long(Schedules.origin(v.data))
    i.anchor, i.cursor = 0, length(i.text)
    v.asking = true
    focus(i)
  elseif a == :weekends
    v.data.weekends = !v.data.weekends
    commit!(v)
  elseif a == :zoom
    zoom_days!(v, action[2], v.box[1] + v.box[3] / 2)
  elseif a == :fit
    fit!(v)
  elseif a == :full
    full!(v, !v.full)
  end
  handled
end

"Take the day that was typed as the day that the work starts, and show every task again"
answer!(v::ScheduleView) = begin
  v.asking || return handled
  d = Schedules.date(schedule_input(v).text)
  d === nothing && return (v.said = "Ladder can't read that day. Type it like 16 Nov 2026."; handled)
  v.data.start = d
  stop_asking!(v)
  commit!(v)
  v.zoom = 0.0
  handled
end

"Take the text field away. The keyboard goes back to the bars."
stop_asking!(v::ScheduleView) = begin
  v.asking = false
  w = window_of(v)
  w !== nothing && w.focus === schedule_input(v) && focus(chart(v))
  handled
end

onkey(v::ScheduleView, ::KeyPress{Keys.enter}) = v.asking ? answer!(v) : nothing
onkey(v::ScheduleView, ::KeyPress{Keys.escape}) = v.asking ? stop_asking!(v) : nothing

"What happens to a schedule in each frame, before the page is laid out: a drag that ended is written down, and the text field that lost the keyboard closes"
tick!(v::ScheduleView) = begin
  w = window_of(v)
  v.grab !== nothing && !held(v, Keys.mouse_left) && drop!(v)
  # A click somewhere else took the keyboard from the text field. A day that reads is kept.
  if v.asking && w !== nothing && w.focus !== schedule_input(v)
    Schedules.date(schedule_input(v).text) === nothing ? stop_asking!(v) : answer!(v)
  end
  v
end

"Do what each schedule of the page that shows needs in this frame"
schedule_tick!(e) = for (key, node) in collect(e.nodes)
  (node isa ScheduleView && key[2] == e.buf.path) || continue
  tick!(node)
  node.full || continue
  # A schedule whose block has gone goes back to the page. Under one that fills the window, the page stays where it was.
  block_lines(e.buf, SCHEDULE, node.n) === nothing ? (node.full = false) : (e.scroll.offset = node.pinned)
end

describe(v::ScheduleView) = begin
  e = editor(v)
  schedule_input(v).color = colours.ink
  ts = tasks!(v)
  # The names of tasks that the page had once are forgotten
  length(v.parts) > 2length(ts) + 40 && filter!(p -> !(p[1] isa Tuple && p[1][1] == :name) || task_place(v, p[1][2]) !== nothing, v.parts)
  with_theme(component_theme(e.zoom)) do
    # In the page it's a box with round corners. In the window it takes all the room under the top bar.
    look = v.full ? (width(grow=grow), height(grow=grow), Alignment.Start, background(takeoff_back())) :
                    (width(grow=grow), Alignment.Start, radius(8px), border(1px, :solid, colours.line), background(takeoff_back()))
    isempty(ts) && return Column(look..., clip=true, name="Schedule", toolbar(v),
      Row(width(grow=grow), height(64px), padding(16px, 0px), Alignment.Center, clip=true,
          Box(label("This page has no to-do items yet. Start a line with - [ ] to make a task.", 13px, color=colours.dim))))
    names = Column(fixed(names_w(v)), height(chart_h(v)), Alignment.Start, border(1px, :solid, colours.line)[:right],
      Row(width(grow=grow), height(px(DATES_H)), padding(12px, 0px, 9px, 12px), Alignment.End, border(1px, :solid, colours.line)[:bottom],
          Box(label("Task", 11px, color=colours.dim))),
      [part!(() -> TaskName(of=v, key=t.todo.key), v, (:name, t.todo.key)) for t in ts]...)
    rows = Row(width(grow=grow), Alignment.Start, names, chart(v))
    v.full || return Column(look..., clip=true, name="Schedule", toolbar(v), rows)
    # The wheel scrolls through more tasks than the window has room for
    list = get!(() -> Scroll(width(grow=grow), height(grow=grow)), v.parts, :list)
    Column(look..., name="Schedule", toolbar(v), reuse!(list, rows))
  end
end

cursor(::ScheduleView) = :arrow
# A click beside a button is the block's, and takes the keyboard from the text field
onkey(v::ScheduleView, ::KeyPress{Keys.mouse_left}) = (focus(chart(v)); handled)
onmouse(v::ScheduleView, ::MouseMove) = held(v, Keys.mouse_left) ? handled : nothing

# --- a to-do item of a page that has a schedule ------------------------------------------------
#
# A to-do item reads as it always does: a box and its text. While the page has
# a schedule, the item is a task, and the mouse over it shows the task's days
# at the right end of its line: its first and last day, how many working days
# it takes, with a button each side that makes it a day shorter or longer, and
# what it waits for. An item whose lines have no room for them shows them under
# the item.

"The schedule that the page's to-do items are in: the page's first, or nothing when it has none"
page_schedule(e) = begin
  b = e.buf
  readonly(b) && return nothing
  span = block_lines(b, SCHEDULE, 1)
  span === nothing && return nothing
  v = schedule_view(e, 1)
  reread!(v, b.lines[span[1]+1:span[2]-1])
  v
end

"The line of the to-do item whose row of the page is at the place `(x, y)` in the window, or nothing. An item that shows its markup isn't one."
todo_line(e, x, y) = begin
  dx, dy = px(x) - e.origin[1], px(y) - e.origin[2]
  (-30px <= dx < e.width && y >= num(TOPBAR_H)) || return nothing
  dy >= 0px || return nothing
  it = e.layout[item_under(e, dx, dy)]
  f = it.content
  dy < it.top + it.tall && f isa Flow && f.kind == Kind.todo && !f.raw ? it.first : nothing
end

"""
The days of the to-do item under the mouse, beside the item. They stay while
the mouse is on them, so that their buttons can be clicked.
"""
task_over(e) = begin
  (zooming(e) === nothing && full_block(e) === nothing && e.popup == :none) || return ()
  win = window_of(e)
  (win === nothing || isempty(e.layout) || readonly(e.buf)) && return ()
  d = node!(TaskDetails, e, :task_details)
  x, y = num(win.mouse[1]), num(win.mouse[2])
  on_details = d.of !== nothing && d.box[1] <= x < d.box[1] + d.box[3] && d.box[2] <= y < d.box[2] + d.box[4]
  hide() = (d.of = nothing; ())
  line = on_details ? nothing : ishovered(node!(Document, e, :document)) && !held(e, Keys.mouse_left) ? todo_line(e, x, y) : nothing
  (on_details || line !== nothing) || return hide()
  v = page_schedule(e)
  v === nothing && return hide()
  ts = tasks!(v)
  i = on_details ? task_place(v, d.key) : findfirst(t -> t.todo.line == line, ts)
  i === nothing && return hide()
  it = item(e, ts[i].todo.line)
  f = it.content
  (f isa Flow && f.kind == Kind.todo && !f.raw) || return hide()
  d.of, d.key = v, ts[i].todo.key
  wide = describe(Row(Alignment.Start, geometry(d)), (9999px, 9999px)).width
  # They go at the right end of the first of the item's lines that has room for them, or under the item when none has
  edge = sum(item_room(e, it))   # the right edge of the item's column, or of the page
  k = findfirst(vl -> maximum(seg -> seg.x + seg.w, vl.segs, init=0px) + 24px + wide <= edge, f.lines)
  d.floats = k === nothing
  vl = f.lines[something(k, length(f.lines))]
  left = e.origin[1] + edge - wide
  top = e.origin[2] + it.top + f.above + vl.top
  top = d.floats ? top + vl.high - 2px : top + (vl.high - DETAILS_H) / 2
  top >= TOPBAR_H || return hide()
  d.box = (num(left), num(top), num(wide), num(DETAILS_H))
  (Row(width(grow=grow), height(grow=grow), Alignment.Start, padding(top, 0px, 0px, left), d),)
end

describe(d::TaskDetails) = begin
  v = d.of
  i = v === nothing ? nothing : task_place(v, d.key)
  i === nothing && return Box(width(0px), height(DETAILS_H))
  t = v.tasks[i]
  d.less === nothing && (d.less = own!(d, DayButton(by=-1)); d.more = own!(d, DayButton(by=1)))
  first_name = isempty(t.after) ? "" : v.tasks[t.after[1]].todo.name
  waits = isempty(t.after) ? "" : length(t.after) > 1 ? "after $(length(t.after)) tasks" :
          "after " * (length(first_name) > 30 ? first(first_name, 29) * "…" : first_name)
  dot() = Box(label("·", 12px, color=colours.faint))
  # Under the line, they float over the text of the next line
  look = d.floats ? (background(colours.float), border(1px, :solid, colours.line), lifted) : (background(colours.bg),)
  Row(height(DETAILS_H), padding(8px, 0px), child_gap=6px, Alignment.Center, radius(6px), look..., name="Task",
    Icon("calendar-event", size=12px, color=colours.dim), Box(label(task_days(t), 12px, color=colours.dim)), dot(),
    d.less, Box(label(Schedules.days_text(t.days), 12px)), d.more,
    (isempty(waits) ? () : (dot(), Box(label(waits, 12px, color=colours.dim))))...)
end

cursor(::TaskDetails) = :arrow
# A click beside a button does nothing, and doesn't move the caret
onkey(::TaskDetails, ::KeyPress{Keys.mouse_left}) = handled
onmouse(::TaskDetails, ::MouseMove) = handled

"The task that the details `d` show, or nothing when the page has it no more"
task_of(d::TaskDetails) = (i = d.of === nothing ? nothing : task_place(d.of, d.key); i === nothing ? nothing : d.of.tasks[i])

describe(b::DayButton) = begin
  t = task_of(b.parent)
  off = b.by < 0 && (t === nothing || t.days <= 1)
  Box(width(18px), height(18px), radius(4px), Alignment.Center, justify=Alignment.Center, name="Button",
      background(ishovered(b) && !off ? colours.hover : clear),
    Icon(b.by < 0 ? "dash" : "plus", size=13px, color=off ? colours.faint : colours.dim))
end

cursor(::DayButton) = :hand
draw(ctx, size, ui::ConcreteRect, b::DayButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::DayButton, ev::MouseMove) = begin
  show_tooltip!(ev.window, tip_label(b.by < 0 ? "A day shorter" : "A day longer"), b.rect..., placement=:top, gap=6px)
  handled
end

onkey(b::DayButton, ev::KeyPress{Keys.mouse_left}) = begin
  d = b.parent
  t = task_of(d)
  hide_tooltip!(ev.window)
  (t === nothing || t.days + b.by < 1) && return handled
  Schedules.days!(d.of.data, t, t.days + b.by)
  commit!(d.of)
  handled
end

# --- a picture, a diagram or a page that fills the window ---------------------------------
#
# While the mouse is over a picture, a diagram, a page of a PDF file, a model or
# a video, a button shows beside its top right corner, so it covers none of it.
# The button makes it fill the window, over the page and under the top bar.
# Esc, or the button with a cross, puts the page back where it was.
#
#   - A picture, a diagram and a page of a PDF file fit the window at first.
#     Pinch, or scroll with ⌘ held, to make one bigger or smaller round the
#     mouse. ⌘+, ⌘- and the buttons under it do the same, and ⌘0 fits it to
#     the window again. Drag it, or scroll, to move it.
#   - A pinch outwards on a picture, a diagram or a page in the page makes it
#     fill the window too.
#   - ← and → go to the page before and the next page of a PDF file. The page
#     that shows in the document goes on from the page you looked at.
#   - A model and a video only fill the window. A model turns and zooms there
#     as it does in the page, and a video plays on.
#   - A diagram of a `mermaid` block can be changed while it fills the window.
#     A click selects a box, a line or another part of it, and two clicks let
#     you type its words where they are. A drag moves the diagram, as before.
#     The first buttons under it are the tools for the part that's selected,
#     or for the whole diagram: add a box, draw a line to the box that's
#     clicked next, change a shape, take the part away. ⌫ takes it away too.
#     Each change is written in the lines of the block, and ⌘Z takes it back.
#     With a part selected, Esc selects nothing, and the next Esc puts the
#     page back.
#
# A diagram is drawn again at each size, so it's sharp however big it is, and so
# is a page of a PDF file once it stops moving. A picture is as sharp as its pixels.

const ZOOM_EDGE = 24.0   # px of room round a picture that fits the window
const BAR_ROOM = 64px    # the bottom of the window, where the bar of buttons is
const MOST_ZOOM = 8.0    # the biggest a picture gets: this many times its own size, or the size that fits the window if that's bigger
const ZOOM_STEP = 1.25   # how much bigger the + button, and ⌘+, make a picture
"The commands that do what they always do while a picture fills the window. The rest would change the page under it."
const PAGE_COMMANDS = (:save, :open, :print, :close, :settings, :sidebar, :sidebar_keys)

"What fills the window, over the page"
@def mutable struct ZoomView <: SemanticUI
  what::Any = nothing                       # (:picture, key), (:diagram, code), (:pdf, path, page) or (:node, node). Nothing while the page shows.
  path::String = ""                         # the document it was opened from. It closes when another document shows.
  from::Any = nothing                       # the node of the page that it was opened from
  page::Int = 1                             # of a PDF file
  pages::Int = 1
  zoom::Float64 = 0.0                       # px of the window to a px of the picture at its own size. 0 fits it to the window.
  at::Tuple{Float64,Float64} = (0.0, 0.0)   # the point of the picture at the view's top left
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the view is in the window: its left, top, width and height
  fits::Bool = true                         # it shows the whole picture, so it fits the window again when the window changes size
  grab::Any = nothing                       # where a drag started, and the point of the picture that was at the view's top left then
  moved::Float64 = 0.0                      # when the view last moved
  sharp::Sharp = Sharp(nothing, C_NULL, 1.0)
  drawn::Any = nothing                      # a diagram laid out at its own size, with what it was laid out for
  home::Any = nothing                       # how tall a model or a video was in the page
  held::px = 0px                            # the room that a model or a video took in the page, which the page keeps for it
  pinned::px = 0px                          # how far the page was scrolled
  block::Int = 0                            # which `mermaid` block of the page its diagram is, so that it can be changed. 0 for a diagram that can't.
  tool::Any = nothing                       # the tool of its diagram that waits for a click, whose button is lit
  parts::Dict{Any,Any} = Dict{Any,Any}()    # its buttons and its area, kept between frames
end

"The part of a ZoomView that shows the picture. It takes the mouse and the keys."
@def mutable struct ZoomArea <: SemanticUI
  of::Any = nothing
end

"""
A picture, a diagram, a page, a model or a video in the page that can fill the
window. It's a node of its own so that the window knows where it is, to put
its button beside it.
"""
@def mutable struct Fillable <: SemanticUI
  what::Any = nothing      # what fills the window. See ZoomView.
  content::Any = nothing   # what shows in the page
  sizing::Any = ()         # how wide it is
  button::Any = nothing       # its FillButton, once it has shown
  transcript::Any = nothing   # a video's TranscriptButton, once it has shown
end

"The button beside the top right corner of a Fillable that makes it fill the window"
@def mutable struct FillButton <: SemanticUI
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
  quiet::Bool = false                         # clicked, so no tooltip until the mouse leaves it
end

const FILL_SIDE = 24px   # how wide and how tall the button is that makes a picture fill the window
const FILL_GAP = 4px     # between that button and the picture, and between it and the window's edge

"A part of `v` that's kept between frames"
part!(make, v::ZoomView, key) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, v)
  node
end

"The ZoomView of `e` while it fills the window, or nothing"
zooming(e) = (v = get(e.nodes, :zoom, nothing); v === nothing || v.what === nothing ? nothing : v)

"True when `a` and `b` say the same thing fills the window. A node is the same node, not one like it."
same_what(a, b) = a !== nothing && b !== nothing && a[1] == b[1] && (a[1] == :node ? a[2] === b[2] : a == b)

"True when `node`, a model or a video, fills the window now"
zoomed_node(e, node) = (v = zooming(e); v !== nothing && v.what[1] == :node && v.what[2] === node)

"The empty room that the page keeps for the model or the video that fills the window"
held_room(e) = Box(width(grow=grow), height(zooming(e).held))

"What fills the window when you click the button over `x`, a node that a live block made, or nothing if it has no button"
fill_what(x) = x isa Mermaid ? (isdiagram(x.code) ? (:diagram, x.code) : nothing) : x isa Union{STLViewer,VideoPlayer} ? (:node, x) : nothing

"How wide `x` is at most in the page, for the button over its top right corner: a width, or :grow when it's as wide as the page"
fill_wide(x) = x isa VideoPlayer ? video_wide(x) : x isa Mermaid && x.made !== nothing && hasproperty(x.made[2], :w) ? px(x.made[2].w) : :grow

"How wide the picture of a video is at most: as wide as a picture of its height is, as VideoPlayer works it out"
video_wide(p::VideoPlayer) = begin
  s = p.media === nothing ? (0.0, 0.0) : picture_size(p.media)
  s[1] > 0 && s[2] > 0 ? max(240px, p.height * s[1] / s[2]) : :grow
end

"The Fillable of each node of the page that shows one, by the node"
fills(e) = get!(Dict{UInt,Fillable}, e.nodes, :fills)

"""
`content`, which `owner` shows, as a Fillable: while the mouse is over it, a
button beside it makes `what` fill the window. `wide` is how wide the content
is at most: a width, :grow for content that's as wide as the room it's given,
or nothing for content of a fixed size. A model or a video that fills the
window now leaves its room empty.
"""
fillable(owner, what, content; wide=nothing) = begin
  e = editor(owner)
  what[1] == :node && zoomed_node(e, what[2]) && return held_room(e)
  f = get!(() -> own!(owner, Fillable()), fills(e), objectid(owner))
  f.what, f.content = what, content
  f.sizing = wide === nothing ? () : wide === :grow ? (width(grow=grow),) : (width(grow=grow, max=wide),)
  f
end

describe(f::Fillable) = Box(f.sizing..., Alignment.Start, f.content isa GeometricUI ? detach!(f.content) : f.content)

"""
Where the button of a picture that's at `r` in the window goes: beside its top
right corner, so it covers none of the picture. Where the window has no room
there, it's beside the top left corner, and where there's room on neither
side, it's in the top right corner. It stays under the top bar.
"""
fill_spot(e, r) = begin
  w, _ = window_size(e)
  top = min(max(r.top, TOPBAR_H + FILL_GAP), r.top + r.height - FILL_SIDE)
  right = r.left + r.width + FILL_GAP
  right + FILL_SIDE <= w - FILL_GAP && return (right, top)
  left = r.left - FILL_GAP - FILL_SIDE
  left >= panel_w(e) * opened(e) + FILL_GAP && return (left, top)
  (right - 2FILL_GAP - FILL_SIDE, top + FILL_GAP)
end

"The video player that `f` shows, or nothing when it shows something else"
video_of(f::Fillable) = f.what !== nothing && f.what[1] == :node && f.what[2] isa VideoPlayer ? f.what[2] : nothing

"How tall the buttons beside `f` are: a video has the button that shows what was said in it under the first"
buttons_tall(f::Fillable) = video_of(f) === nothing ? FILL_SIDE : 2FILL_SIDE + FILL_GAP

"""
The button that makes the picture under the mouse fill the window, beside it.
A video has a button under that one, which shows what was said in the video.
They show while the mouse is over the picture or the buttons, or between them,
and while the drop-down of what was said is open.
"""
fill_over(e) = begin
  (zooming(e) === nothing && full_block(e) === nothing && e.popup == :none) || return ()
  win = window_of(e)
  win === nothing && return ()
  x, y = num(win.mouse[1]), num(win.mouse[2])
  # A picture under a path is in a live block that can fill the window too, so the smallest one under the mouse has the button
  best, spot, least = nothing, nothing, Inf
  for f in values(fills(e))
    r = rect(f)
    r === nothing && continue
    s = fill_spot(e, r)
    if f.transcript !== nothing && f.transcript.open
      best, spot = f, s
      break
    end
    num(min(r.left, s[1])) <= x < num(max(r.left + r.width, s[1] + FILL_SIDE)) || continue
    num(min(r.top, s[2])) <= y < num(max(r.top + r.height, s[2] + buttons_tall(f))) || continue
    area = num(r.width) * num(r.height)
    area < least && ((best, spot, least) = (f, s, area))
  end
  best === nothing && return ()
  b = best.button === nothing ? (best.button = own!(best, FillButton())) : best.button
  buttons = Any[b]
  if video_of(best) !== nothing
    best.transcript === nothing && (best.transcript = own!(best, TranscriptButton()))
    push!(buttons, best.transcript)
  end
  (Row(width(grow=grow), height(grow=grow), Alignment.Start, padding(spot[2], 0px, 0px, spot[1]),
     Column(Alignment.Start, child_gap=FILL_GAP, buttons...)),)
end

describe(b::FillButton) = begin
  ishovered(b) || (b.quiet = false)
  Box(width(FILL_SIDE), height(FILL_SIDE), radius(6px), Alignment.Center, justify=Alignment.Center, name="Button",
      background(ishovered(b) ? colours.hover : colours.float), border(1px, :solid, colours.line),
    Icon("arrows-fullscreen", size=12px, color=colours.dim))
end

cursor(::FillButton) = :hand
draw(ctx, size, ui::ConcreteRect, b::FillButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::FillButton, ev::MouseMove) = begin
  b.quiet && return handled
  tip = b.parent.what[1] == :node ? "Fill the window" : "Fill the window  pinch"
  # A video's tooltip goes beside the button, so that it doesn't cover the button under it
  show_tooltip!(ev.window, tip_label(tip), b.rect...,
                placement=video_of(b.parent) === nothing ? :bottom : :right, gap=6px)
  handled
end

onkey(b::FillButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  f = b.parent
  fill_window!(editor(b), f.what, f.parent)
end

"""
Make `what`, which a Fillable of the node `from` shows, fill the window. A
block like a sketch, `(:block, view)`, fills it by itself. The rest fill the
ZoomView.
"""
fill_window!(e, what, from) = what[1] == :block ? full!(what[2], true) : zoom_in!(e, what, from)

"A pinch outwards on a picture, a diagram, a page or a sketch in the page makes it fill the window"
pinch_open(owner, ev::Pinch) = begin
  ev.scale > 1 || return nothing
  e = editor(owner)
  f = get(fills(e), objectid(owner), nothing)
  (f === nothing || f.what === nothing || f.what[1] == :node) && return nothing
  # Only when the fingers are on the picture, not beside it
  r = rect(f)
  x, y = num(ev.window.mouse[1]), num(ev.window.mouse[2])
  (r !== nothing && num(r.left) <= x < num(r.left + r.width) && num(r.top) <= y < num(r.top + r.height)) || return nothing
  fill_window!(e, f.what, owner)
end

onpinch(s::Shown, ev::Pinch) = pinch_open(s, ev)
onpinch(p::Pages, ev::Pinch) = pinch_open(p, ev)
onpinch(v::FileView, ev::Pinch) = pinch_open(v, ev)
onpinch(l::Breadcrumb, ev::Pinch) = pinch_open(l, ev)

"Make `what` fill the window. `from` is the node of the page that shows it."
zoom_in!(e, what, from=nothing) = begin
  v = node!(ZoomView, e, :zoom)
  # A pinch goes on to the page until the next frame is drawn, so it would open it again
  same_what(v.what, what) && return handled
  zoom_out!(v, false)
  v.what, v.path, v.from, v.pinned = what, e.buf.path, from, e.scroll.offset
  v.zoom, v.fits, v.grab, v.drawn = 0.0, true, nothing, nothing
  v.block, v.tool = 0, nothing
  delete!(v.parts, :diagram)
  if what[1] == :diagram
    # The diagram of a `mermaid` block can be changed here. One that the code of a live block made has no lines of its own.
    from !== nothing && get(e.nodes, (:diagram, what[2]), nothing) === from && !readonly(e.buf) && (v.block = diagram_block(e.buf, what[2]))
  elseif what[1] == :pdf
    v.page, v.pages = what[3], max(1, pdf_pages(what[2]))
  elseif what[1] == :node
    r = rect(what[2])
    v.home = what[2].height
    v.held = r === nothing ? what[2].height : r.height
  end
  focus(part!(() -> ZoomArea(of=v), v, :area))
  handled
end

"Put the page back, with a model or a video back in it. `refocus` gives the keyboard back to the text."
zoom_out!(v::ZoomView, refocus=true) = begin
  what = v.what
  what === nothing && return handled
  # Words that were being typed into a diagram are taken
  m = changing(v)
  m === nothing || Diagrams.settle!(m)
  v.what = nothing
  what[1] == :node && v.home !== nothing && (what[2].height = v.home)
  v.from isa Pages && (v.from.page = v.page)   # the page in the document goes on from the page you looked at
  v.from = nothing
  e = editor(v)
  e.scroll.offset = v.pinned
  refocus && focus(e)
  handled
end

"In each frame: the page comes back when another document shows, and until then it stays where it was"
zoom_tick!(e) = begin
  v = zooming(e)
  v === nothing && return
  v.path == e.buf.path || return zoom_out!(v, false)
  e.scroll.offset = v.pinned
  # The mouse button that started a drag has come up
  w = window_of(e)
  v.grab === nothing || w === nothing || Keys.mouse_left in w.keys || let_go!(v, w)
  m = changing(v)
  if m !== nothing && w !== nothing
    m.joining === nothing || Keys.mouse_left in w.keys || Diagrams.let_go_at!(m, picture_spot(v, w.mouse)...)
    # A box shows its point only while the mouse is over the diagram, and not over the buttons under it
    m.hovered === nothing || ishovered(part!(() -> ZoomArea(of=v), v, :area)) || Diagrams.unhover!(m)
  end
  v.what === nothing && return
  if v.what[1] == :diagram && v.block > 0
    # The diagram is what the lines of its block say now. They change under it when ⌘Z takes a change back.
    code = diagram_code(e.buf, v.block)
    (code === nothing || !isdiagram(code)) && return zoom_out!(v, false)
    code == v.what[2] || (v.what = (:diagram, code); refit!(v))
  end
  nothing
end

"The code of the `n`th `mermaid` block of `b`, or nothing when it has no such block"
diagram_code(b::Buffer, n::Int) = begin
  span = block_lines(b, DIAGRAM, n)
  span === nothing ? nothing : join(b.lines[span[1]+1:span[2]-1], "\n")
end

"Which `mermaid` block of `b` has the code `code`: the first one that does, or 0"
diagram_block(b::Buffer, code) = begin
  n = 1
  while (found = diagram_code(b, n)) !== nothing
    found == code && return n
    n += 1
  end
  0
end

"The diagram of `v` as the component that changes it, or nothing when `v` shows something else or a diagram that can't be changed"
changing(v::ZoomView) = begin
  (v.what !== nothing && v.what[1] == :diagram && v.block > 0) || return nothing
  m = get(v.parts, :diagram, nothing)
  m !== nothing && m.editing ? m : nothing
end

"A diagram that fitted the window fits it again after a change, which gives it another size"
refit!(v::ZoomView) = (v.fits && (v.zoom = 0.0); v)

"""
Write the code of the diagram that fills the window as the lines of its block.
The caret stays where it was in the text, and ⌘Z takes the change back.
"""
write_diagram!(v::ZoomView, code::String) = begin
  e = editor(v)
  b = e.buf
  span = block_lines(b, DIAGRAM, v.block)
  (span === nothing || readonly(b)) && return v
  i, t = span
  new, old = String.(split(code, '\n')), b.lines[i+1:t-1]
  if new != old
    caret, anchor = b.caret, b.anchor
    edit!(b, line_end(b, i), line_end(b, t - 1), "\n" * join(new, "\n"))
    by = length(new) - length(old)
    moved(p) = p[1] >= t ? (p[1] + by, p[2]) : p[1] > i ? (i, 0) : p
    b.caret, b.anchor = moved(caret), moved(anchor)
  end
  v.what = (:diagram, code)
  refit!(v)
end

"What fills the window, over the page and the sidebar and under the top bar"
zoom_over(e) = zooming(e) === nothing ? () :
  (Box(width(grow=grow), height(grow=grow), padding(TOPBAR_H, 0px, 0px, 0px), background(colours.bg), geometry(e.nodes[:zoom])),)

"The button of `v` that's kept under `key`, with what it does and shows now"
button!(v::ZoomView, key, action; icon="", tip="", off=false) = begin
  b = part!(() -> PlanButton(of=v), v, (:button, key))
  b.action, b.icon, b.tip, b.off = action, icon, tip, off
  b
end

"Do what a button of a ZoomView does"
act!(v::ZoomView, action, w) = begin
  a = action isa Tuple ? action[1] : action
  a == :tool && return use_tool!(v, action[2], w)
  a == :zoom && return zoom_by!(v, action[2], view_middle(v)...)
  a == :fit && return fit_now!(v)
  a == :page && return turn!(v, action[2])
  a == :close && return zoom_out!(v)
  handled
end

describe(v::ZoomView) = begin
  e = editor(v)
  what = v.what
  bar(buttons...) = Column(width(grow=grow), height(grow=grow), Alignment.Center, justify=Alignment.End, padding(0px, 0px, 16px, 0px),
    Row(height(36px), padding(4px), child_gap=2px, radius(8px), Alignment.Center, background(colours.float),
        border(1px, :solid, colours.line), lifted, buttons...))
  close = button!(v, :close, :close, icon="x-lg", tip="Back to the page  esc")
  if what[1] == :node
    # A model or a video is as tall as the window has room for. Its own bar is under its picture.
    node = what[2]
    _, h = window_size(e)
    node.height = max(160px, h - TOPBAR_H - BAR_ROOM - px(2ZOOM_EDGE) - 44px)
    shows = with_theme(() -> geometry(node), component_theme(e.zoom))
    return Stack(width(grow=grow), height(grow=grow), Alignment.Start,
      Column(width(grow=grow), height(grow=grow), Alignment.Center, padding(px(ZOOM_EDGE)), shows),
      bar(close))
  end
  what[1] == :diagram && lay_diagram!(v)
  # The view is the whole window under the top bar, so it's fitted here, and the bar says how big the picture is in this frame
  w, h = window_size(e)
  reframe!(v, (0.0, num(TOPBAR_H), num(w), num(h) - num(TOPBAR_H)))
  buttons = Any[diagram_buttons(v)..., button!(v, :smaller, (:zoom, 1 / ZOOM_STEP), icon="zoom-out", tip="Smaller  pinch, or ⌘ and scroll"),
                Box(width(46px), Alignment.Center, justify=Alignment.Center,
                    label(v.zoom > 0 ? "$(round(Int, 100v.zoom))%" : "", 12px, color=colours.dim)),
                button!(v, :bigger, (:zoom, ZOOM_STEP), icon="zoom-in", tip="Bigger  pinch, or ⌘ and scroll"),
                button!(v, :fit, :fit, icon="aspect-ratio", tip="Fit the window  ⌘0")]
  prepend!(buttons, gallery_buttons(v))   # a picture of a gallery says where it is in the gallery, with a button to each side
  if what[1] == :pdf && v.pages > 1
    push!(buttons, button!(v, :back, (:page, -1), icon="chevron-left", tip="The page before  ←", off=v.page <= 1),
          Box(Alignment.Center, padding(4px, 0px), label("Page $(v.page) of $(v.pages)", 12px, color=colours.dim)),
          button!(v, :on, (:page, 1), icon="chevron-right", tip="The next page  →", off=v.page >= v.pages))
  end
  push!(buttons, close)
  Stack(width(grow=grow), height(grow=grow), Alignment.Start, part!(() -> ZoomArea(of=v), v, :area), gallery_edges(v)..., bar(buttons...))
end

describe(::ZoomArea) = Box(width(grow=grow), height(grow=grow))
# While a tool of the diagram waits for a click on a part, the mouse is a cross
# While a tool of the diagram waits for a click on a part, or a line is dragged from a box's point, the mouse is a cross
cursor(a::ZoomArea) = begin
  m = changing(a.of)
  a.of.tool !== nothing || (m !== nothing && (m.joining !== nothing || m.on_point)) ? :crosshair : :arrow
end

"""
The buttons of the tools of the diagram that fills the window, with a line
after them: the tools for the part that's selected, or for the whole diagram
while nothing is. A diagram that can't be changed has none.
"""
diagram_buttons(v::ZoomView) = begin
  m = changing(v)
  m === nothing && return ()
  # The caret in the words that are typed into the diagram blinks
  m.typing === nothing || redraw_in!(v, 0.5)
  v.tool = m.waiting
  tools = Diagrams.tools(m)
  isempty(tools) && return ()
  (Any[button!(v, (:tool, t.name), (:tool, t.name), icon=t.icon, tip=t.tip) for t in tools]...,
   Box(width(9px), height(18px), Alignment.Center, justify=Alignment.Center, Box(width(1px), height(18px), background(colours.line))))
end

"Use the tool `name` of the diagram that fills the window. A tool with choices shows them in a menu over its button first."
use_tool!(v::ZoomView, name, w) = begin
  m = changing(v)
  m === nothing && return handled
  i = findfirst(t -> t.name == name, Diagrams.tools(m))
  i === nothing && return handled
  tool = Diagrams.tools(m)[i]
  isempty(tool.choices) && return (Diagrams.use!(m, name); handled)
  b = get(v.parts, (:button, (:tool, name)), nothing)
  left, top = b === nothing ? (w.mouse[1], w.mouse[2]) : (b.rect[1], b.rect[2])
  tall = 28px * length(tool.choices) + 10px
  show_menu!(w, [first(c) for c in tool.choices], left, top - tall - 6px, 200px, theme=menu_theme(), item_height=28px, lift=3.0,
             onselect=k -> k in eachindex(tool.choices) && Diagrams.use!(m, name, last(tool.choices[k])))
  handled
end

"""
Lay the diagram of `v` out at its own size, in the page's font and colours, to
draw at any size. It's laid out again when the font or the colours change.
"""
lay_diagram!(v::ZoomView) = begin
  e = editor(v)
  code = v.what[2]
  # One component shows the diagram for as long as it fills the window, so it keeps what's selected in it
  m = part!(() -> Mermaid(code, bar=false), v, :diagram)
  m.code = code
  m.editing = v.block > 0 && !readonly(e.buf)
  m.keys = part!(() -> ZoomArea(of=v), v, :area)
  m.onchange = m -> write_diagram!(v, m.code)
  key = (code, e.theme, e.font, e.zoom)
  v.drawn !== nothing && v.drawn[1] == key && return v.drawn[2]
  root = with_theme(component_theme(e.zoom)) do
    inner = geometry(m)
    made = m.made === nothing ? nothing : m.made[2]
    (made === nothing || !hasproperty(made, :w) || made.w <= 0) && return nothing
    describe(Column(fixed(px(made.w)), Alignment.Start, inner), (px(made.w), 99999px))
  end
  v.drawn = (key, root)
  root
end

"How wide and how tall what `v` shows is at its own size, in px, or nothing when it can't be shown"
subject_size(v::ZoomView) = begin
  what = v.what
  what === nothing && return nothing
  if what[1] == :picture
    has_image(what[2]) || return nothing
    s = image_source(what[2])
    n = natural(what[2])
    n === nothing ? (Float64(s.width), Float64(s.height)) : (Float64(n[1]), Float64(n[2]))
  elseif what[1] == :diagram
    root = v.drawn === nothing ? nothing : v.drawn[2]
    root === nothing ? nothing : (num(root.width), num(root.height))
  elseif what[1] == :pdf
    s = pdf_size(what[2], v.page)
    s === nothing ? nothing : (Float64(s[1]), Float64(s[2]))
  end
end

"The middle of the part of the view that's above the bar of buttons"
view_middle(v::ZoomView) = (v.box[1] + v.box[3] / 2, v.box[2] + (v.box[4] - num(BAR_ROOM)) / 2)

"How many px to a px of the picture fits the whole of something `s` big in the view, above the bar and with room round it"
fit_zoom(v::ZoomView, s) = max(min((v.box[3] - 2ZOOM_EDGE) / s[1], (v.box[4] - num(BAR_ROOM) - 2ZOOM_EDGE) / s[2]), 1e-3)

"Show the whole picture, in the middle of the view"
fit!(v::ZoomView, s) = (v.zoom = fit_zoom(v, s); v.fits = true; hold!(v, s))

"""
Keep the picture in the view. Where it's narrower than the view, it stays in
the middle, and so it does where it's shorter. Otherwise it moves no further
than its edges, with room round them.
"""
hold!(v::ZoomView, s) = begin
  w, h = v.box[3] / v.zoom, (v.box[4] - num(BAR_ROOM)) / v.zoom
  edge = ZOOM_EDGE / v.zoom
  v.at = (s[1] + 2edge <= w ? (s[1] - w) / 2 : clamp(v.at[1], -edge, s[1] - w + edge),
          s[2] + 2edge <= h ? (s[2] - h) / 2 : clamp(v.at[2], -edge, s[2] - h + edge))
  v
end

"Note that the view is now `box`. A picture that fitted the old view fits the new one."
reframe!(v::ZoomView, box) = begin
  s = subject_size(v)
  changed, v.box = box != v.box, box
  s === nothing && return v
  v.zoom <= 0 || (v.fits && changed) ? fit!(v, s) : hold!(v, s)
end

"Note that the view moved just now, and keep the picture in it"
moved!(v::ZoomView, s) = begin
  v.moved = time()
  hold!(v, s)
  v.fits = v.zoom <= fit_zoom(v, s) * 1.0001
  handled
end

"Fit the picture to the window again"
fit_now!(v::ZoomView) = (s = subject_size(v); s === nothing || fit!(v, s); handled)

"Make the picture `by` times as big. The point of it at the place `(x, y)` in the window stays there."
zoom_by!(v::ZoomView, by, x, y) = begin
  s = subject_size(v)
  (s === nothing || v.zoom <= 0) && return handled
  p = (v.at[1] + (x - v.box[1]) / v.zoom, v.at[2] + (y - v.box[2]) / v.zoom)
  f = fit_zoom(v, s)
  v.zoom = clamp(v.zoom * by, min(f, 1.0), max(f, 1.0) * MOST_ZOOM)
  v.at = (p[1] - (x - v.box[1]) / v.zoom, p[2] - (y - v.box[2]) / v.zoom)
  moved!(v, s)
end

"Go on by `by` pages of a PDF file, as far as the first page or the last"
turn!(v::ZoomView, by) = begin
  page = clamp(v.page + by, 1, v.pages)
  page == v.page && return handled
  v.page, v.zoom, v.fits = page, 0.0, true
  handled
end

draw(ctx, size, ui::ConcreteRect, a::ZoomArea) = begin
  v = a.of
  v.what === nothing && return
  reframe!(v, (num(ui.left), num(ui.top), num(ui.width), num(ui.height)))
  s = subject_size(v)
  (s === nothing || v.zoom <= 0) && return
  with_clip(() -> zoom_ink(ctx, v, s), ctx, ui.left, ui.top, ui.width, ui.height)
end

"Draw what `v` shows, which is `s` big at its own size"
zoom_ink(ctx, v::ZoomView, s) = begin
  x, y = v.box[1] - v.at[1] * v.zoom, v.box[2] - v.at[2] * v.zoom
  w, h = s[1] * v.zoom, s[2] * v.zoom
  kind = v.what[1]
  if kind == :picture
    image = image_source(v.what[2])
    paint_picture(ctx, image.raw, (0, 0, image.width, image.height), (x, y, w, h))
  elseif kind == :diagram
    # The diagram is drawn at its own size onto a canvas that's made bigger, so its lines and its words stay sharp
    root = v.drawn[2]
    Skia.sk_canvas_save(ctx)
    Skia.sk_canvas_translate(ctx, Float32(x), Float32(y))
    Skia.sk_canvas_scale(ctx, Float32(v.zoom), Float32(v.zoom))
    Skia.sk_canvas_translate(ctx, -Float32(num(root.left)), -Float32(num(root.top)))
    try
      draw(ctx, root.size, root)
    finally
      Skia.sk_canvas_restore(ctx)
    end
  else
    paper = (x, y, w, h)
    paper!(ctx, paper)
    with_round_clip(() -> pdf_ink(ctx, v, paper), ctx, px(x), px(y), px(w), px(h), px(PAPER_ROUND))
  end
end

"Draw the part of a PDF page that's in the view, at the screen's own pixels. While it moves, a rougher picture of the whole page shows."
pdf_ink(ctx, v::ZoomView, paper) = begin
  left, top, wide, tall = v.box
  path = v.what[2]
  d = clamp(density(ctx), 2, 3)
  w, h = round(Int, wide * d), round(Int, tall * d)
  (w < 1 || h < 1) && return
  k = v.zoom * d   # the screen's pixels to a point of the page
  of = (path, mtime(path), v.page, k, v.at, w, h)
  p = v.sharp
  if p.of != of && p.cost > QUICK && time() - v.moved < SETTLED
    rough = pdf_page(path, v.page, 2000)
    if rough !== nothing
      r = image_source(rough)
      paint_picture(ctx, r.raw, (0, 0, r.width, r.height), paper)
    end
    redraw_in!(v, SETTLED)
    return
  end
  image = sharpen!(p, path, v.page, of, k, v.at[1] * k, v.at[2] * k, w, h)
  image == C_NULL || paint_picture(ctx, image, (0, 0, w, h), (left, top, wide, tall))
end

"The place in the picture of the diagram that's at the place `at` in the window"
picture_spot(v::ZoomView, at) = (v.at[1] + (num(at[1]) - v.box[1]) / v.zoom, v.at[2] + (num(at[2]) - v.box[2]) / v.zoom)

# A click starts a drag that moves the picture. On the point of a box of a diagram, the drag draws a line from the box.
onkey(a::ZoomArea, ev::KeyPress{Keys.mouse_left}) = begin
  w, v = ev.window, a.of
  focus(a)
  m = changing(v)
  # The point is under the mouse when it's within 8px of it on the screen, however small the diagram is drawn
  m !== nothing && v.zoom > 0 && Diagrams.press_at!(m, picture_spot(v, w.mouse)..., near=8 / v.zoom) && return handled
  v.grab = ((num(w.mouse[1]), num(w.mouse[2])), v.at)
  handled
end

# A line that's dragged from a box's point is drawn when the button comes up over another box
onkey(a::ZoomArea, ev::KeyRelease{Keys.mouse_left}) = begin
  m = changing(a.of)
  m === nothing || a.of.zoom <= 0 || Diagrams.let_go_at!(m, picture_spot(a.of, ev.window.mouse)...)
  nothing
end

"""
The mouse button came up. On a diagram that can be changed, a click that
didn't drag the diagram selects the part that it was on, or nothing. A drag
only moves the diagram, so the part that's selected stays selected.
"""
let_go!(v::ZoomView, w) = begin
  g, v.grab = v.grab, nothing
  m = changing(v)
  (g === nothing || m === nothing || v.zoom <= 0) && return v
  x, y = g[1]
  hypot(num(w.mouse[1]) - x, num(w.mouse[2]) - y) < 4 || return v
  # A line is clicked when the mouse is within 5px of it on the screen, however small the diagram is drawn
  Diagrams.pick_at!(m, v.at[1] + (x - v.box[1]) / v.zoom, v.at[2] + (y - v.box[2]) / v.zoom, near=5 / v.zoom)
  v
end

onmouse(a::ZoomArea, ev::MouseMove) = begin
  v = a.of
  m = changing(v)
  if m !== nothing && v.zoom > 0
    at = picture_spot(v, ev.position)
    if m.joining !== nothing
      Keys.mouse_left in ev.window.keys ? Diagrams.drag_to!(m, at...) : Diagrams.let_go_at!(m, at...)
      return handled
    end
    # The box under the mouse shows its point
    v.grab === nothing && Diagrams.hover_at!(m, at..., near=8 / v.zoom)
  end
  g = v.grab
  g === nothing && return handled
  Keys.mouse_left in ev.window.keys || (let_go!(v, ev.window); return handled)
  s = subject_size(v)
  (s === nothing || v.zoom <= 0) && return handled
  (x0, y0), at = g
  x, y = num(ev.position[1]), num(ev.position[2])
  v.at = (at[1] - (x - x0) / v.zoom, at[2] - (y - y0) / v.zoom)
  moved!(v, s)
end

# Scrolling with ⌘ held makes the picture bigger or smaller, round the mouse. Scrolling without ⌘ moves it.
onscroll(a::ZoomArea, ev::MouseScroll) = begin
  v, w = a.of, ev.window
  Keys.cmd in w.keys && return zoom_by!(v, exp(num(ev.delta[2]) / 10), num(w.mouse[1]), num(w.mouse[2]))
  s = subject_size(v)
  (s === nothing || v.zoom <= 0) && return handled
  v.at = (v.at[1] - 30num(ev.delta[1]) / v.zoom, v.at[2] - 30num(ev.delta[2]) / v.zoom)
  moved!(v, s)
end

# Two fingers that move apart or together on the trackpad make the picture bigger or smaller, round the mouse
onpinch(a::ZoomArea, ev::Pinch) = zoom_by!(a.of, ev.scale, num(ev.window.mouse[1]), num(ev.window.mouse[2]))

# The keys are the view's, so none of them change the page under it: the editor gives each key to `zoom_key!`
# when the key comes up to it. A right-click has no menu here.
onkey(a::ZoomArea, ::KeyPress{Keys.mouse_right}) = handled
ontype(::ZoomArea, ::Typed) = handled

"""
Do what the key `K` does while `v` fills the window. `command` is the command
that the key bindings give the key, or nothing. It's `handled`, or nothing for
the key of a command that the page still takes, like the one that saves. The
keys that change the size of the page's text change the size of the picture.
"""
zoom_key!(v::ZoomView, K, w, command) = begin
  m = changing(v)
  if m !== nothing
    # ⌘Z takes back the last change to the diagram, which is a change to the lines of its block
    if command in (:undo, :redo)
      Diagrams.cancel!(m)
      command == :redo ? redo!(editor(v).buf) : undo!(editor(v).buf)
      return handled
    end
    # Return types the words of the part that's selected, ⌫ takes it away and Esc selects nothing
    Keys.cmd in w.keys || !Diagrams.key!(m, K) || return handled
  end
  K == Keys.escape && return zoom_out!(v)
  command in PAGE_COMMANDS && return nothing
  v.what[1] == :node && return handled
  command == :bigger && return zoom_by!(v, ZOOM_STEP, view_middle(v)...)
  command == :smaller && return zoom_by!(v, 1 / ZOOM_STEP, view_middle(v)...)
  command == :usual_size && return fit_now!(v)
  !(Keys.cmd in w.keys) && v.what[1] == :pdf && K in (Keys.left, Keys.right) && return turn!(v, K == Keys.left ? -1 : 1)
  # A picture of a gallery: ← and → go to the picture before it and the next one
  !(Keys.cmd in w.keys) && v.from isa GalleryView && K in (Keys.left, Keys.right) && return step!(v.from, K == Keys.left ? -1 : 1)
  handled
end

# --- blocks that show as a component ---------------------------------------------------------
#
# A code block in one of the languages of `BLOCKS` shows as a component of its
# own, as a takeoff and a schedule do: a chart, a question, a set of changes,
# a board, a calendar, a list of what was found, a sketch or a list of emails. Each one
# keeps all that it knows in the lines of its block, so the file holds the
# whole of it, and ⌘Z takes back what you do to it. Move the caret into the
# block, or click the block with ⌥ held, to see those lines.
#
# The view of a block is a node with these fields: `n`, its place among the
# page's blocks in its language, `first` and `last`, the lines of its block,
# `lines`, the lines that it was last read from, and `parts`, its buttons and
# the rest that's kept between frames. `reread!(view, lines)` reads it again.

"What a block in one language shows as"
struct BlockKind
  name::String   # what the sidebar calls it
  icon::String   # and the icon beside that name
  view::Any      # the type of its view
  html::Any      # `html(e, view)` is the block as HTML, or nothing to show its lines
end

"The languages whose blocks show as a component, with what each shows as"
const BLOCKS = Dict{String,BlockKind}()

"The view of the `n`th block of the page that shows in the language `lang`"
block_view(e, lang, n) = begin
  v = get!(() -> BLOCKS[lang].view(n=n), e.nodes, (:block, lang, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v
end

"What the block in the language `lang` from line `i` to line `t` shows. `n` is its place among the page's blocks in that language."
block_item(e, lang, i, t, n) = begin
  v = block_view(e, lang, n)
  v.first, v.last = i, t
  reread!(v, e.buf.lines[i+1:t-1])
  # A block that fills the window is drawn over the page, and its room in the page stays empty
  filling(v) && return Live(Box(width(grow=grow), height(v.tall)), v.tall + 2LIVE_GAP)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(v)), (e.width, 9999px))
  can_fill(v) && (v.tall = concrete.height)
  Live(v, concrete.height + 2LIVE_GAP)
end

"The place of the block that opens on line `s` among the blocks of `b` in the language `lang`"
block_place(b::Buffer, lang, s) = count(i -> (k = kinds(b)[i]; k.kind == Kind.fence && k.level == 0 && k.lang == lang), 1:s)

"The block in the language `lang` that opens on line `s`, as HTML, or nothing to show its lines"
block_html(e, lang, s, t) = begin
  ks = kinds(e.buf)
  t > s && ks[t].kind == Kind.fence && ks[t].level == 1 || return nothing
  v = block_view(e, lang, block_place(e.buf, lang, s))
  v.first, v.last = s, t
  reread!(v, e.buf.lines[s+1:t-1])
  BLOCKS[lang].html(e, v)
end

"""
Write `new` as the lines of the block of `v`, a view in the language `lang`.
The caret stays where it was in the text, and ⌘Z takes the change back. With
`typing`, changes that come one soon after another are taken back together.
"""
write_block!(v, lang, new::Vector{String}; typing=false) = begin
  e = editor(v)
  b = e.buf
  readonly(b) && return v
  span = block_lines(b, lang, v.n)
  span === nothing && return v
  i, t = span
  v.first, v.last = i, t
  old = b.lines[i+1:t-1]
  new == old && return reread!(v, new)
  caret, anchor = b.caret, b.anchor
  edit!(b, line_end(b, i), line_end(b, t - 1), isempty(new) ? "" : "\n" * join(new, "\n"); typing)
  by = length(new) - length(old)
  moved(p) = p[1] >= t ? (p[1] + by, p[2]) : p[1] > i ? (i, 0) : p
  b.caret, b.anchor = moved(caret), moved(anchor)
  v.last += by
  reread!(v, new)
end

"What happens to a block's view in each frame, before the page is laid out. Most kinds of block need nothing."
block_tick!(v) = v

"Do what each block of the page that shows needs in this frame"
blocks_tick!(e) = for (key, node) in collect(e.nodes)
  (key isa Tuple && length(key) == 4 && key[1] == :block && key[3] == e.buf.path) || continue
  block_tick!(node)
  filling(node) || continue
  # A block whose lines have gone goes back to the page. Under one that fills the window, the page stays where it was.
  block_lines(e.buf, key[2], node.n) === nothing ? (node.full = false) : (e.scroll.offset = node.pinned)
end

"A part of the block view `v` that's kept between frames"
block_part!(make, v, key) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, v)
  node
end

"A button of a block. A click does `act!(view, action, window)`."
@def mutable struct BlockButton <: SemanticUI
  of::Any = nothing
  action::Any = :none
  icon::String = ""
  words::String = ""
  tip::String = ""
  on::Bool = false                            # it's lit, like the kind of chart that shows now
  off::Bool = false                           # it does nothing now, and shows that
  bold::Bool = false                          # it's filled with colour, like the one button that a question waits for
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
  quiet::Bool = false                         # clicked, so no tooltip until the mouse leaves it
end

"The button of the block view `v` that's kept under `key`, with what it does and shows now"
block_button!(v, key, action; icon="", words="", tip="", on=false, off=false, bold=false) = begin
  b = block_part!(() -> BlockButton(of=v), v, (:button, key))
  b.action, b.icon, b.words, b.tip, b.on, b.off, b.bold = action, icon, words, tip, on, off, bold
  b
end

describe(b::BlockButton) = begin
  ishovered(b) || (b.quiet = false)
  filled = b.bold && !b.off
  colour = b.off ? colours.faint : filled ? colours.bg : b.on ? colours.accent : colours.dim
  back = filled ? (ishovered(b) ? RGBA(colours.accent, 0.85) : colours.accent) :
         b.on ? colours.active : ishovered(b) && !b.off ? colours.hover : clear
  Box(height(26px), padding(filled ? 10px : 7px, 0px), radius(6px), Alignment.Center, name="Button", background(back),
    Row(Alignment.Center, child_gap=5px,
      (isempty(b.icon) ? () : (Icon(b.icon, size=14px, color=colour),))...,
      (isempty(b.words) ? () : (label(b.words, 12px, color=b.off ? colours.faint : filled ? colours.bg : colours.ink, weight=filled ? "Semibold" : ""),))...))
end

cursor(b::BlockButton) = b.off ? :arrow : :hand
draw(ctx, size, ui::ConcreteRect, b::BlockButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::BlockButton, ev::MouseMove) = begin
  (b.quiet || isempty(b.tip)) && return
  show_tooltip!(ev.window, tip_label(b.tip), b.rect..., placement=:bottom, gap=6px)
end

onkey(b::BlockButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  b.off ? handled : act!(b.of, b.action, ev.window)
end

"What a block's box looks like in the page: round corners and a thin line, as a schedule has"
block_look() = (width(grow=grow), Alignment.Start, radius(8px), border(1px, :solid, colours.line), background(takeoff_back()))

"The row of buttons at the top of a block"
block_bar(parts...) = Row(width(grow=grow), height(38px), padding(6px, 0px), child_gap=2px, Alignment.Center, background(colours.block), parts...)

"A line of quiet words in a block that has nothing to show yet"
block_note(words) = Row(width(grow=grow), padding(16px, 20px), Alignment.Center, clip=true,
                        Box(width(grow=grow), Text(words, size=13px, family=SANS, color=colours.dim, wrap=WrapMode.words)))

"A colour as CSS writes it, like #2a78d6"
css_colour(c) = (c = RGBA(c); "#" * join(string(round(Int, 255x), base=16, pad=2) for x in (c.r, c.g, c.b)))

# --- a chart of a table's numbers ------------------------------------------------------------
#
# A code block in the language `chart` draws the numbers of a table of the
# page as bars, as lines or as a pie. chart.jl says how the block is written,
# and works out where each bar goes. The three buttons at the top of the chart
# choose its kind. The mouse over a bar, a dot or a slice says its number.

const CHART = Charts.CHART
const PLOT_H = 260px   # how tall bars and lines are
const PIE_H = 220px    # and a pie
"Every icon that a block can show. The built app reads them all when it's made."
const BLOCK_ICONS = String["bar-chart", "graph-up", "pie-chart"]

# The colours of the columns of numbers, in the order that a chart uses them. Each one can be told from
# the one before it by a reader who doesn't see every colour. The first eight are for a light page.
const SERIES_LIGHT = [colorant"#2a78d6", colorant"#eb6834", colorant"#1baf7a", colorant"#eda100",
                      colorant"#e87ba4", colorant"#008300", colorant"#6250d6", colorant"#e34948"]
const SERIES_DARK = [colorant"#3987e5", colorant"#d95926", colorant"#199e70", colorant"#c98500",
                     colorant"#d55181", colorant"#0ca30c", colorant"#9085e9", colorant"#e66767"]
series_colours() = dark_page() ? SERIES_DARK : SERIES_LIGHT

"What a `chart` block shows: the numbers of a table, drawn"
@def mutable struct ChartView <: SemanticUI
  n::Int = 0                               # its place among the page's charts
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  spec::Charts.Chart = Charts.Chart()
  lines::Vector{String} = String[]         # the lines that `spec` was read from
  shown::Any = nothing                     # the version of the page, and what the chart shows of that page
  marks::Vector{Charts.Mark} = Charts.Mark[]   # the parts of the chart, where they were last drawn
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the chart was last drawn in the window
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons, kept between frames
end

"The part of a chart that shows the bars, the lines or the pie"
@def mutable struct PlotArea <: SemanticUI
  of::Any = nothing
end

reread!(v::ChartView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.spec = Charts.chart(lines)
  v.shown = nothing
  v
end

"The text of a cell without the marks that make it bold or code"
plain_cell(text) = String(strip(replace(text, r"\*\*|__|`" => "")))

"""
Every table of the page that shows: each table, each spreadsheet and each
sheet. Each one has its first and last line, the heading that it's under, and
the text of each cell of each row. A formula's cell holds what the formula
comes to. `headed` is true when the first row has the names of the columns.
"""
page_tables(e) = begin
  b = e.buf
  key = (:tables, b.path, b.version, table_reads[])
  haskey(e.flows, key) && return e.flows[key]
  ks = kinds(b)
  out = @NamedTuple{first::Int, last::Int, under::String, rows::Vector{Vector{String}}, headed::Bool}[]
  under = ""
  i = 1
  while i <= length(ks)
    k = ks[i]
    stop = i
    if k.kind == Kind.heading
      under = plain_cell(rest(b.lines[i], k.prefix))
    elseif k.kind == Kind.table
      run = table(b, i)
      if run !== nothing && run[1] == i
        rows = [String[plain_cell(rest(head(b.lines[r], c.hi), c.lo)) for c in tablecells(b.lines[r])] for r in tablerows(run)]
        push!(out, (first=i, last=run[2], under=under, rows=rows, headed=true))
        stop = run[2]
      end
    elseif k.kind == Kind.fence && k.level == 0 && k.lang in (SPREADSHEET, SHEET)
      t = codeblock(b, i)[2]
      if t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        if k.lang == SPREADSHEET
          texts = [spreadtexts(b.lines[r]) for r in i+1:t-1]
          values = get!(() -> answers(texts), e.flows, (:answers, texts))
          rows = [String[isformula(text) ? (values[r][c].failed ? "" : values[r][c].text) : String(strip(text)) for (c, text) in enumerate(row)]
                  for (r, row) in enumerate(texts)]
        else
          texts = [parts(b.lines[r]) for r in i+1:t-1]
          results = get!(() -> tally(texts), e.flows, (:sheetrun, texts))
          rows = [String[strip(name), results[r].failed ? "" : results[r].text] for (r, (name, _)) in enumerate(texts)]
        end
        push!(out, (first=i, last=t, under=under, rows=rows, headed=false))
        stop = t
      end
    elseif k.kind == Kind.fence && k.level == 0 && k.lang == TIMELOG
      # A log of hours is a table of its tasks, with the hours of each
      t = codeblock(b, i)[2]
      if t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        rows = Timelogs.table(Timelogs.timelog(b.lines[i+1:t-1]), Timelogs.now())
        length(rows) > 1 && push!(out, (first=i, last=t, under=under, rows=rows, headed=true))
        stop = t
      end
    elseif k.kind == Kind.fence && k.level == 0
      stop = max(i, codeblock(b, i)[2])   # a table in a block of code isn't one
    elseif k.kind == Kind.paragraph && (rows = table_rows(e, i)) !== nothing
      push!(out, (first=i, last=i, under=under, rows=rows, headed=true))   # a line that shows a CSV file as a table
    end
    i = stop + 1
  end
  e.flows[key] = out
end

"""
The rows that a chart draws: its own, or those of a table of the page. With
`from`, that's the first table under the heading that `from` names. Without
it, it's the table that's nearest above the chart, or the first one under it.
"""
chart_data(e, v::ChartView) = begin
  c = v.spec
  isempty(c.rows) || return Charts.data(c, c.rows)
  drawn = chart_file(e, c)   # `from` can name a CSV file
  drawn === nothing || return drawn
  tables = page_tables(e)
  k = isempty(c.from) ? something(findlast(t -> t.last < v.first, tables), findfirst(t -> t.first > v.last, tables), 0) :
                        something(findfirst(t -> Charts.same(t.under, c.from), tables), 0)
  k == 0 && return Charts.nothing_to_draw(isempty(c.from) ?
    "This page has no table yet. Put a table, a spreadsheet or a sheet over this chart, and the chart draws its numbers." :
    "This page has no table under a heading called “$(c.from)”.")
  Charts.data(c, tables[k].rows, headed=tables[k].headed)
end

"What the chart shows. It's worked out again when the page has changed."
shown!(v::ChartView) = begin
  e = editor(v)
  key = (e.buf.version, v.first, v.lines, table_reads[])
  (v.shown !== nothing && v.shown[1] == key) || (v.shown = (key, chart_data(e, v)))
  v.shown[2]
end

"How wide `text` is in the font of a chart's words, at the size `size`"
chart_measure(text, size) = num(measure(Face(SANS, "", px(size), colours.ink, false), text))

"The three kinds of chart: the icon of each one's button, and what the button's tooltip says"
const CHART_KINDS = ((:bars, "bar-chart", "Bars"), (:lines, "graph-up", "Lines"), (:pie, "pie-chart", "A pie"))

describe(v::ChartView) = begin
  e = editor(v)
  d = shown!(v)
  with_theme(component_theme(e.zoom)) do
    bar = block_bar(
      [block_button!(v, k, (:kind, k), icon=icon, tip=tip, on=v.spec.kind == k) for (k, icon, tip) in CHART_KINDS]...,
      (isempty(v.spec.title) ? () : (rule(), Row(width(grow=grow), padding(6px, 0px), clip=true, Box(label(v.spec.title, 13px, weight="Semibold")))))...)
    Column(block_look()..., clip=true, name="Chart", bar,
           isempty(d.problem) ? block_part!(() -> PlotArea(of=v), v, :area) : block_note(d.problem))
  end
end

cursor(::Union{ChartView,PlotArea}) = :arrow

act!(v::ChartView, action, w) = begin
  action isa Tuple && action[1] == :kind || return handled
  v.spec.kind = action[2]
  write_block!(v, CHART, Charts.written(v.spec))
  handled
end

describe(a::PlotArea) = Box(width(grow=grow), height(a.of.spec.kind == :pie ? PIE_H : PLOT_H))

"The mark of the chart that the mouse is over, or nothing"
chart_hit(v::ChartView) = begin
  w = window_of(v)
  w === nothing ? nothing : Charts.hit(v.marks, num(w.mouse[1]) - v.box[1], num(w.mouse[2]) - v.box[2])
end

"Draw a filled circle"
disc(ctx, x, y, r, colour) = begin
  paint = ink(colour)
  Skia.sk_canvas_draw_circle(ctx, Float32(x), Float32(y), Float32(r), paint)
  Skia.sk_paint_delete(paint)
end

"Draw the marks of a chart, with the top left corner of the chart at `(x0, y0)`. The mark `hot` is the one under the mouse."
draw_marks(ctx, marks, x0, y0, hot=nothing) = begin
  cs, surface = series_colours(), takeoff_back()
  for m in marks
    # While the mouse is over a bar or a slice, the others are pale
    pale = hot !== nothing && m.kind in (:bar, :slice) && (m.label, m.series) != (hot.label, hot.series)
    colour = m.colour == 0 ? colours.dim : pale ? RGBA(cs[m.colour], 0.4) : cs[m.colour]
    x, y = x0 + m.at[1], y0 + m.at[2]
    if m.kind == :rule
      trace(ctx, [(x, y), (x0 + m.at[3], y0 + m.at[4])], RGBA(colours.ink, m.style == :strong ? 0.3 : 0.08), 1.0)
    elseif m.kind == :bar
      w, h = m.at[3], m.at[4]
      # Only the end that's away from the line of 0 has round corners, so the box is drawn longer and cut off at that line
      with_clip(ctx, px(x), px(y), px(w), px(h)) do
        round_box(ctx, x, m.style == :down ? y - 4 : y, w, h + 4, min(4.0, w / 2); fill=colour)
      end
    elseif m.kind == :line
      trace(ctx, [(x0 + a, y0 + b) for (a, b) in m.points], colour, 2.0)
    elseif m.kind == :dot
      on = hot === m
      r = on ? 5.5 : m.at[3]
      r > 0 || continue
      disc(ctx, x, y, r + 2, surface)   # a ring in the colour of the page keeps it apart from the line that it's on
      disc(ctx, x, y, r, colour)
    elseif m.kind == :slice
      trace(ctx, [(x0 + a, y0 + b) for (a, b) in m.points], surface, 2.0; fill=colour, closed=true)
    elseif m.kind == :swatch
      round_box(ctx, x, y, m.at[3], m.at[4], 2.5; fill=colour)
    elseif m.kind == :words
      face = Face(SANS, "", px(m.size), m.tone == :ink ? colours.ink : colours.dim, false)
      wide = num(measure(face, m.text))
      write_ink(ctx, m.text, m.style == :end ? x - wide : m.style == :middle ? x - wide / 2 : x, y, face)
    end
  end
end

draw(ctx, size, ui::ConcreteRect, a::PlotArea) = begin
  v = a.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  v.box[3] > 0 || return
  v.marks = Charts.plot(shown!(v), v.spec.kind, v.box[3], v.box[4], chart_measure)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    draw_marks(ctx, v.marks, v.box[1], v.box[2], ishovered(a) ? chart_hit(v) : nothing)
  end
end

# The mouse over a bar, a dot or a slice says its number
onmouse(a::PlotArea, ev::MouseMove) = begin
  v = a.of
  m = Charts.hit(v.marks, num(ev.position[1]) - v.box[1], num(ev.position[2]) - v.box[2])
  m === nothing && return nothing
  x, y = v.box[1] + m.at[1], v.box[2] + m.at[2]
  spot = m.kind == :bar ? (x, y, m.at[3], m.at[4]) : m.kind == :dot ? (x - 6, y - 6, 12.0, 12.0) :
         (mid = (m.at[3] + m.at[4]) / 2; (x + 0.6m.size * cos(mid) - 4, y + 0.6m.size * sin(mid) - 4, 8.0, 8.0))
  show_tooltip!(ev.window, tip_label(Charts.said(shown!(v), m)), px.(spot)..., placement=:top, gap=6px)
  handled
end

"The chart as HTML: its title, and a picture of it"
chart_html(e, v::ChartView) = begin
  d = shown!(v)
  isempty(d.problem) || return nothing
  wide, tall = 720.0, num(v.spec.kind == :pie ? PIE_H : PLOT_H)
  picture = Charts.svg(Charts.plot(d, v.spec.kind, wide, tall, chart_measure), wide, tall, colours=css_colour.(SERIES_LIGHT),
                       ink="#2b2622", dim="#6b6259", line="#e6e0d0", surface="#fdfcf9", family="-apple-system, Helvetica, sans-serif")
  title = isempty(v.spec.title) ? "" : "<p><strong>$(escape(v.spec.title))</strong></p>\n"
  "<div class=\"diagram\">\n$title$picture\n</div>"
end

BLOCKS[CHART] = BlockKind("Chart", "bar-chart", ChartView, chart_html)

# --- a map of a place ---------------------------------------------------------------------------
#
# A code block in the language `map` shows the map round a place, with a pin
# on the place and the address under it. map.jl says how the block is
# written. A program of its own asks the Mac's maps for two things: where the
# place is, and the picture of the map. The window never waits for that
# program. Until the picture is there, the block shows a grey box. What comes
# back is kept on the Mac, so a page shows its map at once the next time,
# with no network.
#
#   - The − and the + on the map show more and less of what's round the
#     place. The block keeps that as a line like `zoom: 15`.
#   - A drag moves the map. When the mouse lets go, the block keeps the
#     middle of what shows as a line like `centre: -33.86120, 151.21010`.
#     A third button beside the − takes that line away, so the place is in
#     the middle again.
#   - A click moves the place: the pin goes where the click was, and the
#     block's place becomes that point's latitude and longitude.
#   - Open in Maps opens the Mac's Maps app at the place.
#   - The button beside the map's top right corner makes it fill the window,
#     as a picture does, and so does Return with the caret on the map.
#
# The picture has no pin in it. Ladder draws the pin over the picture, on the
# point where the place is. So a click moves the pin in the same frame, and
# the picture stays the one that it was: it depends on the middle, the zoom,
# the size and dark or light, and not on the place. The address under the map
# comes later, when the program has it.
#
# Every picture is drawn where its own middle is on the map that shows now.
# So after a drag or a change of zoom, the picture that showed stays in its
# place until the right one is there, and the map never jumps.
#
# A window that isn't on the screen, like one a test makes, never runs the
# program and never opens the Maps app. A test puts functions of its own in
# `Maps.HELPER`, `Maps.FINDER` and `Maps.OPENER` to see what the block does
# with them.

@use "github.com/jkroso/UI.jl/Interface/image" register_image

const MAP = Maps.MAP
# Seconds that a map keeps one width before Ladder asks for a picture that wide, and that a pin
# keeps its place before Ladder makes the picture that fills the window
const MAP_PAUSE = 0.3
const MAP_ROUND = 7.0   # the radius of the map's top corners, which are just inside the round corners of its block
const MAP_SLACK = 4.0   # px that the mouse can move between a press and a release that are still a click
push!(BLOCK_ICONS, "geo-alt", "plus-lg", "dash-lg", "box-arrow-up-right", "crosshair")

"What a `map` block shows: a picture of the map round a place, a pin on the place, and the address under it"
@def mutable struct MapView <: SemanticUI
  n::Int = 0                               # its place among the page's maps
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Maps.Site = Maps.Site()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  asked::Any = nothing                     # how wide the map is, and when it got that width
  # What's known of a place: the place, what `Maps.found!` last said of it, and the latitude, the longitude and the address that Apple has for it
  place::Any = nothing
  got::Any = nothing                       # what `Maps.picture!` last said of the picture that the map needs now, and whether the program can run
  # The last picture that was there: its file, its zoom, the latitude and the longitude in its middle, and how wide it is.
  # It shows until the next one is there.
  shown::Any = nothing
  # While the mouse button is down on the map: where it went down, the middle of the map then, and whether the mouse has dragged the map
  grab::Any = nothing
  at::Any = nothing                        # the latitude and the longitude in the middle of the map while a drag moves it
  pinned::Any = nothing                    # the picture and the point that the picture with a pin in it was last made from
  due::Any = nothing                       # the picture and the point that it's to be made from next, and since when
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the picture was last drawn in the window
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons and its picture, kept between frames
end

"The part of a map that shows the picture"
@def mutable struct MapArea <: SemanticUI
  of::Any = nothing
end

reread!(v::MapView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Maps.site(lines)
  v
end

"True in a window that's on the screen. A window that a test makes isn't."
on_screen(node) = (w = window_of(node); w !== nothing && !isempty(w.glfw))

"True when `file` holds a picture that Ladder can draw"
whole_picture(file) = try image_aspect(file) > 0 catch; false end

"The place of the block, as two blocks that name one place have it"
map_place(v::MapView) = lowercase(Maps.query(v.data.place))

"How wide the picture of the map is, in px: as wide as the page's text"
map_wide(v::MapView) = round(Int, num(editor(v).width))

"The zoom that the map's picture is made at: the block's, or a higher one on a page that's too wide for it"
map_zoom(v::MapView) = Maps.fit(v.data.zoom, map_wide(v), Maps.TALL)

"What Apple has for the block's place, or nothing while that isn't known"
map_facts(v::MapView) = (p = v.place; p !== nothing && p.key == map_place(v) ? p.facts : nothing)

"""
Where the pin is: the latitude and the longitude of the block's place. For an
address, that's what Apple has for it. It's nothing until that's known.
"""
map_pin(v::MapView) = begin
  at = Maps.coordinates(v.data.place)
  at !== nothing && return at
  found = map_facts(v)
  found === nothing ? nothing : (found.lat, found.lon)
end

"""
The latitude and the longitude in the middle of the map: where a drag has it
now, what the block's `centre` line says, or the place. It has the five
decimal places that a block keeps, as the middle of a picture has. It's
nothing while the place of an address isn't known.
"""
map_middle(v::MapView) = begin
  v.at === nothing || return v.at
  middle = something(v.data.centre, map_pin(v), Some(nothing))
  middle === nothing ? nothing : Maps.rounded(middle)
end

"""
Where the picture that the map has is on a map `w` px by `h` px that shows
what the block says now: its left, its top, its width and its height, in px
from that map's top left corner. It's nothing when the map has no picture,
or the middle of the map isn't known.
"""
map_spot(v::MapView, w, h) = begin
  shown, middle = v.shown, map_middle(v)
  (shown === nothing || middle === nothing) && return nothing
  zoom = map_zoom(v)
  # A picture that was made at another zoom is drawn as big as the map of this zoom is
  k = 2.0^(zoom - shown.zoom)
  wide, tall = shown.wide * k, Maps.TALL * k
  cx, cy = Maps.point(shown.centre, middle, zoom, w, h)
  (cx - wide / 2, cy - tall / 2, wide, tall)
end

"True when the map has a picture to draw: some of the picture that it has is in the map that shows now"
map_shows(v::MapView) = begin
  w, h = map_wide(v), Maps.TALL
  r = map_spot(v, w, h)
  r !== nothing && r[1] < w && r[1] + r[3] > 0 && r[2] < h && r[2] + r[4] > 0
end

"True when the page can be changed: a page that's read-only takes no drag and no click"
map_changes(v::MapView) = (b = editor(v).buf; !readonly(b) && !b.fixed)

"True when a drag can move the map and a click can move its place: the page can be changed, and the map shows a picture"
map_moves(v::MapView) = map_changes(v) && map_shows(v)

"""
What Apple has for the block's place. The program that finds a place is
started here, when the place isn't kept. A latitude and a longitude need no
finding, and are asked for only to learn their address. What comes back is
read once.
"""
map_find!(v::MapView, runs) = begin
  key = map_place(v)
  p = v.place
  p !== nothing && p.key == key && p.facts !== nothing && return p
  ask(start) = Maps.found!(media_dir(), v.data.place; start)
  found = ask(runs)
  facts = found.state == :there ? Maps.facts(found.file) : nothing
  # A file that holds something else is taken away, and made again later
  found.state == :there && facts === nothing && (Maps.spoiled!(found.file); found = ask(false))
  v.place = (key=key, found=found, facts=facts)
end

"""
The picture that the map needs now: as wide as the page's text, at the block's
zoom, with the middle of the map in its middle, dark on a dark page.
`Maps.picture!` says what it gives. The program that makes the picture is
started here, when the picture isn't kept. While the window changes size, the
map has another width in each frame, so the program is only started once the
width has stayed for a moment. While the place of an address isn't known, the
map has no middle, and no picture is asked for.
"""
map_picture!(v::MapView) = begin
  s = v.data
  wide, dark, zoom = map_wide(v), dark_page(), map_zoom(v)
  (v.asked === nothing || v.asked[1] != wide) && (v.asked = (wide, v.asked === nothing ? 0.0 : time()))
  rest = MAP_PAUSE - (time() - v.asked[2])
  runs = on_screen(v) || Maps.HELPER[] !== Maps.run_program
  place = map_find!(v, runs)
  # The picture is of what the block says, and not of where a drag has the map now: the block changes when the mouse lets go
  middle = something(s.centre, map_pin(v), Some(nothing))
  p = nothing
  if middle !== nothing
    middle = Maps.rounded(middle)
    ask(start) = Maps.picture!(media_dir(), middle, zoom, wide, Maps.TALL, dark; start)
    p = ask(runs && rest <= 0)
    # A file that was cut short is no picture. It's taken away, and made again later.
    p.state == :there && !whole_picture(p.file) && (Maps.spoiled!(p.file); p = ask(false))
    p.state == :there && (v.shown = (file=p.file, zoom=zoom, centre=middle, wide=wide))
  end
  v.shown === nothing || isfile(v.shown.file) || (v.shown = nothing)
  # The window looks again when a program may have finished, when the width has stayed, or when it's time to try again
  wait = min(place.found.wait, p === nothing ? Inf : p.wait, runs && rest > 0 ? rest : Inf)
  isfinite(wait) && redraw_in!(v, max(wait, 0.05))
  v.got = (p, runs)
end

"What a map says in place of a picture that isn't there, or \"\" when it has a picture to show"
map_words(v::MapView) = begin
  map_shows(v) && return ""
  p, runs = v.got
  # Without a middle, the map waits for the place. With one, it waits for the picture.
  waits = p === nothing ? v.place.found : p
  waits.state == :lost ? waits.problem : waits.state == :failed ? waits.problem * (runs ? " It tries again in a minute." : "") :
  waits.state == :none && !runs ? Maps.FAILED : "Finding the place…"
end

"""
The words under a map: the address that Apple has for the place, or the place
as the block has it until that's known. An address that Apple's maps don't
have says so here, when the map shows a picture all the same.
"""
map_address(v::MapView) = begin
  found = map_facts(v)
  found === nothing || isempty(found.address) || return found.address
  lost = v.place !== nothing && v.place.key == map_place(v) && v.place.found.state == :lost
  lost && map_shows(v) ? v.data.place * ". " * v.place.found.problem : v.data.place
end

"""
The point of the picture that the map has where the pin is, in px from the
picture's top left corner. It's nothing when the place isn't known, or isn't
in that picture.
"""
map_pin_in(v::MapView) = begin
  shown, pin = v.shown, map_pin(v)
  (shown === nothing || pin === nothing) && return nothing
  at = Maps.point(pin, shown.centre, shown.zoom, shown.wide, Maps.TALL)
  0 <= at[1] <= shown.wide && 0 <= at[2] <= Maps.TALL ? at : nothing
end

"""
The key, for an Image, of the picture that fills the window: the map's
picture with the pin drawn in it, since what fills the window is a picture
and no more. A map whose place isn't in its picture fills the window as it
is.

That picture takes some hundredths of a second to make. So it's made a
moment after the picture or the pin last changed, and not in the frame of
the click that moved the pin. Until the first one is made, the map fills the
window without its pin.
"""
map_full!(v::MapView) = begin
  shown, at = v.shown, map_pin_in(v)
  at === nothing && return shown.file
  key = "the map with its pin $(objectid(v))"
  want = (shown.file, at)
  if v.pinned != want
    (v.due === nothing || v.due[1] != want) && (v.due = (want, time()))
    if v.grab === nothing && time() - v.due[2] >= MAP_PAUSE
      was = has_image(key) ? image_source(key) : nothing
      register_image(key, pinned_png(shown.file, at))
      was === nothing || Skia.sk_image_unref(was.raw)   # the picture that the key had isn't needed
      v.pinned, v.due = want, nothing
    else
      redraw_in!(v, MAP_PAUSE)
    end
  end
  has_image(key) ? key : shown.file
end

describe(v::MapView) = begin
  e = editor(v)
  s = v.data
  with_theme(component_theme(e.zoom)) do
    isempty(s.place) && return Column(block_look()..., clip=true, name="Map",
      block_note("Write an address in this block, or a latitude and a longitude, to see the map of that place."))
    map_picture!(v)
    area = block_part!(() -> MapArea(of=v), v, :area)
    least, most = first(Maps.ZOOMS), last(Maps.ZOOMS)
    # On a page that's too wide for the lowest zooms, the − stops at the lowest zoom that a picture is made at
    lowest = s.zoom <= least || Maps.fit(s.zoom - 1, map_wide(v), Maps.TALL) == map_zoom(v)
    buttons = Row(radius(7px), padding(2px), child_gap=1px, background(colours.float), border(1px, :solid, colours.line),
      (s.centre === nothing ? () : (block_button!(v, :home, :home, icon="crosshair", tip="Put the place back in the middle of the map"),))...,
      block_button!(v, :out, (:zoom, -1), icon="dash-lg", tip="Show more of what's round the place", off=lowest),
      block_button!(v, :in, (:zoom, 1), icon="plus-lg", tip="Show the place closer", off=s.zoom >= most))
    Column(block_look()..., clip=true, name="Map",
      Stack(width(grow=grow), height(px(Maps.TALL)), Alignment.Start,
        map_shows(v) ? fillable(v, (:picture, map_full!(v)), area, wide=:grow) : area,
        Row(width(grow=grow), padding(8px), Alignment.Start, justify=Alignment.End, buttons)),
      Row(width(grow=grow), padding(5px, 6px, 5px, 12px), child_gap=8px, Alignment.Center,
        Box(Icon("geo-alt", size=14px, color=colours.dim)),
        Box(width(grow=grow), Alignment.Start, clip_x=true, Text(map_address(v), size=12.5px, family=SANS, color=colours.dim, wrap=WrapMode.words)),
        block_button!(v, :open, :open, words="Open in Maps", icon="box-arrow-up-right", tip="Open the Maps app at this place")))
  end
end

describe(a::MapArea) = begin
  words = map_words(a.of)
  # Only its top corners are round, as the corners of its block are
  Box(width(grow=grow), height(px(Maps.TALL)), Alignment.Center, justify=Alignment.Center, padding(60px, 0px),
      radius(px(MAP_ROUND), px(MAP_ROUND), 0px, 0px), background(colours.block),
      (isempty(words) ? () : (Box(Text(words, size=13px, family=SANS, color=colours.dim, wrap=WrapMode.words)),))...)
end

"The places along the bend from `a` to `d` that `b` and `c` pull towards them, without `a`"
pin_bend(a, b, c, d, steps=12) = [(1 - t)^3 .* a .+ 3t * (1 - t)^2 .* b .+ 3t^2 * (1 - t) .* c .+ t^3 .* d for t in (1:steps) ./ steps]

"""
Draw a pin whose point is at `(x, y)`: a red drop with a white dot in it, as
maps mark a place. It's drawn as a shape, so it's sharp however big the
canvas draws it, on the screen and on paper.
"""
pin_ink(ctx, x, y) = begin
  r, cy = 11.0, y - 26.0   # the radius of the pin's round head, and how high its middle is
  shape = [(x, y); pin_bend((x, y), (x - 2, y - 9), (x - r, cy + 9), (x - r, cy));
           [(x - r * cos(a), cy - r * sin(a)) for a in (1:23) .* (π / 24)];
           (x + r, cy); pin_bend((x + r, cy), (x + r, cy + 9), (x + 2, y - 9), (x, y))]
  # A soft shadow on the ground under the point
  shadow = ink(RGBA(0.0, 0.0, 0.0, 0.25))
  ground = Ref(Skia.sk_rect_t(Float32(x - 5), Float32(y - 2), Float32(x + 5), Float32(y + 2)))
  Skia.sk_canvas_draw_oval(ctx, ground, shadow)
  Skia.sk_paint_delete(shadow)
  trace(ctx, shape, RGBA(0.70, 0.16, 0.13, 1.0), 1.0; fill=RGBA(0.92, 0.26, 0.21, 1.0), closed=true)
  disc(ctx, x, cy, 4, RGBA(1.0, 1.0, 1.0, 1.0))
end

"""
The picture in `file` with a pin drawn on the point `at` of it, in px from its
top left corner, as the bytes of a PNG file. The page of HTML and the map
that fills the window show that picture, since each shows a picture and no
more.
"""
pinned_png(file, at) = begin
  image = image_source(file)
  info = Ref(Skia.sk_image_info_t(C_NULL, Skia.SK_COLOR_TYPE_RGBA_8888, Skia.SK_ALPHA_TYPE_OPAQUE, image.width, image.height))
  GC.@preserve info begin
    surface = Skia.sk_surface_make_raster_n32_premul(pointer_from_objref(info), C_NULL)
    surface == C_NULL && return read(file)
    canvas = Skia.sk_surface_get_canvas(surface)
    paint_picture(canvas, image.raw, (0, 0, image.width, image.height), (0, 0, image.width, image.height))
    # The pin is as big on the picture as it is on the page, where the picture has `Maps.SCALE` pixels to the px
    Skia.sk_canvas_scale(canvas, Float32(Maps.SCALE), Float32(Maps.SCALE))
    pin_ink(canvas, at[1], at[2])
    drawn = Skia.sk_surface_make_image_snapshot(surface)
    encoded = Skia.sk_encode_png(C_NULL, drawn, Int32(6))
    bytes = copy(unsafe_wrap(Array, Ptr{UInt8}(Skia.sk_data_get_data(encoded)), Skia.sk_data_get_size(encoded)))
    Skia.sk_data_unref(encoded)
    Skia.sk_image_unref(drawn)
    Skia.sk_surface_unref(surface)
    bytes
  end
end

# The picture is drawn at its own size, with its middle where that latitude and longitude is on the map that
# shows now. So a picture that was made for another width, or for another middle, shows the same streets in
# the same places until the right one is there, and the part with no picture yet is grey. The pin is drawn
# over it, on the place. A place that isn't in the map that shows has no pin, and nothing is drawn outside
# the map's box.
draw(ctx, size, ui::ConcreteRect, a::MapArea) = begin
  v = a.of
  x, y, w, h = v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  r = map_spot(v, w, h)
  (r !== nothing && map_shows(v) && whole_picture(v.shown.file)) || return
  # Only the top corners are round: the box that's cut out goes on under the map's foot
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    with_round_clip(ctx, ui.left, ui.top, ui.width, ui.height + px(2MAP_ROUND), px(MAP_ROUND)) do
      image = image_source(v.shown.file)
      paint_picture(ctx, image.raw, (0, 0, image.width, image.height), (x + r[1], y + r[2], r[3], r[4]))
      pin = map_pin(v)
      pin === nothing && return
      at = Maps.point(pin, map_middle(v), map_zoom(v), w, h)
      0 <= at[1] <= w && 0 <= at[2] <= h && pin_ink(ctx, x + at[1], y + at[2])
    end
  end
end

cursor(::MapView) = :arrow
# UI.jl has no open hand, so a map that a drag can move has the hand that points
cursor(a::MapArea) = map_moves(a.of) ? :hand : :arrow
onpinch(v::MapView, ev::Pinch) = pinch_open(v, ev)

# A press on the map starts a drag that moves the map, or a click that moves the place. The press is the
# map's own, so the page's text takes no caret and no selection from it. With ⌥ held, the press shows the
# block's lines, as it does on any block. A page that can't be changed takes no drag and no click.
onkey(a::MapArea, ev::KeyPress{Keys.mouse_left}) = begin
  v = a.of
  (held(v, Keys.opt) || !map_moves(v)) && return nothing
  w = ev.window
  focus(editor(v))
  v.grab = (from=(num(w.mouse[1]), num(w.mouse[2])), middle=map_middle(v), dragged=false)
  handled
end

# While the button is down, the mouse is the map's wherever it goes, so the page doesn't select text behind it
onmouse(a::MapArea, ev::MouseMove) = begin
  v = a.of
  g = v.grab
  g === nothing && return nothing
  Keys.mouse_left in ev.window.keys || (map_drop!(v); return handled)
  dx, dy = num(ev.position[1]) - g.from[1], num(ev.position[2]) - g.from[2]
  (g.dragged || hypot(dx, dy) >= MAP_SLACK) || return handled
  g.dragged || (v.grab = merge(g, (dragged=true,)))
  zoom = map_zoom(v)
  v.at = Maps.held(Maps.moved(g.middle, dx, dy, zoom), zoom, Maps.TALL)
  handled
end

onkey(a::MapArea, ::KeyRelease{Keys.mouse_left}) = a.of.grab === nothing ? nothing : (map_drop!(a.of); handled)
# The button can come up while the mouse is off the map, where the map doesn't hear of it
block_tick!(v::MapView) = (v.grab !== nothing && !held(v, Keys.mouse_left) && map_drop!(v); v)

"""
The mouse button came up. After a drag, the middle of what shows is written
as the block's `centre` line. After a click, the block's place becomes the
latitude and the longitude of the point that was clicked, and the middle that
showed is written too, so the map stays where it is, with the picture that it
had, and only the pin moves. ⌘Z takes either back.
"""
map_drop!(v::MapView) = begin
  g, v.grab = v.grab, nothing
  at, v.at = v.at, nothing
  (g === nothing || !map_changes(v)) && return v
  s = v.data
  if g.dragged
    at === nothing && return v
    s.centre = Maps.rounded(at)
  else
    clicked = Maps.latlon((g.from[1] - v.box[1], g.from[2] - v.box[2]), g.middle, map_zoom(v), v.box[3], v.box[4])
    s.centre === nothing && (s.centre = g.middle)
    s.place = Maps.text(clicked)
  end
  write_block!(v, MAP, Maps.written(s))
  v
end

act!(v::MapView, action, w) = begin
  if action == :open
    # Only a window that's on the screen opens another app
    (on_screen(v) || Maps.OPENER[] !== Maps.open_app) && Maps.open_place(v.data.place)
  elseif action == :home
    v.data.centre = nothing
    write_block!(v, MAP, Maps.written(v.data))
  elseif action isa Tuple && action[1] == :zoom
    Maps.zoom!(v.data, action[2]) && write_block!(v, MAP, Maps.written(v.data))
  end
  handled
end

"""
The map as HTML: its picture with the pin drawn in it, when a picture is
kept, and the address under it as a link to Apple Maps. The picture is in the
page itself, so the page needs no other file. A page of HTML is light, so it
gets the light map when that one is kept. Nothing is asked of Apple's maps
for it.
"""
map_html(e, v::MapView) = begin
  s = v.data
  isempty(s.place) && return nothing
  found = Maps.found!(media_dir(), s.place, start=false)
  facts = found.state == :there ? Maps.facts(found.file) : nothing
  pin = something(Maps.coordinates(s.place), facts === nothing ? nothing : (facts.lat, facts.lon), Some(nothing))
  middle = something(s.centre, pin, Some(nothing))
  wide, zoom = map_wide(v), map_zoom(v)
  # The picture that the block asks for, light or else dark, or else the picture that the map shows now
  picture = nothing
  if middle !== nothing
    middle = Maps.rounded(middle)
    kept = [Maps.picture!(media_dir(), middle, zoom, wide, Maps.TALL, dark, start=false) for dark in (false, true)]
    k = findfirst(p -> p.state == :there, kept)
    k === nothing || (picture = (file=kept[k].file, zoom=zoom, centre=middle, wide=wide))
  end
  picture === nothing && v.shown !== nothing && isfile(v.shown.file) && map_shows(v) && (picture = v.shown)
  address = escape(facts === nothing || isempty(facts.address) ? s.place : facts.address)
  shows = ""
  if picture !== nothing && whole_picture(picture.file)
    at = pin === nothing ? nothing : Maps.point(pin, picture.centre, picture.zoom, picture.wide, Maps.TALL)
    inside = at !== nothing && 0 <= at[1] <= picture.wide && 0 <= at[2] <= Maps.TALL
    bytes = inside ? pinned_png(picture.file, at) : read(picture.file)
    shows = "<img src=\"$(Maps.data_uri(bytes))\" alt=\"A map of $address\" width=\"$(picture.wide)\">\n"
  end
  "<div class=\"diagram\">\n$shows<p><a href=\"$(escape(Maps.link(s.place)))\">$address</a></p>\n</div>"
end

BLOCKS[MAP] = BlockKind("Map", "geo-alt", MapView, map_html)

# --- a question with answers to choose ---------------------------------------------------------
#
# A code block in the language `ask` shows a question, the answers to choose
# from, and a field to type in. ask.jl says how the block is written. A click
# on an answer chooses it, and what you type in the field goes under the
# answers. Both are written into the block's lines. So an agent that waits for
# the page reads your answer in the lines that you changed. The block has no
# button that sends them: the bell in the top bar sends the page, and so does
# ⌘Return.

const ASK = Asks.ASK
push!(BLOCK_ICONS, "question-circle", "check")

"What an `ask` block shows: a question, its answers and a field to type in"
@def mutable struct AskView <: SemanticUI
  n::Int = 0                               # its place among the page's questions
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Asks.Question = Asks.Question()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its answers, its field and its button, kept between frames
end

"An answer of a question. A click chooses it."
@def mutable struct AskOption <: SemanticUI
  of::Any = nothing
  i::Int = 0
end

"The text field of a question"
ask_input(v::AskView) = block_part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::AskView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Asks.question(lines)
  # The field shows what the block says was typed, as it does after ⌘Z takes some of it back
  i = ask_input(v)
  i.text == v.data.note || (i.text = v.data.note; i.anchor = i.cursor = length(i.text))
  v
end

"What happens to a question in each frame, before the page is laid out: what was typed in its field is written into its block"
block_tick!(v::AskView) = begin
  text = ask_input(v).text
  text == v.data.note && return v
  v.data.note = text
  write_block!(v, ASK, Asks.written(v.data), typing=true)
end

"""
A text beside a mark that is `tall`, such as an icon or a tick box. The text
starts lower than the mark, so the middle of its capitals is level with the
middle of the mark. A text that wraps keeps its first line there.
"""
beside_mark(tall, t::Text) = Box(width(grow=grow), padding(max(0px, (tall - skia_cap_height(t)) / 2), 0px, 0px, 0px), t)

describe(o::AskOption) = begin
  q = o.of.data
  o.i <= length(q.options) || return Box(height(0px))
  opt = q.options[o.i]
  # The tick is as big as its box. A smaller icon isn't put in the middle of the box.
  mark = opt.many ?
    (opt.chosen ? Box(fixed(16px), height(16px), radius(4px), background(colours.accent), Icon("check", size=16px, color=colours.bg)) :
                  Box(fixed(16px), height(16px), radius(4px), border(1.5px, :solid, colours.marker))) :
    Box(fixed(16px), height(16px), radius(8px), Alignment.Center, justify=Alignment.Center,
        border(1.5px, :solid, opt.chosen ? colours.accent : colours.marker),
        (opt.chosen ? (Box(fixed(8px), height(8px), radius(4px), background(colours.accent)),) : ())...)
  Row(width(grow=grow), padding(8px, 6px), radius(6px), child_gap=10px, Alignment.Start, name="Answer",
      background(opt.chosen ? colours.active : ishovered(o) ? colours.hover : clear),
    Box(mark),
    beside_mark(16px, Text(opt.text, size=13.5px, family=SANS, subfamily=opt.chosen ? "Medium" : "", color=colours.ink, wrap=WrapMode.words)))
end

cursor(::AskOption) = :hand
cursor(::AskView) = :arrow

onkey(o::AskOption, ::KeyPress{Keys.mouse_left}) = begin
  v = o.of
  o.i <= length(v.data.options) || return handled
  Asks.choose!(v.data, o.i)
  write_block!(v, ASK, Asks.written(v.data))
  handled
end

describe(v::AskView) = begin
  e = editor(v)
  q = v.data
  input = ask_input(v)
  input.color = colours.ink
  input.placeholder = isempty(q.options) ? "Type your answer" : "Add a note"
  w = window_of(v)
  typing = w !== nothing && w.focus === input
  with_theme(component_theme(e.zoom)) do
    Column(block_look()..., padding(16px, 14px), child_gap=10px, name="Question",
      Row(width(grow=grow), child_gap=10px, Alignment.Start,
        Box(padding(0px, 1px), Icon("question-circle", size=16px, color=Asks.answered(q) ? colours.string : colours.accent)),
        beside_mark(18px, Text(isempty(q.words) ? "A question with no words yet" : Asks.asked(q), size=15px, family=SANS,
                               subfamily="Semibold", color=isempty(q.words) ? colours.dim : colours.ink, wrap=WrapMode.words))),
      (isempty(q.options) ? () : (Column(width(grow=grow), Alignment.Start, child_gap=2px,
        [block_part!(() -> AskOption(of=v, i=i), v, (:option, i)) for i in eachindex(q.options)]...),))...,
      Box(width(grow=grow), height(30px), padding(9px, 0px), radius(6px), border(1px, :solid, typing ? colours.accent : colours.line),
          background(colours.bg), input))
  end
end

# Return in the field gives the keyboard back to the page
onkey(v::AskView, ::KeyPress{Keys.enter}) = (focus(editor(v)); handled)

"The question as HTML: its words, and each answer with a mark on the ones that are chosen"
ask_html(e, v::AskView) = begin
  q = v.data
  rows = ["<li>$(o.chosen ? "☑" : "☐") $(o.chosen ? "<strong>$(escape(o.text))</strong>" : escape(o.text))</li>" for o in q.options]
  "<p><strong>$(escape(Asks.asked(q)))</strong></p>\n" * (isempty(rows) ? "" : "<ul style=\"list-style: none; padding-left: 0.5em\">\n" * join(rows, "\n") * "\n</ul>\n") *
  (isempty(strip(q.note)) ? "" : "<blockquote>$(escape(q.note))</blockquote>")
end

BLOCKS[ASK] = BlockKind("Question", "question-circle", AskView, ask_html)

# --- changes to accept or reject ----------------------------------------------------------------
#
# A code block in the language `changes` holds a diff, and shows each of its
# changes with the lines that go in red and the lines that come in green.
# changes.jl says how the block is written. Each change has an Accept and a
# Reject button. Your choice is written at the end of the change's @@ line,
# so an agent that waits for the page reads it in the lines that you changed.
# Ladder doesn't change the files that the diff is of.
#
# The lines have the colours of code in the language of their file. Where a
# line that comes is a new version of a line that goes, the words that are
# different have a darker mark. A line that's too long goes on under itself.
# Two buttons at the top choose how the lines show: the new lines under the
# old, or the old lines at the left and the new at the right. That choice is a
# setting, so every block of changes shows the same way.
#
# A click on a line opens a field under it, for what you say about that line.
# Your words are written at the end of the block as you type them, so the
# agent reads them with your choices. Return closes the field, and Esc puts
# back what the comment said before. A comment shows under its line. A click
# on it opens it again, and empty words take it away.

const CHANGES = Diffs.CHANGES
const DIFF_ROW = 19.0        # px: how tall a line of a change is
const DIFF_SIZE = 12px       # how big the text of those lines is
const BESIDE_LEAST = 600.0   # px: the narrowest block that shows the old lines beside the new
const NOTE_ROW = 17.0        # px: how tall a line of a comment is
const NOTE_FIELD = 30.0      # px: how tall the field for a comment is
push!(BLOCK_ICONS, "file-diff", "check-lg", "x-lg", "view-stacked", "layout-split")

"What a `changes` block shows: each change of a diff, with buttons that accept it and reject it"
@def mutable struct ChangesView <: SemanticUI
  n::Int = 0                               # its place among the page's blocks of changes
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Diffs.Changes = Diffs.Changes(String[], Diffs.Hunk[])
  lines::Vector{String} = String[]         # the lines that `data` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons and the lines of each change, kept between frames
  laid::Dict{Any,Any} = Dict{Any,Any}()    # the lines of each change as they're drawn, kept until the block is read again
  noting::Union{Nothing,Tuple{Int,Int}} = nothing   # the line that you're writing a comment on: its change, and which of the change's lines
  before::String = ""                      # what that comment said when its field opened, for Esc to put back
end

"The lines of one change"
@def mutable struct HunkArea <: SemanticUI
  of::Any = nothing
  k::Int = 0
  over::Int = 0   # the line of the change that the mouse is on, or 0
end

"The field for what you say about a line"
note_input(v::ChangesView) = block_part!(v, :note) do
  TextInput(placeholder="Say something about this line", font_family=SANS, font_size=12.5px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::ChangesView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Diffs.changes(lines)
  empty!(v.laid)
  v.noting === nothing && return v
  k, j = v.noting
  # The line that the field is under can go, when an agent writes the block again
  (k <= length(v.data.hunks) && j <= length(v.data.hunks[k].rows)) || return (v.noting = nothing; v)
  # The field shows what the block says, as it does after ⌘Z takes some of it back
  i = note_input(v)
  said = get(v.data.notes, (k, j), "")
  i.text == said || (i.text = said; i.anchor = i.cursor = length(said))
  v
end

"What happens to a block of changes in each frame, before the page is laid out: what was typed in its field is written into its block"
block_tick!(v::ChangesView) = begin
  v.noting === nothing && return v
  w = window_of(v)
  # A click somewhere else closes the field
  w !== nothing && w.focus !== note_input(v) && return stop_noting!(v)
  text = note_input(v).text
  text == get(v.data.notes, v.noting, "") && return v
  Diffs.note!(v.data, v.noting..., text)
  write_block!(v, CHANGES, Diffs.written(v.data), typing=true)
end

"Open the field under line `j` of change `k`, with what you said about the line in it"
noting!(v::ChangesView, k, j) = begin
  stop_noting!(v)
  i = note_input(v)
  i.text = get(v.data.notes, (k, j), "")
  i.anchor = i.cursor = length(i.text)
  v.noting, v.before = (k, j), i.text
  empty!(v.laid)
  focus(i)
  v
end

"Close the field. What was typed stays as the comment, without the spaces at its ends. Without `keep`, the comment says what it said before."
stop_noting!(v::ChangesView; keep=true) = begin
  v.noting === nothing && return v
  k, j = v.noting
  i = note_input(v)
  text = keep ? String(strip(i.text)) : v.before
  v.noting = nothing
  empty!(v.laid)
  w = window_of(v)
  w !== nothing && w.focus === i && focus(editor(v))
  text == get(v.data.notes, (k, j), "") && return v
  Diffs.note!(v.data, k, j, text)
  write_block!(v, CHANGES, Diffs.written(v.data), typing=keep)
end

"A line of a change, ready to draw"
struct DiffText
  chars::Vector{Char}
  xs::Vector{Float64}                           # how far across each character starts, and where the last one ends
  parts::Vector{Tuple{UnitRange{Int},Symbol}}   # the characters that have a colour of their own, and which colour
  marks::Vector{UnitRange{Int}}                 # the characters that the other version of the line doesn't have
  indent::Float64                               # how far across its first word starts
end

"""
One line across a change: the row that shows at each side, or 0, and the
characters of that row on each line of text. Or what you said about row
`note`, which shows under that row: `said` has its words, line by line, and
it's empty while the field for them is open.
"""
struct DiffBand
  top::Float64
  tall::Float64
  rows::NTuple{2,Int}
  lines::NTuple{2,Vector{UnitRange{Int}}}
  note::Int
  said::Vector{String}
end

DiffBand(top, tall, rows, lines) = DiffBand(top, tall, rows, lines, 0, String[])

"The lines of a change as they're drawn at one width. With `beside`, the old lines are at the left and the new at the right."
struct DiffLayout
  beside::Bool
  texts::Vector{DiffText}
  bands::Vector{DiffBand}
  digits::Float64   # how wide a column of line numbers is, or 0 when the change has none
  gutter::Float64   # the room for the numbers at the left of a side
  room::Float64     # how wide the text of a side can be
  tall::Float64
end

"The face of a line of a change"
diff_face(colour=colours.ink) = Face(codefont(), codestyle(), DIFF_SIZE, colour, false)

"How far in a line of a row starts when it isn't the row's first: as far as the row's first word, so the code keeps its shape"
hang(t::DiffText, room) = min(t.indent, room / 2)

"The characters of each line of text that the row `t` takes when it has `room` px across. It breaks after a space where it can."
folded(t::DiffText, room) = begin
  n = length(t.chars)
  out = UnitRange{Int}[]
  s = 1
  while s <= n
    space = isempty(out) ? room : room - hang(t, room)
    stop = s   # the last character that fits. A line holds one character at least.
    while stop < n && t.xs[stop+2] - t.xs[s] <= space
      stop += 1
    end
    if stop < n
      k = stop
      while k > s && !isspace(t.chars[k])
        k -= 1
      end
      k > s && !all(isspace, view(t.chars, s:k)) && (stop = k)
    end
    push!(out, s:stop)
    s = stop + 1
  end
  isempty(out) ? [1:0] : out
end

"How wide the lines of a change are in the block of `v`: as wide as the page's text, less the line at each edge of the block"
diff_wide(v::ChangesView) = num(editor(v).width) - 2

"The face of a comment"
note_face() = Face(SANS, "", 12.5px, colours.ink, false)

"The lines that `words` take in `face` when they have `room` px across"
wrapped(face::Face, words, room) = begin
  out = String[]
  line = ""
  for word in split(words)
    longer = isempty(line) ? String(word) : line * " " * word
    if isempty(line) || num(measure(face, longer)) <= room
      line = longer
    else
      push!(out, line)
      line = String(word)
    end
  end
  push!(out, line)
end

"""
Where the box of a comment is across lines `wide` px wide, and how wide it is.
`sign` is of the row that the comment is on. With the old lines beside the
new, the comment on a line that goes is under the old lines, and any other is
under the new lines.
"""
note_box(beside, gutter, sign, wide) = begin
  half = floor(wide / 2)
  !beside ? (gutter, wide - gutter - 10) : sign == '-' ? (gutter, half - gutter - 10) : (half + gutter, wide - half - gutter - 10)
end

"True when the block of `v` shows the old lines beside the new, with lines `wide` px wide"
beside(v::ChangesView, wide=diff_wide(v)) = editor(v).beside && wide >= BESIDE_LEAST

"The lines of change `k` of `v`, laid out `wide` px wide"
laid(v::ChangesView, k, wide=diff_wide(v)) = get!(v.laid, (k, wide, beside(v, wide), codefont(), codestyle())) do
  h = v.data.hunks[k]
  face = diff_face()
  step = num(measure(face, "0"))
  shown(r) = replace(r.text, '\t' => "  ")
  other, marks = Diffs.matched(h; text=shown)
  lang = lowercase(lstrip(splitext(h.file)[2], '.'))
  texts = map(enumerate(h.rows)) do (j, r)
    chars = collect(shown(r))
    xs = zeros(length(chars) + 1)
    for (i, c) in enumerate(chars)
      xs[i+1] = xs[i] + (isascii(c) ? step : num(measure(face, string(c))))
    end
    parts = [(t.col+1:t.col+length(t.text), t.kind) for t in tokens(String(chars), lang) if !all(isspace, t.text)]
    word = findfirst(!isspace, chars)
    DiffText(chars, xs, parts, marks[j], word === nothing ? 0.0 : xs[word])
  end
  numbered = any(r -> r.old > 0 || r.new > 0, h.rows)
  digits = numbered ? num(measure(Face(face, size=10.5px), string(maximum(r -> max(r.old, r.new), h.rows)))) + 10 : 0.0
  two = beside(v, wide)
  gutter = !numbered ? 12.0 : two ? digits + 10 : 2digits + 10
  room = max((two ? floor(wide / 2) : wide) - gutter - 16 - 8, 12step)
  bands = DiffBand[]
  top = 0.0
  for (l, r) in (two ? Diffs.sides(h, other) : [(j, 0) for j in eachindex(h.rows)])
    lines = (l == 0 ? UnitRange{Int}[] : folded(texts[l], room), r == 0 ? UnitRange{Int}[] : folded(texts[r], room))
    tall = DIFF_ROW * max(length(lines[1]), length(lines[2]), 1)
    push!(bands, DiffBand(top, tall, (l, r), lines))
    top += tall
    # What you said about a row is under it, and so is the field for it
    for j in unique((l, r))
      j == 0 && continue
      said = v.noting == (k, j) ? String[] : haskey(v.data.notes, (k, j)) ?
             wrapped(note_face(), v.data.notes[(k, j)], note_box(two, gutter, h.rows[j].sign, wide)[2] - 20) : continue
      tall = isempty(said) ? NOTE_FIELD + 8 : NOTE_ROW * length(said) + 18
      push!(bands, DiffBand(top, tall, (0, 0), (UnitRange{Int}[], UnitRange{Int}[]), j, said))
      top += tall
    end
  end
  DiffLayout(two, texts, bands, digits, gutter, room, top)
end

"The colour of a line that a change takes away, and of the count of those lines"
removed_colour() = dark_page() ? colorant"rgb(240,120,110)" : colorant"rgb(186,52,40)"
"The colour of a line that a change adds"
added_colour() = dark_page() ? colorant"rgb(130,200,120)" : colorant"rgb(40,128,56)"

"How many lines a change adds and takes away, as two small numbers"
tally_words(added, removed) =
  ((added > 0 ? (Box(label("+$added", 12px, color=added_colour(), weight="Medium")),) : ())...,
   (removed > 0 ? (Box(label("−$removed", 12px, color=removed_colour(), weight="Medium")),) : ())...)

"The end of a file's path that fits in `limit` characters, with … for the folders that it leaves out"
short_path(file, limit=44) = begin
  length(file) <= limit && return file
  parts = split(file, '/')
  k = length(parts)
  while k > 1 && sum(length, parts[k-1:end]) + length(parts) - k + 3 <= limit
    k -= 1
  end
  k == 1 ? file : "…/" * join(parts[k:end], '/')
end

"What the row over a change says: its file, and where the change is in it, like `app.js` and `lines 10 to 13`"
change_words(h) = begin
  place = Diffs.place(h)
  isempty(h.file) ? ("", place) : (short_path(h.file), lowercasefirst(place))
end

describe(v::ChangesView) = begin
  e = editor(v)
  c = v.data
  with_theme(component_theme(e.zoom)) do
    isempty(c.hunks) && return Column(block_look()..., clip=true, name="Changes",
      block_note("This block has no changes yet. Put a diff in it, as git diff writes one: a line that starts with @@, then the lines that go with a - before each, and the lines that come with a +."))
    all = length(c.hunks) > 1 ?
      (rule(), block_button!(v, :accept_all, (:all, :accepted), icon="check-lg", words="Accept all", tip="Accept every change"),
       block_button!(v, :reject_all, (:all, :rejected), icon="x-lg", words="Reject all", tip="Reject every change")) : ()
    # The button of the way that the lines show now is lit. A block that's too narrow shows the new lines under the old.
    two = beside(v)
    narrow = diff_wide(v) < BESIDE_LEAST
    ways = (rule(), block_button!(v, :under, (:beside, false), icon="view-stacked", on=!two, tip="Show the new lines under the old lines"),
            block_button!(v, :beside, (:beside, true), icon="layout-split", on=two, off=narrow,
                          tip=narrow ? "The window is too narrow to show the old lines beside the new lines" : "Show the old lines beside the new lines"))
    bar = block_bar(Box(padding(6px, 0px), label(Diffs.summary(c), 12px, color=colours.dim)), Box(width(grow=grow)),
                    Row(child_gap=8px, padding(6px, 0px), tally_words(Diffs.counts(c)...)...), ways..., all...)
    rows = Any[]
    for (k, h) in enumerate(c.hunks)
      state = h.state
      file, place = change_words(h)
      push!(rows, Row(width(grow=grow), height(34px), padding(0px, 6px, 0px, 12px), child_gap=8px, Alignment.Center, clip=true,
                      border(1px, :solid, colours.line)[:top], background(colours.stripe),
        Row(child_gap=5px, (isempty(file) ? () : (Box(label(file, 12px, weight="Semibold")),))...,
            (isempty(place) ? () : (Box(label(place, 12px, color=colours.dim)),))...),
        Row(width(grow=grow), clip=true, Alignment.Start,
            Box(Text(h.about, size=11.5px, family=codefont(), subfamily=codestyle(), color=colours.faint, wrap=WrapMode.none))),
        tally_words(Diffs.counts(h)...)...,
        block_button!(v, (:accept, k), (:choose, k, :accepted), icon="check-lg", words=state == :accepted ? "Accepted" : "Accept",
                      on=state == :accepted, tip=state == :accepted ? "Take your choice away" : "Accept this change"),
        block_button!(v, (:reject, k), (:choose, k, :rejected), icon="x-lg", words=state == :rejected ? "Rejected" : "Reject",
                      on=state == :rejected, tip=state == :rejected ? "Take your choice away" : "Reject this change")))
      push!(rows, block_part!(() -> HunkArea(of=v, k=k), v, (:hunk, k)))
    end
    Column(block_look()..., clip=true, name="Changes", bar, rows...)
  end
end

cursor(::ChangesView) = :arrow
cursor(a::HunkArea) = a.over == 0 ? :arrow : :hand

# Return closes the field for a comment, and Esc puts back what the comment said before
onkey(v::ChangesView, ::KeyPress{Keys.enter}) = v.noting === nothing ? nothing : (stop_noting!(v); handled)
onkey(v::ChangesView, ::KeyPress{Keys.escape}) = v.noting === nothing ? nothing : (stop_noting!(v, keep=false); handled)

"The line of the change of `a` at the place `x`, `y` of the window: a row of the change or the comment on one. 0 when no line is there."
row_at(a::HunkArea, x, y) = begin
  v, r = a.of, rect(a)
  (r === nothing || a.k > length(v.data.hunks)) && return 0
  l = laid(v, a.k)
  dx, dy = x - num(r.left), y - num(r.top) - 4
  for band in l.bands
    band.top <= dy < band.top + band.tall || continue
    return band.note != 0 ? band.note : band.rows[l.beside && dx >= floor(num(r.width) / 2) ? 2 : 1]
  end
  0
end

onmouse(a::HunkArea, ev::MouseMove) = (a.over = readonly(editor(a.of).buf) ? 0 : row_at(a, num(ev.position[1]), num(ev.position[2])); nothing)

# A click on a line opens the field for what you say about it
onkey(a::HunkArea, ev::KeyPress{Keys.mouse_left}) = begin
  # With ⌥ held, the click is the page's, and it shows the block's lines
  (readonly(editor(a.of).buf) || held(a, Keys.opt)) && return nothing
  j = row_at(a, num(ev.window.mouse[1]), num(ev.window.mouse[2]))
  j == 0 ? stop_noting!(a.of) : a.of.noting == (a.k, j) || noting!(a.of, a.k, j)
  handled
end

act!(v::ChangesView, action, w) = begin
  action[1] == :beside && return (beside!(editor(v), action[2]); handled)
  action[1] == :unsay && return (note_input(v).text = ""; stop_noting!(v); handled)
  stop_noting!(v)
  action[1] == :choose ? Diffs.choose!(v.data, action[2], action[3]) : Diffs.choose!(v.data, action[2])
  write_block!(v, CHANGES, Diffs.written(v.data))
  handled
end

"Show the old lines of every block of changes beside the new lines, or the new lines under the old"
beside!(e, on::Bool) = (e.beside = on; rewrap!(e))   # the line under the mouse stays where it is

describe(a::HunkArea) = begin
  v = a.of
  a.k <= length(v.data.hunks) || return Box(width(grow=grow), height(0px))
  l = laid(v, a.k)
  at = v.noting === nothing || v.noting[1] != a.k ? nothing : findfirst(b -> b.note == v.noting[2], l.bands)
  at === nothing && return Box(width(grow=grow), height(px(l.tall + 8)))
  # The field for a comment is where the comment's box will be. The lines round it are drawn over this.
  band = l.bands[at]
  wide = diff_wide(v)
  x, w = note_box(l.beside, l.gutter, v.data.hunks[a.k].rows[band.note].sign, wide)
  input = note_input(v)
  input.color = colours.ink
  win = window_of(v)
  Column(width(grow=grow), height(px(l.tall + 8)), Alignment.Start,
    Box(height(px(band.top + 8))),
    Row(width(grow=grow), height(px(NOTE_FIELD)), padding(0px, px(wide - x - w), 0px, px(x)), child_gap=4px, Alignment.Center,
      Box(width(grow=grow), height(px(NOTE_FIELD)), padding(9px, 0px), radius(6px), background(colours.bg),
          border(1px, :solid, win !== nothing && win.focus === input ? colours.accent : colours.line), input),
      block_button!(v, :unsay, (:unsay,), icon="trash", tip="Delete this comment")))
end

"Fill a box with slanted lines: the side of a change that has no line. The lines of one box go on in the box under it."
hatch(ctx, x, y, w, h, above) = begin
  shape = Skia.sk_path_new()
  gap = 6.0
  # Each line goes up to the right. `c` is how far across it would cross the top of the change's lines.
  for c in (floor((y - above) / gap) * gap):gap:(w + y + h - above)
    Skia.sk_path_move_to(shape, Float32(x + c - (y + h - above)), Float32(y + h))
    Skia.sk_path_line_to(shape, Float32(x + c - (y - above)), Float32(y))
  end
  paint = ink(RGBA(colours.ink, 0.09), 1.0)
  with_clip(ctx, px(x), px(y), px(w), px(h)) do
    Skia.sk_canvas_draw_path(ctx, shape, paint)
  end
  Skia.sk_paint_delete(paint)
  Skia.sk_path_delete(shape)
end

"""
Draw one side of a line across a change, `wide` px wide with its top left at
`x` and `y`: the row's number, its sign and its text, on the colour of a line
that goes or comes. A change that's rejected is `pale`.
"""
diff_side(ctx, l::DiffLayout, h, band::DiffBand, side, x, y, wide, pale, above) = begin
  j = band.rows[side]
  j == 0 && return hatch(ctx, x, y, wide, band.tall, above)
  r, t = h.rows[j], l.texts[j]
  # A line that stays shows at both sides, with its old number at the left and its new one at the right
  colour = r.sign == '+' ? added_colour() : r.sign == '-' ? removed_colour() : nothing
  colour === nothing || round_box(ctx, x, y, wide, band.tall, 0; fill=RGBA(colour, pale ? 0.05 : 0.13))
  small = Face(diff_face(colour === nothing || pale ? colours.faint : colour), size=10.5px)
  for (i, number) in enumerate(l.beside ? (side == 1 ? r.old : r.new,) : (r.old, r.new))
    number > 0 && write_ink(ctx, string(number), x + 6 + i * l.digits - num(measure(small, string(number))), y + 13.5, small)
  end
  code = diff_face(pale ? colours.faint : colours.ink)
  colour === nothing || write_ink(ctx, r.sign == '-' ? "−" : "+", x + l.gutter, y + 13.5, Face(code, color=pale ? colours.faint : colour))
  for (n, span) in enumerate(band.lines[side])
    isempty(span) && continue
    top = y + (n - 1) * DIFF_ROW
    from = x + l.gutter + 16 + (n > 1 ? hang(t, l.room) : 0.0) - t.xs[first(span)]   # where the row's first character would be
    if colour !== nothing && !pale
      # The words that the other version of the line doesn't have
      for m in t.marks
        lo, hi = max(first(m), first(span)), min(last(m), last(span))
        lo <= hi && round_box(ctx, from + t.xs[lo] - 1, top + 2, t.xs[hi+1] - t.xs[lo] + 2, DIFF_ROW - 4, 3; fill=RGBA(colour, 0.24))
      end
    end
    for (chars, kind) in t.parts
      lo, hi = max(first(chars), first(span)), min(last(chars), last(span))
      lo <= hi || continue
      face = pale || kind == :plain ? code : Face(code, color=getfield(colours, kind), style=kind == :comment ? codeslant() : code.style)
      write_ink(ctx, String(t.chars[lo:hi]), from + t.xs[lo], top + 13.5, face)
    end
  end
end

draw(ctx, size, ui::ConcreteRect, a::HunkArea) = begin
  hunks = a.of.data.hunks
  a.k <= length(hunks) || return
  h = hunks[a.k]
  left, top, wide = num(ui.left), num(ui.top) + 4, num(ui.width)
  l = laid(a.of, a.k, wide)
  half = floor(wide / 2)
  # A change that's rejected is pale
  pale = h.state == :rejected
  over = ishovered(a) ? a.over : 0
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    for band in l.bands
      y = top + band.top
      if band.note != 0
        # What you said about the row over this, in a box. While its field is open, the field is here.
        isempty(band.said) && continue
        x, w = note_box(l.beside, l.gutter, h.rows[band.note].sign, wide)
        round_box(ctx, left + x, y + 4, w, band.tall - 8, 6; fill=colours.bg, line=over == band.note ? colours.accent : colours.line)
        for (n, words) in enumerate(band.said)
          write_ink(ctx, words, left + x + 10, y + 9 + n * NOTE_ROW - 4.5, Face(note_face(), color=pale ? colours.dim : colours.ink))
        end
        continue
      end
      if over != 0 && over in band.rows && !haskey(a.of.data.notes, (a.k, over)) && a.of.noting != (a.k, over)
        # A mark at the end of the line that the mouse is on says that a click adds a comment
        right = !l.beside || band.rows[2] == over ? left + wide : left + half
        mark = Face(SANS, "Semibold", 13px, colours.bg, false)
        round_box(ctx, right - 24, y + 2, 16, 15, 4; fill=colours.accent)
        write_ink(ctx, "+", right - 16 - num(measure(mark, "+")) / 2, y + 14, mark)
      end
      if l.beside
        diff_side(ctx, l, h, band, 1, left, y, half, pale, top)
        diff_side(ctx, l, h, band, 2, left + half, y, wide - half, pale, top)
      else
        diff_side(ctx, l, h, band, 1, left, y, wide, pale, top)
      end
    end
    l.beside && round_box(ctx, left + half, num(ui.top), 1, num(ui.height), 0; fill=colours.line)
    # A change that's accepted has a green edge
    h.state == :accepted && round_box(ctx, left, num(ui.top), 3, num(ui.height), 0; fill=added_colour())
  end
end

"The changes as HTML: each one with its file, where it is and your choice, its lines, and what you said about them"
changes_html(e, v::ChangesView) = begin
  c = v.data
  isempty(c.hunks) && return nothing
  parts = map(enumerate(c.hunks)) do (k, h)
    about = join(filter(!isempty, [h.file, Diffs.place(h), h.state == :open ? "" : uppercasefirst(string(h.state))]), " · ")
    lines = map(h.rows) do r
      text = escape((r.sign == ' ' ? "  " : r.sign == '-' ? "− " : "+ ") * r.text)
      r.sign == '+' ? "<span style=\"background: #e2f2dc; display: block\">$text</span>" :
      r.sign == '-' ? "<span style=\"background: #f8dfda; display: block\">$text</span>" : "<span style=\"display: block\">$text</span>"
    end
    # What you said about a line is under the change, with the line
    said = join("\n<blockquote><code>$(escape(h.rows[j].sign * h.rows[j].text))</code><br>$(escape(c.notes[(k, j)]))</blockquote>"
                for j in eachindex(h.rows) if haskey(c.notes, (k, j)))
    "<p><strong>$(escape(about))</strong></p>\n<pre><code>" * join(lines) * "</code></pre>" * said
  end
  join(parts, "\n")
end

BLOCKS[CHANGES] = BlockKind("Changes", "file-diff", ChangesView, changes_html)

# --- a calendar of the page's days -------------------------------------------------------------
#
# A code block in the language `calendar` shows one month as a grid of days,
# from Monday to Sunday. calendar.jl says how the block is written. Each day
# shows the things of the page that are on it: the tasks of the page's
# schedule, the to-do items that have a day in their text, and the events
# that the block's own lines hold.
#
#   - The arrows at the top go to the month before and the month after, and
#     Today goes back to the month of today.
#   - Click a thing to select it, and click it twice to go to its line.
#   - Click the box of a to-do item to tick it in the page.
#   - Drag a to-do item or an event to another day. Ladder writes the new day
#     into the item's text or the event's line. A task stays where it is: the
#     schedule says when it's done.
#   - Click a day twice to add an event to it, type its words, and press Return.
#   - A day with more things than it has room for says how many more there
#     are. Click those words to make the week tall enough for all of them.

const CALENDAR = Calendars.CALENDAR
push!(BLOCK_ICONS, "calendar3", "chevron-left", "chevron-right")
const DAY_ROWS = 3        # how many lines of things a day has room for
const DAY_HEAD = 26px     # how tall the number of a day is
const THING_H = 20px      # how tall a thing of a day is
const THING_GAP = 2px     # and the space under it
const DAY_TIGHT = 76px    # a day that's narrower than this has less space round its things, and no box or tick before their words

"The day that counts as today, or nothing for the real one. A test names a day here, so that it doesn't depend on the day that it runs."
const calendar_day = Ref{Union{Nothing,Date}}(nothing)
calendar_today() = something(calendar_day[], Dates.today())

"What a `calendar` block shows: a month, with the things of the page on their days"
@def mutable struct CalendarView <: SemanticUI
  n::Int = 0                               # its place among the page's calendars
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Calendars.Calendar = Calendars.Calendar()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # the version of the page and the day, and the things of each day for them
  picked::Any = nothing                    # the thing that's selected, by what `Calendars.id` gives
  grab::Any = nothing                      # the thing that the mouse holds, where the mouse took it, and whether it has moved since
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where it was last clicked
  open::Set{Date} = Set{Date}()            # the Monday of each week that shows every thing of its days
  adding::Union{Nothing,Date} = nothing    # the day that a new event is being typed for
  wide::px = 0px                           # how wide a day is
  weeks::Int = 0                           # how many weeks the month that shows is in
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons, days and things, kept between frames
end

"A day of a calendar"
@def mutable struct CalendarDay <: SemanticUI
  of::Any = nothing
  i::Int = 0                 # its place among the days that show
  day::Date = Date(2000)
  tall::px = 0px             # how tall its week is
end
"A thing of a day: a task, a to-do item or an event"
@def mutable struct CalendarThing <: SemanticUI
  of::Any = nothing
  thing::Any = nothing
  box::Any = nothing         # the box of a to-do item
  cut::Bool = false          # its words have no room, and end with …
end
"The box of a to-do item in a calendar. A click ticks the item in the page."
@def mutable struct CalendarTick <: SemanticUI
  of::Any = nothing          # the thing
end
"The words under a day that has more things than room: a click shows them all, or hides them again"
@def mutable struct CalendarMore <: SemanticUI
  of::Any = nothing
  day::Date = Date(2000)
  more::Int = 0              # how many things don't show, or 0 when they all do
end
"The thing that the mouse drags, drawn over the calendar"
@def mutable struct CalendarDrag <: SemanticUI
  of::Any = nothing
end

reread!(v::CalendarView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Calendars.calendar(lines)
  v.shown = nothing
  v
end

"The first day of the month that the calendar shows"
month_shown(v::CalendarView) = Calendars.shown(v.data, today=calendar_today())

"""
The tasks of the page's first schedule with their days, and whether its work
is done on Saturday and Sunday too. A page with no schedule has no tasks.
"""
calendar_tasks(e) = begin
  b = e.buf
  span = block_lines(b, SCHEDULE, 1)
  span === nothing && return Schedules.Planned[], false
  s = schedule_view(e, 1)
  reread!(s, b.lines[span[1]+1:span[2]-1])
  tasks!(s), s.data.weekends
end

"The things of each day. They're worked out again when the page has changed, and on a new day."
things!(v::CalendarView) = begin
  e = editor(v)
  key = (e.buf.version, v.lines, calendar_today())
  (v.shown !== nothing && v.shown[1] == key) || (v.shown = (key, Calendars.things(v.data, page_todos(e), calendar_tasks(e)...)))
  v.shown[2]
end

"The things of the day `d`"
day_things(v::CalendarView, d::Date) = get(things!(v), d, Calendars.Thing[])

"The line of the page that the thing `t` is on, or 0 when its block has gone"
thing_line(v::CalendarView, t) = begin
  t.kind == :event || return t.line
  span = block_lines(editor(v).buf, CALENDAR, v.n)
  span === nothing ? 0 : span[1] + t.line
end

"The text field of a calendar, for the words of a new event"
calendar_input(v::CalendarView) = block_part!(v, :input) do
  TextInput(placeholder="New event", font_family=SANS, font_size=12px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"True when the days are narrow, as they are in a narrow window"
tight(v::CalendarView) = v.wide < DAY_TIGHT

"How much room the words of a thing have in a day. `lead` is how wide the box or the tick before them is, with the space after it."
words_room(v::CalendarView, lead=0px) = max(v.wide - (tight(v) ? 13px : 19px) - lead, 1px)

"True while the mouse drags a thing of the calendar"
dragging(v::CalendarView) = v.grab !== nothing && v.grab[4]

"The day that the mouse is over, or nothing when the mouse isn't over a day"
drop_day(v::CalendarView) = begin
  w = window_of(v)
  w === nothing && return nothing
  x, y = w.mouse[1], w.mouse[2]
  for i in 1:7v.weeks
    c = get(v.parts, (:day, i), nothing)
    r = c === nothing ? nothing : rect(c)
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return c.day
  end
  nothing
end

"Note a click at `(x, y)`. True when it's the second of two clicks in one place."
click_twice!(v::CalendarView, x, y) = begin
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  time() - at < 0.35 && hypot(x - cx, y - cy) < 4
end

"How many lines the day `d` needs when its week shows every thing: its things, the field for a new event, and the words that hide them again"
day_lines(v::CalendarView, d::Date) = (n = length(day_things(v, d)); n + (v.adding == d ? 1 : 0) + (n > DAY_ROWS ? 1 : 0))

"How many lines of things each day of a week has room for. A week that shows every thing has room for the day with the most."
week_rows(v::CalendarView, week) = week[1] in v.open ? max(DAY_ROWS, maximum(d -> day_lines(v, d), week)) : DAY_ROWS

describe(t::CalendarTick) = begin
  thing = t.of.thing
  done = thing !== nothing && thing.done
  side = 13px
  Box(fixed(side), height(side), radius(3.5px), Alignment.Center, justify=Alignment.Center,
      (done ? (background(RGBA(colours.accent, 0.6)),) : (border(1.5px, :solid, ishovered(t) ? colours.accent : colours.marker),))...,
      (done ? (Icon("check", size=11px, color=colours.bg),) : ())...)
end

onkey(t::CalendarTick, ::KeyPress{Keys.mouse_left}) = begin
  c = t.of
  v, thing = c.of, c.thing
  settle!(v)
  e = editor(v)
  (thing === nothing || readonly(e.buf)) && return handled
  items = page_todos(e)
  k = findfirst(it -> it.key == thing.key, items)
  k === nothing || tick!(e, items[k].line)
  handled
end

describe(c::CalendarThing) = begin
  v, t = c.of, c.thing
  t === nothing && return Box(height(0px))
  on = v.picked == Calendars.id(t)
  taken = dragging(v) && Calendars.id(v.grab[1]) == Calendars.id(t)
  c.box === nothing && (c.box = CalendarTick(of=c); setfield!(c.box, :parent, c))
  if t.kind == :task
    # A task looks like its bar in the schedule
    hue = t.done ? colours.string : colours.accent
    look = (background(RGBA(hue, on ? 0.32 : 0.17)), border(on ? 1.5px : 1px, :solid, RGBA(hue, 0.9)))
    lead = t.done && !tight(v) ? (Icon("check", size=12px, color=hue),) : ()
  else
    look = (background(taken ? clear : colours.block),
            border(on && !taken ? 1.5px : 1px, :solid, taken ? colours.faint : on ? colours.accent : ishovered(c) ? colours.marker : colours.line))
    # A narrow day has no room for the box: the words need it
    lead = t.kind == :todo && !tight(v) ? (c.box,) : ()
  end
  words = elide(t.words, 12px, words_room(v, isempty(lead) ? 0px : 18px))
  c.cut = words != t.words
  Row(width(grow=grow), height(THING_H), padding(tight(v) ? 3px : 5px, 0px), radius(5px), child_gap=5px, Alignment.Center, clip=true, name="Thing", look...,
    lead..., Box(label(words, 12px, color=taken ? colours.faint : t.done ? colours.dim : colours.ink)), Box(width(grow=grow)))
end

cursor(::Union{CalendarThing,CalendarTick,CalendarMore}) = :hand
cursor(::Union{CalendarView,CalendarDay,CalendarDrag}) = :arrow

onkey(c::CalendarThing, ev::KeyPress{Keys.mouse_left}) = begin
  v, w, t = c.of, ev.window, c.thing
  settle!(v)
  hide_tooltip!(w)
  t === nothing && return handled
  x, y = num(w.mouse[1]), num(w.mouse[2])
  twice = click_twice!(v, x, y)
  again = v.picked == Calendars.id(t)
  v.picked = Calendars.id(t)
  # Two clicks in one place go to the thing's line of the page
  twice && again && return show_line!(editor(v), thing_line(v, t))
  # A task's days are the schedule's, so a task stays where it is
  t.kind == :task || readonly(editor(v).buf) || (v.grab = (t, x, y, false))
  # The press isn't a click on the page's text, so the text doesn't select when the mouse leaves the calendar with the thing
  e = editor(v)
  e.clicked = (e.clicked[1], e.clicked[2], 0)
  handled
end

# A thing whose words are cut short shows all of them over it
onmouse(c::CalendarThing, ev::MouseMove) = begin
  v, r = c.of, rect(c)
  (c.cut && c.thing !== nothing && v.grab === nothing && r !== nothing) || return nothing
  show_tooltip!(ev.window, tip_label(c.thing.words), r.left, r.top, r.width, r.height, placement=:top, gap=6px)
  nothing
end

describe(m::CalendarMore) = begin
  words = m.more > 0 ? "$(m.more) more" : "Fewer"
  Row(width(grow=grow), height(THING_H), padding(tight(m.of) ? 4px : 6px, 0px), Alignment.Center, clip=true, name="More",
    Box(label(elide(words, 11px, words_room(m.of)), 11px, color=ishovered(m) ? colours.accent : colours.dim)), Box(width(grow=grow)))
end

onkey(m::CalendarMore, ::KeyPress{Keys.mouse_left}) = begin
  v, week = m.of, Calendars.monday(m.day)
  settle!(v)
  week in v.open ? delete!(v.open, week) : push!(v.open, week)
  handled
end

describe(c::CalendarDay) = begin
  v, d = c.of, c.day
  list = day_things(v, d)
  open = Calendars.monday(d) in v.open
  some, more = open ? (list, 0) : Calendars.fit(list, DAY_ROWS)
  inside = Dates.month(d) == Dates.month(month_shown(v))
  weekend = Dates.dayofweek(d) > 5
  number = string(Dates.day(d))
  head = d == calendar_today() ?
    Row(fixed(20px), height(20px), radius(10px), Alignment.Center, justify=Alignment.Center, background(colours.accent),
        Box(label(number, 11px, color=colours.bg, weight="Semibold"))) :
    Row(height(20px), padding(4px, 0px), Alignment.Center,
        Box(label(number, 11px, color=!inside ? colours.faint : weekend ? colours.dim : colours.ink)))
  field = v.adding == d ?
    (Box(width(grow=grow), height(THING_H), padding(tight(v) ? 3px : 5px, 0px), radius(5px), border(1px, :solid, colours.accent), background(colours.bg), calendar_input(v)),) : ()
  under = more > 0 || (open && length(list) > DAY_ROWS) ?
    ((m = block_part!(() -> CalendarMore(of=v), v, (:more, c.i)); m.day = d; m.more = more; m),) : ()
  over = dragging(v) && drop_day(v) == d
  Column(width(grow=grow), height(c.tall), padding(tight(v) ? 2px : 3px, 0px), child_gap=THING_GAP, Alignment.Start, clip=true, name="Day",
         border(1px, :solid, colours.line)[(c.i % 7 == 1 ? (:top,) : (:top, :left))...],
         background(over ? RGBA(colours.accent, 0.14) : weekend ? RGBA(colours.ink, 0.035) : clear),
    Row(width(grow=grow), height(DAY_HEAD - THING_GAP), padding(tight(v) ? 2px : 1px, 0px), Alignment.Center, head, Box(width(grow=grow))),
    [(t = block_part!(() -> CalendarThing(of=v), v, (:thing, c.i, k)); t.thing = thing; t) for (k, thing) in enumerate(some)]...,
    field..., under...)
end

onkey(c::CalendarDay, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = c.of, ev.window
  settle!(v)
  v.picked = nothing
  # Two clicks on a day start a new event there
  click_twice!(v, num(w.mouse[1]), num(w.mouse[2])) && !readonly(editor(v).buf) && return add_event!(v, c.day)
  handled
end

"Show the field for a new event on the day `d`, and give it the keyboard"
add_event!(v::CalendarView, d::Date) = begin
  i = calendar_input(v)
  i.color = colours.ink
  i.text = ""
  i.anchor = i.cursor = 0
  v.adding = d
  v.clicked = (0.0, 0.0, 0.0)          # the next click isn't the second of two
  push!(v.open, Calendars.monday(d))   # the week grows, so that the field has room
  focus(i)
  handled
end

"Take the field for a new event away. With `keep`, the words that were typed are written into the block as an event."
settle!(v::CalendarView; keep=true) = begin
  d = v.adding
  d === nothing && return handled
  v.adding = nothing
  i = calendar_input(v)
  w = window_of(v)
  w !== nothing && w.focus === i && focus(editor(v))
  words = strip(replace(i.text, r"\s+" => " "))
  keep && !isempty(words) && write_block!(v, CALENDAR, Calendars.added(v.lines, d, words))
  handled
end

onkey(v::CalendarView, ::KeyPress{Keys.enter}) = v.adding === nothing ? nothing : settle!(v)
onkey(v::CalendarView, ::KeyPress{Keys.escape}) = v.adding === nothing ? nothing : settle!(v, keep=false)
# A click beside a button is the block's, and doesn't move the caret
onkey(v::CalendarView, ::KeyPress{Keys.mouse_left}) = (settle!(v); handled)
# A drag is the calendar's, so the page's text doesn't select
onmouse(v::CalendarView, ::MouseMove) = v.grab !== nothing || held(v, Keys.mouse_left) ? handled : nothing

"Do what a button of a calendar does: show the month before, the month after or the month of today"
act!(v::CalendarView, action, w) = begin
  settle!(v)
  empty!(v.open)
  to = action == :today ? nothing : month_shown(v) + Dates.Month(action == :before ? -1 : 1)
  write_block!(v, CALENDAR, Calendars.turned(v.lines, to))
  handled
end

describe(v::CalendarView) = begin
  e = editor(v)
  w = window_of(v)
  g = v.grab
  # A press that moves is a drag, and isn't the first click of two
  if g !== nothing && !g[4] && w !== nothing && hypot(num(w.mouse[1]) - g[2], num(w.mouse[2]) - g[3]) > 4
    v.grab = (g[1], g[2], g[3], true)
    v.clicked = (0.0, 0.0, 0.0)
  end
  calendar_input(v).color = colours.ink
  with_theme(component_theme(e.zoom)) do
    month = month_shown(v)
    weeks = Calendars.weeks(month)
    v.wide = (e.width - 2px) / 7   # each day is as wide as the next
    v.weeks = length(weeks)
    off = readonly(e.buf)
    bar = block_bar(
      block_button!(v, :before, :before, icon="chevron-left", tip="The month before", off=off),
      Row(fixed(max(min(122px, e.width - 150px), 10px)), Alignment.Center, justify=Alignment.Center, clip=true,
          Box(label(Calendars.title(month), 13px, weight="Semibold"))),
      block_button!(v, :after, :after, icon="chevron-right", tip="The month after", off=off),
      Box(width(grow=grow)),
      block_button!(v, :today, :today, words="Today", tip="Show the month of today", off=off || v.data.month === nothing))
    names = Row(width(grow=grow), height(24px), Alignment.Center,
      [Row(fixed(v.wide), padding(8px, 0px), Alignment.Center, clip=true,
           Box(label(name, 11px, color=i > 5 ? colours.faint : colours.dim)), Box(width(grow=grow))) for (i, name) in enumerate(Calendars.DAYS)]...)
    rows = map(enumerate(weeks)) do (k, week)
      tall = DAY_HEAD + week_rows(v, week) * (THING_H + THING_GAP) + 3px
      days = map(enumerate(week)) do (i, d)
        c = block_part!(() -> CalendarDay(of=v), v, (:day, 7(k - 1) + i))
        c.i, c.day, c.tall = 7(k - 1) + i, d, tall
        Box(fixed(v.wide), Alignment.Start, c)
      end
      Row(width(grow=grow), Alignment.Start, days...)
    end
    Stack(block_look()..., clip=true, name="Calendar", Column(width(grow=grow), Alignment.Start, bar, names, rows...),
          (dragging(v) ? (block_part!(() -> CalendarDrag(of=v), v, :drag),) : ())...)
  end
end

describe(::CalendarDrag) = Box(width(grow=grow), height(grow=grow))

draw(ctx, size, ui::ConcreteRect, layer::CalendarDrag) = begin
  v = layer.of
  w = window_of(v)
  (w === nothing || !dragging(v)) && return
  t = v.grab[1]
  # The thing stays under the mouse
  wide = max(num(v.wide) - 6, 40.0)
  x, y = num(w.mouse[1]) - wide / 2, num(w.mouse[2]) - 10
  face = Face(SANS, "", 12px, colours.ink, false)
  round_box(ctx, x + 1, y + 3, wide, 20, 5; fill=RGBA(0, 0, 0, 0.12))
  round_box(ctx, x, y, wide, 20, 5; fill=takeoff_back(), line=colours.accent, wide=1.5)
  write_ink(ctx, elide(t.words, 12px, px(wide - 12)), x + 6, y + 14, face)
end

"A drag ended. Ladder writes the day that the thing was dropped on into the to-do item's text, or into the event's line."
drop!(v::CalendarView) = begin
  g = v.grab
  v.grab = nothing
  (g === nothing || !g[4]) && return v
  t, d = g[1], drop_day(v)
  e = editor(v)
  b = e.buf
  (d === nothing || d == t.day || readonly(b)) && return v
  if t.kind == :event
    write_block!(v, CALENDAR, Calendars.moved(v.lines, t.line, d))
  elseif t.kind == :todo
    k = findfirst(it -> it.key == t.key, page_todos(e))
    k === nothing && return v
    line = page_todos(e)[k].line
    at = Calendars.stamp_at(b.lines[line], t.day)
    at === nothing && return v
    caret, anchor = b.caret, b.anchor
    edit!(b, (line, at[1]), (line, at[2]), string(d))
    kept(p) = p[1] == line ? (line, min(p[2], length(b.lines[line]))) : p
    b.caret, b.anchor = kept(caret), kept(anchor)
    # The item's name has the new day in it, and the item stays selected
    k = findfirst(it -> it.line == line, page_todos(e))
    k === nothing || (v.picked = (:todo, page_todos(e)[k].key))
  end
  v.shown = nothing
  v
end

"What happens to a calendar in each frame, before the page is laid out: a drag that ended is written down, and the field that lost the keyboard closes"
block_tick!(v::CalendarView) = begin
  v.grab !== nothing && !held(v, Keys.mouse_left) && drop!(v)
  w = window_of(v)
  # A click somewhere else took the keyboard from the field. The words that were typed are kept.
  v.adding !== nothing && w !== nothing && w.focus !== calendar_input(v) && settle!(v)
  v
end

"A thing of a day as HTML. A thing that's done has a tick, and is grey."
thing_html(t) = t.done ? "<span style=\"color: #8a8176\">✓ $(escape(t.words))</span>" : escape(t.words)

"The calendar as HTML: a table with a row for each week of the month, and the things of each day in the day's cell"
calendar_html(e, v::CalendarView) = begin
  month = month_shown(v)
  days = things!(v)
  cell(d) = begin
    number = Dates.month(d) == Dates.month(month) ? "<b>$(Dates.day(d))</b>" : "<span style=\"color: #a89f91\">$(Dates.day(d))</span>"
    "<td style=\"vertical-align: top\">" * join([number; thing_html.(get(days, d, Calendars.Thing[]))], "<br>") * "</td>"
  end
  heads = join("<th>$name</th>" for name in Calendars.DAYS)
  rows = join(("<tr>" * join(cell.(week)) * "</tr>" for week in Calendars.weeks(month)), "\n")
  "<table style=\"width: 100%; table-layout: fixed\">\n<caption>$(Calendars.title(month))</caption>\n<tr>$heads</tr>\n$rows\n</table>"
end

BLOCKS[CALENDAR] = BlockKind("Calendar", "calendar3", CalendarView, calendar_html)

# --- a board of the page's tasks ---------------------------------------------------------------
#
# A code block in the language `board` shows each to-do item of the page as a
# card, in columns. board.jl says how the block is written. Drag a card to
# another column to move it. The last column holds the items that are ticked:
# a card that's dropped there ticks its item in the page, and a card that's
# dragged out of it takes the tick away. Click a card twice to go to its line
# of the page. The block's lines hold the column of each card that's between
# the first column and the last.

const BOARD = Boards.BOARD
push!(BLOCK_ICONS, "kanban")

"What a `board` block shows: the page's to-do items as cards in columns"
@def mutable struct BoardView <: SemanticUI
  n::Int = 0                               # its place among the page's boards
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Boards.Board = Boards.Board()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # the version of the page, and the cards of each column for that page
  grab::Any = nothing                      # the card that the mouse holds: its name, where the mouse took it, and whether it has moved since
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where a card was last clicked
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its columns and cards, kept between frames
end

"A column of a board"
@def mutable struct BoardColumn <: SemanticUI
  of::Any = nothing
  c::Int = 0
end
"A card of a board: one to-do item of the page"
@def mutable struct BoardCard <: SemanticUI
  of::Any = nothing
  key::String = ""
end
"The card that the mouse drags, drawn over the board"
@def mutable struct DragLayer <: SemanticUI
  of::Any = nothing
end

reread!(v::BoardView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Boards.board(lines)
  v.shown = nothing
  v
end

"The cards of each column of the board. They're worked out again when the page has changed."
columns!(v::BoardView) = begin
  e = editor(v)
  key = (e.buf.version, v.lines)
  (v.shown !== nothing && v.shown[1] == key) || (v.shown = (key, Boards.arrange(v.data, page_todos(e))))
  v.shown[2]
end

"The to-do item of the page that the card called `key` is for, or nothing"
card_todo(v::BoardView, key) = (items = page_todos(editor(v)); k = findfirst(t -> t.key == key, items); k === nothing ? nothing : items[k])

"True while the mouse drags a card of the board"
dragging(v::BoardView) = v.grab !== nothing && v.grab[4]

"The place of the column that the mouse is over, or nothing when the mouse isn't over the board"
drop_column(v::BoardView) = begin
  w = window_of(v)
  r = rect(v)
  (w === nothing || r === nothing) && return nothing
  x, y = w.mouse[1], w.mouse[2]
  (r.top - 40px <= y <= r.top + r.height + 40px) || return nothing
  for c in eachindex(v.data.columns)
    column = get(v.parts, (:column, c), nothing)
    cr = column === nothing ? nothing : rect(column)
    cr !== nothing && cr.left <= x < cr.left + cr.width && return c
  end
  nothing
end

describe(card::BoardCard) = begin
  v = card.of
  t = card_todo(v, card.key)
  t === nothing && return Box(height(0px))
  taken = dragging(v) && v.grab[1] == card.key
  Row(width(grow=grow), padding(10px, 8px), radius(6px), child_gap=7px, Alignment.Start, name="Card",
      background(taken ? clear : takeoff_back()), border(1px, :solid, taken ? colours.faint : ishovered(card) ? colours.marker : colours.line),
    (t.done ? (Box(padding(0px, 2px), Icon("check", size=14px, color=taken ? colours.faint : colours.string)),) : ())...,
    Box(width(grow=grow), Text(t.name, size=13px, family=SANS, color=taken ? colours.faint : t.done ? colours.dim : colours.ink, wrap=WrapMode.words)))
end

cursor(::BoardCard) = :hand
cursor(::Union{BoardView,BoardColumn,DragLayer}) = :arrow

onkey(card::BoardCard, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = card.of, ev.window
  x, y = num(w.mouse[1]), num(w.mouse[2])
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  t = card_todo(v, card.key)
  # Two clicks in one place go to the card's line of the page
  time() - at < 0.35 && hypot(x - cx, y - cy) < 4 && t !== nothing && return show_line!(editor(v), t.line)
  v.grab = (card.key, x, y, false)
  handled
end

describe(col::BoardColumn) = begin
  v = col.of
  cards = col.c <= length(columns!(v)) ? columns!(v)[col.c] : Schedules.Todo[]
  over = dragging(v) && drop_column(v) == col.c
  Column(width(grow=grow), Alignment.Start, radius(8px), padding(8px), child_gap=6px, name="Column",
         background(over ? RGBA(colours.accent, 0.14) : colours.block),
    Row(width(grow=grow), height(22px), padding(3px, 0px), child_gap=7px, Alignment.Center,
        Box(label(get(v.data.columns, col.c, ""), 12px, color=colours.dim, weight="Semibold")),
        Box(label(string(length(cards)), 11px, color=colours.faint)), Box(width(grow=grow))),
    [block_part!(() -> BoardCard(of=v, key=t.key), v, (:card, t.key)) for t in cards]...,
    (isempty(cards) ? (Box(width(grow=grow), height(34px)),) : ())...)
end

describe(v::BoardView) = begin
  e = editor(v)
  w = window_of(v)
  g = v.grab
  # A press that moves is a drag
  if g !== nothing && !g[4] && w !== nothing && hypot(num(w.mouse[1]) - g[2], num(w.mouse[2]) - g[3]) > 4
    v.grab = (g[1], g[2], g[3], true)
  end
  # The cards of items that the page had once are forgotten
  length(v.parts) > 2length(page_todos(e)) + 40 && filter!(p -> !(p[1] isa Tuple && p[1][1] == :card) || card_todo(v, p[1][2]) !== nothing, v.parts)
  with_theme(component_theme(e.zoom)) do
    isempty(page_todos(e)) && return Column(block_look()..., clip=true, name="Board",
      block_note("This page has no to-do items yet. Start a line with - [ ] to make a card."))
    n = length(v.data.columns)
    wide = (e.width - 2px - 16px - 8px * (n - 1)) / n   # each column is as wide as the next
    columns = Row(width(grow=grow), padding(8px), child_gap=8px, Alignment.Start,
      [Box(fixed(wide), Alignment.Start, block_part!(() -> BoardColumn(of=v, c=c), v, (:column, c))) for c in 1:n]...)
    Stack(block_look()..., clip=true, name="Board", columns,
          (dragging(v) ? (block_part!(() -> DragLayer(of=v), v, :drag),) : ())...)
  end
end

describe(::DragLayer) = Box(width(grow=grow), height(grow=grow))

draw(ctx, size, ui::ConcreteRect, layer::DragLayer) = begin
  v = layer.of
  w = window_of(v)
  (w === nothing || !dragging(v)) && return
  t = card_todo(v, v.grab[1])
  column = get(v.parts, (:column, 1), nothing)
  cr = column === nothing ? nothing : rect(column)
  (t === nothing || cr === nothing) && return
  # The card stays under the mouse where the mouse took hold of it
  wide = num(cr.width) - 16
  x, y = num(w.mouse[1]) - wide / 2, num(w.mouse[2]) - 17
  face = Face(SANS, "", 13px, colours.ink, false)
  round_box(ctx, x + 1, y + 3, wide, 34, 6; fill=RGBA(0, 0, 0, 0.12))
  round_box(ctx, x, y, wide, 34, 6; fill=takeoff_back(), line=colours.accent, wide=1.5)
  write_ink(ctx, elide(t.name, 13px, px(wide - 20)), x + 10, y + 22, face)
end

"A drag ended. The card goes to the column that it was dropped on, and its item is ticked if that's the last one."
drop!(v::BoardView) = begin
  g = v.grab
  v.grab = nothing
  (g === nothing || !g[4]) && return v
  c = drop_column(v)
  e = editor(v)
  b = e.buf
  items = page_todos(e)
  t = card_todo(v, g[1])
  (c === nothing || t === nothing || readonly(b) || Boards.column(v.data, t, items) == c) && return v
  Boards.prune!(v.data, items)
  tick = Boards.move!(v.data, t, c, items)
  # The tick and the block's lines change together, so one ⌘Z takes both back
  b.typed = 0.0
  if tick !== nothing
    caret, anchor = b.caret, b.anchor
    col = findfirst('[', b.lines[t.line])
    edit!(b, (t.line, col), (t.line, col + 1), tick ? "x" : " ", typing=true)
    b.caret, b.anchor = caret, anchor
  end
  write_block!(v, BOARD, Boards.written(v.data), typing=true)
  b.typed = 0.0
  v.shown = nothing
  v
end

block_tick!(v::BoardView) = (v.grab !== nothing && !held(v, Keys.mouse_left) && drop!(v); v)
# A drag is the board's, so the page's text doesn't select
onmouse(v::BoardView, ::MouseMove) = v.grab === nothing ? nothing : handled

"The board as HTML: a table with a column for each of the board's columns"
board_html(e, v::BoardView) = begin
  columns = columns!(v)
  all(isempty, columns) && return nothing
  heads = join("<th>$(escape(name))</th>" for name in v.data.columns)
  cells = join("<td style=\"vertical-align: top\">" * join((escape(t.name) for t in cards), "<br>") * "</td>" for cards in columns)
  "<table>\n<tr>$heads</tr>\n<tr>$cells</tr>\n</table>"
end

BLOCKS[BOARD] = BlockKind("Board", "kanban", BoardView, board_html)

# --- blocks of the page side by side -------------------------------------------------------------
#
# A code block in the language `columns` holds a number, and that many of the
# blocks after it show side by side. columns.jl says how the block is written
# and which blocks each column holds. The blocks stay the page's own lines:
# the caret goes into them, and every key does there what it does anywhere else.
#
# The page's layout does the work. `page_columns!` finds the columns before
# the page is laid out. `column_turn!` is called at each line of the layout.
# In a column it makes the page's text as wide as the column, so each line
# wraps there, and each table, picture and component is made for that width.
# A column's lines of text and its tables are placed at the column's left
# edge. So the caret, the selection and a click find them as they find any
# other line. Each column starts level with the first, and the page goes on
# under the tallest. `page_parts` puts the columns side by side in the window.
#
# In a narrow window the blocks show one under another.
#
# The `columns` block itself takes no room in the page, and shows nothing.
# `column_fold` says which lines that is: the block's own, and as many of the
# empty lines after it as there are before it. So the room over the columns is
# the room between two blocks. As rich text the caret steps over those lines,
# as it steps over the ``` lines of a code block. As plain text (⌘E) the caret
# goes through them, and the block shows its lines while the caret is on them.
# A block that doesn't say how many columns keeps a little room, and says how
# to write it.

const COLUMN_BLOCK = Columns.COLUMNS   # the language of the block. `COLUMNS` is the columns of a takeoff's table.
const COLUMN_GAP = 1.6     # the room between two columns, as a part of the size of the page's text
const COLUMN_MARK = 1px    # how tall a `columns` block that says nothing is in the page, without the room above and below it
push!(BLOCK_ICONS, "columns-gap")

"One column of the page, as the layout places it"
struct PageColumn
  first::Int   # the lines of the page that show in it
  last::Int
  left::px     # how far its left edge is from the left edge of the page's text
  wide::px
  group::Int   # the place of its group among the page's groups of columns
end

"The columns that one `columns` block makes"
mutable struct ColumnGroup
  block::Int   # the line that opens the `columns` block
  top::px      # how far down the page the layout put the columns
  tall::px     # they're as tall as the tallest of them
end

"The columns of a page that are side by side, and what the layout does with them"
mutable struct PageColumns
  path::String                      # the page that they're the columns of
  columns::Vector{PageColumn}       # in the order of their lines
  groups::Vector{ColumnGroup}
  folds::Vector{Tuple{Int,Int,Bool}}   # the lines of each `columns` block that takes no room, and whether the caret is in them
  now::Union{Nothing,PageColumn}    # the column that the layout is in. The page's text is as wide as that column then.
  busy::Bool                        # a line of a column is being laid out, so `column_at` doesn't send it round again
  next::Int                         # the place in `columns` of the next column that the layout comes to
  from::Int                         # the first item of the column that the layout is in
  flows::Dict{Any,Any}              # the page's own layouts and its width, to put back after a column
  width::px
end

"The room between two columns of the page"
column_gap(e) = body(e).size * COLUMN_GAP

"Each `columns` block of the page, with the blocks that it puts in columns. They're found again when the page has changed."
column_groups(e) = begin
  b = e.buf
  get!(e.flows, (:column_groups, b.path, b.version)) do
    # A line that holds only a picture or a formula is a block by itself
    Columns.groups(b.lines, kinds(b), alone=i -> pictured(b, i) || maths_line(b, i))
  end
end

"""
The lines of a `columns` block that takes no room in the page, when line `i`
is one of them: the first and the last. Nothing for any other line. A block
that says how many columns takes no room. Nor do the empty lines after it, as
many of them as there are empty lines before it: the room that's left over the
columns is the room between two blocks of the page.
"""
column_fold(b::Buffer, i::Int) = begin
  b.view == :markdown || return nothing
  ks = kinds(b)
  j = i
  if ks[i].kind == Kind.blank
    # An empty line is one of them when the block is the first thing over it
    while j > 1 && ks[j].kind == Kind.blank
      j -= 1
    end
    (ks[j].kind == Kind.fence && ks[j].level == 1) || return nothing
  elseif !(ks[i].kind in (Kind.fence, Kind.code))
    return nothing
  end
  s, t = codeblock(b, j)
  (t > s && Columns.opens(ks[s]) && ks[t].kind == Kind.fence && ks[t].level == 1) || return nothing
  Columns.shares(@view b.lines[s+1:t-1]) === nothing && return nothing
  bare(k) = 1 <= k <= length(ks) && ks[k].kind == Kind.blank
  n = 0
  while bare(s - n - 1) && bare(t + n + 1)
    n += 1
  end
  i <= t + n ? (s, t + n) : nothing
end

"""
Find the columns of the page, before the layout: where each is across the
page, and how wide. A window that's too narrow has none. It also finds the
`columns` blocks that take no room. It's nothing when the page has neither. A
layout that failed in a column left the column's width behind, so the page's
own is put back first.
"""
page_columns!(e) = begin
  old = pop!(e.nodes, :columns, nothing)
  old !== nothing && old.now !== nothing && (e.flows = old.flows; empty!(e.flows))
  b = e.buf
  (b.view == :markdown && lowered(e) === nothing) || return nothing
  found = column_groups(e)
  isempty(found) && return nothing
  gap = column_gap(e)
  s = PageColumns(b.path, PageColumn[], ColumnGroup[], Tuple{Int,Int,Bool}[], nothing, false, 1, 0, e.flows, e.width)
  for g in found
    fold = column_fold(b, g.first)
    # With the caret in them, the lines of the block show
    fold === nothing || push!(s.folds, (fold..., !caretless(b) && all(p -> fold[1] <= p[1] <= fold[2], (b.caret, b.anchor))))
  end
  for g in (Columns.stacked(num(e.width), e.zoom) ? () : found)
    isempty(g.spans) && continue
    push!(s.groups, ColumnGroup(g.first, 0px, 0px))
    left = 0px
    # A group with fewer blocks than its number has room for the columns that it hasn't got
    for (k, wide) in enumerate(Columns.rooms(g.shares, num(e.width), num(gap))[1:length(g.spans)])
      lines = Columns.reach(g, k)
      push!(s.columns, PageColumn(first(lines), last(lines), left, px(wide), length(s.groups)))
      left += px(wide) + gap
    end
  end
  isempty(s.columns) && isempty(s.folds) && return nothing
  e.nodes[:columns] = s
end

"True when `it`, an item that the layout just made, is of a `columns` block that takes no room: the block, or an empty line after it"
folded(s::PageColumns, e, it::Item) = begin
  k = findfirst(f -> f[1] <= it.first <= f[2], s.folds)
  k === nothing && return false
  # With the caret in the block, the block is lines of code, which show
  it.content isa Live && return it.content.node isa ColumnsView
  it.content isa Flow && kinds(e.buf)[it.first].kind == Kind.blank && !s.folds[k][3]
end

"An item that takes no room, in the place of `it`"
flat(e, it::Item) = Item(it.first, it.last, it.top, 0px, Flow([VLine(Seg[], 0px, 0, 0, 0px, 0px)], 0px, body(e).size, 0px, 0px, Kind.blank, false))

"The column that line `i` of the page shows in, or nothing"
column_at(e, i::Int) = begin
  s = get(e.nodes, :columns, nothing)
  # Another page can show before the next layout finds its columns
  (s === nothing || s.busy || s.path != e.buf.path) && return nothing
  for c in s.columns
    c.first > i && break
    i <= c.last && return c
  end
  nothing
end

"How far the left edge of `it` is from the left edge of the page's text, and how wide it is: its column's, or the page's"
item_room(e, it::Item) = (c = column_at(e, it.first); c === nothing ? (0px, e.width) : (c.left, c.wide))

"The layouts of the lines of a column that's as wide as `c`, kept apart from those of the page's own width"
column_cache(s::PageColumns, c::PageColumn) = get!(() -> Dict{Any,Any}(), s.flows, (:column, c.wide))

"Do `f` while the page's text is as wide as the column `c`, so that what `f` lays out and describes fits the column"
in_column(f, e, s::PageColumns, c::PageColumn) = begin
  width, flows = e.width, e.flows
  e.width, e.flows = c.wide, column_cache(s, c)
  try
    f()
  finally
    e.width, e.flows = width, flows
  end
end

"`f` moved `dx` to the right. A line of a column is placed at the column's left edge."
shifted(f::Flow, dx::px) = dx == 0px ? f :
  Flow([VLine([Seg(s.text, s.col, s.n, s.face, s.atomic, s.link, s.x + dx, s.w, s.node) for s in vl.segs], vl.x + dx, vl.from, vl.to, vl.top, vl.high)
        for vl in f.lines], f.lh, f.size, f.above, f.below, f.kind, f.raw)
shifted(g::Grid, dx::px) = dx == 0px ? g : Grid(g.rows, g.widths, g.heights, g.cells, g.flows, g.head, g.left + dx, g.values)
shifted(content, dx::px) = content   # a sheet and a component have no place across the page of their own

"Line `i` of the page, which is in the column `c`, laid out for the column's width and placed at its left edge"
column_flow(e, c::PageColumn, i::Int, raw::Bool) = begin
  s = e.nodes[:columns]
  s.busy = true
  f = try
    # The layout of the page is in the column already. Anything else that asks is at the page's own width.
    s.now === c ? flow(e, i, raw) : in_column(() -> flow(e, i, raw), e, s, c)
  finally
    s.busy = false
  end
  shifted(f, c.left)
end

"""
The layout has come to line `i` of the page, and `top` is how far down the page
it has got. This says how far down the page line `i` goes. After a `columns`
block, line `i` goes where the block was, because the block takes no room. At
the first line of a column, the page's text becomes as wide as the column, and
the line goes level with the top of the group's first column. After the last line of a
column, the page's text gets its own width back. After the last column of a
group, the page goes on under the tallest column.
"""
column_turn!(s::PageColumns, e, items::Vector{Item}, i::Int, top::px) = begin
  # A `columns` block takes no room, so the item that was just made for it goes flat, and line `i` takes its place
  if !isempty(items) && last(items).tall > 0px && folded(s, e, last(items))
    items[end] = flat(e, last(items))
    top = last(items).top
  end
  c = s.now
  if c !== nothing && i > c.last
    g = s.groups[c.group]
    g.tall = max(g.tall, top - g.top)
    e.width, e.flows = s.width, s.flows
    s.now = nothing
    # A table is placed at the column's left edge, as each line of text was when it was laid out
    for k in s.from:length(items)
      it = items[k]
      it.content isa Grid && (items[k] = Item(it.first, it.last, it.top, it.tall, shifted(it.content, c.left)))
    end
    ends = s.next > length(s.columns) || s.columns[s.next].group != c.group
    ends && (top = g.top + g.tall)
  end
  if s.now === nothing && s.next <= length(s.columns) && i >= s.columns[s.next].first
    c = s.columns[s.next]
    g = s.groups[c.group]
    (s.next == 1 || s.columns[s.next-1].group != c.group) && (g.top = top; g.tall = 0px)
    s.next += 1
    s.now, s.from = c, length(items) + 1
    e.width, e.flows = c.wide, column_cache(s, c)
    top = g.top
  end
  top
end

"How far down the page the lowest of `items` ends. In a group of columns, that's the end of the tallest column."
lowest(e, items) = haskey(e.nodes, :columns) ? maximum(it -> it.top + it.tall, items) : last(items).top + last(items).tall

"The first and the last of the items `lo` to `hi` of the page, with the whole of each group of columns that they're part of"
whole_groups(e, items, lo::Int, hi::Int) = begin
  first_of(k) = (c = column_at(e, items[k].first); c === nothing ? nothing : c.group)
  while lo > 1 && first_of(lo) !== nothing && first_of(lo - 1) == first_of(lo)
    lo -= 1
  end
  while hi < length(items) && first_of(hi) !== nothing && first_of(hi + 1) == first_of(hi)
    hi += 1
  end
  (lo, hi)
end

"""
The place in the page's layout of the item under a point that's `dx` across
and `dy` down from the top left corner of the page's text. Beside a group of
columns and between two of them, it's an item of the column that the point is
in or after. Under a column that's shorter than its group, it's the column's
last item.
"""
item_under(e, dx::px, dy::px) = begin
  items = e.layout
  k = something(findlast(it -> it.top <= dy, items), 1)
  s = get(e.nodes, :columns, nothing)
  s === nothing && return k
  g = findfirst(g -> g.top <= dy < g.top + g.tall, s.groups)
  g === nothing && return k
  mine = [c for c in s.columns if c.group == g]
  c = mine[something(findlast(c -> c.left <= dx, mine), 1)]
  lo = findfirst(it -> it.first >= c.first, items)
  hi = findlast(it -> it.first <= c.last, items)
  (lo === nothing || hi === nothing || hi < lo) && return k
  lo - 1 + something(findlast(it -> it.top <= dy, view(items, lo:hi)), 1)
end

"""
The parts of the page that `items` show, as the document holds them: one under
another, with the columns of a group side by side. Each column describes its
blocks while the page's text is as wide as the column.
"""
page_parts(d::Document, e, items) = begin
  parts(run) = Any[x isa Item ? describe(e, x) : x for x in blocks(d, run)]
  s = get(e.nodes, :columns, nothing)
  s === nothing && return parts(items)
  out, run = Any[], Item[]
  k, n = 1, length(items)
  while k <= n
    c = column_at(e, items[k].first)
    if c === nothing
      push!(run, items[k])
      k += 1
      continue
    end
    append!(out, parts(run))
    empty!(run)
    group, columns = c.group, Any[]
    while k <= n && c !== nothing && c.group == group
      mine = Item[]
      while k <= n && items[k].first <= c.last
        it = items[k]
        # Its text is drawn from the column's own left edge
        push!(mine, Item(it.first, it.last, it.top, it.tall, shifted(it.content, -c.left)))
        k += 1
      end
      push!(columns, in_column(() -> Column(fixed(c.wide), Alignment.Start, name="Column", parts(mine)...), e, s, c))
      c = k <= n ? column_at(e, items[k].first) : nothing
    end
    push!(out, Row(width(grow=grow), Alignment.Start, child_gap=column_gap(e), name="Columns", columns...))
  end
  append!(out, parts(run))
  out
end

"""
The place on line `j` that ↑ or ↓ takes the caret to from line `from`, with `x`
as far across the page as the caret tries to stay. It's nothing when `j` isn't
a line of the page. It follows the rules of `line_step`: the caret steps over
a line that doesn't show, and goes onto a part like a picture as a whole.
"""
land(e, j::Int, by::Int, x::px, from::Int) = begin
  b = e.buf
  if rich(b)
    j = step_over(b, j, by, from)
    1 <= j <= length(b.lines) || return nothing
    free(b, j, from) || return (j, 0)
  end
  1 <= j <= length(b.lines) || return nothing
  into = item(e, j)
  into.content isa Sheet && return enter(e, into, into.content, by, x - item_room(e, into)[1])
  f = flow(e, j, b.plain)
  (j, colat(f, by < 0 ? length(f.lines) : 1, x))
end

"""
The place one line up or down the screen from the caret. ↑ and ↓ stay in a
column of the page: they go through its blocks, and leave the group of columns
from the column's first and last line. Into a group, they go to the column
that's under the caret.
"""
vertical(e, by::Int) = begin
  p = line_step(e, by)
  s = get(e.nodes, :columns, nothing)
  s === nothing && return p
  b = e.buf
  i = b.caret[1]
  from, to = column_at(e, i), column_at(e, p[1])
  from == to && return p
  x = something(e.goal, 0px)
  if from !== nothing
    # In a table, the caret keeps its place across its cell. Out of the table it keeps its place across the page,
    # so that it comes back into the column that it left.
    it = item(e, i)
    at = it.content isa Grid ? gridcell(it.content, b.caret) : nothing
    at === nothing || (x = e.goal = cell_origin(it.content, at...)[1] + spot(it.content.flows[at[1]][at[2]], b.caret[2])[2])
    # Out of a column: only the line above the group or the line under it is next, not another column's
    (to === nothing || to.group != from.group) && return p
    mine = [c for c in s.columns if c.group == from.group]
    j = by > 0 ? last(mine).last + 1 : first(mine).first - 1
    return something(land(e, j, by, x, i), b.caret)
  end
  # Into a group: the column that the caret is over
  mine = [c for c in s.columns if c.group == to.group]
  c = mine[something(findlast(c -> c.left <= x, mine), 1)]
  something(land(e, by > 0 ? c.first : c.last, by, x, i), p)
end

"""
The view of a `columns` block. A block that says how many columns shows
nothing, and the layout gives it no room. One that doesn't say shows a faint
line with words that say how to write it.
"""
@def mutable struct ColumnsView <: SemanticUI
  n::Int = 0                                       # its place among the page's `columns` blocks
  first::Int = 0                                   # the lines of its block, when the page was last laid out
  last::Int = 0
  shares::Union{Nothing,Vector{Float64}} = nothing   # the share of each column, or nothing when the block doesn't say
  lines::Vector{String} = String[]                 # the lines that `shares` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()
end

reread!(v::ColumnsView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.shares = Columns.shares(lines)
  v
end

"What the line of a block that doesn't say how many columns says"
const COLUMN_WORDS = "Columns: write how many in the block, like 3"

# The block is a thin strip of the page. Its line and its words are drawn over the room above and below it.
describe(v::ColumnsView) = Box(width(grow=grow), height(COLUMN_MARK))
cursor(::ColumnsView) = :arrow

draw(ctx, size, ui::ConcreteRect, v::ColumnsView) = begin
  v.shares === nothing || return nothing   # a block that's right shows nothing
  e = editor(v)
  face = Face(SANS, "", body(e).size * 0.62, colours.dim, false)
  x, y = num(ui.left), num(ui.top)
  rectangle(ctx, ui.left, ui.top, ui.width, 1px, background=colours.line, border=0px)
  # The words stand on the line, at its left end, with a picture of two columns before them
  side = num(face.size)
  wide = side * 1.35 + num(measure(face, COLUMN_WORDS)) + 8
  rectangle(ctx, ui.left, ui.top - px(side), px(wide), px(2side), background=colours.bg, border=0px)
  round_box(ctx, x, y - side * 0.42, side * 0.4, side * 0.84, 1.5, line=face.color)
  round_box(ctx, x + side * 0.55, y - side * 0.42, side * 0.4, side * 0.84, 1.5, line=face.color)
  write_ink(ctx, COLUMN_WORDS, x + side * 1.35, y + num(capital(face)) / 2, face)
  nothing
end

"""
The columns of the page for a page of HTML: for each group, the first line, the
last line and the share of each column. A column that the group has no block
for has no lines, and keeps its room.
"""
html_columns(e) = map(filter(g -> !isempty(g.spans), column_groups(e))) do g
  map(eachindex(g.shares)) do k
    k <= length(g.spans) || return (last(g.spans[end]) + 1, last(g.spans[end]), g.shares[k])
    (first(Columns.reach(g, k)), last(Columns.reach(g, k)), g.shares[k])
  end
end

# In a page of HTML the block itself is nothing: its columns are there
columns_html(e, v::ColumnsView) = v.shares === nothing ? nothing : ""

# The language `column` means the same as `columns`
foreach(lang -> BLOCKS[lang] = BlockKind("Columns", "columns-gap", ColumnsView, columns_html), Columns.LANGS)

# --- a list of what was found in the pages of a folder -----------------------------------------
#
# A code block in the language `find` lists the lines that match in every page
# of a folder: every to-do item that isn't ticked, say, or each line that has
# some words. find.jl says how the block is written. The list has the name of
# each page over that page's lines. A click on a line opens its page at that
# line. A click on the box of a to-do item ticks it in its own page. If that
# page isn't open, or is open with nothing to save, Ladder writes the tick to
# the page's file at once. An item that you tick stays in the list, ticked,
# until another page shows.
#
# The top of the list changes what it asks for, so the block's lines needn't
# be seen: a field for the words that a line must have, a button that opens a
# list of the kinds of thing to list, and one that opens a list of the folders
# when the page has folders beside it. Each of the two lists floats under its
# button, as the takeoff's list of units does, with a field at its top that
# searches it. The kinds are those of find.jl: the kinds of line, and each
# kind of block, which is listed by the heading that it's under. Each change
# goes into the block's lines. Under them, a line says
# what the list is of and where it looked. It counts only the lines that
# match, not the items that were ticked here.

const FIND = Searches.FIND
const FIND_MOST = 200     # the most lines that a list shows
const FIND_PAGES = 3000   # the most pages that a list reads
const FIND_EVERY = 3      # seconds between two looks at the folder, while the window is drawn
const FIND_BUDGET = 0.3   # seconds that one look at the folder can take
const FIND_BAR = 440px     # the room that the top of a list needs to show its field and its buttons in one row
const FIND_MENU = :find_choices   # the key of the list that a button at the top opens
const MOST_CHOICES = 8     # the rows that such a list shows before it scrolls
push!(BLOCK_ICONS, "search", "file-earmark-text", "folder", "code-slash")

"What a `find` block shows: the lines of a folder's pages that match"
@def mutable struct SearchView <: SemanticUI
  n::Int = 0                               # its place among the page's lists
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Searches.Query = Searches.Query()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # what the list was last worked out for, and what it found
  kept::Vector{Searches.Match} = Searches.Match[]   # the items whose box was clicked here. They stay in the list.
  pages::Dict{String,Any} = Dict{String,Any}()      # what was found in each page, and the mark of the page's text then
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its rows, kept between frames
  asking::Any = nothing                    # what the list that floats under a button chooses: :kind or :folder, or nothing when none shows
  rows::Vector{Any} = Any[]                # the rows of that list that have the words in its field
  pick::Int = 1                            # the row of them that Return takes
  typed::String = ""                       # the words in its field when the rows were last worked out
  back::Bool = false                       # the field for the words to find had the keyboard when it opened, and gets it back
end

"""
A button at the top of a list that shows what the list asks for now. A click
opens a list of the others. One chooses the kind of thing that the list is
of, and one chooses the folder that it looks in.
"""
@def mutable struct SearchChoice <: SemanticUI
  of::Any = nothing     # the list
  what::Symbol = :kind  # :kind or :folder
end
"The list that floats under such a button, with a field that searches it. It's the takeoff's list of units, with other rows."
@def mutable struct ChoiceMenu <: SemanticUI
  of::Any = nothing        # the list that it changes
  button::Any = nothing    # the button that it's under
  side::Symbol = :bottom   # the side of the button that it's on
  pick::Int = 0            # the row that was picked when it was last drawn. A row that the keys pick is brought in sight.
end
"A row of that list: a kind of thing to list, or a folder"
@def mutable struct ChoiceRow <: SemanticUI
  of::Any = nothing
  k::Int = 0
end

"The name of a page, over the lines of that page in the list"
@def mutable struct SearchPage <: SemanticUI
  of::Any = nothing
  path::String = ""
end
"A line of the list"
@def mutable struct SearchRow <: SemanticUI
  of::Any = nothing
  i::Int = 0
  box::Any = nothing   # its SearchTick
end
"The box of a to-do item in the list. A click ticks the item in its own page."
@def mutable struct SearchTick <: SemanticUI
  of::Any = nothing    # the row
end

"The text field at the top of a list. It holds the words that a line must have."
search_input(v::SearchView) = block_part!(v, :input) do
  TextInput(placeholder="Words to find", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::SearchView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Searches.query(lines)
  v.shown = nothing
  empty!(v.pages)
  # The field shows the words that the block has, as it does after ⌘Z takes some of them back.
  # A space that was just typed after a word stays in the field.
  i = search_input(v)
  split(i.text) == v.data.with || (i.text = join(v.data.with, " "); i.anchor = i.cursor = length(i.text))
  v
end

"Write what the list asks for into the lines of its block, and work the list out again"
ask!(v::SearchView; typing=false) = begin
  v.shown = nothing
  empty!(v.pages)
  write_block!(v, FIND, Searches.written(v.data); typing)
end

"""
What happens to a list in each frame, before the page is laid out: the words
that were typed in its field are written into its block. The words make the
list shorter. They don't change the kind of line that it lists.
"""
block_tick!(v::SearchView) = begin
  choosing_tick!(v)
  words = String.(split(search_input(v).text))
  q = v.data
  words == q.with && return v
  q.what === nothing && (q.what = Searches.kind(q))
  q.with = words
  ask!(v, typing=true)
end

"The folders that the list can look in: the folders beside the page, and the one that the block names now"
search_folders(v::SearchView) = begin
  dir = docdir(editor(v))
  found = isdir(dir) ? sort!([f for f in readdir(dir) if !startswith(f, '.') && f != "node_modules" && isdir(joinpath(dir, f))], by=lowercase) : String[]
  folder = v.data.folder
  isempty(folder) || folder in found || pushfirst!(found, folder)
  found
end

"Look in the folder `name` beside the page, or in the page's own folder when `name` is empty"
look_in!(v::SearchView, name) = (v.data.folder = String(name); ask!(v))

"List things of the kind `kind`, one of the kinds of find.jl, like :todo or :takeoff"
list_kind!(v::SearchView, kind) = (v.data.what = kind; ask!(v))

"What the button `c` says: the kind of thing that its list is of now, or the folder that the list looks in"
choice_words(c::SearchChoice) = begin
  q = c.of.data
  c.what == :folder ? (isempty(q.folder) ? "This folder" : q.folder) : Searches.title(Searches.kind(q))
end

describe(c::SearchChoice) =
  Row(height(26px), padding(9px, 0px), child_gap=6px, radius(6px), Alignment.Center, name="Menu",
      border(1px, :solid, c.of.asking == c.what ? colours.accent : colours.line), background(ishovered(c) ? colours.hover : colours.bg),
    (c.what == :folder ? (Icon("folder", size=13px, color=colours.dim),) : ())...,
    Box(label(choice_words(c), 12px)), Icon("chevron-down", size=9px, color=colours.dim))

cursor(::SearchChoice) = :hand
onkey(c::SearchChoice, ev::KeyPress{Keys.mouse_left}) = open_choices!(c, ev.window)

# --- the list that a button at the top opens -----------------------------------------------
#
# A click on a button shows its list under it: every kind of thing that a
# `find` block can list, or the page's own folder and the folders beside it.
# The keyboard goes to the field at the top of the list, and the list keeps
# the rows that have every word typed there. A kind is found by any of the
# names that a block can give it, so "tasks" finds To-do items. The up and
# down arrows pick a row, and so does the mouse. Return or a click takes it.
# Esc, or a click somewhere else, closes the list and changes nothing.

"The field at the top of the list that a button opens"
choice_input(v::SearchView) = block_part!(v, :filter) do
  TextInput(placeholder="Filter…", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"""
Every row of the list that the button for `what` opens. A row has its `key`,
which is the kind or the folder that goes into the block, the `name` that it
shows, and the `words` that find it.
"""
choice_rows(v::SearchView, what::Symbol) = begin
  what == :kind && return Any[(key=k, name=Searches.title(k), words=[Searches.WHATS[k].names..., Searches.WHATS[k].langs...]) for k in keys(Searches.WHATS)]
  Any[(key="", name="This folder", words=["this folder"]); [(key=f, name=f, words=[f]) for f in search_folders(v)]]
end

"True when the row `r` has every one of the words in `typed`"
choice_matches(r, typed::AbstractString) = all(w -> any(h -> occursin(w, lowercase(h)), r.words), split(lowercase(typed)))

"True when the row `r` is what the list of `v` asks for now"
chosen(v::SearchView, r) = r.key isa Symbol ? r.key == Searches.kind(v.data) : r.key == v.data.folder

"Show the list of the button `c` under it, with the keyboard in its field"
open_choices!(c::SearchChoice, window) = begin
  v = c.of
  stop_choosing!(v)
  input = choice_input(v)
  input.color = colours.ink
  input.text = ""
  input.anchor = input.cursor = 0
  v.back = window.focus === search_input(v)
  v.asking, v.typed = c.what, ""
  v.rows = choice_rows(v, c.what)
  v.pick = something(findfirst(r -> chosen(v, r), v.rows), 1)
  focus(input)
  menu = ChoiceMenu(of=v, button=c)
  v.parts[:menu] = menu
  popup!(window, menu, anchor=c, placement=:bottom, gap=9px, width=230px, key=FIND_MENU,
         onclose=() -> stop_choosing!(v), theme=component_theme(editor(v).zoom))
  handled
end

"Take the list of a button away. The keyboard goes back to the field that had it, or to the page."
stop_choosing!(v::SearchView) = begin
  v.asking === nothing && return handled
  v.asking = nothing
  v.rows = Any[]
  w = window_of(v)
  w === nothing && return handled
  close_popup!(w, FIND_MENU)
  w.focus === choice_input(v) && focus(v.back ? search_input(v) : editor(v))
  handled
end

"Take row `k` of the list that shows: the list of `v` is of that kind, or it looks in that folder"
choose!(v::SearchView, k::Int) = begin
  (v.asking !== nothing && k in eachindex(v.rows)) || return stop_choosing!(v)
  what, key = v.asking, v.rows[k].key
  stop_choosing!(v)
  what == :kind ? list_kind!(v, key) : look_in!(v, key)
  handled
end

"""
What happens in each frame to the list that a button opened: it closes when a
click somewhere else took the keyboard from its field, and it keeps the rows
that have the words in the field. New words pick the row whose name starts
with them, or the first row.
"""
choosing_tick!(v::SearchView) = begin
  v.asking === nothing && return
  w = window_of(v)
  (w === nothing || w.focus !== choice_input(v)) && return stop_choosing!(v)
  typed = String(strip(choice_input(v).text))
  typed == v.typed && return
  v.typed = typed
  v.rows = filter!(r -> choice_matches(r, typed), choice_rows(v, v.asking))
  v.pick = something(findfirst(r -> startswith(lowercase(r.name), lowercase(typed)), v.rows), 1)
end

describe(r::ChoiceRow) = begin
  v = r.of
  r.k <= length(v.rows) || return Box(height(0px))
  row = v.rows[r.k]
  float_row(row.name, picked=v.pick == r.k, on=chosen(v, row))
end

cursor(::ChoiceRow) = :hand
onkey(r::ChoiceRow, ::KeyPress{Keys.mouse_left}) = choose!(r.of, r.k)
# The mouse picks the row that it's over, as the arrow keys do
onmouse(r::ChoiceRow, ::MouseMove) = begin
  v = r.of
  v.pick = r.k
  menu = get(v.parts, :menu, nothing)
  menu === nothing || (menu.pick = r.k)   # it's in sight already, so the list doesn't scroll to it
  handled
end

describe(m::ChoiceMenu) = begin
  v = m.of
  n, high = length(v.rows), FLOAT_ROW
  scroll = get!(() -> Scroll(width(grow=grow)), v.parts, :choice_scroll)
  body = if n == 0
    float_none(v.asking == :folder ? "No folder has that name" : "Nothing has that name")
  else
    # Half a row at the bottom says that the list goes on
    scroll.height = height(n <= MOST_CHOICES ? n * high : MOST_CHOICES * high - high / 2)
    m.pick == v.pick || (m.pick = v.pick; scroll_into_view!(scroll, high * (v.pick - 1), high * v.pick))
    reuse!(scroll, Column(width(grow=grow), Alignment.Start, [block_part!(() -> ChoiceRow(of=v, k=k), v, (:choice_row, k)) for k in 1:n]...))
  end
  float_list(choice_input(v), body, name="Choices")
end

placed!(m::ChoiceMenu, side) = (m.side = side; nothing)
draw(ctx, size, ui::ConcreteRect, m::ChoiceMenu) = caret(ctx, ui, m.side, rect(m.button))

# The list sees a key before its field does. The arrows pick a row, Return takes it, and Esc closes the list.
onkey(m::ChoiceMenu, ::KeyPress{Keys.enter}) = choose!(m.of, m.of.pick)
onkey(m::ChoiceMenu, ::KeyPress{Keys.escape}) = stop_choosing!(m.of)
onkey(m::ChoiceMenu, ::KeyPress{Keys.down}) = (v = m.of; v.pick = min(v.pick + 1, max(1, length(v.rows))); handled)
onkey(m::ChoiceMenu, ::KeyPress{Keys.up}) = (v = m.of; v.pick = max(v.pick - 1, 1); handled)

# Return in the field gives the keyboard back to the page
onkey(v::SearchView, ::KeyPress{Keys.enter}) = (focus(editor(v)); handled)

"""
The Markdown files in `folder`, then those of each folder in it, in the order
of their names, and whether that's all of them. A folder whose name starts
with a dot is left out. A folder with a great many files in it, like a whole
disk, is read for a part of a second only, so that the window doesn't stop.
"""
pages_under(folder; budget=FIND_BUDGET) = begin
  out, whole, started = String[], true, time()
  for (root, dirs, files) in walkdir(folder, onerror=_ -> nothing)
    filter!(d -> !startswith(d, '.') && d != "node_modules", dirs)
    sort!(dirs, by=lowercase)
    append!(out, (joinpath(root, f) for f in sort(files, by=lowercase) if ismarkdown(f) && !startswith(f, '.')))
    (length(out) > FIND_PAGES || time() - started > budget) && (whole = false; break)
  end
  first(out, FIND_PAGES), whole
end

# What each folder that a list looks in held when it was last read: its pages, with when each file last changed
const FOLDER_PAGES = Dict{String,Any}()

"""
The pages of `folder`, with when the file of each last changed. The folder is
read again after a few seconds, and after longer when reading it takes long.
"""
folder_pages(folder) = begin
  kept = get(FOLDER_PAGES, folder, nothing)
  kept !== nothing && time() < kept.next && return kept
  started = time()
  pages, whole = pages_under(folder)
  found = [(path, mtime(path)) for path in pages]
  FOLDER_PAGES[folder] = (next=time() + max(FIND_EVERY, 20 * (time() - started)), read=started, pages=found, whole=whole)
end

# The text of each page that a list has read, with when the file last changed, so a file is read again only when it changes
const PAGE_TEXTS = Dict{String,Tuple{Float64,Vector{String},Vector{Line}}}()

"""
The lines of the page at `path`, what each line is, and a mark that changes
when the page's text does. A page that's open gives its text as it is now,
with the changes that aren't saved. `at` is when the page's file last changed.
"""
page_text(e, path, at) = begin
  b = get(e.buffers, path, nothing)
  b !== nothing && !readonly(b) && return b.lines, kinds(b), (:open, b.version)
  kept = get(PAGE_TEXTS, path, nothing)
  kept !== nothing && kept[1] == at && return kept[2], kept[3], at
  lines = filesize(path) > 2_000_000 ? String[] : try text(path) catch; String[] end
  length(PAGE_TEXTS) > 2FIND_PAGES && empty!(PAGE_TEXTS)
  PAGE_TEXTS[path] = (at, lines, classify(lines))
  lines, PAGE_TEXTS[path][3], at
end

"The folder that the list looks in"
search_folder(e, q::Searches.Query) = isempty(q.folder) ? docdir(e) : abspath(joinpath(docdir(e), expanduser(q.folder)))

"""
What the list shows: the lines that match, page by page, whether every page of
the folder was read, and why there are no lines when the folder can't be read.
It's worked out again when a page changes in Ladder, and when the folder is
read again. Only the pages that changed are looked through again.
"""
found!(v::SearchView) = begin
  e = editor(v)
  q = v.data
  folder = search_folder(e, q)
  listed = isdir(folder) ? folder_pages(folder) : nothing
  # ⌘Z gives a page the version that it had before, so the version of each open page is looked at, not only the newest one
  key = (v.lines, hash([b.version for b in values(e.buffers)]), listed === nothing ? 0.0 : listed.read, folder, length(v.kept))
  v.shown !== nothing && v.shown[1] == key && return v.shown[2]
  listed === nothing && return (v.shown = (key, (matches=Searches.Match[], whole=true, problem="There's no folder called “$(q.folder)” beside this page.")))[2]
  every, kept = Searches.Match[], Searches.Match[]
  for (path, at) in listed.pages
    lines, ks, mark = page_text(e, path, at)
    had = get(v.pages, path, nothing)
    ms = had !== nothing && had[1] == mark ? had[2] : (v.pages[path] = (mark, Searches.matches(q, path, lines, ks)))[2]
    # An item whose box was clicked here stays in the list, though it no longer matches
    for k in v.kept
      k.path == path || continue
      i = Searches.locate(k, lines, ks)
      i === nothing && continue
      push!(kept, Searches.Match(path, i, k.text, k.kind))
      any(m -> m.line == i, ms) || (ms = sort!([ms; kept[end]], by=m -> m.line))
    end
    append!(every, ms)
  end
  v.kept = kept
  key = (key[1:4]..., length(v.kept))
  (v.shown = (key, (matches=every, whole=listed.whole, problem="")))[2]
end

"The name of the page at `path` as the list shows it: where it is in the list's folder, without the end of its file's name"
page_name(v::SearchView, path) = splitext(relpath(path, search_folder(editor(v), v.data)))[1]

describe(p::SearchPage) =
  Row(width(grow=grow), height(30px), padding(12px, 0px), child_gap=7px, Alignment.Center, name="Page",
    Icon("file-earmark-text", size=13px, color=colours.dim),
    Box(label(page_name(p.of, p.path), 12.5px, color=ishovered(p) ? colours.accent : colours.ink, weight="Semibold")), Box(width(grow=grow)))

describe(t::SearchTick) = begin
  row = t.of
  ms = found!(row.of).matches
  done = row.i <= length(ms) && ms[row.i].kind == :done
  side = 15px
  Box(fixed(side), height(side), radius(4px), Alignment.Center, justify=Alignment.Center,
      (done ? (background(colours.accent),) : (border(1.5px, :solid, ishovered(t) ? colours.accent : colours.marker),))...,
      (done ? (Icon("check", size=13px, color=colours.bg),) : ())...)
end

describe(r::SearchRow) = begin
  ms = found!(r.of).matches
  r.i <= length(ms) || return Box(height(0px))
  m = ms[r.i]
  r.box === nothing && (r.box = SearchTick(of=r); setfield!(r.box, :parent, r))
  boxed = m.kind in (:todo, :done)
  Row(width(grow=grow), padding(4px, 12px, 4px, 31px), child_gap=9px, Alignment.Start, name="Found", background(ishovered(r) ? colours.hover : clear),
    (boxed ? (Box(padding(0px, 1px, 0px, 0px), r.box),) : ())...,
    # A block has the icon of its kind, as it has in the sidebar
    (Searches.isblock(m.kind) ? (Box(padding(0px, 2px, 0px, 0px), Icon(block_icon(m.kind), size=13px, color=colours.dim)),) : ())...,
    Box(width(grow=grow), Text(m.text, size=13.5px, family=SANS, subfamily=m.kind == :heading ? "Semibold" : "",
                               color=m.kind == :done ? colours.dim : colours.ink, wrap=WrapMode.words)))
end

cursor(::Union{SearchPage,SearchRow,SearchTick}) = :hand
cursor(::SearchView) = :arrow

"The icon of the kind of block `kind`, one of the kinds of find.jl. It's the one that the sidebar shows beside such a block."
block_icon(kind::Symbol) = begin
  kind == :code && return "code-slash"
  lang = first(Searches.WHATS[kind].langs)
  lang == TAKEOFF ? "rulers" : lang == SCHEDULE ? "bar-chart-steps" : lang == SHEET ? "calculator" : lang == SPREADSHEET ? "grid-3x3" :
  lang == DIAGRAM ? "diagram-3" : haskey(BLOCKS, lang) ? BLOCKS[lang].icon : "puzzle"
end

"""
Show the page at `path`, with the caret at the end of the line that `m` is on
now. For a block that shows as a component, the caret goes to the line under
it: in the block, it would show the block's lines.
"""
visit!(e, path, m=nothing) = begin
  path == e.buf.path || open!(e, path)
  focus(e)
  m === nothing && return handled
  b = e.buf
  i = Searches.locate(m, b.lines, kinds(b))
  i === nothing && return handled
  Searches.isblock(m.kind) || return show_line!(e, i)
  under = last(Searches.block_span(kinds(b), i)) + 2
  show_line!(e, m.kind == :code ? min(i + 1, length(b.lines)) : min(under, length(b.lines)))
end

onkey(p::SearchPage, ::KeyPress{Keys.mouse_left}) = visit!(editor(p.of), p.path)
onkey(r::SearchRow, ::KeyPress{Keys.mouse_left}) = begin
  ms = found!(r.of).matches
  r.i <= length(ms) ? visit!(editor(r.of), ms[r.i].path, ms[r.i]) : handled
end

"""
Tick the to-do item `m` in its own page, or take its tick away. A page that's
open is changed as if you'd clicked the box there. If it isn't the page that
shows, and it had nothing to save, it's saved. A page that isn't open is
changed in its file.
"""
tick_found!(v::SearchView, m::Searches.Match) = begin
  e = editor(v)
  done = m.kind != :done
  b = get(e.buffers, m.path, nothing)
  if b !== nothing && !readonly(b)
    i = Searches.locate(m, b.lines, kinds(b))
    i === nothing && return handled
    clean = !dirty(b)
    caret, anchor = b.caret, b.anchor
    col = findfirst('[', b.lines[i])
    edit!(b, (i, col), (i, col + 1), done ? "x" : " ")
    b.caret, b.anchor = caret, anchor
    b !== e.buf && clean && save!(b)
  else
    isfile(m.path) || return handled
    lines = text(m.path)
    i = Searches.locate(m, lines)
    i === nothing && return handled
    lines[i] = Searches.ticked(lines[i], done)
    # A file that can't be written, like one of the pages that come with the app, stays as it is
    try write(m.path, join(lines, "\n")) catch; return handled end
    empty!(FOLDER_PAGES)   # the folder is read again, so that the list has the file as it is now
  end
  # The item stays in this list. A second click, which puts it back as it was, lets it go.
  now = Searches.Match(m.path, m.line, m.text, done ? :done : :todo)
  k = findfirst(x -> x.path == m.path && x.text == m.text && x.kind == m.kind, v.kept)
  k === nothing ? push!(v.kept, now) : (v.kept[k] = now)
  Searches.kind(v.data) == now.kind && filter!(x -> !(x.path == now.path && x.text == now.text), v.kept)
  v.shown = nothing
  handled
end

"The lists of the page that shows let go of the items that were ticked in them. `open!` does this when another page takes its place."
forget_ticked!(e) = for (key, v) in e.nodes
  v isa SearchView && key[3] == e.buf.path && !isempty(v.kept) && (empty!(v.kept); v.shown = nothing)
end

onkey(t::SearchTick, ::KeyPress{Keys.mouse_left}) = begin
  row = t.of
  ms = found!(row.of).matches
  row.i <= length(ms) ? tick_found!(row.of, ms[row.i]) : handled
end

"""
What the top of the list says: what it lists, how many lines match and where
it looks. An item that was ticked here stays in the list, but it no longer
matches, so it isn't counted.
"""
search_words(v::SearchView) = begin
  q = v.data
  own = [m for m in found!(v).matches if Searches.counted(q, m)]
  Searches.summary(q, length(own), length(unique(m.path for m in own)))
end

describe(v::SearchView) = begin
  e = editor(v)
  found = found!(v)
  ms = found.matches
  q = v.data
  with_theme(component_theme(e.zoom)) do
    input = search_input(v)
    input.color = colours.ink
    w = window_of(v)
    typing = w !== nothing && w.focus === input
    field = Row(width(grow=grow), height(26px), padding(8px, 0px), child_gap=7px, radius(6px), Alignment.Center, background(colours.bg),
                border(1px, :solid, typing ? colours.accent : colours.line),
                Icon("search", size=12px, color=colours.dim), Box(width(grow=grow), height(grow=grow), input))
    # The button for the folder shows only when there's another folder to choose
    menus = (block_part!(() -> SearchChoice(of=v, what=:kind), v, :kind),
             (isempty(search_folders(v)) ? () : (block_part!(() -> SearchChoice(of=v, what=:folder), v, :folder),))...)
    gap() = Box(width(4px))   # a new one each time: a box can be in the page only once
    bars = editor(v).width < FIND_BAR ?
           (block_bar(field), block_bar(menus[1], gap(), menus[2:end]..., Box(width(grow=grow)))) :
           (block_bar(field, gap(), menus[1], gap(), menus[2:end]...),)
    total = Row(width(grow=grow), padding(9px, 12px, 3px, 12px), Alignment.Start, Box(label(search_words(v), 12px, color=colours.dim)), Box(width(grow=grow)))
    isempty(found.problem) || return Column(block_look()..., clip=true, name="Found", bars..., block_note(found.problem))
    rows = Any[total]
    pages = 0
    for i in 1:min(length(ms), FIND_MOST)
      if i == 1 || ms[i-1].path != ms[i].path
        page = block_part!(() -> SearchPage(of=v), v, (:page, pages += 1))
        page.path = ms[i].path
        push!(rows, page)
      end
      push!(rows, block_part!(() -> SearchRow(of=v, i=i), v, (:row, i)))
    end
    length(ms) > FIND_MOST && push!(rows, block_note("And $(length(ms) - FIND_MOST) more. Add words to the block's with: line to list fewer."))
    found.whole || push!(rows, block_note("This folder has more pages than Ladder reads for a list. Name a folder in it with the block's in: line."))
    Column(block_look()..., clip=true, name="Found", bars..., rows..., Box(height(6px)))
  end
end

"The list as HTML: the name of each page, and its lines under it"
find_html(e, v::SearchView) = begin
  ms = found!(v).matches
  isempty(ms) && return "<p>$(escape(Searches.summary(v.data, 0, 0)))</p>"
  out = String[]
  for (i, m) in enumerate(ms)
    if i == 1 || ms[i-1].path != m.path
      i == 1 || push!(out, "</ul>")
      push!(out, "<p><strong>$(escape(page_name(v, m.path)))</strong></p>\n<ul style=\"list-style: none; padding-left: 0.5em\">")
    end
    push!(out, "<li>$(m.kind == :done ? "☑ " : m.kind == :todo ? "☐ " : "")$(escape(m.text))</li>")
  end
  join(out, "\n") * "\n</ul>"
end

BLOCKS[FIND] = BlockKind("Find", "search", SearchView, find_html)

# --- a gallery of a folder's pictures ----------------------------------------------------------
#
# A code block in the language `gallery` shows the pictures of a folder as a
# grid of small squares. gallery.jl says how the block is written. A square
# shows the middle of its picture, cut to fit. The top of the block says how
# many pictures there are and where they are. A button there changes the size
# of the squares, and writes the size into the block.
#
#   - A click on a picture makes it fill the window, as a picture in the text
#     does. There, ← and → go to the picture before it and the next one of
#     the gallery, and Esc puts the page back.
#   - While it fills the window, the bar under it says where it is in the
#     gallery, like "2 of 6", and the name of its file. A button on each side
#     of those words goes to the picture before and to the next one. While
#     the mouse is near the left or the right edge of the window, a large
#     arrow shows there that does the same.
#   - The mouse over a picture shows the name of its file.
#   - A picture that's dropped on the gallery from the Finder is copied into
#     the gallery's folder. A gallery that only lists its pictures gets a
#     line for the picture, and the file stays where it is.
#
# A big folder mustn't stop the window. macOS makes a small picture of each
# file, as it does for the Finder, and Ladder asks for a few of them in each
# frame. Only the rows of the grid that are in the window are built. The
# folder is read again every few seconds while the window is drawn.

const GALLERY = Galleries.GALLERY
const GALLERY_KINDS = (PICTURES..., MAC_PICTURES...)   # the ends of the names of the files that a gallery shows
const GALLERY_EVERY = 3        # seconds between two looks at the folder, while the window is drawn
const GALLERY_BUDGET = 0.012   # seconds of a frame that making small pictures can take. One is always made.
const GALLERY_TOP = 38px       # how tall the line at the top of a gallery is
const GALLERY_PAD = 12px       # between the edge of a gallery and its pictures
const GALLERY_ROUND = 6px      # how round the corners of a square are
const GALLERY_EDGE = 44px      # how big the arrow is at an edge of the window, while a picture fills the window
const GALLERY_NEAR = 140       # px: the mouse is this near an edge of the window when that edge's arrow shows
const GALLERY_NAME = 200       # px: the most room that the name of a file has in the bar under a picture
"For each size of square: the icon of the button that changes the size, and what the button says"
const GALLERY_SIZES = (small=("grid-3x3-gap", "Small"), medium=("grid", "Medium"), large=("square", "Large"))
push!(BLOCK_ICONS, "images", "image", "grid-3x3-gap", "grid", "square")

"What a `gallery` block shows: the pictures of a folder as a grid of squares"
@def mutable struct GalleryView <: SemanticUI
  n::Int = 0                               # its place among the page's galleries
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Galleries.Gallery = Galleries.Gallery()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # what the gallery showed when its folder was last read, and when to read it again
  small::Dict{Any,Any} = Dict{Any,Any}()   # the key of the small picture of each file, or nothing for a file that has none
  wanted::Vector{Galleries.Picture} = Galleries.Picture[]   # the pictures in the window whose small pictures aren't made yet
  side::px = 0px                           # how big each square was when the grid was last laid out
  showing::String = ""                     # the file of the picture that fills the window, or that last did
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its squares and its button, kept between frames
end

"A square of a gallery: one picture"
@def mutable struct GalleryThumb <: SemanticUI
  of::Any = nothing
  i::Int = 0   # its place among the gallery's pictures
end

reread!(v::GalleryView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Galleries.gallery(lines)
  v.shown = nothing
  v
end

"True while the page is drawn for paper. `print_pdf` puts the caret on no line then."
on_paper(e) = e.buf.caret[1] == 0

"""
What the gallery shows: its pictures, the lines that name no picture, and why
there are no pictures. The folder is read again after a few seconds, and after
longer when reading it takes long.
"""
found!(v::GalleryView) = begin
  dir = docdir(editor(v))
  key = (v.lines, dir)
  s = v.shown
  s !== nothing && s.key == key && time() < s.next && return s.found
  started = time()
  found = Galleries.pictures(v.data, dir, kinds=GALLERY_KINDS)
  v.shown = (key=key, next=time() + max(GALLERY_EVERY, 20 * (time() - started)), found=found)
  found
end

"Picture `i` of the gallery, or nothing when it has no such picture"
picture_at(v::GalleryView, i::Int) = get(found!(v).pictures, i, nothing)

"What the small picture of `p` is kept under: its file, when the file last changed, and how many pixels the squares need now"
small_mark(v::GalleryView, p) = (p.path, p.at, Galleries.pixels(num(v.side)))

"The key, for drawing, of the small picture of `p`. It's nothing for a file that has no picture, and `missing` until it's made."
small(v::GalleryView, p) = get(v.small, small_mark(v, p), missing)

"Make the small picture of `p`: the one that macOS makes for the Finder, or the whole picture when macOS has none"
small!(v::GalleryView, p) = begin
  mark = small_mark(v, p)
  key = thumbnail(p.path, mark[3])
  v.small[mark] = key === nothing ? picture_key(p.path) : key
end

"""
Make the small pictures that the last frame had none for: as many as `budget`
seconds have room for, and one at the least. The next frame asks for the rest.
"""
make_small!(v::GalleryView; budget=GALLERY_BUDGET) = begin
  started = time()
  for p in v.wanted
    ismissing(small(v, p)) || continue
    small!(v, p)
    time() - started > budget && break
  end
  empty!(v.wanted)
  v
end

# In each frame, before the page is laid out, a gallery makes a few small pictures, so the window never waits long
block_tick!(v::GalleryView) = make_small!(v)

"""
The rows of the grid `g` that are in the window, and a few on each side of
them. On paper, every row shows.
"""
rows_in_view(v::GalleryView, g) = begin
  e = editor(v)
  on_paper(e) && return 1:g.rows
  _, h = window_size(e)
  k = findfirst(it -> it.content isa Live && it.content.node === v, e.layout)
  # A gallery that the page hasn't laid out yet is taken to be at the top of the window
  k === nothing && return Galleries.rows_between(0, num(h), g.rows, g.side)
  top = e.layout[k].top + LIVE_GAP + 1px + GALLERY_TOP   # of the grid, from the top of the page's text
  Galleries.rows_between(num(e.scroll.offset - PAGE_TOP - 200px - top), num(e.scroll.offset + h + 200px - top), g.rows, g.side)
end

describe(t::GalleryThumb) = begin
  v = t.of
  p = picture_at(v, t.i)
  # A file that has no picture to show has an icon in its square
  none = p !== nothing && small(v, p) === nothing
  Box(fixed(v.side), height(v.side), radius(GALLERY_ROUND), Alignment.Center, justify=Alignment.Center, name="Picture", background(colours.block),
      (none ? (Icon("image", size=20px, color=colours.faint),) : ())...)
end

# The square shows the middle of the small picture, cut to fit, with round corners
draw(ctx, size, ui::ConcreteRect, t::GalleryThumb) = begin
  v = t.of
  p = picture_at(v, t.i)
  p === nothing && return
  key = small(v, p)
  left, top, wide, tall = num(ui.left), num(ui.top), num(ui.width), num(ui.height)
  if key isa String
    image = image_source(key)
    with_round_clip(ctx, ui.left, ui.top, ui.width, ui.height, GALLERY_ROUND) do
      paint_picture(ctx, image.raw, Galleries.crop(image.width, image.height), (left, top, wide, tall))
    end
  end
  # The square under the mouse has a line round it
  ishovered(t) && round_box(ctx, left + 1, top + 1, wide - 2, tall - 2, num(GALLERY_ROUND) - 1; line=colours.accent, wide=2.0)
  nothing
end

cursor(::GalleryThumb) = :hand
cursor(::GalleryView) = :arrow

onmouse(t::GalleryThumb, ev::MouseMove) = begin
  p = picture_at(t.of, t.i)
  p === nothing || show_tooltip!(ev.window, tip_label(p.name), t, placement=:bottom, gap=6px)
  nothing
end

onkey(t::GalleryThumb, ev::KeyPress{Keys.mouse_left}) = (hide_tooltip!(ev.window); show_picture!(t.of, t.i))

"Make picture `i` of the gallery fill the window. A file that can't be read as a picture stays in its square."
show_picture!(v::GalleryView, i::Int) = begin
  p = picture_at(v, i)
  key = p === nothing ? nothing : picture_key(p.path)
  key === nothing && return handled
  v.showing = p.path
  zoom_in!(editor(v), (:picture, key), v)
end

"""
While a picture of the gallery fills the window, go `by` pictures on: to the
one before it, or to the next one. A file that can't be read as a picture is
passed over. At the first picture and the last, nothing changes.
"""
step!(v::GalleryView, by::Int) = begin
  pics = found!(v).pictures
  i = something(findfirst(p -> p.path == v.showing, pics), 0) + by
  while i in eachindex(pics)
    picture_key(pics[i].path) === nothing || return show_picture!(v, i)
    i += by
  end
  handled
end

"""
Where the picture that fills the window is in its gallery: the gallery, the
picture's place, how many pictures there are, and the name of its file. It's
nothing for a picture that isn't from a gallery.
"""
gallery_place(z::ZoomView) = begin
  g = z.from
  (g isa GalleryView && z.what !== nothing && z.what[1] == :picture) || return nothing
  pics = found!(g).pictures
  i = findfirst(p -> p.path == g.showing, pics)
  i === nothing ? nothing : (gallery=g, i=i, n=length(pics), name=pics[i].name)
end

"What the bar under a picture says of the picture's place, like “2 of 6”"
place_words(at) = "$(at.i) of $(at.n)"

"""
True when the gallery has a picture to show `by` pictures on from picture `i`:
one before it, or one after it. A file that's known to have no picture doesn't
count, because `step!` passes over it.
"""
can_step(v::GalleryView, i::Int, by::Int) = begin
  pics = found!(v).pictures
  any(k -> small(v, pics[k]) !== nothing, by < 0 ? (1:i-1) : (i+1:length(pics)))
end

"""
What the bar under a picture of a gallery starts with: a button for the
picture before, the picture's place, a button for the next picture, the name
of its file and a line. The bar of any other picture has none of them. In a
window that's too narrow for them all, the name goes first, and then the place.
"""
gallery_buttons(z::ZoomView) = begin
  at = gallery_place(z)
  at === nothing && return ()
  g = at.gallery
  button(key, by, icon, tip) = begin
    b = part!(() -> PlanButton(of=g), z, (:button, key))
    b.action, b.icon, b.tip, b.off = (:step, by), icon, tip, !can_step(g, at.i, by)
    b
  end
  face = Face(SANS, "", 12px, colours.dim, false)
  # The rest of the bar, with its two buttons here and the room on each side of it, is 281px wide
  spare = num(window_size(editor(z))[1]) - 281
  place = place_words(at)
  placed = num(measure(face, place)) + 8
  room = min(spare - placed - 14, GALLERY_NAME)
  words(text) = label(text, 12px, color=colours.dim)
  (button(:before, -1, "chevron-left", "The picture before  ←"),
   (spare >= placed ? (Box(Alignment.Center, padding(4px, 0px), words(place)),) : ())...,
   button(:next, 1, "chevron-right", "The next picture  →"),
   (room >= 60 ? (Box(Alignment.Center, padding(6px, 0px), words(elide(at.name, 12px, px(room)))),) : ())...,
   rule())
end

"A large arrow at the left or the right edge of the window, while a picture of a gallery fills it. A click goes to the picture before, or to the next one."
@def mutable struct GalleryEdge <: SemanticUI
  of::Any = nothing   # the gallery
  by::Int = 1         # -1 for the picture before, and 1 for the next one
end

describe(a::GalleryEdge) =
  Box(width(GALLERY_EDGE), height(GALLERY_EDGE), radius(GALLERY_EDGE / 2), Alignment.Center, justify=Alignment.Center, name="Button",
      background(ishovered(a) ? colours.hover : RGBA(colours.float, 0.85)), border(1px, :solid, colours.line),
    Icon(a.by < 0 ? "chevron-left" : "chevron-right", size=20px, color=colours.dim))

cursor(::GalleryEdge) = :hand
onkey(a::GalleryEdge, ::KeyPress{Keys.mouse_left}) = step!(a.of, a.by)

"""
The arrows at the left and the right edge of a picture of a gallery that
fills the window, in the middle of the picture's height. Each one shows while
the mouse is near its edge, and there's a picture to go to. Any other picture
has none.
"""
gallery_edges(z::ZoomView) = begin
  at = gallery_place(z)
  w = window_of(z)
  (at === nothing || w === nothing) && return ()
  wide = num(window_size(editor(z))[1])
  x, y = num(w.mouse[1]), num(w.mouse[2])
  arrow(by) = begin
    near = y > num(TOPBAR_H) && (by < 0 ? x < GALLERY_NEAR : x > wide - GALLERY_NEAR)
    near && can_step(at.gallery, at.i, by) ? part!(() -> GalleryEdge(of=at.gallery, by=by), z, (:edge, by)) : Box(width(GALLERY_EDGE))
  end
  (Row(width(grow=grow), height(grow=grow), Alignment.Center, padding(0px, 16px, BAR_ROOM, 16px), arrow(-1), Box(width(grow=grow)), arrow(1)),)
end

"""
Do what a button of a gallery does. The one at its top gives its squares the
next size, which goes into the block. The two under a picture that fills the
window go to the picture before it and to the next one.
"""
act!(v::GalleryView, action, w) = begin
  action isa Tuple && action[1] == :step && return step!(v, action[2])
  action == :size || return handled
  v.data.size = Galleries.next_size(v.data.size)
  # A page that can't be changed still shows the new size
  readonly(editor(v).buf) || write_block!(v, GALLERY, Galleries.written(v.data))
  handled
end

describe(v::GalleryView) = begin
  e = editor(v)
  found = found!(v)
  pics = found.pictures
  paper = on_paper(e)
  with_theme(component_theme(e.zoom)) do
    lost = Galleries.lost_words(found.lost)
    isempty(pics) && return Column(block_look()..., clip=true, name="Gallery", block_note(isempty(lost) ? found.problem : lost))
    icon, words = GALLERY_SIZES[v.data.size]
    bigger = lowercase(GALLERY_SIZES[Galleries.next_size(v.data.size)][2])
    top = Row(width(grow=grow), height(GALLERY_TOP), padding(0px, 6px, 0px, GALLERY_PAD), Alignment.Center, clip=true,
              Box(label(Galleries.summary(v.data, found), 12px, color=colours.dim)), Box(width(grow=grow)),
              (paper ? () : (block_button!(v, :size, :size, icon=icon, words=words, tip="Make the pictures $bigger"),))...)
    g = Galleries.grid(length(pics), num(e.width - 2px - 2GALLERY_PAD), v.data.size)
    v.side = px(g.side)
    rows = rows_in_view(v, g)
    places = [i for r in rows for i in Galleries.row_places(r, g.columns, length(pics))]
    # On paper every picture shows, so each small picture is made now. In the window, the next frames make them.
    paper && foreach(i -> ismissing(small(v, pics[i])) && small!(v, pics[i]), places)
    v.wanted = [pics[i] for i in places if ismissing(small(v, pics[i]))]
    isempty(v.wanted) || redraw_in!(v, 0)
    gap, step = px(Galleries.GAP), g.side + Galleries.GAP
    # The rows that aren't built leave their room empty, so the block is as tall as the whole grid
    above = isempty(rows) ? px(Galleries.tall(g.rows, g.side)) : px((first(rows) - 1) * step) - gap
    below = isempty(rows) ? 0px : px((g.rows - last(rows)) * step) - gap
    grid = Column(width(grow=grow), Alignment.Start, padding(0px, GALLERY_PAD, GALLERY_PAD, GALLERY_PAD), child_gap=gap,
      (above > 0px ? (Box(width(grow=grow), height(above)),) : ())...,
      [Row(height(v.side), child_gap=gap, Alignment.Start,
           [block_part!(() -> GalleryThumb(of=v, i=i), v, (:thumb, i)) for i in Galleries.row_places(r, g.columns, length(pics))]...)
       for r in rows]...,
      (below > 0px ? (Box(width(grow=grow), height(below)),) : ())...)
    # A line of the block that names no picture is named under the grid
    note = isempty(lost) ? () : (Row(width(grow=grow), padding(0px, GALLERY_PAD, GALLERY_PAD, GALLERY_PAD), Alignment.Start, clip=true,
                                     Box(width(grow=grow), Text(lost, size=12px, family=SANS, color=colours.dim, wrap=WrapMode.words))),)
    Column(block_look()..., clip=true, name="Gallery", top, grid, note...)
  end
end

"The gallery under the mouse, or nothing. Only a gallery that the page shows now is where it was last drawn."
gallery_at(e, w) = begin
  x, y = w.mouse
  for it in view(e.layout, intersect(e.shown, eachindex(e.layout)))
    node = it.content isa Live ? it.content.node : nothing
    node isa GalleryView || continue
    r = rect(node)
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return node
  end
  nothing
end

"""
Add the pictures among the files at `paths` to the gallery, as a drop on it
does. Each one is copied into the gallery's folder. A gallery that only lists
its pictures gets a line for each one, and the files stay where they are.
It's true when the gallery took a picture.
"""
add_pictures!(v::GalleryView, paths) = begin
  e = editor(v)
  dir = docdir(e)
  new = [rstrip(String(p), '/') for p in paths]
  filter!(p -> isfile(p) && Galleries.ispicture(p, GALLERY_KINDS), new)
  (isempty(new) || readonly(e.buf) || !isdir(dir)) && return false
  to = Galleries.folder(v.data, dir)
  if to === nothing
    append!(v.data.listed, unique(name for name in (named(e, p) for p in new) if !(name in v.data.listed)))
    write_block!(v, GALLERY, Galleries.written(v.data))
  else
    foreach(p -> Galleries.keep(to, p), new)
    list_files!(e)   # the sidebar lists the new files too
  end
  v.shown = nothing
  true
end

"The gallery as HTML: a grid of its pictures, each one named as a picture in the text names its file"
gallery_html(e, v::GalleryView) = begin
  found = found!(v)
  isempty(found.pictures) && return "<p>$(escape(isempty(found.lost) ? found.problem : Galleries.lost_words(found.lost)))</p>"
  look = "width: 100%; aspect-ratio: 1; object-fit: cover; border-radius: $(round(Int, num(GALLERY_ROUND)))px"
  pictures = join(("<img src=\"$(escape(escaped(named(e, p.path))))\" alt=\"$(escape(splitext(p.name)[1]))\" loading=\"lazy\" style=\"$look\">" for p in found.pictures), "\n")
  "<div class=\"gallery\" style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax($(Galleries.SIDES[v.data.size])px, 1fr)); gap: $(Galleries.GAP)px\">\n$pictures\n</div>"
end

BLOCKS[GALLERY] = BlockKind("Gallery", "images", GalleryView, gallery_html)

# --- a sketch ---------------------------------------------------------------------------------
#
# A code block in the language `sketch` is a drawing. sketch.jl says how the
# block is written. In the page it shows only the drawing. A click on it, a
# pinch outwards, or the button that shows beside its top right corner while
# the mouse is over it, makes it fill the window. Only there does it have its
# tools. The buttons at its top choose a tool: the arrow selects a shape, and
# the others draw by hand, a line, an arrow, a box, an oval or words. The dots
# after them choose the colour of the next shape, or of the shape that's
# selected.
#
#   - Drag in the sketch to draw with the tool. For words, click where they
#     go and type them there. Return, or a click somewhere else, adds them,
#     and Esc leaves them out.
#   - Click words twice with the arrow, or once with the tool for words, to
#     change them where they are. Esc leaves them as they were, and words
#     with nothing left in them are taken away.
#   - With the arrow, click a shape to select it, and drag it to move it.
#     Delete takes the selected shape away.
#   - The shape that's selected glows, and has a circle on each place that
#     changes it: the ends of a line, each place of a line drawn by hand, the
#     corners of a box and the middle of each side of an oval. Drag a circle
#     to move that place.
#   - After the dots come the numbers that say how a shape is drawn: how thick
#     its line is, how round the corners of a box are, and how big words are.
#     The buttons each side of a number change it, for the shape that's
#     selected, or for the shapes that the tool draws next. Click a number
#     to type another, and press Return.
#   - The sketch gets taller when a shape is near its bottom edge.
#   - Esc chooses the arrow tool, and Esc with that tool puts the sketch
#     back in the page. So does the last button.
#
# Each shape is a line of the block, so the file holds the whole drawing, and
# ⌘Z takes back the last thing you drew.

const SKETCH = Sketches.SKETCH
"The tools of a sketch: the icon of each one's button, and what the button's tooltip says"
const SKETCH_TOOLS = ((:select, "cursor", "Select a shape, and drag it to move it"), (:pen, "pencil", "Draw by hand"),
                      (:line, "slash-lg", "Draw a line"), (:arrow, "arrow-up-right", "Draw an arrow"), (:box, "square", "Draw a box"),
                      (:oval, "circle", "Draw an oval"), (:text, "type", "Write words: click where they go, and type them there"))
push!(BLOCK_ICONS, "pencil", "slash-lg", "arrow-up-right", "square", "circle", "type", "trash", "cursor",
      "border-width", "fonts", "dash", "plus", "arrows-fullscreen", "fullscreen-exit")
"""
For each part of how a shape is drawn: its icon at the top of a sketch, what
the tooltips of its two buttons say, and how much one click changes it.
"""
const SKETCH_SETTINGS = (width=("border-width", "Make the line thinner", "Make the line thicker", 0.5),
                         radius=("round-corner", "Make the corners less round", "Make the corners rounder", 1.0),
                         size=("fonts", "Make the words smaller", "Make the words bigger", 1.0))
const SKETCH_BAR = 646px   # the room that the top of a sketch needs to show everything in one row
const HANDLE = 4.5         # px: the radius of the circle on a place of the selected shape
const HANDLE_REACH = 8.0   # px: how near the mouse is to a circle to drag it

# UI.jl has no icon for a round corner. This is one, in a square 16 wide: a line that turns a corner.
const ROUND_CORNER = "M1.75 14L1.75 8A6.25 6.25 0 0 1 8 1.75L14 1.75A0.75 0.75 0 0 1 14 3.25L8 3.25A4.75 4.75 0 0 0 3.25 8L3.25 14A0.75 0.75 0 0 1 1.75 14Z"

"The name of an icon at the top of a sketch. The round corner goes among UI.jl's icons the first time that it's asked for."
sketch_icon(name) = begin
  name == "round-corner" || return name
  kept = get(icon_cache, name, nothing)
  (kept === nothing || first(kept.paths).d != ROUND_CORNER) && (icon_cache[name] = (paths=[SVGPath(d=ROUND_CORNER)], viewbox=(0f0, 0f0, 16f0, 16f0)))
  name
end

"What a `sketch` block shows: a drawing, and the tools that draw it"
@def mutable struct SketchView <: SemanticUI
  n::Int = 0                               # its place among the page's sketches
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Sketches.Sketch = Sketches.Sketch()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  tool::Symbol = :pen
  colour::Symbol = :ink                    # the colour of the next shape
  # How the next shape is drawn: how thick its line is, how round the corners of a box are, and how big words are
  next::Dict{Symbol,Float64} = Dict(:width => Sketches.WIDTH, :radius => Sketches.RADIUS, :size => Sketches.TEXT_SIZE)
  draft::Any = nothing                     # the shape that's being drawn, or nothing
  picked::Int = 0                          # the place of the shape that's selected, or 0
  # A drag of the selected shape: where the mouse was last, whether the shape has changed, and the number of
  # the circle that's dragged, or 0 when the whole shape is
  grab::Any = nothing
  asking::Any = nothing                    # the place in the drawing where words are being typed, or nothing
  editing::Int = 0                         # the place among the shapes of the words that are being changed, or 0 when the words are new
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where the drawing was last clicked
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the drawing was last drawn in the window
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons and its text field, kept between frames
  typing::Any = nothing                    # the part of how a shape is drawn whose number has the keyboard, like `:width`, or nothing
  full::Bool = false                       # it fills the window, over the page
  tall::px = 0px                           # how tall it was in the page when it was last laid out there
  pinned::px = 0px                         # how far the page was scrolled when it filled the window
end

"The part of a sketch that's drawn in"
@def mutable struct SketchArea <: SemanticUI
  of::Any = nothing
end
"A dot in the top of a sketch that chooses a colour"
@def mutable struct InkDot <: SemanticUI
  of::Any = nothing
  colour::Symbol = :ink
end

reread!(v::SketchView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Sketches.sketch(lines)
  v.picked = min(v.picked, length(v.data.shapes))
  v
end

"The colour that a sketch draws the colour called `name` in"
sketch_colour(name::Symbol) = begin
  cs = series_colours()
  name == :red ? cs[8] : name == :blue ? cs[1] : name == :green ? cs[6] : name == :orange ? cs[2] : colours.ink
end

sketch_area(v::SketchView) = block_part!(() -> SketchArea(of=v), v, :area)

"""
The text field that holds the words that are being typed into the drawing. It
has the keyboard while they're typed, and it isn't shown: the drawing shows
its words where they will be.
"""
sketch_input(v::SketchView) = block_part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"How much room the sketch has from side to side: the page's text, or the window when it fills the window"
sketch_room(v::SketchView) = v.full ? window_size(editor(v))[1] : editor(v).width

"How many px of the window one of the sketch's own measure is"
sketch_scale(v::SketchView) = v.box[3] > 0 ? v.box[3] / Sketches.WIDE : num(sketch_room(v) - (v.full ? 0px : 2px)) / Sketches.WIDE

"The shape that's selected, or nothing"
picked_shape(v::SketchView) = 1 <= v.picked <= length(v.data.shapes) ? v.data.shapes[v.picked] : nothing

"A new shape, in the colour and drawn the way that the top of the sketch says now"
new_shape(v::SketchView, kind, points, text="") = begin
  shape = Sketches.Shape(kind, v.colour, points, text)
  foreach(name -> Sketches.set!(shape, name, v.next[name]), Sketches.settings(kind))
  shape
end

"""
The parts of how a shape is drawn that the top of the sketch shows now: those
of the shape that's selected, or those of the shapes that the tool draws.
"""
shown_settings(v::SketchView) = (s = picked_shape(v); s !== nothing ? Sketches.settings(s) : v.tool == :select ? () : Sketches.settings(v.tool))

"What a part of how a shape is drawn is now: for the shape that's selected, or for the next shape"
setting(v::SketchView, name) = (s = picked_shape(v); s === nothing ? v.next[name] : getfield(s, name))

"The most that a part of how a shape is drawn can be now. The corners of the box that's selected are no rounder than half its shorter side."
most(v::SketchView, name) = begin
  top = Sketches.LIMITS[name][2]
  s = picked_shape(v)
  (name == :radius && s !== nothing) || return top
  l, t, r, b = Sketches.bounds(s)
  min(top, round(min(r - l, b - t) / 2, digits=1))
end

"The number that a click takes `n` to: the next whole step up, or the next one down"
stepped(name, n, up) = begin
  step = SKETCH_SETTINGS[name][4]
  to = up ? (floor(n / step + 1e-9) + 1) * step : (ceil(n / step - 1e-9) - 1) * step
  clamp(to, Sketches.LIMITS[name]...)
end

"The text field that holds the number of one part of how a shape is drawn"
number_input(v::SketchView, name) = block_part!(v, (:number, name)) do
  TextInput(placeholder="", font_family=SANS, font_size=12px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"""
Give a part of how a shape is drawn the number `n`: to the shape that's
selected, and to the shapes that are drawn next. A number that's too small or
too big becomes the nearest that the part can be.
"""
set_setting!(v::SketchView, name, n::Real) = begin
  n = round(clamp(n, Sketches.LIMITS[name][1], most(v, name)), digits=1)
  v.next[name] = n
  s = picked_shape(v)
  (s === nothing || getfield(s, name) == n) || (Sketches.set!(s, name, n); commit!(v))
  v
end

"The number that was typed is taken, and its field lets go of it. Text that isn't a number changes nothing."
settle_number!(v::SketchView) = begin
  name = v.typing
  name === nothing && return v
  v.typing = nothing
  n = tryparse(Float64, strip(number_input(v, name).text))
  (n === nothing || !isfinite(n)) ? v : set_setting!(v, name, n)
end

"""
The number of one part of how a shape is drawn, at the top of a sketch, with
its icon and a button each side that changes it. The number is a text field:
a click in it selects the number, and Return takes what's typed.
"""
stepper(v::SketchView, name) = begin
  icon, less, more, _ = SKETCH_SETTINGS[name]
  n = setting(v, name)
  field = number_input(v, name)
  field.color = colours.ink
  typing = v.typing == name
  # While nobody types in it, the field shows the number as it is now
  typing || (field.text = Sketches.figure(n); field.anchor = field.cursor = 0)
  Row(Alignment.Center, name="Setting",
    Box(fixed(22px), height(26px), Alignment.Center, justify=Alignment.Center, Icon(sketch_icon(icon), size=14px, color=colours.dim)),
    block_button!(v, (:less, name), (:set, name, false), icon="dash", tip=less, off=n <= Sketches.LIMITS[name][1]),
    # The field is as wide as its number, in the middle of its room, so the number is half way between the two buttons
    Box(fixed(34px), height(26px), Alignment.Center, justify=Alignment.Center,
      Box(fixed(px(clamp(sketch_measure(field.text, 12) + 14, 20, 34))), height(22px), padding(5px, 0px), radius(5px),
          border(1px, :solid, typing ? colours.accent : ishovered(field) ? colours.line : clear), background(typing ? colours.bg : clear), field)),
    block_button!(v, (:more, name), (:set, name, true), icon="plus", tip=more, off=n >= most(v, name)))
end

"The place in the sketch that's under the mouse"
sketch_place(v::SketchView, w) = (s = sketch_scale(v); ((num(w.mouse[1]) - v.box[1]) / s, (num(w.mouse[2]) - v.box[2]) / s))

"How wide the words of a text shape are, in the sketch's own measure"
sketch_measure(text, size) = num(measure(Face(SANS, "", px(size), colours.ink, false), text))

"Write the sketch into its block"
commit!(v::SketchView) = write_block!(v, SKETCH, Sketches.written(v.data))

describe(::InkDot) = Box(fixed(22px), height(26px), name="Colour")

# The dot and the ring round it are drawn about the middle of the dot's box, so the ring is never off the dot
draw(ctx, size, ui::ConcreteRect, d::InkDot) = begin
  v = d.of
  on = (v.picked > 0 ? v.data.shapes[v.picked].colour : v.colour) == d.colour
  x, y = Float32(num(ui.left + ui.width / 2)), Float32(num(ui.top + ui.height / 2))
  disc(colour, r, wide=0.0) = (paint = ink(colour, wide); Skia.sk_canvas_draw_circle(ctx, x, y, Float32(r), paint); Skia.sk_paint_delete(paint))
  disc(sketch_colour(d.colour), 5)
  (on || ishovered(d)) && disc(on ? colours.accent : colours.marker, 7.25, 1.5)
end

cursor(::InkDot) = :hand

# A click on a colour gives it to the shape that's selected, and to the shapes that are drawn next
onkey(d::InkDot, ::KeyPress{Keys.mouse_left}) = begin
  v = d.of
  v.colour = d.colour
  v.picked > 0 && (v.data.shapes[v.picked].colour = d.colour; commit!(v))
  v.asking === nothing || focus(sketch_input(v))   # the words that are being typed take the colour, and the keyboard stays with them
  handled
end

"True for a sketch with too little room for all of its top in one row. How a shape is drawn then has a row of its own."
narrow(v::SketchView) = sketch_room(v) < SKETCH_BAR

describe(v::SketchView) = begin
  e = editor(v)
  with_theme(component_theme(e.zoom)) do
    # In the page it shows only its drawing. A click on it, a pinch outwards or the button beside its top right
    # corner makes it fill the window, where its tools are.
    v.full || return Box(width(grow=grow), Alignment.Start, fillable(v, (:block, v), Column(block_look()..., clip=true, name="Sketch", sketch_area(v)), wide=:grow))
    full = block_button!(v, :full, :full, icon="fullscreen-exit", tip="Back to the page  esc")
    settings = [stepper(v, name) for name in shown_settings(v)]
    beside = narrow(v) || isempty(settings) ? () : (rule(), settings...)
    tools = ([block_button!(v, tool, (:tool, tool), icon=icon, tip=tip, on=v.tool == tool) for (tool, icon, tip) in SKETCH_TOOLS]..., rule(),
             [block_part!(() -> InkDot(of=v, colour=c), v, (:ink, c)) for c in Sketches.COLOURS]..., beside...,
             Box(width(grow=grow)),
             (v.picked > 0 ? (block_button!(v, :delete, :delete, icon="trash", tip="Take the selected shape away  Delete"),) : ())..., full)
    # The second row is there all the time in a narrow sketch, so that the drawing stays where it is when a shape is selected
    bars = (block_bar(tools...), (narrow(v) ? (block_bar(settings..., Box(width(grow=grow))),) : ())...)
    # In the window it takes all the room under the top bar. The wheel scrolls through a drawing that's taller than that.
    list = get!(() -> Scroll(width(grow=grow), height(grow=grow)), v.parts, :list)
    Column(width(grow=grow), height(grow=grow), Alignment.Start, background(takeoff_back()), name="Sketch", bars..., reuse!(list, sketch_area(v)))
  end
end

"""
Make the sketch fill the window, or put it back in the page. In the page it
shows only its drawing, so words that were being typed are added, no shape is
selected, and the keyboard goes back to the text.
"""
full!(v::SketchView, on::Bool) = begin
  e = editor(v)
  on && unfill!(e)   # one block at a time fills the window
  on || (settle_number!(v); answer!(v); v.picked = 0; v.draft = v.grab = nothing)
  v.full = on
  v.pinned = e.scroll.offset
  v.box = (0.0, 0.0, 0.0, 0.0)   # it's another size now, so how big it's drawn is worked out afresh
  on ? focus(sketch_area(v)) : focus(e)
  handled
end

# A pinch outwards on a sketch in the page makes it fill the window
onpinch(v::SketchView, ev::Pinch) = v.full ? nothing : pinch_open(v, ev)

"How tall the drawing is in a sketch that fills the window, when its shapes need less: the window, under the top bar and the sketch's buttons"
full_room(v::SketchView) = num(window_size(editor(v))[2] - TOPBAR_H - (narrow(v) ? 76px : 38px))

act!(v::SketchView, action, w) = begin
  settle_number!(v)
  # A button beside a number changes the words that are being typed, and they stay open. Any other button adds them first.
  (action isa Tuple && action[1] == :set) || answer!(v)
  if action == :delete
    1 <= v.picked <= length(v.data.shapes) || return handled
    deleteat!(v.data.shapes, v.picked)
    v.picked = 0
    commit!(v)
  elseif action == :full
    return full!(v, !v.full)
  elseif action[1] == :tool
    v.tool = action[2]
    v.tool == :select || (v.picked = 0)
  elseif action[1] == :set
    # A button beside a number changes it for the shape that's selected, and for the shapes that are drawn next
    _, name, up = action
    set_setting!(v, name, stepped(name, setting(v, name), up))
  end
  focus(v.asking === nothing ? sketch_area(v) : sketch_input(v))
  handled
end

describe(a::SketchArea) = begin
  v = a.of
  # While a shape is drawn or moved, the sketch keeps its height, and gets taller when the mouse lets go
  tall = Sketches.tall(v.data) * sketch_scale(v)
  # One that fills the window goes down to the window's foot, or further
  Box(width(grow=grow), height(px(v.full ? max(tall, full_room(v)) : tall)))
end

"Draw a line through `points` whose corners are round, as a line drawn by hand has them"
draw_curve(ctx, points, paint) = begin
  length(points) < 2 && return
  shape = Skia.sk_path_new()
  Skia.sk_path_move_to(shape, Float32(points[1][1]), Float32(points[1][2]))
  # The line goes from the middle of each part to the middle of the next, and bends at the place between
  for i in 2:length(points)-1
    mid = (points[i] .+ points[i+1]) ./ 2
    Skia.sk_path_quad_to(shape, Float32(points[i][1]), Float32(points[i][2]), Float32(mid[1]), Float32(mid[2]))
  end
  Skia.sk_path_line_to(shape, Float32(points[end][1]), Float32(points[end][2]))
  Skia.sk_canvas_draw_path(ctx, shape, paint)
  Skia.sk_path_delete(shape)
end

"""
Draw one shape of a sketch whose top left corner is at `(x0, y0)` in the
window. `s` is how many px one of the sketch's measure is. With `glow`, it
draws a soft light in the shape and the colour of the shape, which goes under
the shape that's selected.
"""
draw_shape(ctx, shape, x0, y0, s; glow=false) = begin
  at(p) = (x0 + p[1] * s, y0 + p[2] * s)
  words = shape.kind == :text
  # A line is never so thin in a small sketch that it can't be seen
  wide = max(min(1.2, 0.6shape.width), shape.width * s)
  colour = sketch_colour(shape.colour)
  # The light is the colour of the shape, and fainter
  paint = glow ? ink(RGBA(colour, 0.35), words ? 0.0 : wide + 4) : ink(colour, words ? 0.0 : wide)
  blur = glow ? Skia.sk_maskfilter_new_blur_with_flags(Skia.SK_BLUR_STYLE_NORMAL, 2.5f0, true) : nothing
  glow && Skia.sk_paint_set_maskfilter(paint, blur)
  stroke(ps) = (line = path_through(ps, false); Skia.sk_canvas_draw_path(ctx, line, paint); Skia.sk_path_delete(line))
  if words
    x, y = at(shape.points[1])
    blob = Skia.sk_textblob_make_from_string(shape.text, skia_font(SANS, px(shape.size * s), "").raw, Skia.SK_TEXT_ENCODING_UTF8)
    # The light under words is drawn twice, since words are thin
    for _ in 1:(glow ? 2 : 1)
      Skia.sk_canvas_draw_text_blob(ctx, blob, Float32(x), Float32(y), paint)
    end
    Skia.sk_textblob_unref(blob)
  elseif shape.kind in (:box, :oval)
    l, t, r, b = Sketches.bounds(shape)
    (x1, y1), (x2, y2) = at((l, t)), at((r, b))
    edges = Ref(Skia.sk_rect_t(Float32(x1), Float32(y1), Float32(x2), Float32(y2)))
    if shape.kind == :oval
      Skia.sk_canvas_draw_oval(ctx, edges, paint)
    else
      # The corners of a small box are no rounder than half its shorter side
      bend = Float32(min(shape.radius * s, (x2 - x1) / 2, (y2 - y1) / 2))
      outline = Skia.sk_path_new()
      Skia.sk_path_add_rounded_rect(outline, edges, bend, bend, Skia.SK_PATH_DIRECTION_CW)
      Skia.sk_canvas_draw_path(ctx, outline, paint)
      Skia.sk_path_delete(outline)
    end
  elseif shape.kind == :pen
    draw_curve(ctx, at.(shape.points), paint)
  else
    stroke(at.(shape.points))
    if shape.kind == :arrow
      a, b = Sketches.barbs(shape)
      stroke([at(a), at(shape.points[2]), at(b)])
    end
  end
  glow && Skia.sk_maskfilter_unref(blur)
  Skia.sk_paint_delete(paint)
end

"The number of the circle of the selected shape that's under the mouse, or nothing"
handle_under(v::SketchView, w) = begin
  shape = picked_shape(v)
  (shape === nothing || w === nothing || v.box[3] <= 0) && return nothing
  Sketches.handle(shape, sketch_place(v, w), HANDLE_REACH / sketch_scale(v))
end

"Draw a circle on each place of the selected shape that a drag moves. The one under the mouse, or the one that's dragged, is filled."
draw_handles(ctx, v::SketchView, shape, s) = begin
  hot = v.grab !== nothing ? (v.grab[3] == 0 ? nothing : v.grab[3]) : v.tool == :select ? handle_under(v, window_of(v)) : nothing
  # The places of a line drawn by hand are close together, so their circles are smaller
  r = shape.kind == :pen ? 0.7HANDLE : HANDLE
  for (k, p) in enumerate(Sketches.handles(shape))
    x, y = Float32(v.box[1] + p[1] * s), Float32(v.box[2] + p[2] * s)
    for paint in (ink(k == hot ? colours.accent : takeoff_back()), ink(colours.accent, 1.5))
      Skia.sk_canvas_draw_circle(ctx, x, y, Float32(r), paint)
      Skia.sk_paint_delete(paint)
    end
  end
end

draw(ctx, size, ui::ConcreteRect, a::SketchArea) = begin
  v = a.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  v.box[3] > 0 || return
  s = sketch_scale(v)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    isempty(v.data.shapes) && v.draft === nothing && v.asking === nothing &&
      write_ink(ctx, v.full ? "Drag here to draw" : "Click here to draw", v.box[1] + 16, v.box[2] + 28, Face(SANS, "", 13px, colours.faint, false))
    for (k, shape) in enumerate(v.data.shapes)
      k == v.editing && continue   # words that are being changed show as they're typed
      # The shape that's selected glows
      k == v.picked && draw_shape(ctx, shape, v.box[1], v.box[2], s, glow=true)
      draw_shape(ctx, shape, v.box[1], v.box[2], s)
    end
    v.draft === nothing || draw_shape(ctx, v.draft, v.box[1], v.box[2], s)
    # And it has a circle on each place that a drag moves
    chosen = picked_shape(v)
    chosen === nothing || draw_handles(ctx, v, chosen, s)
    v.asking === nothing || draw_typing(ctx, v, s)
  end
end

"The words that are being changed, or nothing when the words that are typed are new"
edited_shape(v::SketchView) = begin
  s = 1 <= v.editing <= length(v.data.shapes) ? v.data.shapes[v.editing] : nothing
  s !== nothing && s.kind == :text ? s : nothing
end

"The words that are being typed, as the shape that they will be"
typed_shape(v::SketchView) = begin
  old, text = edited_shape(v), sketch_input(v).text
  old === nothing ? new_shape(v, :text, [v.asking], text) : Sketches.Shape(:text, old.colour, [v.asking], text, old.width, old.radius, old.size)
end

"""
The place among the characters of the words that are being typed that's
nearest to `p`, a place in the sketch. It's nothing when `p` isn't on the words.
"""
typed_index(v::SketchView, p) = begin
  text, size = sketch_input(v).text, typed_shape(v).size
  x, y = v.asking
  to(n) = x + sketch_measure(first(text, n), size)
  (x - 4 <= p[1] <= to(length(text)) + 4 && y - size <= p[2] <= y + 0.3size) || return nothing
  argmin(n -> abs(to(n) - p[1]), 0:length(text))
end

"Start typing in the drawing: new words at `at`, or with `k` the `k`th shape's words, with the caret where `p` is in them"
type_words!(v::SketchView, at, k=0, p=at) = begin
  field = sketch_input(v)
  v.asking, v.editing = at, k
  field.text = k == 0 ? "" : v.data.shapes[k].text
  field.anchor = field.cursor = something(typed_index(v, p), length(field.text))
  field.last_action = time()
  v.picked = k   # so the colours and the size at the top are those of the words
  v.grab = nothing
  focus(field)
  handled
end

"Note a click at `(x, y)`. True when it's the second of two clicks in one place."
click_twice!(v::SketchView, x, y) = begin
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  time() - at < 0.35 && hypot(x - cx, y - cy) < 4
end

"""
Draw the words that are being typed where they will be in the drawing, in
their colour and at their size, with the caret after the place that the next
character goes in, and the colour of a selection behind the words that are
selected.
"""
draw_typing(ctx, v::SketchView, s) = begin
  field = sketch_input(v)
  shape = typed_shape(v)
  x, y = v.box[1] + v.asking[1] * s, v.box[2] + v.asking[2] * s
  tall = shape.size * s
  face = Face(SANS, "", px(tall), colours.ink, false)
  to(n) = x + num(measure(face, first(field.text, n)))
  lo, hi = minmax(field.anchor, field.cursor)
  lo == hi || round_box(ctx, to(lo), y - 0.95tall, to(hi) - to(lo), 1.25tall, 2.0, fill=colours.select)
  isempty(field.text) || draw_shape(ctx, shape, v.box[1], v.box[2], s)
  # The caret blinks, and it's lit just after a key
  mod(time() - field.last_action, 1.0) < 0.5 && trace(ctx, [(to(field.cursor), y - 0.9tall), (to(field.cursor), y + 0.2tall)], colours.accent, 1.5)
end

cursor(a::SketchArea) = begin
  v = a.of
  v.full || return :hand   # a click makes it fill the window
  v.tool == :select || return v.tool == :text ? :ibeam : :crosshair
  v.grab !== nothing || handle_under(v, window_of(a)) !== nothing ? :hand : :arrow
end
cursor(::SketchView) = :arrow

onkey(a::SketchArea, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = a.of, ev.window
  # In the page, a click makes the sketch fill the window, where its tools are. With ⌥ held, the page shows its lines.
  v.full || return held(v, Keys.opt) ? nothing : full!(v, true)
  readonly(editor(v).buf) && return handled
  p = sketch_place(v, w)
  twice = click_twice!(v, num(w.mouse[1]), num(w.mouse[2]))
  # A click on the words that are being typed puts the caret there
  if v.asking !== nothing && (n = typed_index(v, p)) !== nothing
    field = sketch_input(v)
    field.anchor = field.cursor = n
    field.last_action = time()
    return handled
  end
  answer!(v)          # words that were being typed are added where they are
  settle_number!(v)   # a number that was typed goes to the shape that it was typed for
  focus(a)
  k = Sketches.hit(v.data, p, 7.0, sketch_measure)
  words = k !== nothing && v.data.shapes[k].kind == :text
  if v.tool == :select
    # A circle of the shape that's selected is taken before a shape is
    h = handle_under(v, w)
    h === nothing || (k = v.picked)
    # Two clicks on words change them where they are
    h === nothing && words && twice && return type_words!(v, v.data.shapes[k].points[1], k, p)
    v.picked = something(k, 0)
    v.grab = k === nothing ? nothing : (p, false, something(h, 0))
  elseif v.tool == :text
    # A click on words changes them. Anywhere else, new words go where the click was: the middle of their height is at the mouse.
    words ? type_words!(v, v.data.shapes[k].points[1], k, p) : type_words!(v, (p[1], p[2] + 0.35v.next[:size]))
  else
    v.picked = 0
    v.draft = new_shape(v, v.tool, v.tool == :pen ? [p] : [p, p])
  end
  handled
end

onmouse(a::SketchArea, ev::MouseMove) = begin
  v, w = a.of, ev.window
  (v.draft === nothing && v.grab === nothing) && return nothing
  Keys.mouse_left in w.keys || return handled
  p = sketch_place(v, w)
  if v.draft !== nothing
    d = v.draft
    # A line drawn by hand gets a new place when the mouse has moved a little
    d.kind == :pen ? (hypot((p .- d.points[end])...) >= 1.5 && push!(d.points, p)) : (d.points[2] = p)
  elseif (shape = picked_shape(v)) !== nothing
    from, _, h = v.grab
    (p == from) && return handled
    # A circle goes where the mouse is, and takes its place of the shape with it. Without one, the whole shape moves.
    h == 0 ? Sketches.move!(shape, p[1] - from[1], p[2] - from[2]) : Sketches.pull!(shape, h, p)
    v.grab = (p, true, h)
  end
  handled   # the drag is the sketch's, so the page's text doesn't select
end

"The mouse let go. The shape that was drawn joins the sketch, and a shape that moved or changed is written down."
drop!(v::SketchView) = begin
  d, g = v.draft, v.grab
  v.draft = v.grab = nothing
  if d !== nothing
    d.kind == :pen && (d.points = Sketches.simplify(d.points))
    # A click without a drag draws nothing
    (d.kind == :pen ? length(d.points) < 2 : Sketches.slight(d)) && return v
    push!(v.data.shapes, d)
    commit!(v)
  elseif g !== nothing && g[2]
    commit!(v)
  end
  v
end

"""
Take the words that were typed. New words are added as a text shape, at the
place that was clicked. Words that were changed are written down, and taken
away when nothing is left of them.
"""
answer!(v::SketchView) = begin
  v.asking === nothing && return handled
  words = join(split(sketch_input(v).text), " ")
  p, k, old = v.asking, v.editing, edited_shape(v)
  stop_asking!(v)
  if old !== nothing
    isempty(words) ? (deleteat!(v.data.shapes, k); v.picked = 0) : (old.text = words)
    commit!(v)
  elseif k == 0 && !isempty(words)
    push!(v.data.shapes, new_shape(v, :text, [p], words))
    commit!(v)
  end
  handled
end

"Stop typing words into the drawing. New words are left out, and words that were being changed stay as they were. The keyboard goes back to the drawing."
stop_asking!(v::SketchView) = begin
  v.asking = nothing
  v.editing = 0
  v.tool == :select || (v.picked = 0)
  w = window_of(v)
  w !== nothing && w.focus === sketch_input(v) && focus(sketch_area(v))
  handled
end

# Return takes the number that was typed for how a shape is drawn, and Esc leaves the number as it was
onkey(v::SketchView, ::KeyPress{Keys.enter}) =
  v.typing !== nothing ? (settle_number!(v); focus(sketch_area(v)); handled) : v.asking === nothing ? nothing : answer!(v)
onkey(v::SketchView, ::KeyPress{Keys.escape}) =
  v.typing !== nothing ? (v.typing = nothing; focus(sketch_area(v)); handled) : v.asking === nothing ? nothing : stop_asking!(v)
onmouse(v::SketchView, ::MouseMove) = v.full || (held(v, Keys.mouse_left) && (v.draft !== nothing || v.grab !== nothing)) ? handled : nothing
# A click beside a button of a sketch that fills the window is the sketch's, and not the page's under it
onkey(v::SketchView, ::KeyPress{Keys.mouse_left}) = v.full ? (focus(sketch_area(v)); handled) : nothing

# The wheel over a sketch that fills the window scrolls a drawing that's taller than the window. It never
# scrolls the page under the sketch, which UI.jl would choose first.
onscroll(a::SketchArea, ev::MouseScroll) = begin
  v = a.of
  v.full || return nothing
  list = get(v.parts, :list, nothing)
  list === nothing || (list.offset = clamp(list.offset - 30ev.delta[2], 0px, max(0px, px(v.box[4] - full_room(v)))))
  handled
end
onscroll(v::SketchView, ::MouseScroll) = v.full ? handled : nothing

block_tick!(v::SketchView) = begin
  (v.draft !== nothing || v.grab !== nothing) && !held(v, Keys.mouse_left) && drop!(v)
  # A click somewhere else took the keyboard from the words that were being typed. They're added.
  w = window_of(v)
  v.asking !== nothing && w !== nothing && w.focus !== sketch_input(v) && answer!(v)
  # The words that were being changed have gone, as after ⌘Z
  v.editing > 0 && edited_shape(v) === nothing && stop_asking!(v)
  v.asking === nothing || redraw_in!(v, 0.25)   # the caret blinks
  # A click in a number gave it the keyboard, and its text is selected so that typing takes its place.
  # A click somewhere else took the keyboard from it, and a number that was typed is kept.
  if w !== nothing
    at = findfirst(name -> w.focus === get(v.parts, (:number, name), nothing), keys(SKETCH_SETTINGS))
    name = at === nothing ? nothing : keys(SKETCH_SETTINGS)[at]
    if name != v.typing
      settle_number!(v)
      v.typing = name
      name === nothing || tabbed!(number_input(v, name))
    end
  end
  v
end

# Esc lets go of the shape that's selected, then chooses the arrow tool, then puts a sketch that fills the window
# back in the page, then gives the keyboard back to the text. Delete takes the shape away.
onkey(a::SketchArea, ::KeyPress{Keys.escape}) = begin
  v = a.of
  v.picked > 0 && return (v.picked = 0; handled)
  v.tool == :select || return (v.tool = :select; handled)
  v.full ? full!(v, false) : nothing
end
onkey(a::SketchArea, ::KeyPress{K}) where K = begin
  v = a.of
  K in (Keys.backspace, Keys.delete) && return v.picked > 0 ? act!(v, :delete, window_of(a)) : handled
  if (command = command_of(editor(v), window_of(a), K)) in (:undo, :redo)
    b = editor(v).buf
    command == :redo ? redo!(b) : undo!(b)
    return handled
  end
  nothing
end

"The sketch as HTML: a picture of it"
sketch_html(e, v::SketchView) = begin
  isempty(v.data.shapes) && return nothing
  cs = css_colour.(SERIES_LIGHT)
  picture = Sketches.svg(v.data, colours=(ink="#2b2622", red=cs[8], blue=cs[1], green=cs[6], orange=cs[2]), family="-apple-system, Helvetica, sans-serif")
  "<div class=\"diagram\">\n$picture\n</div>"
end

BLOCKS[SKETCH] = BlockKind("Sketch", "pencil", SketchView, sketch_html)

# --- a log of the hours on each task -----------------------------------------------------------
#
# A code block in the language `timelog` keeps the hours that someone works
# on each task. timelog.jl says how the block is written, and adds the hours
# up. The block shows a row for each stretch of work, and the totals under
# the rows. At its top, a field takes a task, and the button beside it starts
# the clock on that task: a new line for now, with no stop time. While a line
# runs, its row counts up, and the button is lit and reads Stop. A click on it
# then writes the time now into the line. A task that's typed in the field
# while a line runs makes the button read Start again: a click stops that
# line and starts the new task. The field offers the tasks that the log
# already has, in a list like the one under a button of a `find` block. A
# click on a time or a task of a row lets you change it where it is, with no
# box round it, and Return writes what's typed there into the line. A `chart` block under a log draws
# the hours of each task.

const TIMELOG = Timelogs.TIMELOG
const TASKS_KEY = :timelog_tasks   # the key of the list of tasks under the field
const MOST_TASKS = 6               # the rows that the list shows before it scrolls
const LOG_ROW = 28px               # how tall a row of the log is
const LOG_DAY, LOG_TIME, LOG_HOURS = 104px, 58px, 124px   # how wide the columns before the task are
const LOG_NARROW = 470px           # a log that's narrower than this has each day on a line of its own, and no column for the day
const LOG_SLIM = (52px, 112px)     # how wide the columns of a time and of the hours are in such a log
const LOG_WRONG = colorant"rgb(214,69,65)"   # the line under a time that's being changed and can't be read
push!(BLOCK_ICONS, "stopwatch", "play-fill", "stop-fill")

"What a `timelog` block shows: a row for each stretch of work, the totals, and a field and a button that start the clock"
@def mutable struct TimelogView <: SemanticUI
  n::Int = 0                               # its place among the page's time logs
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Timelogs.Log = Timelogs.Log()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its fields, its button and its cells, kept between frames
  editing::Any = nothing                   # the cell that's being changed where it is: its row, and :from, :to or :task
  wrong::Bool = false                      # what's typed there isn't a time
  offers::Vector{String} = String[]        # the tasks that the list under the field offers
  pick::Int = 0                            # the one of them that Return takes, or 0 for none
  typed::Any = nothing                     # what the field held when the offers were last worked out, or nothing while it has no keyboard
  minute::Int = -1                         # the minute that the page's charts last drew a running log for
end

"A time or a task of a row. A click lets you change it where it is."
@def mutable struct LogCell <: SemanticUI
  of::Any = nothing
  i::Int = 0
  part::Symbol = :task
end
"The list of tasks that floats under the field of a log"
@def mutable struct TaskOffers <: SemanticUI
  of::Any = nothing
  side::Symbol = :bottom   # the side of the field that it's on
  pick::Int = 0            # the row that was picked when it was last drawn. A row that the keys pick is brought in sight.
end
"A row of that list: a task that the log has"
@def mutable struct TaskOffer <: SemanticUI
  of::Any = nothing
  k::Int = 0
end

"The field at the top of a log. It holds the task that Start starts."
task_input(v::TimelogView) = block_part!(v, :input) do
  TextInput(placeholder="What are you working on?", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"The field that takes the place of a time or a task while you change it"
cell_input(v::TimelogView) = block_part!(v, :edit) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::TimelogView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Timelogs.timelog(lines)
  # The row of the cell that's being changed can go, as when ⌘Z takes its line back
  v.editing === nothing || Timelogs.stretch(v.data, v.editing[1]) !== nothing || (v.editing = nothing)
  v
end

"True when the page can't be changed, so the log can't be"
log_fixed(v::TimelogView) = (b = editor(v).buf; readonly(b) || b.fixed)

"Write the log into the lines of its block"
write_log!(v::TimelogView) = write_block!(v, TIMELOG, Timelogs.written(v.data))

"True when the button starts the clock: no line runs, or the field holds a task to change to"
starts(v::TimelogView) = Timelogs.running(v.data) === nothing || !isempty(strip(task_input(v).text))

"What the button does: it starts the clock on the task in the field, or it stops the line that runs"
clock!(v::TimelogView) = begin
  log_fixed(v) && return handled
  input = task_input(v)
  at = Timelogs.now()
  starts(v) ? Timelogs.start!(v.data, input.text, at) : Timelogs.stop!(v.data, at)
  input.text = ""
  input.anchor = input.cursor = 0
  shut_offers!(v)
  write_log!(v)
  handled
end

# A click on the button gives the keyboard back to the page, if the field had it
act!(v::TimelogView, action, w) = (action == :clock && clock!(v); w.focus === task_input(v) && focus(editor(v)); handled)

"The words of a part of the stretch `s`: a time as its line has it, or its task"
cell_words(s::Timelogs.Stretch, part::Symbol) =
  part == :task ? s.task : part == :from ? Timelogs.hhmm(s.from) : s.to === nothing ? "" : Timelogs.hhmm(s.to)

"""
Write what the field in a row holds into its line, and take the field away.
It gives false, and the field stays, when a time can't be read.
"""
settle_cell!(v::TimelogView) = begin
  v.editing === nothing && return true
  i, part = v.editing
  s = Timelogs.stretch(v.data, i)
  text = cell_input(v).text
  if s !== nothing && !log_fixed(v) && strip(text) != cell_words(s, part)
    Timelogs.set!(v.data, i, part, text) || (v.wrong = true; return false)
    write_log!(v)
  end
  v.editing, v.wrong = nothing, false
  true
end

"Put a field in the place of the cell `c`, with the cell's words in it and selected"
open_cell!(c::LogCell) = begin
  v = c.of
  log_fixed(v) && return handled
  settle_cell!(v) || (v.editing = nothing)   # another cell that was being changed is written first
  s = Timelogs.stretch(v.data, c.i)
  s === nothing && return handled
  input = cell_input(v)
  input.color = colours.ink
  input.text = cell_words(s, c.part)
  input.anchor, input.cursor = 0, length(input.text)
  v.editing, v.wrong = (c.i, c.part), false
  focus(input)
  handled
end

"Show the list of the tasks to offer under the field"
show_offers!(v::TimelogView, w) = begin
  list = TaskOffers(of=v)
  v.parts[:offers] = list
  r = rect(task_input(v))
  # The keys stay with the field, and a click outside the list is the app's, as it is with no list
  popup!(w, list, anchor=task_input(v), placement=:bottom, gap=9px, width=max(220px, r === nothing ? 0px : r.width + 16px), key=TASKS_KEY, modal=false,
         onclose=() -> (v.offers = String[]; v.pick = 0), theme=component_theme(editor(v).zoom))
end

"Take the list of tasks away. It comes back when what's in the field changes."
shut_offers!(v::TimelogView) = begin
  v.offers, v.pick = String[], 0
  w = window_of(v)
  w === nothing || close_popup!(w, TASKS_KEY)
  handled
end

"Put the task at row `k` of the list in the field, with the caret after it. Start, or Return, then starts it."
take_offer!(v::TimelogView, k::Int) = begin
  input = task_input(v)
  k in eachindex(v.offers) && (input.text = v.offers[k]; input.anchor = input.cursor = length(input.text))
  v.typed = input.text
  focus(input)
  shut_offers!(v)
end

"""
What happens to a log in each frame, before the page is laid out. A click
somewhere else writes what the field in a row holds. The list under the top
field gets the tasks that have what's typed there, and goes when the field
loses the keyboard. A chart of a log that runs is drawn again each minute.
"""
block_tick!(v::TimelogView) = begin
  w = window_of(v)
  v.editing !== nothing && (w === nothing || w.focus !== cell_input(v)) && (settle_cell!(v) || (v.editing = nothing))
  input = task_input(v)
  if w === nothing || w.focus !== input
    v.typed === nothing || (v.typed = nothing; shut_offers!(v))
  elseif input.text != v.typed
    v.typed = input.text
    v.offers, v.pick = Timelogs.offered(v.data, input.text), 0
    isempty(v.offers) ? close_popup!(w, TASKS_KEY) : show_offers!(v, w)
  end
  if Timelogs.running(v.data) !== nothing && (minute = Dates.minute(Timelogs.now())) != v.minute
    v.minute = minute
    e = editor(v)
    delete!(e.flows, (:tables, e.buf.path, e.buf.version))
    foreach(node -> node isa ChartView && (node.shown = nothing), values(e.nodes))
  end
  v
end

describe(o::TaskOffer) = begin
  v = o.of
  o.k <= length(v.offers) ? float_row(v.offers[o.k], picked=v.pick == o.k) : Box(height(0px))
end

cursor(::TaskOffer) = :hand
onkey(o::TaskOffer, ::KeyPress{Keys.mouse_left}) = take_offer!(o.of, o.k)
# The mouse picks the task that it's over, as the arrow keys do
onmouse(o::TaskOffer, ::MouseMove) = begin
  v = o.of
  v.pick = o.k
  list = get(v.parts, :offers, nothing)
  list === nothing || (list.pick = o.k)   # it's in sight already, so the list doesn't scroll to it
  handled
end

describe(l::TaskOffers) = begin
  v = l.of
  c = found_colours()
  n, high = length(v.offers), FLOAT_ROW
  scroll = get!(() -> Scroll(width(grow=grow)), v.parts, :offer_scroll)
  # Half a row at the bottom says that the list goes on
  scroll.height = height(n <= MOST_TASKS ? n * high : MOST_TASKS * high - high / 2)
  l.pick == v.pick || (l.pick = v.pick; v.pick > 0 && scroll_into_view!(scroll, high * (v.pick - 1), high * v.pick))
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Tasks",
    reuse!(scroll, Column(width(grow=grow), Alignment.Start, [block_part!(() -> TaskOffer(of=v, k=k), v, (:offer, k)) for k in 1:n]...)))
end

placed!(l::TaskOffers, side) = (l.side = side; nothing)
draw(ctx, size, ui::ConcreteRect, l::TaskOffers) = caret(ctx, ui, l.side, rect(task_input(l.of)))

# The keys that a field of the log has no use for come here. Return in the field of a row writes what's typed
# there. In the top field, it takes the task that's picked in the list, or does what the button does.
onkey(v::TimelogView, ev::KeyPress{Keys.enter}) = begin
  w = ev.window
  if w.focus === cell_input(v)
    settle_cell!(v) && focus(editor(v))
  elseif w.focus === task_input(v)
    v.pick > 0 && return take_offer!(v, v.pick)
    starts(v) && clock!(v)
    focus(editor(v))
  else
    return nothing
  end
  handled
end
# Esc leaves a row as it was. In the top field, it closes the list, and then gives the keyboard back to the page.
onkey(v::TimelogView, ev::KeyPress{Keys.escape}) = begin
  w = ev.window
  if w.focus === cell_input(v)
    v.editing, v.wrong = nothing, false
    focus(editor(v))
  elseif w.focus === task_input(v)
    isempty(v.offers) ? focus(editor(v)) : shut_offers!(v)
  else
    return nothing
  end
  handled
end
onkey(v::TimelogView, ::KeyPress{Keys.down}) = isempty(v.offers) ? nothing : (v.pick = min(v.pick + 1, length(v.offers)); handled)
onkey(v::TimelogView, ::KeyPress{Keys.up}) = isempty(v.offers) ? nothing : (v.pick = max(v.pick - 1, 0); handled)

"True when the log is too narrow for a column of days. Each day is then on a line of its own, over its rows."
log_narrow(v::TimelogView) = editor(v).width < LOG_NARROW

"Words in a column of a log. `wide` says how wide the column is."
log_column(wide, words; size=13px, color=colours.ink, weight="") =
  Row(wide, height(24px), padding(6px, 0px), Alignment.Center, clip=true, Box(label(words, size, color=color, weight=weight)))

describe(c::LogCell) = begin
  v = c.of
  s = Timelogs.stretch(v.data, c.i)
  s === nothing && return Box(width(0px))
  wide = c.part == :task ? width(grow=grow) : fixed(log_narrow(v) ? LOG_SLIM[1] : LOG_TIME)
  if v.editing == (c.i, c.part)
    # The words are changed where they are, with no box round them. A time that can't be read has a red line under it.
    field = Row(wide, height(24px), padding(6px, 0px), Alignment.Center, Box(width(grow=grow), height(grow=grow), cell_input(v)))
    v.wrong && (field.border = border(1px, :solid, LOG_WRONG)[:bottom])
    return field
  end
  words = cell_words(s, c.part)
  # A row with no stop time says "now" while it runs. A row with no task says so.
  shown = !isempty(words) ? words : c.part == :task ? "No task" : Timelogs.running(v.data) == c.i ? "now" : "–"
  Row(wide, height(24px), padding(6px, 0px), radius(5px), Alignment.Center, clip=true, background(ishovered(c) && !log_fixed(v) ? colours.hover : clear),
      Box(label(shown, 13px, color=isempty(words) ? colours.faint : colours.ink)))
end

cursor(c::LogCell) = log_fixed(c.of) ? :arrow : :ibeam
cursor(::TimelogView) = :arrow
onkey(c::LogCell, ::KeyPress{Keys.mouse_left}) = c.of.editing == (c.i, c.part) ? nothing : open_cell!(c)

"What the button's tooltip says after \"Start the clock\": the task, if there is one"
on_task(task) = isempty(task) ? "" : " on " * task

describe(v::TimelogView) = begin
  e = editor(v)
  log = v.data
  at = Timelogs.now()
  run = Timelogs.running(log)
  # The row that runs counts up, so the window draws again when the next second starts
  run === nothing || redraw_in!(v, 1.02 - Dates.millisecond(at) / 1000)
  with_theme(component_theme(e.zoom)) do
    input = task_input(v)
    input.color = colours.ink
    w = window_of(v)
    typing = w !== nothing && w.focus === input
    field = Row(width(grow=grow), height(26px), padding(8px, 0px), child_gap=7px, radius(6px), Alignment.Center, background(colours.bg),
                border(1px, :solid, typing ? colours.accent : colours.line),
                Icon("stopwatch", size=12px, color=run === nothing ? colours.dim : colours.accent), Box(width(grow=grow), height(grow=grow), input))
    # The button reads what a click does. It's lit while a line runs, and its tooltip says which task the click is for.
    typed = Timelogs.tidy(input.text)
    next = on_task(isempty(typed) ? Timelogs.last_task(log) : typed)
    button = !starts(v) ? block_button!(v, :clock, :clock, icon="stop-fill", words="Stop", on=true, tip="Stop the clock" * on_task(log.rows[run].task)) :
             block_button!(v, :clock, :clock, icon="play-fill", words="Start", bold=true, off=log_fixed(v),
                           tip=run === nothing ? "Start the clock" * next : "Stop the clock" * on_task(log.rows[run].task) * ", and start it" * next)
    bar = block_bar(field, Box(width(4px)), button)
    isempty(log.rows) && return Column(block_look()..., clip=true, name="Time log", bar,
      block_note("This log has no hours yet. Type a task in the field and click Start."))
    narrow = log_narrow(v)
    time_wide, hours_wide = narrow ? LOG_SLIM : (LOG_TIME, LOG_HOURS)
    head = Row(width(grow=grow), height(24px), padding(6px, 0px), Alignment.Center,
      (narrow ? () : (log_column(fixed(LOG_DAY), "Day", size=11px, color=colours.dim),))...,
      log_column(fixed(time_wide), "From", size=11px, color=colours.dim), log_column(fixed(time_wide), "To", size=11px, color=colours.dim),
      log_column(fixed(hours_wide), "Hours", size=11px, color=colours.dim), log_column(width(grow=grow), "Task", size=11px, color=colours.dim))
    rows, day = Any[], nothing
    for (i, r) in enumerate(log.rows)
      if r isa String
        # A line that can't be read shows as it's written
        push!(rows, Row(width(grow=grow), height(LOG_ROW), padding(12px, 0px), Alignment.Center, clip=true, Box(label(r, 13px, color=colours.faint)), Box(width(grow=grow))))
        continue
      end
      # The day shows once, for the first of its rows
      fresh = r.day != day
      day = r.day
      narrow && fresh && push!(rows, Row(width(grow=grow), height(24px), padding(12px, 0px), Alignment.Center,
                                         Box(label(Timelogs.day(r.day), 12px, color=colours.dim, weight="Semibold")), Box(width(grow=grow))))
      runs = i == run
      hours = runs ? Timelogs.elapsed(Timelogs.seconds(log, i, at)) : r.to === nothing ? "–" : Timelogs.hours(Timelogs.counted(log, i, at))
      push!(rows, Row(width(grow=grow), height(LOG_ROW), padding(6px, 0px), Alignment.Center, background(runs ? RGBA(colours.accent, 0.09) : clear),
        (narrow ? () : (log_column(fixed(LOG_DAY), fresh ? Timelogs.day(r.day) : "", color=colours.dim),))...,
        block_part!(() -> LogCell(of=v, i=i, part=:from), v, (:cell, i, :from)), block_part!(() -> LogCell(of=v, i=i, part=:to), v, (:cell, i, :to)),
        log_column(fixed(hours_wide), hours, color=runs ? colours.accent : r.to === nothing ? colours.faint : colours.ink, weight=runs ? "Semibold" : ""),
        block_part!(() -> LogCell(of=v, i=i, part=:task), v, (:cell, i, :task))))
    end
    # Under the rows: the total, and the hours of each task when the log has more than one
    sums = Any[]
    if any(r -> r isa Timelogs.Stretch, log.rows)
      lead = (narrow ? 0px : LOG_DAY) + 2time_wide
      sum_row(name, minutes, weight) = Row(width(grow=grow), height(LOG_ROW), padding(6px, 0px), Alignment.Center,
        log_column(fixed(lead), elide(name, 13px, lead - 12px), color=isempty(weight) ? colours.dim : colours.ink, weight=weight),
        log_column(fixed(hours_wide), Timelogs.hours(minutes), weight=weight),
        log_column(width(grow=grow), something(Timelogs.money(log, minutes), ""), weight=weight))
      tasks = Timelogs.tasks(log, at)
      push!(sums, Box(width(grow=grow), padding(12px, 4px), Box(width(grow=grow), height(1px), background(colours.line))),
            sum_row("Total", Timelogs.total(log, at), "Semibold"))
      length(tasks) > 1 && append!(sums, (sum_row(isempty(name) ? "No task" : name, minutes, "") for (name, minutes) in tasks))
    end
    Column(block_look()..., clip=true, name="Time log", bar, head, rows..., sums..., Box(height(6px)))
  end
end

"The log as HTML: a table with a row for each stretch of work, and the totals at its foot"
timelog_html(e, v::TimelogView) = begin
  log = v.data
  isempty(log.rows) && return nothing
  at = Timelogs.now()
  run = Timelogs.running(log)
  rows, day = String[], nothing
  for (i, r) in enumerate(log.rows)
    if r isa String
      push!(rows, "<tr><td colspan=\"5\" style=\"color: #a39a8a\">$(escape(r))</td></tr>")
      continue
    end
    shown = r.day == day ? "" : Timelogs.day(r.day)
    day = r.day
    to = r.to !== nothing ? Timelogs.hhmm(r.to) : i == run ? "now" : ""
    hours = r.to === nothing && i != run ? "" : Timelogs.hours(Timelogs.counted(log, i, at))
    push!(rows, "<tr><td>$shown</td><td>$(Timelogs.hhmm(r.from))</td><td>$to</td><td>$hours</td><td>$(escape(r.task))</td></tr>")
  end
  sum_row(name, minutes, cell) =
    "<tr><$cell colspan=\"3\">$(escape(name))</$cell><$cell>$(Timelogs.hours(minutes))</$cell><$cell>$(something(Timelogs.money(log, minutes), ""))</$cell></tr>"
  sums = String[]
  if any(r -> r isa Timelogs.Stretch, log.rows)
    tasks = Timelogs.tasks(log, at)
    push!(sums, sum_row("Total", Timelogs.total(log, at), "th"))
    length(tasks) > 1 && append!(sums, (sum_row(isempty(name) ? "No task" : name, minutes, "td") for (name, minutes) in tasks))
  end
  "<table>\n<thead><tr><th>Day</th><th>From</th><th>To</th><th>Hours</th><th>Task</th></tr></thead>\n<tbody>\n" * join(rows, "\n") *
  "\n</tbody>\n<tfoot>\n" * join(sums, "\n") * "\n</tfoot>\n</table>"
end

BLOCKS[TIMELOG] = BlockKind("Time log", "stopwatch", TimelogView, timelog_html)

# --- a list of the emails with someone ---------------------------------------------------------
#
# A code block in the language `email` lists the emails with one person, or
# with a few people, newest first. emails.jl says how the block is written.
# The emails are the ones that Ladder keeps on the Mac, in every folder but
# the drafts, the junk and the trash. See "email" in this file, and mail.jl.
# A click on an email opens it. The Reply button starts an answer to the
# newest one, and New email starts one to the block's address.

const EMAIL = Posts.EMAIL
const EMAILS_MOST = 30     # the most emails that a list shows
const EMAILS_READ = 150    # the most emails that a list reads the addresses of in one frame
push!(BLOCK_ICONS, "envelope", "reply", "pencil-square")

"What an `email` block shows: the emails with the people that it names"
@def mutable struct EmailsView <: SemanticUI
  n::Int = 0                               # its place among the page's lists of emails
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Posts.Wanted = Posts.Wanted()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # what the list was last worked out for, and what it found
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its rows and buttons, kept between frames
end

"An email in a list of emails. A click opens it."
@def mutable struct EmailLine <: SemanticUI
  of::Any = nothing
  i::Int = 0
end

reread!(v::EmailsView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Posts.wanted(lines)
  v.shown = nothing
  v
end

# Who each email is from and to, with their addresses, by the email's page. A folder's index has only their names.
const EMAIL_PEOPLE = Dict{String,String}()

"Who the email at `path` is from and to, as its front matter says: names and addresses"
email_people(path) = get!(EMAIL_PEOPLE, path) do
  said, _ = Mail.fields(Mail.first_lines(path))
  lowercase(join((get(said, key, "") for key in ("from", "to", "cc", "reply-to")), " "))
end

"""
What the list shows: the emails that the block asks for, newest first, how
many emails are still to be read, and why there are none when Ladder has no
email. An email that's in two folders, as Gmail has them, is listed once.
"""
emails!(v::EmailsView) = begin
  e = editor(v)
  # The emails of every account are in the list
  ready = [m for m in mailers(e) if Mail.ready(m.account)]
  isempty(ready) &&
    return (rows=[], left=0, problem="Ladder has no email account yet. Press ⌘, and choose Email to give it one.")
  # The list is worked out again no more than once a second, however fast email comes in
  key = (v.lines, floor(Int, time()), length(EMAIL_PEOPLE))
  v.shown !== nothing && v.shown[1] == key && return v.shown[2]
  w = v.data
  found, left, read = Dict{String,Any}(), 0, 0
  for m in ready, b in Mail.nested(Mail.root(m.account))
    b.role in (:drafts, :junk, :trash) && continue
    for l in b.letters
      Posts.about(w, l.subject) || continue
      path = joinpath(b.path, l.file)
      fits = Posts.with(w, l.from * " " * l.to)
      if !fits && Posts.addressed(w)
        # The index has no addresses, so the top of the email's page is read: a few emails in each frame
        if !haskey(EMAIL_PEOPLE, path)
          read >= EMAILS_READ && (left += 1; continue)
          read += 1
        end
        fits = Posts.with(w, email_people(path))
      end
      fits || continue
      id = isempty(l.id) ? path : l.id
      # The copy in a folder of its own is the one that's listed, not the one in the folder of all email
      (haskey(found, id) && b.role == :all) || (found[id] = (path=path, who=l.out ? "To " * l.to : l.from, subject=l.subject, at=l.at, unread=Mail.unread(l)))
    end
  end
  rows = sort!(collect(values(found)), by=r -> r.at, rev=true)
  key = (key[1:2]..., length(EMAIL_PEOPLE))
  (v.shown = (key, (rows=rows, left=left, problem="")))[2]
end

describe(r::EmailLine) = begin
  rows = emails!(r.of).rows
  r.i <= length(rows) || return Box(height(0px))
  x = rows[r.i]
  Row(width(grow=grow), height(30px), padding(0px, 12px, 0px, 8px), child_gap=8px, Alignment.Center, clip=true, name="Email",
      background(ishovered(r) ? colours.hover : clear),
    # An email that isn't read has a dot
    Box(width(10px), height(grow=grow), Alignment.Center,
      (x.unread ? (Box(width(7px), height(7px), radius(3.5px), background(colours.accent)),) : ())...),
    Box(fixed(170px), Alignment.Start, clip=true, label(elide(x.who, 13px, 164px), 13px, weight=x.unread ? "Semibold" : "")),
    Box(width(grow=grow), Alignment.Start, clip=true, label(isempty(x.subject) ? "No subject" : x.subject, 13px, color=x.unread ? colours.ink : colours.dim)),
    Box(label(Mail.shortdate(x.at), 11px, color=colours.faint)))
end

cursor(::EmailLine) = :hand
cursor(::EmailsView) = :arrow

onkey(r::EmailLine, ::KeyPress{Keys.mouse_left}) = begin
  rows = emails!(r.of).rows
  r.i <= length(rows) ? visit!(editor(r.of), rows[r.i].path) : handled
end

describe(v::EmailsView) = begin
  e = editor(v)
  w = v.data
  found = emails!(v)
  # While emails are still to be read, the list is worked out again in the next frame
  found.left > 0 && redraw_in!(v, 0.02)
  with_theme(component_theme(e.zoom)) do
    isempty(found.problem) || return Column(block_look()..., clip=true, name="Emails",
      block_bar(Box(padding(6px, 0px), Icon("envelope", size=13px, color=colours.dim)), Box(label("Email", 12px, color=colours.dim)), Box(width(grow=grow)),
                block_button!(v, :settings, :settings, words="Email settings")),
      block_note(found.problem))
    isempty(w.with) && return Column(block_look()..., clip=true, name="Emails",
      block_note("Say who the emails are with. Move the caret into this block and write a name or an address, like with: sam@example.com."))
    words = Posts.summary(w, length(found.rows)) * (found.left > 0 ? "  ·  reading $(found.left) more" : "")
    bar = block_bar(Box(padding(6px, 0px), Icon("envelope", size=13px, color=colours.dim)), Box(label(words, 12px, color=colours.dim)), Box(width(grow=grow)),
      (isempty(found.rows) ? () : (block_button!(v, :reply, :reply, icon="reply", words="Reply", tip="Answer the newest of these emails"),))...,
      block_button!(v, :new, :new, icon="pencil-square", words="New email", tip="Write a new email" * (isempty(Posts.address(w)) ? "" : " to " * Posts.address(w))))
    shown = min(length(found.rows), EMAILS_MOST)
    Column(block_look()..., clip=true, name="Emails", bar,
      [block_part!(() -> EmailLine(of=v, i=i), v, (:row, i)) for i in 1:shown]...,
      (length(found.rows) > shown ? (block_note("And $(length(found.rows) - shown) older emails. Add words to the block's about: line to list fewer."),) : ())...,
      Box(height(shown > 0 ? 6px : 0px)))
  end
end

act!(v::EmailsView, action, w) = begin
  e = editor(v)
  action == :settings && return (mail_settings!(e); handled)
  m = mail_ready(e)
  m === nothing && return handled
  if action == :reply
    rows = emails!(v).rows
    isempty(rows) && return handled
    # The answer goes from the account that got the email
    draft = Mail.reply!(something(mail_owner(e, rows[1].path), m), rows[1].path)
    mail_window!(e, draft, front_matter(String.(split(read(draft, String), '\n'))) + 2)
  elseif action == :new
    to = Posts.address(v.data)
    mail_window!(e, Mail.draft!(m, to=to), isempty(to) ? 2 : 4)
  end
  handled
end

"The list as HTML: a table with a row for each email"
emails_html(e, v::EmailsView) = begin
  found = emails!(v)
  (isempty(found.problem) && !isempty(v.data.with)) || return nothing
  rows = ["<tr><td>$(escape(x.who))</td><td>$(escape(isempty(x.subject) ? "No subject" : x.subject))</td><td>$(escape(Mail.shortdate(x.at)))</td></tr>"
          for x in first(found.rows, EMAILS_MOST)]
  "<p><strong>$(escape(Posts.summary(v.data, length(found.rows))))</strong></p>" *
  (isempty(rows) ? "" : "\n<table>\n" * join(rows, "\n") * "\n</table>")
end

BLOCKS[EMAIL] = BlockKind("Emails", "envelope", EmailsView, emails_html)

# --- contacts ----------------------------------------------------------------------------------
#
# A code block in the language `contact` holds contacts: people and
# companies. contact.jl says how the block is written. Each contact shows as
# a card: a round picture, the name, the role and the company under it, and a
# row for each other detail. A block with nothing in it shows a card with a
# place for a name.
#
#   - A click on a row uses it. An email address starts a new email, a phone
#     number a call, an address shows in the Maps app, and a web address
#     opens in the browser. Each one goes through `BROWSER`, as the address
#     of a link card does, so a test opens nothing.
#   - While the mouse is over a row, a button at its right end copies its value.
#   - Two clicks on the name, the role, the company or the value of a row
#     change those words where they are, with no box round them. Return keeps
#     the change, esc leaves it, and a click somewhere else keeps it. An
#     emptied value takes its line out of the block. So a click on a row
#     waits a moment for a second click before it opens anything.
#   - While the mouse is over a card, two buttons show at its top right. The
#     + opens a menu of the details to add. The other one writes the contact
#     as a vCard file and opens the file, so the Contacts app asks to add it.
#   - While the mouse is over the block, a button under the last card adds a contact.
#   - A vCard file that's dropped on the page becomes a block of its
#     contacts, and one that's dropped on a block joins it. ⌘V does the same
#     with a contact that was copied in the Contacts app.
#   - A page that can't be changed, like an email, takes no changes. Its
#     rows still open and copy.

const CONTACT = Contacts.CONTACT
push!(BLOCK_ICONS, "person-vcard", "person", "building", "envelope", "telephone", "geo-alt", "globe", "card-text", "tag",
      "plus", "plus-circle", "person-plus", "copy", "check")
const CONTACT_WIDE = 420px   # how wide a card is at the usual size of the text, in a page with room for it
const CONTACT_FACE = 44px    # how wide the round picture is
const CONTACT_PAD = 12px     # the room inside a card's edge, and between the picture and the words
const CONTACT_NAME = 22px    # how tall the line of the name is
const CONTACT_LINE = 20px    # and each other line of a card
const CONTACT_WAIT = 0.35    # how many seconds a click on a row waits for a second click
const CONTACT_COPIED = 1.2   # how many seconds the button of a row shows that it copied
"The details that the + of a card adds: what the menu calls each, and its kind"
const CONTACT_MENU = [("Email", :email), ("Phone", :phone), ("Address", :address), ("Website", :web), ("Note", :note)]
"The icon of a row of each kind. A row of any other kind has a tag."
const CONTACT_ICONS = Dict(:email => "envelope", :phone => "telephone", :address => "geo-alt", :web => "globe", :note => "card-text", :company => "building")
"What the button of a row of each kind copies, as its tooltip says it"
const CONTACT_COPIES = Dict(:email => "the email address", :phone => "the phone number", :address => "the address", :web => "the web address", :note => "the note")

"What a `contact` block shows: a card for each contact of the block"
@def mutable struct ContactView <: SemanticUI
  n::Int = 0                               # its place among the page's blocks of contacts
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Vector{Contacts.Contact} = Contacts.Contact[]
  lines::Vector{String} = String[]         # the lines that `data` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its cards, their rows and buttons, and the field, kept between frames
  # What's being changed where it is, or nothing: the contact's place in the block, then the line of the
  # contact, or `:name` for its name, or the kind of a new detail, like `:email`
  editing::Any = nothing
  waiting::Any = nothing                   # a click on a row that opens something: when it was, the contact and the line
  clicked::Any = (0.0, nothing, 0.0, 0.0)  # when the last click was, what it was on and where
  copied::Any = (0.0, 0, 0)                # when a value was last copied, and its contact and its line
  menu::Int = 0                            # the card whose menu of details is open, or 0
end

"The card of one contact"
@def mutable struct ContactCard <: SemanticUI
  of::Any = nothing
  k::Int = 0
end
"The round picture of a card: the photo, the initials, or a building for a company"
@def mutable struct ContactFace <: SemanticUI
  of::Any = nothing
  k::Int = 0
  key::String = ""   # of the photo, for drawing, or "" when the card has none to show
end
"Words of a card that two clicks change where they are: the name, the role or the company"
@def mutable struct ContactWords <: SemanticUI
  of::Any = nothing
  k::Int = 0
  i::Any = :name       # the line of the contact, or `:name`
  room::px = 0px       # how wide the words can be
  tight::Bool = false  # other words follow them on their line, so the field is as wide as what's typed
end
"A row of a card: one detail, with its icon"
@def mutable struct ContactRow <: SemanticUI
  of::Any = nothing
  k::Int = 0
  i::Any = 0           # the line of the contact, or the kind of a new detail that's being typed
  room::px = 0px       # how wide the row is
end
"A small button of a card, with only an icon. A click does `contact_act!(view, action, window)`."
@def mutable struct ContactButton <: SemanticUI
  of::Any = nothing
  action::Any = (:none,)
  icon::String = ""
  tip::String = ""
  quiet::Bool = false   # clicked, so no tooltip until the mouse leaves it
end

"The field that takes the place of words of a card while you change them"
contact_input(v::ContactView) = block_part!(v, :edit) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"""
That field in a box with no border and no background, set to draw its text
`size` tall. `sizing` says how wide and how tall the box is.
"""
contact_field(v::ContactView, size, sizing...) = begin
  input = contact_input(v)
  input.color = colours.ink
  theme = component_theme(editor(v).zoom)
  # A size in points is a part of the theme's size
  input.font_size = (12 * num(size) / num(theme.size))pt
  with_theme(() -> Box(sizing..., input), theme)
end

"""
A part of a block of contacts that's kept between frames. `parent` is the part
that it's drawn in. So the mouse over a button of a row is over the row too,
and over the row's card.
"""
contact_part!(make, v::ContactView, key, parent) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, parent)
  node
end

contact_card!(v::ContactView, k) = contact_part!(() -> ContactCard(of=v, k=k), v, (:card, k), v)
contact_words!(v::ContactView, k, i) = contact_part!(() -> ContactWords(of=v, k=k, i=i), v, (:words, k, i), contact_card!(v, k))
contact_row!(v::ContactView, k, i) = contact_part!(() -> ContactRow(of=v, k=k, i=i), v, (:row, k, i), contact_card!(v, k))
"The button of the block that's kept for `action`, with what it shows now"
contact_button!(v::ContactView, action, icon, tip, parent) = begin
  b = contact_part!(() -> ContactButton(of=v), v, (:button, action), parent)
  b.action, b.icon, b.tip = action, icon, tip
  b
end

reread!(v::ContactView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Contacts.contacts(lines)
  # The line that was being changed can go, as when ⌘Z takes it back
  v.editing = v.waiting = nothing
  v
end

"True for contacts in a page that can't be changed, like an email. They take no changes."
locked(v::ContactView) = (b = editor(v).buf; readonly(b) || b.fixed)

"The contact at `k` of the block. A place after the last one has a contact with nothing in it: the one that a new name starts."
contact_of(v::ContactView, k::Int) = k in eachindex(v.data) ? v.data[k] : Contacts.Contact()

"How many cards the block shows: one for each contact, one for a block with none, and one more while a new contact gets its name"
contact_cards(v::ContactView) = max(1, length(v.data), v.editing === nothing ? 0 : v.editing[1])

"How wide a card is in the page: 420 px at the usual size of the text, and no wider than the page's text"
contact_wide(v::ContactView) = (e = editor(v); min(CONTACT_WIDE * e.zoom, e.width))

"""
Keep what the field holds: write it into the line that was being changed, as
the name, or as a new detail. A contact that's left with no lines goes out of
the block. It's true when that changed the block.
"""
settle!(v::ContactView) = begin
  v.editing === nothing && return false
  k, what = v.editing
  text = contact_input(v).text
  v.editing = nothing
  locked(v) && return false
  list = Contacts.contacts(v.lines)
  fresh = k > length(list)
  c = fresh ? Contacts.Contact() : list[k]
  changed = what === :name ? Contacts.rename!(c, text) : what isa Symbol ? Contacts.add!(c, what, text) : Contacts.set!(c, what, text)
  changed || return false
  fresh && Contacts.add!(list, c)
  isempty(c.lines) && Contacts.remove!(list, k)
  write_block!(v, CONTACT, Contacts.written(list))
  true
end

"""
Put the field in the place of words of contact `k`, with the words in it and
selected. `what` is the line of the contact, or `:name`, or the kind of a new
detail, which starts with nothing in it.
"""
change!(v::ContactView, k::Int, what) = begin
  locked(v) && return handled
  c = contact_of(v, k)
  words = what === :name ? Contacts.title(c) : what isa Symbol ? "" : what in eachindex(c.lines) ? c.lines[what].value : nothing
  words === nothing && return handled
  input = contact_input(v)
  input.text = words
  input.anchor, input.cursor, input.scroll = 0, length(words), 0px
  input.placeholder = what === :name ? "Name" : what isa Symbol ? first(CONTACT_MENU[findfirst(m -> last(m) == what, CONTACT_MENU)]) : ""
  v.editing, v.waiting = (k, what), nothing
  v.clicked = (0.0, nothing, 0.0, 0.0)
  # The press isn't a click on the page's text, so the text doesn't select when the mouse moves
  e = editor(v)
  e.clicked = (e.clicked[1], e.clicked[2], 0)
  focus(input)
  handled
end

"Note a click on `what`. True when it's the second of two clicks in one place."
contact_twice!(v::ContactView, what, w) = begin
  at, on, x, y = v.clicked
  mx, my = num(w.mouse[1]), num(w.mouse[2])
  v.clicked = (time(), what, mx, my)
  time() - at < CONTACT_WAIT && on == what && hypot(mx - x, my - y) < 4
end

"True when the block can open something now. A window that isn't on the screen opens nothing, unless a test put its own function in place of the browser."
contact_opens(v::ContactView) = on_screen(v) || BROWSER[] !== open_url

"Open what line `i` of contact `k` names: a new email, a call, the Maps app or the browser"
use_row!(v::ContactView, k, i) = begin
  c = contact_of(v, k)
  i in eachindex(c.lines) || return nothing
  to = Contacts.link(c.lines[i])
  to === nothing || !contact_opens(v) || BROWSER[](to)
  nothing
end

"Write contact `k` as a vCard file in a folder for temporary files, and open the file, so the Contacts app asks to add it"
keep_contact!(v::ContactView, k) = begin
  c = contact_of(v, k)
  (Contacts.isblank(c) || !contact_opens(v)) && return nothing
  path = joinpath(mktempdir(), Contacts.filename(c))
  write(path, Contacts.vcard(c))
  BROWSER[](path)
  nothing
end

"Do what a button of a card does"
contact_act!(v::ContactView, action, w) = begin
  kind = action[1]
  # What was being changed is kept first. A line that went with it leaves the others in new places.
  n = length(v.lines)
  settle!(v)
  length(v.lines) == n || kind == :new || return handled
  if kind == :copy
    c = contact_of(v, action[2])
    if action[3] in eachindex(c.lines)
      clipboard!(w, c.lines[action[3]].value)
      v.copied = (time(), action[2], action[3])
      redraw_in!(v, CONTACT_COPIED + 0.05)   # so that the button shows its own icon again
    end
  elseif kind == :more
    # The menu hangs under the button, which stays while the menu is open
    k = action[2]
    v.menu = k
    show_menu!(w, [first(m) for m in CONTACT_MENU], w.mouse[1], w.mouse[2], 150px, theme=menu_theme(), item_height=28px, lift=3.0,
               under=v.parts[(:button, action)], gap=4px,
               onselect=j -> (v.menu = 0; j in eachindex(CONTACT_MENU) && change!(v, k, last(CONTACT_MENU[j])); nothing))
  elseif kind == :keep
    keep_contact!(v, action[2])
  elseif kind == :new
    change!(v, length(v.data) + 1, :name)
  end
  handled
end

"""
What happens to a block of contacts in each frame, before the page is laid
out. A click somewhere else keeps what the field holds. A click on a row
that no second click followed opens what the row names.
"""
block_tick!(v::ContactView) = begin
  w = window_of(v)
  typing = w !== nothing && w.focus === contact_input(v)
  v.editing === nothing || typing || settle!(v)
  # The field went, as when ⌘Z took its line back, so the page has the keyboard again
  v.editing === nothing && typing && focus(editor(v))
  if v.waiting !== nothing && time() - v.waiting[1] >= CONTACT_WAIT
    _, k, i = v.waiting
    v.waiting = nothing
    use_row!(v, k, i)
  end
  v
end

# The keys that the field has no use for come here. Return keeps what's typed, and esc leaves the words as they were.
onkey(v::ContactView, ev::KeyPress{Keys.enter}) = ev.window.focus === contact_input(v) ? (settle!(v); focus(editor(v)); handled) : nothing
onkey(v::ContactView, ev::KeyPress{Keys.escape}) = ev.window.focus === contact_input(v) ? (v.editing = nothing; focus(editor(v)); handled) : nothing

# Return, while the caret is on the block as a whole, starts on the name of its first contact
keyboard_part(v::ContactView) = locked(v) ? nothing : (v.editing === nothing && change!(v, 1, :name); contact_input(v))

describe(b::ContactButton) = begin
  ishovered(b) || (b.quiet = false)
  z = editor(b.of).zoom
  Box(fixed(20px * z), height(20px * z), radius(5px * z), Alignment.Center, name="Button", background(ishovered(b) ? colours.active : clear),
      Row(Alignment.Center, Icon(b.icon, size=13px * z, color=colours.dim)))
end

cursor(::ContactButton) = :hand
onmouse(b::ContactButton, ev::MouseMove) = begin
  (b.quiet || isempty(b.tip)) && return
  show_tooltip!(ev.window, tip_label(b.tip), b, placement=:bottom, gap=6px)
end
onkey(b::ContactButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  contact_act!(b.of, b.action, ev.window)
end

"""
The key, for drawing, of the picture that a contact names, or "" while there's
none to show. A file is named from the page's folder, as a picture line names
one. A picture from the web is fetched in the background and kept, as the
picture of a link card is. An email asks a web site for nothing.
"""
contact_photo(e, src::AbstractString) = begin
  isempty(src) && return ""
  occursin(r"^https?://"i, src) && return Mail.isemail(e.buf.path) ? "" : card_picture(e, src)
  something(picture_key(abspath(docdir(e), expanduser(unescaped(src)))), "")
end

describe(f::ContactFace) = begin
  v = f.of
  e = editor(v)
  z = e.zoom
  c = contact_of(v, f.k)
  side = CONTACT_FACE * z
  f.key = contact_photo(e, Contacts.photo(c))
  # With no photo: a building for a company, the initials of a person, and a head for a contact with no name yet
  letters = Contacts.initials(Contacts.title(c))
  mark = !isempty(f.key) ? () : Contacts.iscompany(c) ? (Icon("building", size=20px * z, color=colours.accent),) :
         isempty(letters) ? (Icon("person", size=22px * z, color=colours.faint),) :
         (label(letters, 16px * z, color=colours.accent, weight="Semibold"),)
  Box(fixed(side), height(side), radius(side / 2), Alignment.Center, name="Picture",
      background(isempty(letters) && !Contacts.iscompany(c) ? colours.hover : tint(colours.accent, 0.13)), Row(Alignment.Center, mark...))
end

# The photo fills the circle. What doesn't fit in a square is cut off at its sides, or at its top and bottom.
draw(ctx, size, ui::ConcreteRect, f::ContactFace) = begin
  isempty(f.key) && return
  source = try image_source(f.key) catch; return end
  w, h = Float64(source.width), Float64(source.height)
  side = min(w, h)
  side > 0 || return
  with_round_clip(ctx, ui.left, ui.top, ui.width, ui.height, ui.width / 2) do
    paint_picture(ctx, source.raw, ((w - side) / 2, (h - side) / 2, side, side), (num(ui.left), num(ui.top), num(ui.width), num(ui.height)))
  end
end

describe(t::ContactWords) = begin
  v = t.of
  z = editor(v).zoom
  c = contact_of(v, t.k)
  name = t.i === :name
  size, tall = name ? (15px * z, CONTACT_NAME * z) : (13px * z, CONTACT_LINE * z)
  if v.editing == (t.k, t.i)
    # The words are changed where they are, with no box round them. A field with words after it is as wide as what's typed.
    field = contact_input(v)
    typed = measure(Face(SANS, "", size, colours.ink, false), isempty(field.text) ? field.placeholder : field.text) + 4px * z
    wide = t.tight ? fixed(clamp(typed, 24px * z, max(24px * z, t.room))) : width(grow=grow)
    return contact_field(v, size, wide, height(tall))
  end
  words = name ? Contacts.title(c) : t.i in eachindex(c.lines) ? c.lines[t.i].value : ""
  face = Face(SANS, name ? "Semibold" : "", size, name ? colours.ink : colours.dim, false)
  # A contact with no name says where its name goes
  shown, colour = isempty(words) && name ? (on_paper(editor(v)) || locked(v) ? "" : "Name", colours.faint) : (shortened(face, words, t.room), face.color)
  Row(height(tall), Box(label(shown, size, color=colour, weight=face.style)))
end

cursor(t::ContactWords) = :arrow
# Two clicks change the words. A contact with no name takes its name at the first click. Any other click goes on to the page.
onkey(t::ContactWords, ev::KeyPress{Keys.mouse_left}) = begin
  v = t.of
  (held(v, Keys.opt) || locked(v) || v.editing == (t.k, t.i)) && return nothing
  twice = contact_twice!(v, (t.k, t.i), ev.window)
  settle!(v) && return nothing   # the click kept what was being changed, and the lines aren't where they were
  nameless = t.i === :name && isempty(Contacts.title(contact_of(v, t.k)))
  twice || nameless ? change!(v, t.k, t.i) : nothing
end

"The lines that the value of the detail `d` takes in a row with `room` for it. An address and a note wrap. Anything else is one line."
contact_lines(d::Contacts.Detail, face::Face, room) =
  d.kind in (:email, :web, :phone) || isempty(d.value) ? [d.value] : wrapped(face, d.value, num(room))

describe(r::ContactRow) = begin
  v, k = r.of, r.k
  e = editor(v)
  z = e.zoom
  c = contact_of(v, k)
  # A new detail that's being typed has no line yet
  d = r.i isa Symbol ? Contacts.Detail(r.i, "", "") : r.i in eachindex(c.lines) ? c.lines[r.i] : nothing
  d === nothing && return Box(height(0px))
  size, line, gap = 13px * z, CONTACT_LINE * z, 7px * z
  editing = v.editing == (k, r.i)
  to = Contacts.link(d)
  face = Face(SANS, "", size, to === nothing ? colours.ink : colours.accent, false)
  grey = Face(SANS, "", size, colours.dim, false)
  # The label of a row that has one is cut short before it takes more than a third of the row
  caption = shortened(grey, Contacts.caption(d), r.room / 3)
  room = r.room - 15px * z - gap - (isempty(caption) ? 0px : measure(grey, caption) + gap) - 20px * z - gap
  lines = contact_lines(d, face, room)
  cell(words, colour) = Row(height(line), Box(label(words, size, color=colour)))
  value = if editing
    # The words are changed where they are, with no box round them. The row stays as tall as it was.
    Column(width(grow=grow), Alignment.Start, contact_field(v, size, width(grow=grow), height(line)),
           (length(lines) > 1 ? (Box(height(line * (length(lines) - 1))),) : ())...)
  else
    Column(width(grow=grow), Alignment.Start, (cell(shortened(face, words, room), face.color) for words in lines)...)
  end
  over = ishovered(r) && !editing && !isempty(d.value) && !on_paper(e)
  done = v.copied[2:3] == (k, r.i) && time() - v.copied[1] < CONTACT_COPIED
  button = over || done ? (contact_button!(v, (:copy, k, r.i), done ? "check" : "copy", "Copy " * get(CONTACT_COPIES, d.kind, "this"), r),) : ()
  Row(width(grow=grow), Alignment.Start, child_gap=gap, name="Detail",
    Box(fixed(15px * z), height(line), Alignment.Center, Row(Alignment.Center, Icon(get(CONTACT_ICONS, d.kind, "tag"), size=13px * z, color=colours.dim))),
    (isempty(caption) ? () : (cell(caption, colours.dim),))...,
    value,
    Box(fixed(20px * z), height(line), Alignment.Center, button...))
end

cursor(r::ContactRow) = begin
  c = contact_of(r.of, r.k)
  r.i in eachindex(c.lines) && Contacts.link(c.lines[r.i]) !== nothing ? :hand : :arrow
end

# A click on a row opens what the row names, once it's known that no second click comes. Two clicks change
# the row's value. The click goes on to the page, which takes the keyboard back from the field.
onkey(r::ContactRow, ev::KeyPress{Keys.mouse_left}) = begin
  v = r.of
  (held(v, Keys.opt) || v.editing == (r.k, r.i)) && return nothing
  twice = contact_twice!(v, (r.k, r.i), ev.window)
  settle!(v) && return nothing   # the click kept what was being changed, and the lines aren't where they were
  c = contact_of(v, r.k)
  r.i in eachindex(c.lines) || return nothing
  # A page that can't be changed has no second click to wait for
  locked(v) && return use_row!(v, r.k, r.i)
  twice && return change!(v, r.k, r.i)
  if Contacts.link(c.lines[r.i]) !== nothing
    v.waiting = (time(), r.k, r.i)
    redraw_in!(v, CONTACT_WAIT + 0.02)
  end
  nothing
end

describe(card::ContactCard) = begin
  v, k = card.of, card.k
  e = editor(v)
  z = e.zoom
  c = contact_of(v, k)
  pad = CONTACT_PAD * z
  inner = contact_wide(v) - 2pad - 2px - CONTACT_FACE * z - pad   # how wide the column beside the picture is
  over = !on_paper(e) && (ishovered(card) || v.menu == k)
  # The buttons have their room at the top right, so the name isn't cut shorter when they show
  buttons = 44px * z
  name = contact_words!(v, k, :name)
  name.room, name.tight = inner - buttons - 4px * z, false
  filler(node) = v.editing == (k, node.i) && !node.tight ? () : (Box(width(grow=grow)),)
  head = Row(width(grow=grow), height(CONTACT_NAME * z), justify=Alignment.Start, name, filler(name)...,
    Row(fixed(buttons), height(20px * z), child_gap=2px * z, justify=Alignment.End,
      (over && !locked(v) ? (contact_button!(v, (:more, k), "plus", "Add a detail", card),) : ())...,
      (over && !Contacts.isblank(c) ? (contact_button!(v, (:keep, k), "person-plus", "Add to Contacts", card),) : ())...))
  # Under the name of a person: the role, a comma, the company
  role, firm = Contacts.under(c)
  grey = Face(SANS, "", 13px * z, colours.dim, false)
  both = role !== nothing && firm !== nothing
  comma = both ? measure(grey, ",") + 4px * z : 0px
  under = Any[]
  taken = 0px
  if role !== nothing
    t = contact_words!(v, k, role)
    # The company keeps half of the line at the least
    t.tight, t.room = both, both ? max(inner / 2, inner - comma - measure(grey, c.lines[firm].value)) : inner
    taken = min(measure(grey, c.lines[role].value), t.room)
    push!(under, t)
    both && push!(under, Row(height(CONTACT_LINE * z), Box(label(",", 13px * z, color=colours.dim))), Box(width(4px * z)))
  end
  if firm !== nothing
    t = contact_words!(v, k, firm)
    t.tight, t.room = false, inner - taken - comma
    push!(under, t)
  end
  tag = isempty(under) ? () : (Row(width(grow=grow), height(CONTACT_LINE * z), justify=Alignment.Start, under..., filler(under[end])...),)
  rows = Any[contact_row!(v, k, i) for i in Contacts.rows(c)]
  # A new detail that's being typed is a row at the end
  v.editing !== nothing && v.editing[1] == k && v.editing[2] isa Symbol && v.editing[2] !== :name && push!(rows, contact_row!(v, k, v.editing[2]))
  foreach(r -> r.room = inner, rows)
  # A card with only a name, or a name and the line under it, has them level with the middle of the picture
  Row(fixed(contact_wide(v)), isempty(rows) ? Alignment.Center : Alignment.Start, padding(pad), child_gap=pad, radius(8px), border(1px, :solid, colours.line),
      background(colours.block), clip=true, name="Contact",
    contact_part!(() -> ContactFace(of=v, k=k), v, (:face, k), card),
    Column(width(grow=grow), Alignment.Start, head, tag..., (isempty(rows) ? () : (Box(height(5px * z)),))..., rows...))
end

cursor(::ContactCard) = :arrow
cursor(::ContactView) = :arrow

describe(v::ContactView) = begin
  e = editor(v)
  z = e.zoom
  wide = contact_wide(v)
  cards = [contact_card!(v, k) for k in 1:contact_cards(v)]
  # The button that adds a contact has its room under the last card, so the page doesn't move when it shows.
  # It's there while the mouse is over the block, and not while a new contact gets its name.
  adds = !locked(v) && !on_paper(e)
  starting = v.editing !== nothing && v.editing[1] > length(v.data)
  more = !adds ? () : (Row(fixed(wide), height(22px * z), justify=Alignment.Start,
    (ishovered(v) && !starting && !isempty(v.data) ? (contact_button!(v, (:new,), "plus-circle", "Add a contact", v),) : ())...),)
  Box(width(grow=grow), Alignment.Start,
    Column(fixed(wide), Alignment.Start, name="Contacts",
      Column(fixed(wide), Alignment.Start, child_gap=8px * z, cards...), more...))
end

"The contacts of the block as HTML: a card for each one, with the class names of the h-card microformat"
contact_html(e, v::ContactView) = Contacts.markup(v.data)

BLOCKS[CONTACT] = BlockKind("Contact", "person-vcard", ContactView, contact_html)

# --- contacts from a vCard ---------------------------------------------------------------------
#
# The Contacts app writes a contact as a vCard: a .vcf file, or text that
# starts with BEGIN:VCARD. contact.jl reads one. A vCard file that's dropped
# on the page, or pasted, goes in as a block of its contacts.

"The contacts that the file at `path` holds, when it's a vCard file. Any other file has none, and so has one that can't be read."
file_contacts(path::AbstractString) = begin
  (isfile(path) && lowercase(splitext(path)[2]) in (".vcf", ".vcard")) || return Contacts.Contact[]
  try Contacts.from_vcard(read(path, String)) catch; Contacts.Contact[] end
end

"The contacts of the vCard files among `paths`, and the paths that are left"
split_contacts(paths) = begin
  list = Contacts.Contact[]
  rest = filter(paths) do p
    found = file_contacts(p)
    foreach(c -> Contacts.add!(list, c), found)
    isempty(found)
  end
  (list, rest)
end

"The block of contacts under the mouse, or nothing. Only a block that the page shows now is where it was last drawn."
contacts_at(e, w) = begin
  x, y = w.mouse
  for it in view(e.layout, intersect(e.shown, eachindex(e.layout)))
    node = it.content isa Live ? it.content.node : nothing
    node isa ContactView || continue
    r = rect(node)
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return node
  end
  nothing
end

"Add `list` to the contacts of the block, each one after an empty line. It's true when the block took them."
add_contacts!(v::ContactView, list) = begin
  (isempty(list) || locked(v)) && return false
  settle!(v)
  all = Contacts.contacts(v.lines)
  foreach(c -> Contacts.add!(all, c), list)
  write_block!(v, CONTACT, Contacts.written(all))
  true
end

"""
Put the contacts of `list` into the text at `at`, and give the place for the
caret. In a block of contacts, they join the block. Anywhere else, they go in
as a new block under the block that `at` is in, as a picture that's dropped
does, and the caret goes to an empty line under it.
"""
put_contacts!(e, list, at::Pos) = begin
  b = e.buf
  (isempty(list) || readonly(b) || b.fixed) && return at
  ks = kinds(b)
  if ks[at[1]].kind in (Kind.fence, Kind.code)
    s, t = codeblock(b, at[1])
    if ks[s].lang == CONTACT && t > s && ks[t].kind == Kind.fence && ks[t].level == 1
      all = Contacts.contacts(b.lines[s+1:t-1])
      foreach(c -> Contacts.add!(all, c), list)
      edit!(b, line_end(b, s), line_end(b, t - 1), "\n" * join(Contacts.written(all), "\n"))
      return (s, 0)
    end
  end
  under = block_end(b, at[1])
  empty = isempty(strip(b.lines[under]))
  block = ["```$CONTACT"; Contacts.written(collect(Contacts.Contact, list)); "```"]
  # An empty line goes under the block, for the caret, unless the page has one there
  spare = under < length(b.lines) && isempty(strip(b.lines[under+1]))
  edit!(b, empty ? (under, 0) : line_end(b, under), line_end(b, under), (empty ? "" : "\n\n") * join(block, "\n") * (spare ? "" : "\n"))
  (under + (empty ? 0 : 2) + length(block), 0)
end

"Put the contacts of `list` in the page at the caret, in place of what's selected, as ⌘V does with a contact that was copied"
paste_contacts!(e, list) = begin
  b = e.buf
  selecting(b) && type!(e, "")
  b.caret = b.anchor = put_contacts!(e, list, settle(b, b.caret))
  focus(e)
  touch!(e)
end

"""
The contacts that ⌘V pastes, or none: the clipboard holds the text of a
vCard, or a contact that was copied in the Contacts app. In a code block of
another language, a vCard is pasted as its text.
"""
copied_contacts(e, text::AbstractString) = begin
  b = e.buf
  b.view == :markdown || return Contacts.Contact[]   # a file of code has no blocks
  k = kinds(b)[b.caret[1]]
  k.kind == Kind.code && kinds(b)[codeblock(b, b.caret[1])[1]].lang != CONTACT && return Contacts.Contact[]
  card = Contacts.isvcard(text) ? text : Sys.isapple() ? Pasteboard.vcard() : ""
  try Contacts.from_vcard(card) catch; Contacts.Contact[] end
end

# --- a signature -------------------------------------------------------------------------------
#
# A code block in the language `signature` is a place where a person signs
# the page with the mouse or the trackpad. signature.jl says how the block is
# written. The block shows a box with a line to sign on, and under it the
# name of who signs. A block with no name has a field there to type it in.
#
#   - Press in the box and drag to draw. Each stroke is a line of the block,
#     so the file holds the signature, and ⌘Z takes back the last stroke.
#   - The first stroke writes the day and the time. From then on the block
#     says who signed and on which day.
#   - A stroke that leaves the box goes on when the mouse comes back. The
#     page's text doesn't select meanwhile, and the page doesn't scroll.
#   - While the mouse is over a signed block, a Clear button shows. It takes
#     the strokes and the day away, and ⌘Z brings them back.
#   - A page that can't be changed, like an email, takes no strokes.

const SIGNATURE = Signatures.SIGNATURE
push!(BLOCK_ICONS, "pen")
const SIGN_STEP = 1.0   # how far the mouse moves, in the box's own measure, before a stroke gets a new place
"The clock that says when a block is signed. A test puts its own clock here."
const sign_clock = Ref{Function}(Dates.now)

"What a `signature` block shows: a box to sign in, and the name of who signs"
@def mutable struct SignatureView <: SemanticUI
  n::Int = 0                               # its place among the page's signatures
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Signatures.Signature = Signatures.Signature()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  draft::Any = nothing                     # the places of the stroke that's being drawn, or nothing
  asked::Bool = false                      # the block had no name once, so its field takes the name
  stay::px = 0px                           # how far the page was scrolled when the stroke started
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the box was last drawn in the window
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its box, its field and its button, kept between frames
end

"The box of a signature that's drawn in"
@def mutable struct SignArea <: SemanticUI
  of::Any = nothing
end

sign_area(v::SignatureView) = block_part!(() -> SignArea(of=v), v, :area)

"The text field that takes the name of who signs"
signer_input(v::SignatureView) = block_part!(v, :input) do
  TextInput(placeholder="Type your name", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::SignatureView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Signatures.signature(lines)
  # The field shows the name that the block has, as it does after ⌘Z takes some of it back
  i = signer_input(v)
  strip(i.text) == v.data.name || (i.text = v.data.name; i.anchor = i.cursor = length(i.text))
  v
end

"True for a signature in a page that can't be changed, like an email. It takes no strokes."
locked(v::SignatureView) = (b = editor(v).buf; readonly(b) || b.fixed)

"True while the page is drawn for paper. Printing puts the caret on no line."
on_paper(v::SignatureView) = editor(v).buf.caret[1] == 0

"""
True when a field under the box takes the name: the block has no name, or it
had none and the name was typed in the field. A signed block has no field.
"""
asks(v::SignatureView) = begin
  isempty(v.data.name) && (v.asked = true)
  v.asked && !Signatures.issigned(v.data) && !locked(v) && !on_paper(v)
end

"How wide the box is in the page: 420 px at the usual size of the text, and no wider than the page's text"
sign_wide(v::SignatureView) = (e = editor(v); min(px(Signatures.WIDE * e.zoom), e.width))

"How many px of the window one of the box's own measure is"
sign_scale(v::SignatureView) = v.box[3] > 0 ? v.box[3] / Signatures.WIDE : num(sign_wide(v)) / Signatures.WIDE

"The place in the box that's at `pos` in the window. A place outside the box has numbers that are outside it."
sign_place(v::SignatureView, pos) = (s = sign_scale(v); ((num(pos[1]) - v.box[1]) / s, (num(pos[2]) - v.box[2]) / s))

describe(a::SignArea) = begin
  wide = sign_wide(a.of)
  Box(fixed(wide), height(wide * (Signatures.TALL / Signatures.WIDE)), radius(8px), border(1px, :solid, colours.line),
      background(takeoff_back()), name="Box to sign in")
end

draw(ctx, size, ui::ConcreteRect, a::SignArea) = begin
  v = a.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  v.box[3] > 0 || return
  s = sign_scale(v)
  at(p) = (v.box[1] + p[1] * s, v.box[2] + p[2] * s)
  with_round_clip(ctx, ui.left, ui.top, ui.width, ui.height, 8px) do
    # The line to sign on, and the ✕ at its left end, as paper forms have
    trace(ctx, [at((Signatures.EDGE, Signatures.LINE)), at((Signatures.WIDE - Signatures.EDGE, Signatures.LINE))], colours.marker, 1.0)
    foreach(((from, to),) -> trace(ctx, [at(from), at(to)], colours.dim, max(1.0, 1.5s)), Signatures.CROSS)
    # The words go with the first stroke. A page that takes no strokes doesn't ask for one.
    if !Signatures.issigned(v.data) && v.draft === nothing && !locked(v)
      face = Face(SANS, "", 13px * editor(v).zoom, colours.faint, false)
      write_ink(ctx, "Sign here", v.box[1] + (v.box[3] - num(measure(face, "Sign here"))) / 2, at((0.0, Signatures.LINE - 12))[2], face)
    end
    # The ink is the colour of the page's text, with round ends
    paint = ink(colours.ink, max(1.2, Signatures.INK * s))
    foreach(points -> draw_curve(ctx, at.(points), paint), v.data.strokes)
    v.draft === nothing || draw_curve(ctx, at.(v.draft), paint)
    Skia.sk_paint_delete(paint)
  end
end

cursor(a::SignArea) = locked(a.of) ? :arrow : :crosshair
cursor(::SignatureView) = :arrow

# A press in the box starts a stroke. The click goes on to the page, which takes the keyboard back from the
# name's field. With ⌥ held the page shows the block's lines, and a page that can't be changed takes no strokes.
onkey(a::SignArea, ev::KeyPress{Keys.mouse_left}) = begin
  v = a.of
  (held(v, Keys.opt) || locked(v) || v.box[3] <= 0) && return nothing
  v.draft === nothing || drop!(v)   # a stroke that no frame has taken yet
  v.draft = Signatures.Place[sign_place(v, ev.window.mouse)]
  v.stay = editor(v).scroll.offset
  nothing
end

# UI.jl gives the box each move of the mouse while its button is down, in the box or out of it
onmouse(a::SignArea, ev::MouseMove) = begin
  v = a.of
  v.draft === nothing && return nothing
  Keys.mouse_left in ev.window.keys || return handled
  p = sign_place(v, ev.position)
  hypot((p .- v.draft[end])...) >= SIGN_STEP && push!(v.draft, p)
  handled   # the drag is the signature's, so the page's text doesn't select
end

# The wheel doesn't scroll the page under a stroke that's being drawn
onscroll(a::SignArea, ::MouseScroll) = a.of.draft === nothing ? nothing : handled

"The mouse let go. The stroke that was drawn joins the signature, and the first stroke writes the day and the time."
drop!(v::SignatureView) = begin
  points = v.draft
  v.draft = nothing
  points === nothing && return v
  Signatures.sign!(v.data, points, sign_clock[]()) && write_block!(v, SIGNATURE, Signatures.written(v.data))
  v
end

block_tick!(v::SignatureView) = begin
  if v.draft !== nothing
    # The page stays where it was while a stroke is drawn, whatever scrolls it
    held(v, Keys.mouse_left) ? (editor(v).scroll.offset = v.stay) : drop!(v)
  end
  # What was typed in the field is written into the block as the name
  name = String(strip(signer_input(v).text))
  name == v.data.name && return v
  v.data.name = name
  write_block!(v, SIGNATURE, Signatures.written(v.data), typing=true)
end

describe(v::SignatureView) = begin
  e = editor(v)
  s = v.data
  signed = Signatures.issigned(s)
  input = signer_input(v)
  input.color = colours.ink
  w = window_of(v)
  typing = w !== nothing && w.focus === input
  with_theme(component_theme(e.zoom)) do
    # Under the box: who signed and when, or the field that takes the name, or the name. The words are
    # bigger in a page whose text is bigger, as the box is.
    size = 13px * e.zoom
    under = signed ? (Box(width(grow=grow), Text(Signatures.caption(s), size=size, family=SANS, color=colours.dim, wrap=WrapMode.words)),) :
            asks(v) ? (Box(fixed(min(sign_wide(v), 240px * e.zoom)), height(28px * e.zoom), padding(9px, 0px), radius(6px), background(colours.bg),
                           border(1px, :solid, typing ? colours.accent : colours.line), input), Box(width(grow=grow))) :
            (Box(width(grow=grow), Text(s.name, size=size, family=SANS, subfamily="Medium", color=colours.ink, wrap=WrapMode.words)),)
    # The Clear button shows while the mouse is over a signed block, and never on paper
    clear = signed && ishovered(v) && v.draft === nothing && !locked(v) && !on_paper(v) ?
      (block_button!(v, :clear, :clear, words="Clear", tip="Take the signature away"),) : ()
    Box(width(grow=grow), Alignment.Start,
      Column(fixed(sign_wide(v)), Alignment.Start, child_gap=6px, name="Signature",
        sign_area(v),
        Row(width(grow=grow), height(min=26px), child_gap=8px, Alignment.Center, under..., clear...)))
  end
end

# Clear takes the strokes and the day away in one change, so one ⌘Z brings them back
act!(v::SignatureView, action, w) = begin
  action == :clear || return handled
  Signatures.clear!(v.data)
  write_block!(v, SIGNATURE, Signatures.written(v.data))
  handled
end

# Return in the name's field gives the keyboard back to the page
onkey(v::SignatureView, ::KeyPress{Keys.enter}) = (focus(editor(v)); handled)

"The signature as HTML: a picture of the box and its strokes, with who signed and when under it"
signature_html(e, v::SignatureView) = begin
  s = v.data
  picture = Signatures.svg(s, ink="#2b2622", line="#d8d0bd", mark="#6b6259")
  under = Signatures.issigned(s) ? Signatures.caption(s) : s.name
  "<div class=\"diagram\">\n$picture\n</div>" *
  (isempty(under) ? "" : "\n<p style=\"margin-top: -0.5em; font-size: 0.88em; color: #6b6259\">$(escape(under))</p>")
end

BLOCKS[SIGNATURE] = BlockKind("Signature", "pen", SignatureView, signature_html)
# --- a link card -------------------------------------------------------------------------------
#
# A line that holds only the address of a web page, written as a picture's
# is, like ![Julia](https://julialang.org), shows a card: the page's title,
# two lines of its description, its picture, and the name of its site beside
# the site's icon. The line's own text shows again while the caret is on it,
# as a picture's does. A click on the card with ⌘ held opens its address in
# the browser. In a page that's never changed, a click opens it with no key
# held. Any other click puts the caret on the line.
#
# What's at the address decides what the line shows. An address whose name
# ends as a picture's, a video's, a sound's or a table's does, like .png, shows
# that, and Ladder asks for no card. For any other address, Ladder gets the
# start of what's there, in the background. A web page shows as a card.
# Anything else, like a picture whose address doesn't end in .png, shows as a
# picture. Until Ladder knows, the line shows a card with the address.
#
# Ladder reads what the page says of itself. See linkcard.jl. It keeps that,
# and the picture, in a folder of the Mac's caches, so the card shows at once
# the next time, and with no network. When the page can't be had, the card
# shows the address. Ladder asks the web for nothing in a window that isn't
# on the screen. An email shows no cards: each such line in it is a picture.

push!(BLOCK_ICONS, "globe")

"What opens the address of a card: the browser. A test puts its own function here."
const BROWSER = Ref{Function}(open_url)

"The folder that keeps what the cards read from the web, and their pictures"
cards_dir() = isempty(MEDIA_CACHE[]) ? joinpath(homedir(), "Library", "Caches", "Ladder", "cards") : joinpath(MEDIA_CACHE[], "cards")

"A card that a line of the page shows: what the web page at the line's address says of itself"
@def mutable struct LinkCard <: SemanticUI
  line::Int = 0
  words::String = ""     # the line's words for the card, between its [ and ], which show while the page has no title
  card::Cards.Card = Cards.Card("")
  picture::String = ""   # the key of the page's picture, for an Image, or "" while there's none
  icon::String = ""      # and the key of the site's icon
end

# The sizes of a card's title, of its description and of the name of its site, as parts of the size of the page's text
const CARD_TITLE, CARD_WORDS, CARD_SOURCE = 0.92, 0.8, 0.74
const CARD_LINE = 1.36   # how tall a line of a card is, as a part of the size of its text
const CARD_PAD = 0.65    # the room inside a card's edge, as a part of the size of the page's text

"How tall a card is in a page whose text is `s` tall. Every card is as tall as the next, so the page's text doesn't move when a card fills in."
card_tall(s) = s * (2CARD_PAD + CARD_LINE * (CARD_TITLE + 2CARD_WORDS + CARD_SOURCE) + 0.45)

"`words` cut short with … so that they're no wider than `room` in `face`"
shortened(face::Face, words::AbstractString, room) = begin
  (room <= 0px || measure(face, words) <= room) && return String(words)
  cs = collect(words)
  lo, hi = 0, length(cs)
  while lo < hi
    mid = (lo + hi + 1) ÷ 2
    measure(face, rstrip(String(cs[1:mid])) * "…") <= room ? (lo = mid) : (hi = mid - 1)
  end
  rstrip(String(cs[1:lo])) * "…"
end

"The picture with the key `key` in a box `wide` by `tall`. The picture fills the box, and the box cuts off what doesn't fit."
covered(key, wide, tall) = begin
  aspect = image_aspect(key)
  w, h = aspect > wide / tall ? (tall * aspect, tall) : (wide, wide / aspect)
  Box(fixed(wide), height(tall), radius(6px), clip=true, Image(key, fixed(w), height(h)))
end

"""
True when Ladder can ask the web for what a card shows: the page isn't an
email, and its window is on the screen. A window that a test makes isn't, so a
test asks the web for nothing, unless it put its own function in place of `curl`.
"""
online(e) = !Mail.isemail(e.buf.path) && (Cards.getter[] !== Cards.curl || (w = window_of(e); w !== nothing && !isempty(w.glfw)))

"The key, for an Image, of the picture at the web address `url`, or \"\" while Ladder has none. It asks for the next frame while the picture is on its way."
card_picture(e, url) = begin
  file, coming = Cards.picture!(url, cards_dir(), ask=online(e))
  coming && redraw_in!(e, 0.2)   # look again soon
  file === nothing ? "" : something(picture_key(file), "")
end

# The ends of the names of the files that a line shows as what they are, and never as a card
const NOT_CARDS = (PICTURES..., MAC_PICTURES..., VIDEOS..., SOUNDS..., TABLES..., ".pdf")

"""
True when a line of `e` that holds only `src`, written as a picture is, can
show a card: `src` is a web address, its name doesn't end as a picture's, a
video's, a sound's or a table's does, and the page isn't an email.
"""
card_address(e, src) = Cards.isaddress(src) && !Mail.isemail(e.buf.path) && !(lowercase(splitext(Cards.path(src))[2]) in NOT_CARDS)

"""
What line `i` shows when it holds only the address `src` of a web page,
written as a picture is: a card. `words` are the line's words for the card.
It's nothing when the address can't show a card, and when what's there turned
out not to be a page. That line shows what's there as a picture.
"""
card_item(e, i, src, words) = begin
  card_address(e, src) || return nothing
  card, coming = Cards.lookup!(src, cards_dir(), ask=online(e))
  coming && redraw_in!(e, 0.2)   # look again soon
  card.page || return nothing
  c = node!(LinkCard, e, (:link_card, i))
  # A picture that the card has already isn't looked for again on each frame
  same = c.card == card
  c.line, c.words, c.card = i, words, card
  same && !isempty(c.picture) || (c.picture = card_picture(e, card.image))
  same && !isempty(c.icon) || (c.icon = card_picture(e, card.icon))
  own!(node!(Document, e, :document), c)
  Live(c, card_tall(body(e).size) + 2LIVE_GAP)
end

describe(c::LinkCard) = begin
  e = editor(c)
  s, wide, card = body(e).size, e.width, c.card
  pad = s * CARD_PAD
  inside = card_tall(s) - 2pad - 2px
  # The picture is at the right, and takes no more than a third of the card
  across = isempty(c.picture) ? 0px : min(inside * 1.75, wide * 0.3)
  room = wide - 2pad - 2px - (across > 0px ? across + pad : 0px)
  # An address that stands in for the title isn't bold
  heading = Cards.heading(card, c.words)
  title = Face(SANS, heading == card.url ? "" : "Semibold", s * CARD_TITLE, colours.ink, false)
  words = Face(SANS, "", s * CARD_WORDS, colours.dim, false)
  source = Face(SANS, "", s * CARD_SOURCE, colours.faint, false)
  line(face, text, room) = Box(width(grow=grow), height(face.size * CARD_LINE), Alignment.Start, justify=Alignment.Center,
                               label(shortened(face, text, room), face.size, color=face.color, weight=face.style))
  # The description has two lines at most, and the second ends in … when there's more
  under = Cards.blurb(card, c.words)
  told = isempty(under) ? String[] : wrapped(words, under, num(room))
  length(told) > 2 && (told = [told[1], join(told[2:end], " ")])
  mark = source.size * 1.15
  # Many sites have a dark icon with nothing behind it, which a dark page would hide. There it has a light square behind it.
  page = convert(RGBA{Float64}, colours.bg)
  behind = page.r + page.g + page.b < 1.5 ? (background(RGBA(1, 1, 1, 0.85)),) : ()
  Row(width(grow=grow), height(card_tall(s)), padding(pad), child_gap=pad, radius(8px), border(1px, :solid, colours.line),
      background(ishovered(c) && opening(c) ? colours.hover : colours.block), name="Link card",
    Column(width(grow=grow), height(inside), Alignment.Start,
      line(title, heading, room),
      (line(words, text, room) for text in told)...,
      Box(width(grow=grow), height(grow=grow)),
      Row(width(grow=grow), height(source.size * CARD_LINE), justify=Alignment.Start, child_gap=s * 0.35,
        isempty(c.icon) ? Icon("globe", size=mark, color=colours.faint) : Image(c.icon, fixed(mark), height(mark), radius(3px), behind...),
        Box(label(shortened(source, Cards.source(card), room - mark - s * 0.35), source.size, color=source.color)))),
    (across > 0px ? (covered(c.picture, across, inside),) : ())...)
end

"True when a click on the card now opens its address: ⌘ is held, or the page is one that's never changed"
opening(c::LinkCard) = held(c, Keys.cmd) || (editor(c).buf.fixed && !held(c, Keys.shft))

cursor(c::LinkCard) = opening(c) ? :hand : :ibeam
# A click with ⌘ held opens the address. Any other click puts the caret on the card's line, so the line shows as it's written.
onkey(c::LinkCard, ::KeyPress{Keys.mouse_left}) = opening(c) ? (BROWSER[](c.card.url); handled) : edit_matter!(c, c.line)

"""
The HTML of the line `text` when it shows a card: the card as a link in a box.
It's nothing for any other line. The rules that give a card its look come with
the first card of the page. `styled` is true once they're in.
"""
card_html(e, text, styled::Ref{Bool}) = begin
  occursin("![", text) || return nothing
  m = match(PICTURE_LINE, text)
  m === nothing && return nothing
  src = unescaped(String(m[2]))
  card_address(e, src) || return nothing
  card = first(Cards.lookup!(src, cards_dir(), ask=online(e)))
  card.page || return nothing
  rules = styled[] ? "" : "<style>\n" * Cards.STYLE * "</style>\n"
  styled[] = true
  rules * Cards.markup(card, unescaped(String(m[1])))
end

# --- blocks that a file defines --------------------------------------------------------------
#
# A page can have kinds of block that Ladder doesn't know. A code block in a
# language that isn't one of Ladder's own, like `progress`, is such a block
# when a file defines the language. The file is `progress.jl` in the page's
# folder, or the file or the GitHub repository that the line that opens the
# block names after the language:
#
#     ```progress                             progress.jl, beside the page
#     ```progress ./widgets.jl                a file that has another name
#     ```progress github.com/sam/blocks       a repository on GitHub
#     ```progress github.com/sam/blocks@v2    one branch of it
#
# The file can be a Markdown page too: `progress.md` beside the page, when
# there's no `progress.jl`, or a path that ends in `.md`. Ladder runs the code
# of the page's `julia` blocks, from the top, in one module, and that module
# defines the kind of block as a Julia file's module does. So the page can say
# in words what its code does, and can hold a block of its own kind to try.
#
# A file beside the page only counts if its text defines a function with the
# language's name that takes one thing. So a page in a folder of Julia code
# doesn't run `json.jl` because it has a block of JSON.
#
# The file has a function with the language's name. Ladder gives it the lines
# of the block, and shows what it makes, as a `ui` block shows what its code
# makes: a node draws itself, and any other value shows as text. If the file
# also has a function called `written`, it gives the lines of what was made,
# and Ladder writes them into the block. So what you do to the block is in
# the page's file.
#
#     progress(lines)          makes a Progress from the lines of the block
#     describe(p::Progress)    draws it
#     written(p::Progress)     the lines of its block now
#
# There are three times that Ladder writes a block's lines:
#
#   - Before something reads the page's text: ⌘S, the caret going into the
#     block, a copy, a page of HTML, another page taking the window. The file
#     does nothing for this.
#   - When the component asks, with UI.jl's `changed!(p)`. Ladder writes in
#     the next frame that the mouse isn't held in. Changes that come one soon
#     after another are one step for ⌘Z.
#   - At once, when the component says `changed!(p, now=true)`.
#
# A change that's written only by the first of these doesn't mark the page as
# edited until then, and ⌘Z can't take it back. So a component asks for a
# write after each change that you'd want to take back.
#
# What was made is kept until the block's lines change some other way: you
# type in them, or ⌘Z puts back older ones. Then the function makes it again.
#
# Ladder asks you before it runs the code of a GitHub repository for the
# first time, and keeps the repositories that you allow in a file.
#
# A file on this Mac is loaded again when it's saved, so a kind of block
# changes as you write it. Each block that the file defines is then made again.

"The file or the repository that follows the language on the line that opens a code block"
const SOURCE = r"^\s*(?:```|~~~)\s*[^\s`]+[ \t]+((?:\.{1,2}/|~?/|github\.com/)\S+)\s*$"

"True when Ladder itself says what a code block in the language `lang` shows"
known_lang(lang) = lang in (LIVE, SHEET, SPREADSHEET, DIAGRAM, MATH, TAKEOFF, SCHEDULE, MATTER, TOML_MATTER, HEX, "julia") || haskey(BLOCKS, lang)

"What was found in each file that could define a kind of block: when the file was saved, and whether its text defines the function"
const DEFINES = Dict{Tuple{String,String},Tuple{Float64,Bool}}()

"""
True when the text of `file` defines a function called `name` that takes one
thing, like `progress(lines) = ...` or `function progress(lines)`. The file
is read again only when it's saved.
"""
defines(file::AbstractString, name::AbstractString) = begin
  at = mtime(file)
  at == 0 && return false
  kept = get(DEFINES, (file, name), nothing)
  kept !== nothing && kept[1] == at && return kept[2]
  code = ismarkdown(file) ? join(last.(page_code(file)), "\n") : read(file, String)
  found = occursin(Regex("^(?:function[ \\t]+)?\\Q$name\\E\\([^,;)]+[;)]", "m"), code)
  DEFINES[(file, name)] = (at, found)
  found
end

"""
Where the function of a block in the language `lang` comes from, as Kip names
it: a file or a GitHub repository. `text` is the line that opens the block, and
`folder` is the folder of its page. It's nothing when no file defines the language.
"""
block_source(text::AbstractString, lang::AbstractString, folder::AbstractString) = begin
  (Base.isidentifier(lang) && !known_lang(lang)) || return nothing
  m = match(SOURCE, text)
  m === nothing || return String(m[1])
  isempty(folder) && return nothing
  # A Julia file comes before a Markdown page with the same name
  k = findfirst(ext -> defines(joinpath(folder, lang * ext), lang), (".jl", ".md"))
  k === nothing ? nothing : "./$lang$((".jl", ".md")[k])"
end

"The Markdown pages that define a kind of block, with the module that each one's code runs in"
const PAGE_MODULES = Dict{String,Module}()

"The code of each `julia` block of the Markdown page at `path`, with the line of the page that it starts on"
page_code(path::AbstractString) = begin
  lines = text(path)
  ks = classify(lines)
  out = Tuple{Int,String}[]
  for (i, k) in enumerate(ks)
    (k.kind == Kind.fence && k.level == 0 && k.lang == "julia") || continue
    t = something(findnext(c -> c.kind == Kind.fence, ks, i + 1), length(lines) + 1)
    push!(out, (i + 1, join(lines[i+1:t-1], "\n")))
  end
  out
end

"""
Run the code of the Markdown page at `path` in the module `m`: each of its
`julia` blocks, from the top. An error names the line of the page that it's on.
"""
run_page!(m::Module, path::AbstractString) = begin
  for (line, code) in page_code(path)
    try
      # Empty lines before the code give each line of it the number that it has in the page
      include_string(m, "\n"^(line - 1) * code, path)
    catch err
      error("Line $(err isa LoadError ? err.line : line) of $(basename(path)): $(trouble(err))")
    end
  end
  m
end

"The module that the `julia` blocks of the Markdown page at `path` define. It's made the first time, and kept."
page_module(path::AbstractString) = get!(PAGE_MODULES, path) do
  # A module holds its own name, so the name has a ⭒ in front, as Kip's modules have. A page called
  # `stars` can then define a function called `stars`.
  m = Module(Symbol("⭒", title(path)))
  # What a Julia file that Kip loads starts with: Kip, for `@use`, and its own `eval` and `include`
  Core.eval(m, :(const Kip = $Kip))
  Core.eval(m, :(using .Kip))
  Core.eval(m, :(eval(x) = Core.eval($m, x)))
  Core.eval(m, :(include(file) = Base.include($m, file)))
  run_page!(m, path)
end

"""
The file on this Mac that the source `source` names inside a repository, like
`github.com/sam/blocks/progress.md`. Kip gets the repository if it isn't here.
"""
repository_file(source::AbstractString) = begin
  user, repo, tag, inside = match(Kip.gh_shorthand, source).captures
  folder = Base.invokelatest(Kip.checkout, Base.invokelatest(Kip.getrepo, user, repo), user, repo, tag)
  joinpath(folder, something(inside, ""))
end

"Where the function of the block that opens on line `s` of `b` comes from, or nothing when no file defines its language"
block_source(b::Buffer, s::Int) = block_source(b.lines[s], kinds(b)[s].lang, isempty(b.path) ? "" : dirname(b.path))

"The `user/repo` of a source that's a GitHub repository, or nothing for a file on this Mac"
repository(source::AbstractString) = (m = match(r"^github\.com/([\w\-.]+)/([\w\-.]+)", source); m === nothing ? nothing : "$(m[1])/$(m[2])")

"The GitHub repositories whose code you let a block run, since Ladder opened"
const ALLOWED = Set{String}()

"The file that keeps the repositories you allowed, one on each line"
allowed_file() = joinpath(dirname(settings_file()), "repositories")

"True when you have let a block run the code of the GitHub repository `repo`"
allowed(e, repo::AbstractString) = repo in ALLOWED || (e.remember && isfile(allowed_file()) && repo in eachline(allowed_file()))

"Let a block run the code of the GitHub repository `repo`, now and when Ladder next opens"
allow!(e, repo::AbstractString) = begin
  allowed(e, repo) && return
  push!(ALLOWED, repo)
  e.remember || return
  try
    mkpath(dirname(allowed_file()))
    open(io -> println(io, repo), allowed_file(), "a")
  catch
    # A file that can't be written only means Ladder asks again the next time it opens
  end
  nothing
end

"A block that a file defines: what the file's function made of the lines of the block"
@def mutable struct FileBlock <: SemanticUI
  n::Int = 0                               # its place among the page's blocks in its language
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  lang::String = ""
  source::String = ""                      # where its function comes from, as the page names it
  lines::Vector{String} = String[]         # the lines that `value` was made from, or that it wrote last
  state::Symbol = :new                     # :new, :ask (you haven't allowed its repository), :wait and :get (its repository comes), :made or :fault
  from::Any = nothing                      # the module of the file
  file::String = ""                        # the file on this Mac that the module comes from, or "" for a repository or a folder
  read::Float64 = 0.0                      # when that file was last saved, as this block last knew it
  value::Any = nothing                     # what the function made
  shown::Any = nothing                     # the Shown that draws it
  said::Any = nothing                      # the lines that `written` last gave for it, or nothing
  wants::Bool = false                      # what was made asked for its lines to be written
  inside::Bool = false                     # the caret was in the block's lines in the last frame
  fault::String = ""                       # what went wrong
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its button, kept between frames
end

cursor(::FileBlock) = :arrow

"The view of the `n`th block of the page in the language `lang`, which the file or the repository `source` defines"
file_block(e, lang, source, n) = begin
  v = get!(() -> FileBlock(n=n, lang=lang), e.nodes, (:block, lang, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v.source == source || (v.source = source; v.from = nothing; v.file = ""; v.state = :new)
  v
end

"What the block in the language `lang` from line `i` to line `t` shows. A file or a repository, `source`, defines the language."
file_block_item(e, lang, source, i, t, n) = begin
  v = file_block(e, lang, source, n)
  v.first, v.last = i, t
  reread!(v, e.buf.lines[i+1:t-1])
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(v)), (e.width, 9999px))
  Live(v, concrete.height + 2LIVE_GAP)
end

reread!(v::FileBlock, lines) = begin
  (lines == v.lines && v.state != :new) && return v
  v.lines = lines
  make!(v)
end

"True when Kip has the GitHub repository `repo` on this Mac, so that nothing has to come from GitHub"
here(repo::AbstractString) = isdir(joinpath(Kip.repos, repo))

"The module of the file or the repository `source`. A path like `./progress.jl` starts from the folder of the page."
source_module(e, source::AbstractString) = begin
  folder = isdir(docdir(e)) ? docdir(e) : pwd()
  # A Markdown page isn't Julia code, so Kip doesn't load it: the page's `julia` blocks make its module
  if ismarkdown(source)
    file = repository(source) === nothing ? source_file(e, source) : repository_file(source)
    isfile(file) || error("Ladder can't find the page $source.")
    return cd(() -> Base.invokelatest(page_module, realpath(file)), folder)
  end
  cd(() -> Base.invokelatest(Kip.require, source, folder), folder)
end

"True when `source` names a file or a folder that's on this Mac, as Kip looks for it: the path as it is, or with `.jl` after it"
source_found(e, source::AbstractString) = begin
  path = startswith(source, "~/") ? homedir() * source[2:end] : normpath(joinpath(docdir(e), source))
  ispath(path) || isfile(path * ".jl")
end

"The file on this Mac that `source` names, or \"\" when it names a folder, or a file that isn't there"
source_file(e, source::AbstractString) = begin
  path = startswith(source, "~/") ? homedir() * source[2:end] : normpath(joinpath(docdir(e), source))
  isfile(path) || (path *= ".jl")
  isfile(path) ? realpath(path) : ""
end

"When each file that defines a kind of block was last loaded: the time that the disk gave for it then"
const LOADED = Dict{String,Float64}()

"The files that define a kind of block and didn't load, with what went wrong"
const BROKEN = Dict{String,String}()

"What went wrong, as a block shows it"
trouble(err) = sprint(showerror, err isa LoadError ? err.error : err)

"""
Load the file of the block of `v` again if it was saved since it was loaded,
so that a kind of block changes as you write it. Each block that the file
defines is then made again from its lines.
"""
reload!(v::FileBlock) = begin
  isempty(v.file) && return v
  at = mtime(v.file)
  at == 0 && return v   # the file is gone, so the block stays as it is
  if at != get(LOADED, v.file, at)
    write_blocks!(editor(v))   # what the blocks hold goes into their lines first, since they're made again from those
    LOADED[v.file] = at
    delete!(BROKEN, v.file)
    m = get(Kip.modules, v.file, get(PAGE_MODULES, v.file, nothing))
    try
      # The file's new code goes into the module that it has. A file that didn't load the first time has none yet.
      m === nothing || (ismarkdown(v.file) ? Base.invokelatest(run_page!, m, v.file) : Base.include(m, v.file))
    catch err
      BROKEN[v.file] = trouble(err)
    end
  end
  v.read == get(LOADED, v.file, v.read) || (v.state = :new)
  v
end

"The function called `name` of the module `from`, or nothing if the module has none"
named(from, name::Symbol) = Base.invokelatest(isdefined, from, name) ? Base.invokelatest(getglobal, from, name) : nothing

"""
The lines of the block of `v` as what the block made writes them now. It's
nothing when the file has no function `written` for what was made.
"""
lines_now(v::FileBlock) = begin
  w = named(v.from, :written)
  (w === nothing || !Base.invokelatest(applicable, w, v.value)) && return nothing
  out = Base.invokelatest(w, v.value)
  String[String(l) for l in (out isa AbstractString ? split(out, '\n') : out)]
end

"""
The Shown that draws what the block of `v` made: its node, or its words when
it has no node. Words show as they are, and any other value as Julia prints it.
"""
shown(v::FileBlock) = begin
  node = Base.invokelatest(present, v.value)
  words = node !== nothing ? "" : v.value isa AbstractString ? v.value : Base.invokelatest(repr, "text/plain", v.value)
  s = own!(v, Shown(value=node === nothing ? note(words, colours.ink) : node))
  s.value isa SemanticUI && own!(s, s.value)
  s
end

"Note that the block of `v` can't show, and why"
fault!(v::FileBlock, why) = begin
  v.state, v.fault = :fault, String(why)
  push!(problems, v.fault)
  v
end

"""
Make what the block of `v` shows from its lines: load its file, and give the
lines to the function that has the language's name. A repository that you
haven't allowed isn't loaded: the block asks first. With `now`, a repository
that has to come from GitHub comes now. Without it, the block first says that
it's coming, because the window stops while it comes.
"""
make!(v::FileBlock; now=false) = begin
  e = editor(v)
  old = v.shown
  v.value = v.shown = v.said = nothing
  repo = repository(v.source)
  if v.from === nothing && repo !== nothing
    allowed(e, repo) || (v.state = :ask; return v)
    (now || here(repo)) || (v.state = :wait; return v)
  end
  v.from === nothing && repo === nothing && !source_found(e, v.source) &&
    return fault!(v, "Ladder can't find the file $(v.source). The line that opens this block names it.")
  repo === nothing && isempty(v.file) && (v.file = source_file(e, v.source))
  if !isempty(v.file)
    v.read = get!(() -> mtime(v.file), LOADED, v.file)
    haskey(BROKEN, v.file) && return fault!(v, BROKEN[v.file])
  end
  try
    v.from === nothing && (v.from = source_module(e, v.source))
    f = named(v.from, Symbol(v.lang))
    f === nothing && return fault!(v, "$(v.source) has no function called $(v.lang). A block in the language $(v.lang) shows what that function makes of the block's lines.")
    v.value = Base.invokelatest(f, copy(v.lines))
    v.shown = shown(v)
    # What a new value shows can carry on from what the last one showed, like a bar that slides to its new length
    old isa Shown && v.shown.value isa SemanticUI && typeof(old.value) === typeof(v.shown.value) && Base.invokelatest(carry!, v.shown.value, old.value)
    v.said = lines_now(v)
    v.state = :made
  catch err
    # A file that didn't load is tried again when it's saved
    v.from === nothing && !isempty(v.file) && (BROKEN[v.file] = trouble(err))
    fault!(v, trouble(err))
  end
  v
end

"""
Write the lines of what the block of `v` made into the block, if they aren't
the lines that it has. With `typing`, writes that come one soon after another
are one step for ⌘Z. Nothing is written when the block's lines in the page
aren't the ones that this was made from: then it's made again from those.
"""
write!(v::FileBlock; typing=false) = begin
  v.wants = false
  (v.state == :made && v.said !== nothing) || return v
  b = editor(v).buf
  span = block_lines(b, v.lang, v.n)
  (span !== nothing && b.lines[span[1]+1:span[2]-1] == v.lines) || return v
  now = try
    lines_now(v)
  catch err
    return fault!(v, trouble(err))
  end
  (now === nothing || now == v.said) && return v
  v.said = v.lines = now
  # A value that shows as words has new words now
  Base.invokelatest(present, v.value) === nothing && (v.shown = shown(v))
  write_block!(v, v.lang, now; typing)
end

"The views of the blocks of the page of `e` that a file defines"
file_blocks(e) = FileBlock[node for (key, node) in e.nodes if node isa FileBlock && key[3] == e.buf.path]

"""
Write the lines of every block of the page that a file defines. Whatever
reads the page's text calls this first: a save, a copy, a page of HTML,
another page that takes the window.
"""
write_blocks!(e) = (foreach(write!, file_blocks(e)); e)

# What was made asks for its lines to be written, with UI.jl's `changed!`
onchanged(v::FileBlock, ev::Changed) = begin
  ev.now ? write!(v) : (v.wants = true; redraw_in!(v, 0))
  handled
end

block_tick!(v::FileBlock) = begin
  v.state == :get && return make!(v, now=true)
  # A repository that another block of the page asked about, and that you allowed there
  v.state == :ask && repository(v.source) in ALLOWED && return make!(v)
  reload!(v)
  v.state == :made || return v
  # The page shows the block's lines while the caret is in them, so they're written as the caret goes in
  b = editor(v).buf
  span = block_lines(b, v.lang, v.n)
  inside = span !== nothing && incode(b, span[1])
  inside && !v.inside && write!(v)
  v.inside = inside
  # A write that was asked for waits until the mouse lets go, so that ⌘Z takes back a whole drag
  v.wants && !held(v, Keys.mouse_left) && write!(v, typing=true)
  v
end

act!(v::FileBlock, action, w) = begin
  allow!(editor(v), repository(v.source))
  v.state = :wait
  make!(v)
  handled
end

describe(v::FileBlock) = begin
  v.state == :made && return Column(width(grow=grow), Alignment.Start, v.shown)
  repo = something(repository(v.source), v.source)
  if v.state == :ask
    return Column(block_look()...,
      Row(width(grow=grow), padding(12px, 16px), child_gap=12px, Alignment.Center,
        Box(width(grow=grow), Alignment.Start,
          Text("This block runs code from github.com/$repo. Run it only if you trust who wrote it.", size=13px, family=SANS, color=colours.dim, wrap=WrapMode.words)),
        block_button!(v, :allow, :allow, words="Run the code", bold=true)))
  end
  if v.state in (:wait, :get)
    # The words are drawn in one frame, and the repository comes in the next
    v.state = :get
    redraw_in!(v, 0)
    return Column(block_look()..., block_note("Getting github.com/$repo…"))
  end
  note(v.fault, colours.accent)
end

# --- front matter as a card ---------------------------------------------------------
#
# While the caret isn't in it, front matter shows as a card: a small FRONTMATTER
# heading, then each key with what it's set to. A click on the card puts the
# caret in the line that was clicked, and the lines show as they're written.

"Front matter, shown as a card"
@def mutable struct MatterCard <: SemanticUI
  rows::Vector{Tuple{Int,String,String}} = Tuple{Int,String,String}[]   # the line, the key and what it's set to
  size::px = 13px                                                       # of the text
end

"A key of front matter and what it's set to, in its card"
@def mutable struct MatterRow <: SemanticUI
  line::Int = 0
  key::String = ""
  value::String = ""
  keys::px = 0px    # how wide the widest key is, so that what each is set to starts in one place
  size::px = 13px
end

"""
The keys of the front matter that ends at line `t`, each with the line it's on and
what it's set to. A line that goes on from the one above, like an item of a list,
joins what that key is set to. A comment isn't shown.
"""
matter_rows(lines, t) = begin
  toml = rstrip(lines[1]) == "+++"
  key = toml ? r"^\s*((?:\"[^\"]*\"|'[^']*'|[\w.-])+)\s*=\s*(.*)$" : r"^([^:#\s-][^:#]*):(?:\s+(.*)|$)"
  rows = Tuple{Int,String,String}[]
  for i in 2:t-1
    text = rstrip(lines[i])
    (isempty(strip(text)) || startswith(lstrip(text), '#')) && continue
    m = match(key, text)
    if m !== nothing
      push!(rows, (i, String(m[1]), something(m[2], "")))
    elseif toml && startswith(lstrip(text), '[') && !isempty(rows) && !endswith(last(rows)[3], ',') && !endswith(last(rows)[3], '[')
      push!(rows, (i, String(strip(text)), ""))   # a [table] that starts a group of keys
    elseif isempty(rows)
      push!(rows, (i, "", String(strip(text))))
    else
      # An item of a list, or the next part of a value that goes over several lines
      at, k, v = pop!(rows)
      part = strip(replace(strip(text), r"^-\s+" => ""))
      push!(rows, (at, k, isempty(v) ? String(part) : endswith(v, '[') ? v * part : v * (startswith(text, r"\s*-\s") ? ", " : " ") * part))
    end
  end
  rows
end

"The front matter that ends at line `t`, as a card"
matter_card(e, t) = begin
  card = node!(MatterCard, e, :matter)
  card.rows = matter_rows(e.buf.lines, t)
  card.size = body(e).size * 0.76
  own!(node!(Document, e, :document), card)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(card)), (e.width, 9999px))
  Live(card, concrete.height + 2LIVE_GAP)
end

describe(c::MatterCard) = begin
  s = c.size
  e = editor(c)
  said = Dict(lowercase(k) => v for (_, k, v) in c.rows)
  # An email that came or went shows who it's from and its subject, as an email does, in place of its keys
  mail_shows(e) && haskey(said, "date") && return mail_head(c, said)
  # ... and a draft says that it's one
  title = Mail.isdraft(e.buf.lines) ? "DRAFT" : "FRONTMATTER"
  keyface = Face(SANS, "Semibold", s, colours.dim, false)
  keys = maximum(r -> measure(keyface, r[2]), c.rows, init=0px)
  Column(width(grow=grow), Alignment.Start, padding(s, s * 0.7), child_gap=s * 0.4, radius(6px),
         border(1px, :solid, colours.line), background(colours.block), name="Front matter",
    # The heading has a little more room under it than the rows have between them
    Box(padding(0px, 0px, s * 0.2, 0px), label(title, s * 0.72, color=colours.dim, weight="Bold")),
    [MatterRow(line=at, key=k, value=v, keys=keys, size=s) for (at, k, v) in c.rows]...)
end

describe(r::MatterRow) = begin
  s, keys = r.size, r.keys
  Row(width(grow=grow), Alignment.Start, padding(0px, s * 0.15), child_gap=(keys > 0px ? s * 0.9 : 0px),
    (keys > 0px ? (Box(fixed(keys), label(r.key, s, color=colours.dim, weight="Semibold")),) : ())...,
    Box(width(grow=grow), Alignment.Start, Text(r.value, size=s, family=SANS, color=colours.ink, wrap=WrapMode.words)))
end

"""
The top of an email, in place of the card of its front matter: the subject as
a title, then who sent it with the date at the right, then who it's to. `said`
is what the front matter sets each key to. A click shows the front matter as
it's written, as a click on any front matter does.
"""
mail_head(c::MatterCard, said) = begin
  s = c.size
  # Each person's name, or the address of one with no name
  people(key) = join((isempty(name) ? address : name for (name, address) in Mail.addresses(get(said, key, ""))), ", ")
  from = Mail.addresses(get(said, "from", ""))
  name, address = isempty(from) ? (get(said, "from", ""), "") : (first(from)[1], first(from)[2])
  isempty(name) && ((name, address) = (address, ""))
  subject = get(said, "subject", "")
  line(words) = Box(width(grow=grow), Alignment.Start, Text(words, size=s, family=SANS, color=colours.dim, wrap=WrapMode.words))
  high = s * 1.5   # a line of one size of text, with room for the tails of its letters
  Column(width(grow=grow), Alignment.Start, padding(0px, s * 0.2, s * 1.1, 0px), child_gap=s * 0.55, name="Email head",
         border(1px, :solid, colours.line)[:bottom],
    Box(width(grow=grow), Alignment.Start, padding(0px, 0px, s * 0.5, 0px),
      Text(isempty(subject) ? "No subject" : subject, size=s * 1.6, family=SANS, subfamily="Semibold", color=colours.ink, wrap=WrapMode.words)),
    Row(width(grow=grow), height(high), child_gap=s * 0.6,
      Box(height(high), justify=Alignment.Center, label(name, s * 1.05, weight="Semibold")),
      Box(width(grow=grow), height(high), Alignment.Start, justify=Alignment.Center, clip=true, label(address, s, color=colours.dim)),
      Box(height(high), justify=Alignment.Center, label(get(said, "date", ""), s, color=colours.dim))),
    (haskey(said, "to") ? (line("To " * people("to")),) : ())...,
    (haskey(said, "cc") ? (line("Cc " * people("cc")),) : ())...)
end

cursor(::Union{MatterCard,MatterRow}) = :ibeam

"Put the caret at the end of line `i` of the front matter, so it shows as it's written"
edit_matter!(node, i) = begin
  e = editor(node)
  b = e.buf
  b.caret = b.anchor = (i, length(b.lines[i]))
  focus(e)
  touch!(e)
  handled
end

onkey(r::MatterRow, ::KeyPress{Keys.mouse_left}) = edit_matter!(r, r.line)
onkey(c::MatterCard, ::KeyPress{Keys.mouse_left}) = edit_matter!(c, isempty(c.rows) ? 1 : first(c.rows)[1])

# The code of a live block can load methods that are newer than the frame that
# ran it, so the node is described with the newest methods there are
geometry(node::SemanticUI) = Base.invokelatest(convert, GeometricUI, node)
geometry(node::GeometricUI) = detach!(node)

"True when the page shows a CSV file as a table"
sheet_page(b::Buffer) = b.view == :file && lowercase(splitext(b.path)[2]) in TABLES

"How far under the top bar the page starts. A CSV file's table starts nearer than the text of a page does."
page_top(e) = sheet_page(e.buf) ? SHEET_ABOVE : PAGE_TOP

"How wide the page's text is in the window"
text_width(e) = begin
  w, _ = window_size(e)
  # While the sidebar slides, the text keeps the width it has beside the
  # sidebar, so it doesn't wrap again on each frame
  # The numbers of a file's lines have room on the left of the text
  # The lines of a block that fill the window have no sidebar beside them
  alone = lowered(e) !== nothing
  room = w - ((e.panel || sliding(e)) && !alone ? panel_w(e) : 0px) - 2PAGE_X - gutter(e)
  # A file of code or of text takes all the room that the window has, and so do a CSV file's table and
  # the lines of a block that fill the window. A page is no wider than the settings say.
  numbered(e.buf) || alone || json_page(e.buf) || sheet_page(e.buf) ? max(room, 240px) : clamp(room, 240px, e.widest * e.zoom)
end

"""
How far the left edge of the page's text is from the left edge of the window.
A page's text is in the middle of the space beside the file panel. A file with
numbered lines starts at the left of that space, after its numbers, unless it's
scrolled to the right.
"""
text_left(e) = begin
  w, _ = window_size(e)
  side = lowered(e) === nothing ? panel_w(e) * opened(e) : 0px
  numbered(e.buf) ? side + PAGE_X + gutter(e) - sideways(e) : side + max(PAGE_X, (w - side - e.width) / 2)
end

"Work out what the page shows and how tall each part is, for text that's `width` wide"
layout!(e, width=text_width(e)) = begin
  b = e.buf
  unlist!(node!(Document, e, :document))   # the document's children are the parts that this layout gives it
  # The page is written as rich text or as plain text, as the switch in the top bar says. After a
  # change, the caret's place is looked at afresh.
  shows = e.plain && b.view == :markdown
  b.plain == shows || (b.plain = shows; b.stood = nothing)
  stand!(b)
  ks = kinds(b)
  width == e.width || (e.width = width; empty!(e.flows))
  columns = page_columns!(e)   # the blocks that show side by side after a `columns` block, or nothing when the page has none
  # A file that's only shown is one viewer, or lines of text that are laid out once and kept
  b.view == :file && return e.layout = [file_item(e, b)]
  readonly(b) && return e.layout = get!(() -> text_items(e, b), e.flows, (:shown, b.path, b.version))
  items = Item[]
  top = 0px
  i = 1
  n = length(b.lines)
  # The lines of a block that went down a level from the window it filled show by themselves
  span = lowered(e)
  span === nothing || ((i, n) = span)
  # The email as it was sent, with the lines that it stands for, or nothing when the page shows its lines
  sent = span === nothing ? sent_email(e) : nothing
  sent === nothing || (lines = sent_lines(e); sent = lines === nothing ? nothing : (sent, lines))
  plans = 0   # how many takeoff blocks there have been so far
  schedules = 0   # and how many schedules
  seen = Dict{String,Int}()   # and how many blocks in each of the languages of `BLOCKS`
  while i <= n
    # In a column, the page's text is as wide as the column, and each column starts level with the first
    columns === nothing || (top = column_turn!(columns, e, items, i, top))
    j = i
    if ks[i].kind == Kind.table
      while j < n && ks[j+1].kind == Kind.table
        j += 1
      end
    end
    # Front matter shows as a card, unless the caret is in it
    if i == 1 && ks[1].kind == Kind.fence && ks[1].lang in (MATTER, TOML_MATTER) && !incode(b, 1)
      t = front_matter(b.lines)
      if t > 1
        content = matter_card(e, t)
        push!(items, Item(1, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # An email shows as it was sent, in place of the lines that were made of it, once its pictures are there
    if sent !== nothing && i == sent[2][1]
      content = sent_item(e, sent[1])
      push!(items, Item(i, sent[2][2], top, content.tall, content))
      top += content.tall
      i = sent[2][2] + 1
      continue
    end
    # A `takeoff` code block shows its plan and its measures, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == TAKEOFF
      plans += 1   # each takeoff keeps its view by its place among the page's takeoffs
      t = codeblock(b, i)[2]
      if !incode(b, i) && t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = takeoff_item(e, i, t, plans)
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A `schedule` code block shows the page's tasks on a line of days, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == SCHEDULE
      schedules += 1
      t = codeblock(b, i)[2]
      if !incode(b, i) && t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = schedule_item(e, i, t, schedules)
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A block in one of the languages of `BLOCKS` shows as its component, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && haskey(BLOCKS, ks[i].lang)
      lang = ks[i].lang
      seen[lang] = get(seen, lang, 0) + 1   # each one keeps its view by its place among the page's blocks in its language
      t = codeblock(b, i)[2]
      if !incode(b, i) && t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = block_item(e, lang, i, t, seen[lang])
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A block in a language that a file defines shows what the file's function makes of it, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && !isempty(ks[i].lang) && !known_lang(ks[i].lang)
      lang = ks[i].lang
      seen[lang] = get(seen, lang, 0) + 1   # every block in the language counts, as `block_lines` counts them
      source = block_source(b, i)
      t = codeblock(b, i)[2]
      if source !== nothing && !incode(b, i) && t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = file_block_item(e, lang, source, i, t, seen[lang])
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A `ui` code block shows what its code makes, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == LIVE && !incode(b, i)
      t = codeblock(b, i)[2]
      if t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = live(e, join(b.lines[i+1:t-1], "\n"))
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A `mermaid` code block shows its diagram, unless the caret is in it. Code that can't be drawn as a diagram shows as code.
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == DIAGRAM && !incode(b, i)
      t = codeblock(b, i)[2]
      content = t > i && ks[t].kind == Kind.fence && ks[t].level == 1 ? diagram(e, join(b.lines[i+1:t-1], "\n")) : nothing
      if content !== nothing
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A formula between two lines of $$, or in a `math` code block, shows as it's set, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == MATH && !incode(b, i)
      t = codeblock(b, i)[2]
      content = t > i && ks[t].kind == Kind.fence && ks[t].level == 1 ? equation_item(e, join(b.lines[i+1:t-1], "\n")) : nothing
      if content !== nothing
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A line that holds only a formula between $$ and $$ shows the formula, unless the caret is in the line
    if ks[i].kind == Kind.paragraph && !israw(b, i) && maths_line(b, i)
      content = equation_item(e, maths_text(b.lines[i]))
      if content !== nothing
        push!(items, Item(i, i, top, content.tall, content))
        top += content.tall
        i += 1
        continue
      end
    end
    # A `sheet` code block is drawn as a sheet, and a `spreadsheet` one as a spreadsheet, unless the caret is on its first or last line
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang in (SHEET, SPREADSHEET)
      run = drawn(b, i, ks[i].lang)
      if run !== nothing
        content = ks[i].lang == SHEET ? sheetgrid(e, run...) : spreadgrid(e, run...)
        push!(items, Item(i, run[2], top, tall(content), content))
        top += tall(content)
        i = run[2] + 1
        continue
      end
    end
    # A line that holds only a picture shows the picture, unless the caret is on the line
    if ks[i].kind == Kind.paragraph && !israw(b, i) && occursin("![", b.lines[i])
      content = picture_item(e, i)
      if content !== nothing
        push!(items, Item(i, i, top, content.tall, content))
        top += content.tall
        i += 1
        continue
      end
    end
    # A table needs its line of dashes. It shows as plain lines while the caret is on that line.
    if j > i && isdivider(b.lines[i+1]) && !israw(b, i + 1)
      content = grid(e, i, j)
      push!(items, Item(i, j, top, tall(content), content))
      top += tall(content)
      i = j + 1
    else
      content = flow(e, i)
      push!(items, Item(i, i, top, tall(content), content))
      top += tall(content)
      i += 1
    end
  end
  columns === nothing || column_turn!(columns, e, items, n + 1, top)   # the page ends in a column
  e.layout = slide_items(e, items)   # while the page shows as slides, only the items of one slide
end

"The item that shows line `i`"
item(e, i::Int) = e.layout[something(findfirst(it -> it.first <= i <= it.last, e.layout), length(e.layout))]

"Scroll so the caret is on screen"
reveal!(e) = begin
  e.buf.view == :file && return   # a viewer has no caret
  it = item(e, e.buf.caret[1])
  top, bottom = it.top, it.top + it.tall
  if it.content isa Flow
    k, x = spot(it.content, e.buf.caret[2])
    top = it.top + line_top(it.content, k)
    bottom = top + it.content.lines[k].high
    # A long line that doesn't wrap scrolls sideways to show the caret, with a little of the line on each side of it
    if !wraps(e)
      b = e.buf
      x < b.across + SIDE_ROOM && (b.across = x - SIDE_ROOM)
      x > b.across + e.width - SIDE_ROOM && (b.across = x - e.width + SIDE_ROOM)
      scroll_sideways!(e, 0px)
    end
  elseif it.content isa Sheet
    r = clamp(e.buf.caret[1] - it.first, 1, length(it.content.rows))
    top = it.top + row_top(it.content, r)
    bottom = top + it.content.heights[r]
  end
  scroll_into_view!(e.scroll, PAGE_TOP + top - 30px, PAGE_TOP + bottom + 40px)
end

# --- drawing the text -----------------------------------------------------------------

"The box of a to-do item: empty, or filled and ticked when the item is done"
todo_box(seg::Seg) = begin
  side = px(round(num(seg.face.size) * 0.82))
  box = seg.text == TODO_DONE ?
    Box(fixed(side), height(side), radius(side * 0.22), Alignment.Center, justify=Alignment.Center, background(colours.accent),
        Icon("check", size=side * 0.9, color=colours.bg)) :
    Box(fixed(side), height(side), radius(side * 0.22), border(1.5px, :solid, colours.marker))
  Box(fixed(seg.w), Alignment.Start, box)
end

describe(seg::Seg) = begin
  # What inline code made is drawn in place of the code
  seg.node === nothing || return Box(fixed(seg.w), Alignment.Start, geometry(seg.node.node))
  isbox(seg) && return todo_box(seg)
  f = seg.face
  t = Text(seg.text, size=f.size, family=f.family, subfamily=f.style, color=f.color, wrap=WrapMode.none)
  # The number of a footnote is at the top of a box as tall as the text beside it, so it sits high in the line
  seg.atomic && startswith(seg.link, '^') && !endswith(seg.text, ' ') && return Box(fixed(seg.w), height(f.size * 1.9), Alignment.Start, t)
  # A Text on its own would take a share of the spare room in its row
  f.chip || return Box(fixed(seg.w), Alignment.Start, t)
  if !isempty(f.lang)
    t = Row(Alignment.Start, [part for tok in tokens(seg.text, f.lang) for part in coloured(tok, f)]...)
  elseif !hasall(f, seg.text)
    t = Row(Alignment.Start, spared(seg.text, f)...)
  end
  Box(fixed(seg.w), height(f.size * 1.5), padding(CHIP_X, 0px), radius(4px), background(colours.chip), border(1px, :solid, colours.chip_line), t)
end

"""
One part of a line of code in a chip, in the colour of its kind, as the parts
of a row. Each is as wide as its text measures, so the caret lines up with it.
"""
coloured(tok, f::Face) =
  spared(tok.text, Face(f, color=tok.kind == :plain ? f.color : getfield(colours, tok.kind), style=tok.kind == :comment ? codeslant() : f.style))

"The lines of a Flow, as rows of text. `edge` is the width of a border on its left."
rows(f::Flow, edge=0px) =
  [Row(width(grow=grow), height(vl.high), padding(0px, 0px, 0px, vl.x - edge), clip=true, map(describe, vl.segs)...) for vl in f.lines]

describe(e::Editor, it::Item) = describe(e, it, it.content)

describe(e::Editor, it::Item, f::Flow) = begin
  k = f.kind
  if k == Kind.rule && !f.raw
    return Box(width(grow=grow), height(tall(f)), Box(width(grow=grow), height(1px), background(colours.line)))
  end
  edge = k == Kind.blockquote ? 3px : 0px
  col = Column(width(grow=grow), Alignment.Start, padding(f.above, 0px, f.below, 0px), rows(f, edge)...)
  if k == Kind.code || k == Kind.fence
    col.background = background(colours.block)
  elseif k == Kind.blockquote
    # A callout has its kind's colour down its left, and a little of that colour behind it
    kind = 1 <= it.first <= length(e.buf.lines) ? callout(kinds(e.buf)[it.first]) : ""
    col.border = border(edge, :solid, isempty(kind) ? colours.line : callout_colour(kind))[:left]
    isempty(kind) || (col.background = background(callout_tint(kind)))
  end
  col
end

describe(e::Editor, it::Item, g::Grid) = begin
  isspread(g) && return spreadsheet(e, it, g)
  line = border(1px, :solid, colours.line; between=true)
  table = Column(width(grow=grow), Alignment.Start, line, name="Table",
    [Row(width(grow=grow), height(g.heights[r]), Alignment.Start, line[:between],
         background(r == 1 ? colours.head : iseven(r) ? colours.bg : colours.stripe),
       [Column(fixed(g.widths[c]), height(grow=grow), Alignment.Start, justify=Alignment.Center, rows(g.flows[r][c])...)
        for c in eachindex(g.widths)]...)
     for r in eachindex(g.rows)]...)
  Box(width(grow=grow), padding(0px, TABLE_GAP), table)
end

describe(e::Editor, it::Item, l::Live) = begin
  Box(width(grow=grow), height(l.tall), Alignment.Start, padding(0px, LIVE_GAP), geometry(l.node))
end

"The kind of block that an item is part of, or nothing for a blank line"
blocktype(it::Item) = begin
  c = it.content
  c isa Grid && return Table
  c isa Sheet && return SheetBlock
  c isa Live ? LiveBlock : blocktype(c.kind)
end

blocktype(k::Kind) =
  k == Kind.paragraph ? Paragraph : k == Kind.heading ? Heading : k in (Kind.bullet, Kind.ordered, Kind.todo) ? List :
  k == Kind.blockquote ? Quote : k in (Kind.code, Kind.fence) ? CodeBlock : k == Kind.table ? Table :
  k == Kind.rule ? Rule : nothing

"The kind of block that line `i` is in. The keys that edit the text do different things in different blocks."
block(b::Buffer, i::Int) = blocktype(kinds(b)[i].kind)

"The items as the nodes of the document: one for each paragraph, list, table and so on"
blocks(d::Document, items) = begin
  ks = kinds(editor(d).buf)
  out, group, T = Any[], Item[], nothing
  close() = begin
    isempty(group) && return
    T === nothing ? append!(out, group) : push!(out, own!(d, T(first=group[1].first, last=group[end].last, items=copy(group))))
    empty!(group)
  end
  for it in items
    U = blocktype(it)
    # A heading, a rule, a table and a live block each stand alone, and a ``` line that opens a block starts a new one
    alone = U in (Heading, Rule, LiveBlock, SheetBlock) || it.content isa Grid || (U === CodeBlock && ks[it.first].kind == Kind.fence && ks[it.first].level == 0)
    (U !== T || alone) && close()
    T = U
    push!(group, it)
  end
  close()
  out
end

describe(b::Block) = Column(width(grow=grow), Alignment.Start, [describe(editor(b), it) for it in b.items]...)

describe(d::Document) = begin
  e = editor(d)
  items = e.layout
  total = isempty(items) ? 0px : lowest(e, items)
  _, h = window_size(e)
  # Only the lines on screen, and a few either side, are built
  from, to = e.scroll.offset - PAGE_TOP - 200px, e.scroll.offset + h + 200px
  lo = something(findfirst(it -> it.top + it.tall >= from, items), length(items))
  hi = something(findlast(it -> it.top <= to, items), lo)
  lo, hi = whole_groups(e, items, lo, hi)   # a group of columns is built whole
  e.shown = lo:hi
  # Each row of text cuts off what's past its end, so long lines that don't wrap need a page as wide as the longest
  Column(fixed(wraps(e) ? e.width : max(e.width, e.reach + SIDE_ROOM)), Alignment.Start, name="Document",
    spacer(items[lo].top),
    page_parts(d, e, items[lo:hi])...,
    spacer(total - lowest(e, view(items, lo:hi))))
end

# With ⌘ held, a click on a link opens it, so the mouse shows a hand there. In a page that's never
# changed, a click on a link opens it with no key held.
cursor(d::Document) = begin
  e = editor(d)
  e.buf.view == :file && return :arrow   # a viewer has no text to select
  slideshow(e) === nothing || return slide_cursor(e)   # nor has a slide
  w = window_of(e)
  w === nothing && return :ibeam
  # A click on a to-do item's box ticks it
  todo_at(e, w.mouse) === nothing || return :hand
  (Keys.cmd in w.keys && link_at(e, w.mouse) !== nothing) || (e.buf.fixed && link_on(e, w.mouse) !== nothing) ? :hand : :ibeam
end

"""
The room under the last line of the page. A code file scrolls on until its last
lines are at the top of the window, so a box that opens under them has room to
show.
"""
page_bottom(e) = numbered(e.buf) ? max(PAGE_BOTTOM, e.scroll.viewport - CODE_END) : PAGE_BOTTOM

describe(p::Page) = begin
  e = editor(p)
  # Long lines that don't wrap go on to the right edge of the window. The text moves left as the page
  # scrolls sideways. None of it shows past the edges of the page, and the numbers of the lines go over it.
  page = wraps(e) ?
    Row(width(grow=grow), Alignment.Start, justify=numbered(e.buf) ? Alignment.Start : Alignment.Center,
        padding(page_top(e), PAGE_X, page_bottom(e), PAGE_X + gutter(e)),
      node!(Document, e, :document)) :
    Row(width(grow=grow), Alignment.Start, padding(page_top(e), 0px, page_bottom(e), PAGE_X + gutter(e)), clip_x=true,
      Box(Alignment.Start, offset_x=-sideways(e), node!(Document, e, :document)))
  reuse!(e.scroll, guide_under(e, page))
end

"""
Put a faint line down a file of code, under the text of `page`, after the
number of characters that the settings page chooses. It moves with the text
when the page scrolls sideways.
"""
guide_under(e, page) = begin
  (e.guide > 0 && numbered(e.buf)) || return page
  x = PAGE_X + gutter(e) + measure(face(e, Line(Kind.code, 0, 0, "")), "0") * e.guide - sideways(e)
  Stack(width(grow=grow), Alignment.Start,
    Box(fixed(1px), height(grow=grow), background(colours.line), offset_x=x),
    page)
end

"The part of line `i` that's selected, as columns, and whether the selection goes on past it"
selected(b::Buffer, i::Int) = begin
  lo, hi = selection(b)
  (lo[1] <= i <= hi[1] && lo != hi) || return nothing
  (i == lo[1] ? lo[2] : 0, i == hi[1] ? hi[2] : length(b.lines[i]), i < hi[1])
end

const Rect = NTuple{4,Float64}   # left, top, right and bottom, in px

"""
The boxes that cover the selected part of each line of `f`, whose top left
corner is at (x, y). The first and last boxes take in the space above and below
the lines, so the boxes of one line of the document meet those of the next.
With `margin`, a box that starts at the start of its line also takes in the
space to the left of the text, like the inset of a code block. That's for a
line that the selection came into from the line above: it keeps the left edge
of the selection straight from one kind of line to the next. The line that the
selection starts in has no `margin`, so its box starts where its text does. A
selection that's all in one code block has no `margin` on any line. See `within_code`.
"""
marks(f::Flow, x, y, (from, to, more); margin=true, edge=0px) = begin
  out = Rect[]
  n = length(f.lines)
  for (k, vl) in enumerate(f.lines)
    (from <= vl.to && to >= vl.from) || continue
    # `edge` is the left edge of the line's column of the page, where the space to the left of its text starts
    x1 = from > vl.from ? xcol(vl, from) : margin ? edge : vl.x
    x2 = xcol(vl, min(to, vl.to))
    # A little extra shows that the end of the line is selected too
    (to > vl.to || (more && k == n)) && (x2 += 7px)
    # A line with none of its text selected has no box, not even over its margin
    x2 > max(x1, vl.x) || continue
    top = k == 1 ? 0px : line_top(f, k)
    bottom = line_top(f, k) + vl.high + (k == n ? f.below : 0px)
    push!(out, (num(x + x1), num(y + top), num(x + x2), num(y + bottom)))
  end
  out
end

const SELECTION_RADIUS = 4.0

"""
Fill the selection. Boxes that sit on top of each other are joined into one
shape, and every corner of that shape is rounded, the ones that point in as
well as the ones that point out.
"""
fill_selection(ctx, rects::Vector{Rect}) = begin
  isempty(rects) && return
  paint = Skia.sk_paint_new()
  Skia.sk_paint_set_antialias(paint, true)
  Skia.sk_paint_set_color(paint, sk_color(colours.select))
  from = 1
  for i in 2:length(rects)+1
    # A box joins the one above it when they touch and share some width
    joined = i <= length(rects) && abs(rects[i][2] - rects[i-1][4]) < 1 &&
             rects[i][1] < rects[i-1][3] && rects[i][3] > rects[i-1][1]
    joined && continue
    outline = rounded(corners(rects[from:i-1]), SELECTION_RADIUS)
    Skia.sk_canvas_draw_path(ctx, outline, paint)
    Skia.sk_path_delete(outline)
    from = i
  end
  Skia.sk_paint_delete(paint)
end

"The corners of the shape made by a stack of boxes: down its right side, then back up its left"
corners(rects) = begin
  points = NTuple{2,Float64}[]
  add(p) = (isempty(points) || points[end] != p) && push!(points, p)
  top = rects[1][2]
  for (l, t, r, b) in rects
    add((r, top)); add((r, b))
    top = b
  end
  for (i, (l, t, r, b)) in Iterators.reverse(enumerate(rects))
    add((l, b)); add((l, i == 1 ? t : rects[i-1][4]))
  end
  points
end

"A Skia path around `points`, with each corner rounded by up to `radius`"
rounded(points, radius) = begin
  path = Skia.sk_path_new()
  n = length(points)
  for i in 1:n
    before, corner, after = points[mod1(i - 1, n)], points[i], points[mod1(i + 1, n)]
    d1, d2 = hypot((before .- corner)...), hypot((after .- corner)...)
    # A short edge has room for less of a curve at each end
    r = min(radius, d1 / 2, d2 / 2)
    a = corner .+ (before .- corner) .* (r / max(d1, 1e-6))
    b = corner .+ (after .- corner) .* (r / max(d2, 1e-6))
    i == 1 ? Skia.sk_path_move_to(path, Float32(a[1]), Float32(a[2])) : Skia.sk_path_line_to(path, Float32(a[1]), Float32(a[2]))
    # A conic with this weight is a quarter of a circle
    Skia.sk_path_conic_to(path, Float32(corner[1]), Float32(corner[2]), Float32(b[1]), Float32(b[2]), Float32(sqrt(0.5)))
  end
  Skia.sk_path_close(path)
  path
end

"Draw the caret at column `col` of `f`, whose top left corner is at (x, y)"
caret(ctx, e, f::Flow, x, y, col) = begin
  w = window_of(e)
  (w !== nothing && w.focus === e) || return
  since = time() - e.blink
  (since < 0.5 || mod(since - 0.5, 1.0) >= 0.5) || return
  k, cx = spot(f, col)
  high = f.size * 1.25
  rectangle(ctx, x + cx - 0.75px, y + line_top(f, k) + (f.lines[k].high - high)/2, 1.5px, high, background=colours.ink, border=0px)
end

# The caret and the selection are drawn over the text, once it has been placed
draw(ctx, size, ui::ConcreteRect, d::Document) = begin
  e = editor(d)
  b = e.buf
  e.origin = (ui.left, ui.top)
  fill_selection(ctx, selection_boxes(ctx, e, ui))
  with_others(() -> fill_selection(ctx, selection_boxes(ctx, e, ui)), b)
  outline_same_word(ctx, e, ui)
  ring_part(ctx, e, ui)
  annotate(ctx, e, ui)
  glow_bracket_pair(ctx, e, ui)
  # A file that's only shown has a selection and no caret. So has a page that's never changed.
  if !(caretless(b) || readonly(b))
    carets(ctx, e, ui)
    with_others(() -> carets(ctx, e, ui), b)
  end
  margin(ctx, e, ui)
end

"""
True when the selection is all in one code block, or in a file of code. The
space to the left of the code is the block's padding. There's no line outside
the block for the selection to line up with, so that space gets no colour.
"""
within_code(b::Buffer) = begin
  lo, hi = selection(b)
  kinds(b)[lo[1]].kind in (Kind.code, Kind.fence) && hi[1] <= codeblock(b, lo[1])[2]
end

"""
The boxes that cover the selection on the page, whose text is at `ui`. The
part of it that's in the cells of a table is filled here, a cell at a time.
"""
selection_boxes(ctx, e, ui) = begin
  b = e.buf
  # A line takes in the space left of its text only when the selection came into it from the line above
  margins = !within_code(b)
  # The selection goes under the caret, as one shape for each run of lines that touch
  rects = Rect[]
  for it in e.layout[e.shown]
    top = ui.top + it.top
    across, wide = item_room(e, it)   # an item in a column of the page starts at the column's left edge, and is as wide as the column
    left = ui.left + across
    if it.content isa Grid
      g = it.content
      if b.caret[1] != b.anchor[1]
        # A selection that covers several lines takes each row whole
        lo, hi = selection(b)
        y = top + TABLE_GAP
        lo[1] < it.first && hi[1] >= it.first && push!(rects, (num(left), num(top), num(left + 7px), num(y)))
        y += g.head   # a spreadsheet's row of letters isn't part of the text, so it's never selected
        for (r, i) in enumerate(g.rows)
          h = g.heights[r] + (r == length(g.rows) ? 2px : 1px)
          lo[1] <= i <= hi[1] && push!(rects, (num(left), num(y), num(left + wide), num(y + h)))
          y += h
        end
        lo[1] <= it.last && hi[1] > it.last && push!(rects, (num(left), num(y), num(left + 7px), num(y + TABLE_GAP)))
        continue
      end
      for (r, i) in enumerate(g.rows), (c, cell) in enumerate(g.cells[r])
        sel = selected(b, i)
        (sel !== nothing && sel[1] < cell.limit && sel[2] > cell.lo) || continue
        x, y = cell_origin(g, r, c)
        fill_selection(ctx, marks(g.flows[r][c], ui.left + x, top + y, (max(sel[1], cell.lo), min(sel[2], cell.limit), false), margin=false))
      end
    elseif it.content isa Sheet
      append!(rects, marks(e, it, it.content, left, top))
    elseif it.content isa Live
      # A live block is selected whole
      lo, hi = selection(b)
      selecting(b) && lo[1] <= it.first && hi[1] >= it.last &&
        push!(rects, (num(left), num(top), num(left + wide), num(top + it.tall)))
    else
      sel = selected(b, it.first)
      sel === nothing || append!(rects, marks(it.content, ui.left, top, sel, margin=margins && selection(b)[1][1] < it.first, edge=across))
    end
  end
  rects
end

"""
Draw the numbers of the lines, and the bars beside the lines that just changed,
in the room on the left of the text. The text of a page that's scrolled to the
right goes under that room, so the room is filled with the page's colour first.
"""
margin(ctx, e, ui) = begin
  across = sideways(e)
  left = ui.left + across   # where the text starts when it isn't scrolled
  room = PAGE_X + gutter(e)
  across > 0px && rectangle(ctx, left - room, ui.top, room, ui.height, background=colours.bg, border=0px)
  shade_line(ctx, e, left - room, ui.top)
  draw_numbers(ctx, e, left, ui.top)
  draw_fresh(ctx, e, left, ui.top)
end

const SHADE = 0.05   # how much of the colour of the text the shade of the caret's line has

"""
Shade the line that the caret is on, from `x` to the right edge of the window,
in a file of code whose settings ask for it. The shade is faint, so the text
shows through it. There's none while text is selected.
"""
shade_line(ctx, e, x, top) = begin
  b = e.buf
  (e.shade && numbered(b) && !caretless(b) && !readonly(b) && !selecting(b) && !isempty(e.layout)) || return
  it = item(e, b.caret[1])
  w, _ = window_size(e)
  rectangle(ctx, x, top + it.top, w - x, it.tall, background=RGBA(colours.ink, SHADE), border=0px)
end

"Draw the caret on the page, whose text is at `ui`"
carets(ctx, e, ui) = begin
  b = e.buf
  picked(b) === nothing || return   # a line round the part shows where the caret is
  for it in e.layout[e.shown]
    top = ui.top + it.top
    if it.content isa Grid
      g = it.content
      at = gridcell(g, b.caret)
      isspread(g) && at !== nothing && b.caret[1] == b.anchor[1] && ring(ctx, g, at, ui.left, top)
      for (r, i) in enumerate(g.rows), (c, cell) in enumerate(g.cells[r])
        x, y = cell_origin(g, r, c)
        at == (r, c) && caret(ctx, e, g.flows[r][c], ui.left + x, top + y, b.caret[2])
      end
      continue
    end
    it.content isa Sheet && caret(ctx, e, it.content, ui.left + item_room(e, it)[1], top)
    it.first == b.caret[1] && it.content isa Flow && caret(ctx, e, it.content, ui.left, top, b.caret[2])
  end
end

# --- the mouse on the page --------------------------------------------------------------

"The place in the document under a point in the window"
locate(e, (x, y)) = begin
  # On a page that's scrolled sideways, a point on the numbers of the lines is on the first part of the line that shows
  dx, dy = max(x - e.origin[1], sideways(e)), y - e.origin[2]
  items = e.layout
  it = items[item_under(e, dx, dy)]
  if it.content isa Grid
    g = it.content
    # The row and the column under the point
    r = something(findfirst(r -> dy < it.top + cell_origin(g, r, 1)[2] + g.heights[r], eachindex(g.rows)), length(g.rows))
    c = something(findlast(c -> dx >= cell_origin(g, r, c)[1], eachindex(g.widths)), 1)
    cells = g.cells[r]
    isempty(cells) && return line_end(e.buf, g.rows[r])
    # A row can have fewer cells than the table has columns
    c = min(c, length(cells))
    f = g.flows[r][c]
    x, y = cell_origin(g, r, c)
    k = line_at(f, dy - it.top - y)
    return (g.rows[r], cellcol(f, k, dx - x, cells[c]))
  end
  it.content isa Sheet && return locate(e, it, it.content, dx - item_room(e, it)[1], dy - it.top)
  if it.content isa Live
    # A point on a live block counts as the end of the line above it or the start of the line below
    above = dy < it.top + it.tall/2 ? it.first > 1 : it.last == length(e.buf.lines)
    return above && it.first > 1 ? line_end(e.buf, it.first - 1) : it.last < length(e.buf.lines) ? (it.last + 1, 0) : (it.first, 0)
  end
  f = it.content::Flow
  (it.first, colat(f, line_at(f, dy - it.top), dx))
end

"The link under a point in the window, or nothing"
link_at(e, pos) = begin
  line, col = locate(e, pos)
  it = item(e, line)
  it.content isa Flow || return nothing
  for vl in it.content.lines, seg in vl.segs
    seg.col <= col < seg.col + seg.n && !isempty(seg.link) && return seg.link
  end
  nothing
end

"""
The link that's drawn under a point in the window, or nothing. `link_at` gives
the link nearest to a point, which is right for a click with ⌘ held. A point
beside a line, or between two lines, is on no link here, so a click with no
key held opens a link only when the click is on its words.
"""
link_on(e, (x, y)) = begin
  dx, dy = x - e.origin[1], y - e.origin[2]
  (dy >= 0px && !isempty(e.layout)) || return nothing
  it = e.layout[item_under(e, dx, dy)]
  f = it.content
  f isa Flow || return nothing
  for vl in f.lines
    top = it.top + f.above + vl.top
    top <= dy < top + vl.high || continue
    for seg in vl.segs
      !isempty(seg.link) && seg.x <= dx < seg.x + seg.w && return seg.link
    end
  end
  nothing
end

isword(c::Char) = isletter(c) || isdigit(c) || c == '_' || c == '\''

"The columns of the word around column `col` of `line`"
word_at(line::String, col::Int) = begin
  chars = collect(line)
  lo = hi = clamp(col, 0, length(chars))
  while lo > 0 && isword(chars[lo]); lo -= 1 end
  while hi < length(chars) && isword(chars[hi+1]); hi += 1 end
  (lo, hi)
end

held(node, key) = (w = window_of(node); w !== nothing && key in w.keys)

"The caret moved or the text changed, so show the caret"
touch!(e; keep_goal=false) = begin
  e.buf.reading = false
  e.blink = time()
  e.reveal = true
  keep_goal || (e.goal = nothing)
  confine!(e)
end

"The line of the to-do item whose box is under a point in the window, or nothing"
todo_at(e, (x, y)) = begin
  isempty(e.layout) && return nothing
  dx, dy = x - e.origin[1], y - e.origin[2]
  it = e.layout[item_under(e, dx, dy)]
  f = it.content
  (f isa Flow && f.kind == Kind.todo && !f.raw) || return nothing
  # The box is on the item's first line
  it.top + f.above <= dy < it.top + f.above + first(f.lines).high || return nothing
  for seg in first(f.lines).segs
    isbox(seg) && return seg.x <= dx < seg.x + seg.w ? it.first : nothing
  end
  nothing
end

"What inline code made that's under a point in the window: its Inline, or nothing"
inline_at(e, (x, y)) = begin
  isempty(e.layout) && return nothing
  dx, dy = x - e.origin[1], y - e.origin[2]
  it = e.layout[item_under(e, dx, dy)]
  c = it.content
  if c isa Grid
    for r in eachindex(c.rows), col in eachindex(c.flows[r])
      cx, cy = cell_origin(c, r, col)
      found = inline_at(c.flows[r][col], dx - cx, dy - it.top - cy)
      found === nothing || return found
    end
    return nothing
  end
  c isa Flow ? inline_at(c, dx, dy - it.top) : nothing
end

inline_at(f::Flow, dx::px, dy::px) = begin
  (0px <= dy < tall(f)) || return nothing
  for seg in f.lines[line_at(f, dy)].segs
    seg.node !== nothing && seg.x <= dx < seg.x + seg.w && return seg.node
  end
  nothing
end

"Tick the box of the to-do item on line `i`, or take its tick away. The caret stays where it is."
tick!(e, i::Int) = begin
  b = e.buf
  text = b.lines[i]
  col = findfirst('[', text)   # the column after the [, because only spaces and a - come before it
  caret, anchor = b.caret, b.anchor
  edit!(b, (i, col), (i, col + 1), isdone(text) ? " " : "x")
  b.caret, b.anchor = caret, anchor
  e
end

press!(e, pos) = begin
  slideshow(e) === nothing || return slide_press!(e, pos)   # a click on a slide goes to the next one, or back
  b = e.buf
  box = held(e, Keys.opt) ? nothing : todo_at(e, pos)
  if box !== nothing
    # A click on a to-do item's box ticks it, and doesn't move the caret
    focus(e)
    e.popup = :none
    e.clicked = (time(), (box, 0), 0)
    return tick!(e, box)
  end
  it = e.layout[item_under(e, pos[1] - e.origin[1], pos[2] - e.origin[2])]
  made = held(e, Keys.opt) ? nothing : inline_at(e, pos)
  # A click on a formula in a line of text puts the caret beside it, as a click on a word does
  if made !== nothing && !(made.node isa Equation)
    # What inline code made takes its own clicks, as a live block does. A click with ⌥ held shows the code.
    e.popup = :none
    e.clicked = (time(), (it.first, 0), 0)
    took(e) || focus(e)
    return
  end
  if it.content isa Live && !held(e, Keys.opt)
    # A live block takes its own clicks. A part of it that took the keyboard, like a text field, keeps it.
    e.popup = :none
    e.clicked = (time(), (it.first, 0), 0)
    took(e) || focus(e)
    return
  end
  focus(e)
  e.popup = :none
  if held(e, Keys.cmd)
    url = link_at(e, pos)
    url === nothing || return follow!(e, url)
  elseif b.fixed && !held(e, Keys.shft)
    # A page that's never changed has no caret for a click to place, so a click on a link opens it
    url = link_on(e, pos)
    url === nothing || return follow!(e, url)
  end
  if it.content isa Live
    # A click with ⌥ held shows the block's code
    e.clicked = (time(), (it.first, 0), 0)
    b.caret = b.anchor = (min(it.first + 1, it.last), 0)
    return touch!(e)
  end
  it.content isa Sheet && press!(e, it, it.content, pos) && return touch!(e)
  if it.content isa Grid && isspread(it.content) && held(e, Keys.opt)
    # A click on a spreadsheet with ⌥ held shows it as lines of code
    b.caret = b.anchor = line_end(b, it.first)
    return touch!(e)
  end
  at = settle(b, locate(e, pos))
  t, before, count = e.clicked
  count = time() - t < 0.4 && before == at ? count % 3 + 1 : 1
  e.clicked = (time(), at, count)
  if count == 2
    lo, hi = word_at(b.lines[at[1]], at[2])
    b.anchor, b.caret = (at[1], lo), (at[1], hi)
  elseif count == 3
    # Three clicks select the line, or in a table the cell
    cell = cellat(b, at)
    lo, hi = cell === nothing ? (0, length(b.lines[at[1]])) : (cell.lo, cell.hi)
    b.anchor, b.caret = (at[1], lo), (at[1], hi)
  else
    b.caret = at
    held(e, Keys.shft) || (b.anchor = at)
  end
  touch!(e)
end

"""
How far a key scrolls the page while it's read, or nothing for a key that doesn't
scroll it. `command` is the command that the key runs while the page isn't read.
The keys that move the caret up and down scroll a little. The keys that move it
a screen, and Space, scroll a screen less a little, so a line or two stays in
sight. Home, End and the keys that move the caret to the top or the bottom of
the page scroll that far.
"""
read_step(e, K, command, shift) = begin
  screen = e.scroll.viewport - 40px
  command == :up ? -50px :
  command == :down ? 50px :
  command == :page_up ? -screen :
  command == :page_down ? screen :
  command == :doc_start || (K == Keys.home && command in (nothing, :line_start)) ? px(-Inf) :
  command == :doc_end || (K == Keys._end && command in (nothing, :line_end)) ? px(Inf) :
  command === nothing && K == Keys.space ? (shift ? -screen : screen) : nothing
end

"Scroll the page by `by`, as far as it goes"
scroll_page!(e, by) = begin
  s = e.scroll
  s.offset = clamp(s.offset + by, 0px, max(0px, s.content_height - s.viewport))
  e
end

"True when `a` is `b` or holds it"
holds(a, b) = begin
  while b !== nothing
    b === a && return true
    b = b.parent
  end
  false
end

"""
True when the node that has the keyboard is something other than the text, and
the click that is happening now is on that node, or on a part of it, or on a
node that holds it. A click on a list in a live block gives the list the
keyboard, and the click goes on to the page after the list has taken it.
"""
took(e) = begin
  w = window_of(e)
  w === nothing && return false
  f, under = w.focus, hittest(w)
  (f === nothing || f === e || f === input(e) || under === nothing) && return false
  holds(f, under) || holds(under, f)
end

"A heading as a link names it: its letters and digits in lower case, with a - where anything else is. `Live blocks` is `live-blocks`."
heading_slug(words) = String(strip(replace(lowercase(plain_cell(words)), r"[^\p{L}\p{N}]+" => "-"), '-'))

"""
Follow a link that names a heading of a page: `welcome.md#tables`, or `#tables`
for a heading of the page that shows. The page opens, and the heading goes to
the top of the window. It's true when the link names a page. It's false for any
other link with a # in it, like the address of a web page.
"""
follow_heading!(e, url) = begin
  file, name = String.(split(url, '#', limit=2))
  path = isempty(file) ? e.buf.path : abspath(docdir(e), unescaped(file))
  (ismarkdown(path) && isfile(path)) || return false
  path == e.buf.path || open!(e, path)
  b = e.buf
  ks = kinds(b)
  i = findfirst(i -> ks[i].kind == Kind.heading && heading_slug(rest(b.lines[i], ks[i].prefix)) == heading_slug(unescaped(name)), eachindex(ks))
  i === nothing && return true   # the page has no such heading, so it shows from where it was
  show_line!(e, i)
  # Its line goes near the top of the window. The next frame does it, once it has laid out the page.
  e.nodes[:hold] = (i, 24px - PAGE_TOP)
  true
end

"Open a link: a file on the Mac in this editor, like a page, or a file that came with an email, and anything else in the app the system picks for it"
follow!(e, url) = begin
  startswith(url, '^') && return follow_note!(e, url[2:end])
  occursin('#', url) && follow_heading!(e, url) && return e   # a heading of a page, like welcome.md#tables
  path = abspath(docdir(e), unescaped(url))
  isfile(path) ? open!(e, path) : open_url(url)
end

drag!(e, pos) = begin
  held(e, Keys.mouse_left) && e.clicked[3] == 1 || return
  at = settle(e.buf, locate(e, pos))
  at == e.buf.caret && return
  e.buf.caret = at
  touch!(e)
end

onkey(d::Document, ev::KeyPress{Keys.mouse_left}) = press!(editor(d), ev.window.mouse)
onkey(p::Page, ev::KeyPress{Keys.mouse_left}) = press!(editor(p), ev.window.mouse)
onmouse(d::Document, ev::MouseMove) = drag!(editor(d), ev.position)
onmouse(p::Page, ev::MouseMove) = drag!(editor(p), ev.position)

# --- editing -----------------------------------------------------------------------------

"Put `new` where the selection is, or at the caret"
type!(e, new; typing=false) = begin
  b = e.buf
  run = picked(b)
  if run !== nothing
    isempty(new) && return e
    # What's pasted or inserted while the caret is on a part as a whole goes on a line of its own under the part
    b.caret = b.anchor = line_end(b, run[2])
    new = "\n" * new
  end
  cell = cellat(b, b.caret)
  if cell !== nothing && b.caret[1] == b.anchor[1]
    # In a row of a table, typing only ever changes the cell the caret is in
    lo, hi = selection(b)
    (within(cell, lo[2]) && within(cell, hi[2])) || (b.anchor = b.caret)
    new = replace(new, '\n' => ' ')
  end
  lo, hi = selection(b)
  # A third ` that opens a code block. Inside a block it would close that block instead.
  fence = new == "`" && lo == hi && kinds(b)[lo[1]].kind != Kind.code && strip(b.lines[lo[1]]) == "``" && lo[2] == length(b.lines[lo[1]])
  if rich(b) && lo != hi
    # As rich text, the markup of text that's only partly selected stays, after what's typed
    from, to, kept = richcut(b, lo, hi, typed=!isempty(new))
    edit!(b, from, to, new * kept; typing)
    parts = split(new, '\n')
    b.caret = b.anchor = (from[1] + length(parts) - 1, length(parts) == 1 ? from[2] + length(new) : length(last(parts)))
  else
    edit!(b, lo, hi, new; typing)
  end
  if fence
    # The line that closes the block is typed too. Without it, the block would
    # take the line that opens the next block as its end, and turn every block
    # after it inside out.
    at = b.caret
    edit!(b, at, at, "\n```")
    b.caret = b.anchor = at
  end
  touch!(e)
end

line_end(b, i) = (i, length(b.lines[i]))

"The place one character of the file before or after `p`"
neighbour(b::Buffer, (i, col)::Pos, by::Int) =
  by < 0 ? (col > 0 ? (i, col - 1) : i > 1 ? line_end(b, i - 1) : (i, col)) :
           (col < length(b.lines[i]) ? (i, col + 1) : i < length(b.lines) ? (i + 1, 0) : (i, col))

"""
The place one character before or after `p`. As rich text that's one
character that shows: the place is past any markup that's in the way, and past
the whole of something that shows as one thing, like the number of a footnote.
"""
beside(b::Buffer, p::Pos, by::Int) = begin
  rich(b) || return neighbour(b, p, by)
  run = p == b.caret ? picked(b) : nothing
  # From a part that the caret is on as a whole, it's the end of the line before the part or the start of the line after it
  run === nothing || return by < 0 ? (run[1] > 1 ? line_end(b, run[1] - 1) : p) : (run[2] < length(b.lines) ? (run[2] + 1, 0) : p)
  i, col = p
  hidden, whole = unseen(b, i), wholes(b, i)
  if by < 0
    for (a, z) in hidden
      a < col <= z && (col = a)
    end
    col <= 0 && return neighbour(b, (i, 0), by)
    k = findfirst(r -> r[2] == col, whole)
    (i, k === nothing ? col - 1 : whole[k][1])
  else
    for (a, z) in hidden
      a <= col < z && (col = z)
    end
    col >= length(b.lines[i]) && return neighbour(b, line_end(b, i), by)
    k = findfirst(r -> r[1] == col, whole)
    (i, k === nothing ? col + 1 : whole[k][2])
  end
end

"The place one word before or after `p`"
word_step(b::Buffer, p::Pos, by::Int) = begin
  i, col = p
  chars = collect(b.lines[i])
  # As rich text, a line's text can start after characters that don't show, like the # of a heading
  (by < 0 ? col <= first_stop(b, i) : col == length(chars)) && return beside(b, p, by)
  if by < 0
    while col > 0 && !isword(chars[col]); col -= 1 end
    while col > 0 && isword(chars[col]); col -= 1 end
  else
    while col < length(chars) && !isword(chars[col+1]); col += 1 end
    while col < length(chars) && isword(chars[col+1]); col += 1 end
  end
  (i, col)
end

"The place one line up or down the screen from the caret, in the order of the page's lines. `vertical` keeps it in a column of the page."
line_step(e, by::Int) = begin
  b = e.buf
  i, col = b.caret
  run = picked(b)
  if run !== nothing
    # From a part that the caret is on as a whole, ↑ goes to the line before the part and ↓ to the line after it
    j = by > 0 ? run[2] + 1 : run[1] - 1
    j < 1 && return b.caret
    if j > length(b.lines)
      # ↓ on a part at the end of the document starts a line below it, as it does under a table
      edit!(b, line_end(b, length(b.lines)), line_end(b, length(b.lines)), "\n")
      return (length(b.lines), 0)
    end
    x = e.goal = something(e.goal, 0px)
    free(b, j, 0) || return by > 0 ? (j, 0) : line_end(b, j)
    into = item(e, j)
    into.content isa Sheet && return enter(e, into, into.content, by, x)
    f = flow(e, j, false)
    return (j, colat(f, by < 0 ? length(f.lines) : 1, x))
  end
  it = item(e, i)
  at = it.content isa Grid ? gridcell(it.content, b.caret) : nothing
  at === nothing || return vertical(e, it, at, by)
  it.content isa Sheet && return vertical(e, it, it.content, by)
  f = flow(e, i)
  k, x = spot(f, col)
  x = e.goal = something(e.goal, x)
  1 <= k + by <= length(f.lines) && return (i, colat(f, k + by, x))
  j = i + by
  if rich(b)
    # As rich text, the caret steps over a line that doesn't show, like the ``` of a code block
    j = step_over(b, j, by, i)
    if j > length(b.lines) && i < length(b.lines)
      # ↓ over such a line at the end of the document starts a line below it, as it does under a table
      edit!(b, line_end(b, length(b.lines)), line_end(b, length(b.lines)), "\n")
      return (length(b.lines), 0)
    end
    # It goes onto a part that shows as one thing, like a diagram, as a whole
    1 <= j <= length(b.lines) && !free(b, j, i) && return (j, 0)
  end
  j < 1 && return (1, 0)
  j > length(b.lines) && return line_end(b, i)
  # Into a sheet, the caret goes to the cell that's under it or over it
  into = item(e, j)
  into.content isa Sheet && return enter(e, into, into.content, by, x)
  # The line is laid out as it will show with the caret on it
  f = flow(e, j, b.plain)
  (j, colat(f, by < 0 ? length(f.lines) : 1, x))
end

"The place one line up or down from the caret, which is in row `r`, column `c` of a table"
vertical(e, it::Item, (r, c), by::Int) = begin
  b = e.buf
  g = it.content::Grid
  f = g.flows[r][c]
  k, x = spot(f, b.caret[2])
  x = e.goal = something(e.goal, x)
  1 <= k + by <= length(f.lines) && return (b.caret[1], cellcol(f, k + by, x, g.cells[r][c]))
  r += by
  if r < 1
    return it.first > 1 ? line_end(b, it.first - 1) : b.caret
  elseif r > length(g.rows)
    # ↓ on the last row of a table at the end of the document starts a line below it
    it.last == length(b.lines) && edit!(b, line_end(b, it.last), line_end(b, it.last), "\n")
    return (it.last + 1, 0)
  end
  isempty(g.cells[r]) && return (g.rows[r], 0)
  c = min(c, length(g.cells[r]))
  f = g.flows[r][c]
  (g.rows[r], cellcol(f, by < 0 ? length(f.lines) : 1, x, g.cells[r][c]))
end

"The start or end of the line of the screen that the caret is on"
screen_edge(e, by::Int) = begin
  cell = cellat(e.buf, e.buf.caret)
  cell === nothing || return (e.buf.caret[1], by < 0 ? cell.lo : cell.hi)
  i, col = e.buf.caret
  f = flow(e, i)
  k, _ = spot(f, col)
  vl = f.lines[k]
  by < 0 ? (i, vl.from) : (i, k < length(f.lines) ? max(vl.from, vl.to - 1) : vl.to)
end

"""
Where a selection that grows to `p` ends. It steps over the ``` lines of a code
block that the selection didn't start in, and over the whole of a block that
shows as one thing, like a diagram or a contact, because those lines don't show.
"""
pass(b::Buffer, p::Pos, by::Int) = begin
  ks = kinds(b)
  i = p[1]
  ks[i].kind in (Kind.fence, Kind.code) || return p
  s, t = codeblock(b, i)
  s <= b.anchor[1] <= t && return p
  whole = solid(b, i)
  if whole !== nothing && whole[1] < whole[2]
    # Under a block that ends the document there's no line to go to, so the selection ends where the block does
    by > 0 && whole[2] == length(b.lines) && return line_end(b, whole[2])
    i = by < 0 ? whole[1] - 1 : whole[2] + 1
  elseif ks[i].kind == Kind.fence
    i += by
  else
    return p
  end
  1 <= i <= length(b.lines) || return p
  by < 0 ? line_end(b, i) : (i, 0)
end

"Move the caret to `p`, which was reached by going in the direction `by`. With `extend`, the selection grows to it."
move!(e, p::Pos, extend::Bool; keep_goal=false, by=0) = begin
  p = settle(e.buf, p, by)
  extend && by != 0 && (p = pass(e.buf, p, by))
  e.buf.caret = p
  extend || (e.buf.anchor = p)
  touch!(e; keep_goal)
end

erase!(e, to::Pos) = begin
  b = e.buf
  picked(b) === nothing || return delete_lines!(e)   # the part that the caret is on as a whole goes
  insheet(b, b.caret[1]) && !selecting(b) && erase_row!(e, to) && return
  cell = cellat(b, b.caret)
  # In a table, a cell's edges can't be deleted
  cell === nothing || selecting(b) || (to[1] == b.caret[1] && within(cell, to[2])) || return
  selecting(b) || (b.anchor = to)
  type!(e, "")
end

"Return starts a new line. What else it does depends on the block the caret is in."
newline!(e) = begin
  b = e.buf
  picked(b) === nothing || return enter_part!(e)   # Return gives the keyboard to the part that the caret is on
  insheet(b, b.caret[1]) && b.caret[1] == b.anchor[1] && return next_row!(e)
  isempty(rowcells(b, b.caret)) || return next_cell!(e, false, down=true)
  selecting(b) ? type!(e, "\n") : newline!(e, block(b, b.caret[1]))
end

newline!(e, block) = begin
  b = e.buf
  i, col = b.caret
  if rich(b) && kinds(b)[i].kind == Kind.heading && col <= first_stop(b, i) < length(b.lines[i])
    # As rich text, Return at the start of a heading's text moves the heading down a line
    edit!(b, (i, 0), (i, 0), "\n")
    b.caret = b.anchor = (i + 1, col)
    return touch!(e)
  end
  shut, opened = halves!(b)
  type!(e, shut * "\n" * opened)
end

# In a list or a quote, the new line carries it on
newline!(e, ::Type{<:Union{List,Quote,Paragraph}}) = begin
  b = e.buf
  i, col = b.caret
  text, line = b.lines[i], kinds(b)[i]
  k = line.kind
  col < line.prefix && return type!(e, "\n")
  lead = head(text, line.prefix)
  # The line after the one that names a callout is a line of the callout: it starts with the > and no more
  if opens_callout(line)
    shut, opened = halves!(b)
    return type!(e, shut * "\n> " * opened)
  end
  # Return on an empty list item ends the list
  # What starts the item goes as it's written. As rich text, a selection that's
  # deleted keeps what starts its line, so `type!` would leave the item there.
  if length(text) == line.prefix && k != Kind.paragraph
    edit!(b, (i, 0), (i, line.prefix), "")
    return touch!(e)
  end
  # As rich text, bold text that the new line cuts in two is bold on both lines
  shut, opened = halves!(b)
  type!(e, shut * "\n" * carry(lead, k) * opened)
end

"What starts the line after a list item or a quote that starts with `lead`: the next number, or a to-do box with no tick"
carry(lead, k::Kind) = begin
  k == Kind.todo && return replace(lead, r"\[[xX]\]" => "[ ]")
  m = k == Kind.ordered ? match(r"^(\s*)(\d+)(.*)$", lead) : nothing
  m === nothing ? lead : string(m[1], parse(Int, m[2]) + 1, m[3])
end

# In code, the new line starts under the text of the line before. It starts
# one step further in after a line that opens a block.
newline!(e, ::Type{CodeBlock}) = begin
  b = e.buf
  i, col = b.caret
  line = kinds(b)[i]
  if line.kind == Kind.fence && line.level == 0 && line.lang == SHEET && col == length(b.lines[i])
    # The line that opens a sheet. Its first row starts with a place for a name.
    type!(e, "\n = ")
    b.caret = b.anchor = (i + 1, 0)
    return touch!(e)
  end
  if line.kind == Kind.fence && line.level == 0 && line.lang == SPREADSHEET && col == length(b.lines[i])
    # The line that opens a spreadsheet. Its first row starts with three cells, and the caret goes to the first.
    type!(e, "\n|  |  |  |")
    b.caret = b.anchor = (i + 1, 2)
    return touch!(e)
  end
  line.kind == Kind.fence && return type!(e, "\n")
  before = head(b.lines[i], col)
  type!(e, "\n" * match(r"^ *", before).match * (opens(before, line.lang) ? indentation(e, CodeBlock) : ""))
end

const STEP = "  "   # one step of indentation
const OPENERS = r"^\s*(function|if|elseif|else|for|while|let|try|catch|finally|struct|mutable struct|module|macro|quote)\b"

"True when a line of code that ends with `text` opens a block, so the next line goes further in"
opens(text::AbstractString, lang::AbstractString) = begin
  s = rstrip(text)
  isempty(s) && return false
  last(s) in "([{" && return true
  lowercase(lang) in ("python", "py") && return last(s) == ':'
  lowercase(lang) in ("julia", "jl", LIVE) || return false
  occursin(r"\b(begin|do( [\w, ]+)?)$", s) || (occursin(OPENERS, s) && !occursin(r"\bend$", s))
end

"Where backspace deletes back to from the caret: one character, or one step of `n` of the spaces that start a line"
backstep(b::Buffer, block, n=length(STEP)) = begin
  i, col = b.caret
  indented = col > 0 && !selecting(b) && all(==(' '), head(b.lines[i], col))
  indented ? (i, col - (col - 1) % n - 1) : beside(b, b.caret, -1)
end

# In a table the spaces belong to a cell
backstep(b::Buffer, ::Type{Table}, n=0) = beside(b, b.caret, -1)

# In code, a bracket that you type comes with the bracket that closes it, and
# the caret stays between the two. A quote comes with the quote that ends the
# string. This is so in a file of code and in a code block of a page.
#
#   - The closing one only comes where it can't join a word: at the end of the
#     line, or before a space, a comma or another closing bracket.
#   - A closing bracket or a quote that you type where the same one already is
#     goes over that one. So `f(x)` typed one key after another is `f(x)`.
#   - With text selected, a bracket or a quote goes round the text, and the
#     text stays selected.
#   - A quote that's typed in a string ends the string, and comes alone. A ' after
#     a name is Julia's transpose, or the ' of a word like "don't", and comes alone too.
#   - A third quote after two makes the six quotes of a string of several lines.
#   - ⌫ between the two of a pair that has nothing in it takes both away.

const PAIRS = Dict('(' => ')', '[' => ']', '{' => '}', '"' => '"', '\'' => '\'')
const CLOSING = Set(values(PAIRS))

"True when line `i` is code that's typed as text. A row of a sheet or a spreadsheet is typed as a cell."
typed_code(b::Buffer, i::Int) = kinds(b)[i].kind == Kind.code && !insheet(b, i) && !inspread(b, i)

"How many quotes in `text` start or end a string. One after a \\ is a character of its string."
quotes(text::AbstractString) = count(r"(?<!\\)\"", text)

"True when line `i` up to `before` is inside a string of several lines: an odd number of \"\"\" come before it in its code"
in_long_string(b::Buffer, i::Int, before::AbstractString) = begin
  top = b.view == :code ? 1 : codeblock(b, i)[1] + 1
  isodd(sum(l -> count("\"\"\"", l), @view(b.lines[top:i-1]), init=0) + count("\"\"\"", before))
end

"""
Type the character `c` at the caret, as code does: a bracket or a quote comes
with the one that closes it. It returns false, and types nothing, where `c` is
typed as any other character is.
"""
pair!(e, c::Char) = begin
  b = e.buf
  picked(b) === nothing || return false
  lo, hi = minmax(b.caret, b.anchor)
  all(i -> typed_code(b, i), lo[1]:hi[1]) || return false
  close = get(PAIRS, c, nothing)
  if lo != hi
    # A bracket or a quote goes round the text that's selected, and the text stays selected
    close === nothing && return false
    back = b.caret < b.anchor
    edit!(b, lo, hi, c * excerpt(b, lo, hi) * close)
    from, to = (lo[1], lo[2] + 1), (hi[1], hi[2] + (lo[1] == hi[1]))
    b.anchor, b.caret = back ? (to, from) : (from, to)
    touch!(e)
    return true
  end
  i, col = lo
  before, after = head(b.lines[i], col), rest(b.lines[i], col)
  next = isempty(after) ? nothing : first(after)
  if next == c && c in CLOSING
    # The one that closes is already here, so the caret goes over it
    b.caret = b.anchor = (i, col + 1)
    touch!(e)
    return true
  end
  close === nothing && return false
  # Before a word, the one that closes would have to be moved to the word's end by hand
  roomy = next === nothing || isspace(next) || next in ")]},;:" || (c in "([{" && next == '"')
  roomy || return false
  if c == '"' && endswith(before, "\"\"") && !endswith(before, "\"\"\"")
    # The third quote of three. It starts a string of several lines, or it ends the one that the caret is in.
    in_long_string(b, i, chop(before, tail=2)) && return false
    close = "\"\"\""
  elseif c == '"'
    isodd(quotes(before)) && return false   # this quote ends a string
  elseif c == '\'' && !isempty(before)
    prev = last(before)
    (isnamechar(prev) || prev in ")]}'") && return false
  end
  edit!(b, lo, lo, c * close, typing=true)
  b.caret = b.anchor = (i, col + 1)
  touch!(e)
  true
end

"True when the caret is in code between a bracket or a quote and the one that closes it, with nothing between them"
in_empty_pair(b::Buffer) = begin
  i, col = b.caret
  line = b.lines[i]
  (!selecting(b) && 0 < col < length(line) && typed_code(b, i)) || return false
  at = nextind(line, 0, col)
  get(PAIRS, line[at], nothing) == line[nextind(line, at)]
end

# In code, the two brackets that the caret is between glow: the nearest ( [
# or { before the caret that's still open there, and the bracket that closes
# it. The two can be on different lines. Each has a soft light in its own
# shape, in the colour of a link, and two that touch have one light.
#
#   - A bracket in a string or a comment isn't one of the code's brackets. With
#     the caret in a string or a comment, the brackets are the ones in the
#     strings or the comments of the caret's line.
#   - A bracket that's closed by another kind of bracket doesn't glow.
#   - Nothing glows while text is selected.

const PAIR_REACH = 2000   # lines. A bracket that's further from the caret than this isn't looked for.
const OPENING, ENDING = "([{", ")]}"

"What each character of line `i` is a part of: :code, :string or :comment"
parts_of(b::Buffer, i::Int) = begin
  out = Symbol[]
  for t in tokens(b.lines[i], shared_lang(kinds(b)[i].lang))
    append!(out, fill(t.kind in (:string, :comment) ? t.kind : :code, length(t.text)))
  end
  out
end

"""
The places of the two brackets that the caret is between, in code: the one that
opens and the one that closes. Nothing when the caret isn't between two.
"""
bracket_pair(b::Buffer) = begin
  i, col = b.caret
  (!selecting(b) && picked(b) === nothing && typed_code(b, i)) || return nothing
  here = parts_of(b, i)
  col = min(col, length(here))   # a caret that a change left past the end of its line is at the end
  before = col > 0 ? here[col] : :code
  after = col < length(here) ? here[col+1] : before == :comment ? :comment : :code
  # At the edge of a string, the caret is in the code
  part = before == after ? before : :code
  top, bottom = b.view == :code ? (1, length(b.lines)) : codeblock(b, i) .+ (1, -1)
  top, bottom = part == :code ? (max(top, i - PAIR_REACH), min(bottom, i + PAIR_REACH)) : (i, i)
  # The characters of line `l` that are brackets of the caret's part, or nothing when it has none
  brackets(l) = begin
    any(in("()[]{}"), b.lines[l]) || return nothing
    parts = l == i ? here : parts_of(b, l)
    [(k, c) for (k, c) in enumerate(b.lines[l]) if (c in OPENING || c in ENDING) && parts[k] == part]
  end
  open = nothing
  closed = Char[]   # the brackets between the caret and here that close one before here
  for l in i:-1:top
    found = brackets(l)
    found === nothing && continue
    for (k, c) in Iterators.reverse(found)
      l == i && k > col && continue
      if c in ENDING
        push!(closed, c)
      elseif isempty(closed)
        open = (l, k - 1, c)
        break
      elseif closed[end] == PAIRS[c]
        pop!(closed)
      end
    end
    open === nothing || break
  end
  open === nothing && return nothing
  opened = Char[]   # what closes the brackets that open between the caret and here
  for l in i:bottom
    found = brackets(l)
    found === nothing && continue
    for (k, c) in found
      l == i && k <= col && continue
      if c in OPENING
        push!(opened, PAIRS[c])
      elseif isempty(opened)
        return c == PAIRS[open[3]] ? ((open[1], open[2]), (l, k - 1)) : nothing
      elseif opened[end] == c
        pop!(opened)
      end
    end
  end
  nothing
end

"The two brackets that the caret is between. They're looked for once for each place of the caret in each version of the text."
caret_pair(e) = begin
  b = e.buf
  key = (b.path, b.version, b.caret, b.anchor)
  kept = get(e.nodes, :bracket_pair, nothing)
  kept !== nothing && kept[1] == key && return kept[2]
  found = bracket_pair(b)
  e.nodes[:bracket_pair] = (key, found)
  found
end

"""
The runs of text that glow for the two brackets at `found`: the line of each,
and its columns. Two brackets with nothing between them are one run, so they
have one light.
"""
bracket_runs((open, close)) =
  open[1] == close[1] && close[2] == open[2] + 1 ? [(open[1], open[2], open[2] + 2)] : [(i, col, col + 1) for (i, col) in (open, close)]

"""
Make the two brackets that the caret is between glow: a soft light in the shape
of each bracket, and the bracket over it in the light's colour. The page's text
is at `ui`.
"""
glow_bracket_pair(ctx, e, ui) = begin
  b = e.buf
  (caretless(b) || readonly(b)) && return
  w = window_of(e)
  (w !== nothing && w.focus === e) || return   # as the caret does, the light shows while the page has the keyboard
  found = caret_pair(e)
  found === nothing && return
  light, lit = ink(tint(colours.accent, 0.65)), ink(colours.accent)
  blur = Skia.sk_maskfilter_new_blur_with_flags(Skia.SK_BLUR_STYLE_NORMAL, 3f0, true)
  Skia.sk_paint_set_maskfilter(light, blur)
  for it in e.layout[e.shown], (i, from, to) in bracket_runs(found)
    f = it.content
    (f isa Flow && it.first == i) || continue
    for (k, vl) in enumerate(f.lines), seg in vl.segs
      lo, hi = max(from, seg.col), min(to, seg.col + seg.n)
      (hi > lo && seg.node === nothing && !seg.atomic) || continue
      words = String(collect(seg.text)[lo-seg.col+1:hi-seg.col])
      x = num(ui.left + seg.x + inset(seg, lo - seg.col))
      # The brackets stand on the line that the text stands on
      y = num(ui.top + it.top + line_top(f, k) + (vl.high + capital(seg.face)) / 2)
      blob = Skia.sk_textblob_make_from_string(words, skia_font(seg.face.family, seg.face.size, seg.face.style).raw, Skia.SK_TEXT_ENCODING_UTF8)
      # The light is drawn twice, since a bracket is thin
      for paint in (light, light, lit)
        Skia.sk_canvas_draw_text_blob(ctx, blob, Float32(x), Float32(y), paint)
      end
      Skia.sk_textblob_unref(blob)
    end
  end
  Skia.sk_maskfilter_unref(blur)
  Skia.sk_paint_delete(light)
  Skia.sk_paint_delete(lit)
end

"Tab moves text in, and shift-Tab moves it back out. What they move depends on the block the caret is in."
indent!(e, out::Bool) = begin
  b = e.buf
  insheet(b, b.caret[1]) && return sheet_tab!(e, out)
  isempty(rowcells(b, b.caret)) || return next_cell!(e, out)
  indent!(e, out, block(b, b.caret[1]))
end

indent!(e, out::Bool, block) = out ? nothing : type!(e, STEP)

# In code, Tab goes to the next step. With a selection, or with shift, it moves every line the selection touches.
indent!(e, out::Bool, ::Type{CodeBlock}) = begin
  b = e.buf
  tab = indentation(e, CodeBlock)   # as many spaces as the settings page says
  out || selecting(b) || return type!(e, " " ^ (length(tab) - b.caret[2] % length(tab)))
  ends = Dict(:caret => b.caret, :anchor => b.anchor)
  lo, hi = minmax(b.caret, b.anchor)
  for i in lo[1]:hi[1]
    kinds(b)[i].kind == Kind.code || continue
    n = out ? min(length(tab), length(match(r"^ *", b.lines[i]).match)) : length(tab)
    isempty(b.lines[i]) && continue
    edit!(b, (i, 0), (i, out ? n : 0), out ? "" : tab)
    for (name, (l, col)) in ends
      l == i && (ends[name] = (i, max(0, col + (out ? -n : n))))
    end
  end
  b.caret, b.anchor = ends[:caret], ends[:anchor]
  touch!(e)
end

# In a list, Tab moves the item in and shift-Tab moves it back out
indent!(e, out::Bool, ::Type{List}) = begin
  b = e.buf
  i, col = b.caret
  selecting(b) && return out ? nothing : type!(e, STEP)
  n = out ? min(2, kinds(b)[i].level) : 2
  edit!(b, (i, 0), (i, out ? n : 0), out ? "" : "  ")
  b.caret = b.anchor = (i, max(0, col + (out ? -n : n)))
  touch!(e)
end

"""
Go to the next cell of a table and select what's in it, or with `back` the one
before. With `down`, go to the same cell of the next row. Going on from the end
of the table adds a row.
"""
next_cell!(e, back::Bool; down=false) = begin
  b = e.buf
  i, col = b.caret
  rows = gridrows(b, i)
  r = findfirst(==(i), rows)
  cs = rowcells(b, b.caret)
  c = nearest(cs, col)
  if down
    r += 1
  elseif back
    c -= 1
    c < 1 && (r -= 1; c = 0)
  else
    c += 1
    c > length(cs) && (r += 1; c = 1)
  end
  r < 1 && return
  if r > length(rows)
    t = last(rows)
    edit!(b, line_end(b, t), line_end(b, t), "\n|" * repeat("  |", maximum(i -> length(rowcells(b, (i, 0))), rows)))
    push!(rows, t + 1)
  end
  cs = rowcells(b, (rows[r], 0))
  isempty(cs) && return move!(e, (rows[r], 0), false)
  cell = cs[c == 0 ? length(cs) : min(c, length(cs))]
  b.anchor, b.caret = (rows[r], cell.lo), (rows[r], cell.hi)
  touch!(e)
end

"Put `mark` around the selection, or take it away if it's there already"
surround!(e, mark::String) = begin
  b = e.buf
  picked(b) === nothing || return
  lo, hi = selection(b)
  lo[1] == hi[1] || return
  if rich(b)
    # As rich text, each end of a selection can be on either side of markup that doesn't show. A selection
    # of all the text that `mark` marks is that text, whichever side its ends are on.
    _, ss = richspans(b, lo[1])
    hidden = unseen(b, lo[1])
    for (o, c) in markpairs(ss)
      ss[o].text == mark || continue
      from, to = ss[o].col + length(mark), ss[c].col
      opens = findfirst(r -> r[1] <= ss[o].col && from <= r[2], hidden)
      closes = findfirst(r -> r[1] <= to && to + length(mark) <= r[2], hidden)
      (opens === nothing || closes === nothing) && continue
      hidden[opens][1] <= lo[2] <= hidden[opens][2] && hidden[closes][1] <= hi[2] <= hidden[closes][2] || continue
      lo, hi = (lo[1], from), (hi[1], to)
      break
    end
  end
  i, n = lo[1], length(mark)
  line = b.lines[i]
  inner = rest(head(line, hi[2]), lo[2])
  if lo[2] >= n && rest(head(line, lo[2]), lo[2] - n) == mark && head(rest(line, hi[2]), n) == mark
    edit!(b, (i, lo[2] - n), (i, hi[2] + n), inner)
    b.anchor, b.caret = (i, lo[2] - n), (i, hi[2] - n)
  else
    edit!(b, lo, hi, mark * inner * mark)
    b.anchor, b.caret = (i, lo[2] + n), (i, hi[2] + n)
  end
  touch!(e)
end

"Copy what's selected. With several selections, each one's text goes on a line of its own, in the order of the page."
copy_selection!(e) = begin
  b = e.buf
  selecting(b) && write_blocks!(e)   # a block that a file defines is copied as what it holds now
  spans = selecting(b) ? [selection(b)] : Tuple{Pos,Pos}[]
  with_others(() -> selecting(b) && push!(spans, selection(b)), b)
  isempty(spans) ? false : clipboard(join((excerpt(b, s...) for s in sort(spans)), "\n"))
end

"""
Put what the clipboard holds into the text at the caret. Files that were
copied in the Finder go in the way a dropped file does: a picture shows as a
picture, and a video, a sound, a PDF or any other file as a path that shows
what's in the file. A picture that was copied as itself, like a screenshot, is
written to a file in the media folder beside the document first. So is a PDF,
a sound or a video that was copied as itself. Anything else is pasted as text.

A file in a folder for temporary files is copied to that media folder,
and the copy is what goes in. An app that takes screenshots puts its picture
on the clipboard as a file like that, and macOS removes the file later.
"""
paste!(e) = begin
  b = e.buf
  paths = Pasteboard.files()
  if isempty(paths)
    text = Sys.isapple() ? Pasteboard.text() : clipboard()
    # A contact that was copied in the Contacts app goes in as a block of contacts
    list = copied_contacts(e, text)
    isempty(list) || return paste_contacts!(e, list)
    # A picture that's copied from a web page comes with its address as text, and the picture is what's wanted
    found = isempty(strip(text)) || occursin(r"^\s*\w+://\S+\s*$", text) ? Pasteboard.media() : nothing
    path = found === nothing ? nothing : keep_pasted(e, found...)
    path === nothing && return each_selection!(() -> type!(e, replace(text, "\r\n" => "\n", '\r' => '\n', '\t' => "  ")), e)
    paths = [path]
  end
  paths = [passing(e, p) ? something(keep_copy(e, p), p) : p for p in paths]
  selecting(b) && type!(e, "")
  put_files!(e, paths, settle(b, b.caret))
end

# A file that a page makes goes in a folder called .media beside the page: a
# picture that's pasted, a recording, a copy of a temporary file. Only the page
# that made it has a use for it, so it stays out of the list of the page's
# folder. The Finder and the sidebar leave out a name that starts with a dot
# until you ask for the hidden files.
const PAGE_MEDIA = ".media"

"The folder for the files that the pages of the folder `dir` make. It's made if it isn't there."
page_media(dir) = begin
  media = joinpath(dir, PAGE_MEDIA)
  # A folder that can't be made leaves the file's own write to say what went wrong
  try mkpath(media) catch end
  media
end

"""
Write `bytes` that were pasted to a new file in the media folder of the
document's folder, and return its path. `ext` is the end of the file's name,
like "png". Nothing if the document has no folder yet.
"""
keep_pasted(e, ext, bytes) = begin
  dir = docdir(e)
  isdir(dir) || return nothing
  path = unused(page_media(dir), "pasted-" * Libc.strftime("%Y%m%d-%H%M%S", time()), ".$ext")
  write(path, bytes)
  list_files!(e)   # a sidebar that shows hidden files lists the media folder, or the new file in it
  path
end

"A path in `dir` that no file has yet: `stem` and `ext`, with a number after the stem if that name is taken"
unused(dir, stem, ext) = begin
  path = joinpath(dir, stem * ext)
  n = 1
  while ispath(path)
    path = joinpath(dir, "$stem-$(n += 1)$ext")
  end
  path
end

# The folders that macOS keeps temporary files in, and empties by itself
const PASSING = ("/private/var/folders/", "/var/folders/", "/private/tmp/", "/tmp/")

"True when the file at `path` is a temporary one, which macOS removes later. A file in the document's own folder is never one."
passing(e, path) = isfile(path) && dirname(path) != docdir(e) && any(p -> startswith(path, p), PASSING)

"""
Copy the file at `path` to the media folder of the document's folder, under
its own name, and return the copy's path. Nothing if the document has no
folder yet.
"""
keep_copy(e, path) = begin
  dir = docdir(e)
  isdir(dir) || return nothing
  copy = unused(page_media(dir), splitext(basename(path))...)
  cp(path, copy)
  list_files!(e)
  copy
end

zoom!(e, z) = (e.zoom = clamp(z, 0.6, 2.5); save_settings!(e); rerun!(e, :zoom); restyle!(e))

"The size of the page's text, to the nearest pixel"
text_size(e) = round(Int, TEXT_SIZE.value * e.zoom)
# The page's text is a whole number of pixels tall, so the settings page can show its size as a number
"The zoom that makes the page's text `size` pixels tall. Sizes are whole numbers from 11 to 42."
zoom_for(size) = clamp(round(Int, size), 11, 42) / TEXT_SIZE.value

"The one after `x` in `list`, going back to the start after the last"
after(list, x) = list[mod1(findfirst(==(x), list) + 1, length(list))]

const THEME_ORDER = (:sepia, :paper, :night)

const STATS = (:words, :chars, :minutes)
const STAT_NAMES = ("Words", "Characters", "Reading time")   # what the settings page calls them

"Make the count at the top right count `stat`: one of `STATS`"
stat!(e, stat::Symbol) = (e.stat = stat; save_settings!(e); rerun!(e, :stat); e)
next_stat!(e) = stat!(e, after(STATS, e.stat))

const SLIDE_TIME = 0.25   # seconds for the sidebar to slide in or out

"Show the sidebar if it's hidden, or hide it. It slides from where it is now."
toggle_panel!(e) = (e.slid_from = opened(e); e.slid = time(); e.panel = !e.panel)

sliding(e) = time() - e.slid < SLIDE_TIME

"How far the sidebar is open, from 0 to 1"
opened(e) = begin
  to = e.panel ? 1.0 : 0.0
  sliding(e) || return to
  t = (time() - e.slid) / SLIDE_TIME
  t = t < 0.5 ? 4t^3 : 1 - (2 - 2t)^3 / 2   # slow at the start and the end
  e.slid_from + (to - e.slid_from) * t
end

"The most of the window's width that the sidebar can have, so the page keeps room beside it"
widest_panel(e) = max(PANEL_MIN, min(PANEL_MAX, px(floor(num(window_size(e)[1]) / 2))))

"How wide the sidebar is when it's open. A narrow window makes it narrower than you dragged it."
panel_w(e) = min(e.side, widest_panel(e))

"Make the sidebar `w` pixels wide, or as near to that as it can be, and keep the width in the settings"
side!(e, w) = begin
  w = px(round(num(clamp(w, PANEL_MIN, widest_panel(e)))))
  w == e.side && return e
  e.side = w
  save_settings!(e)
  e
end

ismouse(k) = k in (Keys.mouse_left, Keys.mouse_right, Keys.mouse_middle, Keys.mouse_back, Keys.mouse_forward)

# --- key bindings ------------------------------------------------------------------------
#
# Each thing that a key does is a command with a name, like `:save`. A shortcut
# is the keys that run a command: one key with the keys that are held with it,
# like ⌘S, or two of those pressed one after the other, like ⌃X ⌃S. A bundle
# gives every command its shortcuts. Ladder starts with the bundle called
# "Ladder". Each other bundle has the keys of another editor. The key bindings
# page of the settings chooses the bundle, and gives any one command another
# shortcut. The bundle and those changes are settings: every window has the
# same keys, and the settings file keeps them.
#
# A command's kind says where it works:
#   :window  whatever has the keyboard, and on a file that's only shown
#   :look    while the text has the keyboard, and on a file that's only shown as text
#   :edit    while the text has the keyboard. It changes the text.
#   :move    it moves the caret. With ⇧ held too, it grows the selection.
#   :type    it changes the text at the caret, like ⌫. While the page is read it does nothing.
#
# Return, esc and Space have no command. What each does depends on where the caret is.

"A key, and the keys of ⌃, ⌘, ⌥ and ⇧ that are held with it"
struct Stroke
  held::Keys
  key::Keys
end

"The keys that run a command: one stroke, or two that are pressed one after the other"
const Shortcut = Tuple{Vararg{Stroke}}

# The keys that are held with another key: the name that the settings file has for each, and the Mac's sign for it
const HOLDS = ((Keys.ctrl, "ctrl", "⌃"), (Keys.cmd, "cmd", "⌘"), (Keys.opt, "opt", "⌥"), (Keys.shft, "shift", "⇧"))
const HELD = Keys.ctrl | Keys.cmd | Keys.opt | Keys.shft

"Each key that a shortcut can have, by the name that the settings file has for it, like \"z\", \"f5\" or \"pageup\""
const KEY_NAMES = Dict{String,Keys}(lstrip(string(name), '_') => getproperty(Keys, name) for name in keys(instances(Keys))
                                    if !(name in (:shft, :cmd, :opt, :ctrl, :capslock, :fn, :mouse_left, :mouse_right, :mouse_middle, :mouse_back, :mouse_forward)))
const KEY_OF = Dict{Keys,String}(key => name for (name, key) in KEY_NAMES)

"What the key bindings page shows for a key that isn't a letter, a number or an F key"
const KEY_SIGNS = Dict{Keys,String}(
  Keys.enter => "Return", Keys.tab => "Tab", Keys.space => "Space", Keys.backspace => "⌫", Keys.delete => "⌦", Keys.escape => "esc",
  Keys.left => "←", Keys.right => "→", Keys.up => "↑", Keys.down => "↓",
  Keys.home => "Home", Keys._end => "End", Keys.pageup => "Page Up", Keys.pagedown => "Page Down",
  Keys.tilde => "`", Keys.minus => "-", Keys.equal => "=", Keys.left_bracket => "[", Keys.right_bracket => "]", Keys.semicolon => ";",
  Keys.apostrophe => "'", Keys.comma => ",", Keys.period => ".", Keys.slash => "/", Keys.backslash => "\\", Keys.plus => "+", Keys.times => "*")

const TYPING_KEYS = ("tilde", "minus", "equal", "left_bracket", "right_bracket", "semicolon", "apostrophe", "comma", "period", "slash",
                     "backslash", "times", "plus", "space")

"True when the key `K` types a character: a letter, a number or a sign. A shortcut with it needs ⌘, ⌃ or ⌥ too."
typing_key(K) = (name = get(KEY_OF, K, ""); length(name) == 1 || startswith(name, "num") || name in TYPING_KEYS)

"The stroke that `text` writes, like \"cmd+shift+z\", or nothing when it writes none"
read_stroke(text::AbstractString) = begin
  parts = split(text, '+')
  key = get(KEY_NAMES, last(parts), nothing)
  key === nothing && return nothing
  held = Keys(0)
  for part in parts[1:end-1]
    i = findfirst(h -> h[2] == part, HOLDS)
    i === nothing && return nothing
    held |= HOLDS[i][1]
  end
  Stroke(held, key)
end

"The shortcuts that `text` writes, with a comma between them, like \"cmd+z, ctrl+x u\". One that can't be read is left out."
read_shortcuts(text::AbstractString) = begin
  out = Shortcut[]
  for part in split(text, ','; keepempty=false)
    strokes = map(read_stroke, split(part))
    (isempty(strokes) || length(strokes) > 2 || any(isnothing, strokes)) && continue
    push!(out, Tuple(strokes))
  end
  out
end

"How the settings file writes a stroke, a shortcut or a command's shortcuts. `read_shortcuts` reads it back."
written(s::Stroke) = join([[name for (key, name, _) in HOLDS if key in s.held]; KEY_OF[s.key]], '+')
written(s::Shortcut) = join(map(written, s), ' ')
written(list::Vector{Shortcut}) = join(map(written, list), ", ")

"How a stroke or a shortcut reads, like ⌘⇧Z or ⌃X ⌃S"
caps(s::Stroke) = join([sign for (key, _, sign) in HOLDS if key in s.held]) * get(() -> uppercase(KEY_OF[s.key]), KEY_SIGNS, s.key)
caps(s::Shortcut) = join(map(caps, s), ' ')

"""
Something that a key does. `keys` are its shortcuts in the bundle called
Ladder. `run` gets the editor, its window, and true when ⇧ is held to grow
the selection.
"""
struct Command
  name::Symbol
  title::String   # what the key bindings page calls it
  kind::Symbol
  keys::String
  run::Function
end

"Move the caret one character left or right. With a selection and no ⇧, it goes to that end of the selection."
caret_step!(e, by::Int, select::Bool) = begin
  b = e.buf
  lo, hi = selection(b)
  move!(e, selecting(b) && !select ? (by < 0 ? lo : hi) : beside(b, b.caret, by), select; by)
end

"Move the caret most of a screen up or down"
caret_page!(e, by::Int, select::Bool) = foreach(_ -> move!(e, vertical(e, by), select; keep_goal=true, by), 1:20)

"What ⌫ does: it takes away a row of a table that has nothing in it, or what's before the caret"
erase_back!(e) = begin
  b = e.buf
  picked(b) === nothing || return delete_lines!(e)   # the part that the caret is on as a whole goes
  emptyrow(b) && return backrow!(e)
  erase_start!(e) && return
  if in_empty_pair(b)
    # The bracket that closes goes with the bracket that it came with
    i, col = b.caret
    b.anchor, b.caret = (i, col - 1), (i, col + 1)
    return type!(e, "")
  end
  blk = block(b, b.caret[1])
  erase!(e, backstep(b, blk, length(indentation(e, blk))))
end

"""
What ⌫ does in rich text when the caret is at the start of a line's text. It
returns true when it did it, and false when the caret is somewhere else.

- In a heading, a list item or a quote, it makes the line a paragraph. An item
  of a list inside a list goes out a step first.
- After a part that shows as one thing, like a diagram or a picture, it takes
  away a line with nothing on it. A line with text stays. Either way the caret
  goes onto the part, and ⌫ again takes the part away.
"""
erase_start!(e) = begin
  b = e.buf
  (rich(b) && !selecting(b)) || return false
  i, col = b.caret
  line = kinds(b)[i]
  hidden = unseen(b, i)
  if !isempty(hidden) && first(hidden)[1] < 0 && col <= first(hidden)[2]
    n = line.kind in (Kind.bullet, Kind.ordered, Kind.todo) && line.level >= 2 ? 2 : richspans(b, i)[1]
    edit!(b, (i, 0), (i, n), "")
    b.caret = b.anchor = (i, max(0, col - n))
    touch!(e)
    return true
  end
  at = something(findfirst(r -> r[1] < col <= r[2], hidden), 0)
  (at == 0 ? col : hidden[at][1]) == 0 && i > 1 && !free(b, i - 1, i) || return false
  if isempty(b.lines[i]) && line.kind != Kind.code
    edit!(b, line_end(b, i - 1), (i, 0), "")
    b.caret = b.anchor = settle(b, line_end(b, i - 1), -1, from=(0, 0))
  else
    return (move!(e, line_end(b, i - 1), false, by=-1); true)
  end
  touch!(e)
  true
end

"""
What ⌦ does: it takes away what's after the caret. As rich text, at the end of
a line it joins the next line's text to it, without what starts that line.
"""
erase_next!(e) = begin
  b = e.buf
  picked(b) === nothing || return delete_lines!(e)   # the part that the caret is on as a whole goes
  to = beside(b, b.caret, 1)
  if rich(b) && !selecting(b) && to[1] > b.caret[1]
    j = to[1]
    # The caret goes onto a part that comes next, and ⌦ again takes that part away. It stays before a ``` line.
    free(b, j, b.caret[1]) || return part(b, j) === nothing ? nothing : move!(e, to, false, by=1)
    to = (j, first_stop(b, j))
  end
  erase!(e, to)
end

"Take away the rest of the caret's line. At the end of a line, it joins the next line to it."
erase_line_end!(e) = (b = e.buf; at = line_end(b, b.caret[1]); at == b.caret ? erase_next!(e) : erase!(e, at))

# --- commands for whole lines ---

"The first and last line that the selection touches. A selection that ends at the start of a line doesn't touch that line."
touched(b::Buffer) = begin
  run = picked(b)
  run === nothing || return run   # all the lines of the part that the caret is on as a whole
  lo, hi = minmax(b.caret, b.anchor)
  (lo[1], hi[2] == 0 && hi[1] > lo[1] ? hi[1] - 1 : hi[1])
end

"Put the caret at `caret` and the other end of the selection at `anchor`, each `by` lines further down, after their lines moved"
follow_lines!(e, caret::Pos, anchor::Pos, by::Int) = begin
  b = e.buf
  place((i, col)) = i + by > length(b.lines) ? line_end(b, length(b.lines)) : (max(1, i + by), min(col, length(b.lines[max(1, i + by)])))
  b.caret, b.anchor = place(caret), place(anchor)
  touch!(e)
end

"Take away each line that the selection touches"
delete_lines!(e) = begin
  b = e.buf
  s, t = touched(b)
  col = b.caret[2]
  if t < length(b.lines)
    edit!(b, (s, 0), (t + 1, 0), "")
  elseif s > 1
    edit!(b, line_end(b, s - 1), line_end(b, t), "")
  else
    edit!(b, (1, 0), line_end(b, t), "")
  end
  i = min(s, length(b.lines))
  # The caret comes to the line afresh, so in rich text it isn't left on a line that doesn't show
  b.caret = b.anchor = settle(b, (i, min(col, length(b.lines[i]))), 1, from=(0, 0))
  touch!(e)
end

"Put a copy of the lines that the selection touches under them. The caret goes to the copy."
duplicate_lines!(e) = begin
  b = e.buf
  s, t = touched(b)
  caret, anchor = b.caret, b.anchor
  edit!(b, line_end(b, t), line_end(b, t), "\n" * join(b.lines[s:t], "\n"))
  follow_lines!(e, caret, anchor, t - s + 1)
end

"Move the lines that the selection touches one line up or down"
move_lines!(e, by::Int) = begin
  b = e.buf
  s, t = touched(b)
  caret, anchor = b.caret, b.anchor
  if by < 0
    s > 1 || return
    edit!(b, (s - 1, 0), line_end(b, t), join([b.lines[s:t]; b.lines[s-1]], "\n"))
  else
    t < length(b.lines) || return
    edit!(b, (s, 0), line_end(b, t + 1), join([b.lines[t+1]; b.lines[s:t]], "\n"))
  end
  follow_lines!(e, caret, anchor, by)
end

"Select the whole of the caret's line. With a selection, it grows to the end of its last line. Again, it takes the next line too."
select_lines!(e) = begin
  b = e.buf
  lo, hi = minmax(b.caret, b.anchor)
  b.anchor = (lo[1], 0)
  move!(e, hi[1] < length(b.lines) ? (hi[1] + 1, 0) : line_end(b, hi[1]), true; by=1)
end

"""
Do `f` at each selection: at the main one, then at each of the others with it
in the main one's place. An edit that one of them makes moves the ones after
it, and one ⌘Z takes back what they all did.
"""
each_selection!(f, e) = begin
  b = e.buf
  n = length(others(b))
  (n == 0 || b.many) && return f()
  undos = length(b.undo)
  b.many = true
  try
    for _ in 0:n
      f()
      # The main selection goes to the back of the queue, and the next one takes its place
      push!(b.others, (b.anchor, b.caret))
      b.anchor, b.caret = popfirst!(b.others)
    end
  finally
    b.many = false
  end
  length(b.undo) > undos + 1 && resize!(b.undo, undos + 1)
  # Two selections that came to the same place are one
  kept = Tuple{Pos,Pos}[]
  for s in b.others
    clash(s, (b.anchor, b.caret)) || any(k -> clash(s, k), kept) || push!(kept, s)
  end
  b.others = kept
  keep_others!(b)
  nothing
end

"Do `f` with each of the other selections in the main one's place, then put the main one back. It's for drawing them."
with_others(f, b::Buffer) = begin
  list = copy(others(b))
  isempty(list) && return
  main, many = (b.anchor, b.caret), b.many
  b.many = true
  try
    for s in list
      b.anchor, b.caret = s
      f()
    end
  finally
    b.anchor, b.caret = main
    b.many = many
  end
end

"The columns of each place in `line` that has `text`. With `whole`, only where it's a word by itself."
places(line::AbstractString, text::AbstractString, whole::Bool) = begin
  out = Tuple{Int,Int}[]
  at = firstindex(line)
  while (r = findnext(text, line, at)) !== nothing
    before, after = prevind(line, first(r)), nextind(line, last(r))
    if whole && ((before >= 1 && isword(line[before])) || (after <= ncodeunits(line) && isword(line[after])))
      at = nextind(line, first(r))
      continue
    end
    lo = length(line, 1, before)
    push!(out, (lo, lo + length(text)))
    at = after
  end
  out
end

"""
Select the next place that has the text of the selection as well, and go to
it. After the end of the page it looks from the top. Text that is one word is
found only where it's a word by itself. A live block's own text isn't looked at.
"""
select_next!(e) = begin
  b = e.buf
  lo, hi = selection(b)
  (lo != hi && lo[1] == hi[1]) || return
  text = excerpt(b, lo, hi)
  whole = all(isword, text)
  taken = [(b.anchor, b.caret); others(b)]
  found = [((i, from), (i, to)) for i in eachindex(b.lines) for (from, to) in places(b.lines[i], text, whole)]
  for s in [filter(s -> s[1] >= hi, found); filter(s -> s[1] < lo, found)]
    (any(t -> clash(s, t), taken) || item(e, s[1][1]).content isa Live) && continue
    push!(b.others, (b.anchor, b.caret))
    b.anchor, b.caret = s
    keep_others!(b)
    return
  end
end

"""
Select the word that the caret is in or beside. With a selection, each end of
it goes out to the edge of the word that it's in. With whole words selected
already, the next place that has the same text is selected as well, so what's
typed next goes in at each of them. With no word at the caret, nothing changes.

The selection that was there first stays first in `others`, so Escape can go
back to it.
"""
select_word!(e) = begin
  b = e.buf
  grew = Ref(false)
  each_selection!(e) do
    lo, hi = selection(b)
    from = (lo[1], word_at(b.lines[lo[1]], lo[2])[1])
    to = (hi[1], word_at(b.lines[hi[1]], hi[2])[2])
    (from, to) == (lo, hi) && return
    b.anchor, b.caret = from, to
    grew[] = true
  end
  grew[] || select_next!(e)
  touch!(e)
end

"What starts a comment in each language of code, by the language's name or the end of its file's name"
const COMMENT_MARKS = Dict{String,String}(
  (lang => "#" for lang in ("jl", "julia", "ui", "py", "python", "rb", "ruby", "sh", "bash", "zsh", "fish", "toml", "yaml", "yml", "r", "perl", "pl", "make", "dockerfile"))...,
  (lang => "//" for lang in ("js", "javascript", "jsx", "ts", "typescript", "tsx", "c", "h", "cpp", "hpp", "cc", "java", "swift", "rs", "rust", "go", "kt", "kotlin",
                             "scala", "cs", "php", "dart", "zig"))...,
  (lang => "--" for lang in ("lua", "sql", "hs", "haskell", "elm"))...,
  (lang => ";" for lang in ("lisp", "el", "clj", "clojure", "scm", "scheme"))...,
  (lang => "%" for lang in ("tex", "latex", MATH, "erl", "erlang"))..., "mermaid" => "%%")

"""
Make a comment of each line of code that the selection touches, or make code
of them again if each is a comment already. A line with nothing on it stays
as it is. Outside code, where a comment has no mark, nothing changes.
"""
toggle_comment!(e) = begin
  b = e.buf
  picked(b) === nothing || return
  s, t = touched(b)
  ks = kinds(b)
  lines = [i for i in s:t if ks[i].kind == Kind.code && !isempty(strip(b.lines[i]))]
  isempty(lines) && return
  mark = get(COMMENT_MARKS, lowercase(ks[first(lines)].lang), nothing)
  mark === nothing && return
  indent(i) = length(b.lines[i]) - length(lstrip(b.lines[i]))
  on = all(i -> startswith(lstrip(b.lines[i]), mark), lines)
  at = minimum(indent, lines)   # every mark goes at the indent of the line that's furthest out
  ends = Dict(:caret => b.caret, :anchor => b.anchor)
  new = b.lines[s:t]
  for i in lines
    line = b.lines[i]
    from = on ? indent(i) : at
    # A comment's mark has a space after it, which goes with the mark
    n = !on ? length(mark) + 1 : length(mark) + (startswith(rest(line, from + length(mark)), " ") ? 1 : 0)
    new[i-s+1] = on ? head(line, from) * rest(line, from + n) : head(line, from) * mark * " " * rest(line, from)
    for (name, (l, col)) in ends
      l == i && (ends[name] = (i, on ? (col > from ? max(from, col - n) : col) : (col >= from ? col + n : col)))
    end
  end
  # One change, so one ⌘Z puts every line back
  edit!(b, (s, 0), line_end(b, t), join(new, "\n"))
  b.caret, b.anchor = ends[:caret], ends[:anchor]
  touch!(e)
end

"""
The commands, in the groups and the order that the key bindings page shows
them. Each has its shortcuts in the bundle called Ladder.
"""
const COMMAND_GROUPS = [
  "Files and windows" => [
    Command(:save, "Save the file", :window, "cmd+s", (e, w, _) -> save_page!(e)),
    Command(:open, "Find a file by name", :window, "cmd+o", (e, w, _) -> open_finder!(e)),
    Command(:back, "Go back to the file that showed before", :window, "cmd+opt+left", (e, w, _) -> go_back!(e)),
    Command(:forward, "Go forward again, to the file that you went back from", :window, "cmd+opt+right", (e, w, _) -> go_forward!(e)),
    Command(:print, "Print the page", :window, "cmd+p", (e, w, _) -> print!(e, w)),
    Command(:export, "Export the page as HTML", :window, "cmd+shift+e", (e, w, _) -> export_html!(e, w)),
    Command(:slides, "Show the page as slides, or as a page again", :window, "ctrl+cmd+shift+p", (e, w, _) -> slides!(e)),
    Command(:close, "Close the window", :window, "cmd+w", (e, w, _) -> close(w)),
    Command(:settings, "Show or hide the settings", :window, "cmd+comma", (e, w, _) -> toggle_settings!(e)),
    Command(:sidebar, "Show or hide the sidebar", :window, "cmd+backslash", (e, w, _) -> toggle_panel!(e)),
    Command(:sidebar_keys, "Give the sidebar the keyboard", :window, "cmd+shift+backslash", (e, w, _) -> focus_panel!(e)),
    Command(:plain, "Go down a level, to the symbols at the caret, or up again", :window, "cmd+e", (e, w, _) -> level!(e)),
